pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = pr as f64 - item_size as f64; // residual left after placing item
    let remaining = total_items.saturating_sub(step_index);

    // Dead-space avoidance: small unusable gaps heavily penalized.
    if pr > 0 && pr < 10 {
        score += 60.0;
    } else if pr < 25 {
        score += 25.0 * (1.0 - pr as f64 / 25.0);
    }

    // Reward near-perfect fills.
    if pr == 0 {
        score -= 60.0;
    }

    // Reusability bonus: residuals that are round multiples are easier to fill later.
    let reusable = (pr % 10 == 0) as f64 * 4.0 + (pr % 20 == 0) as f64 * 3.0 + (pr % 25 == 0) as f64 * 2.0 + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Lookahead: dead space worse if next item cannot use the post-residual.
    if next_item_size > 0 {
        if next_item_size > pr && pr > 0 {
            score += 12.0 + (next_item_size - pr) as f64 * 0.15;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 8.0 + 8.0 / (1.0 + slack as f64);
            if slack == 0 { score -= 4.0; }
            // reward near-exact chain with small slack
            if slack >= 1 && slack <= 12 {
                score -= 3.0 * (1.0 - slack as f64 / 12.0);
            }
            // penalize awkward gap just above next item (guaranteed strand)
            if slack > 0 && slack < item_size.min(next_item_size) {
                score += 2.0;
            }
            // large slack that will strand space on long streams
            if slack > 45 {
                score += (slack as f64 - 45.0) * 0.05;
            }
        }
        // two-step exact chain: item + next fills the bin perfectly
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        // near-exact triple chain
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 6 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 6.0);
        }
        // quad chain: item + 3x next fits near-exactly
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        // residual is an exact multiple of next item (perfect future splits)
        if pr > 0 && pr % next_item_size == 0 {
            score -= 1.5;
        }
        // frag barely too small for next item — guaranteed dead space next step
        if frag > 0.0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        // mid-range frag in (next, 2*next) is dead-space prone on long streams
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && remaining > 80 {
            score += (frag - next_item_size as f64) * 0.07;
        }
        // frag exactly equals next item: perfect chain next step
        if frag > 0.0 && frag as u32 == next_item_size {
            score -= 4.5;
        }
        // frag leaves room for next + small remainder
        if frag > 0.0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 {
                score -= 2.2 - rem as f64 * 0.6;
            }
        }
        // dead-space ratio: penalize frag in (next, 2*next) harder when mean residual low
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && mean_residual < 16.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
    }

    // Open-bin pressure: prefer tighter packing when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Bias toward bins with larger residuals (better long-term hosts).
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr as f64 * 0.3 * progress;

    // Large frag that will likely never be filled, scaled by remaining stream.
    if frag > 40.0 && remaining > 60 {
        score += (frag - 40.0) * 0.05;
    }
    // near-closing bins: tiny frag is excellent
    if frag > 0.0 && frag <= 2.0 {
        score -= 3.0;
    }

    // NEW-BIN CANDIDATE logic (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        score += 8.0 + crowding * 6.0;
        if fitting_bins_count == 0 {
            score += 40.0;
        } else {
            score += 4.0;
        }
        // open new bin eagerly when residuals are low (fresh bin amortizes well)
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        // large items early: avoid fragmenting fresh bins late
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        if item_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        // resist new bin when mean residual closely matches next item (open bins close cleanly)
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
        // resist new bin near stream end
        if remaining < 15 && fitting_bins_count > 0 {
            score += 4.0;
        }
        // open new bin when mean residual sits in awkward 12..20 zone on long streams
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 {
            score -= 1.5;
        }
        // no existing bin leaves room for next item after this one
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 4.0;
        }
        // high mean residual on long stream: fresh bin absorbs future items better
        if mean_residual > 28.0 && remaining > 100 {
            score -= 2.0;
        }
        // next item is large: fresh bin hosts it better than a fragmented open bin
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        // prefer new bin for large items when mean residual is mid-range (poor fits ahead)
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 {
            score -= 3.0;
        }
        // resist new bin when many open bins can each still absorb next item
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
        // open new bin when only fitting bins would leave frag just under next item (guaranteed dead space)
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2 && item_size + next_item_size <= bin_capacity && mean_residual > 28.0 && remaining > 60 {
            score -= 1.8;
        }
    } else {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: heavily reward (post_residual == 0)
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize unusable small gaps.
    // Min item size is 1 (interface note), so treat gaps < 10 as near-dead.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64);
    }

    // Penalize moderate gaps that only fit the smallest items weakly
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward leaving a gap that the lookahead item can exactly fill
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Penalize if the leftover gap cannot fit the next item while it could have fit a smaller split
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many bins when fits are plentiful
    if fitting_bins_count > 1 {
        score += 0.5 * open_bins_count as f64;
    }

    // New-bin candidate handling: prefer new bin only when all open fits are terrible
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin
        score = 30.0;
        // Cheaper to open a new bin late in the stream? No: amortize over remaining items
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * progress;
        // If only one fitting bin and it would leave dead space, opening new bin is attractive
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // If mean residual across open bins is small, open bins are nearly full anyway
        score += 0.2 * mean_residual;
    }

    // Mild tie-break: prefer fuller bins (smaller residual before placement)
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = pr as f64 - item_size as f64;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Dead-space avoidance ladder
    if pr == 0 {
        score -= 300.0;
    } else if pr < 10 {
        score += 500.0;
    } else if pr <= 20 {
        score += 150.0;
    } else if pr <= 35 {
        score += 40.0;
    } else {
        let r = pr as f64;
        score += 0.02 * (100.0 - r) * (100.0 - r) / 10.0;
    }

    // Tight-fit reward
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 80.0 * fit_ratio * fit_ratio;

    // Bin-count pressure
    score += 6.0 * open_bins_count as f64;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Lookahead: next item fits in post residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 90.0;
        } else if pr >= next_item_size {
            score -= 70.0;
            let slack = (pr - next_item_size) as f64;
            if slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 45.0 {
                score += (slack - 45.0) * 0.05;
            }
        } else if pr > 0 && pr < next_item_size {
            // dead-space ratio term scaled by stream density and scarcity
            let dead = (next_item_size - pr) as f64;
            let density = remaining as f64 / total_items.max(1) as f64;
            let scarcity = if fitting_bins_count <= 2 { 1.25 } else { 1.0 };
            score += dead * (0.25 + 0.55 * density) * scarcity;
            if dead <= 8.0 {
                score += dead * 0.5;
            } else {
                score += 60.0;
            }
        }
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        // divisibility chain reward
        if pr > 0 && pr >= next_item_size && pr % next_item_size == 0 && pr / next_item_size >= 2 && remaining > 50 {
            score -= 2.0 * ((pr / next_item_size) as f64).min(3.0);
        }
        // multi-fit lookahead with near-divisible residuals
        if next_item_size > 1 && pr > 0 && pr >= next_item_size && pr / next_item_size >= 2 && (pr % next_item_size) <= 2 && remaining > 30 {
            score -= 1.6 * ((pr / next_item_size) as f64).min(4.0);
        }
        // small-gap exact closure
        if pr >= next_item_size && pr - next_item_size <= 1 {
            score -= 3.0;
        }
        // residual just below next item, small gap -> guaranteed dead space late in stream
        if pr > 0 && pr < next_item_size && next_item_size - pr <= 3 && remaining > 80 {
            score += (next_item_size - pr) as f64 * 0.6;
        }
        if pr == next_item_size && fitting_bins_count <= 2 {
            score -= 4.0;
        }
    }

    // Penalize residual just below mean residual (unusable gap)
    if pr > 0 && mean_residual > 2.0 && (pr as f64) < mean_residual && (mean_residual - pr as f64) < 6.0 {
        score += (mean_residual - pr as f64) * 0.35;
    }
    // residual well below mean strands future packing
    if pr > 0 && mean_residual > 3.0 && (pr as f64) < mean_residual * 0.85 && remaining > 60 {
        score += (mean_residual * 0.85 - pr as f64) * 0.22;
    }

    // Keep fat bins fat
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.3 * diff;
    }

    // Frag-based dead-space pressure
    if frag > 0.0 && frag > 12.0 && frag > mean_residual {
        score += (frag - mean_residual) * 0.06;
    }
    if frag > 40.0 && remaining > 60 {
        score += (frag - 40.0) * 0.05;
    }
    // frag just below next item size
    if next_item_size > 0 && frag > 0.0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
        score += (next_item_size - frag as u32) as f64 * 0.9;
    }
    // frag just above next item size
    if next_item_size > 0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
        score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
    }
    // low fill-ratio penalty for small items early/mid stream
    let fill_ratio = item_size as f64 / bin_capacity.max(1) as f64;
    if frag > 0.0 && fill_ratio < 0.42 && remaining > 40 {
        score += (0.42 - fill_ratio) * 16.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let new_bin_bonus = 120.0
            - 0.8 * mean_residual
            - 60.0 * (item_size as f64 / 100.0)
            - 50.0 * progress;
        score += new_bin_bonus;
        if pr > 0 && pr < 20 {
            score += 100.0;
        }
        let fresh_left = bin_capacity.saturating_sub(item_size) as f64;
        if remaining > 60 && fresh_left > 0.0 && fresh_left < mean_residual * 1.25 && open_bins_count > 0 {
            score += (mean_residual * 1.25 - fresh_left) * 0.38;
        }
        if fresh_left <= 6.0 && remaining > 30 {
            score -= 4.0;
        }
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && (next_item_size as f64 - fresh_left) <= 8.0 && remaining > 40 {
            score += (next_item_size as f64 - fresh_left) * 0.5;
        }
        if next_item_size > 2 && fresh_left > 0.0 && fresh_left % next_item_size as f64 == 0.0 && fresh_left / next_item_size as f64 >= 2.0 && remaining > 60 {
            score -= 2.5;
        }
        // fresh-bin multi-fit lookahead: bin will hold item plus >=2 next items
        if next_item_size > 1 && fresh_left >= next_item_size as f64 * 3.0 && remaining > 50 {
            score -= 2.0;
        }
        // large item late in stream: open a bin rather than fragment
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 {
            score -= 3.0;
        }
        if item_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 4.0;
        }
        // large item and open bins cannot fit it well
        if fitting_bins_count > 0 && item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        if next_item_size > 0 && next_item_size as f64 >= fresh_left && mean_residual >= next_item_size as f64 && remaining > 30 && open_bins_count > 0 {
            score += 6.0;
        }
    } else {
        score += 60.0; // bias toward existing bins by default
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        if remaining < 35 && next_item_size > 0 && pr == next_item_size {
            score -= 3.0;
        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        // endgame exact-closure bonus
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 6 && fitting_bins_count > 2 {
            score -= 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
