        }
        // Remainder-after-next near-mean.
        if next_item_size > 1 && pr > next_item_size {
            let rem_after = (pr - next_item_size) as f64;
            if mean_residual > 2.0 && (rem_after - mean_residual).abs() <= 1.5 && remaining > 35 {
                score -= 1.3 * (1.0 - (rem_after - mean_residual).abs() / 1.5) * (0.5 + 0.5 * progress);
            }
        }
        // Dead-space-ratio normalizer.
        if pr > 0 && pr < next_item_size {
            let dead = (next_item_size - pr) as f64;
            let ratio = dead / next_item_size as f64;
            if ratio > 0.6 && fitting_bins_count > 2 && remaining > 20 {
                score += dead * ratio * (0.25 + 0.35 * progress);
            }
        }
        // Slack-shape coupling — 15-24 dead band.
        if pr > next_item_size {
            let slack = (pr - next_item_size) as f64;
            if slack >= 15.0 && slack <= 24.0 && mean_residual < slack - 4.0 && remaining > 40 {
                score += (slack - 14.0) * 0.22 * (0.5 + 0.5 * progress);
            }
        }
        // Scarcity-weighted exact closure.
        if pr == next_item_size && fitting_bins_count > 3 && remaining > 15 {
            score -= 1.5 * (0.5 + 0.5 * progress);
        }
        // MUTATION v174: near-multiple divisibility ladder — residuals one or two units
        // above an exact multiple of next_item still chain well; reward with decay.
        if next_item_size > 1 && pr > 0 && pr >= next_item_size * 2 && remaining > 25 {
            let rem = pr % next_item_size;
            if rem > 0 && rem <= 2 {
                score -= (1.4 - 0.45 * rem as f64) * (0.4 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION v174: reusable-surplus alignment — leftover after one next-item slot
        // that sits just below the mean residual is the most likely to be reused.
        if next_item_size > 1 && pr > 0 && pr >= next_item_size && remaining > 40 {
            let surplus = pr - next_item_size;
            if (surplus as f64) > 0.0 && (surplus as f64) < mean_residual * 0.8 {
                score -= (mean_residual * 0.8 - surplus as f64) * 0.12 * (0.5 + 0.5 * progress);
            }
        }
        // MUTATION v174: post-fit mean-band tightening — leftover after placing next_item
        // just above the mean residual is reusable by the stream's typical item.
        if next_item_size > 1 && pr > 0 && pr >= next_item_size && mean_residual > 3.0 && remaining > 40 {
            let rem_after = (pr - next_item_size) as f64;
            if rem_after > mean_residual && rem_after - mean_residual <= 3.0 {
                score -= (3.0 - (rem_after - mean_residual)) * 0.35 * (0.6 + 0.4 * progress);
