        }
        // MUTATION v174: dead-space suppression below half-mean — post-residuals too
        // small to host a typical item are stranded capacity; penalize smoothly.
        if pr > 0 && mean_residual > 4.0 && (pr as f64) < mean_residual * 0.5 && remaining > 80 {
            score += (mean_residual * 0.5 - pr as f64) * 0.22 * (1.0 - progress * 0.4);
        }
        // MUTATION v174: smooth extension of the dead-space suppression into the
        // mean*0.5..mean*0.75 band so the boundary is ranked continuously.
        if pr > 0 && mean_residual > 4.0 && (pr as f64) >= mean_residual * 0.5 && (pr as f64) < mean_residual * 0.75 && remaining > 60 {
            score += (mean_residual * 0.75 - pr as f64) * 0.09 * (1.0 - progress * 0.3);
        }
        // MUTATION v174: exact-multiple closure — deep multiples of next_item are the
        // tightest compaction signal; reward scaled by depth and remaining horizon.
        if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 && pr / next_item_size >= 2 {
            let k = (pr / next_item_size) as f64;
            score -= (1.0 + 0.4 * (k - 2.0).min(3.0)) * (0.4 + 0.6 * (1.0 - progress));
        }
    }

    // Open-bin pressure.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Bias toward bins with larger residuals.
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Fragments larger than mean residual waste capacity.
    if frag > mean_residual && frag > 12.0 && remaining > 30 {
        score += (frag - mean_residual) * 0.06;
    }
    if frag > 40.0 && remaining > 60 {
        score += (frag - 40.0) * 0.05;
    }
    // Frag trapped between one and two next-items.
    if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
        score += (frag - next_item_size as f64) * 0.10;
        if mean_residual < 16.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
    }
    // Small-item fragmentation guard.
    let fill_ratio = item_size as f64 / bin_capacity.max(1) as f64;
    if frag > 0.0 && fill_ratio < 0.42 && remaining > 40 {
        score += (0.42 - fill_ratio) * 16.0 * (1.0 - progress * 0.5);
    }
    if frag > 0.0 && frag > mean_residual * 1.6 && remaining > 30 {
        score += (frag - mean_residual * 1.6) * 0.04;
    }

    // Late-stream tightening.
    score += pr as f64 * (0.1 + 0.22 * progress);

    // Residual close to mean residual is a good host.
    if pr > 0 && mean_residual > 1.0 {
        let dev = ((pr as f64 - mean_residual) / mean_residual).abs();
        if dev < 0.3 {
