        if next_item_size > 0 && pr > 0 && pr == next_item_size && remaining >= 50 {
            score -= 1.2;
        }
        if next_item_size > 0 && pr > next_item_size {
            let slack = (pr - next_item_size) as f64;
            if slack >= 15.0 && slack <= 24.0 && mean_residual < slack - 4.0 && fitting_bins_count > 2 && remaining > 40 {
                score += (slack - 14.0) * 0.15;
            }
        }
        // MUTATION v174: non-fresh divisibility closure — deep exact multiples in open
        // bins are reliable chained fits; reward deeper multiples with mild decay.
        if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 && pr / next_item_size >= 2 && remaining > 30 {
            let k = (pr / next_item_size) as f64;
            score -= 0.9 + 0.25 * (k - 2.0).min(4.0);
        }
        // MUTATION v174: post-fit residual banding in non-fresh bins.
        if next_item_size > 1 && pr > 0 && pr > next_item_size {
            let rem_after = pr - next_item_size;
            if rem_after > 0 && mean_residual > 2.0 && (rem_after as f64 - mean_residual).abs() <= mean_residual * 0.2 && remaining > 30 {
                score -= 1.2 * (1.0 - (rem_after as f64 - mean_residual).abs() / (mean_residual * 0.2 + 1.0)) * (0.4 + 0.6 * progress);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item (1..100 stream)
    // are unusable unless exactly 0. Penalize gaps in [1, 9] heavily (strict dead-space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + 4.0 * (10 - post_residual) as f64;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward snug fits: small post_residual relative to capacity.
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 && post_residual - next_item_size > 0 {
            // next item would create dead space here; mild penalty
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (which would strand this residual).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight bins.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 50.0);
    score += 3.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is below the mean (already tightly packed bins).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // New-bin candidate: neutral-ish baseline; make it attractive only when
    // no open bin offers a good fit (large dead-space creation elsewhere).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.5 - 15.0 * pressure;
        if fitting_bins_count == 1 {
            score += 60.0; // don't open new bin when a lone fitting bin exists
        }
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
