        if fresh_left > 0.0 && mean_residual > 3.0 && (fresh_left - mean_residual).abs() <= 2.0 && remaining > 80 {
            score -= 1.0;
        }
    } else {
        score += 60.0;
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        // Endgame: strong bonus for exact-closure residuals.
        if remaining < 35 && next_item_size > 0 && pr == next_item_size {
            score -= 3.0;
        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 6 && fitting_bins_count > 2 {
            score -= 1.5;
        }
        // Endgame two-item closure.
        if remaining < 30 && next_item_size > 0 && pr > 0 && pr >= next_item_size && pr - next_item_size <= 3 {
            score -= 2.0 * (1.0 - remaining as f64 / 30.0) * (1.0 - (pr - next_item_size) as f64 / 3.0);
        }
        // Scarcity-aware waste — near-miss residuals with few alternatives are costly late.
        if next_item_size > 0 && pr > 0 && pr < next_item_size && fitting_bins_count <= 2 && remaining > 40 {
            score += (next_item_size - pr) as f64 * 0.20;
        }
        // Mid-stream near-closure window.
        if remaining >= 35 && remaining < 120 && next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 5 {
            score -= 1.0;
        }
        // Endgame mean-residual alignment.
        if remaining < 20 && pr > 0 && mean_residual > 1.0 && ((pr as f64) - mean_residual).abs() < 3.0 {
            score -= 1.5;
        }
        // Many alternatives and residual leaves more dead space than mean: deprioritize.
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
        // Widened endgame exact-closure — late stream, prefer fits that zero the residual.
        if remaining < 50 && next_item_size > 0 && pr > 0 && pr == next_item_size {
            score -= 2.5 * (1.0 - remaining as f64 / 50.0);
        }
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        // Two-step exact closure — residual fits item then next item exactly.
        if next_item_size > 0 && pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        // Mid-stream residual that holds next item twice exactly — strong host.
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.0;
        }
        // Scarcity-aware triple closure — residual that holds next item three times
        // exactly with few alternatives is a near-perfect multi-fit host.
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 3 && fitting_bins_count <= 3 && remaining > 40 {
            score -= 1.8;
        }
        // Mid-stream zero-slack exact closure — any post-residual that exactly
        // equals next item size is a guaranteed clean fit; reward scaled by horizon.
        if next_item_size > 0 && pr > 0 && pr == next_item_size && remaining >= 50 {
            score -= 1.2;
        }
        // Near-closure escalation — residual within 2 of next item size mid-stream
        // with many alternatives is a near-perfect host; reward scaled by alternatives.
        if remaining >= 50 && next_item_size > 0 && pr > next_item_size && pr - next_item_size <= 2 && fitting_bins_count > 3 {
            score -= 1.0 + 0.5 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible future item are pure waste; penalize them hard.
    if post_residual > 0 && post_residual < 20 {
        score += 60.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Perfect or near-perfect fills get a strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Reward bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 30.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward;
    // if post-residual is large but next item won't fit, mild penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual - next_item_size < 20 {
            score -= 20.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 10.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // New-bin candidate: only attractive when existing bins would leave
    // large dead space or few bins fit the item.
    if bin_residual == bin_capacity {
        score = 100.0 - (item_size as f64);
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let is_new_bin = bin_residual == bin_capacity;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Tightness reward: squared residual gap relative to capacity.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += 12.0 * tight * tight;

    // Lookahead: reward if next item can use the post-residual well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover_after_next = post_residual - next_item_size;
        score -= 8.0 * (1.0 - (leftover_after_next as f64) / (bin_capacity as f64));
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 3.0; // dead space risk for lookahead
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Penalize high fragmentation relative to mean residual.
    if (post_residual as f64) > mean_residual + 20.0 {
        score += 6.0;
    } else if (post_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // New-bin candidate scoring: baseline penalty that shrinks as stream progresses
    // and when open bins are scarce relative to load.
    if is_new_bin {
        let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 30.0 - 15.0 * progress - 4.0 * open_pressure;
        // Large items justify fresh bins; small items should fill existing ones.
        score += 0.15 * (item_size as f64 - 50.0);
    }

    // Late in stream: consolidate, prefer existing bins even more.
    if progress > 0.8 && !is_new_bin {
        score -= 5.0;
    }

    // Mild penalty for leaving residuals that are hard-to-fill windows (1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
