                score -= 1.4 * (1.0 - rem_after as f64 / (mean_residual + 3.0)) * (1.0 - progress * 0.4);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer bins that become nearly full (small post_residual),
    // but only if post_residual is not a useless sliver of dead space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead: reward if the next item fits exactly into post_residual (perfect 2-step match).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect chaining: this bin absorbs both items completely.
            score -= 60.0;
        } else if next_item_size < post_residual {
            // Next item fits, but leaves further residual: mild reward scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leftover dead space, worse when
            // post_residual is small enough that nothing else will ever fit it.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 40.0; // unusable sliver
            } else {
                score += 10.0 * (1.0 - dead / bin_capacity as f64);
            }
        }
    }

    // Tightness reward: strongly prefer bins that end up with minimal residual,
    // non-linearly, so near-exact fits dominate loose fits.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that can fit the item,
    // avoid opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // Mean-residual coupling: prefer bins whose residual deviates below the mean
    // (closing out small-residual bins first keeps the fleet of open bins tidy).
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 12.0 * dev;
    }

    // New-bin candidate: an empty bin is attractive early (build capacity for
    // future large items) but expensive late in the stream. Tune threshold.
    if bin_residual == bin_capacity {
        let openness = 1.0 - progress;
        // Prefer a new bin when the current fit would leave a large, awkward residual
        // or when many open bins are already congested.
        let awkward = (post_residual as f64 / bin_capacity as f64).clamp(0.0, 1.0);
        score += 45.0 * openness - 25.0 * awkward - 8.0 * open_bins_count as f64 * (1.0 - openness);
        // If next item is large and won't fit anywhere else soon, a fresh bin is safer.
        if next_item_size > 60 && next_item_size > post_residual {
            score -= 15.0;
        }
    }

    score
}

