    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // next item fits, penalize leftover after chaining
            score -= 100.0 - (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit here: penalize tight-but-wasted residuals
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Prefer bins with low residual relative to mean (tight packing)
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Penalize leaving large dead space that small items can't use
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // tiny unusable slivers
    }

    // Early in stream, be slightly more willing to open new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score = score.min(0.0) + 60.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

