pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: quadratic polynomial in normalized post residual
    let mut score = 3.0 * x * x - 2.0 * x * x * x + 0.35 * x;

    // Smooth non-linear coupling with stream progress: late in stream,
    // prefer tighter fits more aggressively (bend the polynomial).
    let bend = (0.5 - (progress - 0.5) * (progress - 0.5)) * 2.0; // peak 1 at mid, 0 at ends
    score += (x * x) * (1.0 - bend) * 1.2;
    score -= (1.0 - x) * (1.0 - x) * bend * 0.8;

    // Dead-space penalty: post residual too small to fit any plausible item
    let dead = ((30.0 - pr).max(0.0) / 30.0).powi(2);
    score += dead * 6.0;

    // Lookahead: reward if next item fits in post residual (smooth logistic)
    if next_item_size > 0 {
        let fits_next = pr >= next_item_size as f64;
        let margin = (pr - next_item_size as f64) / cap;
        let bonus = 1.0 / (1.0 + (-margin * 8.0).exp());
        if fits_next {
            score -= 2.0 * bonus;
        } else {
            score += 1.0 * (1.0 - bonus);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 4.0;
    }

    // Prefer bins below mean residual (consolidate space)
    score += (pr as f64 - mean_residual) / cap * 0.5;

    // Mild preference for existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 1.5 + 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residuals in the "unusable" band
