        if post_residual == next_item_size {
            score -= 1000.0;
        } else {
            // Proximity reward: closer post_residual to next_item_size is better
            score -= 200.0 / (1.0 + diff / 10.0);
        }
        // Penalize leaving residual that is too small for next item (dead space)
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    // Compare post_residual relative to mean residual: favor bins that will end near mean
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += mean_gap * 0.3;

    // Penalize tight fits that create small unusable slivers (unless next item matches)
    if post_residual > 0 && post_residual < 10 && post_residual != next_item_size {
        score += 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins can fit
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 500.0;
        } else {
            score -= 100.0;
        }
    }

    // Slight preference to consolidate into fewer bins as stream progresses
    score += open_bins_count as f64 * 0.5;

    // Mild tie-breaker: prefer fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Core archetype: 2-step lookahead matching.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual >= next_item_size {
            // Reward exact match: post_residual == next_item_size is perfect.
            let diff = (pr - nxt).abs();
            score -= 2.5 * nxt * (1.0 - diff / (nxt + 1.0));
            // Extra reward if the item after next could also fit (rough guess).
            if post_residual >= next_item_size * 2 {
                score -= 3.0;
            }
        } else {
            // Dead space: post_residual too small for the next item.
            score += (nxt - pr) * 1.5;
        }
    } else {
        // Last item: simply prefer tightest fit.
        score -= 10.0;
    }

    // Compare post_residual against mean residual: leaving more than average
    // slack is wasteful; leaving much less than average is a good squeeze.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.4;
    } else {
        score += (pr - mean_residual) * 0.3;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 8.0 * tightness;
    }

    // Penalize near-empty fills of a fresh bin only mildly; new-bin candidate
    // gets a baseline so it wins only when fits are poor.
    if bin_residual == bin_capacity {
        score += 6.0;
    }

    // Late-stream consolidation: as the stream progresses, prefer filling
    // existing bins tighter and avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0 * (1.0 - pr / cap);

    // Mild penalty when many bins are open (encourage consolidation).
    score += open_bins_count as f64 * 0.15;

    // Small reward for large items placed into tight residuals.
    score -= (item_size as f64 / cap) * 2.0 * (1.0 - pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
