    // Penalize leaving residuals that no plausible item can use well
    if post_residual > 0 && post_residual < 15 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post_residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // next item could have used this bin's full residual; mild penalty
            score += 4.0;
        }
        // If next item is large, keep bins with large residuals open
        if next_item_size > 50 && post_residual > next_item_size {
            score -= 6.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 20.0 + 2.0 * open_bins_count as f64;
        // But if existing bins leave very bad fits, allow opening
        let waste = (bin_residual as f64 - item_size as f64) - post_residual as f64;
        if post_residual < 10 {
            score -= 10.0;
        }
        let _ = waste;
        // Late in the stream, avoid proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // If many bins already fit the item, opening a new one is wasteful
        if fitting_bins_count > 2 {
            score += 10.0;
        }
    }

    // Prefer bins whose residual deviates from the mean in a useful way
    // (use a bin with more space than average when item is large)
    let mean_diff = bin_residual as f64 - mean_residual;
    if item_size > 50 {
        score -= 0.15 * mean_diff;
    } else {
        score += 0.05 * mean_diff;
    }

    // Mild preference for consolidating into fewer bins early
    score += 0.05 * open_bins_count as f64;

    // Small time-varying exploration term (deterministic, derived from step)
    let phase = ((step_index as f64 * 0.37).sin()) * 1.5;
    score += phase;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: prefer tight fits (low post residual), with a smooth non-linear
    // penalty on dead space that strengthens quadratically as it grows.
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth polynomial coupling with stream progress:
    // early in the stream, keep bins flexible (penalize very small residuals);
    // late in the stream, exploit tight fits aggressively.
    let flex = (1.0 - progress) * (1.0 - progress); // smooth early-stream weight
    let exploit = progress * progress;             // smooth late-stream weight

    // Penalize leaving a residual too small to be useful, more so early on.
    let small_waste = (norm_pr * (1.0 - norm_pr)) * 4.0; // peaks mid-range, smooth
    score += flex * 30.0 * (1.0 - small_waste) * norm_pr;

    // Late stream: reward tight packing via smooth cubic coupling.
    score -= exploit * 25.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Interaction with mean residual: prefer bins whose post residual aligns
    // with the fleet average (smooth quadratic deviation term).
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Last-chance bin: smooth reward for using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - exploit * 0.5);
    }

    // Lookahead: smooth reward if the next item fits the post residual well.
    if next_item_size > 0 && next_item_size as f64 <= pr {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 18.0 * (1.0 - slack) * (1.0 - exploit);
    } else if next_item_size > 0 {
        score += 10.0 * flex;
    }

    // Mild pressure to prefer already-open bins over opening new ones,
    // scaled smoothly by how many bins are open.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize dead space into capacity fractions.
    let post_frac = post_residual as f64 / cap;
    let class = (post_frac * 8.0).floor() as i32; // 8 harmonic classes of residual space

    // Reward placements that land the bin into a "nearly full" class.
    match class {
        0 => score -= 40.0,                 // residual < 12.5% : excellent closure
        1 => score -= 25.0,
        2 => score -= 15.0,
        3 => score -= 8.0,
        4 => score -= 3.0,
        5 => score += 2.0,                  // mid-range dead space: mildly bad
        6 => score += 6.0,
        _ => score += 10.0,                 // residual > 87.5% : item barely dented the bin
    }

    // Integer-division thresholds: exact-fit detection via divisibility structure.
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else if post_residual < 10 {
        score -= 20.0; // dead space too small for any item (min size 1..100, small is fine)
    }

    // Lookahead coupling: does post_residual match the next item's class?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item could reuse this bin's remainder: reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - (slack / cap) * 10.0;
            // Harmonic match: post_residual and next_item in same modulo-10 band
            if (post_residual % 10) >= (next_item_size % 10) && post_residual / 10 == (next_item_size + post_residual) / 10 {
                score -= 6.0;
            }
        } else {
            score += 4.0; // remainder unusable by next item
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.5 + 45.0 * (1.0 - pressure) + 10.0 * progress;
        if fitting_bins_count == 0 {
            score = 0.0; // must open a new bin
        }
    }

    // Tie-break toward tighter existing bins via mean residual comparison.
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Mild penalty for spreading across many open bins.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (below the minimum size 1... but practically
    // below a "useful" threshold) are pure waste. Penalize heavily.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = (item_size as f64) / (bin_residual as f64);
        score -= 15.0 * tightness;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, opening a new one is less costly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.4 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 35.0;
        } else if (gap as f64) < dead_threshold {
            score -= 10.0;
        }
    }
    // If next item does NOT fit in this bin's post residual, mild penalty
    // unless post residual is large enough to be reusable anyway.
    else if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate handling: only attractive when current bin would
    // leave a bad gap or open bins are numerous.
    if bin_residual == bin_capacity {
        let bad_fit = (post_residual as f64) < dead_threshold && post_residual > 0;
        let base = 60.0 + 3.0 * open_bins_count as f64;
        score = if bad_fit { 10.0 } else { base - 15.0 * ((post_residual as f64) / bin_capacity as f64) };
    }

    // Mild normalization against mean residual state.
    score -= 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill is always best.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Exact 2-step lookahead match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 500.0;
    }
    // Next item fits with a little slack left for later items.
    else if next_item_size > 0 && post_residual > next_item_size {
        score -= 50.0 + (post_residual - next_item_size) as f64;
    }
    // Next item cannot fit here: penalize proportionally to wasted lookahead potential.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0 + (next_item_size - post_residual) as f64;
    }

    // Small dead space (hard to reuse) is bad; large residual is more reusable.
    if post_residual < 10 {
        score += 40.0;
    }

    // Compare against mean residual: prefer bins tighter than average (good fits).
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New empty bin candidate: only attractive when nothing sensible exists.
    if bin_residual == bin_capacity {
        // Base penalty so open bins usually win...
        score += 90.0;
        // ...but if the item barely fits anywhere or would leave tiny dead space
        // in every open bin, a fresh bin becomes competitive.
        if fitting_bins_count <= 1 {
            score -= 150.0;
        }
        if post_residual < 10 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let prn = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): mild penalty on large residuals, mild reward on tight fits.
    // Late (progress ~ 1): much stronger reward for tight packing (small post_residual).
    let tightness = 1.0 - prn;
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep in [0,1]
    let coupling = progress_poly * (tightness * tightness * tightness) * 60.0;
    score -= coupling;

    // Quadratic dead-space penalty: residuals too small for the smallest plausible item
    // are wasted; penalize super-linearly as post_residual shrinks below a soft zone.
    let dead = (cap * 0.2 - pr).max(0.0) / cap;
    score += dead * dead * 40.0;

    // Penalize large leftover residuals quadratically (waste grows non-linearly).
    score += prn * prn * 20.0 * (1.0 - progress_poly);

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress_poly;
    }

    // Lookahead: reward if the next item fits into the resulting residual.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = (pr - n) / cap;
            score -= 25.0 * (1.0 - slack * slack) * (0.5 + 0.5 * progress_poly);
        } else {
            score += 10.0 * (n - pr) / cap;
        }
    }

    // Prefer bins with residuals close to the mean (balanced packing), smooth coupling.
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 15.0;

    // Mild penalty for accumulating too many open bins late in the stream.
    score += open_bins_count as f64 * progress_poly * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr / cap * 4.0).floor(); // 0: <=25%, 1: <=50%, 2: <=75%, 3: >75%

    // Reward tight fits (low class), especially exact/near-exact.
    match class as u32 {
        0 => score -= 30.0 + (cap - pr) * 0.5, // excellent fit
        1 => score -= 12.0,
        2 => score -= 3.0,
        _ => score += 8.0, // mostly empty bin wasted on this item
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // Harmonic compatibility: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let nxt_class = (next_item_size as f64 / cap * 4.0).floor();
            // Reward when next item's harmonic class complements the leftover.
            if nxt_class <= class {
                score -= 15.0;
            }
            // Penalize leaving a residual that is awkwardly larger than next item
            let gap = post_residual - next_item_size;
            if gap > 0 && gap <= 10 {
                score -= 10.0;
            } else if gap > 30 {
                score += 5.0;
            }
        } else {
            // next item cannot use this residual; residual becomes dead-ish if small
            if post_residual < 10 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless the item is large (good seeding) or few bins open.
    if bin_residual == bin_capacity {
        let seed_bonus = (item_size as f64 / cap) * 40.0; // large items seed bins well
        score += 20.0 - seed_bonus;
        if open_bins_count == 0 {
            score -= 50.0;
        }
        // Late in stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Prefer bins with residuals harmonically distant from mean (diversity of classes)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= dev * 0.05;

    // Modulo-class tiebreaker on post_residual: residuals divisible into common item
    // sizes (multiples of 5/10) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual that is too small for the minimum item size (1..100 unknown,
    // but assume small items rare) is dead space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let min_plausible_item = 10.0;

    // Dead-space penalty: post_residual in (0, threshold) is nearly unusable.
    if post_residual > 0 && (post_residual as f64) < min_plausible_item {
        score += 60.0 * (1.0 - 0.5 * progress);
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Reward tight fits relative to bin capacity.
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 30.0 * tightness * tightness;
    }

    // Lookahead: if next item fits exactly in post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 80.0;
        } else if (slack as f64) < min_plausible_item {
            score -= 40.0;
        } else {
            score -= 15.0;
        }
    } else if next_item_size > 0 && (post_residual as f64) < (next_item_size as f64) {
        // Post residual cannot hold next item: mild penalty scaled by gap.
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open bins pressure: with many open bins, discourage opening new ones
    // (new-bin candidate has bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 25.0 + 12.0 * open_bins_count as f64 * (0.5 + progress);
        // But if no existing bin fits well, opening is fine: relax penalty
        // when post_residual of alternatives would be dead space — handled
        // implicitly since this is the empty-bin call.
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score -= 30.0; // huge item: fresh bin is natural
        }
    }

    // Prefer bins whose residual is below mean residual (more filled bins).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    // Mild normalization by open bins to spread load when bins are scarce.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
