pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver under min item size
    }

    // Lookahead coupling: reward bins whose post-residual exactly fits next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += 3.0; // next item can't follow here
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is expensive.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += 60.0;
        // Early in the stream, opening bins is cheap (build diversity).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 25.0 * (1.0 - progress);
        // If fit is poor elsewhere, a new bin is attractive.
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        if fit_ratio > 0.7 {
            score -= 30.0;
        }
        // Many open bins with small residuals -> consolidate, don't open.
        if open_bins_count > 3 && mean_residual < 25.0 {
            score += 20.0;
        }
    }

    // Mild preference for fuller bins relative to fleet average.
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Late-stream consolidation pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Normalized post-residual and its smooth polynomial expansion
    let x = post / cap; // in [0, 1]
    let x2 = x * x;
    let x3 = x2 * x;

    // Base: penalize leftover space, but super-linearly (dead space is costly)
    let mut score = post * (1.0 + 0.9 * x2 + 0.6 * x3);

    // Smooth coupling with stream progress: early on, waste is cheaper;
    // later, tight packing matters more (amplify post-residual penalty).
    let progress_gain = 1.0 + 1.4 * progress * progress;
    score *= progress_gain;

    // Smooth interaction: small post-residual relative to next item's need
    // is a bonus (next item may fill the gap); large gap vs next item is waste.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap_ratio = (post - nxt) / cap;
        let smooth = gap_ratio * (1.0 - gap_ratio.abs().min(1.0));
        score -= 8.0 * smooth.max(0.0) * (1.0 - progress);
        score += 6.0 * (gap_ratio.abs()) * x2;
    }

    // Last-chance bin: smooth exponential reward scaled by scarcity
    if fitting_bins_count <= 1 {
        score -= 25.0 * (1.0 - x).powi(2) * (0.5 + 0.5 * progress);
    }

    // Mild penalty for opening a new bin when alternatives exist,
    // smoothly decaying as stream progresses (early opening is fine).
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin && fitting_bins_count > 0 {
        let alt_pressure = 1.0 / (1.0 + fitting_bins_count as f64);
        score += 18.0 * alt_pressure * (1.0 - 0.6 * progress);
    }

    // Coupling with mean residual: bins deviating far below the mean
    // (fragmented) get a smooth quadratic penalty.
    let dev = mean_residual - post;
    score += 0.15 * dev * dev / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" is the leftover space
    // Class bins by which standard item sizes could still fit.
    let usable = if post_residual == 0 {
        1.0 // perfect fit, best possible
    } else if post_residual >= 50 {
        0.2 // huge leftover, still very usable
    } else if post_residual >= 30 {
        0.5
    } else if post_residual >= 20 {
        0.8
    } else if post_residual >= 10 {
        1.5
    } else {
        3.0 // dead space (<10): nearly unusable
    };
    score += (post_residual as f64) * usable;

    // Modulo arithmetic on post_residual: leftover congruent to common
    // item sizes (multiples of 10) is more reusable.
    let mod10 = post_residual % 10;
    score += mod10 as f64 * 0.7;

    // Reward tight fits (small post_residual) more aggressively.
    if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 10.0;
    }

    // Lookahead coupling: if the next item fits the post-residual,
    // strongly favor this bin (chaining placements).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + 0.15 * next_item_size as f64;
        // Extra bonus if next item exactly fills it later.
        if next_item_size == post_residual {
            score -= 12.0;
        }
    } else if next_item_size > 0 {
        // penalize leaving space that the next item can't use
        score += 3.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 6.0;
        if post_residual <= 10 {
            score -= 8.0;
        }
    }

    // New-bin candidate handling: opening a new bin should only win when
    // no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = cap * 1.1;
        // if the item is large relative to capacity, fresh bin is fine
        score -= (item_size as f64 / cap) * 20.0;
        // if many open bins exist with large mean residual, prefer reusing them
        score += (open_bins_count as f64) * (mean_residual / cap).max(0.0) * 10.0;
        // late in the stream, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Mild penalty for spreading across many bins when mean residual is high.
    if open_bins_count > 3 && mean_residual > 40.0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly useless.
    // Penalize gaps that are too small to be useful for typical items.
    if post_residual > 0 {
        // Dead-space zone: gaps below the smallest plausible item (1..20)
        // are hard to fill; penalize superlinearly as gap shrinks.
        let gap = post_residual as f64;
        if gap < 20.0 {
            score += (20.0 - gap) * (20.0 - gap) * 0.15; // quadratic dead-space penalty
        }
