        if post_residual == 0 {
            score -= 60.0;
        } else if post_residual <= 5 {
            score -= 30.0;
        } else if post_residual <= 10 {
            score -= 12.0;
        }
    }

    // Reward filling a bin nearly full (tight fit relative to capacity).
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Open-bins pressure: with many open bins, prefer existing bins over spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.8 + 0.6 * progress);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mean residual coupling: prefer bins whose residual is below mean
    // (i.e., closer to being filled) — close out nearly-done bins first.
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // chained perfect fit
        } else if next_item_size < post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here: leftover becomes dead space; penalize
            score += 6.0;
        }
