    // New-bin candidate handling: empty bin has full residual.
    // Opening a new bin is only attractive if this bin would leave a large
    // unusable gap AND open bins are few.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; grows with open bin count.
        score = 40.0 + open_bins_count as f64 * 1.5;
        // If the current item is large, a fresh bin is reasonable.
        if item_size >= 60 {
            score -= 10.0;
        }
        // Late in the stream, avoid spawning bins unnecessarily.
        score += progress * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
