    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 30.0;
        } else if post_residual as u32 >= next_item_size {
            score -= (post_residual as u32 - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += (next_item_size as f64 - post_residual as f64).min(20.0) * 0.5;
        }
    } else {
        // Last item in stream: prefer closing bins out.
        score -= 20.0;
    }

    // Global fragmentation pressure: if mean residual is high, bins are loose;
    // encourage filling existing bins rather than spreading.
    let frag = mean_residual / bin_capacity as f64;
    score += frag * 15.0;

    // Time horizon: early in the stream, opening new bins is cheaper long-term;
    // late in the stream, consolidate into existing bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bias = (1.0 - t) * 25.0;
    if bin_residual == bin_capacity {
        // candidate new bin: penalize proportionally to how much we want consolidation
        score += new_bin_bias - 10.0;
