        score -= (bin_residual as f64 / bin_capacity as f64) * 10.0;
    }

    // Many open bins: push toward consolidation to avoid bin proliferation.
    score += open_bins_count as f64 * 0.4;

    // Non-linear coupling: reward placements that leave residuals matching
    // common small item sizes (multiples of 10) when stream is long.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
