    let norm_pr = pr / cap;

    // Base: minimize post residual, with non-linear polynomial shaping.
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth stream-progress coupling: later in stream, tighter packing preferred.
    let prog_term = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score += prog_term * pr * 0.3;

    // Penalize dead space that cannot fit the next item (smooth interaction).
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (ns - pr).max(0.0) / cap;
        score += gap * gap * 40.0 * (1.0 - progress);
