    }

    // Mild penalty when many bins are open relative to stream position.
    score += (open_bins_count as f64) * 0.5 * (1.0 - progress);

    // Deviation from mean residual: prefer bins diverging from mean (non-linear).
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 10.0 - dev * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
