    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }
    // Many fitting bins: mild penalty so we keep flexibility (best-fit still wins).
    if fitting_bins_count > 3 {
        score += 1.0;
    }

    // ---- New-bin candidate handling (bin_residual == bin_capacity) ----
    if bin_residual == bin_capacity {
