        + (pr % 20 == 0) as f64 * 3.0
        + (pr % 25 == 0) as f64 * 2.0
        + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Two-item lookahead: reward bins where item + next fits exactly
    if next_item_size > 0 && item_size + next_item_size == bin_residual {
        score -= 6.0;
    }
    // Triple-chain lookahead
