    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 6.0; }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 40.0 { score += (slack - 40.0) * 0.06; }
            // Dead zone: gap 13..45 after next item is awkward.
            if slack > 12.0 && slack < 45.0 {
                score += (slack - 12.0) * 0.05;
            }
            // Sharpen mid dead zone scaled by mean residual.
            if slack >= 15 && slack <= 25 && mean_residual > 22.0 {
