            if pr % next_item_size.max(1) == 0 && pr <= 30 + next_item_size { score -= 2.0; }
            // Perfect future splits: residual a small multiple of next item.
            if pr % next_item_size == 0 && pr <= next_item_size * 3 { score -= 1.5; }
            // Slack that itself fits next item again (chainable).
            if slack >= next_item_size as f64 { score -= 2.5; }
