        else if pr <= 6 { -16.0 }
        else if pr <= 12 { -8.0 }
        else if pr <= 20 { -2.0 }
        else if pr <= 32 { 2.0 }
        else if pr <= 50 { 6.0 }
        else if pr <= 70 { 10.0 }
        else { 14.0 };
    score += class;

    // Reusability bonus: keep residuals that remain useful multiples.
    let reusable = (pr % 10 == 0) as f64 * 4.0
        + (pr % 20 == 0) as f64 * 3.0
        + (pr % 25 == 0) as f64 * 2.0
        + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Fragment penalty: tiny leftover slivers are dead space.
    if pr > 0 && pr < item_size.min(20) {
        score += 6.0;
    }

    // Lookahead coupling with next item.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 {
                score -= 6.0;
            }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 40.0 {
                score += (slack - 40.0) * 0.06;
            }
        } else {
            let gap = (next_item_size - pr) as f64;
            let soft = if pr <= 10 { 0.5 } else { 1.0 };
            score += (5.0 + gap * 0.09) * soft;
        }
    }

    // Two-item chain: item then next item closes the bin exactly.
    if next_item_size > 0 && item_size + next_item_size == bin_residual {
        score -= 6.0;
    }

    // Triple chain: item + next*2 nearly closes the bin.
    if next_item_size > 0 {
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
    }

    // Dead-zone penalty: gaps in 15..45 after next item are awkward.
    if next_item_size > 0 && pr >= next_item_size {
        let gap = pr - next_item_size;
        if gap > 25 && gap < 45 {
            score += (gap as f64 - 25.0) * 0.08;
        } else if gap >= 15 && gap <= 25 && mean_residual > 22.0 {
            score += (gap as f64 - 15.0) * 0.10;
        }
    }

    // Reward residuals that are exact multiples of next item (future splits).
    if next_item_size > 0 && pr > 0 && pr % next_item_size == 0 {
        score -= 1.5;
    }

    // Penalize residual just below next item (guaranteed dead space).
    if next_item_size > 0 && pr > 0 && pr < next_item_size && pr < item_size.min(next_item_size) {
        score += 1.5 + (next_item_size - pr) as f64 * 0.05;
    }

    // Dead-space ratio: frag that neither fits next item nor closes soon.
    let remaining = total_items.saturating_sub(step_index);
    if next_item_size > 0 && pr > 0 {
        let frag = pr as f64;
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
        }
        if frag as u32 >= next_item_size {
