    score -= 8.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize dead space: post_residual too small for any future item (items >= 1,
    // but very small residuals relative to typical item sizes are wasteful).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 3.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here regardless; slight penalty if we leave big gap.
            score += 0.02 * post_residual as f64;
        }
    } else {
        // Last item: prefer filling existing bins maximally.
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no
    // open bin has a decent fit, or the stream is young with few open bins.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins more as stream progresses and bins accumulate.
        let mut new_bin_penalty = 10.0 + 15.0 * progress + 0.4 * open_bins_count as f64;
        // But if mean residual across open bins is small (poor fits everywhere),
        // opening a fresh bin becomes more acceptable.
        if mean_residual < item_size as f64 * 0.5 {
            new_bin_penalty -= 8.0;
        }
        // A new bin guarantees perfect fit for large items late in the stream.
        if item_size >= 70 {
            new_bin_penalty -= 4.0;
        }
        score += new_bin_penalty.max(2.0);
    }

    // Mild preference for bins with below-average residual (keep spread even),
    // but reward packing into fuller-than-average bins to consolidate waste.
    if !is_new_bin {
        let diff = bin_residual as f64 - mean_residual;
        score += 0.05 * diff;
    }

    // Slight global pressure: with many open bins, favor filling existing ones.
    score += 0.05 * open_bins_count as f64;

    score
}

