pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 25 {
        score += 25.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead space is worse if the next item cannot use it.
    if next_item_size > post_residual && post_residual > 0 {
        score += 15.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    }

    // Open-bin pressure: prefer tighter packing when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Slight bias toward bins with larger residuals (better long-term hosts).
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = pr.saturating_sub(item_size) as f64;
    let remaining = total_items.saturating_sub(step_index);

    // Fine-grained residual class ladder with tighter mid-range boundaries.
    let class: f64 = if pr == 0 { -50.0 }
        else if pr <= 5 { -18.0 }
        else if pr <= 10 { -10.0 }
        else if pr <= 15 { -5.0 }
        else if pr <= 22 { -1.0 }
        else if pr <= 32 { 3.0 }
        else if pr <= 45 { 7.0 }
        else if pr <= 65 { 11.0 }
