    let pr = post_residual;
    let frag = (pr as f64 - item_size as f64).max(0.0);
    let remaining = total_items.saturating_sub(step_index);

    // Residual class scoring: reward exact closes and tiny residuals, penalize awkward gaps.
    let class: f64 = if pr == 0 { -50.0 }
        else if pr <= 8 { -14.0 }
        else if pr <= 15 { -6.0 }
        else if pr <= 25 { -1.0 }
        else if pr <= 40 { 4.0 }
        else if pr <= 60 { 8.0 }
        else { 12.0 };
    score += class;

    // Reward residuals that are clean multiples (likely future perfect splits).
    let reusable = (pr % 10 == 0) as f64 * 4.0 + (pr % 20 == 0) as f64 * 3.0
        + (pr % 25 == 0) as f64 * 2.0 + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Next-item fit coupling: exact chain is best, small slack good, no-fit bad.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 5.0; }
            if slack >= 1.0 && slack <= 12.0 { score -= 3.0 * (1.0 - slack / 12.0); }
            if slack > 45.0 { score += (slack - 45.0) * 0.05; }
        } else {
