pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong lookahead: reward bins whose post-residual exactly (or nearly) matches next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_gap = (post_residual as u32 - next_item_size) as f64;
        score -= 30.0 * (1.0 - match_gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit in residual: penalize proportionally to wasted space.
        score += 0.35 * (next_item_size as f64 - post_residual as f64);
    }

    // Relative-to-mean-residual coupling: prefer bins tighter than average.
    score -= 0.6 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize tiny dead space that nothing (min size ~10) can ever use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Early in the stream, be more willing to open new bins (spread items);
    // late in the stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when many bins are open or early in stream.
        score -= 8.0 * (1.0 - progress);
        score += 2.0 * open_bins_count as f64 * 0.1;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = if pr >= item_size { (pr - item_size) as f64 } else { 0.0 };

    // Refined residual class ladder
    let class: f64 = if pr == 0 { -48.0 }
        else if pr <= 8 { -15.0 }
        else if pr <= 15 { -6.5 }
        else if pr <= 25 { -1.0 }
        else if pr <= 40 { 4.0 }
        else if pr <= 60 { 8.0 }
        else { 12.0 };
    score += class;

    // Reusability bonus
    let reusable = (pr % 10 == 0) as f64 * 4.0
        + (pr % 20 == 0) as f64 * 3.0
        + (pr % 25 == 0) as f64 * 2.0
        + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Tiny residual trap: residual below min(item, 20) is nearly dead
    if pr > 0 && pr < item_size.min(20) {
        score += 6.0;
    }

    // Lookahead coupling with next item
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 {
                score -= 6.0;
            }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 40.0 {
                score += (slack - 40.0) * 0.06;
            }
            if slack >= next_item_size as f64 {
                score -= 2.5;
            }
        } else {
            let gap = (next_item_size - pr) as f64;
            let soft = if pr <= 10 { 0.5 } else { 1.0 };
            score += (5.0 + gap * 0.09) * soft;
            // residual just barely too small for next item => guaranteed dead space
            if gap <= 4.0 && pr > 0 {
                score += gap * 0.9;
            }
        }
        // exact two-item chain: item + next fills residual exactly
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        // near-exact two-step chain
        if frag > 0.0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 {
                score -= 2.2 - rem as f64 * 0.6;
            }
        }
        // triple chain lookahead
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        // residual is exact multiple of next item => future perfect splits
        if pr > 0 && pr % next_item_size == 0 {
            score -= 1.5;
        }
        // awkward mid-range frag that neither fits next nor closes soon
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
        }
    }

    // Scarcity pressure
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 6.0;
    } else if fitting_bins_count >= 5 {
        score += 2.0;
    }

    // Global residual context
    if mean_residual > 25.0 && pr > mean_residual as u32 {
        score += 3.0;
    } else if mean_residual < 12.0 && pr > 0 && pr <= item_size * 2 {
        score -= 2.0;
    }

    // Dead-space ratio: penalize frag far above mean residual when many bins open
    if frag > 0.0 && frag > mean_residual * 1.5 && open_bins_count > 3 {
        score += (frag - mean_residual * 1.5) * 0.06;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let remaining = total_items.saturating_sub(step_index);
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        score += 8.0
            + (fitting_bins_count == 0) as i32 as f64 * 40.0
            + (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0) * 4.0;
        if item_size > bin_capacity / 2 && mean_residual < item_size as f64 {
            score -= 10.0;
        }
        // large item early in long stream: prefer fresh bin
        if item_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 {
            score -= 3.0;
        }
        // resist new bin when stream nearly over and open bins suffice
        if remaining < 8 && fitting_bins_count > 0 {
            score += 5.0;
        }
        // item + next won't co-fit anywhere anyway: new bin is fine
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 4.0;
        }
        // dead space accumulating: open fresh bin more eagerly
        if mean_residual > 30.0 && remaining > 100 {
            score -= 2.0;
        }
        // resist new bin when mean residual closely matches next item
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
        if fitting_bins_count > 0 {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is best.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small to ever be useful
    // (below the minimum plausible item size), unless it's exactly 0.
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 - (post_residual as f64 / 10.0) } else { 0.0 };
        score += 8.0 * dead;
    }

    // Lookahead: penalize if the next item would no longer fit after placement.
    if next_item_size > 0 {
        if post_residual < next_item_size && bin_residual >= next_item_size {
            score += 6.0; // placement destroys a useful slot for the lookahead item
        }
        if post_residual >= next_item_size {
            score -= 3.0; // keeps a compatible slot open
        }
        // Bonus if post_residual pairs exactly-ish with the next item
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= 2.0 * (1.0 - gap / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when open bins have poor fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 15.0;
        // Scale penalty with number of open bins (more open bins => keep consolidating).
        score += (open_bins_count as f64).sqrt() * 2.0;
        // If the best alternative is bad (large post_residual elsewhere), new bin becomes
        // relatively more attractive: subtract proportional to mean residual waste.
        let mean_waste = mean_residual / bin_capacity as f64;
        score -= 20.0 * mean_waste;
        // If item is large relative to residual, opening fresh is safer.
        if item_size > bin_residual / 2 {
            score -= 5.0;
        }
    } else {
        // Existing-bin bonus grows as stream progresses (consolidation bias).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 4.0 * progress;
    }

    // Mild preference for bins with below-average residual (pack tighter bins first).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
