pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let waste = (post / cap).clamp(0.0, 1.0);

    let mut score = post;

    // Non-linear polynomial waste penalty, growing with stream progress
    score += 45.0 * waste * waste * (0.5 + t);
    score += 20.0 * waste * waste * waste * (1.0 + 2.0 * t);

    // Reward tight fits (low post_residual) smoothly
    let tight = (1.0 - waste).clamp(0.0, 1.0);
    score -= 25.0 * tight * tight;

    // Perfect-fill lookahead reward: post_residual exactly matches next item
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        if gap < 1.0 {
            score -= 18.0;
        } else if post >= next_item_size as f64 {
            score -= 6.0 * (1.0 - gap / cap);
        } else {
            score += 4.0 * (gap / cap) * (0.5 + t);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 22.0 + 10.0 * t;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 { (fitting_bins_count as f64).min(6.0) } else { 0.0 };
        score += 30.0 + 12.0 * pressure * (0.6 + 0.8 * t);
        // Allow a new bin when it would leave room for the next item
        if next_item_size > 0 && post >= next_item_size as f64 {
            score -= 10.0;
        }
    }

    // Mild coupling to mean residual: prefer bins near the fleet average (keeps residuals balanced)
    score += 0.06 * (mean_residual - post).abs();

    // Slight preference for consolidating into existing bins as stream progresses
    score += (open_bins_count as f64) * 0.15 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
