}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity fraction classes.
    // Residuals that are "harmonically useful" (divisible into many common item
    // sizes) are rewarded; awkward residuals are penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity remaining after placement.
    let frac = pr / cap;

    // Class boundaries at capacity fractions: 0, 1/4, 1/3, 1/2, 2/3, 3/4, 1.
    // Residuals near a "harmonic" fraction are reusable by many item sizes.
    let harmonic_fracs = [0.0f64, 0.25, 1.0 / 3.0, 0.5, 2.0 / 3.0, 0.75, 1.0];
    let mut best_dist = f64::MAX;
    let mut best_idx = 0usize;
    for (i, hf) in harmonic_fracs.iter().enumerate() {
        let d = (frac - hf).abs();
        if d < best_dist {
            best_dist = d;
            best_idx = i;
        }
    }
    // Reward proximity to harmonic class (bigger classes = more reusable).
    let class_weight = [0.6f64, 0.4, 0.5, 0.8, 0.5, 0.4, 0.3][best_idx];
    score -= class_weight * (1.0 - best_dist / 0.5).max(0.0) * 12.0;

    // Integer-division threshold: post_residual bucketed by /10 decade.
    let decade = post_residual / 10;
    // Low decades (small dead space) are good; mid decades (15..35 dead space,
    // too small for most items) are bad.
    if decade >= 2 && decade <= 4 {
        score += 18.0; // dead zone: residual 20..49 fits few items
    } else if decade >= 8 {
        score -= 6.0; // large residual, very reusable
    }

    // Modulo logic: residuals divisible by common item sizes (10, 20, 25, 50)
    // are harmonically attractive.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 5.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 3.0;
    }
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Perfect fit is best possible.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chained harmonic match).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let chain_post = post_residual - next_item_size;
            // Reward chains that stay in harmonic classes.
            if chain_post % 10 == 0 {
                score -= 10.0;
            }
            score -= (chain_post as f64).min(20.0) * 0.3;
        } else {
            // Next item won't fit here: penalize slightly more in the dead zone.
            if decade >= 2 && decade <= 4 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; only prefer
    // it late in the stream when mean residual across open bins is large
    // (fragmentation) or when the current fit creates a dead-zone residual.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let frag = mean_residual / cap;
        // Base preference for consolidating into open bins.
        score += 25.0;
        // Late in stream with fragmented open bins, a fresh bin is fine.
        score -= progress * frag * 30.0;
        // If the item would leave a dead-zone residual anywhere else, new bin
        // becomes relatively attractive.
        let pr_dec = post_residual / 10;
        if pr_dec >= 2 && pr_dec <= 4 {
            score -= 20.0;
        }
        // Early stream: strongly prefer filling existing bins.
        score += (1.0 - progress) * 20.0;
    }

    // Mild pressure to prefer bins with lower residual (tighter fits) when
    // many bins are open, to close out bins.
    score += (bin_residual as f64 - pr) * 0.05;
    score += open_bins_count as f64 * 0.05 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);

    // Residual class ladder: reward small/closed residuals, penalize large ones.
    let class: f64 = if pr == 0 { -48.0 }
        else if pr <= 8 { -15.0 }
        else if pr <= 15 { -6.5 }
        else if pr <= 25 { -1.0 }
        else if pr <= 40 { 4.0 }
        else if pr <= 60 { 8.0 }
        else { 12.0 };
    score += class;

    // Reward residuals divisible by common sizes (likely reusable).
    let reusable = (pr % 10 == 0) as f64 * 4.0 + (pr % 20 == 0) as f64 * 3.0 + (pr % 25 == 0) as f64 * 2.0 + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    let fits = pr >= item_size;
    if fits {
        let frag = (pr - item_size) as f64;

        // Penalize small awkward fragments.
        if frag > 0.0 && frag < item_size.min(15) as f64 {
            score += 4.0 + (15.0 - frag) * 0.15;
        }

        // Next-item lookahead: exact fit is great, small slack is good, big slack wasteful.
        if next_item_size > 0 {
            if next_item_size <= pr {
                let slack = (pr - next_item_size) as f64;
                score -= 7.0 + 10.0 / (1.0 + slack);
                if slack == 0.0 { score -= 5.0; }
                if slack >= 1.0 && slack <= 12.0 { score -= 3.0 * (1.0 - slack / 12.0); }
                if slack > 45.0 { score += (slack - 45.0) * 0.05; }
            } else {
                score += 5.0 + (next_item_size - pr) as f64 * 0.09;
            }
        }

        // Two-item exact chain lookahead.
        if next_item_size > 0 && item_size + next_item_size == pr { score -= 6.0; }

        // Triple-chain lookahead.
        if next_item_size > 0 {
            let triple = item_size + next_item_size * 2;
            if pr >= triple && pr - triple <= 10 {
                score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
            }
        }

        // Frag just barely too small for next item = guaranteed dead space.
        if next_item_size > 0 && frag > 0.0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }

        // Frag within 3 of next item = near-exact chain next step.
        if next_item_size > 0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }

        // Frag is exact multiple of next item (perfect future splits).
        if next_item_size > 0 && frag > 0.0 && frag as u32 % next_item_size == 0 && frag <= next_item_size as f64 * 3.0 {
            score -= 1.5;
        }

        // Dead-space ratio: penalize mid-range frag scaled by remaining stream.
        if next_item_size > 0 && frag > next_item_size as f64 && frag < 30.0 && remaining > 60 {
            score += (frag - next_item_size as f64) * 0.05;
        }

        // Frag barely above next item with big remainder: penalize when long stream.
        if next_item_size > 0 && frag > next_item_size as f64 && remaining > 120 {
            score += (frag - next_item_size as f64) * 0.03;
        }

        // Penalize frag that exceeds mean residual significantly (waste accumulation).
        let mr = mean_residual.max(1.0);
        if frag > 0.0 && frag > mr * 1.5 && open_bins_count > 3 {
            score += (frag - mr * 1.5) * 0.06;
        }

        if frag == 0.0 { score -= 4.0; }
    } else {
        // Item does not fit: strong penalty.
        score += 60.0;
    }

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Bias toward bins with larger residuals (better long-term hosts).
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Open-bin pressure.
    score += open_bins_count as f64 * 0.3;

    // NEW-BIN CANDIDATE LOGIC
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
