        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2 && item_size + next_item_size <= bin_capacity && mean_residual > 28.0 && remaining > 60 { score -= 1.8; }
        // Gen 26: resist new bin when many open bins can absorb next item.
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps are almost unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // dead space penalty
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    }

    // Penalize post-residuals that cannot fit the lookahead item (wasted space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage fragmenting further,
    // encourage consolidating into fewer bins.
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate: only attractive when existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let poor_fit = mean_residual < item_size as f64 * 0.5;
        if poor_fit && open_bins_count > 0 {
            score -= 20.0;
        } else {
            score += 15.0; // prefer filling existing bins by default
        }
    }

    // Tightness bonus: reward filling a bin densely.
    let fill_ratio = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
