pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative waste of the residual consumed.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Strongly reward near-perfect fills (post_residual small relative to capacity).
    if post_residual as f64 <= 0.05 * bin_capacity as f64 {
        score -= 25.0;
    } else if post_residual as f64 <= 0.15 * bin_capacity as f64 {
        score -= 8.0;
    }

    // Lookahead: if the next item can fit into the post-residual, this is a great chain.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + 4.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Dead space that the next item cannot use; penalize proportionally,
            // but only mildly late in the stream when closing bins matters less.
            let progress = step_index as f64 / total_items as f64;
            let waste = (post_residual as f64 - next_item_size as f64).max(0.0);
            score += 0.08 * waste * (1.0 - 0.5 * progress);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
        if post_residual as f64 <= 0.2 * bin_capacity as f64 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: an empty bin is attractive only when open bins
    // have poor fits. Penalize opening a new bin when decent fits exist.
    if bin_residual == bin_capacity {
        let mean_fit_quality = if mean_residual > 0.0 {
            (mean_residual - item_size as f64).max(0.0) / bin_capacity as f64
        } else {
            0.0
        };
        // If open bins have plenty of room, discourage a new bin.
        score += 20.0 * mean_fit_quality;
        // Early in stream, filling existing bins is cheap; late, allow new bins more freely.
        let progress = step_index as f64 / total_items as f64;
        score += 10.0 * (1.0 - progress);
        // Many open bins with room: new bin is wasteful.
        score += 0.5 * open_bins_count as f64 * mean_fit_quality;
        // If next item is small and mean residual is large, new bin even worse.
        if next_item_size > 0 && mean_residual > 2.0 * next_item_size as f64 {
            score += 8.0;
        }
    }

    // Global pressure: when few bins fit the item, be more tolerant of imperfect fits
    // in any fitting bin to avoid overflow cascades.
    if fitting_bins_count <= 2 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Slight preference to consolidate into bins with low mean residual state
    // (balance load toward already-low bins).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.05 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);

    // Fine-grained residual class ladder
    let class: f64 = if pr == 0 { -48.0 }
        else if pr <= 6 { -16.0 }
        else if pr <= 12 { -8.0 }
        else if pr <= 20 { -2.0 }
        else if pr <= 32 { 2.0 }
        else if pr <= 50 { 6.0 }
        else if pr <= 70 { 10.0 }
        else { 14.0 };
    score += class;

    // Reusability bonus: residuals that remain useful multiples
    let reusable = (pr % 10 == 0) as f64 * 4.0
        + (pr % 20 == 0) as f64 * 3.0
        + (pr % 25 == 0) as f64 * 2.0
        + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    let fits = pr >= item_size;
    let frag = if fits { (pr - item_size) as f64 } else { -1.0 };

    // Exact-fill chain rewards (combined lookahead)
    if next_item_size > 0 {
        if item_size + next_item_size == pr {
            score -= 6.0; // perfect two-step chain
        }
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
    }

    // Lookahead coupling with next item
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 6.0; }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 40.0 { score += (slack - 40.0) * 0.06; }
            // near-exact chain next step
            if fits && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
                score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
            }
            // frag splits into next item plus tiny remainder
            if fits && frag as u32 > next_item_size {
                let rem = frag as u32 - next_item_size;
                if rem <= 2 { score -= 2.2 - rem as f64 * 0.6; }
            }
            // dead zone: awkward gap in 15..45 after next item
            let gap = pr - next_item_size;
            if gap >= 15 && gap <= 25 && mean_residual > 22.0 {
                score += (gap as f64 - 15.0) * 0.10;
            }
            if gap > 25 && gap < 45 {
                score += (gap as f64 - 25.0) * 0.08;
            }
        } else {
            // Next item won't fit here: penalize proportionally, soften when nearly full
            let gap = (next_item_size - pr) as f64;
            let soft = if pr <= 10 { 0.5 } else { 1.0 };
            score += (5.0 + gap * 0.09) * soft;
            // residual just below next item = guaranteed dead space next step
            if pr > 0 && next_item_size - pr <= 4 {
                score += (next_item_size - pr) as f64 * 0.9;
            }
        }
        // post-residual exact multiple of next item (perfect future splits)
        if pr > 0 && pr % next_item_size == 0 { score -= 1.5; }
        // post-residual hosts next item twice with near-zero slack
        if pr >= next_item_size * 2 {
            let d2 = pr - next_item_size * 2;
            if d2 <= 3 { score -= 2.0 - d2 as f64 * 0.5; }
        }
    }

    // Fragment/dead-space ratio handling
    if fits {
        if frag == 0.0 { score -= 4.0; }
        if frag > 0.0 && frag < item_size.min(15) as f64 {
            score += 4.0 + (15.0 - frag) * 0.15;
        }
        let mr = mean_residual.max(1.0);
        if frag > mr * 1.5 && open_bins_count > 3 {
            score += (frag - mr * 1.5) * 0.06;
        }
        // mid-range frag that neither fits next nor closes soon
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
        }
        // awkward 20..35 dead zone on long streams
        if frag >= 20.0 && frag <= 35.0 && remaining > 80 && next_item_size > 0 && next_item_size < frag as u32 {
            score += (frag - 20.0) * 0.045;
        }
        // frag divisible by next item within a small multiple
        if frag > 0.0 && next_item_size > 0 && frag as u32 % next_item_size == 0 && frag <= next_item_size as f64 * 3.0 {
            score -= 1.5;
        }
    }

    // Scarcity pressure
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 6.0;
    } else if fitting_bins_count >= 5 {
        score += 2.0;
    }
    if next_item_size > 0 && pr >= next_item_size && (pr - next_item_size) <= 2 && fitting_bins_count <= 2 {
        score -= 3.0;
    }

    // Global residual context
    if mean_residual > 25.0 && pr > mean_residual as u32 {
        score += 3.0;
    } else if mean_residual < 12.0 && pr > 0 && pr <= item_size * 2 {
        score -= 2.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        score += 8.0 + crowding * 6.0
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 18.0 { score += 10.0; }
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        // resist new bin when a fitting bin can chain item + next exactly
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size <= bin_capacity && mean_residual > 20.0 && remaining > 50 {
            score += 1.2;
        }
        // open new bin when all fitting bins would leave frag just under next item
        if next_item_size > 0 && fitting_bins_count > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score -= 3.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: penalize leftover space, with non-linear curvature
    let mut score = post_norm * (1.0 + 0.8 * post_norm * post_norm);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, larger leftovers are tolerable; later, they become costly.
    let progress_coupling = post_norm * progress * (2.0 - progress);
    score += 3.0 * progress_coupling * post_norm;

    // Reward tight fits (small post_residual) with a smooth bonus
    let tightness = (1.0 - post_norm).max(0.0);
    score -= 2.0 * tightness * tightness * tightness;

    // Lookahead: if next item fits exactly into post_residual, reward strongly (smooth gate)
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        let fit_quality = (-gap / cap).exp();
        score -= 1.5 * fit_quality;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 4.0;
    }

    // Penalize bins whose residual deviates from mean (keep bin pool homogeneous)
    let dev = (post - mean_residual) / cap;
    score += 0.5 * dev * dev;

    // Mild penalty for many open bins: prefer consolidation
    score += 0.02 * open_bins_count as f64;

    // New-bin candidate: make empty bins less attractive unless post_residual is large
    if bin_residual == bin_capacity {
        score += 1.0 + 2.0 * (1.0 - post_norm);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.85;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues near capacity fractions
    // (0, 25, 50, 75) are "usable" for future items; others are dead space.
    let quarters = [0u32, 25, 50, 75];
    let mut min_dist: u32 = u32::MAX;
    for &q in quarters.iter() {
        let d = if post_residual >= q { post_residual - q } else { q - post_residual };
        if d < min_dist { min_dist = d; }
    }
    // Reward closeness to a harmonic class (0 = perfect fit is best).
    score += min_dist as f64 * 0.35;

    // Perfect or near-perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 2 {
        score -= 30.0;
    }

    // Penalize dead space that no plausible item (1..100) could ever
    // consume usefully: residual < 10 is unfillable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the
    // post-residual (harmonic pairing), strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            // Reward if the pair leaves another harmonic-class residue.
            let mut d2: u32 = u32::MAX;
            for &q in quarters.iter() {
                let d = if leftover >= q { leftover - q } else { q - leftover };
                if d < d2 { d2 = d; }
            }
            score -= 15.0 - d2 as f64 * 0.2;
        } else {
            // Next item won't fit here: slight penalty scaled by mismatch.
            score += ((next_item_size - post_residual) as f64) * 0.1;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening
    // a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin early in the stream
    // or when open bins still have room; reward it when the stream is
    // nearly done and open bins are fragmented.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * progress;
        score += open_bins_count as f64 * 1.5;
        if mean_residual > 30.0 {
            score += 8.0;
        }
    }

    // Prefer bins whose residual is below the mean (tighter packing).
    score += (bin_residual as f64 - mean_residual).max(0.0) * 0.15;

    // Integer-division threshold: post_residual divisible by common
    // item sizes (10..=25 step 5) is likely reusable.
    if post_residual > 0 {
        for k in [10u32, 15, 20, 25, 50].iter() {
            if post_residual % k == 0 {
                score -= 5.0;
                break;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
