    // Refined residual class ladder
    let class: f64 = if pr == 0 { -48.0 }
        else if pr <= 6 { -16.0 }
        else if pr <= 12 { -8.0 }
        else if pr <= 20 { -2.0 }
        else if pr <= 32 { 2.0 }
        else if pr <= 50 { 6.0 }
        else if pr <= 70 { 10.0 }
        else { 14.0 };
    score += class;

    // Reusability bonus: keep residuals that remain useful multiples.
    let reusable = (pr % 10 == 0) as f64 * 4.0
        + (pr % 20 == 0) as f64 * 3.0
        + (pr % 25 == 0) as f64 * 2.0
        + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Dead-space guard: tiny residual just below next item is guaranteed waste.
    if pr > 0 && next_item_size > 0 && pr < next_item_size && pr < item_size.min(next_item_size) {
        score += 1.5 + (next_item_size - pr) as f64 * 0.05;
    }

    // Lookahead coupling with next item.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 {
                score -= 6.0;
            }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 40.0 {
                score += (slack - 40.0) * 0.06;
            }
            // near-exact two-step chain: rem barely fits another item
