    } else if fitting_bins_count >= 5 {
        score += 2.0;
    }

    // Global residual context.
    if mean_residual > 25.0 && pr > mean_residual as u32 {
        score += 3.0;
    } else if mean_residual < 12.0 && pr > 0 && pr <= item_size * 2 {
        score -= 2.0;
    }

    // New-bin candidate logic with adaptive pressure.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        // open new bin more eagerly when stream is long and dead space is accumulating
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        // resist new bin when an existing bin closes exactly on next item
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 { score += 2.0; }
        // prefer new bin for large items when mean residual is mid-range
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        // open new bin when no existing bin leaves room for next item after this one
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        // resist new bin near stream end
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        // resist new bin when many open bins can absorb next item (avoid sprawl)
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        // prefer new bin for very large items early in stream
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        // open new bin when mean residual is high and fitting bins are loose
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
        // resist new bin when stream ends soon
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        // open new bin when the only fitting bins would leave frag just under next item
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && item_size + next_item_size <= bin_capacity
            && mean_residual > 28.0 && remaining > 60 { score -= 1.8; }
        // resist new bin when mean residual closely matches next item
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size
            && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        // resist new bin when next item is bigger and open bins are promising
        if next_item_size > 0 && fitting_bins_count > 0 && next_item_size > item_size
            && remaining > 50 && mean_residual > 20.0 { score -= 1.2; }
    }

    score
