            let usable = next_item_size.min(frag as u32) as f64;
            let dead_ratio = 1.0 - usable / frag;
            if dead_ratio < 0.5 { score += (frag - 12.0) * 0.06 * (1.0 - dead_ratio); }
        }
        // gen 31: long streams punish any frag exceeding next item
        if next_item_size > 0 && frag > next_item_size as f64 && remaining > 120 {
            score += (frag - next_item_size as f64) * 0.03;
        }
    }

    // Scarcity pressure
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 6.0;
    } else if fitting_bins_count >= 5 {
        score += 2.0;
    }

    // Global residual context
    if mean_residual > 25.0 && pr > mean_residual as u32 {
        score += 3.0;
    } else if mean_residual < 12.0 && pr > 0 && pr <= item_size * 2 {
        score -= 2.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        // resist new bin when a fitting bin can chain item + next exactly
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size <= bin_capacity && mean_residual > 20.0 { score += 1.5; }
        // resist new bin when mean residual closely matches next item
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        // open new bin when all fitting bins would leave frag just under next item (dead space)
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && next_item_size > item_size && next_item_size - item_size <= 4 && remaining > 50 {
            score -= 2.0;
        }
        // resist new bin late in stream when open bins suffice
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        // open new bin for large items when mean residual is high and spare bins crowd
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
        // gen 31: resist new bin when many open bins can each absorb next item (avoid sprawl)
        if next_item_size > 0 && fitting_bins_count >= 2 && mean_residual >= next_item_size as f64 {
            score += 2.0;
        }
        // gen 31: open new bin when only fitting bins would leave near-dead residuals for next item
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && item_size + next_item_size <= bin_capacity && mean_residual > 28.0 && remaining > 60 {
            score -= 1.8;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.08;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item (1) are fine,
    // but residuals in the awkward low band (1..=10) relative to typical item sizes are dead space.
    // Treat post_residual in (0, 10] as nearly wasted: push it toward full waste penalty.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual <= 10 {
        // unusable micro-gap: penalize as if the whole residual were dead
        score += 40.0 - pr * 2.0;
    }

    // Reward very tight fits (small post_residual) extra.
    if post_residual <= 3 {
        score -= 15.0;
    }

    // Dead-space coupling with mean residual: if this bin's post-fit residual is far below
    // the mean residual, we are consolidating space well.
    score -= 0.3 * (mean_residual - pr).max(0.0);

    // Open bins pressure: prefer filling existing bins when many are open.
    score -= 0.6 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has full residual. Only prefer it when
    // the item is large or no open bin fits well.
    if bin_residual == bin_capacity {
        // base handicap so open bins are usually preferred
        score += 12.0;
        // large items or no alternatives make a fresh bin attractive
        if item_size >= 60 {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // early in the stream, opening bins is cheap
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (1.0 - progress);
    }

    // Lookahead: if next item would fit exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    }
    // If next item fits comfortably, mild reward; if it cannot fit, mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 3.0;
        } else if post_residual > 0 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.17;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact 2-step matches: post_residual == next_item_size
    // means the next item fills this bin perfectly (waste -> 0 over two steps).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item fits but leaves a further gap: reward proportional closeness.
        let gap = (post_residual - next_item_size) as f64;
        score -= 30.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize dead space.
        score += 25.0;
    }

    // Perfect single-item fill: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Compare against mean residual: placing into a bin with residual near the
    // mean keeps the bin fleet balanced; strongly-larger residuals are wasteful.
    let residual_f = post_residual as f64;
    score += 0.5 * (residual_f - mean_residual).abs();

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize tiny unusable leftovers (dead space < 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Early in the stream, be more willing to open new bins (spread items);
    // late in the stream, consolidate tightly.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, penalized late.
        score = score * 0.8 + (1.0 - progress) * 30.0 - progress * 10.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin when none exist
        }
    } else {
        // Existing bins become more attractive as the stream progresses.
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = if pr >= item_size { (pr - item_size) as f64 } else { 0.0 };
    let remaining = total_items.saturating_sub(step_index);

    // Residual class ladder (tight-closure tuned)
    let class: f64 = if pr == 0 { -48.0 }
        else if pr <= 6 { -17.0 }
        else if pr <= 12 { -8.0 }
        else if pr <= 20 { -2.5 }
        else if pr <= 32 { 2.0 }
        else if pr <= 50 { 6.5 }
        else if pr <= 70 { 10.0 }
        else { 14.0 };
    score += class;

    // Reusability bonus
    let reusable = (pr % 10 == 0) as f64 * 4.0
        + (pr % 20 == 0) as f64 * 3.0
        + (pr % 25 == 0) as f64 * 2.0
        + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Dead residual just below item size — guaranteed waste
    if pr > 0 && pr < item_size.min(20) {
        score += 6.0;
    }

    // Lookahead coupling with next item.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 6.0; }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 40.0 { score += (slack - 40.0) * 0.06; }
            if slack <= 3.0 { score -= 1.0 * (1.0 - slack / 3.0); }
            // residual can host next item repeatedly — perfect future splits
            if slack >= next_item_size as f64 { score -= 2.5; }
        } else {
            let gap = (next_item_size - pr) as f64;
            let soft = if pr <= 10 { 0.5 } else { 1.0 };
            score += (5.0 + gap * 0.09) * soft;
            if gap <= 4.0 && pr > 0 { score += (4.0 - gap) * 0.9; }
        }
        // two-item exact chain
        if item_size.saturating_add(next_item_size) == pr { score -= 6.0; }
        // triple chain near-exact
        let triple = item_size.saturating_add(next_item_size * 2);
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        // quad chain — item + next x3 near-exact
        let quad = item_size.saturating_add(next_item_size * 3);
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        // residual hosts next item twice with near-zero slack
        if pr >= next_item_size * 2 {
            let d2 = pr - next_item_size * 2;
            if d2 <= 3 { score -= 2.0 - d2 as f64 * 0.5; }
        }
        // mid dead-zone shaping
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 { score += (gap as f64 - 25.0) * 0.08; }
            if gap >= 15 && gap <= 25 && mean_residual > 22.0 {
                score += (gap as f64 - 15.0) * 0.10;
            }
        }
        // residual exact multiple of next item
        if pr > 0 && pr % next_item_size == 0 { score -= 1.5; }
        // residual just below next item — dead space next step
        if pr > 0 && pr < next_item_size && pr < item_size.min(next_item_size) {
            score += 1.5 + (next_item_size - pr) as f64 * 0.05;
        }
    }

    // Frag-based dead-space shaping
    if frag > 0.0 {
        if frag < item_size.min(15) as f64 { score += 4.0 + (15.0 - frag) * 0.15; }
        if next_item_size > 0 && (frag as u32) == next_item_size { score -= 4.5; }
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
        }
        if frag >= 20.0 && frag <= 35.0 && remaining > 80 && next_item_size > 0 && next_item_size < frag as u32 {
            score += (frag - 20.0) * 0.045;
        }
        let mr = mean_residual.max(1.0);
        if frag > mr * 1.5 && open_bins_count > 3 { score += (frag - mr * 1.5) * 0.06; }
        if next_item_size > 0 && frag as u32 > next_item_size * 2 && pr > 30 {
            score += (frag - next_item_size as f64) * 0.045;
        }
        // reward frag that splits into next item + tiny remainder (two-step close)
        if next_item_size > 0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 { score -= 2.2 - rem as f64 * 0.6; }
        }
        // penalize frag just barely too small for next item
        if next_item_size > 0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        // reward frag within 3 of next item (near-exact chain)
        if next_item_size > 0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        // frag divisible by next item within small range — future perfect splits
        if next_item_size > 0 && frag as u32 % next_item_size == 0 && frag <= next_item_size as f64 * 3.0 {
            score -= 1.5;
        }
        // long-stream waste pressure on awkward frag
        if next_item_size > 0 && frag > next_item_size as f64 && frag < 30.0 && remaining > 60 {
            score += (frag - next_item_size as f64) * 0.05;
        }
        // gen 31 (from best): dead-space ratio — penalize frag that exceeds usable next-item fit by a large ratio
        if next_item_size > 0 {
            let usable = next_item_size.min(frag as u32) as f64;
            let dead_ratio = usable / frag.max(1.0);
            if dead_ratio < 0.5 && frag > 12.0 && remaining > 30 {
                score += (frag - 12.0) * 0.06 * (1.0 - dead_ratio);
            }
        }
    } else if pr >= item_size {
        // perfect close — item exactly fills the bin
        score -= 4.0;
    }

    // Scarcity pressure
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 6.0;
    } else if fitting_bins_count >= 5 {
        score += 2.0;
    }

    // Global residual context
    if mean_residual > 25.0 && pr > mean_residual as u32 {
        score += 3.0;
    } else if mean_residual < 12.0 && pr > 0 && pr <= item_size * 2 {
        score -= 2.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        // resist new bin when a fitting bin can chain item + next exactly
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size <= bin_capacity && mean_residual > 20.0 { score += 1.5; }
        // resist new bin when mean residual closely matches next item
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        // open new bin when all fitting bins would leave frag just under next item (dead space)
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && next_item_size > item_size && next_item_size - item_size <= 4 && remaining > 50 {
            score -= 2.0;
        }
        // resist new bin late in stream when open bins suffice
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        // open new bin for large items when mean residual is high and spare bins crowd
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
        // gen 31: resist new bin when a fitting bin leaves frag that exactly equals next item (perfect chain)
        if next_item_size > 0 && fitting_bins_count > 0 && bin_residual.saturating_sub(item_size) == next_item_size {
            score += 6.0;
        }
        // gen 31: prefer new bin when item is large and every fitting bin would strand more than half its residual
        if fitting_bins_count > 0 && item_ratio > 0.5 && mean_residual > 24.0 && remaining > 60 {
            score -= 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let fit_ratio = post_residual as f64 / cap;
    score -= 12.0 * (1.0 - fit_ratio).powi(4);

    // Penalize dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    }
    if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) && post_residual > 0 {
        score += 15.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).min(cap));
    }
    // Reward leaving room for the lookahead item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (1.0 - ((post_residual - next_item_size) as f64 / cap));
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Global state coupling: many open bins with high mean residual -> prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let crowd = (open_bins_count as f64 / (1.0 + mean_residual / cap)).sqrt();
    score -= 8.0 * crowd * (0.5 + 0.5 * progress);

    // Penalize bins whose residual deviates far from the mean (fragmentation control).
    score += 0.4 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: prefer it only when nothing fits well and early/late extremes.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        score += 18.0 - pressure - 10.0 * progress + 0.15 * mean_residual;
    }

    // Mild time-horizon modulation: tighten selection as stream advances.
    score *= 1.0 + 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.97;
    score
