pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / c;                       // normalized post residual
    let norm_item = item_size as f64 / c;

    // Base: penalize wasted space, but non-linearly (quadratic + cubic coupling with progress)
    let mut score = norm_pr + 0.9 * norm_pr * norm_pr;

    // Polynomial coupling: waste tolerance shrinks as stream progresses (smooth)
    let urgency = 1.0 + 1.5 * t - 1.0 * t * t;
    score *= urgency;

    // Reward tight fits: subtract bonus proportional to fill ratio, amplified by progress
    let fill = 1.0 - norm_pr;
    score -= 1.2 * fill * fill * (0.5 + t);

    // Dead-space penalty: post residual too small to ever fit anything useful (smooth sigmoid-like)
    let dead = ((norm_pr - 0.10) / 0.05).tanh(); // ~1 when pr tiny, ~-1 when pr large
    score += 0.8 * dead * (0.5 + t);

    // Last-chance bin: strongly favor using it (smooth exponential decay of penalty)
    if fitting_bins_count == 1 {
        score -= 2.5 * (-2.0 * norm_pr).exp();
    }

    // Lookahead coupling: bonus if next item fits the post residual, penalty otherwise (smooth)
    if next_item_size > 0 {
        let next_norm = next_item_size as f64 / c;
        let gap = next_norm - norm_pr;
        let fit_smooth = 1.0 / (1.0 + (8.0 * gap).exp()); // ~1 if next fits, ~0 if not
        score -= 0.7 * fit_smooth;
        score += 0.4 * (1.0 - fit_smooth) * (0.5 + t);
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean (polynomial divergence)
    let mean_norm = mean_residual / c;
    let div = norm_pr - mean_norm;
    score += 0.3 * div * div;

    // Mild pressure to consolidate when many bins are open (smooth)
    let bin_pressure = (open_bins_count as f64).ln().max(0.0) / 5.0;
    score -= 0.3 * fill * bin_pressure;

    // New-bin candidate: penalize opening a fresh bin unless item is large (smooth)
    if bin_residual == bin_capacity {
        let size_pref = ((norm_item - 0.6) / 0.15).tanh();
        score += 1.5 - 1.2 * size_pref;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // --- Perfect fill: strongest reward ---
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // --- Harmonic capacity-quarter classes on post_residual ---
        // Class 0: tiny waste (<25% capacity) -> great
        // Class 1: moderate waste -> mild penalty
        // Class 2: half-empty -> neutral-ish
        // Class 3+: mostly empty bin -> bad placement
        let q = (post_residual * 4) / bin_capacity;
        score -= match q {
            0 => 25.0,
            1 => 5.0,
            2 => -2.0,
            _ => 4.0,
        };
        // Modulo-10 harmonic: residuals that are multiples of 10 align
        // with common item-size granularities -> slightly more reusable
        if post_residual % 10 == 0 {
            score -= 3.0;
        } else if post_residual % 5 == 0 {
            score -= 1.5;
        }
    }

    // --- Lookahead: does the next item still fit here? ---
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // exact harmonic pairing: post_residual == next_item_size
            // leaves a perfect fill next step
            if post_residual == next_item_size {
                score -= 12.0;
            }
        } else {
            score += 5.0;
        }
    }

    // --- Last-chance bin before opening a new one ---
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        score += 2.0;
    }

    // --- New-bin candidate penalty: prefer reusing open bins ---
    if bin_residual == bin_capacity {
        score += 35.0;
        // Late in the stream, opening fresh bins is cheaper than
        // fragmenting many open bins; relax the penalty slightly.
        score -= 10.0 * progress;
    }

    // --- Divergence from mean residual: keep bin population homogeneous ---
    score += (bin_residual as f64 - mean_residual) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
