pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for typical
    // future items (<= 10) are wasted; penalize small nonzero gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 15.0;
    }

    // Reward tight packing (small post_residual relative to residual).
    if bin_residual > 0 {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 25.0 * tightness;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last usable bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // making new-bin candidates (residual == capacity) less attractive.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.5 * open_bins_count as f64;
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 8.0;
        } else {
            score += 10.0; // next item can't use this bin's remainder
        }
    }

    // Mild stream-progression pressure: later in stream, consolidate more.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins with below-average residual (more filled bins first).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = if pr >= item_size { (pr - item_size) as f64 } else { 0.0 };
    let remaining = total_items.saturating_sub(step_index);

    // Residual class ladder (tight-closure tuned, borrowed finer early bands)
    let class: f64 = if pr == 0 { -48.0 }
        else if pr <= 6 { -17.0 }
        else if pr <= 12 { -8.0 }
        else if pr <= 20 { -2.5 }
        else if pr <= 32 { 2.0 }
        else if pr <= 50 { 6.5 }
        else if pr <= 70 { 10.0 }
