            let soft = if pr <= 10 { 0.5 } else { 1.0 };
            score += (5.0 + gap * 0.09) * soft;
            if gap <= 4.0 && pr > 0 { score += (4.0 - gap) * 0.9; }
        }
        // two-item exact chain
        if item_size.saturating_add(next_item_size) == pr { score -= 6.0; }
        // triple chain near-exact
        let triple = item_size.saturating_add(next_item_size * 2);
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        // quad chain — item + next x3 near-exact
        let quad = item_size.saturating_add(next_item_size * 3);
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        // residual hosts next item twice with near-zero slack
        if pr >= next_item_size * 2 {
            let d2 = pr - next_item_size * 2;
            if d2 <= 3 { score -= 2.0 - d2 as f64 * 0.5; }
        }
        // mid dead-zone shaping
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 { score += (gap as f64 - 25.0) * 0.08; }
            if gap >= 15 && gap <= 25 && mean_residual > 22.0 {
                score += (gap as f64 - 15.0) * 0.10;
            }
        }
        // residual exact multiple of next item
        if pr > 0 && pr % next_item_size == 0 { score -= 1.5; }
        // small-residual divisible-by-next strong bonus (borrowed)
        if pr > 0 && pr <= 20 && next_item_size <= pr && pr % next_item_size == 0 { score -= 2.0; }
        // residual just below next item — dead space next step
        if pr > 0 && pr < next_item_size && pr < item_size.min(next_item_size) {
            score += 1.5 + (next_item_size - pr) as f64 * 0.05;
        }
        // gen 32: reward tight two-step chain when fitting bins scarce
        if pr >= next_item_size && (pr - next_item_size) as f64 <= 2.0 && fitting_bins_count <= 2 {
            score -= 3.0;
        }
    }

    // Frag-based dead-space shaping
    if frag > 0.0 {
        if frag < item_size.min(15) as f64 { score += 4.0 + (15.0 - frag) * 0.15; }
        if next_item_size > 0 && (frag as u32) == next_item_size { score -= 4.5; }
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
        }
        if frag >= 20.0 && frag <= 35.0 && remaining > 80 && next_item_size > 0 && next_item_size < frag as u32 {
            score += (frag - 20.0) * 0.045;
        }
        let mr = mean_residual.max(1.0);
        if frag > mr * 1.5 && open_bins_count > 3 { score += (frag - mr * 1.5) * 0.06; }
        if next_item_size > 0 && frag as u32 > next_item_size * 2 && pr > 30 {
            score += (frag - next_item_size as f64) * 0.045;
        }
        // gen 30: reward frag that splits into next item + tiny remainder (two-step close)
        if next_item_size > 0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 { score -= 2.2 - rem as f64 * 0.6; }
        }
        // gen 30: penalize frag just barely too small for next item
        if next_item_size > 0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        // gen 30: reward frag within 3 of next item (near-exact chain)
        if next_item_size > 0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        // gen 30: frag divisible by next item within small range — future perfect splits
        if next_item_size > 0 && frag as u32 % next_item_size == 0 && frag <= next_item_size as f64 * 3.0 {
            score -= 1.5;
        }
        // gen 30: long-stream waste pressure on awkward frag
        if next_item_size > 0 && frag > next_item_size as f64 && frag < 30.0 && remaining > 60 {
            score += (frag - next_item_size as f64) * 0.05;
        }
        // gen 32: chain reward extended to slack <= 6 (borrowed from best)
        if next_item_size > 0 && frag as u32 >= next_item_size {
            let chain = frag as u32 - next_item_size;
            if chain <= 6 { score -= 1.8 * (1.0 - chain as f64 / 6.0); }
        }
        // gen 32: dead-space ratio penalty for large unusable frag
        if next_item_size > 0 && frag > 12.0 && remaining > 30 {
            let usable = next_item_size.min(frag as u32) as f64;
            let dead_ratio = 1.0 - usable / frag.max(1.0);
            if dead_ratio < 0.5 { score += (frag - 12.0) * 0.06 * (1.0 - dead_ratio); }
        }
        // gen 32: long-stream waste pressure extended
        if next_item_size > 0 && frag > next_item_size as f64 && remaining > 120 {
            score += (frag - next_item_size as f64) * 0.03;
        }
    }

    // Scarcity pressure
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 6.0;
    } else if fitting_bins_count >= 5 {
        score += 2.0;
    }

    // Global residual context
    if mean_residual > 25.0 && pr > mean_residual as u32 {
        score += 3.0;
    } else if mean_residual < 12.0 && pr > 0 && pr <= item_size * 2 {
        score -= 2.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        // resist new bin when a fitting bin can chain item + next exactly
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size <= bin_capacity && mean_residual > 20.0 { score += 1.5; }
        // resist new bin when mean residual closely matches next item
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        // gen 30: open new bin when all fitting bins would leave frag just under next item (dead space)
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && next_item_size > item_size && next_item_size - item_size <= 4 && remaining > 50 {
            score -= 2.0;
        }
        // gen 30: resist new bin late in stream when open bins suffice
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        // gen 30: open new bin for large items when mean residual is high and spare bins crowd
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
        // gen 32: resist new bin when some open bin closes exactly on next item
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 { score += 2.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);
    let frag = if pr >= item_size { (pr - item_size) as f64 } else { -(item_size - pr) as f64 };

    // Residual class scoring: reward exact closes and tight residuals.
    let class: f64 = if pr == 0 { -55.0 } else if pr <= 8 { -14.0 } else if pr <= 15 { -6.0 }
        else if pr <= 25 { -1.0 } else if pr <= 40 { 4.5 } else if pr <= 60 { 8.5 } else { 12.0 };
    score += class;

    // Reward residuals that are clean multiples (likely future exact splits).
    if pr > 0 {
        if pr % 10 == 0 { score -= 3.5; }
        else if pr % 5 == 0 { score -= 1.2; }
    }

    // Dead-space avoidance: penalize gaps just below next item size.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 9.0 / (1.0 + slack);
            if slack == 0.0 { score -= 5.0; }
            if slack >= 1.0 && slack <= 10.0 { score -= 3.0 * (1.0 - slack / 10.0); }
            if slack > 45.0 { score += (slack - 45.0) * 0.05; }
        } else {
            // residual can't host next item — dead space next step
            score += 4.0 + (next_item_size - pr) as f64 * 0.09;
        }
    }

    // Two-step exact chain: item then next fills bin exactly.
    if next_item_size > 0 && item_size + next_item_size == pr { score -= 6.0; }
    // Triple chain with tiny slack.
    if next_item_size > 0 {
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 8 { score -= 2.5 * (1.0 - (pr - triple) as f64 / 8.0); }
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 5 { score -= 1.8 * (1.0 - (pr - quad) as f64 / 5.0); }
    }

    // Frag just barely too small for next item = guaranteed dead space.
    if next_item_size > 0 && pr > 0 && pr < next_item_size && next_item_size - pr <= 5 {
        score += (next_item_size - pr) as f64 * 0.9;
    }

    // Mid-range awkward frag scaled by stream length.
    if next_item_size > 0 && frag > 0.0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
        score += (frag - next_item_size as f64) * 0.10;
    }
    if next_item_size > 0 && frag > next_item_size as f64 && frag < 30.0 && remaining > 60 {
        score += (frag - next_item_size as f64) * 0.05;
    }

    // Awkward dead zone 20..35 on long streams.
    if frag >= 20.0 && frag <= 35.0 && remaining > 80 && next_item_size > 0 && next_item_size < frag {
        score += (frag - 20.0) * 0.045;
    }

    // Open-bin pressure: prefer tighter packing when many bins are open.
    score += open_bins_count as f64 * 0.25;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity { score -= 22.0; }

    // Bias toward bins with larger residuals.
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Late-stream tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr as f64 * 0.25 * progress;

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        let mut nb = 8.0;
        // Always open a bin if nothing fits.
        if fitting_bins_count == 0 { nb -= 40.0; }
        else {
            // Some open bin fits: new bin is costly unless it prevents fragmentation.
            nb += 5.0;
            // Prefer new bin for very large items (avoid fragmenting fresh bins late).
            if item_ratio > 0.7 && remaining > 30 { nb -= 3.0 * item_ratio; }
            // Prefer new bin when open bins would leave dead space relative to next item.
            if next_item_size > 0 && item_size + next_item_size > bin_capacity { nb -= 4.0; }
            // Resist new bin when stream is nearly over.
            if remaining < 10 { nb += 8.0; }
            // Resist new bin when mean residual closely matches next item (clean closes ahead).
            if next_item_size > 0 && mean_residual >= next_item_size as f64
                && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { nb += 3.5; }
            // Prefer new bin when mean residual is high (dead space accumulating).
            if mean_residual > 28.0 && remaining > 100 { nb -= 2.5; }
            // Prefer new bin when only fitting bins would leave frag just under next item.
            if next_item_size > 0 && fitting_bins_count <= 2 && pr > 0 && pr < next_item_size
                && next_item_size - pr <= 4 && remaining > 50 { nb -= 2.0; }
        }
        score += nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: fill the bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when the next item exactly fills
    // the residual left behind (a chained perfect fit over two placements).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 900.0;
    }

    // Reward when the next item can also fit into the post residual
    // (keeps the chain going), scaled by how well it matches.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 120.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize dead space: post residual too small to ever fit a typical
    // item (below minimum item size 1 => any residual is usable, but very
    // small slivers relative to mean residual are wasteful).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    if pr > 0.0 {
        let tiny = (1.0 - pr / cap).min(1.0);
        score += 40.0 * tiny * tiny;
    }

    // Prefer bins whose residual is below the mean (tight packing),
    // penalize placing into unusually empty bins.
    score += 0.6 * (mean_residual - bin_residual as f64).max(0.0);

    // Last-chance bonus: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make it attractive only when nothing else fits
    // well; otherwise slightly discourage opening a new bin.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // If next item is large and current item is small, opening a fresh
        // bin can be better (preserve big residuals for big items).
        if next_item_size > 60 && item_size < 30 {
            score -= 80.0;
        }
    }

    // Early in the stream, be more willing to open new bins to build a
    // diverse residual pool; later, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 50.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
