        if next_item_size > 0 && fitting_bins_count > 0 && bin_residual.saturating_sub(item_size) > 0
            && bin_residual.saturating_sub(item_size) % next_item_size == 0
            && bin_residual.saturating_sub(item_size) <= next_item_size * 3 && remaining > 30 {
            score += 3.0;
        }
        // gen 33: open new bin when every fitting bin's frag falls into the 13..25 dead zone
        if next_item_size > 0 && fitting_bins_count >= 1 && fitting_bins_count <= 2 && remaining > 60
            && bin_residual > item_size {
            let f = bin_residual - item_size;
            if f > next_item_size && f < next_item_size + 12 && mean_residual > 22.0 { score -= 2.0; }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (low post residual).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize residuals too small for any future item (dead space).
    let min_item = 1u32;
    if post_residual < min_item {
        score += 50.0;
    } else if post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Bonus proportional to how well next item fits after this one.
            let next_post = post_residual - next_item_size;
            score -= 8.0 * (1.0 - next_post as f64 / bin_capacity as f64);
        } else {
            // Post residual can't fit next item: mild penalty, worse if residual is tiny.
            score += 6.0;
            if post_residual < next_item_size / 2 {
                score += 5.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins with high mean residual: encourage consolidating into
    // already-open bins rather than spreading; penalize new-bin tendency.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: usually bad unless open bins are nearly full
        // or this item fits nothing well.
        let open_pressure = if open_bins_count > 0 {
            1.0 - (mean_residual / bin_capacity as f64)
        } else {
            1.0
        };
        score += 25.0 - 30.0 * open_pressure;
        // Late in stream with many bins, opening new bins is worse.
        score += 10.0 * progress;
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            // Fresh bin can host next item after this one.
            score -= 5.0;
        }
    } else {
        // Favor bins with residual close to item size (best-fit coupling).
        let fit_gap = (bin_residual - item_size) as f64;
        score += 0.05 * fit_gap;
        // Favor bins with below-mean residual (fill the fullest bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Mild penalty for very large post residual that is awkward
    // (not zero, but leaves fragmented space).
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 8.0;
    }

    score
}

