pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, waste is more costly -> amplify residual penalty smoothly.
    let coupling = (pr / cap).powi(2) * (1.0 + 2.0 * progress) * 40.0;
    score += coupling;

    // Reward near-perfect fits smoothly via cubic term on normalized residual.
    score -= 15.0 * (1.0 - (pr / cap)).powi(3);

    // Lookahead: bonus if next item fits the post-residual (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64 / cap;
        score -= 8.0 * (1.0 - gap).powi(2);
    } else if next_item_size > post_residual {
        // penalize leaving dead space relative to the upcoming item
        score += 4.0 * ((next_item_size - post_residual) as f64 / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a bin when open bins fit, smoothly
    // scaled by how many alternatives exist and stream progress.
    if bin_residual == bin_capacity {
        let alternatives = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 0.0 };
        score += 10.0 + 6.0 * alternatives + 10.0 * progress;
        // allow opening new bins late when existing residuals are fragmented
        score -= 5.0 * (mean_residual / cap).powi(2);
    }

    // Mild preference to fill bins that are already small-residual outliers.
    score += 3.0 * ((mean_residual - bin_residual as f64) / cap).abs();

    score
}

