        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
        // gen 34: resist new bin when a fitting bin closes exactly on item + next (perfect pair)
        if next_item_size > 0 && item_size + next_item_size == bin_capacity - item_size.min(bin_residual) && fitting_bins_count > 0 { score += 2.0; }
