pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that cannot host typical future
    // items (small unusable gaps) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    } else {
        // Larger residual is partially usable; mild reward for keeping it.
        score -= 4.0;
    }

    // Reward exact / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Tightness relative to the bin: filling most of the bin is good.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Coupling with mean residual: prefer bins that stay near the open-bin
    // average (keeps a balanced residual profile for future items).
    let deviation = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * deviation;

    // Open-bin pressure: with many open bins, discourage spreading into a
    // new/partially-filled bin; consolidate instead.
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    score += 10.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item can exactly use the post-residual, reward
    // this placement; if post-residual is just barely too small for the next
    // item, penalize creating that dead gap.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size {
            score -= 8.0;
        } else if post_residual >= next_item_size.saturating_sub(5) && post_residual < next_item_size {
            score += 12.0;
        }
    }

    // New-bin candidate handling: opening a fresh bin is justified only when
    // no open bin offers a decent fit or dead space would be created anyway.
    let is_new_bin = bin_residual == bin_capacity;
