            && next_item_size > item_size && next_item_size - item_size <= 4 && remaining > 50 {
            score -= 2.0;
        }
        // resist new bin late in stream when open bins suffice
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        // open new bin for large items when mean residual is high and spare bins crowd
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
        // gen 34: open new bin for mid-size items when fitting bins would leave dead frag vs next item
        if next_item_size > 0 && fitting_bins_count > 0 && next_item_size > item_size && remaining > 50 && mean_residual > 20.0 {
            score -= 1.2;
        }
        // gen 34: resist new bin when fitting bins can tightly close on next item
        if next_item_size > 0 && fitting_bins_count >= 2 && mean_residual >= next_item_size as f64 { score += 2.0; }
        // gen 34: prefer new bin early for very large items to avoid fragmenting fresh bins late
        if item_ratio > 0.85 && remaining > 150 && open_bins_count < 4 { score -= 1.5; }
    }

    score
}

