    let mut score = post_residual as f64;

    // Exact / near-exact fit reward
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 2 {
        score -= 300.0;
    }

    // 2-step lookahead: does the next item fit exactly into the leftover?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if (post - nxt).abs() < 0.5 {
            score -= 250.0; // next item will close this bin perfectly
        } else if nxt <= post {
            let wasted_after = post - nxt;
            score -= 60.0 - wasted_after.min(60.0); // chainable fit
        } else {
            // next item cannot use this residual: penalize dead space
            score += (nxt - post).min(40.0);
        }
        // bonus if residual is small relative to mean residual (tight packing)
        if post < mean_residual {
            score -= (mean_residual - post).min(30.0) * 0.8;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no open bin offers a good fit
    if bin_residual == bin_capacity {
        let good_open_fit = fitting_bins_count > 0 && (post_residual as f64) <= 0.25 * bin_capacity as f64;
        if good_open_fit {
            score += 200.0; // keep existing bins preferred
        } else {
            score -= 40.0; // opening fresh bin is reasonable
        }
        score += open_bins_count as f64 * 2.0;
    }

    // Mild progression term: early stream, be conservative with new bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0;

    score
}

