    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Perfect fit: strong reward
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Penalize small-but-nonzero dead space quadratically
        let pr = post_residual as f64;
        let dead = (1.0 - pr / bin_capacity as f64).min(1.0);
        score += (1.0 - dead) * (1.0 - dead) * 8.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big bonus
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.3; // mild penalty for leftover after lookahead fit
        } else {
            // next item won't fit here; penalize leaving large gaps less useful
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Early stream: prefer filling existing bins tightly, discourage bin sprawl
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(0.0));
    score += pressure * 0.05;

    // Late stream: tighter packing matters more; penalize residual more
    score += t * (post_residual as f64) * 0.5;

    // New-bin candidate: make it attractive only when no good fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a bin, reduced when current bin fits are scarce
        score += 12.0;
        if fitting_bins_count == 0 {
            score -= 40.0;
        } else if fitting_bins_count == 1 {
            score += 15.0; // only one fitting bin -> keep option, slight penalty
        }
        // early stream: opening bins is cheaper
        score -= (1.0 - t) * 6.0;
    }

    // Mild tie-breaking toward bins with residual close to item (snug fits)
    let snug = 1.0 - (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= snug * 2.0;

    score
}

