pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual (tight fit), with smooth polynomial shaping
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap;

    // Non-linear coupling: post_residual vs stream progress (waste less late in stream)
    let coupling = (norm_pr - progress).powi(3) * 40.0;
    score += coupling;

    // Smooth penalty for dead space that no typical item can use
    let dead = (norm_pr - 0.1).max(0.0);
    score += 30.0 * dead * dead * (1.0 - progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits = (pr - nxt) / cap;
        if fits >= 0.0 {
            score -= 12.0 * (1.0 - fits) * (1.0 - progress);
        } else {
            score += 8.0 * (-fits) * (1.0 + progress);
        }
    }

    // Slight preference to fill bins with smaller residuals relative to mean
    score += 5.0 * (bin_residual as f64 - mean_residual) / cap;

    // Mild preference for using existing bins over opening new ones early
    if bin_residual == bin_capacity {
        score += 3.0 + 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
