pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: quantize post_residual into
    // capacity-fraction buckets. Small post_residual classes are desirable
    // (tight packing); mid-size classes create dead space -> penalize.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (pr / c * 8.0).floor(); // 0..7 harmonic class

    // Class-based additive adjustment (tight fits rewarded, dead zones punished)
    score += match class as u32 {
        0 => -14.0,                      // near-perfect fill
        1 => -8.0,
        2 => 2.0,
        3 => 6.0,
        4 => 9.0,                        // ~50% dead space worst zone
        5 => 7.0,
        6 => 4.0,
        _ => 1.0,
    };

    // Modulo coupling: residuals that are multiples of common small item
    // granularities (item sizes often cluster on multiples of 5/10) are
    // reusable by future items -> reward them.
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead harmonic match: if the next item exactly fits the post
    // residual (or its integer-division complement), strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let gap = post_residual - next_item_size;
            // reward proportional to how tightly next item nests
            score -= 10.0 * (1.0 - gap as f64 / c);
            if gap % 10 == 0 { score -= 3.0; }
        } else {
            // next item cannot use this residual at all: mild penalty scaled
            // by leftover size
            score += 3.0 * (pr / c);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual;
    // prefer it only when no open bin offers a decent (small-class) fit.
    if bin_residual == bin_capacity {
        // opening a new bin wastes the mean residual mass already out there
        score += 10.0 + open_bins_count as f64 * 0.5;
        if next_item_size > 0 && next_item_size >= bin_capacity - item_size {
            score -= 8.0; // next item is huge, fresh bin is fine
