    }

    // Stream progression: late in the stream, prefer closing bins tightly
    // (avoid stranding residual) since fewer future items remain to fill gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 4.0 * (pr / c);

    // Pull toward mean residual: bins already below mean residual are
    // "loose" and absorb items more cheaply.
    score -= (mean_residual - pr) * 0.05;

    score
}

