        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 { score += 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        // gen 39: open new bin when mean residual sits in awkward 12..20 zone on long streams
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        // gen 39: resist new bin when stream nearly over
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
    } else {
        // Any non-fitting open bin candidate is heavily penalized (shouldn't occur, safety).
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps heavily (dead space avoidance).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Penalty decays as post_residual grows into a reusable zone.
    let pr = post_residual as f64;
    if pr >= 10.0 {
        // Mild reward for leaving gaps that can still host typical small items.
        score -= 4.0 * (1.0 - pr / bin_capacity as f64);
    }

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Dead-space coupling: if next item cannot fit in the post residual,
    // this placement likely strands space unless post_residual is large.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 8.0;
    }
    // Reward when next item fits snugly into the residual.
    if next_item_size > 0 && next_item_size <= post_residual && post_residual - next_item_size < 10 {
        score -= 10.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when it enables a large future pairing
    // (big item followed by another big item), otherwise penalize mildly.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size >= 50 {
            score -= 20.0;
        }
    }

    // Slight preference for filling fuller bins early vs late in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
