pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: later, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional fill achieved by this placement.
    let fill = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 60.0 * fill * fill;

    // Reward tight fits more strongly as the stream matures.
    score -= (1.0 - progress) * 10.0 * (post_residual as f64 / bin_capacity as f64).powi(3);

    // Penalize large dead space, but only when the item is small relative to it.
    if post_residual > 0 && (post_residual as f64) < 0.5 * bin_capacity as f64 {
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strong bonus to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly or well,
    // reward this placement; if next item is large, prefer conserving big residuals.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize leaving a tiny unusable gap.
            score += 12.0 * (post_residual as f64 / next_item_size as f64).min(1.0);
        }
    } else {
        // Final item: maximize fill aggressively.
        score -= 40.0 * fill;
    }

    // Global state: many open bins with high mean residual -> encourage consolidating
    // into existing bins rather than spreading.
    let mean_res_norm = mean_residual / bin_capacity as f64;
    if mean_res_norm > 0.4 {
        score -= 15.0 * mean_res_norm * (open_bins_count as f64).ln().max(1.0) / 3.0;
    }

    // Penalize opening a new bin when plenty of open bins could fit the item.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count > 0 { fitting_bins_count as f64 } else { 0.0 };
        score += 25.0 + 10.0 * pressure;
        // But allow new bin if this item is huge and stream is early (reserve strategy).
        if item_size as f64 > 0.6 * bin_capacity as f64 && progress < 0.5 {
            score -= 30.0;
        }
    }

    // Mild penalty for very small post-residual fragments (wasted capacity)
    // unless the bin is nearly full anyway.
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
