pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream: mildly tolerate residual (bins still fillable later).
    // Late in the stream: strongly penalize leftover space (dead space).
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 12.0 * norm_pr * norm_pr * progress_poly;

    // Slight discount for tight fits, modulated by progress.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit_ratio * fit_ratio * (0.5 + progress_poly);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 6.0 * (1.0 + progress);
    }

    // Lookahead: penalize if the next item cannot fit in post_residual.
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 4.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score -= 2.0 * (pr - next_item_size as f64) / cap;
    }

    // Mild penalty when this bin's residual deviates from mean residual (balance pressure).
    score += 0.05 * (pr - mean_residual).abs() * (0.5 + progress_poly);

    // New-bin candidate: encourage opening fresh bins early, discourage late.
    if bin_residual == bin_capacity {
        score = 0.35 * cap * (1.0 - progress) + 0.65 * cap * progress + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = if pr >= item_size { (pr - item_size) as f64 } else { 0.0 };
    let remaining = total_items.saturating_sub(step_index);

    // Residual class ladder (tight-closure tuned)
    let class: f64 = if pr == 0 { -48.0 }
        else if pr <= 6 { -17.0 }
        else if pr <= 12 { -8.0 }
        else if pr <= 20 { -2.5 }
        else if pr <= 32 { 2.0 }
        else if pr <= 50 { 6.5 }
        else if pr <= 70 { 10.0 }
        else { 14.0 };
    score += class;

    // Reusability bonus
    let reusable = (pr % 10 == 0) as f64 * 4.0
        + (pr % 20 == 0) as f64 * 3.0
        + (pr % 25 == 0) as f64 * 2.0
        + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Dead residual just below item size — guaranteed waste
    if pr > 0 && pr < item_size.min(20) {
        score += 6.0;
    }

    // Lookahead coupling with next item.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 6.0; }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 40.0 { score += (slack - 40.0) * 0.06; }
            if slack <= 3.0 { score -= 1.0 * (1.0 - slack / 3.0); }
            // residual can host next item repeatedly — perfect future splits
            if slack >= next_item_size as f64 { score -= 2.5; }
        } else {
            let gap = (next_item_size - pr) as f64;
            let soft = if pr <= 10 { 0.5 } else { 1.0 };
            score += (5.0 + gap * 0.09) * soft;
            if gap <= 4.0 && pr > 0 { score += (4.0 - gap) * 0.9; }
        }
        // two-item exact chain
        if item_size.saturating_add(next_item_size) == pr { score -= 6.0; }
        // triple chain near-exact
        let triple = item_size.saturating_add(next_item_size * 2);
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        // quad chain — item + next x3 near-exact
        let quad = item_size.saturating_add(next_item_size * 3);
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        // residual hosts next item twice with near-zero slack
        if pr >= next_item_size * 2 {
            let d2 = pr - next_item_size * 2;
            if d2 <= 3 { score -= 2.0 - d2 as f64 * 0.5; }
        }
        // mid dead-zone shaping
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 { score += (gap as f64 - 25.0) * 0.08; }
            if gap >= 15 && gap <= 25 && mean_residual > 22.0 {
                score += (gap as f64 - 15.0) * 0.10;
            }
        }
        // residual exact multiple of next item
        if pr > 0 && pr % next_item_size == 0 { score -= 1.5; }
        // residual just below next item — dead space next step
        if pr > 0 && pr < next_item_size && pr < item_size.min(next_item_size) {
            score += 1.5 + (next_item_size - pr) as f64 * 0.05;
        }
        // gen 40: reward exact two-item chain when it closes the bin perfectly
        if item_size.saturating_add(next_item_size) == pr && pr == bin_capacity { score -= 4.0; }
    }

    // Frag-based dead-space shaping
    if frag > 0.0 {
        if frag < item_size.min(15) as f64 { score += 4.0 + (15.0 - frag) * 0.15; }
        if next_item_size > 0 && (frag as u32) == next_item_size { score -= 4.5; }
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
        }
        if frag >= 20.0 && frag <= 35.0 && remaining > 80 && next_item_size > 0 && next_item_size < frag as u32 {
            score += (frag - 20.0) * 0.045;
        }
        let mr = mean_residual.max(1.0);
        if frag > mr * 1.5 && open_bins_count > 3 { score += (frag - mr * 1.5) * 0.06; }
        if next_item_size > 0 && frag as u32 > next_item_size * 2 && pr > 30 {
            score += (frag - next_item_size as f64) * 0.045;
        }
        // reward frag that splits into next item + tiny remainder (two-step close)
        if next_item_size > 0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 { score -= 2.2 - rem as f64 * 0.6; }
        }
        // penalize frag just barely too small for next item
        if next_item_size > 0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        // reward frag within 3 of next item (near-exact chain)
        if next_item_size > 0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        // frag divisible by next item within small range — future perfect splits
        if next_item_size > 0 && frag as u32 % next_item_size == 0 && frag <= next_item_size as f64 * 3.0 {
            score -= 1.5;
        }
        // long-stream waste pressure on awkward frag
        if next_item_size > 0 && frag > next_item_size as f64 && frag < 30.0 && remaining > 60 {
            score += (frag - next_item_size as f64) * 0.05;
        }
        // gen 40: reward perfect close — frag is zero (bin fully closed)
        if frag == 0.0 { score -= 4.0; }
        // gen 40: penalize very large frag that will likely never be filled
        if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }
        // gen 40: dead-space ratio — penalize frag in the half-open gap (next, 2*next) on long streams with low mean residual
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && mean_residual < 16.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
        // gen 40: scale dead-zone penalty by stream length
        if next_item_size > 0 && frag > next_item_size as f64 && remaining > 120 {
            score += (frag - next_item_size as f64) * 0.03;
        }
    }

    // Scarcity pressure
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 6.0;
    } else if fitting_bins_count >= 5 {
        score += 2.0;
    }

    // Global residual context
    if mean_residual > 25.0 && pr > mean_residual as u32 {
        score += 3.0;
    } else if mean_residual < 12.0 && pr > 0 && pr <= item_size * 2 {
        score -= 2.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        // resist new bin when a fitting bin can chain item + next exactly
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size <= bin_capacity && mean_residual > 20.0 { score += 1.5; }
        // resist new bin when mean residual closely matches next item
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        // open new bin when all fitting bins would leave frag just under next item (dead space)
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && next_item_size > item_size && next_item_size - item_size <= 4 && remaining > 50 {
            score -= 2.0;
        }
        // resist new bin late in stream when open bins suffice
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        // open new bin for large items when mean residual is high and spare bins crowd
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
        // gen 40: open new bin when mean residual sits in the awkward 12..20 dead zone on a long stream
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        // gen 40: resist new bin when stream ends soon even if mean residual is high
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
        // gen 40: open new bin when the only fitting bins would leave near-dead residuals relative to next item
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && item_size + next_item_size <= bin_capacity && mean_residual > 28.0 && remaining > 60 { score -= 1.8; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: residuals in the "usable band" (>= 10)
    // are worth keeping; tiny residuals are dead space.
    let usable_threshold = 10.0;
    if post < usable_threshold {
        // Dead space penalty, worse the smaller it is (quadratic in deficit).
        let deficit = usable_threshold - post;
        score += 40.0 + deficit * deficit * 2.0;
    }

    // Integer-division class: post_residual divisible by common item-size
    // harmonics (5, 10, 20, 25, 50) is more likely to be exactly consumed.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony_bonus = 0.0;
        if pr % 5 == 0 { harmony_bonus += 3.0; }
        if pr % 10 == 0 { harmony_bonus += 4.0; }
        if pr % 20 == 0 { harmony_bonus += 3.0; }
        if pr % 25 == 0 { harmony_bonus += 3.0; }
        if pr % 50 == 0 { harmony_bonus += 4.0; }
        score -= harmony_bonus;
    }

    // Lookahead: reward if next item fits in post_residual (chaining),
    // penalize if it nearly fits (wasted potential).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
        // Extra reward when next item exactly consumes post_residual.
        if next_item_size == post_residual {
            score -= 25.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 && next_item_size - post_residual <= 10 {
        score += 8.0; // near-miss: this bin's leftover likely useless for next item
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when this item is large relative to
    // mean residual (poor fit everywhere) or stream is early.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 30.0 + item_frac * 20.0 - progress * 10.0;
        if next_item_size > 0 && next_item_size > post_residual {
            score += 5.0; // new bin gives room for lookahead
        }
        if fitting_bins_count <= 1 {
            score -= 35.0; // poor fit elsewhere -> new bin is fine
        }
    }

    // Mild preference for bins below mean residual (balance load).
    score += (post - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = if pr >= item_size { (pr - item_size) as f64 } else { 0.0 };
    let remaining = total_items.saturating_sub(step_index);

    // Residual class ladder (tightened low end)
    let class: f64 = if pr == 0 { -48.0 }
        else if pr <= 5 { -18.0 }
        else if pr <= 10 { -10.0 }
        else if pr <= 18 { -3.0 }
        else if pr <= 28 { 2.0 }
        else if pr <= 45 { 6.5 }
        else if pr <= 65 { 10.0 }
        else { 14.0 };
    score += class;

    // Reusability bonus
    let reusable = (pr % 10 == 0) as f64 * 4.0
        + (pr % 20 == 0) as f64 * 3.0
        + (pr % 25 == 0) as f64 * 2.0
        + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Dead residual just below item size — guaranteed waste
    if pr > 0 && pr < item_size.min(20) {
        score += 6.0;
    }

    // Lookahead coupling with next item.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 6.0; }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 40.0 { score += (slack - 40.0) * 0.06; }
            if slack <= 3.0 { score -= 1.0 * (1.0 - slack / 3.0); }
            if slack >= next_item_size as f64 { score -= 2.5; }
        } else {
            let gap = (next_item_size - pr) as f64;
            let soft = if pr <= 10 { 0.5 } else { 1.0 };
            score += (5.0 + gap * 0.09) * soft;
            if gap <= 4.0 && pr > 0 { score += (4.0 - gap) * 0.9; }
        }
        // two-item exact chain
        if item_size.saturating_add(next_item_size) == pr { score -= 6.0; }
        // triple chain near-exact
        let triple = item_size.saturating_add(next_item_size * 2);
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        // quad chain — item + next x3 near-exact
        let quad = item_size.saturating_add(next_item_size * 3);
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        // residual hosts next item twice with near-zero slack
        if pr >= next_item_size * 2 {
            let d2 = pr - next_item_size * 2;
            if d2 <= 3 { score -= 2.0 - d2 as f64 * 0.5; }
        }
        // mid dead-zone shaping
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 { score += (gap as f64 - 25.0) * 0.08; }
            if gap >= 15 && gap <= 25 && mean_residual > 22.0 {
                score += (gap as f64 - 15.0) * 0.10;
            }
        }
        // residual exact multiple of next item
        if pr > 0 && pr % next_item_size == 0 { score -= 1.5; }
        // residual just below next item — dead space next step
        if pr > 0 && pr < next_item_size && pr < item_size.min(next_item_size) {
            score += 1.5 + (next_item_size - pr) as f64 * 0.05;
        }
        // new: exact two-step chain — pr minus next equals item exactly
        if pr >= next_item_size && pr - next_item_size == item_size { score -= 2.0; }
    }

    // Frag-based dead-space shaping
    if frag > 0.0 {
        if frag < item_size.min(15) as f64 { score += 4.0 + (15.0 - frag) * 0.15; }
        if next_item_size > 0 && (frag as u32) == next_item_size { score -= 4.5; }
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
            // gen 40: sharpen this dead-zone when stream is long and mean residual low
            if mean_residual < 16.0 && remaining > 100 { score += (frag - next_item_size as f64) * 0.08; }
        }
        if frag >= 20.0 && frag <= 35.0 && remaining > 80 && next_item_size > 0 && next_item_size < frag as u32 {
            score += (frag - 20.0) * 0.045;
        }
        // gen 40: penalize large frag that will likely never be filled
        if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }
        let mr = mean_residual.max(1.0);
        if frag > mr * 1.5 && open_bins_count > 3 { score += (frag - mr * 1.5) * 0.06; }
        if next_item_size > 0 && frag as u32 > next_item_size * 2 && pr > 30 {
            score += (frag - next_item_size as f64) * 0.045;
        }
        // reward frag that splits into next item + tiny remainder (two-step close)
        if next_item_size > 0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 { score -= 2.2 - rem as f64 * 0.6; }
        }
        // penalize frag just barely too small for next item
        if next_item_size > 0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        // reward frag within 3 of next item (near-exact chain)
        if next_item_size > 0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        // frag divisible by next item within small range — future perfect splits
        if next_item_size > 0 && frag as u32 % next_item_size == 0 && frag <= next_item_size as f64 * 3.0 {
            score -= 1.5;
        }
        // long-stream waste pressure on awkward frag
        if next_item_size > 0 && frag > next_item_size as f64 && frag < 30.0 && remaining > 60 {
            score += (frag - next_item_size as f64) * 0.05;
        }
        // gen 40: reward tiny frag (near-closing bin)
        if frag <= 2.0 { score -= 3.0; }
        // gen 40: dead-space ratio — frag that exceeds usable next-item fit by a large ratio
        if next_item_size > 0 && frag > 12.0 && remaining > 30 {
            let usable = next_item_size.min(frag as u32) as f64;
            let dead_ratio = (frag - usable) / frag.max(1.0);
            if dead_ratio < 0.5 { score += (frag - 12.0) * 0.06 * (1.0 - dead_ratio); }
        }
    } else {
        // exact fill
        score -= 4.0;
    }

    // Scarcity pressure
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 6.0;
    } else if fitting_bins_count >= 5 {
        score += 2.0;
    }

    // Global residual context
    if mean_residual > 25.0 && pr > mean_residual as u32 {
        score += 3.0;
    } else if mean_residual < 12.0 && pr > 0 && pr <= item_size * 2 {
        score -= 2.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        // resist new bin when a fitting bin can chain item + next exactly
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size <= bin_capacity && mean_residual > 20.0 { score += 1.5; }
        // resist new bin when mean residual closely matches next item
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        // open new bin when all fitting bins would leave frag just under next item (dead space)
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && next_item_size > item_size && next_item_size - item_size <= 4 && remaining > 50 {
            score -= 2.0;
        }
        // resist new bin late in stream when open bins suffice
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        // open new bin for large items when mean residual is high and spare bins crowd
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
        // gen 40: resist new bin when remaining is short and a fitting bin exists
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
        // gen 40: open new bin when mean residual sits in the awkward 12..20 dead zone on a long stream
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        // gen 40: resist new bin when some existing bin can close exactly on next item
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 { score += 2.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the enemy.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // gap below minimum item size is pure waste
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit: fully packed bin
    }

    // Reward tight fits (high fill ratio of the used space).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill;

    // Open-bin pressure: discourage spreading across many bins,
    // but ease pressure late in the stream when consolidation matters less.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * (open_bins_count as f64) * (1.0 - 0.5 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: prefer bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // New-bin candidate: neutral baseline, slightly penalized so it is only
    // chosen when every open bin would create bad dead space.
    if bin_residual == bin_capacity {
        score += 45.0 + mean_residual * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);

    // Dead-space class ladder (borrowed from best-known)
    let class: f64 = if pr == 0 { -48.0 }
        else if pr <= 8 { -15.0 }
        else if pr <= 15 { -6.5 }
        else if pr <= 25 { -1.0 }
        else if pr <= 40 { 4.0 }
        else if pr <= 60 { 8.0 }
        else { 12.0 };
    score += class;

    // Reward residuals on round boundaries (likely future perfect splits)
    let reusable = (pr % 10 == 0) as f64 * 4.0 + (pr % 20 == 0) as f64 * 3.0
        + (pr % 25 == 0) as f64 * 2.0 + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    let frag = (pr - item_size) as f64;

    // Next-item lookahead: reward bins that will host next item cleanly
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 5.0; }
            if slack >= 1.0 && slack <= 12.0 { score -= 3.0 * (1.0 - slack / 12.0); }
            if slack > 45.0 { score += (slack - 45.0) * 0.05; }
        } else {
            score += 5.0 + (next_item_size - pr) as f64 * 0.09;
        }
        // two-item exact chain
        if item_size + next_item_size == pr { score -= 6.0; }
        // triple chain with near-zero slack
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        // quad chain
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        // double next-item with near-zero slack
        if pr >= next_item_size * 2 {
            let d2 = pr - next_item_size * 2;
            if d2 <= 3 { score -= 2.0 - d2 as f64 * 0.5; }
        }
        // frag just under next item: guaranteed dead space
        if pr > 0 && pr < next_item_size && next_item_size - pr <= 4 {
            score += (next_item_size - pr) as f64 * 0.9;
        }
        // frag in (next, 2*next) gap — penalize more when mean residual low
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 {
            score += (frag - next_item_size as f64) * 0.10;
            if mean_residual < 16.0 && remaining > 100 {
                score += (frag - next_item_size as f64) * 0.08;
            }
        }
        // residual divisible by next item
        if pr > 0 && pr % next_item_size == 0 { score -= 1.5; }
    }

    // Tiny frag near-closing
    if frag > 0.0 && frag <= 2.0 { score -= 3.0; }

    // Large frag that will likely never fill
    if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }

    // Mean-residual scaled penalty on awkward mid frag
    let mr = mean_residual.max(1.0);
    if frag > 0.0 && frag > mr * 1.5 && open_bins_count > 3 {
        score += (frag - mr * 1.5) * 0.06;
    }

    // Last-chance bin: strongly favor
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Slight bias toward larger residuals
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Open-bin pressure
    score += open_bins_count as f64 * 0.3;

    // Late-stream tightening
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr as f64 * 0.3 * progress;

    // ---- New-bin candidate logic ----
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 { score += 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        // resist new bin when mean residual closely matches next item
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size
            && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        // open new bin in awkward 12..20 mean-residual dead zone on long streams
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        // resist new bin when stream nearly over
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
    } else {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Perfect chain fit gets a big reward.
            if slack == 0.0 {
                score -= 60.0;
            } else {
                score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Next item won't chain: penalize leftover dead space, worse if tiny.
            let dead = post_residual as f64;
            if dead < 10.0 {
                score += 15.0; // unusable sliver
            } else {
                score += 5.0 * (dead / bin_capacity as f64);
            }
        }
    }

    // Relative-to-mean coupling: prefer bins whose post residual stays near the mean
    // (balanced packing), penalize outliers.
    let diff = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * diff;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base new-bin cost: opening a bin is expensive.
        score += 45.0;
        // But if many open bins exist and mean residual is fragmented, new bin
        // becomes relatively better.
        score -= 0.05 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 20.0; // item won't fit anywhere anyway (defensive)
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Prefer filling fuller bins (small post_residual) with slight non-linearity.
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
