    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a super-linear penalty on waste.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Reward exact / near-exact fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Last-chance bonus: if this is the only bin that fits, prefer it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: does the residual left behind accommodate the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Leaving space usable by the next item is good.
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // Placing here destroys the only space for the next item: penalize mildly.
            score += 6.0;
        }
        // Bonus if post_residual exactly matches next item (perfect chain).
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // late in the stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 10.0 * waste_frac;

    // Global state: many open bins with slack -> favor filling existing bins.
    if open_bins_count > 2 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Prefer bins whose residual deviates favorably from the mean (fill the emptiest-relative bins
    // that still fit well, keeping tight bins for tight items).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // New-bin candidate: make opening a new bin costly unless the item is large and
    // no existing bin gives a decent fit.
    if bin_residual == bin_capacity {
        let base_cost = 55.0 + 20.0 * progress;
        let desperation = if fitting_bins_count == 0 { 0.0 } else { (item_size as f64 / bin_capacity as f64) * 30.0 };
        score += base_cost - desperation;
        // Opening a new bin is more attractive early when lookahead item is large.
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Smooth non-linear coupling: quadratic in normalized post residual, modulated by progress
    score += 8.0 * norm_pr * norm_pr * (1.0 - progress);
    score -= 6.0 * norm_pr * (1.0 - norm_pr) * progress;
    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 10.0 * tightness * tightness * progress;
    // Last-chance bonus (smoothly scaled)
    if fitting_bins_count == 1 {
        score -= 12.0 * (0.5 + 0.5 * progress);
    }
    // Prefer bins below mean residual (fill emptier bins) with smooth term
    let mean_norm = mean_residual / cap;
    score += 4.0 * (norm_pr - mean_norm) * (norm_pr - mean_norm) - 3.0 * mean_norm;
    // Lookahead: penalize leaving residual that barely fits next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = pr - nx;
        if diff >= 0.0 && diff < 10.0 {
            score += 5.0 * (1.0 - diff / 10.0);
        } else if diff < 0.0 {
            score += 2.0 * (-diff / cap);
        }
    }
    // Mild penalty for spreading across many bins
    score += 0.3 * open_bins_count as f64 * norm_pr;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = if pr >= item_size { (pr - item_size) as f64 } else { 0.0 };
    let remaining = total_items.saturating_sub(step_index);

    // Residual class ladder (tightened per best-heuristic profile)
    let class: f64 = if pr == 0 { -48.0 }
        else if pr <= 8 { -16.0 }
        else if pr <= 15 { -7.5 }
        else if pr <= 25 { -2.0 }
        else if pr <= 40 { 3.5 }
        else if pr <= 60 { 7.5 }
        else { 12.0 };
    score += class;

    // Reusability bonus
    let reusable = (pr % 10 == 0) as f64 * 4.0
        + (pr % 20 == 0) as f64 * 3.0
        + (pr % 25 == 0) as f64 * 2.0
        + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Dead residual just below item size — guaranteed waste
    if pr > 0 && pr < item_size.min(20) {
        score += 6.0;
    }

    // Exact-fit reward
    if frag == 0.0 && pr > 0 { score -= 4.0; }

    // Lookahead coupling with next item.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 6.0; }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 40.0 { score += (slack - 40.0) * 0.06; }
            if slack <= 3.0 { score -= 1.0 * (1.0 - slack / 3.0); }
            if slack >= next_item_size as f64 { score -= 2.5; }
            // gen 41: tight fit with few alternatives — strong preference
            if slack <= 2.0 && fitting_bins_count <= 2 { score -= 2.0; }
        } else {
            let gap = (next_item_size - pr) as f64;
            let soft = if pr <= 10 { 0.5 } else { 1.0 };
            score += (5.0 + gap * 0.09) * soft;
            if gap <= 4.0 && pr > 0 { score += (4.0 - gap) * 0.9; }
        }
        // two-item exact chain
        if item_size.saturating_add(next_item_size) == pr { score -= 6.0; }
        // triple chain near-exact
        let triple = item_size.saturating_add(next_item_size * 2);
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        // quad chain — item + next x3 near-exact
        let quad = item_size.saturating_add(next_item_size * 3);
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        // residual hosts next item twice with near-zero slack
        if pr >= next_item_size * 2 {
            let d2 = pr - next_item_size * 2;
            if d2 <= 3 { score -= 2.0 - d2 as f64 * 0.5; }
        }
        // mid dead-zone shaping
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 { score += (gap as f64 - 25.0) * 0.08; }
            if gap >= 15 && gap <= 25 && mean_residual > 22.0 {
                score += (gap as f64 - 15.0) * 0.10;
            }
        }
        // residual exact multiple of next item
        if pr > 0 && pr % next_item_size == 0 { score -= 1.5; }
        // residual just below next item — dead space next step
        if pr > 0 && pr < next_item_size && pr < item_size.min(next_item_size) {
            score += 1.5 + (next_item_size - pr) as f64 * 0.05;
        }
    }

    // Frag-based dead-space shaping
    if frag > 0.0 {
        if frag < item_size.min(15) as f64 { score += 4.0 + (15.0 - frag) * 0.15; }
        if next_item_size > 0 && (frag as u32) == next_item_size { score -= 4.5; }
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
            // gen 41: sharpen in low-mean-residual long streams (few absorption chances)
            if mean_residual < 16.0 && remaining > 100 { score += (frag - next_item_size as f64) * 0.08; }
        }
        if frag >= 20.0 && frag <= 35.0 && remaining > 80 && next_item_size > 0 && next_item_size < frag as u32 {
            score += (frag - 20.0) * 0.045;
        }
        // gen 41: large frag unlikely to ever fill
        if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }
        // gen 41: tiny frag is near-closed — reward
        if frag <= 2.0 { score -= 3.0; }
        let mr = mean_residual.max(1.0);
        if frag > mr * 1.5 && open_bins_count > 3 { score += (frag - mr * 1.5) * 0.06; }
        if next_item_size > 0 && frag as u32 > next_item_size * 2 && pr > 30 {
            score += (frag - next_item_size as f64) * 0.045;
        }
        // reward frag that splits into next item + tiny remainder (two-step close)
        if next_item_size > 0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 { score -= 2.2 - rem as f64 * 0.6; }
            if rem <= 6 { score -= 1.8 * (1.0 - rem as f64 / 6.0); }
        }
        // penalize frag just barely too small for next item
        if next_item_size > 0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        // reward frag within 3 of next item (near-exact chain)
        if next_item_size > 0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        // frag divisible by next item within small range — future perfect splits
        if next_item_size > 0 && frag as u32 % next_item_size == 0 && frag <= next_item_size as f64 * 3.0 {
            score -= 1.5;
        }
        // long-stream waste pressure on awkward frag
        if next_item_size > 0 && frag > next_item_size as f64 && frag < 30.0 && remaining > 60 {
            score += (frag - next_item_size as f64) * 0.05;
        }
        // gen 41: dead-space ratio penalty — frag that exceeds usable next-item fit
        if next_item_size > 0 && frag > 12.0 && remaining > 30 {
            let usable = next_item_size.min(frag as u32) as f64;
            let dead_ratio = (frag - usable) / frag.max(1.0);
            if dead_ratio < 0.5 { score += (frag - 12.0) * 0.06 * (1.0 - dead_ratio); }
        }
    }

    // Scarcity pressure
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 6.0;
    } else if fitting_bins_count >= 5 {
        score += 2.0;
    }

    // Global residual context
    if mean_residual > 25.0 && pr > mean_residual as u32 {
        score += 3.0;
    } else if mean_residual < 12.0 && pr > 0 && pr <= item_size * 2 {
        score -= 2.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        // resist new bin when a fitting bin can chain item + next exactly
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size <= bin_capacity && mean_residual > 20.0 { score += 1.5; }
        // resist new bin when mean residual closely matches next item
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        // open new bin when all fitting bins would leave frag just under next item (dead space)
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && next_item_size > item_size && next_item_size - item_size <= 4 && remaining > 50 {
            score -= 2.0;
        }
        // resist new bin late in stream when open bins suffice
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
        // gen 41: open new bin for large items when mean residual is high and spare bins crowd
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
        // gen 41: open new bin when mean residual sits in the awkward 12..20 zone on a long stream
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        // gen 41: resist new bin when some existing bin closes exactly on next item
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 { score += 2.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);
    let frag = pr.saturating_sub(item_size) as f64;

    // Residual class shaping (borrowed from best, retuned)
    let class: f64 = if pr == 0 { -50.0 }
        else if pr <= 6 { -14.0 }
        else if pr <= 12 { -6.0 }
        else if pr <= 20 { -1.5 }
        else if pr <= 35 { 3.5 }
        else if pr <= 55 { 8.0 }
        else { 12.0 };
    score += class;

    // Reward residuals that are clean multiples (likely future exact splits)
    if pr > 0 {
        if pr % next_item_size.max(1) == 0 { score -= 2.0; }
        if pr % 10 == 0 { score -= 1.5; }
        if pr % 25 == 0 { score -= 1.0; }
    }

    // Next-item lookahead
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 5.0; }
            if slack >= 1.0 && slack <= 10.0 { score -= 3.0 * (1.0 - slack / 10.0); }
            if slack > 45.0 { score += (slack - 45.0) * 0.05; }
        } else {
            // residual just below next item = guaranteed dead space
            score += 4.0 + (next_item_size - pr) as f64 * 0.09;
        }
        // exact two-item chain
        if item_size + next_item_size == pr { score -= 6.0; }
        // triple chain with small slack
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 8 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 8.0);
        }
        // quad chain
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 5 { score -= 1.8; }
    }

    // Frag-based dead-space shaping
    if frag > 0.0 {
        if frag < item_size.min(15) as f64 { score += 4.0 + (15.0 - frag) * 0.15; }
        if frag <= 2.0 { score -= 3.0; }
        if next_item_size > 0 && (frag as u32) == next_item_size { score -= 4.5; }
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 {
            // awkward mid-range frag: worse on long streams / low mean residual
            let w = if mean_residual < 16.0 && remaining > 100 { 0.10 } else { 0.05 };
            score += (frag - next_item_size as f64) * w;
        }
        if next_item_size > 0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }
        let mr = mean_residual.max(1.0);
        if frag > mr * 1.5 && open_bins_count > 3 { score += (frag - mr * 1.5) * 0.06; }
        if next_item_size > 0 && frag > 0.0 && frag as u32 % next_item_size == 0 && frag <= next_item_size as f64 * 3.0 { score -= 1.5; }
    }

    // Open-bin pressure
    score += open_bins_count as f64 * 0.25;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity { score -= 22.0; }

    // Bias toward larger residuals slightly
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Late-stream tightening
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    // ---- New-bin candidate logic ----
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        score += 8.0 + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if fitting_bins_count > 0 { score += 4.0; }

        // Large items early: give them a fresh bin to avoid fragmenting hosts
        if item_ratio > 0.7 && remaining > 20 { score -= 2.5 * item_ratio; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }

        // Dead space accumulating: open fresh bins on long streams
        if mean_residual > 25.0 && remaining > 80 { score -= 2.0; }
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }

        // Resist new bins when stream nearly over or open bins absorb next item cleanly
        if remaining < 15 && fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 { score += 2.5; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        // Open new bin when only fitting bins would leave frag just under next item
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2 && item_size + next_item_size <= bin_capacity && mean_residual > 28.0 && remaining > 60 { score -= 1.8; }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
    } else {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: prefer leftovers in "useful" residue classes.
    // Items 1..=100 unknown distribution; leftovers divisible by common item sizes (10,20,25,50)
    // are more likely reusable by future items.
    let harmonic_bonus: f64 = {
        let pr = post_residual;
        let mut b = 0.0;
        if pr > 0 {
            if pr % 10 == 0 { b += 6.0; }
            if pr % 20 == 0 { b += 4.0; }
            if pr % 25 == 0 { b += 4.0; }
            if pr % 50 == 0 { b += 5.0; }
            if pr == bin_capacity / 2 { b += 3.0; }
        } else {
            // Perfect fit: best possible outcome.
            b -= 30.0;
        }
        b
    };
    score -= harmonic_bonus;

    // Penalize small dead space (unusable residue) non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0 - 1.5 * post_residual as f64;
    }

    // Tightness reward: the fuller the bin relative to capacity, the better.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill * fill;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            if slack % 10 == 0 { score -= 8.0; }
            if slack < 10 { score += 6.0; }
        }
    }

    // New-bin candidate logic: opening a new bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of consuming a fresh bin, modulated by stream progress and bin count.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 + 10.0 * progress;
        if fitting_bins_count == 0 {
            // Nothing fits anywhere: new bin is mandatory.
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            // Only one fitting bin: keep new-bin option expensive unless that bin wastes space.
            score += 8.0;
        }
        // Many open bins with large mean residual -> prefer reusing them.
        score += 0.15 * mean_residual;
    } else {
        // Mild reward for consolidating into already-open bins.
        score -= 2.0;
        // Penalize bins whose residual deviates far below the mean (fragmented bins).
        let dev = mean_residual - bin_residual as f64;
        if dev > 0.0 {
            score += 0.05 * dev;
        }
    }

    // Integer-division threshold on post_residual: leftovers >= half capacity are flexible.
    if post_residual >= bin_capacity / 2 {
        score -= 4.0;
    }

    score
}

