        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 { score += 2.0; }
    } else if pr < item_size {
        // non-fitting bin — strong penalty so it is never chosen over a fitting option
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is smaller than the smallest possible item (1),
    // but practically we penalize gaps that are too small to be useful
    // relative to typical item sizes. Treat gaps < 10 as dead weight.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit reward: post_residual == 0 is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Exact fill relative to capacity: prefer bins that become very full.
    let fill_ratio = (bin_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * fill_ratio * fill_ratio;

    // Open bins pressure: penalize opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: add pressure proportional to open bins count.
        score += 15.0 + (open_bins_count as f64) * 2.0;
    } else {
        // Reward using existing bins, more so when many are open.
        score -= (open_bins_count as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }
    // If next item would be blocked by leaving this gap, penalize small gaps.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // Slight preference for tighter bins overall vs mean residual.
    if (bin_residual as f64) < mean_residual {
        score += 3.0;
    } else {
        score -= 2.0;
    }

    score
}

