pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect fits (no dead space).
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: reward when next item exactly fills the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0; // chain fit: this bin becomes perfectly full next step
        } else if next_item_size <= post_residual {
            // Next item fits: penalize leftover slack after the pair.
            let pair_slack = (post_residual - next_item_size) as f64;
            score -= 50.0 - pair_slack * 0.5;
        } else {
            // Next item will NOT fit in this bin: penalize small dead space
            // that is likely unusable, scaled by how close next item is.
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 1.5;
        }
    }

    // Penalize post_residual below the smallest plausible item (dead space).
    if post_residual < 10 {
        score += 200.0;
    }

    // Compare against mean residual: prefer bins whose remaining space
    // stays close to the average (balanced packing), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bonus: if this is the only bin that fits the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Prefer tighter bins overall (smaller residual before placement).
    score += (bin_residual as f64) * 0.1;

    // Slight preference for keeping bin count low as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and when
        // decent fitting bins exist.
        score += 100.0 + progress * 100.0 + (fitting_bins_count as f64) * 20.0;
    }

    score
}

