        else if pr <= 12 { -8.0 }
        else if pr <= 20 { -2.5 }
        else if pr <= 32 { 2.0 }
        else if pr <= 50 { 6.5 }
        else if pr <= 70 { 10.0 }
        else { 14.0 };
    score += class;

