pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: only attractive when the item fits poorly everywhere else.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let tightness = item_size as f64 / bin_capacity as f64;
        let last_chance = fitting_bins_count <= 1;
        let late = step_index as f64 / (total_items.max(1) as f64);
        let mut nb = 45.0 - 20.0 * tightness;
        if last_chance {
            nb -= 25.0;
        }
        if fitting_bins_count == 0 {
            nb -= 40.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        nb += 30.0 * late;
        // If mean residual is large, open bins have slack; discourage new bins.
        nb += (mean_residual - post_residual as f64) * 0.4;
        // Lookahead: if next item is large, a fresh bin is valuable.
        if next_item_size > 0 && (next_item_size as f64) > 0.7 * bin_capacity as f64 {
            nb -= 15.0;
        }
        return nb;
    }

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= 30.0 * (1.0 - fit_ratio) * (1.0 - fit_ratio);

    // Penalize dead space that no future item can plausibly use.
    let smallest = 1.0f64;
    if (post_residual as f64) < smallest {
        score -= 50.0; // perfect fit
    }

    // Lookahead coupling: if the next item fits the post-residual exactly-ish, reward.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 18.0 / (1.0 + gap);
        // If next item won't fit here anyway, mild penalty for leaving awkward residue.
        if post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 22.0;
    }

    // Prefer bins with residual below the mean (consolidate fuller bins).
    score += 0.35 * (mean_residual - bin_residual as f64);

    // Mild pressure against accumulating many open bins early.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.15 * (open_bins_count as f64) * (1.0 - progress);

    score
}

