    // Early on (progress ~ 0), tolerate larger residuals; late, penalize them.
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 40.0 * progress_poly * norm_post * norm_post;

    // Reward tight fits (small post_residual) more strongly as stream advances.
    score -= 25.0 * progress_poly * (1.0 - norm_post) * (1.0 - norm_post);

    // Penalize residuals that cannot fit the lookahead item (dead space risk),
    // smoothly scaled by how close the next item is to the residual.
    if next_item_size > 0 {
