    // Residuals that are multiples of 10 are "harmonic" — easier to fill later.
    let pr = post_residual;
    let harmonic = pr % 10 == 0;
    let near_harmonic = pr % 10 <= 2 || pr % 10 >= 8;

    if harmonic {
        score -= 8.0; // reward perfectly harmonic leftover
    } else if near_harmonic {
        score -= 3.0;
    } else {
        // penalize awkward residues proportional to distance from harmonic class
        let d = (pr % 10).min(10 - pr % 10) as f64;
        score += d * 1.5;
    }

    // Perfect fit is ideal
    if pr == 0 {
        score -= 50.0;
    }

    // Dead space: residuals too small for the minimum item size are wasted
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // reward if the leftover after next item is harmonic or zero
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 {
                score -= 10.0;
            } else {
                score += (pr2 % 10) as f64 * 0.8;
            }
        } else {
            // next item won't fit here: slight penalty proportional to gap
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer tight fits: closeness of item to residual
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 6.0;

    // Late in the stream, consolidate: favor existing bins over new ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 10.0 + 30.0 * progress;
        // but if mean residual is low and item is large, a new bin is reasonable
        if item_size as f64 > mean_residual {
            score -= 12.0;
        }
    } else {
        // existing bin: reward consolidation, more so late in stream
        score -= 4.0 + 8.0 * progress;
    }

    // Many open bins: encourage filling them down
    score += open_bins_count as f64 * 0.2;

    score
}

