pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest plausible
    // item (<= 10) are pure waste — hit them hard and super-linearly.
    if post_residual < 10 {
        score += 120.0 + (10 - post_residual) as f64 * 25.0;
    } else if post_residual <= 20 {
        // Small gaps are semi-dead: only usable by tiny future items.
        score += 25.0 * (1.0 - (post_residual as f64) / 20.0);
    } else {
        // Larger post-residuals remain usable; mildly reward keeping them.
        score -= 6.0;
    }

    // Reward tight fits (waste ratio near zero) with a non-linear bonus.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.85 {
        score -= 30.0 * (fill_ratio - 0.85) / 0.15;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: many open bins -> discourage opening yet another,
    // encourage consolidating into existing bins.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins and to
        // how well existing bins could still absorb items (mean residual).
        score += 40.0 + 12.0 * open_pressure + 0.35 * mean_residual;
        // If no existing bin fits, opening a new one is fine.
        if fitting_bins_count == 0 {
            score -= 90.0;
        }
    } else {
        // Existing bins get a consolidation bonus under pressure.
        score -= 3.0 * open_pressure;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement creates a perfect chain — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // Next item won't fit in the leftover: leftover becomes dead
            // unless large enough for later items.
            if post_residual < 10 {
                score += 30.0;
            }
        }
    }

    // Late in the stream, minimize total bins: favor filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - fill_ratio.min(1.0));

    score
}

