    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Core archetype: 2-step lookahead matching.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual >= next_item_size {
            // Reward exact match: post_residual == next_item_size is perfect.
            let diff = (pr - nxt).abs();
            score -= 2.5 * nxt * (1.0 - diff / (nxt + 1.0));
            // Extra reward if the item after next could also fit (rough guess).
            if post_residual >= next_item_size * 2 {
                score -= 3.0;
            }
        } else {
