    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 8.0 * tightness;
    }

    // Penalize near-empty fills of a fresh bin only mildly; new-bin candidate
    // gets a baseline so it wins only when fits are poor.
    if bin_residual == bin_capacity {
        score += 6.0;
    }

    // Late-stream consolidation: as the stream progresses, prefer filling
    // existing bins tighter and avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0 * (1.0 - pr / cap);

    // Mild penalty when many bins are open (encourage consolidation).
    score += open_bins_count as f64 * 0.15;

    // Small reward for large items placed into tight residuals.
    score -= (item_size as f64 / cap) * 2.0 * (1.0 - pr / cap);

    score
