pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_post * norm_post);

    // Non-linear coupling: later in the stream, tight fits matter more
    let tightness = 1.0 - norm_post;
    score -= 18.0 * progress * tightness * tightness * norm_item;

    // Penalize large dead space quadratically, stronger as stream progresses
    score += 25.0 * progress * norm_post * norm_post * cap * 0.1;

    // Reward near-perfect fits smoothly (post_residual close to 0)
    score -= 30.0 * (-pr / 8.0).exp();

    // Lookahead: reward if next item fits the post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 * (next_item_size as f64 / cap) * (1.0 + progress);
    } else if next_item_size > 0 {
        score += 6.0 * progress;
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // Pull toward mean residual: smooth regularization
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: neutral-ish baseline with slight progress-dependent bias
    if bin_residual == bin_capacity {
        score = cap * 0.5 + 30.0 * progress - 8.0 * (1.0 - progress);
    }

    score
}

