    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes over capacity fractions
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;
    let quarter = cap / 4; // 25
    let eighth = cap / 8;  // 12

    // Reward (subtract) when post_residual lands in "useful" harmonic classes:
    // residuals that are multiples of common item-size granularities (10, 20, 25)
    let class_bonus = if pr == 0 {
        40.0 // perfect fit — huge reward
    } else if pr % 25 == 0 {
        18.0
    } else if pr % 20 == 0 {
        14.0
    } else if pr % 10 == 0 {
        10.0
    } else if pr % 5 == 0 {
        5.0
    } else {
