        }
        if next_item_size > 0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        if next_item_size > 0 && frag as u32 % next_item_size == 0 && frag <= next_item_size as f64 * 3.0 {
            score -= 1.5;
        }
        if next_item_size > 0 && frag > next_item_size as f64 && frag < 30.0 && remaining > 60 {
            score += (frag - next_item_size as f64) * 0.05;
        }
        // dead-space ratio — penalize frag far above next item when stream is long
        if next_item_size > 0 && frag > next_item_size as f64 && remaining > 120 {
            score += (frag - next_item_size as f64) * 0.03;
        }
        // reward near-closing frag (tiny remainder)
        if frag <= 2.0 { score -= 3.0; }
        // penalize large frag that will likely never be filled
        if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }
