        if next_item_size > 0 && open_bins_count > 6 && mean_residual >= next_item_size as f64 && remaining > 30 { score += 2.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if no plausible future item (>= 1) fits, but
    // practically we treat gaps below the next item size as dead.
    if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead: the larger the waste, the worse.
        score += 3.0 * (next_item_size - post_residual) as f64;
    }

    // Perfect fit is a big win.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        // Tiny leftover gap is nearly dead space (items >= 1 exist, but small
        // gaps are hard to reuse); mild penalty.
        score += 5.0 * (10 - post_residual) as f64;
    }

    // Reward tight fits: small post_residual relative to bin capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 10.0 * tightness;

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new bins
    // (the new-bin candidate has bin_residual == bin_capacity, so it gets
    // penalized here since it also has large post_residual naturally).
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 15.0 + 2.0 * open_bins_count as f64;
        // But if the item is large and nothing fits well, a fresh bin is fine.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    } else {
        // Using an existing bin slightly reduces system-wide bin pressure.
        score -= 1.0 * open_bins_count as f64 / 10.0;
    }

    // Late in the stream, be more conservative: prefer consolidating into
    // existing bins rather than leaving many partially-filled bins behind.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 * progress;
    } else {
        score += 5.0 * progress;
    }

    // Prefer bins whose residual deviates from the mean in a useful way:
    // if this bin's residual is much larger than the mean, it's a good host.
    let residual_gap = bin_residual as f64 - mean_residual;
    if residual_gap > 0.0 {
        score -= 0.05 * residual_gap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
