pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = (pr as f64) - item_size as f64; // >= 0 for fitting bins
    let remaining = total_items.saturating_sub(step_index);

    // Residual class: reward small/near-zero residuals, penalize mid-range dead zones.
    let class: f64 = if pr == 0 { -48.0 }
        else if pr <= 8 { -15.0 }
        else if pr <= 15 { -6.5 }
        else if pr <= 25 { -1.0 }
        else if pr <= 40 { 4.0 }
        else if pr <= 60 { 8.0 }
        else { 12.0 };
    score += class;

    // Reward residuals that are "usable" round numbers for future items.
    let reusable = (pr % 10 == 0) as f64 * 4.0
        + (pr % 20 == 0) as f64 * 3.0
        + (pr % 25 == 0) as f64 * 2.0
        + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Next-item lookahead: reward bins that can host the next item with small slack.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 5.0; }
            if slack >= 1.0 && slack <= 12.0 { score -= 3.0 * (1.0 - slack / 12.0); }
            if slack > 45.0 { score += (slack - 45.0) * 0.05; }
        } else {
            score += 5.0 + (next_item_size - pr) as f64 * 0.09;
        }
    }

    if pr >= item_size {
        // Penalize tiny awkward fragments that can't host the next item.
        if frag > 0.0 && frag < (item_size.min(15)) as f64 {
            score += 4.0 + (15.0 - frag) * 0.15;
        }
        // Two-step chain: bin closes after hosting next item exactly.
        if next_item_size > 0 && item_size + next_item_size == pr {
            score -= 6.0;
        }
        // Frag just barely too small for next item = guaranteed dead space.
        if next_item_size > 0 && frag > 0.0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        // Frag splits into next item plus tiny remainder — near-perfect chain.
        if next_item_size > 0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 { score -= 2.2 - rem as f64 * 0.6; }
        }
        // Dead-space ratio: penalize frag in (next, 2*next) gap on long streams.
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
        // Large frag that will likely never be filled.
        if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }
        // Reward pr that hosts next item twice with near-zero slack.
        if next_item_size > 0 && pr >= next_item_size * 2 {
            let d2 = pr - next_item_size * 2;
            if d2 <= 3 { score -= 2.0 - d2 as f64 * 0.5; }
        }
        // Triple chain lookahead.
        if next_item_size > 0 {
            let triple = item_size + next_item_size * 2;
            if pr >= triple && pr - triple <= 10 {
                score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
            }
        }
        // Frag exactly equals next item — perfect chain next step.
        if next_item_size > 0 && frag as u32 == next_item_size { score -= 4.5; }
        // Awkward gap after next item in 25..45 dead zone.
        if next_item_size > 0 && pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 { score += (gap as f64 - 25.0) * 0.08; }
        }
        // Residual divisible by next item — future perfect splits.
        if next_item_size > 0 && pr > 0 && pr % next_item_size == 0 { score -= 1.5; }
        // Frag within 3 of next item — near-exact chain.
        if next_item_size > 0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        // Mean-residual scaled penalty for oversized frag.
        let mr = mean_residual.max(1.0);
        if frag > 0.0 && frag > mr * 1.5 && open_bins_count > 3 {
            score += (frag - mr * 1.5) * 0.06;
        }
    }

    // Open-bin pressure: prefer tighter packing when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Slight bias toward bins with larger residuals.
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // NEW-BIN CANDIDATE LOGIC (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 { score += 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && next_item_size > 0 && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        // Open new bin when only 1-2 fitting bins would strand dead space for next item.
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && item_size + next_item_size <= bin_capacity && mean_residual > 28.0 && remaining > 60 { score -= 1.8; }
        // Resist new bin when mean residual closely matches next item.
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size
            && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        // Open new bin when mean residual in the awkward 12..20 zone on long streams.
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
    } else {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 5 {
        score -= 15.0;
    }

    // Lookahead: reward if next item fits into the post residual, penalize otherwise.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Dead space relative to next item's needs.
            let waste = post_residual as f64;
            score += 0.08 * waste;
            if next_item_size <= bin_residual {
                score += 4.0; // this bin would have fit next item, but placement blocks it
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin generally,
    // but relax penalty late in the stream or when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 18.0;
        // If mean residual across open bins is small (fragmented), opening is less bad.
        new_bin_penalty -= 0.15 * mean_residual;
        // Early stream: keep bins open (amortize); late stream: less concern.
        new_bin_penalty += 10.0 * (1.0 - progress);
        // Many open bins: mildly discourage more.
        new_bin_penalty += 0.5 * open_bins_count as f64;
        score += new_bin_penalty.max(0.0);
    } else {
        // Using existing bins is good; slightly reward when many open bins exist
        // to encourage draining them.
        score -= 0.1 * open_bins_count as f64;
        // Prefer bins with residual below mean (consolidate small leftovers).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Residual class ladder: reward small usable residuals, penalize large ones.
    let class: f64 = if pr == 0 { -48.0 } else if pr <= 8 { -15.0 } else if pr <= 15 { -6.5 }
        else if pr <= 25 { -1.0 } else if pr <= 40 { 4.0 } else if pr <= 60 { 8.0 } else { 12.0 };
    score += class;

    // Divisibility bonuses: residuals that align with common item sizes are reusable.
    let reusable = (pr % 10 == 0) as f64 * 4.0 + (pr % 20 == 0) as f64 * 3.0
        + (pr % 25 == 0) as f64 * 2.0 + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Two-step lookahead: does the next item fit after this placement?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= next_item_size {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 5.0; }
            if slack >= 1.0 && slack <= 12.0 { score -= 3.0 * (1.0 - slack / 12.0); }
            if slack > 45.0 { score += (slack - 45.0) * 0.05; }
            // post-residual is an exact multiple of next item -> perfect future splits
            if pr % next_item_size == 0 { score -= 2.0; }
        } else {
            // Dead space: residual just below next item is guaranteed waste.
            score += 5.0 + (nxt - pr as f64) * 0.09;
            if next_item_size - pr <= 4 { score += (next_item_size - pr) as f64 * 0.9; }
        }
        // Exact chain: item + next fills the bin perfectly.
        if item_size + next_item_size == pr { score -= 6.0; }
        // Triple chain near-exact.
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 6 { score -= 2.2 * (1.0 - (pr - triple) as f64 / 6.0); }
        // Double next-item fit with tiny slack.
        if pr >= next_item_size * 2 { let d2 = pr - next_item_size * 2; if d2 <= 3 { score -= 2.0 - d2 as f64 * 0.5; } }
        // Dead zone: gap in (next, 2*next) is stranded space on long streams.
        let frag = (pr - item_size) as f64;
        if frag > nxt && frag < nxt * 2.0 && remaining > 60 { score += (frag - nxt) * 0.08; }
    } else {
        // Last item: tightest fit wins.
        score -= 10.0;
    }

    // Tight frag rewards.
    let frag = (pr - item_size) as f64;
    if frag == 0.0 { score -= 4.0; }
    if frag > 0.0 && frag <= 2.0 { score -= 3.0; }
    if frag > 0.0 && frag < item_size.min(15) as f64 { score += 4.0 + (15.0 - frag) * 0.15; }

    // Mean-residual comparison: leave less slack than average.
    if frag < mean_residual { score -= (mean_residual - frag) * 0.4; } else { score += (frag - mean_residual) * 0.3; }

    // Large frag that will likely never be filled.
    if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }

    // Last-chance bonus: only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 8.0 * tightness;
    }

    // Late-stream consolidation.
    score -= progress * 4.0 * (1.0 - pr as f64 / cap);
    score += open_bins_count as f64 * 0.15;
    score -= (item_size as f64 / cap) * 2.0 * (1.0 - pr as f64 / cap);

