        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / cap.max(1.0);
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        // Open new bin when mean residual is high on a long stream.
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        // Resist new bin when existing bins close cleanly on next item.
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 { score += 2.0; }
        // Prefer new bin for large items when mean residual is mid-range.
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        // Open new bin when no existing bin leaves room for next item after this one.
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        // Resist new bin near stream end.
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        // Resist sprawl when many open bins can absorb next item.
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        // Prefer new bin for very large items early in stream.
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        // Open new bin when fitting bins would strand awkward mid-range residuals.
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        // Resist new bin when a fitting bin leaves frag just under next item (dead space).
        if next_item_size > 0 && fitting_bins_count > 0 && next_item_size > item_size && remaining > 50 && mean_residual > 20.0 { score -= 1.2; }
        // Resist new bin when stream is nearly over.
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
    } else {
        // Existing-bin candidates get a mild offset so new bins only win on genuinely poor fits.
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear coupling: polynomial in post_residual with progress-modulated coefficients
    let pr = post_residual as f64;
    let pr_n = pr / bin_capacity as f64;
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;

    // Dead-space penalty grows with progress (end of stream: waste hurts more)
    let dead_weight = 0.8 + 2.5 * prog2 + 1.5 * prog3;
    score += dead_weight * pr_n * pr_n * bin_capacity as f64;

    // Reward tight fits (small post_residual) with smooth exponential-ish polynomial
    let tightness = 1.0 - pr_n;
    score -= (2.0 + 3.0 * progress) * tightness * tightness * tightness;

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let diff = pr - nx;
        if diff >= 0.0 {
            let d_n = diff / bin_capacity as f64;
            score -= (1.5 + 2.0 * prog2) * (1.0 - d_n) * (1.0 - d_n);
        } else {
            let gap = (-diff) / bin_capacity as f64;
            score += (0.5 + 1.5 * progress) * gap * gap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 4.0 + 6.0 * progress;
    }

    // Mild preference to fill bins with residual close to mean (balance avoidance)
    let mean_dev = (pr - mean_residual).abs() / bin_capacity as f64;
    score += (0.3 + 0.7 * prog2) * mean_dev;

    // New-bin candidate: penalize opening new bins unless current bins are very full
    if bin_residual == bin_capacity {
        let fill_pressure = 1.0 - (mean_residual / bin_capacity as f64);
        score += 3.0 + 8.0 * fill_pressure * fill_pressure * (1.0 - progress);
        // Late in stream, new bins are cheaper to open (less future waste risk)
        score -= 2.0 * prog3;
    }

    // Mild penalty for many open bins (encourage consolidation)
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
