        }
        // gen 46: reward exact two-item chain regardless of fit order
        if item_size + next_item_size == pr { score -= 3.0; }
        // gen 46: reward bins whose residual can host next item twice with near-zero slack
        if pr >= next_item_size * 2 && pr - next_item_size * 2 <= 1 { score -= 1.5; }
    }

    if frag > 0.0 {
        if frag < item_size.min(15) as f64 { score += 4.0 + (15.0 - frag) * 0.15; }
        if next_item_size > 0 && (frag as u32) == next_item_size { score -= 4.5; }
