pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 10.0).floor() as i64; // 0..10 capacity-decile class

    // Penalize dead space super-linearly, but give a bonus for near-perfect fits.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;
    if post_residual <= 5 {
        score -= 40.0; // near-closed bin is excellent
    } else if post_residual <= 15 {
        score -= 18.0;
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of common
    // small item sizes (10/20/25/50) remain "usable" for future arrivals.
    let usable = post_residual % 10 == 0 || post_residual % 25 == 0;
    if usable {
        score -= 6.0 + 0.05 * post_residual as f64;
    } else {
        score += 8.0; // awkward residual class
    }

    // Lookahead coupling: does the next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Exact harmonic match: post_residual is an integer multiple of next item.
            let k = post_residual / next_item_size;
            if k >= 1 && post_residual % next_item_size == 0 {
                score -= 25.0 + 3.0 * k as f64;
            } else {
                score -= 12.0;
            }
        } else {
            // Next item won't fit here: leftover becomes dead space.
            score += 15.0 + 0.1 * next_item_size as f64;
        }
    } else {
        // Last item: prefer tightest fit strongly.
        score -= 30.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.1 * item_size as f64;
    }

    // New-bin candidate handling: empty bin gets a baseline score near the mean
    // residual of open bins; open it only when open bins are crowded.
    if bin_residual == bin_capacity {
        score = 55.0 + mean_residual * 0.5;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count == 0 {
            score -= 100.0;
