            score += (frag - next_item_size as f64) * 0.03;
        }
        // gen 47: sharpen dead-space ratio in the (next, 2*next) gap when mean residual is low
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0
            && mean_residual < 16.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
        // reward near-closing frag (tiny remainder)
        if frag <= 2.0 { score -= 3.0; }
        // penalize large frag that will likely never be filled
        if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }
        // exact-fill reward
        if frag == 0.0 { score -= 4.0; }
        // gen 47: dead-space ratio — penalize frag with poor usable fraction on mid streams
        if next_item_size > 0 && frag > 12.0 {
            let usable = (frag as u32).min(next_item_size) as f64;
            let dead_ratio = 1.0 - usable / frag;
            if dead_ratio < 0.5 && remaining > 30 {
                score += (frag - 12.0) * 0.06 * (1.0 - dead_ratio);
            }
        }
        // gen 47: reward frag that equals next + item (perfect two-item chain next step)
        if next_item_size > 0 && frag as u32 == next_item_size + item_size.min(frag as u32) && frag as u32 > next_item_size {
            score -= 2.0;
        }
    }

    // Scarcity pressure
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 6.0;
    } else if fitting_bins_count >= 5 {
        score += 2.0;
    }

    // Global residual context
    if mean_residual > 25.0 && pr > mean_residual as u32 {
        score += 3.0;
    } else if mean_residual < 12.0 && pr > 0 && pr <= item_size * 2 {
        score -= 2.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size <= bin_capacity && mean_residual > 20.0 { score += 1.5; }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && next_item_size > item_size && next_item_size - item_size <= 4 && remaining > 50 {
            score -= 2.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
        // resist new bin when an open bin can absorb item plus next item exactly
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size == bin_capacity { score += 3.0; }
        // open new bin in awkward mid dead zone on very long streams
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        // resist new bin late when open bins suffice
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
        // gen 47: resist new bin when mean residual closely matches next item (open bins will close cleanly)
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 { score += 2.0; }
        // gen 47: resist new bin when only fitting bins would leave frag just under next item
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && item_size + next_item_size <= bin_capacity && mean_residual > 28.0 && remaining > 60 { score -= 1.8; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual > 0 && post_residual < item_size {
        score += 12.0; // gap likely unusable for the next item
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: prefer bins where the item fills most of the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness;

    // Lookahead: reward if next item fits the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: discourage new bins when many are open.
    if bin_residual == bin_capacity {
        score += 5.0 + 2.0 * open_bins_count as f64;
    }

    // Early-stream mild preference to keep bins consolidated.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = (pr as i32 - item_size as i32) as f64;
    let remaining = total_items.saturating_sub(step_index);

    // Residual class ladder: strongly prefer bins that close or nearly close.
    let class: f64 = if pr == 0 { -48.0 } else if pr <= 8 { -15.0 } else if pr <= 15 { -6.5 } else if pr <= 25 { -1.0 } else if pr <= 40 { 4.0 } else if pr <= 60 { 8.0 } else { 12.0 };
    score += class;

    // Reusable residual bonuses (common multiples).
    let reusable = (pr % 10 == 0) as f64 * 4.0 + (pr % 20 == 0) as f64 * 3.0 + (pr % 25 == 0) as f64 * 2.0 + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Two-step lookahead matching (inherited from parent).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= next_item_size {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 5.0; }
            if slack >= 1.0 && slack <= 12.0 { score -= 3.0 * (1.0 - slack / 12.0); }
            if slack > 45.0 { score += (slack - 45.0) * 0.05; }
        } else {
            score += 5.0 + (next_item_size - pr) as f64 * 0.09;
        }
    } else {
        score -= 10.0;
    }

    if fits_ok(pr, item_size) {
        // Exact close.
        if frag == 0.0 { score -= 4.0; }
        // frag equals next item: perfect chain next step.
        if next_item_size > 0 && frag > 0.0 && (frag as u32) == next_item_size { score -= 4.5; }
        // Small remainder after next item fits.
        if next_item_size > 0 && frag > 0.0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 { score -= 2.2 - rem as f64 * 0.6; }
        }
        // frag barely too small for next item: guaranteed dead space.
        if next_item_size > 0 && frag > 0.0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        // Two-item chain: item then next exactly fills residual.
        if next_item_size > 0 && item_size + next_item_size == pr { score -= 6.0; }
        // Triple chain near-exact.
        if next_item_size > 0 {
            let triple = item_size + next_item_size * 2;
            if pr >= triple && pr - triple <= 10 { score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0); }
        }
        // Dead-space ratio: mid-range frag in (next, 2*next) wastes space.
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
        }
        // Large frag unlikely to be filled.
        if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }
        // Near-closing bins.
        if frag > 0.0 && frag <= 2.0 { score -= 3.0; }
        // Mean-residual squeeze comparison.
        if frag > 0.0 {
            if frag < mean_residual { score -= (mean_residual - frag) * 0.4; } else { score += (frag - mean_residual) * 0.3; }
        }
    }

    // Last-chance bonus: only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 8.0 * tightness;
    }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        score += 8.0 + crowding * 6.0 + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        let item_ratio = item_size as f64 / cap;
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        // Open new bin when only fitting bins would strand dead space vs next item.
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2 && item_size + next_item_size <= bin_capacity && mean_residual > 28.0 && remaining > 60 { score -= 1.8; }
    } else {
        score += 60.0;
    }

    // Late-stream consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 4.0 * (1.0 - pr as f64 / cap);
    score += open_bins_count as f64 * 0.15;
    score -= (item_size as f64 / cap) * 2.0 * (1.0 - pr as f64 / cap);

    score
}

#[inline]
fn fits_ok(pr: u32, item_size: u32) -> bool { pr >= item_size }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is best possible outcome.
    if post_residual == 0 {
        return -10000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post residual
    // closely matches the next item size (creating a near-perfect follow-up).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot fit here after placement; penalize relative gap.
        let gap = (next_item_size - post_residual) as f64;
        score += 8.0 * (gap / 100.0);
    }

    // Penalize leaving small unusable slivers (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Prefer bins with residuals below the mean (tighter bins first),
    // keeping looser bins available for larger future items.
    score += 2.0 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 1.0 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 30.0;
        // Late in the stream, opening new bins is less costly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * progress;
        // If next item is large, a fresh bin is more attractive.
        if next_item_size > 0 {
            score -= (next_item_size as f64 / 100.0) * 15.0;
        }
    }

    // Mild fragmentation penalty scaled by bin fullness.
    score += (post_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

