        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size == bin_capacity { score += 3.0; }
        // open new bin in awkward mid dead zone on very long streams
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        // resist new bin late when open bins suffice
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
        // gen 48: resist new bin when mean residual closely matches next item (open bins will close cleanly)
        if next_item_size > 0 && fitting_bins_count >= 2 && mean_residual >= next_item_size as f64 {
            score += 2.0;
        }
        // gen 48: open new bin when the only fitting bins would leave frag just under next item
        if next_item_size > 0 && fitting_bins_count > 0 && remaining > 50 && mean_residual > 20.0 {
            let fits_next = (mean_residual as u32) >= next_item_size;
            if !fits_next && (mean_residual as u32) + 4 >= next_item_size { score -= 1.8; }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Normalized post-residual, cubic coupling with stream progress:
    // later in the stream, we tolerate large residuals less (they become dead space).
    let norm_post = post / cap;
    let progress_weight = 0.5 + 1.5 * progress * progress;
    let mut score = post * (1.0 + progress_weight * norm_post * norm_post);

    // Tight-fit reward: smooth quadratic on fill ratio.
    let fill = item / cap;
    score -= 12.0 * fill * fill * (1.0 + progress);

    // Exact/near-exact fit bonus (smooth exponential rather than hard cutoff).
    let tightness = 1.0 - norm_post;
    score -= 8.0 * tightness * tightness * tightness * tightness;

    // Lookahead coupling: reward if next item fits the post residual smoothly.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let nx = next_item_size as f64;
        let combo_fill = (item + nx) / cap;
        score -= 6.0 * combo_fill * combo_fill;
    } else if next_item_size > 0 {
        // Penalize leaving a residual that neither fits next item usefully.
        let waste = post - (next_item_size as f64);
        score += 0.05 * waste * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    }

    // Mild penalty when many bins are open and this one is far below mean residual
    // (prefer consolidating into bins near the mean to keep residuals uniform).
    let dev = (post - mean_residual) / cap;
    score += 3.0 * dev * dev * (0.5 + progress);

    // New-bin candidate: penalize opening a bin unless residuals are tight
    // or few bins fit the item (smooth logistic gate on mean residual).
    if bin_residual == bin_capacity {
        let gate = 1.0 / (1.0 + (-(mean_residual / cap - 0.35) * 8.0).exp());
        score += 6.0 + 14.0 * gate - 8.0 * (1.0 - (fitting_bins_count as f64).min(5.0) / 5.0);
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
