pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod capacity fractions.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;

    // Reward tight fits: post_residual in low harmonic classes.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit, always take
    } else if post_residual <= quarter {
        score -= 60.0;
    } else if post_residual <= half {
