pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the enemy.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Relative tightness: reward using a large fraction of the bin.
    let fill_fraction = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_fraction;

    // Last chance: only one bin fits the item -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Pressure from number of open bins: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 25.0 + 8.0 * open_bins_count as f64;
        // But allow opening a new bin if the item would leave a big gap elsewhere
        // and the next item is large (needs fresh space).
        if next_item_size > 60 && post_residual < next_item_size as u32 {
            score -= 35.0;
        }
    } else {
        // Mild preference to fill already-open bins as stream progresses.
        score -= 5.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Prefer bins with below-average residual (denser bins) for tight fits.
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    }

    // Lookahead: if next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use the leftover gap -> penalize wasting space.
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
