    if next_item_size > 0 && item_size + next_item_size == pr { score -= 6.0; }

    // Triple / quad chain lookahead.
    if next_item_size > 0 {
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
