        if next_item_size > 0 && fitting_bins_count >= 1 && fitting_bins_count <= 2
            && item_size < next_item_size
            && pr <= item_size
            && (next_item_size - item_size) <= 6
            && remaining > 80 { score -= 2.5; }
        // Gen 49 mutation: resist new bin late in stream when mean residual can absorb next item.
        if next_item_size > 0 && remaining < 30 && mean_residual >= next_item_size as f64 { score += 4.0; }
    } else {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Post residual can still fit the next item: reward proportional to snugness
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Post residual too small for next item: penalize dead space, worse if very small
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64;
        score += 10.0 * (1.0 - dead / bin_capacity as f64);
    }

    // Compare against mean residual across open bins: prefer bins tighter than average
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize unless current bin would leave large unusable residue
    if bin_residual == bin_capacity {
        let base_penalty = 15.0;
        let waste_now = (bin_residual - item_size) as f64;
        let poor_fit = if next_item_size > 0 && waste_now < next_item_size as f64 { 30.0 } else { 0.0 };
        score += base_penalty + poor_fit;
    }

    // Early in stream: be more conservative about fragmenting bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 80.0;
    }

    // Penalize dead space relative to smallest plausible item.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let dead_penalty = (post_residual as f64 / 10.0).powi(2);
    score += dead_penalty * (0.5 + 0.5 * (1.0 - progress));

    // Lookahead coupling: reward bins whose leftover fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 60.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // leftover blocks next item but is small
        score += 20.0 * (next_item_size - post_residual) as f64 / 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Prefer fuller bins over emptier ones (best-fit bias).
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    // New-bin candidate handling: only attractive when open bins are crowded
    // or mean residual is too small to host future items.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let scarcity = (mean_residual - item_size as f64).max(0.0);
        score += 200.0 - 30.0 * crowd.min(10.0) - scarcity * 2.0;
        if next_item_size > 0 && next_item_size > mean_residual {
            score -= 100.0;
        }
    }

    // Late in stream: consolidate harder, discourage opening bins.
    if progress > 0.8 {
        score += 50.0 * (1.0 - progress);
        if bin_residual == bin_capacity {
            score += 150.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
