pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.35 * progress * norm_pr) + 12.0 * norm_pr * norm_pr * (1.0 - progress);

    // Reward tight fits via smooth cubic decay of post residual
    score -= (1.0 - norm_pr).powi(3) * 8.0;

    // Last-chance bin bonus (smoothly scaled by progress)
    if fitting_bins_count == 1 {
        score -= 6.0 + 10.0 * progress;
    }

    // Lookahead: favor bins leaving room for the next item
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let slack = (pr - n) / cap;
            score -= 4.0 * (1.0 - slack * slack);
        } else {
            score += 3.0 * ((n - pr) / cap);
        }
    }

    // Mild penalty for spreading across many open bins, smoothed by progress
    score += 0.15 * (open_bins_count as f64).ln() * (0.5 + 0.5 * progress);

    // Mean residual alignment term (quadratic coupling)
    score += 0.05 * (mean_residual - pr) * (mean_residual - pr) / cap;

    // New-bin candidate: penalize opening a new bin unless residuals are tight
    if bin_residual == bin_capacity {
        score += 18.0 - 14.0 * progress + 0.1 * mean_residual;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lies in "usable"
    // residue classes (multiples of 10, small leftovers) are preferred.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Modulo-10 harmonic bonus: leftover divisible by 10 is reusable by
    // typical item sizes; penalize awkward residue classes.
    let m = post_residual % 10;
    score -= match m {
        0 => 8.0,
        1 | 9 => -3.0,
        2 | 8 => -1.5,
        3 | 7 => 0.5,
        4 | 6 => 1.5,
        _ => 2.5,
    } as f64;

    // Small leftover (dead space) penalty, nonlinear.
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - pr / 10.0);
    }

    // Lookahead coupling: does post_residual fit the next item exactly or well?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item cannot fit here: mild penalty scaled by overshoot class
            let over = (next_item_size - post_residual) % 20;
            score += 2.0 + over as f64 * 0.15;
        }
    }

    // Capacity fraction thresholds on residual: bins with residual in
    // [50, 100) are "half-full class" — keep them flexible.
    let frac = bin_residual as f64 / cap;
    if frac >= 0.5 {
        score -= 3.0;
    } else if frac < 0.2 {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize unless current bins are crowded or the
    // item is large and fits poorly anywhere.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < 25.0;
        let poor_fit = post_residual > 0 && post_residual < item_size / 2;
        if !crowded && !poor_fit {
            score += 30.0;
        } else {
            score += 6.0;
        }
        // Opening fresh bins late is cheap; early streams should consolidate.
        let t = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - t);
    }

    // Tie-break: prefer fuller bins (smaller mean_residual spread).
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = if pr >= item_size { (pr - item_size) as f64 } else { 0.0 };
    let remaining = total_items.saturating_sub(step_index);

    // Sharpened residual class ladder (tight-closure tuned, borrowed finer cut at 8/15/25)
    let class: f64 = if pr == 0 { -48.0 }
        else if pr <= 8 { -15.0 }
        else if pr <= 15 { -6.5 }
        else if pr <= 25 { -1.0 }
        else if pr <= 40 { 4.0 }
        else if pr <= 60 { 8.0 }
        else { 12.0 };
    score += class;

    // Reusability bonus
    let reusable = (pr % 10 == 0) as f64 * 4.0
        + (pr % 20 == 0) as f64 * 3.0
        + (pr % 25 == 0) as f64 * 2.0
        + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Dead residual just below item size — guaranteed waste
    if pr > 0 && pr < item_size.min(20) {
        score += 6.0;
    }

    // Lookahead coupling with next item.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 6.0; }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 45.0 { score += (slack - 45.0) * 0.05; }
            if slack <= 3.0 { score -= 1.0 * (1.0 - slack / 3.0); }
            if slack >= next_item_size as f64 { score -= 2.5; }
        } else {
            let gap = (next_item_size - pr) as f64;
            let soft = if pr <= 10 { 0.5 } else { 1.0 };
            score += (5.0 + gap * 0.09) * soft;
            if gap <= 4.0 && pr > 0 { score += (4.0 - gap) * 0.9; }
        }
        if item_size.saturating_add(next_item_size) == pr { score -= 6.0; }
        let triple = item_size.saturating_add(next_item_size * 2);
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        let quad = item_size.saturating_add(next_item_size * 3);
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        if pr >= next_item_size * 2 {
            let d2 = pr - next_item_size * 2;
            if d2 <= 3 { score -= 2.0 - d2 as f64 * 0.5; }
        }
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 { score += (gap as f64 - 25.0) * 0.08; }
            if gap >= 15 && gap <= 25 && mean_residual > 22.0 {
                score += (gap as f64 - 15.0) * 0.10;
            }
        }
        if pr > 0 && pr % next_item_size == 0 { score -= 1.5; }
        if pr > 0 && pr < next_item_size && pr < item_size.min(next_item_size) {
            score += 1.5 + (next_item_size - pr) as f64 * 0.05;
        }
        // reward bins whose residual is a near-exact sum of next item and a small filler
        if pr >= next_item_size {
            let rem = pr - next_item_size;
            if rem > 0 && rem <= item_size.min(8) { score -= 2.0 - rem as f64 * 0.2; }
        }
        // gen 50: reward bins where frag splits into next item plus a tiny remainder (two-step chain)
        if pr >= item_size {
            let f = pr - item_size;
            if f > next_item_size {
                let rem = f - next_item_size;
                if rem <= 2 { score -= 2.2 - rem as f64 * 0.6; }
            }
            // gen 50: penalize frag just barely too small for next item (guaranteed dead space)
            if f > 0 && f < next_item_size && next_item_size - f <= 4 {
                score += (next_item_size - f) as f64 * 0.9;
            }
        }
        // gen 50: reward bins whose frag lands within 3 of next item (near-exact chain next step)
        if pr >= item_size {
            let f = pr - item_size;
            if f >= next_item_size && f - next_item_size <= 3 {
                score -= 1.0 * (1.0 - (f - next_item_size) as f64 / 3.0);
            }
        }
        // gen 50: dead-space ratio refinement in the (next, 2*next) gap when absorption is scarce
        if pr >= item_size {
            let f = pr - item_size;
            if f > next_item_size as f64 && f < next_item_size as f64 * 2.0
                && mean_residual < 16.0 && remaining > 100 {
                score += (f - next_item_size as f64) * 0.08;
            }
        }
    }

    // Frag-based dead-space shaping
    if frag > 0.0 {
        if frag < item_size.min(15) as f64 { score += 4.0 + (15.0 - frag) * 0.15; }
        if next_item_size > 0 && (frag as u32) == next_item_size { score -= 4.5; }
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
        }
        if frag >= 20.0 && frag <= 35.0 && remaining > 80 && next_item_size > 0 && next_item_size < frag as u32 {
            score += (frag - 20.0) * 0.045;
        }
        let mr = mean_residual.max(1.0);
        if frag > mr * 1.5 && open_bins_count > 3 { score += (frag - mr * 1.5) * 0.06; }
        if next_item_size > 0 && frag as u32 > next_item_size * 2 && pr > 30 {
            score += (frag - next_item_size as f64) * 0.045;
        }
        if next_item_size > 0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 { score -= 2.2 - rem as f64 * 0.6; }
        }
        if next_item_size > 0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        if next_item_size > 0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        if next_item_size > 0 && frag as u32 % next_item_size == 0 && frag <= next_item_size as f64 * 3.0 {
            score -= 1.5;
        }
        if next_item_size > 0 && frag > next_item_size as f64 && frag < 30.0 && remaining > 60 {
            score += (frag - next_item_size as f64) * 0.05;
        }
        // dead-space ratio — penalize frag far above next item when stream is long
        if next_item_size > 0 && frag > next_item_size as f64 && remaining > 120 {
            score += (frag - next_item_size as f64) * 0.03;
        }
        // reward near-closing frag (tiny remainder)
        if frag <= 2.0 { score -= 3.0; }
        // penalize large frag that will likely never be filled
        if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }
        // exact-fill reward
        if frag == 0.0 { score -= 4.0; }
        // gen 50: reward frag exactly equal to next + item (perfect two-item chain next step)
        if next_item_size > 0 && frag as u32 == next_item_size + item_size.min(frag as u32) && frag as u32 > next_item_size {
            score -= 2.0;
        }
        // gen 50: reward bins whose post-residual can host next item twice with near-zero slack
        if next_item_size > 0 && frag as u32 >= next_item_size * 2 {
            let d2 = frag as u32 - next_item_size * 2;
            if d2 <= 3 { score -= 1.5 - d2 as f64 * 0.4; }
        }
    }

    // Scarcity pressure
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 6.0;
    } else if fitting_bins_count >= 5 {
        score += 2.0;
    }

    // Global residual context
    if mean_residual > 25.0 && pr > mean_residual as u32 {
        score += 3.0;
    } else if mean_residual < 12.0 && pr > 0 && pr <= item_size * 2 {
        score -= 2.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size <= bin_capacity && mean_residual > 20.0 { score += 1.5; }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && next_item_size > item_size && next_item_size - item_size <= 4 && remaining > 50 {
            score -= 2.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
        // resist new bin when an open bin can absorb item plus next item exactly
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size == bin_capacity { score += 3.0; }
        // open new bin in awkward mid dead zone on very long streams
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        // resist new bin late when open bins suffice
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
        // gen 50: resist new bin when mean residual closely matches next item (open bins will close cleanly)
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 2 && remaining > 80 { score += 2.5; }
        // gen 50: open new bin when all fitting bins would strand frag just under next item
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && item_size + next_item_size <= bin_capacity && mean_residual > 28.0 && remaining > 60 { score -= 1.8; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps harshly.
    // Anything below half the minimum item size is likely dead space.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 25.0;
    }

    // Penalize mid-range awkward residuals too (hard to fill later).
    if post_residual > 0 && post_residual < 30 {
        score += (30 - post_residual) as f64 * 2.0;
    }

    // Reward tight fits (small post_residual) with a bonus.
    if post_residual == 0 {
        score -= 40.0; // perfect fill is ideal
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open bins pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins count.
        score += 30.0 + (open_bins_count as f64) * 6.0;
        // But if this bin is the last chance and residual is tight, allow opening.
        if fitting_bins_count == 1 && (bin_residual as f64) - (item_size as f64) > 35.0 {
            score -= 20.0;
        }
    } else {
        // Favor using existing bins, more so as open_bins_count grows.
        score -= (open_bins_count as f64) * 1.5;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits comfortably in post_residual, reward.
    if next_item_size > 0 && (post_residual as f64) >= (next_item_size as f64) {
        score -= 10.0;
    } else if next_item_size > 0 && (post_residual as u32) < next_item_size {
        // Slight penalty if we strand the next item.
        score += 5.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Stream progression: later in the stream, be more conservative about
    // opening new bins and more aggressive about filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    } else {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
