pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize tiny dead space only if it is truly unusable for the lookahead item.
    if next_item_size > 0 {
        if post_residual > 0 && post_residual < next_item_size {
            score += 15.0; // dead space for the next item
        } else if post_residual >= next_item_size {
            score -= 8.0; // leftover still useful for lookahead
        }
    } else {
        // Last item: minimize waste absolutely.
        score += 2.0 * post_residual as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current fit is bad.
    if bin_residual == bin_capacity {
        let good_fit = fit_ratio > 0.6 || (next_item_size > 0 && next_item_size >= post_residual && post_residual == 0);
        if good_fit && fitting_bins_count > 0 {
            score += 40.0; // discourage opening new bin when a decent fit exists
        } else if fit_ratio < 0.35 {
            score -= 20.0; // encourage fresh bin for very poor fits
        }
        // Mild penalty for proliferating bins over time.
        score += open_bins_count as f64 * 1.5;
    }

    // Time horizon: early in stream, be more willing to keep bins flexible;
    // late in stream, prioritize closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 5.0 * (bin_residual as f64 / bin_capacity as f64);
    score += progress * 3.0 * post_residual as f64 / bin_capacity as f64;

    // Global balance: prefer bins whose residual deviates favorably from the mean residual.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Prefer larger residual bins slightly when item is small (keeps big bins for big items).
    if item_size < 30 {
        score += 0.03 * (bin_capacity - bin_residual) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);

    // Residual class ladder: reward small post-residuals sharply.
    let class: f64 = if pr == 0 { -48.0 }
        else if pr <= 8 { -15.0 }
        else if pr <= 15 { -6.5 }
        else if pr <= 25 { -1.0 }
        else if pr <= 40 { 4.0 }
        else if pr <= 60 { 8.0 }
        else { 12.0 };
    score += class;

    // Reward residuals on round boundaries (likely future perfect fills).
    let reusable = (pr % 10 == 0) as f64 * 4.0
        + (pr % 20 == 0) as f64 * 3.0
        + (pr % 25 == 0) as f64 * 2.0
        + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    let frag = pr.saturating_sub(item_size) as f64;

    // Next-item lookahead: reward bins that host next item cleanly.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 5.0; }
            if slack >= 1.0 && slack <= 12.0 { score -= 3.0 * (1.0 - slack / 12.0); }
            if slack > 45.0 { score += (slack - 45.0) * 0.05; }
        } else {
            score += 5.0 + (next_item_size - pr) as f64 * 0.09;
        }
    }

    // Two-step exact chain.
    if next_item_size > 0 && item_size + next_item_size == pr {
        score -= 6.0;
    }

    // Triple chain: item + next*2 near-exact.
    if next_item_size > 0 {
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
    }

    // Frag just below next item = guaranteed dead space.
    if next_item_size > 0 && frag > 0.0 && frag < next_item_size as f64 && (next_item_size as f64 - frag) <= 4.0 {
        score += (next_item_size as f64 - frag) * 0.9;
    }

    // Frag just above next item = near-exact chain.
    if next_item_size > 0 && frag > 0.0 && frag as u32 > next_item_size {
        let rem = frag as u32 - next_item_size;
        if rem <= 2 { score -= 2.2 - rem as f64 * 0.6; }
    }

    // Dead-space ratio in (next, 2*next) zone, sharper on long streams with low mean residual.
    if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 {
        score += (frag - next_item_size as f64) * 0.10;
        if mean_residual < 16.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
    }

    // Large frag that will likely never be filled.
    if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }

    // Tiny frag = near-closing bin.
    if frag > 0.0 && frag <= 2.0 { score -= 3.0; }

    // Post-residual exact multiple of next item (future perfect splits).
    if next_item_size > 0 && pr > 0 && pr % next_item_size == 0 { score -= 1.5; }

    // Open-bin pressure: prefer tighter packing when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Bias toward bins with larger residuals.
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Late-stream tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    // ---- NEW-BIN CANDIDATE LOGIC ----
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        score += 8.0 + crowding * 6.0 + (fitting_bins_count == 0) as i32 as f64 * 40.0;

        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;

        // Open eagerly when mean residual is high and stream is long (dead space accumulating).
        if mean_residual > 25.0 && remaining > 80 { score -= 2.0; }
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }

        // Prefer new bin for large items early (avoid fragmenting fresh bins late).
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }

        if fitting_bins_count > 0 { score += 4.0; }

        // Resist new bin when an open bin closes exactly on next item.
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 { score += 2.0; }

        // Resist new bin when item + next cannot cohabit anyway.
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }

        // Near stream end: resist new bin.
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }

        // Open new bin when mean residual closely matches next item (open bins will close cleanly).
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
    } else {
        // Non-new-bin calls: mild offset so new bins only win when clearly better.
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Core: non-linear cost of leftover space (superlinear waste penalty)
    let mut score = post.powf(1.4) / cap.powf(0.4);

    // Smooth coupling with stream progress: waste matters more later in stream
    score += post / cap * (0.5 + progress) * 10.0;

    // Reward tight fits: item filling most of residual
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill * fill * 8.0;

    // Penalize residuals that no plausible next item can use (dead space),
    // smoothly weighted by lookahead
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - post).abs();
        score += (1.0 - (gap / cap).min(1.0)) * 3.0;
        // Bonus if post_residual exactly accommodates next item
        if post_residual >= next_item_size {
            score -= 2.0 * (1.0 - ((post - next_item_size as f64) / cap));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0 * (1.0 - progress * 0.5);
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.15;

    // Mean-residual deviation: prefer bins with residual near mean (balanced packing)
    let dev = (post - mean_residual).abs();
    score += dev * 0.05;

    // New-bin candidate: smooth sigmoid-like gate — attractive early or when
    // this bin would leave very large post_residual
    if bin_residual == bin_capacity {
        let waste_gate = 1.0 / (1.0 + (-(post / cap - 0.35) * 10.0).exp());
        score += waste_gate * 20.0 - 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
