        // gen 51: dead-space ratio shaping — penalize frag in the (next, 2*next) half-open gap
        // more sharply when mean residual is low (few future absorption opportunities)
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0
            && mean_residual < 16.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
        // gen 51: reward chainable frag — frag equals next item plus a small filler item
        if next_item_size > 0 && frag > 0.0 && frag as u32 > next_item_size {
            let chain_rem = frag as u32 - next_item_size;
            if chain_rem <= 6 { score -= 1.8 * (1.0 - chain_rem as f64 / 6.0); }
        }
    }

    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 6.0;
    } else if fitting_bins_count >= 5 {
        score += 2.0;
    }

    if mean_residual > 25.0 && pr > mean_residual as u32 {
        score += 3.0;
    } else if mean_residual < 12.0 && pr > 0 && pr <= item_size * 2 {
        score -= 2.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size <= bin_capacity && mean_residual > 20.0 { score += 1.5; }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && next_item_size > item_size && next_item_size - item_size <= 4 && remaining > 50 {
            score -= 2.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size == bin_capacity { score += 3.0; }
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
        // gen 51: resist new bin when a fitting bin would close exactly on next item
        // (open bins will absorb cleanly; a fresh bin would strand capacity)
        if next_item_size > 0 && fitting_bins_count >= 2 && mean_residual >= next_item_size as f64 {
            score += 2.0;
        }
        // gen 51: open new bin eagerly when mean residual is high AND the only fits are loose
        // (dead space is accumulating; a fresh bin amortizes better on a long stream)
        if mean_residual > 28.0 && remaining > 60 && fitting_bins_count > 0
            && next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 1.8;
        }
        // gen 51: resist new bin late in the stream even with high mean residual (no time to amortize)
        if remaining < 30 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 2.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = if pr >= item_size { (pr - item_size) as f64 } else { 0.0 };
    let remaining = total_items.saturating_sub(step_index);

    // Residual class ladder (tight-closure tuned)
    let class: f64 = if pr == 0 { -48.0 }
        else if pr <= 6 { -17.0 }
        else if pr <= 12 { -8.0 }
        else if pr <= 20 { -2.5 }
        else if pr <= 32 { 2.0 }
        else if pr <= 50 { 6.5 }
        else if pr <= 70 { 10.0 }
        else { 14.0 };
    score += class;

    // Reusability bonus
    let reusable = (pr % 10 == 0) as f64 * 4.0
        + (pr % 20 == 0) as f64 * 3.0
        + (pr % 25 == 0) as f64 * 2.0
        + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Dead residual just below item size — guaranteed waste
    if pr > 0 && pr < item_size.min(20) {
        score += 6.0;
    }

    // Lookahead coupling with next item.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 6.0; }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 40.0 { score += (slack - 40.0) * 0.06; }
            if slack <= 3.0 { score -= 1.0 * (1.0 - slack / 3.0); }
            if slack >= next_item_size as f64 { score -= 2.5; }
        } else {
            let gap = (next_item_size - pr) as f64;
            let soft = if pr <= 10 { 0.5 } else { 1.0 };
            score += (5.0 + gap * 0.09) * soft;
            if gap <= 4.0 && pr > 0 { score += (4.0 - gap) * 0.9; }
        }
        if item_size.saturating_add(next_item_size) == pr { score -= 6.0; }
        let triple = item_size.saturating_add(next_item_size * 2);
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        let quad = item_size.saturating_add(next_item_size * 3);
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        if pr >= next_item_size * 2 {
            let d2 = pr - next_item_size * 2;
            if d2 <= 3 { score -= 2.0 - d2 as f64 * 0.5; }
        }
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 { score += (gap as f64 - 25.0) * 0.08; }
            if gap >= 15 && gap <= 25 && mean_residual > 22.0 {
                score += (gap as f64 - 15.0) * 0.10;
            }
        }
        if pr > 0 && pr % next_item_size == 0 { score -= 1.5; }
        if pr > 0 && pr < next_item_size && pr < item_size.min(next_item_size) {
            score += 1.5 + (next_item_size - pr) as f64 * 0.05;
        }
        // reward bins whose residual is a near-exact sum of next item and a small filler
        if pr >= next_item_size {
            let rem = pr - next_item_size;
            if rem > 0 && rem <= item_size.min(8) { score -= 2.0 - rem as f64 * 0.2; }
        }
        // gen 52: combine fine-grained residual fitting with lookahead — reward bins
        // whose residual splits cleanly into next item plus a small common-size chunk
        if pr >= next_item_size {
            let rem = pr - next_item_size;
            if rem > 0 && rem % 5 == 0 && rem <= 30 { score -= 1.2; }
        }
        // gen 52: penalize residual in the awkward (next, next+6) band when stream is long
        if pr > next_item_size && pr - next_item_size < 6 && remaining > 100 {
            score += (6 - (pr - next_item_size)) as f64 * 0.5;
        }
    }

    // Frag-based dead-space shaping
    if frag > 0.0 {
        if frag < item_size.min(15) as f64 { score += 4.0 + (15.0 - frag) * 0.15; }
        if next_item_size > 0 && (frag as u32) == next_item_size { score -= 4.5; }
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
        }
        if frag >= 20.0 && frag <= 35.0 && remaining > 80 && next_item_size > 0 && next_item_size < frag as u32 {
            score += (frag - 20.0) * 0.045;
        }
        let mr = mean_residual.max(1.0);
        if frag > mr * 1.5 && open_bins_count > 3 { score += (frag - mr * 1.5) * 0.06; }
        if next_item_size > 0 && frag as u32 > next_item_size * 2 && pr > 30 {
            score += (frag - next_item_size as f64) * 0.045;
        }
        if next_item_size > 0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 { score -= 2.2 - rem as f64 * 0.6; }
        }
        if next_item_size > 0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        if next_item_size > 0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        if next_item_size > 0 && frag as u32 % next_item_size == 0 && frag <= next_item_size as f64 * 3.0 {
            score -= 1.5;
        }
        if next_item_size > 0 && frag > next_item_size as f64 && frag < 30.0 && remaining > 60 {
            score += (frag - next_item_size as f64) * 0.05;
        }
        // dead-space ratio — penalize frag far above next item when stream is long
        if next_item_size > 0 && frag > next_item_size as f64 && remaining > 120 {
            score += (frag - next_item_size as f64) * 0.03;
        }
        // reward near-closing frag (tiny remainder)
        if frag <= 2.0 { score -= 3.0; }
        // penalize large frag that will likely never be filled
        if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }
        // exact-fill reward
        if frag == 0.0 { score -= 4.0; }
        // gen 52: dead-space ratio refinement — penalize frag in the half-open gap
        // (next, 2*next) more sharply when mean residual is low (few absorption chances)
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0
            && mean_residual < 16.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
        // gen 52: reward bins whose frag equals next + item (perfect two-item chain next step)
        if next_item_size > 0 && frag as u32 == next_item_size + item_size.min(frag as u32) && frag as u32 > next_item_size {
            score -= 2.0;
        }
    }

    // Scarcity pressure
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 6.0;
    } else if fitting_bins_count >= 5 {
        score += 2.0;
    }

    // Global residual context
    if mean_residual > 25.0 && pr > mean_residual as u32 {
        score += 3.0;
    } else if mean_residual < 12.0 && pr > 0 && pr <= item_size * 2 {
        score -= 2.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size <= bin_capacity && mean_residual > 20.0 { score += 1.5; }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && next_item_size > item_size && next_item_size - item_size <= 4 && remaining > 50 {
            score -= 2.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
        // resist new bin when an open bin can absorb item plus next item exactly
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size == bin_capacity { score += 3.0; }
        // open new bin in awkward mid dead zone on very long streams
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        // resist new bin late when open bins suffice
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
        // gen 52: resist new bin when mean residual closely matches next item (open bins close cleanly)
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 { score += 2.0; }
        // gen 52: open new bin when the only fitting bins would leave frag just under next item
        if next_item_size > 0 && fitting_bins_count > 0 && next_item_size > item_size
            && item_size + next_item_size <= bin_capacity && mean_residual > 28.0 && remaining > 60 {
            score -= 1.8;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: near-perfect packing gets a strong discount.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Harmonic class of the leftover: classify post_residual into residue
    // classes modulo 10 (capacity fraction classes). Small dead-space classes
    // are more reusable, large ones are penalized more.
    let cls = (post_residual % 10) as f64;
    let quot = (post_residual / 10) as f64;
    score += cls * 1.2 + quot * quot * 0.8;

    // If the next item could exactly consume this bin's post_residual,
    // strongly favor this bin (chained tight packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // Reward proportionally how well next item fills the leftover.
            let fill = next_item_size as f64 / (post_residual as f64 + 1.0);
            score -= 20.0 * fill;
        } else {
            // Next item won't fit here at all: leftover likely becomes waste
            // unless another bin absorbs it; slight penalty scaled by dead space.
            score += 0.05 * post_residual as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid forcing a
    // bad fit that creates large dead space; but reward decent fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual <= 20 {
            score -= 12.0;
        } else {
            score += 8.0;
        }
    }

    // New-bin candidate handling: an empty bin is attractive early in the
    // stream or when few bins are open, but should be discouraged when this
    // bin gives a tight fit (handled above via discounts).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress) - 0.3 * open_bins_count as f64;
        // If existing bins would leave big dead space, opening fresh is fine.
        if post_residual == cap && mean_residual > 30.0 {
            score -= 10.0;
        }
    }

    // Mild preference for bins below the mean residual (consolidate waste).
    score -= 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);

    // Banded residual quality (borrowed from best heuristic, re-tuned)
    let class: f64 = if pr == 0 { -50.0 }
        else if pr <= 8 { -16.0 }
        else if pr <= 15 { -6.0 }
        else if pr <= 25 { -1.0 }
        else if pr <= 40 { 4.0 }
        else if pr <= 60 { 8.0 }
        else { 12.0 };
    score += class;

    // Reward reusable residuals (multiples of common item sizes)
    let reusable = (pr % 10 == 0) as f64 * 4.0
        + (pr % 20 == 0) as f64 * 3.0
        + (pr % 25 == 0) as f64 * 2.0
        + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    let frag = if pr >= item_size { (pr - item_size) as f64 } else { 0.0 };

    // Two-step lookahead: exact chain item + next
    if next_item_size > 0 && item_size + next_item_size == pr {
        score -= 6.0;
    }
    // Near-exact chain: frag within 3 of next item
    if next_item_size > 0 && frag > 0.0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
        score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
    }
    // Triple chain: item + next*2 near-exact
    if next_item_size > 0 {
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 8 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 8.0);
        }
    }
    // Penalize frag just below next item (guaranteed dead space next step)
    if next_item_size > 0 && frag > 0.0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
        score += (next_item_size - frag as u32) as f64 * 0.9;
    }
    // Dead-zone penalty in 25..45 gap after next item fits
    if next_item_size > 0 && pr >= next_item_size {
        let gap = pr - next_item_size;
        if gap > 25 && gap < 45 {
            score += (gap as f64 - 25.0) * 0.08;
        }
    }
    // Penalize frag in (next, 2*next) dead zone, stronger on long streams
    if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 {
        let base = 0.08;
        let scale = if remaining > 100 && mean_residual < 16.0 { base * 1.5 } else { base };
        if frag > 8.0 { score += (frag - next_item_size as f64) * scale; }
    }
    // Reward residual divisible by next item (future perfect splits)
    if next_item_size > 0 && pr > 0 && pr % next_item_size == 0 {
        score -= 1.5;
    }
    // Large frag that will likely never fill
    if frag > 40.0 && remaining > 60 {
        score += (frag - 40.0) * 0.05;
    }
    // Tiny frag near-closing bonus
    if frag > 0.0 && frag <= 2.0 {
        score -= 3.0;
    }
    // Mean residual coupling: prefer tighter bins
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        if fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 {
            score += 3.0;
        }
        // Open new bin when mean residual is high (dead space accumulating)
        if mean_residual > 30.0 && remaining > 100 {
            score -= 2.0;
        }
        // Prefer new bin for large items when mean residual is mid-range
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 {
            score -= 3.0;
        }
        // Open new bin when item + next can't share a bin anyway
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 4.0;
        }
        // Resist new bin when stream is nearly over
        if remaining < 8 && fitting_bins_count > 0 {
            score += 5.0;
        }
        // Resist new bin when many open bins can absorb next item
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
        // Prefer new bin for very large items early in stream
        if item_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        // Resist new bin when stream ends soon even if mean residual is high
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 4.0;
        }
        // Open new bin when mean residual sits in the awkward 12..20 dead zone
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 {
            score -= 1.5;
        }
        // Resist new bin when mean residual closely matches next item
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
    } else {
        // Existing bin: mild pressure to consolidate
        score -= (open_bins_count as f64).min(8.0) * 0.5;
        // Last-chance bonus
        if fitting_bins_count == 1 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits (small post_residual), but with a dead-space twist.
    let pr = post_residual as f64;
    score += pr * 0.6;

    // Strict dead-space avoidance: residuals that are tiny (unusable gaps)
    // are heavily penalized. A gap < 1 is impossible; gaps < ~10 (min item)
    // are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - pr / 10.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    } else {
        // Usable gap: mild reward proportional to how well next item might use it.
        score -= 3.0;
    }

    // Coupling: if the lookahead item fits exactly into the post_residual,
    // this is a chained perfect fill — big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    } else if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        // Partial chain usability: small bonus.
        score -= 6.0 * (next_item_size as f64 / pr);
    }

    // Dead-space coupling with lookahead: if post_residual is a dead gap
    // AND next item can't use it, penalize harder.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Open bins pressure: discourage scattering across many bins when
    // the fit is mediocre; encourage using existing bins when few are open.
    let open_pressure = (open_bins_count as f64).powf(1.3) * 0.5;
    score += open_pressure * (pr / bin_capacity as f64);

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is only attractive when this bin would leave a
    // large dead gap or the item is huge relative to residual.
    if bin_residual == bin_capacity {
        // Mild default preference for existing bins: empty bin gets a
        // moderate score that tight fits can beat.
        score += 15.0;
        // But if the item is large (hard to place later), opening fresh
        // space is reasonable.
        if item_size > bin_capacity * 3 / 4 {
            score -= 20.0;
        }
    }

    // Stream progression: early in the stream, be slightly more willing
    // to open bins (flexibility); late in the stream, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 2.0 - progress * 2.0;

    // Mean residual alignment: prefer bins whose residual is near the mean
    // (balanced packing) when the fit is loose.
    if pr > 10.0 {
        let dev = (pr - mean_residual).abs();
        score += dev * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
