        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size <= bin_capacity && mean_residual > 20.0 { score += 1.5; }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && next_item_size > item_size && next_item_size - item_size <= 4 && remaining > 50 {
            score -= 2.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
        // resist new bin when an open bin can absorb item plus next item exactly
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size == bin_capacity { score += 3.0; }
        // open new bin in awkward mid dead zone on very long streams
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        // resist new bin late when open bins suffice
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
        // gen 52: resist new bin when mean residual matches next item closely (open bins close cleanly)
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size
            && (mean_residual as u32) - next_item_size <= 2 && remaining > 60 { score += 2.0; }
        // gen 52: open new bin when mean residual is high and many open bins cannot fit this item
        if mean_residual > 28.0 && remaining > 80 && fitting_bins_count > 0
            && open_bins_count.saturating_sub(fitting_bins_count) >= 3 { score -= 2.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit reward: strong bonus for leaving nothing behind.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post-residual, this placement is perfect (chain fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            // Next item fits, but leftover after it matters: penalize by the
            // double-lookahead dead space.
            let post2 = post_residual - next_item_size;
            score += post2 as f64 * 0.35;
        } else {
            // Dead space: next item cannot use the leftover. Penalize
            // proportionally to how unusable the residual is.
            score += (next_item_size - post_residual) as f64 * 0.6;
        }
    }

    // Relative-to-mean coupling: bins with residual below the mean are the
    // "scrap" bins — prefer filling those to consolidate space.
    let residual_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += (mean_residual - residual_f) * 0.25;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when open bins exist that fit well:
    // the empty-bin candidate gets a mild penalty unless its score is
    // otherwise excellent (large item relative to capacity).
    if bin_residual == bin_capacity {
        score += 15.0 - 20.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Stream progression: late in the stream, be more conservative —
    // tighten bins harder to avoid end-of-stream waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    // Slight preference for bins that already hold material (fragmentation
    // avoidance): larger item relative to residual is a good fill ratio.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 8.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
