        if next_item_size > 0 && fitting_bins_count > 0 && next_item_size > item_size && remaining > 50 && mean_residual > 20.0 { score -= 1.2; }
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
