        score += 3.0; // dead space risk for lookahead
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Penalize high fragmentation relative to mean residual.
    if (post_residual as f64) > mean_residual + 20.0 {
        score += 6.0;
    } else if (post_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // New-bin candidate scoring: baseline penalty that shrinks as stream progresses
    // and when open bins are scarce relative to load.
    if is_new_bin {
        let open_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 30.0 - 15.0 * progress - 4.0 * open_pressure;
        // Large items justify fresh bins; small items should fill existing ones.
        score += 0.15 * (item_size as f64 - 50.0);
    }

    // Late in stream: consolidate, prefer existing bins even more.
    if progress > 0.8 && !is_new_bin {
        score -= 5.0;
    }

    // Mild penalty for leaving residuals that are hard-to-fill windows (1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);

    // Residual class ladder: reward tight, penalize awkward mid-range gaps.
    let class: f64 = if pr == 0 { -48.0 }
        else if pr <= 8 { -15.0 }
        else if pr <= 15 { -6.5 }
        else if pr <= 25 { -1.0 }
        else if pr <= 40 { 4.0 }
        else if pr <= 60 { 8.0 }
        else { 12.0 };
    score += class;

    // Reusability of residual (divisible residuals are easier to fill later).
    let reusable = (pr % 10 == 0) as f64 * 4.0
        + (pr % 20 == 0) as f64 * 3.0
        + (pr % 25 == 0) as f64 * 2.0
        + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Dead-space trap: residual just below next item is guaranteed waste.
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        score += 1.5 + (next_item_size - pr) as f64 * 0.05;
    }

    // Lookahead: next item fits with small slack -> strong reward.
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 7.0 + 10.0 / (1.0 + slack);
        if slack == 0.0 { score -= 5.0; }
        if slack >= 1.0 && slack <= 12.0 { score -= 3.0 * (1.0 - slack / 12.0); }
        if slack > 45.0 { score += (slack - 45.0) * 0.05; }
    } else if next_item_size > 0 {
        score += 5.0 + (next_item_size - pr) as f64 * 0.09;
    }

    // Fragmentation analysis on frag = pr - item_size.
    let fits = pr >= item_size;
    if fits {
        let frag = (pr - item_size) as f64;
        if frag > 0.0 && frag < item_size.min(15) as f64 {
            score += 4.0 + (15.0 - frag) * 0.15;
        }
        if frag == 0.0 { score -= 4.0; }
        if next_item_size > 0 && (frag as u32) == next_item_size { score -= 4.5; }
        // Two-step chain: item then next item exactly fills bin.
        if next_item_size > 0 && item_size + next_item_size == pr { score -= 6.0; }
        // Triple chain near-exact.
        if next_item_size > 0 {
            let triple = item_size + next_item_size * 2;
            if pr >= triple && pr - triple <= 10 {
                score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
            }
        }
        // Awkward gap after next item fits (13..25 dead zone).
        if next_item_size > 0 && pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 { score += (gap as f64 - 25.0) * 0.08; }
            if gap >= 15 && gap <= 25 && mean_residual > 22.0 { score += (gap as f64 - 15.0) * 0.10; }
        }
        // Frag in (next, 2*next) zone: dead space ahead, penalize on long streams.
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
            if mean_residual < 16.0 && remaining > 100 { score += (frag - next_item_size as f64) * 0.08; }
        }
        // Frag just barely too small for next item: guaranteed dead space.
        if next_item_size > 0 && frag > 0.0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        // Near-perfect two-step chain: frag = next + tiny remainder.
        if next_item_size > 0 && frag > 0.0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 { score -= 2.2 - rem as f64 * 0.6; }
        }
        // Large frag that will likely never be filled.
        if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }
        // Residual a small multiple of next item: perfect future splits.
        if next_item_size > 0 && frag > 0.0 && frag as u32 % next_item_size.max(1) == 0 && frag <= 30.0 { score -= 2.0; }
        if next_item_size > 0 && pr > 0 && pr % next_item_size == 0 { score -= 1.5; }
        // Mean-residual coupling: over-tight frag vs mean residual on many open bins.
        let mr = mean_residual.max(1.0);
        if frag > 0.0 && frag > mr * 1.5 && open_bins_count > 3 { score += (frag - mr * 1.5) * 0.06; }
        // Quad chain.
        if next_item_size > 0 {
            let quad = item_size + next_item_size * 3;
            if pr >= quad && pr - quad <= 6 { score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0); }
        }
        // Two next-items with near-zero slack.
        if next_item_size > 0 && pr >= next_item_size * 2 {
            let d2 = pr - next_item_size * 2;
            if d2 <= 3 { score -= 2.0 - d2 as f64 * 0.5; }
        }
    }

    // Mean residual coupling: prefer tighter bins.
    if (bin_residual as f64) < mean_residual { score -= 3.0; } else { score += 2.0; }

    // Stream progression pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity { score -= progress * 5.0; }

    // ---- New-bin candidate logic (adaptive) ----
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 { score += 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        // Gen 53 mutation: open new bin when all fitting bins would strand frag just under next item.
        if next_item_size > 0 && fitting_bins_count > 0 && next_item_size > item_size && remaining > 50 && mean_residual > 20.0 { score -= 1.2; }
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
        // Gen 53: resist new bin when an open bin closes exactly on the pair (item + next).
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size <= bin_capacity && remaining < 60 { score += 2.5; }
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic penalty on post_residual (dead space), scaled by progress
    let mut score = pr * (1.0 + 2.5 * progress) + 40.0 * norm_pr * norm_pr;

    // Cubic coupling: large residuals are worse late in the stream
    score += 60.0 * norm_pr * norm_pr * norm_pr * progress;

    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let tightness = 1.0 - (pr - nxt) / cap;
            score -= 25.0 * tightness * tightness;
        } else {
            // next item won't fit here; slight penalty for stranding capacity
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Open-bin pressure: when many bins are open, discourage spreading
    score += 3.0 * open_bins_count as f64 * norm_pr;

    // Mean residual deviation: prefer bins with residual near mean (balanced packing)
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // Smooth new-bin preference: an empty bin gets a mild progress-dependent bonus
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * progress;
    }

    // Tight fit reward: near-perfect fills strongly favored
    score -= 35.0 * (1.0 - norm_pr).powi(6);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual;
    let mut score = pr as f64;

    // Residual class shaping: reward near-closures, penalize awkward mid gaps.
    let class: f64 = if pr == 0 { -50.0 }
        else if pr <= 8 { -14.0 }
        else if pr <= 15 { -6.0 }
        else if pr <= 25 { -1.0 }
        else if pr <= 40 { 4.0 }
        else if pr <= 60 { 8.0 }
        else { 12.0 };
    score += class;

    let remaining = total_items.saturating_sub(step_index);
    let frag = pr.saturating_sub(item_size) as f64;

    // Divisibility rewards: residuals that future items can split perfectly.
    if pr > 0 && next_item_size > 0 {
        if pr % next_item_size == 0 { score -= 2.0; }
        if pr % 10 == 0 { score -= 2.0; }
        if pr % 5 == 0 { score -= 1.0; }
    }

    // Next-item fit coupling.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 5.0; }
            if slack >= 1.0 && slack <= 12.0 { score -= 3.0 * (1.0 - slack / 12.0); }
            if slack > 45.0 { score += (slack - 45.0) * 0.05; }
        } else {
            // Residual just below next item: guaranteed dead space next step.
            score += 5.0 + (next_item_size - pr) as f64 * 0.09;
        }
        // Two-item exact chain: item + next fills residual exactly.
        if item_size + next_item_size == pr { score -= 6.0; }
        // Triple chain with tiny slack.
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        // Double hosting of next item with near-zero slack.
        if pr >= next_item_size * 2 {
            let d2 = pr - next_item_size * 2;
            if d2 <= 3 { score -= 2.0 - d2 as f64 * 0.5; }
        }
        // Awkward gap (next, 2*next) — dead space by ratio, scaled by stream length.
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 {
            score += (frag - next_item_size as f64) * 0.09;
        }
        // Frag barely too small for next item.
        if frag > 0.0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        // Frag just above next item — near-exact chain next step.
        if frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        // Mid-range gap in 25..45 dead zone.
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 { score += (gap as f64 - 25.0) * 0.08; }
        }
    }

    // Tiny frag = near-closure, reward strongly.
    if frag > 0.0 && frag <= 2.0 { score -= 3.0; }

    // Large frag that will likely never fill, scaled by remaining stream.
    if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }

    // Dead-space ratio penalty scaled by mean residual context.
    if frag > 12.0 && remaining > 30 && mean_residual < 16.0 {
        score += (frag - 12.0) * 0.06;
    }

    // Open-bin pressure: tighter packing when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Bias toward larger residuals slightly.
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Late-stream tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr as f64 * 0.3 * progress;

    // NEW-BIN CANDIDATE logic.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        score += 8.0 + crowding * 6.0 + (fitting_bins_count == 0) as i32 as f64 * 40.0;

        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;

        // Open eagerly when mean residual is high (dead space accumulating).
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }

        // Prefer new bin for large items when mean residual is mid-range.
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }

        // Open new bin when no existing bin leaves room for next item after this one.
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }

        // Resist new bin when stream ends soon.
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }

        // Resist when many open bins can each absorb next item (avoid sprawl).
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
        // Resist when mean residual closely matches next item (bins will close cleanly).
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
        // Resist when some existing bin closes exactly on next item.
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 {
            score += 2.0;
        }
        if fitting_bins_count > 0 { score += 4.0; }
        // Open eagerly for big next items (fresh bin hosts them better).
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
    } else {
        score += 60.0;
    }

    score
}

