    let mut score = post_residual as f64;

    // Harmonic class of post_residual: partition residual space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1 fraction of capacity left

    // Harmonic class via integer division thresholds on post_residual.
    let class = post_residual / 25; // 0: near-full, 1: quarter, 2: half, 3: three-quarter, 4: empty
    match class {
        0 => score -= 40.0, // tiny dead space, excellent fill
        1 => score -= 18.0,
        2 => score -= 8.0,
        3 => score += 6.0,  // large residual wasted
