    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 2.0;
    }

    // Reward when next item exactly fits the post_residual (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; penalize proportionally to leftover fraction
            score += 10.0 * frac;
        }
    } else {
        // last item: just minimize residual
        score -= 30.0 * (1.0 - frac);
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 55.0 - 40.0 * frac; // base penalty; empty bin has frac=1 -> +15 net
