    }

    // Prefer bins below mean residual (tighter bins get filled first).
    score += (mean_residual - pr) * 0.3;

    // Slight preference for fewer open bins early in stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (1.0 - progress) * 0.5;

    score
}

