pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = (pr as i64 - item_size as i64).max(0) as f64;
    let remaining = total_items.saturating_sub(step_index);

    // Residual class ladder (borrowed from best-so-far, recalibrated)
    let class: f64 = if pr == 0 { -48.0 }
        else if pr <= 8 { -14.0 }
        else if pr <= 15 { -6.0 }
        else if pr <= 25 { -1.0 }
        else if pr <= 40 { 4.0 }
        else if pr <= 60 { 8.0 }
        else { 12.0 };
    score += class;

    // Reward residuals that are friendly multiples for future items
    let reusable = (pr % 10 == 0) as i32 as f64 * 4.0
        + (pr % 20 == 0) as i32 as f64 * 3.0
        + (pr % 25 == 0) as i32 as f64 * 2.0
        + (pr % 5 == 0) as i32 as f64 * 1.0;
    score -= reusable;

    // Next-item lookahead
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 5.0; }
            if slack >= 1.0 && slack <= 12.0 { score -= 3.0 * (1.0 - slack / 12.0); }
            if slack > 45.0 { score += (slack - 45.0) * 0.05; }
        } else {
            score += 5.0 + (next_item_size - pr) as f64 * 0.09;
        }
    }

    if pr > 0 && pr < item_size.min(20) { score += 6.0; }

    // Two-step chain: item then next fits exactly
    if next_item_size > 0 && item_size + next_item_size == pr { score -= 6.0; }

    // Near-exact chain next step
    if next_item_size > 0 && frag > 0.0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
        score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
    }

    // Barely-too-small for next item = guaranteed dead space
    if next_item_size > 0 && frag > 0.0 && frag < next_item_size as f64 && next_item_size as f64 - frag <= 4.0 {
        score += (next_item_size as f64 - frag) * 0.9;
    }

    // Triple chain lookahead
    if next_item_size > 0 {
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
    }

    // Dead-space ratio penalty in (next, 2*next) gap
    if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
        score += (frag - next_item_size as f64) * 0.10;
        if mean_residual < 16.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
    }

    // Awkward mid-zone frag scaled by remaining stream
    if next_item_size > 0 && frag > next_item_size as f64 && frag < 30.0 && remaining > 60 {
        score += (frag - next_item_size as f64) * 0.05;
    }

    // Large frag that will likely never fill
    if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }

    // Residual just below next item (dead space next step)
    if next_item_size > 0 && pr > 0 && pr < next_item_size && pr < item_size.min(next_item_size) {
        score += 1.5 + (next_item_size - pr) as f64 * 0.05;
    }

    // Open-bin pressure
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity { score -= 20.0; }

    // Bias toward larger residuals
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Late-stream tightening
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    // ---- NEW-BIN CANDIDATE LOGIC ----
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;

        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }

        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }

        if fitting_bins_count > 0 { score += 4.0; }

        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }

        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 { score += 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }

        // Open new bin when mean residual is high and few bins tightly fit
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && next_item_size > 0 && open_bins_count.saturating_sub(fitting_bins_count) > 2 {
            score -= 1.5;
        }

        // Resist new bin near stream end
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }

        // Open new bin when fitting bins would leave frag just under next item
        if next_item_size > 0 && fitting_bins_count > 0 && next_item_size > item_size
            && remaining > 50 && mean_residual > 20.0 { score -= 1.2; }

        // Resist new bin when mean residual closely matches next item
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size
            && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }

        // Awkward 12..20 mean residual dead zone on long streams
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }

        // Resist new bin when stream nearly over
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
    } else {
        // Not the new-bin candidate: mild penalty keeps new-bin competitive only when intended
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the next item (or the minimum plausible item) are wasted space.
    let min_item = if next_item_size > 0 { next_item_size.min(100) } else { 1 };
    if post_residual > 0 && post_residual < min_item {
        score += 60.0 * (1.0 - post_residual as f64 / min_item as f64);
    }

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits generally (small post_residual relative to capacity).
    score -= 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // If this bin is the last chance before opening a new bin, prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading items;
    // with few open bins, mildly encourage consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
    score += 0.05 * pressure * (1.0 - progress);

    // New-bin candidate: only attractive when residuals are fragmented
    // (high mean residual spread) or nothing fits well.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 15.0 - 0.1 * fragmentation;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score += 5.0; // keep new bin fresh for the lookahead item
        }
    }

    // Lookahead synergy: if the post residual exactly fits the next item, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    score
}

