        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && next_item_size > 0 && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && item_size + next_item_size <= bin_capacity && mean_residual > 28.0 && remaining > 60 { score -= 1.8; }
        if next_item_size > 0 && mean_residual as u32 >= next_item_size
            && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        if next_item_size > 0 && fitting_bins_count > 0 && next_item_size > item_size
            && remaining > 50 && mean_residual > 20.0 { score -= 1.2; }
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
        // gen 54: open a new bin when every fitting bin would strand a tiny dead residual
        if fitting_bins_count > 0 && next_item_size > 0 && remaining > 40 {
            let all_bad = true; // heuristic pressure only
            if all_bad && mean_residual < 10.0 { score -= 1.0; }
        }
    } else {
        score += 60.0;
    }

    // Late-stream tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate: make it unattractive unless it is genuinely the best option.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 40.0 + open_bins_count as f64 * 2.0;
        // If no open bin fits, opening a new bin is the only real choice:
        // still score it by wasted space, but drop the penalty.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Aggressive 2-step lookahead: perfect follow-up match is highly desirable.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 35.0; // exact 2-step chain: item + next item fill bin perfectly
        } else if post_residual >= next_item_size {
            // next item fits after this placement: mild reward proportional to tightness
            let tightness = 1.0 - ((post_residual as f64 - nxt) / bin_capacity as f64);
            score -= 10.0 * tightness;
        } else {
            // next item won't fit here afterward: penalize by the shortfall
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Reward using bins that are already fragmented (residual below mean) to
    // consolidate dead space; penalize draining the best bins.
    if !is_new_bin {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor filling the only bin that can host the item.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Penalize tiny unusable leftovers less when stream is near its end.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual < 10 {
        score -= 5.0 * progress;
    }

    // Prefer placing into bins with small residual overall (best-fit bias).
    score += 0.2 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = if pr >= item_size { (pr - item_size) as f64 } else { 0.0 };
    let remaining = total_items.saturating_sub(step_index);

    // Residual class ladder (tightened mid bands per momentum combine)
    let class: f64 = if pr == 0 { -48.0 }
        else if pr <= 5 { -18.0 }
        else if pr <= 10 { -9.0 }
        else if pr <= 18 { -2.5 }
        else if pr <= 30 { 2.0 }
        else if pr <= 48 { 6.5 }
        else if pr <= 70 { 10.0 }
        else { 14.0 };
    score += class;

    // Reusability bonus
    let reusable = (pr % 10 == 0) as f64 * 4.0
        + (pr % 20 == 0) as f64 * 3.0
        + (pr % 25 == 0) as f64 * 2.0
        + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Dead residual just below item size — guaranteed waste
    if pr > 0 && pr < item_size.min(20) {
        score += 6.0;
    }

    // Lookahead coupling with next item.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 6.0; }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 40.0 { score += (slack - 40.0) * 0.06; }
            if slack <= 3.0 { score -= 1.0 * (1.0 - slack / 3.0); }
            if slack >= next_item_size as f64 { score -= 2.5; }
        } else {
            let gap = (next_item_size - pr) as f64;
            let soft = if pr <= 10 { 0.5 } else { 1.0 };
            score += (5.0 + gap * 0.09) * soft;
            if gap <= 4.0 && pr > 0 { score += (4.0 - gap) * 0.9; }
        }
        if item_size.saturating_add(next_item_size) == pr { score -= 6.0; }
        let triple = item_size.saturating_add(next_item_size * 2);
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        let quad = item_size.saturating_add(next_item_size * 3);
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        if pr >= next_item_size * 2 {
            let d2 = pr - next_item_size * 2;
            if d2 <= 3 { score -= 2.0 - d2 as f64 * 0.5; }
        }
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 { score += (gap as f64 - 25.0) * 0.08; }
            if gap >= 15 && gap <= 25 && mean_residual > 22.0 {
                score += (gap as f64 - 15.0) * 0.10;
            }
        }
        if pr > 0 && pr % next_item_size == 0 { score -= 1.5; }
        if pr > 0 && pr < next_item_size && pr < item_size.min(next_item_size) {
            score += 1.5 + (next_item_size - pr) as f64 * 0.05;
        }
        // reward bins whose residual is a near-exact sum of next item and a small filler
        if pr >= next_item_size {
            let rem = pr - next_item_size;
            if rem > 0 && rem <= item_size.min(8) { score -= 2.0 - rem as f64 * 0.2; }
        }
        // gen 54: fine-grained coupling — reward residual within 1 of next item (near-certain close)
        if pr == next_item_size + 1 { score -= 1.2; }
        // gen 54: penalize residual that is exactly 1 below next item (worst dead space)
        if pr + 1 == next_item_size { score += 2.0; }
    }

    // Frag-based dead-space shaping
    if frag > 0.0 {
        if frag < item_size.min(15) as f64 { score += 4.0 + (15.0 - frag) * 0.15; }
        if next_item_size > 0 && (frag as u32) == next_item_size { score -= 4.5; }
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
        }
        if frag >= 20.0 && frag <= 35.0 && remaining > 80 && next_item_size > 0 && next_item_size < frag as u32 {
            score += (frag - 20.0) * 0.045;
        }
        let mr = mean_residual.max(1.0);
        if frag > mr * 1.5 && open_bins_count > 3 { score += (frag - mr * 1.5) * 0.06; }
        if next_item_size > 0 && frag as u32 > next_item_size * 2 && pr > 30 {
            score += (frag - next_item_size as f64) * 0.045;
        }
        if next_item_size > 0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 { score -= 2.2 - rem as f64 * 0.6; }
        }
        if next_item_size > 0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        if next_item_size > 0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        if next_item_size > 0 && frag as u32 % next_item_size == 0 && frag <= next_item_size as f64 * 3.0 {
            score -= 1.5;
        }
        if next_item_size > 0 && frag > next_item_size as f64 && frag < 30.0 && remaining > 60 {
            score += (frag - next_item_size as f64) * 0.05;
        }
        // dead-space ratio — penalize frag far above next item when stream is long
        if next_item_size > 0 && frag > next_item_size as f64 && remaining > 120 {
            score += (frag - next_item_size as f64) * 0.03;
        }
        // reward near-closing frag (tiny remainder)
        if frag <= 2.0 { score -= 3.0; }
        // penalize large frag that will likely never be filled
        if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }
        // exact-fill reward
        if frag == 0.0 { score -= 4.0; }
        // gen 54: dead-space ratio refinement — sharper penalty in (next, 2*next) gap when mean residual is low and stream long
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0
            && mean_residual < 16.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
        // gen 54: reward bins whose frag equals next + item (perfect two-item chain next step)
        if next_item_size > 0 && frag as u32 == next_item_size + item_size.min(frag as u32) && frag as u32 > next_item_size {
            score -= 2.0;
        }
    }

    // Scarcity pressure
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 6.0;
    } else if fitting_bins_count >= 5 {
        score += 2.0;
    }

    // Global residual context
    if mean_residual > 25.0 && pr > mean_residual as u32 {
        score += 3.0;
    } else if mean_residual < 12.0 && pr > 0 && pr <= item_size * 2 {
        score -= 2.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size <= bin_capacity && mean_residual > 20.0 { score += 1.5; }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && next_item_size > item_size && next_item_size - item_size <= 4 && remaining > 50 {
            score -= 2.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
        // resist new bin when an open bin can absorb item plus next item exactly
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size == bin_capacity { score += 3.0; }
        // open new bin in awkward mid dead zone on very long streams
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        // resist new bin late when open bins suffice
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
        // gen 54: resist new bin when mean residual closely matches next item (open bins will close cleanly)
        if next_item_size > 0 && mean_residual >= next_item_size as f64
            && mean_residual - next_item_size as f64 <= 2.0 && fitting_bins_count >= 2 { score += 2.5; }
        // gen 54: prefer new bin for large items when all fitting bins would strand frag just under next item
        if next_item_size > 0 && fitting_bins_count > 0 && item_ratio > 0.5 && remaining > 60
            && mean_residual > 20.0 && (mean_residual as u32) < next_item_size { score -= 2.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: non-linear bonus when post_residual is small.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Penalize dead space that is too small for typical future items
    // (residuals below ~20 are hard to fill; waste grows as post_residual shrinks toward 0).
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 2.5;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's remainder: mild penalty scaled by waste.
            score += 4.0 * (1.0 - (post_residual as f64 / bin_capacity as f64));
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin should only win when all open
    // bins would leave bad fits. Penalize the empty-bin candidate progressively
    // as more bins are open, but relax late in the stream.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_pressure = (open_bins_count as f64).sqrt() * 3.0;
        let mean_waste = (mean_residual - item_size as f64).max(0.0);
        // If open bins are very full on average, opening a new bin is fine.
        let relief = (mean_residual / bin_capacity as f64).min(1.0) * 20.0;
        score += 15.0 + open_pressure - relief - progress * 8.0 - mean_waste * 0.1;
    }

    // Global state: many open bins with high mean residual -> encourage consolidation
    // into fuller bins (lower post_residual naturally does this, add a nudge).
    if open_bins_count > 3 {
        score += (mean_residual - post_residual as f64) * 0.05;
    }

    // Time horizon: early in the stream, be slightly conservative about creating
    // tiny remainders; late in the stream, squeeze hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (post_residual as f64 / bin_capacity as f64) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);

    // Residual class ladder (borrowed structure, retuned)
    let class: f64 = if pr == 0 { -55.0 } else if pr <= 6 { -18.0 } else if pr <= 12 { -8.0 } else if pr <= 20 { -2.0 } else if pr <= 35 { 3.0 } else if pr <= 55 { 8.0 } else { 13.0 };
    score += class;

    // Reward residuals that are clean multiples (likely future exact fits)
    if pr > 0 {
        if pr % 10 == 0 { score -= 4.0; }
        if pr % 20 == 0 { score -= 2.5; }
        if pr % 5 == 0 { score -= 1.0; }
        if next_item_size > 0 && pr % next_item_size.max(1) == 0 { score -= 2.0; }
    }

    // Next-item lookahead: exact fit is gold; near fit is good; just-barely-too-small is terrible
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 5.0; }
            if slack > 45.0 { score += (slack - 45.0) * 0.05; }
        } else {
            let deficit = (next_item_size - pr) as f64;
            if deficit <= 5.0 {
                score += 2.0 + deficit * 1.2; // guaranteed dead space next step
            } else {
                score += 4.0 + deficit * 0.08;
            }
        }
        // two-step exact chain
        if item_size + next_item_size == pr { score -= 7.0; }
        // triple chain near-exact
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 8 { score -= 2.5 * (1.0 - (pr - triple) as f64 / 8.0); }
        // double next-item fit
        if pr >= next_item_size * 2 {
            let d2 = pr - next_item_size * 2;
            if d2 <= 3 { score -= 2.0 - d2 as f64 * 0.5; }
        }
    }

    // Fragment analysis
    if pr >= item_size {
        let frag = (pr - item_size) as f64;
        if frag == 0.0 {
            score -= 5.0;
        } else {
            // small awkward frag that next item can't use
            if frag < 4.0 && next_item_size > frag as u32 { score += 2.5; }
            // frag just under next item: dead space guaranteed
            if next_item_size > 0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
                score += (next_item_size - frag as u32) as f64 * 0.9;
            }
            // frag just above next item: good chain
            if next_item_size > 0 && frag >= next_item_size as f64 {
                let chain = frag as u32 - next_item_size;
                if chain <= 6 { score -= 1.8 * (1.0 - chain as f64 / 6.0); }
                if chain == 0 { score -= 4.5; }
            }
            // mid-range frag in (next, 2*next): awkward, penalize more on long streams
            if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 && remaining > 60 {
                score += (frag - next_item_size as f64) * 0.08;
            }
            // large frag that will likely never fill
            if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }
            // frag in dead zone 20..35 on long streams
            if frag >= 20.0 && frag <= 35.0 && remaining > 80 && next_item_size > 0 && next_item_size < frag as u32 {
                score += (frag - 20.0) * 0.045;
            }
            // frag exceeding mean residual: waste relative to typical absorption
            if frag > mean_residual * 1.5 && open_bins_count > 3 { score += (frag - mean_residual * 1.5) * 0.06; }
        }
    }

    // Open-bin pressure and last-chance bin
    score += open_bins_count as f64 * 0.25;
    if fitting_bins_count == 1 && bin_residual < bin_capacity { score -= 22.0; }
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    // Progress-scaled tightening
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr as f64 * 0.25 * progress;

    // ===== NEW-BIN CANDIDATE LOGIC =====
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        score += 8.0 + (fitting_bins_count == 0) as i32 as f64 * 45.0;

        // resist new bin when stream nearly over
        if remaining < 10 && fitting_bins_count > 0 { score += 6.0; }

        // open eagerly for large items early (don't fragment fresh bins late)
        if item_ratio > 0.7 && remaining > 30 { score -= 2.5 * item_ratio; }

        // high mean residual on long stream = dead space accumulating; open fresh bin
        if mean_residual > 25.0 && remaining > 80 { score -= 2.0; }

        // resist new bin when open bins can absorb next item cleanly
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 && remaining < 60 { score += 3.0; }

        // open new bin when item + next won't share a bin anyway
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }

        // resist new bin if mean residual closely matches next item (bins will close cleanly)
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }

        // low mean residual = tight packing works; avoid sprawl
        if mean_residual < 12.0 && remaining > 50 && fitting_bins_count > 0 { score += 3.0; }
    } else {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.18;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Reward tight fits more strongly as the stream progresses
    score -= 12.0 * (1.0 - pr_norm).powf(2.0) * (0.5 + progress);

    // Penalize leaving residuals that match neither the next item nor typical sizes
    let next_fit_penalty = if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs() / cap;
        8.0 * (1.0 - diff).powf(3.0)
    } else {
        0.0
    };
    score += next_fit_penalty;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize mildly early, more when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress;
    }

    // Penalize deviation from mean residual to balance load across bins
    score += 0.3 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.84;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual, but with harmonic (fractional) shaping.
    let frac = post_residual as f64 / cap;
    score += 12.0 * (frac * std::f64::consts::PI).sin().abs();

    // Harmonic classes of post_residual via modulo arithmetic:
    // residuals divisible by large chunk sizes are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else {
        if pr % 50 == 0 { score -= 18.0; }
        else if pr % 25 == 0 { score -= 12.0; }
        else if pr % 10 == 0 { score -= 8.0; }
        else if pr % 5 == 0 { score -= 4.0; }
        // integer-division thresholds: dead-space classes
        let dead_class = pr / 10; // 0..10 class
        score += match dead_class {
            0 => 6.0,           // 1..9: nearly unusable sliver
            1 => 3.0,
            2 => 0.0,
            3 => -2.0,
            4 => -4.0,
            5 => -6.0,          // ~50: half bin, very reusable
            6 => -4.0,
            7 => -2.0,
            _ => 0.0,
        } as f64;
    }

    // Lookahead coupling: reward residuals that exactly or closely fit next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 { score -= 14.0 * (1.0 - slack as f64 / 10.0); }
            else { score -= 4.0 * (10.0 / slack as f64); }
        } else {
            // next item can't use leftover; penalize proportionally
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // last item: only perfect fit matters
        score += 5.0 * frac;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: opening a bin is expensive when many bins could fit.
    if bin_residual == bin_capacity {
        let open_cost = 60.0;
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (fitting_bins_count as f64) };
        // prefer new bin only when fit elsewhere is bad (large post_residual) or scarce fits
        let elsewhere_bad = if fitting_bins_count > 0 {
            (post_residual as f64 / cap).max(0.0)
        } else { 0.0 };
        score = open_cost * scarcity - 35.0 * elsewhere_bad
            + if next_item_size > 0 && next_item_size >= bin_residual { 10.0 } else { 0.0 };
        // late in stream, avoid proliferating bins
        score += 20.0 * (step_index as f64 / total_items.max(1) as f64);
        // many open bins with high mean residual: reuse them instead
        score += (open_bins_count as f64).ln() * 4.0 + (mean_residual / cap) * 15.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.3 - (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = if pr >= item_size { (pr - item_size) as f64 } else { 0.0 };
    let remaining = total_items.saturating_sub(step_index);

    // Residual class ladder (tightened from best lineage: sharper early tiers)
    let class: f64 = if pr == 0 { -48.0 }
        else if pr <= 8 { -16.0 }
        else if pr <= 15 { -7.5 }
        else if pr <= 25 { -1.5 }
        else if pr <= 40 { 3.5 }
        else if pr <= 60 { 7.5 }
        else { 12.5 };
    score += class;

    // Reusability bonus
    let reusable = (pr % 10 == 0) as f64 * 4.0
        + (pr % 20 == 0) as f64 * 3.0
        + (pr % 25 == 0) as f64 * 2.0
        + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Dead residual just below item size — guaranteed waste
    if pr > 0 && pr < item_size.min(20) {
        score += 6.0;
    }

    // Lookahead coupling with next item.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 5.0; }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 45.0 { score += (slack - 45.0) * 0.05; }
            if slack >= next_item_size as f64 { score -= 2.5; }
        } else {
            let gap = (next_item_size - pr) as f64;
            let soft = if pr <= 10 { 0.5 } else { 1.0 };
            score += (5.0 + gap * 0.09) * soft;
            if gap <= 4.0 && pr > 0 { score += (4.0 - gap) * 0.9; }
        }
        if item_size.saturating_add(next_item_size) == pr { score -= 6.0; }
        let triple = item_size.saturating_add(next_item_size * 2);
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        let quad = item_size.saturating_add(next_item_size * 3);
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        if pr >= next_item_size * 2 {
            let d2 = pr - next_item_size * 2;
            if d2 <= 3 { score -= 2.0 - d2 as f64 * 0.5; }
        }
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 { score += (gap as f64 - 25.0) * 0.08; }
            if gap >= 15 && gap <= 25 && mean_residual > 22.0 {
                score += (gap as f64 - 15.0) * 0.10;
            }
        }
        if pr > 0 && pr % next_item_size == 0 { score -= 1.5; }
        if pr > 0 && pr < next_item_size && pr < item_size.min(next_item_size) {
            score += 1.5 + (next_item_size - pr) as f64 * 0.05;
        }
        // reward bins whose residual is a near-exact sum of next item and a small filler
        if pr >= next_item_size {
            let rem = pr - next_item_size;
            if rem > 0 && rem <= item_size.min(8) { score -= 2.0 - rem as f64 * 0.2; }
        }
        // gen 55: chain bonus — tight fit for next item with few alternatives
        if next_item_size <= pr && (pr - next_item_size) as f64 <= 2.0 && fitting_bins_count <= 2 {
            score -= 3.0;
        }
    }

    // Frag-based dead-space shaping
    if frag > 0.0 {
        if frag < item_size.min(15) as f64 { score += 4.0 + (15.0 - frag) * 0.15; }
        if next_item_size > 0 && (frag as u32) == next_item_size { score -= 4.5; }
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
        }
        if frag >= 20.0 && frag <= 35.0 && remaining > 80 && next_item_size > 0 && next_item_size < frag as u32 {
            score += (frag - 20.0) * 0.045;
        }
        let mr = mean_residual.max(1.0);
        if frag > mr * 1.5 && open_bins_count > 3 { score += (frag - mr * 1.5) * 0.06; }
        if next_item_size > 0 && frag as u32 > next_item_size * 2 && pr > 30 {
            score += (frag - next_item_size as f64) * 0.045;
        }
        if next_item_size > 0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 { score -= 2.2 - rem as f64 * 0.6; }
        }
        if next_item_size > 0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        if next_item_size > 0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        if next_item_size > 0 && frag as u32 % next_item_size == 0 && frag <= next_item_size as f64 * 3.0 {
            score -= 1.5;
        }
        if next_item_size > 0 && frag > next_item_size as f64 && frag < 30.0 && remaining > 60 {
            score += (frag - next_item_size as f64) * 0.05;
        }
        // dead-space ratio — penalize frag far above next item when stream is long
        if next_item_size > 0 && frag > next_item_size as f64 && remaining > 120 {
            score += (frag - next_item_size as f64) * 0.03;
        }
        // gen 55: sharper dead-zone penalty in (next, 2*next) when mean residual is low
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0
            && mean_residual < 16.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
        // reward near-closing frag (tiny remainder)
        if frag <= 2.0 { score -= 3.0; }
        // penalize large frag that will likely never be filled
        if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }
        // exact-fill reward
        if frag == 0.0 { score -= 4.0; }
        // gen 55: dead-space ratio refinement — penalize frag that leaves little usable fraction
        if next_item_size > 0 && frag > 12.0 && remaining > 30 {
            let usable = next_item_size.min(frag as u32) as f64;
            let dead_ratio = 1.0 - usable / frag;
            if dead_ratio < 0.5 { score += (frag - 12.0) * 0.06 * (1.0 - dead_ratio); }
        }
    }

    // Scarcity pressure
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 6.0;
    } else if fitting_bins_count >= 5 {
        score += 2.0;
    }

    // Global residual context
    if mean_residual > 25.0 && pr > mean_residual as u32 {
        score += 3.0;
    } else if mean_residual < 12.0 && pr > 0 && pr <= item_size * 2 {
        score -= 2.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size <= bin_capacity && mean_residual > 20.0 { score += 1.5; }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && next_item_size > item_size && next_item_size - item_size <= 4 && remaining > 50 {
            score -= 2.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
        // resist new bin when an open bin can absorb item plus next item exactly
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size == bin_capacity { score += 3.0; }
        // open new bin in awkward mid dead zone on very long streams
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        // resist new bin late when open bins suffice
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
        // gen 55: resist new bin when several open bins can each absorb next item cleanly
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 { score += 2.0; }
        // gen 55: open new bin when the only fitting bins would leave frag just under next item
        if next_item_size > 0 && fitting_bins_count > 0 && next_item_size > item_size
            && remaining > 50 && mean_residual > 20.0 { score -= 1.2; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Small leftover gaps (< 10) are almost unusable: apply a steep nonlinear penalty.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual as i32) as f64 * 8.0;
    }
    // Exact fit is perfect: heavy reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin capacity (post_residual small fraction).
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // --- Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_gap = post_residual - next_item_size;
        if chain_gap < 10 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    }
    // Penalize if the next item would NOT fit here (this residual becomes dead space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 12.0;
    }

    // --- Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // --- Open-bin pressure: discourage spreading across many bins; more open bins
    // means new placements should prefer consolidation.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins whose residual is close to the mean residual (balanced packing),
    // penalize outliers creating fragmented residuals.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // --- New-bin candidate handling (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // Opening a new bin wastes capacity equal to bin_residual of an existing bin;
        // penalize unless the item is large and would leave a big gap elsewhere anyway.
        let progress = step_index as f64 / total_items.max(1) as f64;
        let new_bin_penalty = 45.0 - 20.0 * progress;
        // If no existing bin fits well (this call only happens for the candidate), the
        // large-item exception: big items leave large residuals anyway.
        if item_size > bin_capacity / 2 {
            score += new_bin_penalty * 0.4;
        } else {
            score += new_bin_penalty;
        }
        // Slight relief late in the stream when many bins are open anyway.
        score -= open_bins_count.min(10) as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual;
    let mut score = pr as f64;

    // Residual class ladder (borrowed and tightened from best-so-far).
    let class: f64 = if pr == 0 { -48.0 }
        else if pr <= 8 { -15.0 }
        else if pr <= 15 { -6.5 }
        else if pr <= 25 { -1.0 }
        else if pr <= 40 { 4.0 }
        else if pr <= 60 { 8.0 }
        else { 12.0 };
    score += class;

    // Reward residuals that are "round" and likely reusable.
    let reusable = (pr % 10 == 0) as f64 * 4.0
        + (pr % 20 == 0) as f64 * 3.0
        + (pr % 25 == 0) as f64 * 2.0
        + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    let remaining = total_items.saturating_sub(step_index);
    let frag = if pr >= item_size { (pr - item_size) as f64 } else { -1.0 };

    // Lookahead: chain with next item.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 5.0; }
            if slack >= 1.0 && slack <= 12.0 { score -= 3.0 * (1.0 - slack / 12.0); }
            if slack > 45.0 { score += (slack - 45.0) * 0.05; }
        } else {
            score += 5.0 + (next_item_size - pr) as f64 * 0.09;
        }
        // two-item exact chain
        if item_size + next_item_size == pr { score -= 6.0; }
        // triple chain near-exact
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 { score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0); }
        // quad chain near-exact
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 { score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0); }
        // residual divisible by next item (future perfect splits)
        if pr > 0 && pr % next_item_size == 0 { score -= 1.5; }
        // frag just below next item = guaranteed dead space
        if frag >= 0.0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        // frag in (next, 2*next) dead zone
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
            if mean_residual < 16.0 && remaining > 100 { score += (frag - next_item_size as f64) * 0.08; }
        }
        // gap in 25..45 awkward zone
        if pr as f64 >= next_item_size as f64 {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 { score += (gap as f64 - 25.0) * 0.08; }
        }
        // frag equals next item exactly
        if frag > 0.0 && (frag as u32) == next_item_size { score -= 4.5; }
        // small chain remainder
        if frag > 0.0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 { score -= 2.2 - rem as f64 * 0.6; }
        }
        // large frag never filled
        if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }
        // near-closing bins
        if frag > 0.0 && frag <= 2.0 { score -= 3.0; }
    }

    // Dead-space ratio penalty scaled by remaining stream.
    if frag > 12.0 && remaining > 30 && next_item_size > 0 {
        let usable = next_item_size.min(frag as u32) as f64;
        let dead_ratio = usable / frag.max(1.0);
        if dead_ratio < 0.5 { score += (frag - 12.0) * 0.06 * (1.0 - dead_ratio); }
    }

    // Mean residual coupling: prefer tighter bins.
    if (bin_residual as f64) < mean_residual { score -= 3.0; } else { score += 2.0; }

    // New-bin candidate logic.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        // open new bin when mean residual sits in awkward 12..20 zone on long stream
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        // open new bin for mid-size items when all fitting bins would strand dead space
        if next_item_size > 0 && fitting_bins_count > 0 && next_item_size > item_size && remaining > 50 && mean_residual > 20.0 { score -= 1.2; }
        // resist new bin when mean residual closely matches next item
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        // stream progression: late stream resists new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 8.0;
        // resist new bin when remaining is short and a fitting bin exists
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
    } else {
        // Favor existing bins, more so as open count grows.
        score -= (open_bins_count as f64) * 1.5;
        score -= progress_f(step_index, total_items) * 5.0;
        // Last-chance bonus.
        if fitting_bins_count == 1 { score -= 25.0; }
    }

    score
}

#[inline]
fn progress_f(step_index: usize, total_items: usize) -> f64 {
    step_index as f64 / total_items.max(1) as f64
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);

    // --- Post-residual class scoring (tight fits rewarded, awkward zones penalized) ---
    let class: f64 = if pr == 0 {
        -48.0
    } else if pr <= 8 {
        -15.0
    } else if pr <= 15 {
        -6.5
    } else if pr <= 25 {
        -1.0
    } else if pr <= 40 {
        4.0
    } else if pr <= 60 {
        8.0
    } else {
        12.0
    };
    score += class;

    // Reward residuals divisible by common item granularities (reusable shapes)
    let reusable = (pr % 10 == 0) as f64 * 4.0
        + (pr % 20 == 0) as f64 * 3.0
        + (pr % 25 == 0) as f64 * 2.0
        + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Penalize residuals just below the next item (guaranteed dead space next step)
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        score += 1.5 + (next_item_size - pr) as f64 * 0.9;
    }

    // Lookahead: next item fits comfortably in post_residual
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 {
                score -= 5.0;
            }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 45.0 {
                score += (slack - 45.0) * 0.05;
            }
        } else {
            score += 5.0 + (next_item_size - pr) as f64 * 0.09;
        }
    }

    // Two-step chain: exact fit of item + next in residual
    if next_item_size > 0 && item_size + next_item_size == pr {
        score -= 6.0;
    }

    // Triple-chain lookahead
    if next_item_size > 0 {
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
    }

    // Quad-chain lookahead
    if next_item_size > 0 {
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
    }

    // Dead-zone penalties in gap (next, 2*next)
    if next_item_size > 0 && pr >= next_item_size {
        let gap = pr - next_item_size;
        if gap > 25 && gap < 45 {
            score += (gap as f64 - 25.0) * 0.08;
        }
        if gap >= 15 && gap <= 25 && mean_residual > 22.0 {
            score += (gap as f64 - 15.0) * 0.10;
        }
    }

    // Penalize frag that neither fits next item nor closes soon
    if next_item_size > 0 && pr > 0 {
        let frag = (pr - item_size.min(pr)) as f64;
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
        }
        if frag > next_item_size as f64 && frag < 30.0 && remaining > 60 {
            score += (frag - next_item_size as f64) * 0.05;
        }
    }

    // Reward post-residual exact multiples of next item (future perfect splits)
    if next_item_size > 0 && pr > 0 && pr % next_item_size.max(1) == 0 {
        score -= 1.5;
    }

    // Mean residual coupling: prefer tighter bins
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // --- New-bin candidate logic (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;

        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        if fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 {
            score += 3.0;
        }
        if mean_residual > 30.0 && remaining > 100 {
            score -= 2.0;
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 {
            score += 2.0;
        }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 {
            score -= 3.0;
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 4.0;
        }
        if remaining < 8 && fitting_bins_count > 0 {
            score += 5.0;
        }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
        if item_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && next_item_size > 0 && open_bins_count.saturating_sub(fitting_bins_count) > 2 {
            score -= 1.5;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 4.0;
        }
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && item_size + next_item_size <= bin_capacity && mean_residual > 28.0 && remaining > 60 {
            score -= 1.8;
        }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size
            && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
        if next_item_size > 0 && fitting_bins_count > 0 && next_item_size > item_size
            && remaining > 50 && mean_residual > 20.0 {
            score -= 1.2;
        }
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 {
            score -= 1.5;
        }
        if remaining < 15 && fitting_bins_count > 0 {
            score += 3.0;
        }
    } else {
        // Existing bin: strong preference as open bins accumulate
        score -= (open_bins_count as f64) * 1.5;
        if fitting_bins_count == 1 {
            score -= 25.0;
        }
        // Stream progression: later, fill existing bins more aggressively
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer bins that become fuller (smaller post_residual is already rewarded).

    // --- Aggressive 2-step lookahead against the next item ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Perfect match: this bin absorbs the next item exactly.
            score -= 18.0;
        } else if next_item_size <= post_residual {
            // Next item also fits here: strong reward, scaled by how well it fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 - slack * 0.08;
        } else {
            // Next item will NOT fit in the leftover: penalize proportional dead space.
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.12;
        }
        // Small global lookahead pressure: late in the stream, consolidation matters more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 3.0;
    }

    // --- Tightness reward: bigger items into this bin are good ---
    score -= (item_size as f64 / bin_capacity as f64) * 6.0;

    // --- Relative fullness vs. mean residual across open bins ---
    // Prefer bins whose residual is already below the mean (fuller bins).
    score += (bin_residual as f64 - mean_residual) * 0.05;

    // --- Last-chance bin: if this is the only open bin that fits, use it ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // No open bin can fit the item: opening a new bin is mandatory.
            score -= 1000.0;
        } else {
            // Prefer existing bins in general...
            score += 30.0;
            // ...but if existing bins leave very poor leftovers while a fresh bin
            // would leave a clean residual for the next item, allow opening.
            if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
                score -= 20.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
