pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that is too small to ever be useful
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead: reward bins whose post_residual can hold the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.3 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // penalize wasting space the next item could have used
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // more competition: prefer bins with least residual waste
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: only prefer opening a new bin when
    // global residuals are fragmented or item is huge
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // base penalty for opening a new bin
        let mut new_bin_score = bin_capacity as f64 * 0.6;
        // cheaper to open new bins early in the stream
        new_bin_score -= 30.0 * (1.0 - progress);
        // expensive when many bins are already open and mean residual is high
        new_bin_score += 0.05 * open_bins_count as f64;
        new_bin_score += 0.4 * mean_residual;
        // if item is large, a fresh bin is attractive
        new_bin_score -= 0.2 * item_size as f64;
        // if next item is also large, fresh bin keeps room
        if next_item_size >= 50 {
            new_bin_score -= 15.0;
        }
        return new_bin_score;
    }

    // Prefer filling bins whose residual deviates favorably from mean
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Slight time-dependent exploration bonus
    score -= 3.0 * (progress * std::f64::consts::PI).sin();

    score
}

