        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size <= bin_capacity && mean_residual > 20.0 { score += 1.5; }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && next_item_size > item_size && next_item_size - item_size <= 4 && remaining > 50 {
            score -= 2.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
        // resist new bin when an open bin can absorb item plus next item exactly
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size == bin_capacity { score += 3.0; }
        // open new bin in awkward mid dead zone on very long streams
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        // resist new bin late when open bins suffice
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
        // gen 56: open new bin when the only fitting bins would leave frag just under next item (guaranteed dead space)
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && item_size + next_item_size <= bin_capacity && mean_residual > 28.0 && remaining > 60 {
            score -= 1.8;
        }
        // gen 56: resist new bin when mean residual closely matches next item (open bins will close cleanly)
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 {
            score += 2.0;
        }
        // gen 56: open new bin for mid-size items when all fitting bins would strand space relative to next item
        if next_item_size > 0 && fitting_bins_count > 0 && next_item_size > item_size && remaining > 50 && mean_residual > 20.0 {
            score -= 1.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual, with non-linear polynomial shaping
    let mut score = pr
        + 40.0 * norm_pr * norm_pr
        + 60.0 * norm_pr * norm_pr * norm_pr;

    // Smooth stream-progress coupling: late in the stream, dead space matters more
    let late = progress * progress;
    score += 25.0 * late * norm_pr;

    // Reward near-perfect fits smoothly
    let fit_quality = 1.0 - norm_pr;
    score -= 15.0 * fit_quality * fit_quality * fit_quality;

    // Last-chance bin: strong reward, modulated by progress
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * progress;
    }

    // Penalize crowding when many bins are open relative to mean residual
    let openness = open_bins_count as f64;
    score += 3.0 * (openness.ln() + 1.0) * (norm_pr - mean_residual / cap).abs();

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 12.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // New-bin candidate: mild penalty so it only wins when fits are truly bad
    if bin_residual == bin_capacity {
        score += 30.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = if pr >= item_size { (pr - item_size) as f64 } else { 0.0 };
    let remaining = total_items.saturating_sub(step_index);

    // Residual class ladder: reward small residuals, penalize large stranded ones.
    let class: f64 = if pr == 0 { -48.0 }
        else if pr <= 8 { -15.0 }
        else if pr <= 15 { -6.5 }
        else if pr <= 25 { -1.0 }
        else if pr <= 40 { 4.0 }
        else if pr <= 60 { 8.0 }
        else { 12.0 };
    score += class;

    // Reward residuals that are round numbers (likely reusable by common item sizes).
    let reusable = (pr % 10 == 0) as f64 * 4.0 + (pr % 20 == 0) as f64 * 3.0
        + (pr % 25 == 0) as f64 * 2.0 + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Next-item fit: reward bins that can host the next item, penalize near-misses.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 5.0; }
            if slack >= 1.0 && slack <= 12.0 { score -= 3.0 * (1.0 - slack / 12.0); }
            if slack > 45.0 { score += (slack - 45.0) * 0.05; }
        } else {
            // residual just below next item = guaranteed dead space next step
            score += 5.0 + (next_item_size - pr) as f64 * 0.09;
        }
    }

    // Two-item lookahead: exact chain item + next.
    if next_item_size > 0 && item_size + next_item_size == pr { score -= 6.0; }

    // Triple chain: item + 2*next with tiny slack.
    if next_item_size > 0 {
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
    }

    // Quad chain.
    if next_item_size > 0 {
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 { score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0); }
    }

    // Frag-based dead-space reasoning.
    if frag > 0.0 {
        // frag just barely too small for next item is worst case
        if next_item_size > 0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        // frag in (next, 2*next) gap = awkward leftover
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 {
            let mut p = (frag - next_item_size as f64) * 0.10;
            if mean_residual < 16.0 && remaining > 100 { p *= 1.6; }
            score += p;
        }
        // frag near-exact chain next step
        if next_item_size > 0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        // frag splits into next + tiny remainder
        if next_item_size > 0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 { score -= 2.2 - rem as f64 * 0.6; }
        }
        // frag divisible by next item = perfect future split
        if next_item_size > 0 && frag as u32 % next_item_size == 0 && frag <= next_item_size as f64 * 3.0 {
            score -= 1.5;
        }
        // large frag that will likely never be filled
        if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }
        // frag just above a small threshold with long stream left
        if next_item_size > 0 && frag > next_item_size as f64 && remaining > 120 {
            score += (frag - next_item_size as f64) * 0.03;
        }
        // tiny frag is nearly a close
        if frag <= 2.0 { score -= 3.0; }
        // frag exactly equals next + item
        if next_item_size > 0 && frag as u32 == next_item_size + item_size.min(frag as u32) && frag as u32 > next_item_size {
            score -= 2.0;
        }
    }

    // Open-bin pressure: prefer tighter packing when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Bias toward bins with larger residuals (better long-term hosts).
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr as f64 * 0.3 * progress;

    // ---- new-bin candidate logic ----
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 { score += 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && next_item_size > 0 && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size
            && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        if next_item_size > 0 && fitting_bins_count > 0 && next_item_size > item_size
            && remaining > 50 && mean_residual > 20.0 { score -= 1.2; }
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
        // gen 56: open a fresh bin when every fitting bin would strand frag just under next item
        if next_item_size > 0 && fitting_bins_count > 0 && frag > 0.0
            && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 && remaining > 60 {
            score -= 4.0;
        }
    } else {
        // Open-bin candidates get a mild baseline so new bins only win when justified.
        score += 60.0;
        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 { score -= 20.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: prefer post_residual in "useful" residue classes.
    // Items 1..100; leftover classes mod 10 capture typical size granularity.
    let pr = post_residual;
    let class = pr % 10;
    // Class 0 leftovers are perfectly reusable (pairs of 10s, 20s, etc.)
    match class {
        0 => score -= 25.0,
        5 => score -= 12.0,          // half-slots still quite usable
        1 | 2 | 3 | 4 => score -= 4.0, // small shims fit small items
        9 => score += 8.0,           // 1-unit dead space worst
        _ => score += 3.0,           // 6..8 awkward
    }

    // Integer-division thresholds on post_residual: big usable blocks get bonus.
    if pr >= 50 { score -= 15.0; }
    else if pr >= 30 { score -= 8.0; }
    else if pr >= 20 { score -= 4.0; }
    else if pr < 10 && pr > 0 { score += 10.0; }

    // Perfect fit: zero waste is ideal.
    if pr == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: does this bin's post_residual admit the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // next item fits here afterwards -> strong chain bonus
            score -= 10.0 + (pr - next_item_size) as f64 * 0.3;
            // harmonic bonus if post_residual is an exact multiple of next size class
            if next_item_size >= 10 && pr % next_item_size.max(1) == 0 {
                score -= 6.0;
            }
        } else {
            // leftover dead relative to lookahead
            score += (next_item_size - pr) as f64 * 0.2;
        }
    }

    // Last-chance bin: if only one open bin fits, strongly prefer using it
    // over opening a new bin (unless post_residual waste is huge).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate (empty bin): penalize so we only open when open bins fit badly.
    if bin_residual == bin_capacity {
        score += 45.0;
        // open a fresh bin early in the stream to build capacity reserve
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // if many open bins but item fits none well, fresh bin is fine
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Prefer tighter bins: closeness of item to residual (good fill ratio).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill;

    // Spread pressure: if mean residual is high, reuse bins rather than opening new.
    score += (mean_residual - pr as f64) * 0.15;

    // Many open bins: discourage spreading, favor consolidation into tight fits.
    score += open_bins_count as f64 * 0.4 * (1.0 - fill);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = pr as f64 - item_size as f64; // residual left after placing item
    let remaining = total_items.saturating_sub(step_index);

    // Dead-space avoidance: small unusable gaps heavily penalized.
    if pr > 0 && pr < 10 {
        score += 60.0;
    } else if pr < 25 {
        score += 25.0 * (1.0 - pr as f64 / 25.0);
    }

    // Reward near-perfect fills.
    if pr == 0 {
        score -= 60.0;
    }

    // Reusability bonus: residuals that are round multiples are easier to fill later.
    let reusable = (pr % 10 == 0) as f64 * 4.0 + (pr % 20 == 0) as f64 * 3.0 + (pr % 25 == 0) as f64 * 2.0 + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Lookahead: dead space worse if next item cannot use the post-residual.
    if next_item_size > 0 {
        if next_item_size > pr && pr > 0 {
            score += 12.0 + (next_item_size - pr) as f64 * 0.15;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 8.0 + 8.0 / (1.0 + slack as f64);
            if slack == 0 { score -= 4.0; }
            // reward near-exact chain with small slack
            if slack >= 1 && slack <= 12 {
                score -= 3.0 * (1.0 - slack as f64 / 12.0);
            }
            // penalize awkward gap just above next item (guaranteed strand)
            if slack > 0 && slack < item_size.min(next_item_size) {
                score += 2.0;
            }
            // large slack that will strand space on long streams
            if slack > 45 {
                score += (slack as f64 - 45.0) * 0.05;
            }
        }
        // two-step exact chain: item + next fills the bin perfectly
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        // near-exact triple chain
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 6 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 6.0);
        }
        // quad chain: item + 3x next fits near-exactly
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        // residual is an exact multiple of next item (perfect future splits)
        if pr > 0 && pr % next_item_size == 0 {
            score -= 1.5;
        }
        // frag barely too small for next item — guaranteed dead space next step
        if frag > 0.0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        // mid-range frag in (next, 2*next) is dead-space prone on long streams
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && remaining > 80 {
            score += (frag - next_item_size as f64) * 0.07;
        }
        // frag exactly equals next item: perfect chain next step
        if frag > 0.0 && frag as u32 == next_item_size {
            score -= 4.5;
        }
        // frag leaves room for next + small remainder
        if frag > 0.0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 {
                score -= 2.2 - rem as f64 * 0.6;
            }
        }
        // dead-space ratio: penalize frag in (next, 2*next) harder when mean residual low
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && mean_residual < 16.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
    }

    // Open-bin pressure: prefer tighter packing when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Bias toward bins with larger residuals (better long-term hosts).
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr as f64 * 0.3 * progress;

    // Large frag that will likely never be filled, scaled by remaining stream.
    if frag > 40.0 && remaining > 60 {
        score += (frag - 40.0) * 0.05;
    }
    // near-closing bins: tiny frag is excellent
    if frag > 0.0 && frag <= 2.0 {
        score -= 3.0;
    }

    // NEW-BIN CANDIDATE logic (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        score += 8.0 + crowding * 6.0;
        if fitting_bins_count == 0 {
            score += 40.0;
        } else {
            score += 4.0;
        }
        // open new bin eagerly when residuals are low (fresh bin amortizes well)
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        // large items early: avoid fragmenting fresh bins late
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        if item_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        // resist new bin when mean residual closely matches next item (open bins close cleanly)
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
        // resist new bin near stream end
        if remaining < 15 && fitting_bins_count > 0 {
            score += 4.0;
        }
        // open new bin when mean residual sits in awkward 12..20 zone on long streams
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 {
            score -= 1.5;
        }
        // no existing bin leaves room for next item after this one
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 4.0;
        }
        // high mean residual on long stream: fresh bin absorbs future items better
        if mean_residual > 28.0 && remaining > 100 {
            score -= 2.0;
        }
        // next item is large: fresh bin hosts it better than a fragmented open bin
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        // prefer new bin for large items when mean residual is mid-range (poor fits ahead)
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 {
            score -= 3.0;
        }
        // resist new bin when many open bins can each still absorb next item
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
        // open new bin when only fitting bins would leave frag just under next item (guaranteed dead space)
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2 && item_size + next_item_size <= bin_capacity && mean_residual > 28.0 && remaining > 60 {
            score -= 1.8;
        }
    } else {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Gaps that are too small to hold even the minimum plausible item are "dead".
    // Penalize them super-linearly so tight fits are strongly preferred.
    let dead_threshold = 12.0; // below typical small item size
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Non-linear penalty on wasted residual: quadratic in the gap.
    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Reward near-perfect fits (post_residual close to 0).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // --- Open bins pressure ---
    // Discourage spreading across many bins; encourage consolidating.
    score += open_bins_count as f64 * 2.5;

    // --- Last-chance bin bonus ---
    // If this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // --- New-bin candidate handling ---
    // A fresh empty bin should only win if no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Penalize opening new bins generally.
        score += 30.0;
        // But if all existing residuals are poor fits (item barely fits),
        // relax the penalty: compare against mean residual mismatch.
        let fit_quality = (bin_residual - item_size) as f64; // == residual of fresh bin
        if fit_quality < mean_residual - item_size as f64 {
            score -= 15.0;
        }
        // Late in the stream, opening new bins is less costly than dead space.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0;
    }

    // --- Lookahead coupling (k=2) ---
    // If the next item would fit into this bin's post-residual, reward it.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 20.0;
