            score -= 5.0;
        } else {
            // Post-residual unusable by next item: penalize dead space.
            score += 12.0;
        }
    }

    // --- Mean residual alignment ---
    // Prefer bins whose residual is close to the mean (keeps bins balanced),
    // but only mildly, so tight fits still dominate.
    let residual_diff = (bin_residual as f64 - mean_residual).abs();
    score += residual_diff * 0.15;

