}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = if pr >= item_size { (pr - item_size) as f64 } else { -1.0 };
    let remaining = total_items.saturating_sub(step_index);

    // Residual class ladder (borrowed from best): small residuals are good.
    let class: f64 = if pr == 0 { -48.0 } else if pr <= 8 { -15.0 } else if pr <= 15 { -6.5 } else if pr <= 25 { -1.0 } else if pr <= 40 { 4.0 } else if pr <= 60 { 8.0 } else { 12.0 };
    score += class;

    // Reward residuals divisible by common item sizes (future perfect splits).
    if pr > 0 {
        let reusable = (pr % 10 == 0) as f64 * 4.0 + (pr % 20 == 0) as f64 * 3.0 + (pr % 25 == 0) as f64 * 2.0 + (pr % 5 == 0) as f64 * 1.0;
