    }

    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= next_item_size {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 5.0; }
            if slack >= 1.0 && slack <= 12.0 { score -= 3.0 * (1.0 - slack / 12.0); }
            // two-step exact chain
            if item_size + next_item_size == pr { score -= 6.0; }
            // near-exact chain next step
            if slack <= 3.0 { score -= 1.0 * (1.0 - slack / 3.0); }
            // awkward gap in 25..45 dead zone
            if slack > 25.0 && slack < 45.0 { score += (slack - 25.0) * 0.08; }
