        if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }
        // tiny frag near-closing
        if frag >= 0.0 && frag <= 2.0 { score -= 3.0; }
        // frag exactly equals next item — perfect chain
        if frag > 0.0 && (frag as u32) == next_item_size { score -= 4.5; }
    }

    // Open-bin pressure: prefer tighter packing when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity { score -= 20.0; }

    // Bias toward bins with larger residuals.
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Late-stream tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

