pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fill = 1.0 - pr / cap;

    // Non-linear tightness reward: strongly favor small post_residual (smooth quadratic coupling)
    score -= 12.0 * fill * fill;

    // Perfect fit bonus, smoothly scaled
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: penalize leaving a residual that neither fits next item well nor is tiny
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let coupling = 1.0 - (gap / cap).min(1.0);
        score -= 8.0 * coupling * coupling * (0.5 + 0.5 * progress);
        // Penalize residual just below next item size (dead space)
        if pr < nx && pr > 0.0 {
            score += 6.0 * (nx - pr) / cap * (1.0 + progress);
        }
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more as stream progresses
    if bin_residual == bin_capacity {
        score += 30.0 + 25.0 * progress + 2.0 * open_bins_count as f64;
    }

    // Penalize bins far from mean residual (fragmentation pressure), smooth interaction
    let dev = (pr - mean_residual).abs() / cap;
    score += 5.0 * dev * dev * progress;

    // Mild reward for filling bins deeper as stream matures
    score -= 4.0 * (bin_residual as f64 / cap) * (1.0 - pr / cap) * progress;

    score
}

