        1..=9 => -4.0,                   // near-perfect, unusable sliver
        10..=19 => -1.5,                 // small-item class
        20..=29 => -2.5,
        30..=39 => -1.0,
        40..=49 => -3.0,                 // half-bin class is valuable
        50..=59 => -2.0,
        60..=79 => -0.5,
        80..=99 => 1.5,                  // large dead space
        _ => 3.0,
    };
