    // granularities remain usable.
    if pr % 10 == 0 && pr > 0 {
        score -= 2.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 1.0;
    }

    // Integer-division threshold: can the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // chainability is good, weighted by how tightly it chains
            let tightness = 1.0 - (pr - next_item_size) as f64 / cap;
            score -= 3.0 + 2.0 * tightness;
        } else {
            // next item cannot chain here: penalize proportionally to overshoot
            score += 1.0 + (next_item_size - pr) as f64 / 20.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

