        }
        // Large frag unlikely to ever be filled.
        if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }
        // Near-closing bins.
        if frag <= 2.0 { score -= 3.0; }
        // Dead-space ratio scaled by mean residual.
        let mr = mean_residual.max(1.0);
        if frag > mr * 1.5 && open_bins_count > 3 {
            score += (frag - mr * 1.5) * 0.06;
        }
    }

    // Open-bin pressure.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Bias toward bins with larger residuals.
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Progress-scaled tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr as f64 * 0.3 * progress;

    // ---- NEW-BIN CANDIDATE LOGIC ----
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 { score += 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        // Open new bin when all fitting bins would leave frag just under next item.
        if next_item_size > 0 && fitting_bins_count > 0 && next_item_size > item_size && remaining > 50 && mean_residual > 20.0 { score -= 1.2; }
        // Resist new bin when mean residual closely matches next item.
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        // Resist new bin when stream nearly over and bins suffice.
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
    } else {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never be used by any
    // future item (item sizes >= 1, so residual 0 is perfect; small gaps of
    // 1..=9 are near-dead). Penalize them heavily.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: strongly favored
    } else if post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0; // dead space penalty
    }

    // If residual cannot fit the next item, it is likely dead space too.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Reward residuals that exactly accommodate the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Tightness coupling: relative fill quality of this placement.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness;

    // Open-bin pressure: discourage scattering items across many bins,
    // but allow opening a new bin when this bin's fit is poor.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 + 2.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Mean-residual alignment: prefer bins whose residual is below mean
    // (they are the "fuller" ones), pushing toward closing bins out.
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // New-bin candidate: only attractive when this placement would waste
    // space or no good fit exists. Base new-bin score is neutral-ish;
    // the open_bins_count pressure above makes it costly unless fit is bad.
    if bin_residual == bin_capacity {
        // Opening a new bin gives residual = capacity - item_size; judge it
        // by how well the item fills the fresh bin.
        let fill = item_size as f64 / bin_capacity as f64;
        score += 10.0 - 30.0 * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = (pr as f64 - item_size as f64).max(0.0);
    let remaining = total_items.saturating_sub(step_index);

    // Residual class base: reward small residuals (near-closed bins)
    let class: f64 = if pr == 0 { -48.0 }
        else if pr <= 8 { -15.0 }
        else if pr <= 15 { -6.5 }
        else if pr <= 25 { -1.0 }
        else if pr <= 40 { 4.0 }
        else if pr <= 60 { 8.0 }
        else { 12.0 };
    score += class;

    // Reward round residuals likely reusable by future items
    let reusable = (pr % 10 == 0) as f64 * 4.0 + (pr % 20 == 0) as f64 * 3.0 + (pr % 25 == 0) as f64 * 2.0 + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Lookahead: reward bins that fit the next item with small slack
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 5.0; }
            if slack >= 1.0 && slack <= 12.0 { score -= 3.0 * (1.0 - slack / 12.0); }
            if slack > 45.0 { score += (slack - 45.0) * 0.05; }
        } else {
            // Residual just below next item = guaranteed dead space
            score += 5.0 + (next_item_size - pr) as f64 * 0.09;
        }
        // Two-item exact chain
        if item_size + next_item_size == pr { score -= 6.0; }
        // Triple chain near-exact
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 { score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0); }
        // Quad chain near-exact
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 { score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0); }
        // Penalize mid-range frag in (next, 2*next) — awkward dead zone
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
            if mean_residual < 16.0 && remaining > 100 { score += (frag - next_item_size as f64) * 0.08; }
        }
        // Residual just barely too small for next item
        if pr > 0 && pr < next_item_size && next_item_size - pr <= 4 { score += (next_item_size - pr) as f64 * 0.9; }
        // Post-residual exact multiple of next item (future perfect splits)
        if pr > 0 && pr % next_item_size == 0 { score -= 1.5; }
        // Two-step chain: next item then a tiny remainder
        if frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 { score -= 2.2 - rem as f64 * 0.6; }
        }
        // Penalize awkward 20..35 dead zone on long streams
        if frag >= 20.0 && frag <= 35.0 && remaining > 80 && next_item_size < frag { score += (frag - 20.0) * 0.045; }
    }

    // Near-closing bins
    if frag > 0.0 && frag <= 2.0 { score -= 3.0; }
    // Perfect fit
    if frag == 0.0 { score -= 4.0; }
    // Large frag that will likely never be filled
    if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 300.0; }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if fitting_bins_count > 0 {
            score += 500.0;
            // Open new bin more eagerly for large items when mean residual is mid-range
            if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
            // Open new bin when mean residual sits in awkward 12..20 dead zone on long streams
            if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 { score -= 1.5; }
            // Open new bin when no existing bin leaves room for next item after this one
            if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
            // Prefer new bin for very large items early in stream
            if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
            // Resist new bin when stream nearly over
            if remaining < 8 { score += 5.0; }
            if remaining < 25 && mean_residual < item_size as f64 { score += 4.0; }
            // Resist new bin when open bins will close cleanly on next item
            if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        } else {
            score -= 100.0;
        }
    } else {
        score += 60.0;
    }

    // Consolidation pressure and fuller-bin tie-breaker
    score += open_bins_count as f64 * 0.5;
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead: exact match of post_residual with next item ---
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect two-step packing: bin becomes exactly full after next item.
            score -= 100.0;
        } else if post_residual >= next_item_size {
            // Next item still fits; reward small leftover slack after the pair.
            let pair_leftover = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - pair_leftover / bin_capacity as f64);
        } else {
            // Next item cannot fit here: penalize proportionally to the mismatch.
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 + 0.5 * gap;
        }
    } else {
        // Last item: prefer leaving zero residual.
        score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // --- Fit tightness relative to current bin ---
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // --- Compare post_residual to mean residual across open bins ---
    // Leaving less than average residual is good (tight packing).
    score -= 0.3 * (mean_residual - post_residual as f64);

    // --- Last-chance bin: strongly favor using it to avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when nothing fits well:
        // make it costly unless the item is large relative to capacity.
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 40.0 * (1.0 - large_item);
        // If many open bins already fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 1 {
            score += 30.0 * (fitting_bins_count as f64 - 1.0);
        }
    }

    // --- Mild pressure against bin proliferation late in the stream ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

