    // Lookahead: reward if next item fits exactly into post_residual
    if next_item_size > 0 && (next_item_size as f64 - pr).abs() < 1.0 {
        score -= 10.0;
    } else if next_item_size > 0 && next_item_size as u32 <= post_residual {
        score -= 4.0 * (1.0 - (next_item_size as f64 - pr) / cap).powi(2);
    } else if next_item_size > 0 {
        // dead space for the next item: penalize
