        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening a bin unless residuals across open bins are tight
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        let mean_tightness = 1.0 - (mean_residual / cap);
