    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: when many bins are open, favor using existing ones
    // (penalize the new-bin candidate which has bin_residual == bin_capacity).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * (open_bins_count as f64).ln().max(0.0) + 20.0 * progress;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with residual below mean (consolidating fuller bins).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

