pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: leaving zero residual is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: strongly reward exact chain fit (post_residual == next item).
    if next_item_size > 0 {
        let chain_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.45 * chain_gap;

        // Exact chain match: next item fills this bin completely.
        if post_residual == next_item_size {
            score -= 45.0;
        }

        // Next item fits in the leftover after this placement: good chaining.
        if next_item_size <= post_residual {
            score -= 8.0 + 0.15 * (post_residual - next_item_size) as f64;
        } else {
            // Leftover too small for next item: penalize potential dead space,
            // worse when the leftover is small (hard to reuse later).
            let dead = post_residual as f64;
            if dead > 0.0 && dead < next_item_size as f64 {
                score += 6.0 * (1.0 - dead / next_item_size as f64);
            }
        }
    }

    // Compare post_residual against the mean residual of open bins.
    // Leaving less than the mean is a tighter, more valuable fit.
    let res = post_residual as f64;
    score += 0.35 * (res - mean_residual);

    // Penalize tiny unusable leftovers (dead space below min item size ~1..small).
    if res > 0.0 && res < 10.0 {
        score += 12.0 * (1.0 - res / 10.0);
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 15.0;
        // With many open bins, prefer reusing them over opening new ones.
        score += 1.2 * open_bins_count as f64;
        // If the only fitting bin is this new bin, allow it.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Early in the stream, slightly favor consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = pr as f64 - item_size as f64;
    let remaining = total_items.saturating_sub(step_index);

    // Dead-space avoidance: small unusable gaps heavily penalized.
    if pr > 0 && pr < 10 {
        score += 60.0;
    } else if pr < 25 {
        score += 25.0 * (1.0 - pr as f64 / 25.0);
    }

    // Reward near-perfect fills.
    if pr == 0 {
        score -= 60.0;
    }

    // Reusability bonus: residuals that are round multiples are easier to fill later.
    let reusable = (pr % 10 == 0) as f64 * 4.0 + (pr % 20 == 0) as f64 * 3.0 + (pr % 25 == 0) as f64 * 2.0 + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Lookahead: dead space worse if next item cannot use the post-residual.
    if next_item_size > 0 {
        if next_item_size > pr && pr > 0 {
            score += 12.0 + (next_item_size - pr) as f64 * 0.15;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 8.0 + 8.0 / (1.0 + slack as f64);
            if slack == 0 { score -= 4.0; }
            if slack >= 1 && slack <= 12 {
                score -= 3.0 * (1.0 - slack as f64 / 12.0);
            }
            if slack > 0 && slack < item_size.min(next_item_size) {
                score += 2.0;
            }
            if slack > 45 {
                score += (slack as f64 - 45.0) * 0.05;
            }
            // slack large enough to host next item again: strong chain potential
            if slack >= next_item_size {
                score -= 2.5;
            }
        }
        // two-step exact chain: item + next fills the bin perfectly
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        // near-exact triple chain
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 6 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 6.0);
        }
        // quad chain: item + 3x next fits near-exactly
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        // residual is an exact multiple of next item (perfect future splits)
        if pr > 0 && pr % next_item_size == 0 {
            score -= 1.5;
        }
        // frag barely too small for next item — guaranteed dead space next step
        if frag > 0.0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        // mid-range frag in (next, 2*next) is dead-space prone on long streams
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && remaining > 80 {
            score += (frag - next_item_size as f64) * 0.07;
        }
        // frag exactly equals next item: perfect chain next step
        if frag > 0.0 && frag as u32 == next_item_size {
            score -= 4.5;
        }
        // frag leaves room for next + small remainder
        if frag > 0.0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 {
                score -= 2.2 - rem as f64 * 0.6;
            }
        }
        // dead-space ratio: penalize frag in (next, 2*next) harder when mean residual low
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && mean_residual < 16.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
        // penalize residual just below next item (guaranteed dead space next step)
        if pr > 0 && pr < next_item_size && pr < item_size.min(next_item_size) {
            score += 1.5 + (next_item_size - pr) as f64 * 0.05;
        }
        // reward post-residual hosting next item twice with near-zero slack
        if pr >= next_item_size * 2 {
            let d2 = pr - next_item_size * 2;
            if d2 <= 3 {
                score -= 2.0 - d2 as f64 * 0.5;
            }
        }
        // awkward 13..25 gap above next item on high mean residual
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap >= 15 && gap <= 25 && mean_residual > 22.0 {
                score += (gap as f64 - 15.0) * 0.10;
            }
            if gap > 25 && gap < 45 {
                score += (gap as f64 - 25.0) * 0.08;
            }
        }
    }

    // Open-bin pressure: prefer tighter packing when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Bias toward bins with larger residuals (better long-term hosts).
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr as f64 * 0.3 * progress;

    // Large frag that will likely never be filled, scaled by remaining stream.
    if frag > 40.0 && remaining > 60 {
        score += (frag - 40.0) * 0.05;
    }
    // near-closing bins: tiny frag is excellent
    if frag > 0.0 && frag <= 2.0 {
        score -= 3.0;
    }
    // frag within 3 of next item: near-exact chain next step
    if next_item_size > 0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
        score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
    }

    // NEW-BIN CANDIDATE logic (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        score += 8.0 + crowding * 6.0;
        if fitting_bins_count == 0 {
            score += 40.0;
        } else {
            score += 4.0;
        }
        // open new bin eagerly when residuals are low (fresh bin amortizes well)
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        // large items early: avoid fragmenting fresh bins late
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        if item_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        // resist new bin when mean residual closely matches next item (open bins close cleanly)
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
        // resist new bin near stream end
        if remaining < 15 && fitting_bins_count > 0 {
            score += 4.0;
        }
        // open new bin when mean residual sits in awkward 12..20 zone on long streams
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 {
            score -= 1.5;
        }
        // no existing bin leaves room for next item after this one
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 4.0;
        }
        // high mean residual on long stream: fresh bin absorbs future items better
        if mean_residual > 28.0 && remaining > 100 {
            score -= 2.0;
        }
        // next item is large: fresh bin hosts it better than a fragmented open bin
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        // prefer new bin for large items when mean residual is mid-range (poor fits ahead)
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 {
            score -= 3.0;
        }
        // resist new bin when many open bins can each still absorb next item
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
        // open new bin when only fitting bins would leave frag just under next item (guaranteed dead space)
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2 && item_size + next_item_size <= bin_capacity && mean_residual > 28.0 && remaining > 60 {
            score -= 1.8;
        }
        // open new bin for mid-size items when all fitting bins would strand space relative to next item
        if next_item_size > 0 && fitting_bins_count > 0 && next_item_size > item_size && remaining > 50 && mean_residual > 20.0 {
            score -= 1.2;
        }
        // resist new bin when stream ends soon even if mean residual is high
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 4.0;
        }
    } else {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual relative to capacity nonlinearly.
    let tightness = (post_residual as f64) / cap;
    score += 25.0 * tightness * tightness;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: prefer it only when no open bin fits well.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64;
        // Opening a new bin is cheap when many bins are open and mean residual is high.
        score += 35.0 - 0.5 * crowding + 0.3 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin anyway
        }
        // Late in stream, prefer consolidation into existing bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
    }

    // Lookahead: if the next item would fit the post-residual exactly, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post >= nxt && (post - nxt) < 10.0 {
            score -= 25.0;
        } else if post < nxt && post > 0.0 {
            // dead space that next item cannot use
            score += 0.5 * post;
        }
        // If next item fits current residual but not post, placing here wastes the slot
        if bin_residual as f64 >= nxt && post < nxt {
            score += 15.0;
        }
    }

    // Penalize leaving residuals that most item sizes (10..80) cannot use.
    if post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Mild penalty for spreading across too many bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
