pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping
    let mut score = pr;

    // Smooth polynomial coupling: post_residual interacts with stream progress.
    // Late in the stream, dead space matters more; penalize residual quadratically.
    score += 40.0 * pr_norm * pr_norm * (0.5 + progress);

    // Reward near-perfect fills smoothly via a bump around pr ~ 0..10
    let bump = (pr / 10.0).tanh();
    score -= 15.0 * (1.0 - bump * bump) * (1.0 - progress);

    // Last-chance bonus: strongly favor the only bin that fits (avoid opening bins)
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead coupling: if the next item fits in the post-residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - pr_norm);
    } else if next_item_size > 0 {
        // smooth penalty when lookahead cannot follow into this bin
        let gap = (next_item_size as f64 - pr) / cap;
        score += 8.0 * gap * gap;
    }

    // Discourage opening new bins when many bins are already open with slack
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * open_bins_count as f64 - 10.0 * mean_residual / cap;
    }

    // Mild preference for filling bins with larger residuals relative to mean
    score -= 5.0 * ((bin_residual as f64 - mean_residual) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
