pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover lands on a
    // "friendly" residue class (divisible by small sizes) are more reusable.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        for d in [5u32, 10, 20, 25, 50] {
            if pr % d == 0 {
                harmony += 1.0;
            }
        }
        score -= 2.5 * harmony;

        // Penalize awkward dead space: tiny unusable slivers.
        if pr < 10 {
            score += 15.0;
        } else if pr < 20 {
            score += 6.0;
        }

        // Reward leftovers in the "medium" band that many items can use.
        if pr >= 20 && pr <= 50 {
            score -= 4.0;
        }
    } else {
        // Perfect closure of the bin.
        score -= 12.0;
    }

    // Integer-division threshold coupling: how well next_item_size divides
    // into the post-residual predicts a chain placement.
    if next_item_size > 0 && pr >= next_item_size {
        let k = pr / next_item_size;
        score -= 3.0 * (k as f64).min(3.0);
        if pr % next_item_size == 0 {
            score -= 4.0;
        }
    } else if next_item_size > 0 && next_item_size > pr && next_item_size <= bin_residual {
        // Next item won't fit here after this placement; mild penalty unless
        // this is a perfect-fit situation.
        score += 2.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // and mean residual is large (fragmented state).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64) / bin_capacity as f64;
        // Opening a new bin costs ~1 bin; make it unattractive by default.
        score += 30.0;
        // But if open bins are highly fragmented and many exist, allow opening.
        if mean_residual > 0.6 * bin_capacity as f64 && open_bins_count > 2 {
            score -= 25.0 + 10.0 * fragmentation - 10.0 * progress;
        }
        // Small items seed new bins cheaply.
        if item_size <= 20 {
            score -= 5.0;
        }
    }

    // Prefer tighter fits overall: relative waste term.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * waste_frac * waste_frac;

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - waste_frac);

    score
}

