    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: keep it neutral-ish, only attractive when current fit is bad.
    if bin_residual == bin_capacity {
        score += 10.0;
