            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        let quad = item_size.saturating_add(next_item_size * 3);
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        if pr >= next_item_size * 2 {
            let d2 = pr - next_item_size * 2;
            if d2 <= 3 { score -= 2.0 - d2 as f64 * 0.5; }
        }
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 { score += (gap as f64 - 25.0) * 0.08; }
            if gap >= 15 && gap <= 25 && mean_residual > 22.0 {
                score += (gap as f64 - 15.0) * 0.10;
            }
        }
        if pr > 0 && pr % next_item_size == 0 { score -= 1.5; }
        if pr > 0 && pr < next_item_size && pr < item_size.min(next_item_size) {
            score += 1.5 + (next_item_size - pr) as f64 * 0.05;
        }
        // reward bins whose residual is a near-exact sum of next item and a small filler
        if pr >= next_item_size {
            let rem = pr - next_item_size;
            if rem > 0 && rem <= item_size.min(8) { score -= 2.0 - rem as f64 * 0.2; }
        }
        // gen 62: reward near-exact chain where frag leaves room for next item with tiny remainder
        if pr >= next_item_size {
            let chain = pr - next_item_size;
            if chain >= item_size && chain - item_size <= 2 { score -= 2.0; }
        }
        // gen 62: reward bins whose residual fits next item twice with near-zero slack
        if pr >= next_item_size * 2 && pr % next_item_size == 0 { score -= 2.0; }
    }

    // Frag-based dead-space shaping
    if frag > 0.0 {
        if frag < item_size.min(15) as f64 { score += 4.0 + (15.0 - frag) * 0.15; }
        if next_item_size > 0 && (frag as u32) == next_item_size { score -= 4.5; }
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
        }
        if frag >= 20.0 && frag <= 35.0 && remaining > 80 && next_item_size > 0 && next_item_size < frag as u32 {
            score += (frag - 20.0) * 0.045;
        }
        let mr = mean_residual.max(1.0);
        if frag > mr * 1.5 && open_bins_count > 3 { score += (frag - mr * 1.5) * 0.06; }
        if next_item_size > 0 && frag as u32 > next_item_size * 2 && pr > 30 {
            score += (frag - next_item_size as f64) * 0.045;
        }
        if next_item_size > 0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 { score -= 2.2 - rem as f64 * 0.6; }
        }
        if next_item_size > 0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        if next_item_size > 0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        if next_item_size > 0 && frag as u32 % next_item_size == 0 && frag <= next_item_size as f64 * 3.0 {
            score -= 1.5;
        }
        if next_item_size > 0 && frag > next_item_size as f64 && frag < 30.0 && remaining > 60 {
            score += (frag - next_item_size as f64) * 0.05;
        }
        // dead-space ratio — penalize frag far above next item when stream is long
        if next_item_size > 0 && frag > next_item_size as f64 && remaining > 120 {
            score += (frag - next_item_size as f64) * 0.03;
        }
        // gen 62: sharpen dead-space penalty in (next, 2*next) gap when mean residual is low
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0
            && mean_residual < 16.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
        // reward near-closing frag (tiny remainder)
        if frag <= 2.0 { score -= 3.0; }
        // penalize large frag that will likely never be filled
        if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }
        // exact-fill reward
        if frag == 0.0 { score -= 4.0; }
        // gen 62: dead-space ratio refinement — penalize frag whose usable portion is small
        if next_item_size > 0 {
            let usable = next_item_size.min(frag as u32);
            let dead_ratio = (frag - usable as f64) / frag.max(1.0);
            if dead_ratio < 0.5 && frag > 12.0 && remaining > 30 {
                score += (frag - 12.0) * 0.06 * (1.0 - dead_ratio);
            }
        }
    }

    // Scarcity pressure
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 6.0;
    } else if fitting_bins_count >= 5 {
        score += 2.0;
    }

    // Global residual context
    if mean_residual > 25.0 && pr > mean_residual as u32 {
        score += 3.0;
    } else if mean_residual < 12.0 && pr > 0 && pr <= item_size * 2 {
        score -= 2.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size <= bin_capacity && mean_residual > 20.0 { score += 1.5; }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && next_item_size > item_size && next_item_size - item_size <= 4 && remaining > 50 {
            score -= 2.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
        // resist new bin when an open bin can absorb item plus next item exactly
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size == bin_capacity { score += 3.0; }
        // open new bin in awkward mid dead zone on very long streams
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        // resist new bin late when open bins suffice
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
        // gen 62: resist new bin when mean residual closely matches next item (open bins will close cleanly)
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 { score += 2.0; }
        // gen 62: open new bin when only fitting bins would leave frag just under next item (guaranteed dead space)
        if next_item_size > 0 && fitting_bins_count > 0 && next_item_size > item_size && remaining > 50 && mean_residual > 20.0 { score -= 1.2; }
    } else {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Brand-new empty bin candidate: give it a moderate baseline that becomes
    // more attractive when existing bins are crowded (high mean residual).
    if bin_residual == bin_capacity {
        let base = 42.0_f64;
        let crowd_penalty = mean_residual * 0.35 + open_bins_count as f64 * 0.4;
        return base + crowd_penalty;
    }

    // Reward tight fits right now (low post residual = less dead space),
    // but punish leaving a tiny unusable sliver.
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    } else if post_residual < 10 {
        score += 10.0; // awkward sliver, likely dead space
    }

    // Aggressive 2-step lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward closeness of the match: perfect next-fit gets a big bonus.
            let gap = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score -= 18.0 * (1.0 - gap) + 6.0;
        } else {
            // Next item won't fit here: penalize proportionally to the shortfall.
            let shortfall = (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
            score += 4.0 + 14.0 * shortfall;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 22.0;
    }

    // Mild coupling with the fleet state: prefer bins whose residual is
    // below the mean (consolidate space into fewer, fuller bins).
    score += (post_residual as f64 - mean_residual) * 0.12;

    // Slight progression bias: later in the stream, be a bit more conservative
    // about leaving large residuals (fewer chances left to fill them).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = pr.saturating_sub(item_size) as f64;
    let remaining = total_items.saturating_sub(step_index);

    // Residual quality classes (borrowed from best-so-far)
    let class: f64 = if pr == 0 { -48.0 } else if pr <= 8 { -15.0 } else if pr <= 15 { -6.5 } else if pr <= 25 { -1.0 } else if pr <= 40 { 4.0 } else if pr <= 60 { 8.0 } else { 12.0 };
    score += class;

    // Reward residuals that are clean multiples (future perfect splits)
    if pr > 0 {
        if pr % next_item_size.max(1) == 0 { score -= 1.5; }
        if pr % 10 == 0 { score -= 2.0; }
        if pr % 5 == 0 { score -= 1.0; }
    }

    // Next-item fit: reward tight chains
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 5.0; }
            if slack >= 1.0 && slack <= 12.0 { score -= 3.0 * (1.0 - slack / 12.0); }
            if slack > 45.0 { score += (slack - 45.0) * 0.05; }
        } else {
            // residual just below next item = guaranteed dead space
            score += 5.0 + (next_item_size - pr) as f64 * 0.09;
        }
    }

    // Fragment quality after placing item
    if frag > 0.0 {
        if frag < item_size.min(15) as f64 { score += 4.0 + (15.0 - frag) * 0.15; }
        if frag <= 2.0 { score -= 3.0; }
        if next_item_size > 0 && (frag as u32) == next_item_size { score -= 4.5; }
        if next_item_size > 0 && (frag as u32) > next_item_size {
            let chain = frag as u32 - next_item_size;
            if chain <= 6 { score -= 1.8 * (1.0 - chain as f64 / 6.0); }
            if chain <= 2 { score -= 2.2 - chain as f64 * 0.6; }
        }
        if next_item_size > 0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        // dead-space ratio penalty on long streams
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 {
            score += (frag - next_item_size as f64) * 0.10;
            if mean_residual < 16.0 && remaining > 100 { score += (frag - next_item_size as f64) * 0.08; }
        }
        if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }
        // exact multi-item chain lookaheads
        if next_item_size > 0 {
            let two = item_size + next_item_size;
            if pr >= two && pr - two <= 2 { score -= 6.0; }
            let triple = item_size + next_item_size * 2;
            if pr >= triple && pr - triple <= 6 { score -= 2.5 * (1.0 - (pr - triple) as f64 / 6.0); }
            let quad = item_size + next_item_size * 3;
            if pr >= quad && pr - quad <= 6 { score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0); }
        }
        let mr = mean_residual.max(1.0);
        if frag > mr * 1.5 && open_bins_count > 3 { score += (frag - mr * 1.5) * 0.06; }
    } else if frag == 0.0 {
        score -= 4.0;
    }

    // Open-bin pressure
    score += open_bins_count as f64 * 0.3;
    if fitting_bins_count == 1 && bin_residual < bin_capacity { score -= 20.0; }
    score -= (bin_residual as f64 - mean_residual) * 0.2;
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr as f64 * 0.3 * progress;

    // NEW-BIN CANDIDATE logic
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        score += 8.0 + crowding * 6.0 + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if fitting_bins_count > 0 { score += 4.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        // open new bin when mean residual sits in awkward dead zone on long streams
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        // resist new bin when open bins will close cleanly on next item
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        // resist new bin near stream end
        if remaining < 15 && fitting_bins_count > 0 { score += 4.0; }
        // open new bin when all fitting bins would leave frag just under next item
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2 && next_item_size > item_size && mean_residual > 20.0 && remaining > 50 { score -= 1.2; }
    } else {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a non-linear push
    // that grows quadratically for large wasted space (dead space penalty).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Reward near-perfect fits aggressively.
    if post_residual <= 3 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead (k=2): if the next item fits exactly or well into the
    // post-residual, this bin is doubly valuable.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        let gap = post_residual as f64 - next_item_size as f64;
        score -= 30.0 - gap.min(30.0); // exact follow-up fit => -30, worse => less reward
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Global state coupling: with many open bins, prefer consolidating into
    // existing bins (penalize new-bin temptation); with few open bins and
    // large mean residual, spreading out is less costly.
    let open_f = open_bins_count as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_f * 0.8 * (1.0 - progress);

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize outliers that would strand capacity.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in the stream, keep bins flexible (penalize tiny
    // post residuals slightly less late, when tight fits matter most).
    score -= 20.0 * progress * (1.0 - waste_frac);

    // New-bin candidate handling: an empty bin has neutral appeal. Score it
    // so it wins only when every open bin would leave a large unusable gap.
    if bin_residual == bin_capacity {
        // Empty bin: its "post_residual" equals capacity - item_size.
        // Make it attractive only for large items that waste little space.
        score = (bin_capacity - item_size) as f64 + 35.0 * waste_frac;
        if item_size >= 70 {
            score -= 25.0; // big items start fresh bins happily
        }
        score += open_f * 0.5;
    }

    // Small stabilizing term: prefer bins that will remain usable
    // (post_residual >= 10 keeps room for typical small items).
    if post_residual >= 10 && post_residual <= 30 {
        score -= 8.0;
    }

    score
}

