        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 { score += 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        // open new bin when mean residual sits in awkward 12..20 dead zone on long stream
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        // resist new bin when stream nearly over
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
        // resist new bin when mean residual closely matches next item
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        // open new bin when only fitting bins would leave frag just under next item
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && next_item_size > item_size && remaining > 50 && mean_residual > 20.0 { score -= 1.2; }
    } else {
        // Non-new-bin calls: keep open bins preferred
        score += 60.0;
    }

    // Late-stream tightening
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += norm_pr * norm_pr * (1.0 - progress) * cap * 0.35;
    score -= norm_pr * p2 * cap * 0.25;
    score -= norm_pr * p3 * cap * 0.15;

    // Reward tight fits more strongly as stream progresses (smoothly)
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (0.5 + progress) * 8.0;

    // Penalize dead space relative to next item (smooth coupling)
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let waste = (pr - ni).max(0.0);
        score += (waste / cap) * (waste / cap) * cap * (0.2 + 0.4 * progress);
        // Bonus if post_residual exactly accommodates next item
        let gap = (pr - ni).abs();
        score -= (1.0 - gap / cap).max(0.0) * 6.0 * (1.0 - progress);
    }

    // Last-chance bin bonus (smooth in fitting_bins_count)
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - progress);
    } else if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64 - 2.0).min(5.0) * 1.5 * progress;
    }

    // Mild coupling with mean residual and open bins
    score += (mean_residual - pr) * 0.05;
    score += open_bins_count as f64 * 0.1 * norm_pr;

    // New-bin candidate: penalize lightly early, more later unless fit is bad
    if bin_residual == bin_capacity {
        score += 3.0 + 6.0 * progress - tightness * 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);

    // Residual class tiers: reward perfect closes and tiny residuals, penalize mid-range waste.
    let class: f64 = if pr == 0 { -50.0 } else if pr <= 8 { -14.0 } else if pr <= 15 { -6.0 } else if pr <= 25 { -1.0 } else if pr <= 40 { 4.5 } else if pr <= 60 { 8.5 } else { 12.0 };
    score += class;

    // Reward residuals that are "friendly" (round / divisible) values.
    let reusable = (pr % 10 == 0) as f64 * 4.0 + (pr % 20 == 0) as f64 * 3.0 + (pr % 25 == 0) as f64 * 2.0 + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Next-item lookahead: exact fit is great, awkward near-miss is bad.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 5.0; }
            if slack >= 1.0 && slack <= 12.0 { score -= 3.0 * (1.0 - slack / 12.0); }
            if slack > 45.0 { score += (slack - 45.0) * 0.05; }
        } else {
            score += 5.0 + (next_item_size - pr) as f64 * 0.09;
        }
    }

    let frag = (pr - item_size) as f64; // space left after placing item (pr already post-placement? guard below)
    // Note: post_residual is residual after placing the item, so frag here is not meaningful;
    // use pr-based lookahead terms instead.
    let _ = frag;

    // Two-step exact chain: item + next fills this bin perfectly.
    if next_item_size > 0 && item_size + next_item_size == pr { score -= 6.0; }

    // Triple chain: item + 2*next with tiny slack.
    if next_item_size > 0 {
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 { score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0); }
    }

    // Quad chain: item + 3*next with tiny slack.
    if next_item_size > 0 {
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 { score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0); }
    }

    // Penalize residual just below next item (guaranteed dead space next step).
    if next_item_size > 0 && pr > 0 && pr < next_item_size && pr < item_size.min(next_item_size) {
        score += 1.5 + (next_item_size - pr) as f64 * 0.05;
    }

    // Penalize residual that fits next item with awkward 15..45 gap.
    if next_item_size > 0 && pr >= next_item_size {
        let gap = pr - next_item_size;
        if gap > 25 && gap < 45 { score += (gap as f64 - 25.0) * 0.08; }
        if gap >= 15 && gap <= 25 && mean_residual > 22.0 { score += (gap as f64 - 15.0) * 0.10; }
    }

    // Penalize large frag that will likely never be filled, scaled by remaining stream.
    if pr > 40 && remaining > 60 { score += (pr - 40) as f64 * 0.05; }

    // Dead-space ratio: penalize awkward mid-range residuals when many future items remain.
    if next_item_size > 0 && pr > next_item_size && pr < next_item_size * 2 && pr > 8 {
        score += (pr - next_item_size) as f64 * 0.10;
        if mean_residual < 16.0 && remaining > 100 { score += (pr - next_item_size) as f64 * 0.08; }
    }

    // Reward residuals that are exact multiples of next item (future perfect splits).
    if next_item_size > 0 && pr > 0 && pr % next_item_size == 0 { score -= 1.5; }

    // Open-bin pressure: prefer tighter packing when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Bias toward bins with larger residuals (better long-term hosts).
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr as f64 * 0.3 * progress;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity { score -= 20.0; }

    // NEW-BIN CANDIDATE LOGIC (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 { score += 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0 && next_item_size > 0 && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2 && item_size + next_item_size <= bin_capacity && mean_residual > 28.0 && remaining > 60 { score -= 1.8; }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        if next_item_size > 0 && fitting_bins_count > 0 && next_item_size > item_size && remaining > 50 && mean_residual > 20.0 { score -= 1.2; }
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
    } else {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how "usable" the leftover space is.
    // Residuals that are multiples of common item sizes (5,10,20,25,50) are reusable.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -12.0 // perfect fit, best possible outcome
    } else if pr % 50 == 0 {
        -8.0
    } else if pr % 25 == 0 {
        -6.0
    } else if pr % 20 == 0 {
        -5.0
    } else if pr % 10 == 0 {
        -4.0
    } else if pr % 5 == 0 {
        -2.0
    } else {
        3.0 // awkward residual, dead space risk
    };
    score += harmonic_bonus;

    // Integer-division threshold: classify residual into size classes
    let pr_class = pr / 10; // 0..=10
    score += match pr_class {
        0 => 0.0,                       // 0-9: nearly dead
        1 | 2 => 2.0,                   // 10-29: only tiny items fit
        3 | 4 => 1.0,                   // 30-49: medium
        5 | 6 => -1.0,                  // 50-69: good
        _ => -2.0,                      // 70+: very reusable
    } as f64;

    // Lookahead coupling: if next item fits into the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            // exact chain fit: post_residual == next_item_size is ideal
            if post_residual == next_item_size {
                score -= 6.0;
            }
        } else {
            // next item cannot use this residual; penalize proportionally to waste
            score += (next_item_size as f64) * 0.15;
        }
        // Harmonic class of next item relative to post residual (modulo compatibility)
        if next_item_size % 10 == 0 && pr % 10 == 0 && pr >= next_item_size {
            score -= 2.0;
        }
    } else {
        // last item: any placement is fine, prefer tightest
        score += 0.0;
    }

    // Last-chance bin: if this is the only fitting bin, opening a new bin wastes it;
    // strongly favor using it unless residual is tiny.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
        if post_residual <= 10 {
            score -= 5.0; // near-perfect last-chance fit
        }
    }

    // New-bin candidate handling: empty bin should only win when all open bins are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty so open bins with decent fits win
        score += 25.0;
        // but if many open bins are nearly full (low mean residual), new bin is fine
        score -= (mean_residual / cap) * 20.0;
        // early stream: prefer opening bins to build diversity
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 8.0;
        // if the item is large, packing into fresh bin avoids fragmentation
        if item_size >= bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Penalty for creating unusable slivers (< 10, the min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Mild preference for bins already below mean residual (tighter bins)
    score += ((mean_residual - bin_residual as f64) / cap).clamp(-0.5, 0.5) * 4.0;

    // Small penalty per open bin to discourage bin proliferation
    score += open_bins_count as f64 * 0.05;

    score
}

