    let frag = if pr >= item_size { (pr - item_size) as f64 } else { -1.0 };
    let remaining = total_items.saturating_sub(step_index);

    // Residual class shaping (borrowed from best): reward small/closed residuals
    let class: f64 = if pr == 0 { -48.0 } else if pr <= 8 { -15.0 } else if pr <= 15 { -6.5 } else if pr <= 25 { -1.0 } else if pr <= 40 { 4.0 } else if pr <= 60 { 8.0 } else { 12.0 };
    score += class;

    // Reward "round" residuals likely to be exactly filled by future items
    let reusable = (pr % 10 == 0) as f64 * 4.0 + (pr % 20 == 0) as f64 * 3.0 + (pr % 25 == 0) as f64 * 2.0 + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Lookahead: reward bins that will fit next item well
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 5.0; }
            if slack >= 1.0 && slack <= 12.0 { score -= 3.0 * (1.0 - slack / 12.0); }
            if slack > 45.0 { score += (slack - 45.0) * 0.05; }
        } else {
            score += 5.0 + (next_item_size - pr) as f64 * 0.09;
        }
        // two-item chain: item + next exactly fills residual
        if item_size + next_item_size == pr { score -= 6.0; }
        // triple chain near-exact
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 { score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0); }
        // residual is multiple of next item (perfect future splits)
        if pr > 0 && pr % next_item_size == 0 { score -= 1.5; }
        // frag just under next item: guaranteed dead space next step
        if frag >= 0.0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        // dead-space ratio: frag in (next, 2*next) is awkward
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
        }
        // penalize frag just barely too small for next item chain remainder
        if frag > 0.0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 { score -= 2.2 - rem as f64 * 0.6; }
        }
    }

    // Penalize tight slivers unless they match next item
    if pr > 0 && pr < 10 && pr != next_item_size { score += 50.0; }
    if frag > 0.0 && frag <= 2.0 { score -= 3.0; }

    // Mean residual alignment (weakened from parent)
    let mean_gap = (pr as f64 - mean_residual).abs();
    score += mean_gap * 0.15;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity { score -= 300.0; }

    // Mild tie-breaker: prefer fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + waste_pressure + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if fitting_bins_count > 0 { score += 4.0; }
        // open new bin for large items when mean residual is mid-range (poor fits ahead)
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        // open new bin when no existing bin leaves room for next item after this one
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        // resist new bin when stream nearly over
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        // resist new bin when open bins can absorb next item
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        // open new bin when mean residual high and few bins tightly fit (dead-space accumulation)
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
