    let prog_coupling = 1.0 + 0.8 * (1.0 - progress) * (1.0 - progress);
    score *= prog_coupling;

    // Reward tight fits (small post_residual) with smooth saturation
    let tight = (-prn * 8.0).exp();
    score -= 25.0 * tight * (0.5 + progress);

    // Lookahead: reward bins whose residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let snug = 1.0 - (pr - nxt) / cap;
            score -= 12.0 * snug * snug;
        } else {
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.15 * open_bins_count as f64 * prn;

    // Deviation from mean residual: prefer bins near mean (balance)
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // New-bin candidate: neutral-ish baseline, penalized slightly unless early stream
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * (1.0 - progress);
    }

    score
}

