pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small residues are dead space
    // Classes: residue mod 10 -> how "usable" the leftover is for typical items
    let residue_class = post_residual % 10;
    let class_bonus: f64 = match residue_class {
        0 => 30.0,           // round leftover, very reusable
        1 | 2 | 3 | 4 => -15.0, // tiny sliver, near-dead space
        5 => 10.0,
        6 | 7 | 8 | 9 => 5.0,
        _ => 0.0,
    };
    score -= class_bonus;

    // Integer-division thresholds: leftover >= 40 is a "half-bin", still valuable
    if post_residual >= 40 {
        score -= 25.0;
    } else if post_residual >= 20 {
        score -= 10.0;
    } else if post_residual < 10 && post_residual > 0 {
        // penalize creating sub-10 dead space
        score += 20.0;
    }

    // Lookahead coupling: if next item fits in post_residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let lookahead_fit = (post_residual - next_item_size) as f64;
        score -= 40.0 - 0.2 * lookahead_fit;
    } else if next_item_size > 0 && next_item_size <= bin_residual {
        // next item could fit here but we'd leave a bad split
        score += 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate logic: only attractive if no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // prefer new bin when open bins are fragmented (low mean residual)
        // and many bins are open (consolidation unlikely)
        let fragmentation = 1.0 - pressure;
        let open_factor = (open_bins_count as f64).min(20.0) / 20.0;
        score += 45.0 * pressure - 30.0 * fragmentation * open_factor;
        // late in stream, opening new bins is cheaper than fragmenting
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * progress;
        // penalty baseline so a decent existing fit beats a new bin
        score += 55.0;
    }

