        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 { nb += 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { nb -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { nb -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { nb += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { nb += 3.0; }
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && item_size + next_item_size <= bin_capacity && mean_residual > 28.0 && remaining > 60 { nb -= 1.8; }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size
            && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { nb += 3.5; }
        if next_item_size > 0 && fitting_bins_count > 0 && next_item_size > item_size
            && remaining > 50 && mean_residual > 20.0 { nb -= 1.2; }
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { nb -= 1.5; }
        if remaining < 15 && fitting_bins_count > 0 { nb += 3.0; }
        // gen 66: open a fresh bin when every fitting bin would strand frag just under next item
        if next_item_size > 0 && fitting_bins_count > 0 && frag > 0.0
            && frag < next_item_size as f64 && remaining > 60 { nb -= 2.0; }
        score += nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strong reward for exact / near-exact fit (dead space minimization)
    if post == 0 {
        score -= 40.0;
    } else if post <= 5.0 {
        score -= 25.0;
    } else if post <= 10.0 {
        score -= 12.0;
    }

    // 2-step lookahead: reward residuals that can still host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            // post_residual - next_item_size = leftover after two placements
            let two_step_left = post - nxt;
            score -= 15.0 * (1.0 - two_step_left / cap);
            if two_step_left <= 5.0 {
                score -= 10.0; // perfect 2-item packing
            }
        } else {
            // next item won't fit here; penalize proportionally to the gap
            score += 8.0 + 0.25 * (nxt - post);
        }
    } else {
        // last item: prefer minimal residual, exact fit heavily rewarded
        score -= 20.0 * (1.0 - post / cap);
    }

    // Relative-to-mean coupling: prefer bins tighter than the average residual
    score += 0.35 * (mean_residual - post);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 1
            || (fitting_bins_count == 1 && post <= 10.0);
        if good_fit_exists {
            score += 60.0; // discourage opening new bin
        } else {
            score -= 5.0; // slight preference for fresh bin over bad fit
        }
    }

    // Mild pressure to consolidate into fewer bins as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * progress * post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
