pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (waste almost nothing).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0 + 4.0 * (5 - post_residual) as f64;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Penalize dead space relative to what the bin already had.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness;

    // Lookahead: reward if next item fits in the resulting residual,
    // penalize if the residual is awkwardly small for the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly-ish here; reward proportionally
            let nfit = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * nfit;
        } else {
            // residual becomes dead space for the next item
            let waste = (post_residual as f64) / (bin_capacity as f64);
            score += 15.0 * waste;
        }
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Global state: when many bins are open with high mean residual,
    // prefer consolidation into existing bins rather than opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let consolidation = (mean_residual / bin_capacity as f64) * (1.0 - 0.5 * progress);
    score -= 10.0 * consolidation;

    // Penalize opening a new bin when open bins already have plenty of room.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost, plus extra penalty if existing
        // bins fit the item well.
        score += 40.0;
        if fitting_bins_count > 0 {
            let spread = (mean_residual - item_size as f64).abs();
            score += 30.0 + 0.2 * spread;
        }
        // Early in the stream, opening bins is cheaper (builds diversity).
        score -= 25.0 * (1.0 - progress);
    }

    // Mild penalty for too many open bins late in the stream.
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = pr as f64 - item_size as f64;
    let remaining = total_items.saturating_sub(step_index);

    // Dead-space avoidance: small unusable gaps heavily penalized (class-style ladder).
    if pr > 0 && pr < 10 {
        score += 60.0 - 15.0;
    } else if pr < 25 {
        score += 25.0 * (1.0 - pr as f64 / 25.0);
    } else if pr <= 40 {
        score += 4.0;
    } else if pr <= 60 {
        score += 8.0;
    } else {
        score += 12.0;
    }

    // Reward near-perfect fills.
    if pr == 0 {
        score -= 60.0;
    }

    // Reusability bonus: residuals that are round multiples are easier to fill later.
    let reusable = (pr % 10 == 0) as f64 * 4.0 + (pr % 20 == 0) as f64 * 3.0 + (pr % 25 == 0) as f64 * 2.0 + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Lookahead: dead space worse if next item cannot use the post-residual.
    if next_item_size > 0 {
        if next_item_size > pr && pr > 0 {
            score += 12.0 + (next_item_size - pr) as f64 * 0.15;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 8.0 + 8.0 / (1.0 + slack as f64);
            if slack == 0 { score -= 4.0; }
            if slack >= 1 && slack <= 12 {
                score -= 3.0 * (1.0 - slack as f64 / 12.0);
            }
            if slack > 0 && slack < item_size.min(next_item_size) {
                score += 2.0;
            }
            if slack > 45 {
                score += (slack as f64 - 45.0) * 0.05;
            }
            // slack that itself fits next item again: good multi-split potential
            if slack >= next_item_size {
                score -= 2.5;
            }
        }
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 6 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 6.0);
        }
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        if pr > 0 && pr % next_item_size == 0 {
            score -= 1.5;
        }
        if frag > 0.0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && remaining > 80 {
            score += (frag - next_item_size as f64) * 0.07;
        }
        if frag > 0.0 && frag as u32 == next_item_size {
            score -= 4.5;
        }
        if frag > 0.0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 {
                score -= 2.2 - rem as f64 * 0.6;
            }
        }
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && mean_residual < 16.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
        // NEW: reward frag that is an exact small multiple of next item (future perfect splits)
        if frag > 0.0 && frag as u32 % next_item_size == 0 && frag <= next_item_size as f64 * 3.0 {
            score -= 1.5;
        }
        // NEW: penalize residual just below next item (guaranteed dead space next step)
        if pr > 0 && pr < next_item_size && pr < item_size.min(next_item_size) {
            score += 1.5 + (next_item_size - pr) as f64 * 0.05;
        }
        // NEW: dead zone gap 15..25 above next item scaled by mean residual
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap >= 15 && gap <= 25 && mean_residual > 22.0 {
                score += (gap as f64 - 15.0) * 0.10;
            }
        }
    }

    // Open-bin pressure: prefer tighter packing when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Bias toward bins with larger residuals (better long-term hosts).
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr as f64 * 0.3 * progress;

    // Large frag that will likely never be filled, scaled by remaining stream.
    if frag > 40.0 && remaining > 60 {
        score += (frag - 40.0) * 0.05;
    }
    if frag > 0.0 && frag <= 2.0 {
        score -= 3.0;
    }

    // NEW-BIN CANDIDATE logic (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        score += 8.0 + crowding * 6.0;
        if fitting_bins_count == 0 {
            score += 40.0;
        } else {
            score += 4.0;
        }
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        if item_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
        if remaining < 15 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 {
            score -= 1.5;
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 4.0;
        }
        if mean_residual > 28.0 && remaining > 100 {
            score -= 2.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 {
            score -= 3.0;
        }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2 && item_size + next_item_size <= bin_capacity && mean_residual > 28.0 && remaining > 60 {
            score -= 1.8;
        }
        // NEW: resist new bin when some open bin closes exactly on next item
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 {
            score += 2.0;
        }
        // NEW: open new bin when mean residual is high and many open bins are unusable hosts
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0 && open_bins_count.saturating_sub(fitting_bins_count) > 2 {
            score -= 1.5;
        }
        // NEW: resist new bin when stream ends soon and mean residual is small relative to item
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 4.0;
        }
    } else {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;
    // Non-linear coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    score -= 12.0 * fill * fill * (0.5 + 0.5 * progress);
    score -= 8.0 * (pr / cap) * (1.0 - (pr / cap)) * (1.0 - prog3);
    // Penalize dead space that shrinks as stream progresses
    score += (pr * pr) / (cap * (1.0 + 4.0 * progress));
    // Reward tight fits more strongly late in the stream
    score -= (item_size as f64 / cap) * (1.0 + 6.0 * prog2);
    // Lookahead: favor bins whose residual matches next item
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - gap / cap) * (1.0 - progress);
    } else if next_item_size > post_residual {
        score += 3.0 * (1.0 - progress);
    }
    // Last-chance bin pressure
    if fitting_bins_count == 1 {
        score -= 10.0 * (0.3 + 0.7 * progress);
    }
    // Mean residual coupling: avoid outliers relative to mean
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;
    // Mild penalty for spreading across many bins early
    score += (open_bins_count as f64) * 0.02 * (1.0 - progress);
    // New-bin candidate: penalize unless residual very small elsewhere
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (1.0 - progress) - 0.05 * mean_residual;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
