        }
        if pr > 0 && pr % next_item_size == 0 { score -= 1.5; }
        if pr > 0 && pr < next_item_size && pr < item_size.min(next_item_size) {
            score += 1.5 + (next_item_size - pr) as f64 * 0.05;
        }
        // reward bins whose residual is a near-exact sum of next item and a small filler
        if pr >= next_item_size {
            let rem = pr - next_item_size;
            if rem > 0 && rem <= item_size.min(8) { score -= 2.0 - rem as f64 * 0.2; }
        }
        // near-exact chain next step: frag within 3 of next item
        if frag > 0.0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        // dead-zone penalty sharpened when mean residual is low (few absorption chances)
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && mean_residual < 16.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
    }

    // Frag-based dead-space shaping
    if frag > 0.0 {
        if frag < item_size.min(15) as f64 { score += 4.0 + (15.0 - frag) * 0.15; }
        if next_item_size > 0 && (frag as u32) == next_item_size { score -= 4.5; }
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
        }
        if frag >= 20.0 && frag <= 35.0 && remaining > 80 && next_item_size > 0 && next_item_size < frag as u32 {
            score += (frag - 20.0) * 0.045;
        }
        let mr = mean_residual.max(1.0);
        if frag > mr * 1.5 && open_bins_count > 3 { score += (frag - mr * 1.5) * 0.06; }
        if next_item_size > 0 && frag as u32 > next_item_size * 2 && pr > 30 {
            score += (frag - next_item_size as f64) * 0.045;
