    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class: residual modulo 10 defines usability classes.
    let class = post_residual % 10;
    // Small remainders (<10) are dead space under integer sizes >=1... but items can be 1..100,
    // so treat classes 0 and >=10-friendly. Penalize awkward classes.
    score -= match class {
        0 => 12.0,               // perfectly closed bin
        1 | 2 => 2.0,            // nearly dead
        3..=6 => 5.0,            // hard to reuse
        _ => 8.0,                // class 7..9 decent for small items
    };

    // Lookahead pairing: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let pair_waste = post_residual - next_item_size;
            // reward tight pairing; harmonic bonus if pair closes a class
            score -= 15.0 - pair_waste as f64 * 0.4;
            if (post_residual % 10) == ((post_residual - next_item_size) % 10) && next_item_size % 10 == 0 {
                score -= 6.0;
            }
        } else if next_item_size > post_residual && next_item_size <= post_residual + 10 {
            // near-miss: next item almost fits, mild penalty for blocking
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has high residual; make it attractive
    // only when current fit is poor.
    if bin_residual == bin_capacity {
        score = (bin_capacity as f64) * 0.9
            - (fitting_bins_count as f64) * 3.0
            + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // opening fresh bin is good if item barely fits nowhere
            if fitting_bins_count == 0 {
                score -= 25.0;
            }
        }
    }

    // Tight fit reward: waste fraction of capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 10.0;

    // Slight preference to fill older bins as stream progresses (keep mean residual low).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (mean_residual - post_residual as f64).abs() * 0.05 * (0.5 + progress);

    score
}

