pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Dead-space penalty: small unusable gaps are heavily punished.
    if post > 0.0 && post < 10.0 {
        score += 60.0 * (10.0 - post) / 10.0;
    } else if post == 0.0 {
        score -= 25.0; // perfect fit reward
    }

    // Prefer bins whose residual tightly matches the item.
    let tight = (bin_residual as f64 - item_size as f64) / cap;
    score += 30.0 * tight;

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 8.0 * (1.0 - (post - nxt) / cap);
        } else if post > 0.0 {
            score += 10.0; // blocks the next item
        }
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += 1.5 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no tight fit exists.
    if bin_residual == bin_capacity {
        score += 45.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count >= 1 {
            score += 25.0;
