    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact / tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward when the NEXT item fits the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // perfect chain: this placement enables a perfect follow-up
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it fills the leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fill;
            // extra reward if post_residual - next_item is nearly zero
            let chain_residual = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - chain_residual / bin_capacity as f64);
        } else {
            // next item will NOT fit here: penalize leaving a residual
            // that is "just barely too small" (wasted dead space)
            let gap = (next_item_size - post_residual) as f64;
            if gap < 20.0 {
                score += 12.0 * (1.0 - gap / 20.0);
            }
        }
    }

    // Reward bins whose residual is already below average (consolidating space)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;
    } else {
        score += 3.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a brand-new bin when open bins could still fit the item,
    // unless the current item is large and residual space is plentiful
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            let waste = bin_residual as f64 - item_size as f64;
            // new bin is only attractive if it enables a very tight fit
            if waste > 15.0 {
                score += 18.0;
            } else {
                score += 4.0;
            }
        }
        // slight late-stream preference to consolidate into existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * progress;
    }

    // Mild penalty for scattering across many open bins
    score += 0.15 * open_bins_count as f64;

    score
}

