pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space relative to capacity
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, strongly favor this bin
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize if we leave large dead space
            score += 8.0 * waste_frac;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Global pressure: many open bins with high mean residual -> prefer consolidating
    let pressure = mean_residual / bin_capacity as f64;
    if bin_residual < bin_capacity {
        score -= 10.0 * pressure * (open_bins_count as f64).ln().max(1.0);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (large mean residual spread) or early in stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // base cost of a fresh bin, modulated by stream progress and open count
        score = bin_capacity as f64 * 0.55 + 15.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative, must open
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score += 20.0; // future items likely need fresh space anyway
        }
    }

    // Small dynamic jitter-free time coupling: slightly prefer filling older bins
    if bin_residual < bin_capacity {
        score -= 3.0 * (1.0 - progress);
    }

    score
}

