        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size <= bin_capacity && mean_residual > 20.0 { score += 1.5; }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && next_item_size > item_size && next_item_size - item_size <= 4 && remaining > 50 {
            score -= 2.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
