        if next_item_size > 0 && fitting_bins_count > 0 && next_item_size > item_size
            && remaining > 50 && mean_residual > 20.0 { score -= 1.2; }
    } else {
        // gen 68: strong guard so non-new-bin candidates never beat a forced new-bin when nothing fits
        if fitting_bins_count == 0 { score += 60.0; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 residue relative to capacity fraction.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let residue_class = post_residual % 10;
    let harmonic_bonus = match residue_class {
        0 => 12.0, // perfectly decadal residual: highly reusable
        1 | 9 => 8.0,
        2 | 8 => 5.0,
        3 | 7 => 2.0,
        4 | 6 => -2.0,
        _ => -5.0, // residue 5: least compatible with typical sizes
    };
    score -= harmonic_bonus;

    // Integer-division threshold on post_residual: dead-space zones.
    if post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual <= 20 {
        score -= 6.0; // sweet spot: fits smallest items
    } else if post_residual > 60 {
        score += 4.0; // large leftover suggests poor packing
    }

    // Lookahead coupling: next item fits exactly into post_residual -> strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: avoid opening new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize mildly, but allow it when existing residuals are large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_penalty = 18.0 + 20.0 * (1.0 - progress) - (mean_residual - pr) * 0.2;
        score += new_bin_penalty.max(0.0);
    }

    // Prefer bins tighter than the mean residual (good fill).
    score += (mean_residual - pr) * 0.1;

    // Slight preference for fewer open bins overall.
    score += open_bins_count as f64 * 0.05;

    score
}

