        if pr > 0 && pr % next_item_size == 0 { score -= 1.5; }
        if pr > 0 && pr < next_item_size && pr < item_size.min(next_item_size) {
            score += 1.5 + (next_item_size - pr) as f64 * 0.05;
        }
        // reward bins whose residual is a near-exact sum of next item and a small filler
        if pr >= next_item_size {
            let rem = pr - next_item_size;
            if rem > 0 && rem <= item_size.min(8) { score -= 2.0 - rem as f64 * 0.2; }
        }
        // gen 69: near-exact chain next step — frag within 3 of next item
        if frag > 0.0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        // gen 69: tight two-step chain — frag splits into next item plus tiny remainder
        if frag > 0.0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 { score -= 2.2 - rem as f64 * 0.6; }
        }
        // gen 69: penalize frag just barely too small for next item (guaranteed dead space)
        if frag > 0.0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        // gen 69: chain-fit scarcity bonus — reward tight fits when few bins fit
        if pr >= next_item_size && (pr - next_item_size) as f64 <= 2.0 && fitting_bins_count <= 2 {
            score -= 3.0;
        }
    }

    // Frag-based dead-space shaping
    if frag > 0.0 {
        if frag < item_size.min(15) as f64 { score += 4.0 + (15.0 - frag) * 0.15; }
        if next_item_size > 0 && (frag as u32) == next_item_size { score -= 4.5; }
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
        }
        if frag >= 20.0 && frag <= 35.0 && remaining > 80 && next_item_size > 0 && next_item_size < frag as u32 {
            score += (frag - 20.0) * 0.045;
        }
        let mr = mean_residual.max(1.0);
        if frag > mr * 1.5 && open_bins_count > 3 { score += (frag - mr * 1.5) * 0.06; }
        if next_item_size > 0 && frag as u32 > next_item_size * 2 && pr > 30 {
            score += (frag - next_item_size as f64) * 0.045;
        }
        if next_item_size > 0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 { score -= 2.2 - rem as f64 * 0.6; }
        }
        if next_item_size > 0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        if next_item_size > 0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        if next_item_size > 0 && frag as u32 % next_item_size == 0 && frag <= next_item_size as f64 * 3.0 {
            score -= 1.5;
        }
        if next_item_size > 0 && frag > next_item_size as f64 && frag < 30.0 && remaining > 60 {
            score += (frag - next_item_size as f64) * 0.05;
        }
        // dead-space ratio — penalize frag far above next item when stream is long
        if next_item_size > 0 && frag > next_item_size as f64 && remaining > 120 {
            score += (frag - next_item_size as f64) * 0.03;
        }
        // gen 69: sharpen the (next, 2*next) dead-zone gap when mean residual is low
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0
            && mean_residual < 16.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
        // reward near-closing frag (tiny remainder)
        if frag <= 2.0 { score -= 3.0; }
        // penalize large frag that will likely never be filled
        if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }
        // exact-fill reward
        if frag == 0.0 { score -= 4.0; }
        // gen 69: small-frag divisibility reward — residual splits cleanly into future items
        if next_item_size > 0 && frag <= 10.0 && (frag as u32) >= next_item_size.min(10) {
            score -= 1.2;
        }
        // gen 69: mid-range frag that fits neither next item nor closes soon
        if frag > 10.0 && frag < 20.0 && next_item_size > frag as u32 {
            score += (frag - 10.0) * 0.12;
        }
    }

    // Scarcity pressure
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 6.0;
    } else if fitting_bins_count >= 5 {
        score += 2.0;
    }

    // Global residual context
    if mean_residual > 25.0 && pr > mean_residual as u32 {
        score += 3.0;
    } else if mean_residual < 12.0 && pr > 0 && pr <= item_size * 2 {
        score -= 2.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size <= bin_capacity && mean_residual > 20.0 { score += 1.5; }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && next_item_size > item_size && next_item_size - item_size <= 4 && remaining > 50 {
            score -= 2.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
        // resist new bin when an open bin can absorb item plus next item exactly
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size == bin_capacity { score += 3.0; }
        // open new bin in awkward mid dead zone on very long streams
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        // resist new bin late when open bins suffice
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
        // gen 69: resist new bin when many open bins can each still absorb next item (avoid sprawl)
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining > 40 && remaining < 120 {
            score += 1.5;
        }
        // gen 69: resist new bin when mean residual closely matches next item (open bins will close cleanly)
        if next_item_size > 0 && mean_residual >= next_item_size as f64
            && mean_residual - next_item_size as f64 <= 4.0 && fitting_bins_count >= 2 {
            score += 2.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal: strongly reward post_residual == 0.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Penalize unusable small gaps: residuals in (0, 10] can hold nothing
        // (items >= 1 though, so scale by min item size ~ small threshold).
        if post_residual < 8 {
            score += 25.0;
        } else if post_residual < 15 {
            score += 10.0;
        }
        // Reward leaving gaps that could fit a plausibly-sized future item.
        // Use mean_residual as a proxy for typical leftover scale.
        let gap_useful = post_residual as f64 >= (next_item_size as f64).min(mean_residual.max(1.0));
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 6.0; // leaves room for the known next item
        } else if !gap_useful && post_residual > 0 {
            score += 5.0; // gap likely dead
        }
    }

    // Prefer tight fits: smaller post_residual relative to item size is better.
    score += (item_size as f64) * (post_residual as f64) / (bin_capacity as f64) * 2.0;

    // Open-bin pressure: when many bins are open, discourage spreading to new bins;
    // when few bins are open, opening a new bin is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.7 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize by pressure, but discount when this bin
        // is the last fitting option (avoid forcing bad fits).
        score += 12.0 + pressure;
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 4.0; // new bin will have room for next item too
        }
    } else {
        // Existing bin: reward using it, more so under high pressure.
        score -= 3.0 + pressure * 0.1;
        if fitting_bins_count == 1 {
            score -= 10.0; // last-chance bin: strong preference to use it
        }
    }

    // Mild preference for bins below mean residual (keeps residuals balanced).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = pr as f64 - item_size as f64;
    let remaining = total_items.saturating_sub(step_index);

    // Dead-space avoidance: small unusable gaps heavily penalized.
    if pr > 0 && pr < 10 {
        score += 60.0;
    } else if pr < 25 {
        score += 25.0 * (1.0 - pr as f64 / 25.0);
    }

    // Reward near-perfect fills.
    if pr == 0 {
        score -= 60.0;
    }

    // Reusability bonus: residuals that are round multiples are easier to fill later.
    let reusable = (pr % 10 == 0) as f64 * 4.0 + (pr % 20 == 0) as f64 * 3.0 + (pr % 25 == 0) as f64 * 2.0 + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Lookahead: dead space worse if next item cannot use the post-residual.
    if next_item_size > 0 {
        if next_item_size > pr && pr > 0 {
            score += 12.0 + (next_item_size - pr) as f64 * 0.15;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 8.0 + 8.0 / (1.0 + slack as f64);
            if slack == 0 { score -= 4.0; }
            if slack >= 1 && slack <= 12 {
                score -= 3.0 * (1.0 - slack as f64 / 12.0);
            }
            if slack > 0 && slack < item_size.min(next_item_size) {
                score += 2.0;
            }
            if slack > 45 {
                score += (slack as f64 - 45.0) * 0.05;
            }
            // combined feature: slack large enough to host next item again
            if slack >= next_item_size {
                score -= 2.5;
            }
        }
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 8 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 8.0);
        }
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        if pr > 0 && pr % next_item_size == 0 {
            score -= 1.5;
        }
        if frag > 0.0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && remaining > 80 {
            score += (frag - next_item_size as f64) * 0.07;
        }
        if frag > 0.0 && frag as u32 == next_item_size {
            score -= 4.5;
        }
        if frag > 0.0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 {
                score -= 2.2 - rem as f64 * 0.6;
            }
        }
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && mean_residual < 16.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
        // residual just below next item: guaranteed dead space next step
        if pr > 0 && pr < next_item_size && pr < item_size.min(next_item_size) {
            score += 1.5 + (next_item_size - pr) as f64 * 0.05;
        }
        // reward frag that is a small multiple of next item (perfect future splits)
        if frag > 0.0 && frag as u32 % next_item_size == 0 && frag <= next_item_size as f64 * 3.0 {
            score -= 1.5;
        }
        // reward near-exact chain: frag within 3 of next item
        if frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        // two-step exact chain via frag: frag == next + item
        if frag > 0.0 && frag as u32 == next_item_size + item_size.min(frag as u32) && frag as u32 > next_item_size {
            score -= 2.0;
        }
        // dead zone 25..45 after next item
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 {
                score += (gap as f64 - 25.0) * 0.08;
            }
        }
        // awkward 20..35 frag zone on long streams
        if frag >= 20.0 && frag <= 35.0 && remaining > 80 && next_item_size < frag as u32 {
            score += (frag - 20.0) * 0.045;
        }
        // can host next item twice with near-zero slack
        if pr >= next_item_size * 2 {
            let d2 = pr - next_item_size * 2;
            if d2 <= 3 {
                score -= 2.0 - d2 as f64 * 0.5;
            }
        }
    }

    // Open-bin pressure: prefer tighter packing when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Bias toward bins with larger residuals (better long-term hosts).
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr as f64 * 0.3 * progress;

    // Large frag that will likely never be filled, scaled by remaining stream.
    if frag > 40.0 && remaining > 60 {
        score += (frag - 40.0) * 0.05;
    }
    if frag > 0.0 && frag <= 2.0 {
        score -= 3.0;
    }
    // frag == 0: perfect close
    if frag == 0.0 {
        score -= 4.0;
    }
    // dead-space ratio: frag exceeds usable next-item fit by a large ratio
    if next_item_size > 0 && frag > 0.0 {
        let usable = next_item_size.min(frag as u32) as f64;
        let dead_ratio = usable / frag.max(1.0);
        if dead_ratio < 0.5 && frag > 12.0 && remaining > 30 {
            score += (frag - 12.0) * 0.06 * (1.0 - dead_ratio);
        }
    }

    // NEW-BIN CANDIDATE logic (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        score += 8.0 + crowding * 6.0;
        if fitting_bins_count == 0 {
            score += 40.0;
        } else {
            score += 4.0;
        }
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        if item_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
        if remaining < 15 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 {
            score -= 1.5;
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 4.0;
        }
        if mean_residual > 28.0 && remaining > 100 {
            score -= 2.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 {
            score -= 3.0;
        }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2 && item_size + next_item_size <= bin_capacity && mean_residual > 28.0 && remaining > 60 {
            score -= 1.8;
        }
        // resist new bin when many fitting bins exist and mean residual matches next item closely
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 {
            score += 2.0;
        }
        // open new bin when mean residual is high and only a few bins fit (reduce sprawl dead space)
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0 && open_bins_count.saturating_sub(fitting_bins_count) > 2 {
            score -= 1.5;
        }
        // resist new bin near stream end when a fitting bin leaves less than item size
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 4.0;
        }
        // open new bin for mid-size items when next is larger and mean residual is high
        if next_item_size > 0 && next_item_size > item_size && remaining > 50 && mean_residual > 20.0 {
            score -= 1.2;
        }
        // small next item with open bins able to absorb it: resist new bin
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 {
            score += 3.0;
        }
    } else {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: bin becomes exactly reusable for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item can still fit with modest slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Dead space relative to the next item: penalize small unusable leftovers harder.
        let dead = (next_item_size - post_residual) as f64;
        score += 1.5 * dead;
    }

    // Compare against mean residual: bins tighter than average are better targets.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 45.0;
    }

    // Prefer filling bins as the stream progresses (reduce open-bin sprawl late).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = if pr >= item_size { (pr - item_size) as f64 } else { 0.0 };
    let remaining = total_items.saturating_sub(step_index);

    // Residual class ladder (tightened)
    let class: f64 = if pr == 0 { -48.0 }
        else if pr <= 6 { -17.0 }
        else if pr <= 12 { -8.0 }
        else if pr <= 20 { -2.5 }
        else if pr <= 32 { 2.0 }
        else if pr <= 50 { 6.5 }
        else if pr <= 70 { 10.0 }
        else { 14.0 };
    score += class;

    // Reusability bonus
    let reusable = (pr % 10 == 0) as f64 * 4.0
        + (pr % 20 == 0) as f64 * 3.0
        + (pr % 25 == 0) as f64 * 2.0
        + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Dead residual just below item size — guaranteed waste
    if pr > 0 && pr < item_size.min(20) {
        score += 6.0;
    }

    // Lookahead coupling with next item.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 6.0; }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 40.0 { score += (slack - 40.0) * 0.06; }
            if slack <= 3.0 { score -= 1.0 * (1.0 - slack / 3.0); }
            if slack >= next_item_size as f64 { score -= 2.5; }
        } else {
            let gap = (next_item_size - pr) as f64;
            let soft = if pr <= 10 { 0.5 } else { 1.0 };
            score += (5.0 + gap * 0.09) * soft;
            if gap <= 4.0 && pr > 0 { score += (4.0 - gap) * 0.9; }
        }
        if item_size.saturating_add(next_item_size) == pr { score -= 6.0; }
        let triple = item_size.saturating_add(next_item_size * 2);
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        let quad = item_size.saturating_add(next_item_size * 3);
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        if pr >= next_item_size * 2 {
            let d2 = pr - next_item_size * 2;
            if d2 <= 3 { score -= 2.0 - d2 as f64 * 0.5; }
        }
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 { score += (gap as f64 - 25.0) * 0.08; }
            if gap >= 15 && gap <= 25 && mean_residual > 22.0 {
                score += (gap as f64 - 15.0) * 0.10;
            }
        }
        if pr > 0 && pr % next_item_size == 0 { score -= 1.5; }
        if pr > 0 && pr < next_item_size && pr < item_size.min(next_item_size) {
            score += 1.5 + (next_item_size - pr) as f64 * 0.05;
        }
        // reward bins whose residual is a near-exact sum of next item and a small filler
        if pr >= next_item_size {
            let rem = pr - next_item_size;
            if rem > 0 && rem <= item_size.min(8) { score -= 2.0 - rem as f64 * 0.2; }
        }
        // gen 69: chain-fit reward — residual that hosts item then next item with tiny slack
        if pr >= item_size + next_item_size {
            let chain_slack = pr - item_size - next_item_size;
            if chain_slack <= 3 { score -= 2.5 - chain_slack as f64 * 0.6; }
        }
    }

    // Frag-based dead-space shaping
    if frag > 0.0 {
        if frag < item_size.min(15) as f64 { score += 4.0 + (15.0 - frag) * 0.15; }
        if next_item_size > 0 && (frag as u32) == next_item_size { score -= 4.5; }
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
        }
        if frag >= 20.0 && frag <= 35.0 && remaining > 80 && next_item_size > 0 && next_item_size < frag as u32 {
            score += (frag - 20.0) * 0.045;
        }
        let mr = mean_residual.max(1.0);
        if frag > mr * 1.5 && open_bins_count > 3 { score += (frag - mr * 1.5) * 0.06; }
        if next_item_size > 0 && frag as u32 > next_item_size * 2 && pr > 30 {
            score += (frag - next_item_size as f64) * 0.045;
        }
        if next_item_size > 0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 { score -= 2.2 - rem as f64 * 0.6; }
        }
        if next_item_size > 0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        if next_item_size > 0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        if next_item_size > 0 && frag as u32 % next_item_size == 0 && frag <= next_item_size as f64 * 3.0 {
            score -= 1.5;
        }
        if next_item_size > 0 && frag > next_item_size as f64 && frag < 30.0 && remaining > 60 {
            score += (frag - next_item_size as f64) * 0.05;
        }
        // dead-space ratio — penalize frag far above next item when stream is long
        if next_item_size > 0 && frag > next_item_size as f64 && remaining > 120 {
            score += (frag - next_item_size as f64) * 0.03;
        }
        // reward near-closing frag (tiny remainder)
        if frag <= 2.0 { score -= 3.0; }
        // penalize large frag that will likely never be filled
        if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }
        // exact-fill reward
        if frag == 0.0 { score -= 4.0; }
        // gen 69: dead-space ratio refinement — penalize frag in (next, 2*next) more sharply when mean residual is low
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0
            && mean_residual < 16.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
        // gen 69: reward frag that equals next item + item (perfect two-item chain next step)
        if next_item_size > 0 && frag as u32 == next_item_size + item_size.min(frag as u32) && frag as u32 > next_item_size {
            score -= 2.0;
        }
    }

    // Scarcity pressure
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 6.0;
    } else if fitting_bins_count >= 5 {
        score += 2.0;
    }

    // Global residual context
    if mean_residual > 25.0 && pr > mean_residual as u32 {
        score += 3.0;
    } else if mean_residual < 12.0 && pr > 0 && pr <= item_size * 2 {
        score -= 2.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size <= bin_capacity && mean_residual > 20.0 { score += 1.5; }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && next_item_size > item_size && next_item_size - item_size <= 4 && remaining > 50 {
            score -= 2.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
        // resist new bin when an open bin can absorb item plus next item exactly
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size == bin_capacity { score += 3.0; }
        // open new bin in awkward mid dead zone on very long streams
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        // resist new bin late when open bins suffice
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
        // gen 69: resist new bin when mean residual tightly matches next item on a long stream
        if next_item_size > 0 && mean_residual >= next_item_size as f64
            && mean_residual < next_item_size as f64 * 2.0 && remaining > 80 && fitting_bins_count > 0 {
            score += 2.0;
        }
        // gen 69: prefer new bin for large items when fitting bins would strand near-dead residuals
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && item_size + next_item_size <= bin_capacity && mean_residual > 28.0 && remaining > 60 {
            score -= 1.8;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to item size)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that few future items could use
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fill
    } else if post_residual >= 10 && post_residual < 20 {
        score += 5.0; // awkward dead zone
    }

    // Lookahead: reward if next item fits in the post residual (chained packing)
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else if next_item_size <= bin_residual {
            // next item fits this bin now but not after placing current item
            score += 10.0;
        }
        // exact chain: post_residual == next_item_size is ideal
        if next_item_size == post_residual {
            score -= 30.0;
        }
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 3 {
        score += 3.0 * (fitting_bins_count as f64 - 3.0);
    }

    // Prefer bins with residual below mean (consolidate small spaces)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // New-bin candidate handling: empty bin should only win when no open bin fits well
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 60.0; // forced new bin
        } else {
            // competing with existing bins: make new bin moderately attractive
            // more attractive early (future flexibility) and when mean residual is low
            let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
            score = score.min(45.0 + 40.0 * (1.0 - progress) + 0.2 * mean_residual);
        }
    }

    // Late stream: discourage spreading across many bins
    if open_bins_count > 8 && bin_residual != bin_capacity {
        score += 2.0 * (open_bins_count as f64 - 8.0).min(10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = pr as f64 - item_size as f64;
    let remaining = total_items.saturating_sub(step_index);

    // Class-style ladder with sharper small-residual rewards (borrowed from best).
    let class: f64 = if pr == 0 {
        -55.0
    } else if pr <= 8 {
        -15.0
    } else if pr <= 15 {
        -6.5
    } else if pr <= 25 {
        -1.0 + (25.0 - pr as f64) * 0.1
    } else if pr <= 40 {
        4.0
    } else if pr <= 60 {
        8.0
    } else {
        12.0
    };
    score += class;

    // Reusability bonus: residuals that are round multiples are easier to fill later.
    let reusable = (pr % 10 == 0) as f64 * 4.0 + (pr % 20 == 0) as f64 * 3.0 + (pr % 25 == 0) as f64 * 2.0 + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Penalize residual just below item size (guaranteed near-dead space).
    if pr > 0 && pr < item_size.min(20) {
        score += 6.0;
    }

    if next_item_size > 0 {
        if next_item_size > pr && pr > 0 {
            score += 12.0 + (next_item_size - pr) as f64 * 0.15;
        } else if next_item_size <= pr {
            let slack = pr - next_item_size;
            score -= 8.0 + 8.0 / (1.0 + slack as f64);
            if slack == 0 { score -= 4.0; }
            if slack >= 1 && slack <= 12 {
                score -= 3.0 * (1.0 - slack as f64 / 12.0);
            }
            if slack > 0 && slack < item_size.min(next_item_size) {
                score += 2.0;
            }
            if slack > 45 {
                score += (slack as f64 - 45.0) * 0.05;
            }
            if slack >= next_item_size {
                score -= 2.5;
            }
        }
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 6 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 6.0);
        }
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        if pr > 0 && pr % next_item_size == 0 {
            score -= 1.5;
        }
        if frag > 0.0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && remaining > 80 {
            score += (frag - next_item_size as f64) * 0.07;
        }
        if frag > 0.0 && frag as u32 == next_item_size {
            score -= 4.5;
        }
        if frag > 0.0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 {
                score -= 2.2 - rem as f64 * 0.6;
            }
        }
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && mean_residual < 16.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
        // Reward frag that is an exact small multiple of next item (future perfect splits)
        if frag > 0.0 && frag as u32 % next_item_size == 0 && frag <= next_item_size as f64 * 3.0 {
            score -= 1.5;
        }
        // Penalize residual just below next item (guaranteed dead space next step)
        if pr > 0 && pr < next_item_size && pr < item_size.min(next_item_size) {
            score += 1.5 + (next_item_size - pr) as f64 * 0.05;
        }
        // Dead zone gap 15..25 above next item scaled by mean residual
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap >= 15 && gap <= 25 && mean_residual > 22.0 {
                score += (gap as f64 - 15.0) * 0.10;
            }
            // Sharpen the 25..45 dead zone
            if gap > 25 && gap < 45 {
                score += (gap as f64 - 25.0) * 0.08;
            }
        }
        // Reward bins whose frag lands within 3 of next_item (near-exact chain next step)
        if frag > 0.0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        // Reward near-perfect two-step chain — frag splits into next item plus a tiny remainder
        if pr >= next_item_size * 2 {
            let d2 = pr - next_item_size * 2;
            if d2 <= 3 {
                score -= 2.0 - d2 as f64 * 0.5;
            }
        }
        // Two-step chain: residual can host next item then item again
        if next_item_size <= pr {
            let two_step = pr - next_item_size;
            if two_step >= item_size && item_size >= two_step - item_size {
                score -= 1.5;
            }
        }
    }

    // Open-bin pressure: prefer tighter packing when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Bias toward bins with larger residuals (better long-term hosts).
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Late in the stream, tighten packing further.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr as f64 * 0.3 * progress;

    // Large frag that will likely never be filled, scaled by remaining stream.
    if frag > 40.0 && remaining > 60 {
        score += (frag - 40.0) * 0.05;
    }
    if frag > 0.0 && frag <= 2.0 {
        score -= 3.0;
    }

    // NEW-BIN CANDIDATE logic (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        score += 8.0 + crowding * 6.0;
        if fitting_bins_count == 0 {
            score += 40.0;
        } else {
            score += 4.0;
        }
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        if item_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
        if remaining < 15 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 {
            score -= 1.5;
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 4.0;
        }
        if mean_residual > 28.0 && remaining > 100 {
            score -= 2.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 {
            score -= 3.0;
        }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2 && item_size + next_item_size <= bin_capacity && mean_residual > 28.0 && remaining > 60 {
            score -= 1.8;
        }
        // Resist new bin when some open bin closes exactly on next item
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 {
            score += 2.0;
        }
        // Open new bin when mean residual is high and many open bins are unusable hosts
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0 && open_bins_count.saturating_sub(fitting_bins_count) > 2 {
            score -= 1.5;
        }
        // Resist new bin when stream ends soon and mean residual is small relative to item
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 4.0;
        }
        // Open new bin when the only fitting bins would leave frag just under next item (guaranteed dead space)
        if next_item_size > 0 && fitting_bins_count > 0 && next_item_size > item_size && remaining > 50 && mean_residual > 20.0 {
            score -= 1.2;
        }
        // Resist new bin when next item is small and open bins can absorb it cleanly
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 {
            score += 3.0;
        }
    } else {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with progress-dependent weighting
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Smooth non-linear penalty on wasted residual (dead space grows quadratically)
    score += 40.0 * norm_pr * norm_pr * (1.0 - 0.5 * progress);

    // Interaction: residual vs mean residual of open bins — prefer bins below mean residual (tighter)
    let mean_norm = mean_residual / cap;
    score += 25.0 * (norm_pr - mean_norm) * (norm_pr - mean_norm) - 15.0 * norm_pr * mean_norm;

    // Lookahead coupling: reward leaving room for the next item, smoothly
    let nres = next_item_size as f64;
    if nres > 0.0 {
        let fit_gap = pr - nres;
        let s = 1.0 / (1.0 + (-fit_gap / 20.0).exp());
        score -= 30.0 * s * (1.0 - progress);
        score += 10.0 * (1.0 - s) * norm_pr;
    }

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0 * (1.0 + progress);
    }

    // Mild penalty for proliferating bins, smoothly scaled by progress
    score += open_bins_count as f64 * (0.5 + 2.0 * progress);

    // New-bin candidate: penalize slightly so it's chosen only when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 55.0 * (1.0 - 0.4 * progress) + 0.2 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    if bin_residual < item_size { return post_residual as f64 + 60.0; }
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = if pr >= item_size { (pr - item_size) as f64 } else { 0.0 };
    let remaining = total_items.saturating_sub(step_index);

    // Residual class ladder (tightened from best lineage)
    let class: f64 = if pr == 0 { -48.0 }
        else if pr <= 8 { -15.0 }
        else if pr <= 15 { -6.5 }
        else if pr <= 25 { -1.0 }
        else if pr <= 40 { 4.0 }
        else if pr <= 60 { 8.0 }
        else { 12.0 };
    score += class;

    // Reusability bonus
    let reusable = (pr % 10 == 0) as f64 * 4.0
        + (pr % 20 == 0) as f64 * 3.0
        + (pr % 25 == 0) as f64 * 2.0
        + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Dead residual just below item size — guaranteed waste
    if pr > 0 && pr < item_size.min(20) { score += 6.0; }

    // Lookahead coupling with next item.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 5.0; }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 45.0 { score += (slack - 45.0) * 0.05; }
            if slack <= 3.0 { score -= 1.0 * (1.0 - slack / 3.0); }
            if slack >= next_item_size as f64 { score -= 2.5; }
        } else {
            let gap = (next_item_size - pr) as f64;
            let soft = if pr <= 10 { 0.5 } else { 1.0 };
            score += (5.0 + gap * 0.09) * soft;
            if gap <= 4.0 && pr > 0 { score += (4.0 - gap) * 0.9; }
        }
        if item_size.saturating_add(next_item_size) == pr { score -= 6.0; }
        let triple = item_size.saturating_add(next_item_size * 2);
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        let quad = item_size.saturating_add(next_item_size * 3);
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        if pr >= next_item_size * 2 {
            let d2 = pr - next_item_size * 2;
            if d2 <= 3 { score -= 2.0 - d2 as f64 * 0.5; }
        }
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 { score += (gap as f64 - 25.0) * 0.08; }
            if gap >= 15 && gap <= 25 && mean_residual > 22.0 {
                score += (gap as f64 - 15.0) * 0.10;
            }
        }
        if pr > 0 && pr % next_item_size == 0 { score -= 1.5; }
        if pr > 0 && pr < next_item_size && pr < item_size.min(next_item_size) {
            score += 1.5 + (next_item_size - pr) as f64 * 0.05;
        }
        // reward bins whose residual is a near-exact sum of next item and a small filler
        if pr >= next_item_size {
            let rem = pr - next_item_size;
            if rem > 0 && rem <= item_size.min(8) { score -= 2.0 - rem as f64 * 0.2; }
        }
        // gen 70: reward tight two-step chain when fitting bins are scarce
        if pr >= next_item_size && (pr - next_item_size) as f64 <= 2.0 && fitting_bins_count <= 2 {
            score -= 3.0;
        }
    }

    // Frag-based dead-space shaping
    if frag > 0.0 {
        if frag < item_size.min(15) as f64 { score += 4.0 + (15.0 - frag) * 0.15; }
        if next_item_size > 0 && (frag as u32) == next_item_size { score -= 4.5; }
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
        }
        if frag >= 20.0 && frag <= 35.0 && remaining > 80 && next_item_size > 0 && next_item_size < frag as u32 {
            score += (frag - 20.0) * 0.045;
        }
        let mr = mean_residual.max(1.0);
        if frag > mr * 1.5 && open_bins_count > 3 { score += (frag - mr * 1.5) * 0.06; }
        if next_item_size > 0 && frag as u32 > next_item_size * 2 && pr > 30 {
            score += (frag - next_item_size as f64) * 0.045;
        }
        if next_item_size > 0 && frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 { score -= 2.2 - rem as f64 * 0.6; }
        }
        if next_item_size > 0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        if next_item_size > 0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        if next_item_size > 0 && frag as u32 % next_item_size == 0 && frag <= next_item_size as f64 * 3.0 {
            score -= 1.5;
        }
        if next_item_size > 0 && frag > next_item_size as f64 && frag < 30.0 && remaining > 60 {
            score += (frag - next_item_size as f64) * 0.05;
        }
        // dead-space ratio — penalize frag far above next item when stream is long
        if next_item_size > 0 && frag > next_item_size as f64 && remaining > 120 {
            score += (frag - next_item_size as f64) * 0.03;
        }
        // reward near-closing frag (tiny remainder)
        if frag <= 2.0 { score -= 3.0; }
        // penalize large frag that will likely never be filled
        if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }
        // exact-fill reward
        if frag == 0.0 { score -= 4.0; }
        // gen 70: dead-space ratio refinement — penalize frag in (next, 2*next) gap when mean residual is low
        if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0
            && mean_residual < 16.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
        // gen 70: reward bins whose frag equals next + item (perfect two-item chain next step)
        if next_item_size > 0 && frag as u32 > next_item_size
            && frag as u32 == next_item_size + item_size.min(frag as u32) {
            score -= 2.0;
        }
        // gen 70: penalize frag just barely too small for next item (dead space guaranteed)
        if next_item_size > 0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.4;
        }
    }

    // Scarcity pressure
    if fitting_bins_count <= 2 && bin_residual != bin_capacity {
        score -= 6.0;
    } else if fitting_bins_count >= 5 {
        score += 2.0;
    }

    // Global residual context
    if mean_residual > 25.0 && pr > mean_residual as u32 {
        score += 3.0;
    } else if mean_residual < 12.0 && pr > 0 && pr <= item_size * 2 {
        score -= 2.0;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size <= bin_capacity && mean_residual > 20.0 { score += 1.5; }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2
            && next_item_size > item_size && next_item_size - item_size <= 4 && remaining > 50 {
            score -= 2.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0
            && open_bins_count.saturating_sub(fitting_bins_count) > 2 { score -= 1.5; }
        // resist new bin when an open bin can absorb item plus next item exactly
        if next_item_size > 0 && fitting_bins_count > 0 && item_size + next_item_size == bin_capacity { score += 3.0; }
        // open new bin in awkward mid dead zone on very long streams
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        // resist new bin late when open bins suffice
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
        // gen 70: open new bin when the only fitting bins would leave frag just under next item (guaranteed dead space)
        if next_item_size > 0 && fitting_bins_count > 0 && remaining > 50 {
            let would_frag = bin_capacity.saturating_sub(item_size);
            if would_frag > 0 && would_frag < next_item_size && next_item_size - would_frag <= 4 { score -= 2.0; }
        }
        // gen 70: open new bin for mid-size items when mean residual is high and no bin closes tightly on next item
        if next_item_size > 0 && mean_residual > 24.0 && remaining > 80 && fitting_bins_count > 0
            && item_size + next_item_size <= bin_capacity { score -= 1.2; }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes over capacity.
    let pr = post_residual as i64;
    let cap = bin_capacity as i64;

    // Perfect fit -> overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals that cannot be filled by any plausible item.
    // Items are >= 1, but small residuals (< 10) are hard to fill exactly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic classes: classify post_residual by (cap - post_residual) mod 10
    // i.e. how "aligned" the used space is with common size classes.
    let used = cap - pr;
    let harmonic = used % 10;
    // Reward residuals that pair with typical item sizes (multiples of 5/10).
    if harmonic == 0 {
        score -= 12.0;
    } else if harmonic == 5 {
        score -= 6.0;
    } else {
        score += 3.0 + (harmonic as f64) * 0.8;
    }

    // Integer-division thresholds on post_residual: coarse capacity fractions.
    let quarter = cap / 4;
    let half = cap / 2;
    if pr > half {
        score -= 8.0; // bin still roomy, keep flexibility
    } else if pr > quarter {
        score += 4.0;
    } else if pr > 0 {
        score += 10.0; // nearly-full bin: fine if not dead space, else penalized above
    }

    // Lookahead coupling: prefer post_residual that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
            // exact class match: next item fills bin completely
            if post_residual == next_item_size {
                score -= 25.0;
            }
            // next item leaves a harmonic residual too
            let n_used = used + next_item_size as i64;
            if (cap - n_used) % 10 == 0 && n_used <= cap {
                score -= 8.0;
            }
        } else {
            // next item won't fit here; penalize mildly, more if bin is the only option
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && post_residual <= bin_residual {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when current fit is bad
    // and there is slack in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let bad_fit = item_size < quarter
            || (next_item_size > 0 && next_item_size > bin_residual && next_item_size > item_size);
        if bad_fit && open_bins_count > 2 && progress < 0.9 {
            score -= 20.0;
        } else {
            score += 25.0; // prefer existing bins by default
        }
    }

    // Mild diversity pressure: many open bins -> tighten packing.
    if open_bins_count > 4 {
        score += (open_bins_count as f64) * 0.4;
    }

    // Mean-residual coupling: if mean residual is large, reward filling this bin well.
    if mean_residual > 20.0 && post_residual < mean_residual as u32 {
        score -= 5.0;
    }

    score
}

