    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (below min item size) are worthless.
    if post_residual < 10 && post_residual > 0 {
        score += 50.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

