    let frag = (pr >= item_size) as u32 * (pr - item_size);
    let remaining = total_items.saturating_sub(step_index);

    // Residual class shaping (borrowed, tightened)
    let class: f64 = if pr == 0 { -48.0 } else if pr <= 8 { -15.0 } else if pr <= 15 { -6.5 } else if pr <= 25 { -1.0 } else if pr <= 40 { 4.0 } else if pr <= 60 { 8.0 } else { 12.0 };
    score += class;

    // Reward residuals that are clean multiples (easy future splits)
    let reusable = (pr % 10 == 0) as f64 * 4.0 + (pr % 20 == 0) as f64 * 3.0 + (pr % 25 == 0) as f64 * 2.0 + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    // Dead space just under next item is guaranteed waste
    if next_item_size > 0 && pr > 0 && pr < next_item_size && pr < item_size.min(next_item_size) {
        score += 1.5 + (next_item_size - pr) as f64 * 0.05;
    }

    // Two-step lookahead: reward bins that fit item then next item exactly
    if next_item_size > 0 && item_size + next_item_size == pr { score -= 6.0; }
    if next_item_size > 0 && pr >= item_size + next_item_size * 2 && pr - (item_size + next_item_size * 2) <= 4 { score -= 2.5; }

    // Reward frag that chains next item with tiny remainder
    if next_item_size > 0 && frag > next_item_size {
        let rem = frag - next_item_size;
        if rem <= 2 { score -= 2.2 - rem as f64 * 0.6; }
    }
    // Penalize frag just barely too small for next item
    if next_item_size > 0 && frag > 0 && frag < next_item_size && next_item_size - frag <= 4 {
        score += (next_item_size - frag) as f64 * 0.9;
    }
    // Penalize awkward mid-range frag in (next, 2*next)
    if next_item_size > 0 && frag > next_item_size && frag < next_item_size * 2 && frag > 8 {
        score += (frag - next_item_size) as f64 * 0.10;
        if mean_residual < 16.0 && remaining > 100 { score += (frag - next_item_size) as f64 * 0.08; }
    }
    // Large frag that likely never fills
    if frag > 40 && remaining > 60 { score += (frag - 40) as f64 * 0.05; }
    // Near-closing bins
    if frag > 0 && frag <= 2 { score -= 3.0; }
    if frag == 0 { score -= 4.0; }
    if next_item_size > 0 && frag as u32 == next_item_size { score -= 4.5; }
    // Perfect future splits: frag multiple of next item
    if next_item_size > 0 && frag > 0 && frag % next_item_size == 0 && frag <= next_item_size * 3 { score -= 1.5; }
    // Quad chain
    if next_item_size > 0 { let quad = item_size + next_item_size * 3; if pr >= quad && pr - quad <= 6 { score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0); } }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity { score -= 20.0; }
    // Bias toward larger residuals
    score -= (bin_residual as f64 - mean_residual) * 0.2;
    // Progress-scaled tightening
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr as f64 * 0.3 * progress;

    // NEW-BIN CANDIDATE LOGIC
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        score += 8.0 + crowding * 6.0 + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
        // new mutation: open bin eagerly when best fit would strand frag just under next item
        if next_item_size > 0 && fitting_bins_count > 0 && frag > 0 && frag < next_item_size && next_item_size - frag <= 4 && remaining > 80 { score -= 2.5; }
    } else {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (post_residual small), with quadratic waste penalty.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Lookahead reward: if the next item fits exactly (or very well) in the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 45.0 * (1.0 - slack / bin_capacity as f64);
        // Perfect pairing bonus
        if slack == 0.0 {
            score -= 30.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // Dead space that cannot serve the next item: penalize proportionally to tightness.
        score += 12.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly favor using it
    // rather than opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Global fragmentation pressure: if mean residual is high and this placement would
    // strand a small residual, penalize.
    let frag = if post_residual > 0 && post_residual < 10 {
        25.0
    } else {
        0.0
    };
    score += frag;

    // Time horizon: early in the stream, be more willing to open new bins (preserve
    // flexibility); late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate score: base cost of opening a bin, reduced early on,
        // increased late when consolidation matters.
        let mut new_bin_score = bin_capacity as f64 * 0.85;
        new_bin_score -= 25.0 * (1.0 - progress);
        // If mean residual across open bins is large, opening new bins is wasteful.
        new_bin_score += 0.6 * mean_residual;
        // If many bins already open, prefer consolidation.
        new_bin_score += 1.5 * open_bins_count as f64;
        // If lookahead item is small relative to the residual a fresh bin would leave,
        // a new bin is more attractive.
        if next_item_size > 0 {
            let fresh_residual = bin_capacity - item_size;
            if fresh_residual >= next_item_size {
                new_bin_score -= 10.0;
            }
        }
        // Last chance override: never open a new bin when this is the sole fitting bin.
        if fitting_bins_count == 1 {
            new_bin_score += 1000.0;
        }
        return new_bin_score;
    }

    // Mild preference for bins with larger residual being consumed by large items.
    score -= 0.1 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = pr.saturating_sub(item_size) as f64;
    let remaining = total_items.saturating_sub(step_index);

    // Dead-space penalty: small unusable gaps are worthless.
    if pr < 10 && pr > 0 {
        score += 50.0;
    } else if pr > 0 && pr < 20 {
        score += 25.0;
    }

    // Reward tight fits.
    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 40.0;
    }

    // Open-bin pressure: penalize spreading across many open bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: exact next-item fill is excellent.
    if next_item_size > 0 && next_item_size == pr {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size > pr {
        score += (pr as f64) * 0.5;
    }

    // Reusability bonus: residuals that are round multiples absorb future items cleanly.
    if pr > 0 {
        if pr % 10 == 0 { score -= 4.0; }
        if pr % 20 == 0 { score -= 3.0; }
        if pr % 25 == 0 { score -= 2.0; }
        if pr % 5 == 0 { score -= 1.0; }
    }

    // Two-step chain lookahead: item + next fits exactly.
    if next_item_size > 0 && item_size + next_item_size == pr {
        score -= 8.0;
    }
    // Near-exact two-step chain.
    if next_item_size > 0 && pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 3 {
        score -= 3.0 * (1.0 - (pr - (item_size + next_item_size)) as f64 / 3.0);
    }
    // Triple chain: item + next*2 fits with tiny slack.
    if next_item_size > 0 {
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 6 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 6.0);
        }
    }
    // Penalize frag just barely too small for next item (guaranteed dead space).
    if next_item_size > 0 && frag > 0.0 && frag < next_item_size as f64 && next_item_size as f64 - frag <= 4.0 {
        score += (next_item_size as f64 - frag) * 0.9;
    }
    // Penalize frag in the awkward (next, 2*next) gap on long streams.
    if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && remaining > 60 {
        score += (frag - next_item_size as f64) * 0.08;
    }
    // Reward frag that is an exact small multiple of next item (perfect future splits).
    if next_item_size > 0 && frag > 0.0 && (frag as u32) % next_item_size == 0 && frag <= next_item_size as f64 * 3.0 {
        score -= 2.0;
    }
    // Penalize large frag that will likely never be filled.
    if frag > 40.0 && remaining > 60 {
        score += (frag - 40.0) * 0.05;
    }
    // Progress-aware scaling of dead-space aversion.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr as f64 * (0.1 + 0.2 * progress);

    // New-bin candidate logic with adaptive pressure.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + if fitting_bins_count == 0 { 40.0 } else { 0.0 };
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        if fitting_bins_count > 0 {
            score += 4.0;
        }
        // Prefer new bin for large items when mean residual is mid-range (poor fits ahead).
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 {
            score -= 3.0;
        }
        // Resist new bin when stream is nearly over and open bins suffice.
        if remaining < 8 && fitting_bins_count > 0 {
            score += 5.0;
        }
        // Open new bin when existing bins would strand space just under next item.
        if next_item_size > 0 && fitting_bins_count > 0 && (mean_residual as u32) >= next_item_size
            && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
        // Open new bin when mean residual sits in the awkward 12..20 dead zone on a long stream.
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 {
            score -= 1.5;
        }
        // Resist new bin when mean residual closely matches next item (open bins will close cleanly).
        if next_item_size > 0 && (mean_residual as u32).saturating_sub(next_item_size) <= 3
            && mean_residual >= next_item_size as f64 && remaining > 40 {
            score += 2.0;
        }
        // Discourage new bin when many open bins can each absorb next item (avoid sprawl).
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
    } else {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Normalized post-residual
    let pr = post_residual as f64 / bin_capacity as f64;

    // Smooth non-linear coupling: penalize large residual more aggressively as stream progresses
    let coupling = pr * pr * (1.0 + progress * 2.0) * bin_capacity as f64;
    score += 0.5 * coupling;

    // Reward tight fits (small post_residual) with smooth polynomial
    let tightness = (1.0 - pr).powi(3);
    score -= 12.0 * tightness;

    // Penalize when post-residual cannot fit the lookahead item (smooth interaction)
    if next_item_size > 0 {
        let gap = next_item_size as f64 - post_residual as f64;
        if gap > 0.0 {
            let norm_gap = gap / bin_capacity as f64;
            score += 8.0 * norm_gap * norm_gap * bin_capacity as f64;
        } else {
            // Smooth reward for leaving room for the next item
            let room = (-gap) / bin_capacity as f64;
            score -= 6.0 * room * (1.0 - room);
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Slight penalty for proliferating bins relative to mean residual
    score += 0.02 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    // Penalize opening a new bin when a good fit exists elsewhere
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - pr) - 5.0 * progress * (mean_residual / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity fraction band does it land in?
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: residuals below half capacity are increasingly useless.
    let half = cap * 0.5;
    if pr < half {
        let dead_frac = (half - pr) / half; // 0..1
        score += 14.0 * dead_frac * dead_frac;
    }

    // Perfect / near-perfect fits get strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0 + 2.0 * (10 - post_residual) as f64;
    }

    // Harmonic class via integer division thresholds on post_residual:
    // quarters of capacity define "usable slots" for future items (min item ~ small).
    let quarter = cap * 0.25;
    let harmonic_class = (pr / quarter).floor() as i32; // 0..4
    score += match harmonic_class {
        0 => 10.0, // tiny residual: nearly dead
        1 => 4.0,
        2 => 0.0,
        3 => -6.0,
        _ => -10.0, // still very roomy
    };

    // Modulo coupling: does post_residual sit on a harmonic residue of capacity?
    let mod_res = post_residual % 25; // capacity/4 grid
    if mod_res == 0 && post_residual > 0 {
        score -= 8.0; // aligns with quarter-grid: likely to fit another harmonic item
    } else if mod_res >= 20 {
        score -= 3.0; // close to grid alignment
    } else if mod_res <= 5 && post_residual > 0 {
        score += 5.0; // awkward sliver above a grid line
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // how tightly does next item fit afterwards?
            let after2 = post_residual - next_item_size;
            score -= 12.0;
            if after2 <= 10 {
                score -= 10.0; // chains into a near-closed bin
            }
        } else {
            score += 6.0; // next item won't fit here: bin closes after this placement
            if post_residual == 0 {
                score -= 5.0; // ...but closes perfectly
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).min(4.0);
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Prefer it only when current item is huge relative to typical residuals
    // or late in the stream with many open bins.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowding = open_bins_count as f64 / (mean_residual.max(1.0) / 10.0 + 1.0);
        score = cap - item_size as f64; // baseline: waste equals item size in fresh bin
        score -= 8.0 * progress;
        score -= crowding.min(10.0);
        if item_size >= 60 {
            score -= 15.0; // big items start fresh bins more readily
        }
        // Never open a new bin when a perfect fit exists elsewhere is handled
        // by those bins' large negative scores.
    }

    // Mild stream-phase modulation: early on, keep bins flexible (favor larger residuals).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 4.0 * (1.0 - progress) * (pr / cap); // early: prefer roomier bins
    score += 4.0 * progress * (1.0 - pr / cap);   // late: prefer tight packing

    // Mean-residual coupling: if this bin is far below mean, it's an outlier — close it out.
    let dev = (pr - mean_residual) / cap;
    if dev < -0.15 {
        score += 6.0 * (-dev);
    } else if dev > 0.15 {
        score -= 3.0 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
