pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        let mut nb = 10.0 + progress * 4.0;
        // no fitting bin: must open
        if fitting_bins_count == 0 {
            nb -= 40.0;
        } else {
            nb += 4.0;
        }
        // resist new bin when existing bins can absorb next item cleanly
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 {
            nb += 3.0;
        }
        // open new bin when mean residual is awkward dead zone (12..20) on long stream
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 {
            nb -= 1.5;
        }
        // open new bin for large items on long stream (avoid fragmenting fresh bins)
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.7 && remaining > 100 {
            nb -= 2.5 * item_ratio;
        }
        // resist new bin near end of stream
        if remaining < 15 && fitting_bins_count > 0 {
            nb += 5.0;
        }
        // open new bin when fitting bins would strand space just below next item
        if next_item_size > 0 && fitting_bins_count <= 2 && item_size + next_item_size <= bin_capacity && mean_residual > 25.0 && remaining > 60 {
            nb -= 2.0;
        }
        // resist sprawl when many bins can each host next item
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            nb += 3.0;
        }
        // large item + high mean residual: fresh bin better than bad fit
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 {
            nb -= 3.0;
        }
        score = nb;
        return score;
    }

    // ---- Open-bin scoring ----
    let class: f64 = if pr == 0 {
        -48.0
    } else if pr <= 8 {
        -15.0
    } else if pr <= 15 {
        -6.5
    } else if pr <= 25 {
        -1.0
    } else if pr <= 40 {
        4.0
    } else if pr <= 60 {
        8.0
    } else {
        12.0
    };
    score += class;

    // reward residuals that are clean multiples (future perfect splits)
    if pr > 0 {
        if pr % 10 == 0 { score -= 3.0; }
        else if pr % 5 == 0 { score -= 1.0; }
    }

    let frag = (pr - item_size) as f64;

    if next_item_size > 0 {
        let n = next_item_size;
        // exact two-item chain: item + next fills bin perfectly
        if item_size + n == pr {
            score -= 6.0;
        }
        // frag == next: next item closes bin exactly
        if frag > 0.0 && (frag as u32) == n {
            score -= 4.5;
        }
        if frag > 0.0 && (frag as u32) > n {
            let rem = frag as u32 - n;
            // tiny remainder after next item: near-perfect chain
            if rem <= 2 {
                score -= 2.2 - rem as f64 * 0.6;
            } else if rem <= 6 {
                score -= 1.8 * (1.0 - rem as f64 / 6.0);
            }
            // awkward mid-gap: frag between next and 2*next
            if rem < n && rem > 8 {
                score += rem as f64 * 0.08;
            }
        }
        // frag just below next item: guaranteed dead space
        if frag > 0.0 && (frag as u32) < n && n - (frag as u32) <= 4 {
            score += (n - frag as u32) as f64 * 0.9;
        }
        // triple chain: item + 2*next with tiny slack
        let triple = item_size + n * 2;
        if pr >= triple && pr - triple <= 6 {
            score -= 2.0 * (1.0 - (pr - triple) as f64 / 6.0);
        }
        // quad chain
        let quad = item_size + n * 3;
        if pr >= quad && pr - quad <= 4 {
            score -= 1.5;
        }
        // pr multiple of next: perfect future splits
        if pr > 0 && pr % n == 0 {
            score -= 1.5;
        }
        // pr just below next: dead space next step
        if pr > 0 && pr < n && pr < item_size.min(n) {
            score += 1.5 + (n - pr) as f64 * 0.05;
