        if pr > 0 && pr % next_item_size == 0 { score -= 1.8; }
        // Awkward mid gap (next, 2*next) wastes space on long streams.
        if frag > next_item_size && frag < next_item_size * 2 && remaining > 60 {
            score += (frag - next_item_size) as f64 * 0.09;
        }
    }

    // Penalize residual just below item size when next item is bigger (stranded).
    if pr > 0 && pr < item_size && next_item_size > pr {
        score += 2.0;
    }

    // Open-bin pressure and residual-host bias.
    score += open_bins_count as f64 * 0.3;
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Late-stream tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr as f64 * 0.35 * progress;

    // Large frag that will likely never be filled, scaled by remaining stream.
    if pr > 40 && remaining > 60 { score += (pr - 40) as f64 * 0.05; }

    // Near-close bonus.
    if pr > 0 && pr <= 2 { score -= 3.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: strong preference for tight fits.
    let fill_frac = item_size as f64 / cap;
    score -= 60.0 * fill_frac;

    // Harmonic class of post_residual: classify dead space by integer division
    // against the next item size (can the leftover host the lookahead item?).
    let nxt = next_item_size as f64;
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Leftover is reusable by the lookahead item: reward proportionally.
            score -= 8.0 * (post_residual as f64 / nxt).min(3.0);
            // Harmonic bonus: post_residual is an exact multiple of next size.
            if post_residual % next_item_size == 0 {
                score -= 10.0;
            }
        } else {
            // Dead space: leftover too small for the next item.
            let dead_frac = post_residual as f64 / cap;
            score += 25.0 * dead_frac * dead_frac;
            // Harmonic penalty via modulo classes of post_residual mod 10:
            // residues near 0 (tiny slivers) are worst.
            let r = (post_residual % 10) as f64;
            score += 4.0 * (5.0 - (r - 5.0).abs()) / 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when current bins are
    // nearly full or the item is large and fits nothing well.
    if bin_residual == bin_capacity {
        // New bin starts with full residual; add an opening cost so it loses
        // against any decent existing fit.
        score += 55.0;
        // Discount the opening cost late in the stream or when few bins fit.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if fitting_bins_count == 0 || item_size >= 70 {
            score -= 40.0 * (0.5 + 0.5 * progress);
        }
        if next_item_size > 0 && next_item_size >= bin_capacity as u32 / 2 {
            score -= 5.0; // big lookahead: fresh bin gives room
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (more
    // filled-than-average bins are closer to closure).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 10.0 * dev;

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64;

    // Exact-fill harmonic reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);

    // Dead-space penalty: small unusable gaps are worthless.
    if pr > 0 && pr < 10 {
        score += 50.0;
    } else if pr > 0 && pr < 20 {
        score += 25.0;
    }

    // Reward tight fits.
    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 40.0;
    }

    // Open-bin pressure: penalize spreading across many open bins.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if next item exactly fills post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == pr {
        score -= 60.0;
    } else if next_item_size > 0 && next_item_size > pr {
        score += pr as f64 * 0.5;
    }

    // Progress-aware scaling of dead-space aversion.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr as f64 * (0.1 + 0.2 * progress);

    // --- Borrowed refinements from the best heuristic ---
    // Residual divisibility: residuals that are clean multiples of 5/10/20 split well later.
    let reusable = (pr % 10 == 0) as f64 * 4.0 + (pr % 20 == 0) as f64 * 3.0 + (pr % 5 == 0) as f64 * 1.0;
    if pr > 0 {
        score -= reusable;
    }

    // Two-item lookahead: item + next fills the bin exactly.
    if next_item_size > 0 && item_size + next_item_size == pr {
        score -= 6.0;
    }

    // Post-residual that can host next item twice with near-zero slack.
    if next_item_size > 0 && pr >= next_item_size * 2 {
        let d2 = pr - next_item_size * 2;
        if d2 <= 3 {
            score -= 2.0 - d2 as f64 * 0.5;
        }
    }

    // Frag just below next item = guaranteed dead space next step.
    let frag = if pr >= item_size { (pr - item_size) as f64 } else { 0.0 };
    if next_item_size > 0 && frag > 0.0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
        score += (next_item_size - frag as u32) as f64 * 0.9;
    }

    // Frag that is just barely above next item: near-perfect chain next step.
    if next_item_size > 0 && frag > 0.0 && frag as u32 > next_item_size {
        let rem = frag as u32 - next_item_size;
        if rem <= 2 {
            score -= 2.2 - rem as f64 * 0.6;
        }
    }

    // Mid-range frag in (next, 2*next) dead zone, sharper when mean residual is low.
    if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 {
        score += (frag - next_item_size as f64) * 0.10;
        if mean_residual < 16.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
    }

    // Large frag that will likely never be filled, scaled by remaining stream.
    if frag > 40.0 && remaining > 60 {
        score += (frag - 40.0) * 0.05;
    }

    // New-bin candidate logic with adaptive pressure.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        if fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        // Open new bin eagerly when mean residual is high on a long stream.
        if mean_residual > 30.0 && remaining > 100 {
            score -= 2.0;
        }
        // Prefer new bin for large items when mean residual is mid-range.
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 {
            score -= 3.0;
        }
        // Open new bin when no existing bin can host item + next.
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 4.0;
        }
        // Resist new bin near stream end.
        if remaining < 8 && fitting_bins_count > 0 {
            score += 5.0;
        }
        // Resist sprawl when many open bins can absorb next item.
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
        // Gen-75 mutation: open new bin when all fitting bins would leave frag just under next item.
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2 && remaining > 50 && mean_residual > 20.0 {
            let mr = mean_residual as u32;
            if mr >= next_item_size && mr - next_item_size <= 3 {
                score += 3.5;
            }
        }
        // Gen-75 mutation: resist new bin when mean residual closely matches next item.
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 && fitting_bins_count >= 2 {
            score += 3.5;
        }
    } else {
        // Non-fitting open bins are strongly penalized so a fitting bin or new bin wins.
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than large ones.
    // A residual that cannot hold even the smallest plausible item is pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0 * (1.0 - (post_residual as f64) / 20.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += 2.5 * open_bins_count as f64;

    // Prefer bins whose residual is close to the item (tight fit relative to bin state).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += 0.3 * tightness;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin fits well or when
    // the item is large relative to what open bins can absorb.
    if bin_residual == bin_capacity {
        let new_bin_base = 70.0 + 3.0 * open_bins_count as f64;
        let lookahead_penalty = if next_item_size > 0 && next_item_size as f64 > mean_residual {
            0.5 * (next_item_size as f64 - mean_residual)
        } else {
            0.0
        };
        score = new_bin_base + lookahead_penalty
            + (post_residual as f64 - item_size as f64).abs() * 0.1;
    }

    // Late-stream consolidation: as the stream progresses, prefer filling
    // existing bins over creating new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 15.0 * progress;
    }

    // Coupling with mean residual: bins far from the mean residual are
    // less attractive unless the fit is exact.
    let mean_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_gap * (1.0 - (post_residual == 0) as u8 as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
