        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Large items early: prefer fresh bin over fragmenting an open one.
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 {
