    let class: f64 = if pr == 0 { -55.0 }
        else if pr <= 5 { -18.0 }
        else if pr <= 10 { -10.0 }
        else if pr <= 18 { -4.0 }
        else if pr <= 28 { 1.0 }
        else if pr <= 45 { 6.0 }
        else { 10.0 };
    score += class;

    // Next-item lookahead: reward residuals that host the next item exactly or nearly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 12.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            score -= 6.0 + 8.0 / (1.0 + slack as f64);
            if slack <= 3 {
