            }
        } else {
            // Guaranteed dead space next step: penalize by closeness.
            let gap = next_item_size - pr;
            if gap <= 6 {
                score += gap as f64 * 1.1;
            } else {
                score += 4.0;
            }
        }
        // Two-item chain: item + next fits exactly.
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        // Triple chain near-exact.
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 6 {
            score -= 2.0 * (1.0 - (pr - triple) as f64 / 6.0);
        }
    }

