    if pr > 0 && pr < item_size.min(12) {
        score += 7.0;
    }

    // Last-chance bin: strong bonus.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Prefer bins with larger residuals slightly (better long-term hosts).
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    // Open-bin pressure: tighter packing when many bins are open.
    score += open_bins_count as f64 * 0.25;

    // Late-stream tightening: punish leftover dead space more as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr as f64 * 0.35 * progress;

    // Long-stream waste penalty on mid-range frag.
    if remaining > 120 && pr > 20 {
        score += (pr as f64 - 20.0) * 0.04;
    }

    score
}

