                score += (frag - next_item_size as f64) * 0.08;
            }
        }
        // frag just barely too small for next item: guaranteed dead space
        if frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        // near-exact chain next step
        if frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        // two-step chain: frag splits into next item plus tiny remainder
        if frag as u32 > next_item_size {
            let rem = frag as u32 - next_item_size;
            if rem <= 2 {
                score -= 2.2 - rem as f64 * 0.6;
            }
        }
        // gap in 25..45 dead zone
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 {
                score += (gap as f64 - 25.0) * 0.08;
            }
            if gap >= 15 && gap <= 25 && mean_residual > 22.0 {
                score += (gap as f64 - 15.0) * 0.10;
            }
        }
        // awkward 20..35 frag on long streams
        if frag >= 20.0 && frag <= 35.0 && remaining > 80 && next_item_size < frag as u32 {
            score += (frag - 20.0) * 0.045;
        }
        // large frag that will likely never fill
        if frag > 40.0 && remaining > 60 {
            score += (frag - 40.0) * 0.05;
        }
        // tiny frag: near-closing bin
        if frag > 0.0 && frag <= 2.0 {
            score -= 3.0;
        }
        // perfect close
        if frag == 0.0 {
            score -= 4.0;
        }
    }

    // Mean-residual alignment: mild
    let mean_gap = (pr as f64 - mean_residual).abs();
    score += mean_gap * 0.1;

    // Sliver penalty
    if pr > 0 && pr < 10 && pr != next_item_size {
        score += 20.0;
    }

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Consolidation preference
    score += open_bins_count as f64 * 0.5;
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // New-bin candidate logic (adaptive)
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        if fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 {
            score += 3.0;
        }
        if mean_residual > 30.0 && remaining > 100 {
            score -= 2.0;
        }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 4.0;
        }
        if remaining < 8 && fitting_bins_count > 0 {
            score += 5.0;
        }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
        if item_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 4.0;
        }
        // open new bin when the only fitting bins would leave frag just under next item
        if next_item_size > 0 && fitting_bins_count > 0 && fitting_bins_count <= 2 && next_item_size > item_size && mean_residual > 20.0 && remaining > 50 {
            score -= 1.2;
        }
        // mid-range dead zone on long stream: prefer fresh bin
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 {
            score -= 1.5;
        }
        if remaining < 15 && fitting_bins_count > 0 {
            score += 3.0;
        }
    } else {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling: post_residual shaped by stream progress.
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - norm_pr);
    score += 12.0 * poly * (progress - 0.5).abs() * 2.0 - 6.0 * poly;

    // Penalize large residuals early, less late (dead space value changes over time).
    score += pr * pr / cap * (0.4 + 0.6 * progress);

    // Reward tight fits.
    let fit = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fit * fit;

    // Last-chance bin bonus.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // Lookahead: reward leaving space for the next item.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 3.0 * (1.0 - gap / cap).max(0.0);
    }

    // Mild preference for filling existing bins when many are open.
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * (1.0 - norm_pr);

    // New-bin candidate: penalize slightly unless residuals are all poor.
    if bin_residual == bin_capacity {
        score += 4.0 - 6.0 * (mean_residual / cap - 0.5).clamp(0.0, 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual;
    let mut score = pr as f64;
    let remaining = total_items.saturating_sub(step_index);

    // Residual class ladder: strongly reward exact closes, penalize dead zones.
    let class: f64 = if pr == 0 { -55.0 } else if pr <= 5 { -14.0 } else if pr <= 10 { -8.0 }
