    // Reward residuals that are clean multiples (likely perfect future splits).
    if pr > 0 {
        if pr % 10 == 0 { score -= 3.0; }
        else if pr % 5 == 0 { score -= 1.0; }
    }

    // Next-item lookahead: reward exact fit, penalize just-barely-too-small.
    if next_item_size > 0 {
        if next_item_size == pr { score -= 8.0; }
        else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 6.0 + 8.0 / (1.0 + slack);
            if slack <= 3.0 { score -= 2.0; }
        } else {
            // Guaranteed dead space next step.
            score += 4.0 + (next_item_size - pr) as f64 * 0.12;
        }
        // Two-step exact chain: item then next fills the bin perfectly.
        if item_size + next_item_size == pr { score -= 6.0; }
        // Triple chain near-exact.
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 6 { score -= 2.0 * (1.0 - (pr - triple) as f64 / 6.0); }
    }

    // Frag-based dead-space penalty for mid-range waste on long streams.
    if pr >= item_size {
        let frag = (pr - item_size) as f64;
        if frag == 0.0 { score -= 5.0; }
        else if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 && remaining > 60 {
            score += (frag - next_item_size as f64) * 0.08;
        }
        if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }
        // Frag within 3 of next item: near-exact chain next step.
        if next_item_size > 0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.5 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
    }

    // Open-bin pressure: prefer tighter packing when many bins are open.
    score += open_bins_count as f64 * 0.25;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity { score -= 22.0; }

    // Bias toward bins with larger residuals (better long-term hosts).
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Late-stream tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += pr as f64 * 0.3 * progress;

    // NEW-BIN CANDIDATE LOGIC (bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin; adaptive pressure.
        score += 10.0;
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        // No fitting bin at all: must open.
        if fitting_bins_count == 0 { score -= 60.0; }
        // Crowding: many open bins already -> resist sprawl.
        score += (open_bins_count.min(12) as f64) * 0.8;
        // Large items late-ish: fresh bin better than fragmenting.
        if item_ratio > 0.6 && remaining > 20 { score -= 3.0 * item_ratio; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        // High mean residual with long stream left: existing bins are stranding space.
        if mean_residual > 25.0 && remaining > 80 && fitting_bins_count > 0 { score -= 2.0; }
        if mean_residual > 12.0 && mean_residual < 20.0 && remaining > 150 && fitting_bins_count > 0 { score -= 1.5; }
        // Mean residual closely matches next item: open bins will close cleanly -> resist new bin.
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        // Stream nearly over: use existing bins.
        if remaining < 15 && fitting_bins_count > 0 { score += 5.0; }
        // Next item huge relative to capacity: fresh bin hosts it better.
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        // Item + next exceeds capacity: existing bins can't chain them anyway.
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        // Small next item absorbable by existing mean residual: resist new bin.
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
    }

    score
}

