pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into residue classes mod 10.
    let r = post_residual % 10;
    // Dead-space penalty: residuals not expressible as sums of small item sizes
    // (items >= 10 originally, but interface allows 1..100, so use mod classes).
    let harmonic_penalty = match r {
        0 => -6.0,   // perfectly aligned residual, highly reusable
        1 | 9 => 2.5,
        2 | 8 => -1.0,
        3 | 7 => 0.5,
        4 | 6 => -0.5,
        _ => 3.0,    // r == 5, awkward half-class
    };
    score += harmonic_penalty;

    // Integer-division thresholds: small post_residual = tight fit (good).
    let q = post_residual / 10;
    if q == 0 {
        score -= 8.0; // near-perfect packing
    } else if q <= 2 {
        score -= 2.0;
    } else if q >= 6 {
        score += 1.5; // large leftover, wasteful unless new bin
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // reward heavily (chained harmonic fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 5.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize residuals that strand capacity
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // fit poorly (large post_residual everywhere) or none exist.
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score -= 20.0;
        } else {
            // compare against mean residual of open bins: if open bins would
            // leave similar waste, opening new bin keeps clean slates
            let avg_post = (mean_residual - item_size as f64).max(0.0);
            if avg_post > 0.5 * bin_capacity as f64 {
                score -= 4.0;
            } else {
                score += 6.0 + 0.05 * open_bins_count as f64;
            }
        }
    }

    // Mild stream-progression pressure: late in stream, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates favorably from the mean.
    score += 0.3 * (post_residual as f64 - mean_residual).max(-50.0).min(50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);

    // Residual class ladder (borrowed from best): reward small residuals.
    let class: f64 = if pr == 0 { -48.0 } else if pr <= 8 { -15.0 } else if pr <= 15 { -6.5 } else if pr <= 25 { -1.0 } else if pr <= 40 { 4.0 } else if pr <= 60 { 8.0 } else { 12.0 };
    score += class;

    // Reward residuals divisible by common item granularities.
    let reusable = (pr % 10 == 0) as f64 * 4.0 + (pr % 20 == 0) as f64 * 3.0 + (pr % 25 == 0) as f64 * 2.0 + (pr % 5 == 0) as f64 * 1.0;
    score -= reusable;

    let frag = (pr - item_size) as f64; // fits since pr is post-residual

    // Next-item lookahead: reward residuals that host the next item well.
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 { score -= 5.0; }
            if slack >= 1.0 && slack <= 12.0 { score -= 3.0 * (1.0 - slack / 12.0); }
            if slack > 45.0 { score += (slack - 45.0) * 0.05; }
        } else {
            score += 5.0 + (next_item_size - pr) as f64 * 0.09;
        }
        // Two-item exact chain.
        if item_size + next_item_size == pr { score -= 6.0; }
        // Triple chain near-exact.
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 { score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0); }
        // Penalize frag just under next item (guaranteed dead space).
        if frag > 0.0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        // Penalize frag in (next, 2*next) gap, stronger when mean residual is low.
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 {
            score += (frag - next_item_size as f64) * (0.06 + if mean_residual < 16.0 && remaining > 100 { 0.08 } else { 0.0 });
        }
        // Reward pr a small multiple of next item.
        if pr > 0 && pr % next_item_size == 0 { score -= 1.5; }
        // Near-exact chain next step.
        if frag > 0.0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
    }

    // Small frag handling.
    if frag > 0.0 && frag <= 2.0 { score -= 3.0; }
    if frag > 0.0 && frag < item_size.min(15) as f64 { score += 4.0 + (15.0 - frag) * 0.15; }
    if frag == 0.0 { score -= 4.0; }

    // Large frag that will likely never fill, scaled by remaining stream.
    if frag > 40.0 && remaining > 60 { score += (frag - 40.0) * 0.05; }
    if frag > 0.0 && frag > mean_residual * 1.5 && open_bins_count > 3 { score += (frag - mean_residual * 1.5) * 0.06; }

    // Open-bin pressure.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity { score -= 20.0; }

    // NEW-BIN CANDIDATE logic.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 { score -= 2.5 * item_ratio; }
        if item_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 { score += 2.0; }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
