            score -= (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        // Fragments just over one next-item but under two: hard-to-fill dead zone.
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
            if mean_residual < 16.0 && remaining > 100 {
                score += (frag - next_item_size as f64) * 0.08;
            }
        }
        // Large fragments relative to mean residual waste space.
        if frag > mean_residual && frag > 12.0 {
            score += (frag - mean_residual) * 0.06;
        }
        if frag > 40.0 && remaining > 60 {
            score += (frag - 40.0) * 0.05;
        }
        if frag > mean_residual * 1.6 && remaining > 30 {
            score += (frag - mean_residual * 1.6) * 0.04;
        }
        // Small items placed alone leave big gaps: penalize low fill ratio.
        let fill_ratio = item_size as f64 / bin_capacity.max(1) as f64;
