pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (best-fit), with slight non-linearity
    // to disproportionately punish large wasted fragments.
    let frag = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * frag * frag;

    // Lookahead: reward bins whose post_residual can host the next item.
