        // Harmonic classes: post_residual in {10,20,25,50} are reusable slots.
        if post_residual % 50 == 0 { score -= 45.0; }
        else if post_residual % 25 == 0 { score -= 30.0; }
        else if post_residual % 20 == 0 { score -= 25.0; }
        else if post_residual % 10 == 0 { score -= 15.0; }

        // Dead space: residuals below the minimum item size are wasted.
        if post_residual < 10 {
            score += 40.0 * (10 - post_residual) as f64;
        }

        // Lookahead coupling: does next_item_size fit into post_residual?
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                // Chain-friendly: prefer bins that can also host the next item.
                let slack = (post_residual - next_item_size) as f64;
                score -= 20.0 + 0.3 * slack;
            } else {
                // Next item won't fit here: penalize proportionally to overshoot.
                let over = (next_item_size - post_residual) as f64;
                score += 0.5 * over;
                // Modulo coupling: if next item's size mod 10 leaves a friendly residual
                let after_next = post_residual as i64 - next_item_size as i64;
                if after_next < 0 && (next_item_size % 10 == 0 || next_item_size % 25 == 0) {
                    score -= 5.0; // next item likely pairs well elsewhere, mild relief
                }
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, mild spread penalty toward wasteful large residuals.
        score += 0.05 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        let tight_exists = fitting_bins_count > 0 && (post_residual as f64) < mean_residual;
        let early = (step_index as f64) / (total_items.max(1) as f64);
        if fitting_bins_count == 0 {
            score -= 500.0; // nothing fits anywhere: open new bin
        } else if post_residual > 35 && mean_residual < 30.0 {
            score -= 40.0 * (1.0 - early); // early stream: fresh bins cheap
        } else if tight_exists {
            score += 60.0; // a decent existing fit exists: don't open new bin
        }
    }

    // Slight preference for bins below mean residual (tight packing consolidation).
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it is too small to fit even the smallest plausible item.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 8.0;
    }

    // Perfect fits get a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving a gap that fits neither the next item nor a small item.
    if next_item_size > 0 && (post_residual as u32) < next_item_size && post_residual > 0 {
        score += 6.0 + (next_item_size - post_residual) as f64 * 0.3;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Reward leaving a gap exactly usable by the lookahead item.
        score -= 4.0 + (post_residual as f64 - next_item_size as f64).min(10.0) * 0.2;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64 / total_items.max(1) as f64);
    score += pressure * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Prefer bins whose residual is already below the mean (tighter bins fill first).
    score += (post_residual as f64 - mean_residual) * 0.4;

    // New-bin candidate: only attractive when the item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, discounted when item is large.
        score += 18.0 - (item_size as f64 / bin_capacity as f64) * 10.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
