pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward a perfect 2-step chain: post_residual exactly matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match: big bonus; near matches: graded bonus.
        if gap == 0.0 {
            score -= 60.0;
        } else if gap <= 10.0 {
            score -= 60.0 * (1.0 - gap / 10.0);
        } else {
            // Penalize large leftover relative to lookahead need.
            score += gap * 0.15;
        }
    } else {
        // Last item: minimize leftover directly (already base score).
    }

    // Dead-space penalty: tiny unusable remnants (cannot host min item of 1).
    if post_residual > 0 && post_residual < 8 {
        score += 25.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: default baseline; only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        score = 100.0 + item_size as f64 * 0.5;
        if fitting_bins_count <= 1 {
            score -= 80.0; // opening new bin is fine when fits are scarce
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // fresh bin can host the lookahead too
        }
    }

    // Mild preference for bins tighter than average (good utilization).
    if bin_residual != bin_capacity {
        score += (mean_residual - bin_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = pr as f64 - item_size as f64;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Dead-space avoidance tiers.
    if pr > 0 && pr < 10 {
        score += 55.0;
    } else if pr > 0 && pr < 20 {
        score += 25.0;
    }

    // Reward exact and near-exact fills.
    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 8 {
        score -= 15.0;
    } else if pr <= 15 {
        score -= 6.5;
    } else if pr <= 25 {
        score -= 1.0;
    } else if pr <= 40 {
        score += 4.0;
    } else if pr <= 60 {
        score += 8.0;
    } else {
        score += 12.0;
    }

    if next_item_size > 0 {
        // Perfect lookahead fit is gold.
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size > pr {
            score += pr as f64 * 0.5;
        } else {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 45.0 {
                score += (slack - 45.0) * 0.05;
            }
        }
        // Two-item combo fit.
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        // Multi-item lookahead: pr leaves a small gap after next item copies.
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        // Divisible residual hosts next item cleanly.
        if pr > 0 && pr % next_item_size == 0 {
            score -= 1.5;
        }
        // Frag barely misses next item: future dead space.
        if frag > 0.0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        // Frag absorbs next item with tiny slack: good host.
        if frag > 0.0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        // Large leftover fragments are wasteful when stream continues.
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
            if mean_residual < 16.0 && remaining > 100 {
                score += (frag - next_item_size as f64) * 0.08;
            }
        }
        if frag > 40.0 && remaining > 60 {
            score += (frag - 40.0) * 0.05;
        }
        if frag > mean_residual && frag > 12.0 {
            score += (frag - mean_residual) * 0.06;
        }
        // Small items prefer hosting in fragmented bins.
        let fill_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if frag > 0.0 && fill_ratio < 0.42 && remaining > 40 {
            score += (0.42 - fill_ratio) * 16.0 * (1.0 - progress * 0.5);
        }
        if frag > 0.0 && frag > mean_residual * 1.6 && remaining > 30 {
            score += (frag - mean_residual * 1.6) * 0.04;
        }
        // Residual close to mean: typical host, mildly preferred.
        if pr > 0 && mean_residual > 1.0 {
            let dev = ((pr as f64 - mean_residual) / mean_residual).abs();
            if dev < 0.3 {
                score -= 2.0 * (1.0 - dev / 0.3);
            } else if dev > 1.5 && pr as f64 > mean_residual * 2.0 {
                score += 2.5;
            }
        }
    }

    // Progress-weighted residual penalty: tighten later in the stream.
    score += pr as f64 * (0.1 + 0.2 * progress);

    // Open-bin pressure: prefer tighter packing when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Slight bias toward bins with larger residuals.
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // NEW-BIN CANDIDATE evaluation.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        if fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 {
            score += 3.0;
        }
        if mean_residual > 30.0 && remaining > 100 {
            score -= 2.0;
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 {
            score += 2.0;
        }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 {
            score -= 3.0;
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 4.0;
        }
        if remaining < 8 && fitting_bins_count > 0 {
            score += 5.0;
        }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
        if item_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 4.0;
        }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size
            && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
        if next_item_size > 0 && fitting_bins_count > 0 && frag > 0.0
            && frag < next_item_size as f64 && next_item_size - frag as u32 <= 6 && remaining > 60 {
            score -= 2.0;
        }
        if remaining < 15 && fitting_bins_count > 0 {
            score += 3.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size && remaining > 30
            && open_bins_count > 0 && mean_residual >= next_item_size as f64 {
            score += 6.0;
        }
        // Fresh bin leftover near mean residual: wasteful opening.
        let fresh_left = bin_capacity.saturating_sub(item_size) as f64;
        if remaining > 60 && fresh_left > 0.0 && fresh_left < mean_residual * 1.25 && open_bins_count > 0 {
            score += (mean_residual * 1.25 - fresh_left) * 0.38;
        }
        if fresh_left <= 6.0 && remaining > 30 {
            score -= 4.0;
        }
        if fitting_bins_count > 0 && fresh_left <= 3.0 && item_ratio > 0.9 {
            score -= 5.0;
        }
    } else {
        // Existing-bin adjustments.
        score += 60.0;
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 60.0;

    // Reward exact-ish fits heavily.
    if post_residual < 5 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Penalize creating dead space that no future item (min size 1, typical ~10+) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver is wasted
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; mild penalty for leaving large residual anyway.
            score += (next_item_size - post_residual) as f64 * 0.1;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of all
    // open bins; only attractive if this bin's fit is poor.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: its full residual.
        score = bin_capacity as f64 * 0.9;
        // Cheaper to open new bins early in the stream (more items to come to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 30.0;
        // If many bins are open with large mean residual, discourage opening another.
        score += open_bins_count as f64 * 2.0 + mean_residual * 0.3;
        // If no open bin fits at all (fitting_bins_count == 0), new bin is necessary-ish.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Prefer fuller bins: mild bonus proportional to how full this bin already is.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill * 10.0;
        // Spread load: prefer bins with residual below mean (keeps some bins for big items).
        if (bin_residual as f64) > mean_residual {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
