fn progress_proxy (step_index : usize , total_items : usize) -> f64 { step_index as f64 / total_items . max (1) as f64 }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling: waste penalty grows super-linearly
    // with residual size, modulated by stream progress.
    let waste = norm_pr * norm_pr * (1.0 + 2.0 * progress);
    score += 8.0 * waste;

    // Lookahead: reward if the next item fits into the post residual
    // (smooth sigmoid-like gate on fit quality).
    if next_item_size > 0 {
        let fits = (post_residual >= next_item_size) as i32 as f64;
        let tightness = 1.0 - ((next_item_size as f64 - pr).abs() / cap).min(1.0);
        score -= 6.0 * fits * (0.5 + 0.5 * tightness) * (1.0 - 0.5 * progress);
        // Penalize leaving a gap that is too small for the next item
        // (dead space), stronger late in the stream.
        let dead = if next_item_size > post_residual { (next_item_size as f64 - pr) / cap } else { 0.0 };
        score += 5.0 * dead * dead * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 * (1.0 + progress);
    }

    // Crowding bonus: using an already-open bin reduces fragmentation;
    // penalize opening new bins when many bins are open and residuals are low.
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * (1.0 - progress);
    } else {
        score -= 1.5 * (1.0 - (bin_residual as f64 / cap));
    }

    // Mild alignment with mean residual: bins deviating far below the mean
    // residual are near-full; placing there is good (tight packing).
    score -= 0.05 * (mean_residual - bin_residual as f64);

    // Smooth non-linear interaction between item size and residual fill.
    let fill = 1.0 - (bin_residual as f64 / cap);
    score += 3.0 * fill * fill * (1.0 - fill) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = (pr as i64 - item_size as i64).max(0) as f64;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill_ratio = item_size as f64 / bin_capacity.max(1) as f64;

    // graded residual quality: exact fill rewarded, small leftovers penalized
    if pr == 0 {
        score -= 100.0;
    } else if pr <= 3 {
        score -= 30.0;
    } else if pr <= 6 {
        score -= 12.0;
    } else if pr <= 10 {
        score += 50.0;
    } else if pr <= 15 {
        score -= 5.0;
    } else if pr <= 25 {
        score += 20.0 * (1.0 - pr as f64 / 25.0);
    } else if pr <= 40 {
        score += 3.0;
    } else {
        score += 9.0;
    }

    // lookahead: next item usability of the post residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 45.0 {
                score += (slack - 45.0) * 0.05;
            }
        } else {
            score += 5.0 + (next_item_size - pr) as f64 * 0.09;
        }
        // two-step exact chain
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        // triple / quad chains near-exact
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        // frag just below next item = guaranteed dead space next step
        if frag > 0.0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        // frag slightly above next item: good, splittable
        if frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        // frag awkward between next and 2*next on long streams
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.10;
            if mean_residual < 16.0 {
                score += (frag - next_item_size as f64) * 0.08;
            }
        }
        // frag divisible by next item: perfect future splits
        if frag > 0.0 && frag as u32 % next_item_size == 0 && frag <= next_item_size as f64 * 3.0 {
            score -= 1.5;
        }
        // frag exceeds mean residual: pushing waste above average
        if frag > mean_residual && frag > 12.0 {
            score += (frag - mean_residual) * 0.06;
        }
        if frag > mean_residual * 1.6 && remaining > 30 {
            score += (frag - mean_residual * 1.6) * 0.04;
        }
    }

    // large frag that will never fill
    if frag > 40.0 && remaining > 60 {
        score += (frag - 40.0) * 0.05;
    }
    // near-closing bins
    if frag > 0.0 && frag <= 2.0 {
        score -= 3.0;
    }

    // small items leave flexible residuals; tiny items wasting big residuals is bad
    if frag > 0.0 && fill_ratio < 0.42 && remaining > 40 {
        score += (0.42 - fill_ratio) * 16.0 * (1.0 - progress * 0.5);
    }

    // open-bin pressure
    score += open_bins_count as f64 * 0.3;
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }
    score -= (bin_residual as f64 - mean_residual) * 0.2;
    score += pr as f64 * (0.1 + 0.2 * progress);

    // NEW-BIN CANDIDATE logic
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 { score -= 3.0; }
        if item_ratio_checks(fill_ratio) && remaining > 20 { score -= 2.5 * fill_ratio; }
        if fitting_bins_count > 0 { score += 4.0; }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 { score -= 5.0; }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 { score += 3.0; }
        if mean_residual > 30.0 && remaining > 100 { score -= 2.0; }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 { score += 2.0; }
        if fill_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 { score -= 3.0; }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity { score -= 4.0; }
        if remaining < 8 && fitting_bins_count > 0 { score += 5.0; }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 { score += 3.0; }
        if fill_ratio > 0.85 && remaining > 150 { score -= 2.0; }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 { score += 4.0; }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 { score += 3.5; }
        if remaining < 15 && fitting_bins_count > 0 { score += 3.0; }
        // next item won't fit even in a fresh bin after this item
        if next_item_size > 0 && next_item_size > bin_capacity - item_size && remaining > 30 && open_bins_count > 0 && mean_residual >= next_item_size as f64 {
            score += 6.0;
        }
        // fresh-bin leftover close to mean residual: aligns with stream
        let fresh_left = (bin_capacity.saturating_sub(item_size)) as f64;
        if remaining > 60 && fresh_left > 0.0 && fresh_left < mean_residual * 1.25 && open_bins_count > 0 {
            score += (mean_residual * 1.25 - fresh_left) * 0.38;
        }
        if fresh_left <= 6.0 && remaining > 30 { score -= 4.0; }
        if fitting_bins_count > 0 && fresh_left <= 3.0 && fill_ratio > 0.9 { score -= 5.0; }
    } else {
        score += 60.0;
        // open-bin bonus: nearly perfect next-step closure
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
    }

    score
}

#[inline]
fn item_ratio_checks(r: f64) -> bool { r > 0.6 }

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into
    // "useful" classes divisible by common small item sizes (1..=10 range classes).
    let pr = post_residual;
    if pr > 0 {
        // A residual that is exactly a plausible next-item size is gold.
        if next_item_size > 0 && pr == next_item_size {
            score -= 30.0;
        } else if next_item_size > 0 && pr > next_item_size {
            // residual can hold the lookahead item: strong reward scaled by slack
            score -= 12.0 + (pr - next_item_size) as f64 * 0.15;
        } else if next_item_size > 0 {
            // lookahead won't fit in leftover: penalize dead space
            score += (next_item_size - pr) as f64 * 0.35;
        }
        // Divisibility bonus: residual usable by many item classes
        let mut div_bonus = 0.0;
        for d in [1u32, 2, 4, 5, 8, 10, 20, 25, 50] {
            if pr % d == 0 {
                div_bonus += 1.0;
            }
        }
        score -= div_bonus * 1.5;

        // Integer-division thresholds: tiny unusable slivers are bad.
        if pr < 10 {
            score += 25.0; // dead space class
        } else if pr < 20 {
            score += 8.0;
        }
        // Perfect fill
        if pr == 0 {
            score -= 40.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }
    // Many fitting bins: mild penalty to encourage spreading load / keeping options.
    if fitting_bins_count > 2 {
        score += (fitting_bins_count as f64 - 2.0) * 1.0;
    }

    // New-bin candidate handling: empty bin gets a baseline cost so it is only
    // chosen when open bins have poor fits; cheaper late in the stream is irrelevant,
    // but discourage hoarding many open bins early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0 + open_bins_count as f64 * 2.0 * (1.0 - progress) - progress * 10.0;
        if next_item_size > 0 && next_item_size > 50 {
            score -= 8.0; // big lookahead favors a fresh bin
        }
        return score;
    }

    // Prefer bins whose residual is far from mean residual (tight fits stand out).
    score -= ((bin_residual as f64 - mean_residual).abs()) * 0.05;

    // Tight fit reward relative to item size.
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
