        }
        // Mid-gap fragment between one and two next-items: likely dead space.
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
            if mean_residual < 16.0 && remaining > 100 {
                score += (frag - next_item_size as f64) * 0.08;
            }
        }
        if frag > 40.0 && remaining > 60 {
            score += (frag - 40.0) * 0.05;
        }
        if frag > mean_residual && frag > 12.0 {
            score += (frag - mean_residual) * 0.06;
        }
        // Small-item placement creates large relative waste: penalize.
        let fill_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if frag > 0.0 && fill_ratio < 0.42 && remaining > 40 {
            score += (0.42 - fill_ratio) * 16.0 * (1.0 - progress * 0.5);
        }
        if frag > 0.0 && frag > mean_residual * 1.6 && remaining > 30 {
            score += (frag - mean_residual * 1.6) * 0.04;
        }
        if next_item_size <= 10 && mean_residual >= next_item_size as f64 {
            score += 3.0;
        }
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 {
                score += (gap as f64 - 25.0) * 0.08;
            }
        }
    }

    if pr > 0 && mean_residual > 1.0 {
        let dev = ((pr as f64 - mean_residual) / mean_residual).abs();
        if dev < 0.3 {
            score -= 2.0 * (1.0 - dev / 0.3);
        } else if dev > 1.5 && pr as f64 > mean_residual * 2.0 {
            score += 2.5;
        }
    }

    score += open_bins_count as f64 * 0.3;

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    score += pr as f64 * (0.1 + 0.2 * progress);

    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        if fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 {
            score += 3.0;
        }
        if mean_residual > 30.0 && remaining > 100 {
            score -= 2.0;
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 {
            score += 2.0;
        }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 {
            score -= 3.0;
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 4.0;
        }
        if remaining < 8 && fitting_bins_count > 0 {
            score += 5.0;
        }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
        if item_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 4.0;
        }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
        if next_item_size > 0 && fitting_bins_count > 0 && frag > 0.0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 6 && remaining > 60 {
            score -= 2.0;
        }
        if remaining < 15 && fitting_bins_count > 0 {
            score += 3.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size && remaining > 30 && open_bins_count > 0 && mean_residual >= next_item_size as f64 {
            score += 6.0;
        }
        let fresh_left = (bin_capacity.saturating_sub(item_size)) as f64;
        if remaining > 60 && fresh_left > 0.0 && fresh_left < mean_residual * 1.25 && open_bins_count > 0 {
            score += (mean_residual * 1.25 - fresh_left) * 0.38;
        }
        if fresh_left <= 6.0 && remaining > 30 {
            score -= 4.0;
        }
        if fitting_bins_count > 0 && fresh_left <= 3.0 && item_ratio > 0.9 {
            score -= 5.0;
        }
    } else {
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    if post_residual > 0 && post_residual < item_size as f64 * 0.5 {
        score += 15.0;
    }

    // Reward tight fits.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio;

    // Penalize wasting a large residual on a small item.
    score += 0.15 * (post_residual as f64 - item_size as f64).max(0.0);

    // Open-bin pressure: discourage opening new bins when many bins exist.
    if bin_residual == bin_capacity {
        score += 20.0 + 3.0 * open_bins_count as f64;
    } else {
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: bonus if next item fits the post residual.
    if next_item_size > 0 && post_residual >= next_item_size as u32 {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    // Late-stream tightening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;
    let frag = pr as f64 - item_size as f64;

    // Dead-space avoidance: small unusable gaps are heavily penalized.
    if pr > 0 && pr < 10 {
        score += 55.0;
    } else if pr < 25 {
        score += 22.0 * (1.0 - pr as f64 / 25.0);
    }

    // Reward near-perfect fills.
    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 35.0;
    } else if pr <= 12 {
        score -= 10.0;
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0; // perfect next fit
        } else if next_item_size > pr {
            score += pr as f64 * 0.4; // dead space for next item
        } else {
            let slack = (pr - next_item_size) as f64;
            score -= 6.0 + 9.0 / (1.0 + slack);
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 45.0 {
                score += (slack - 45.0) * 0.05;
            }
        }
        // Two-item lookahead: next item fits twice more.
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
    }

    // Open-bin pressure: prefer tighter packing when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Slight bias toward bins with larger residuals (better long-term hosts).
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Fragments larger than mean residual waste capacity going forward.
    if frag > mean_residual && frag > 12.0 && remaining > 30 {
        score += (frag - mean_residual) * 0.06;
    }

    // Late in the stream, tighten packing further.
    score += pr as f64 * (0.1 + 0.25 * progress);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        score += 8.0 + crowding * 6.0 + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        // Large items: better to start a fresh bin than fragment a good one.
        if item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        // Fresh bin leaves a large usable residual matching mean need.
        let fresh_left = bin_capacity.saturating_sub(item_size) as f64;
        if remaining > 60 && fresh_left > 0.0 && fresh_left < mean_residual * 1.25 && open_bins_count > 0 {
            score += (mean_residual * 1.25 - fresh_left) * 0.38;
        }
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        if fitting_bins_count > 0 {
            score += 4.0;
        }
        if remaining < 8 && fitting_bins_count > 0 {
            score += 5.0;
        }
    } else {
        score += 60.0;
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // Wasted space relative to the next item: penalize.
            score += 0.8 * (next_item_size - post_residual) as f64;
        }
        // Extra bonus if chain continues perfectly (post - next leaves tiny gap).
        if post_residual > next_item_size && (post_residual - next_item_size) <= 5 {
            score -= 100.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score += 2.0 * post_residual as f64;
    }

    // Relative to mean residual: prefer bins that are fuller than average.
    score += 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when reasonable fits exist, unless the fit is bad.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost of a fresh bin.
        score += 120.0;
        if next_item_size > 0 && next_item_size as f64 > post_residual as f64 {
            // New bin can chain with next item nicely.
            score -= 80.0;
        }
        // Early in the stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 60.0 * (1.0 - progress);
    }

    // Prefer bins with small residual relative to capacity (fuller bins).
    score += 0.2 * (bin_capacity as f64 - bin_residual as f64) * -0.0;

    score
}

