pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Reward small post-residual non-linearly
        score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(4);

        // Dead-space penalty: residual too small for typical items
        if post_residual < 10 {
            score += 40.0;
        }
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.3 * next_item_size as f64;
        } else {
            score += 8.0 * (next_item_size as f64 - post_residual as f64).min(50.0) / 50.0;
        }
    }

    // Last chance: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Time horizon: early in stream, prefer keeping bins flexible (higher residual);
    // late, accept tighter fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.15 * post_residual as f64;

    // Global state: many open bins -> prefer consolidating into existing bins
    // (penalize opening new bins when open_bins_count is high)
    if bin_residual == bin_capacity {
        // New-bin candidate
        score += 20.0 + 5.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity && fitting_bins_count == 0 {
            score -= 40.0; // nothing fits, opening new bin is fine
        }
        if mean_residual > item_size as f64 * 2.0 {
            score += 10.0; // plenty of residual elsewhere, don't open new bin
        }
    } else {
        // Existing bin: compare against mean residual to favor below-average waste
        score -= 0.1 * (mean_residual - post_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: wasted space after placement, non-linearly scaled.
    let mut score = pr * (1.0 + 0.5 * pr / cap);

    // Reward tight fits (small post_residual) with a superlinear bonus.
    let tightness = 1.0 - pr / cap;
    score -= 30.0 * tightness.powi(3);

    // Lookahead coupling: if next item fits exactly in the post residual,
    // this placement is excellent; if next item barely misses, penalize.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_quality = 1.0 - (pr - nx) / cap;
            score -= 20.0 * fit_quality * fit_quality;
        } else {
            let miss = (nx - pr) / cap;
            score += 15.0 * miss;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 + 10.0 * progress;
    }

    // New-bin candidate: penalize opening a new bin, more so later in the stream
    // and when many bins are already open; slight relief for large items.
    if bin_residual == bin_capacity {
        let size_relief = item_size as f64 / cap;
        score += 40.0 + 30.0 * progress + 2.0 * (open_bins_count as f64).ln().max(0.0) - 15.0 * size_relief;
    }

    // Mean-residual coupling: prefer bins whose residual deviates from the mean
    // in the direction of a better fill (bin_residual below mean = already full-ish).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual;
    let mut score = pr as f64;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;
    let frag = pr as f64 - item_size as f64;
    let fill_ratio = item_size as f64 / bin_capacity.max(1) as f64;

    // Dead-space avoidance: small unusable gaps heavily penalized.
    if pr > 0 && pr < 10 {
        score += 55.0;
    } else if pr > 0 && pr < 20 {
        score += 22.0 * (1.0 - pr as f64 / 20.0);
    }

    // Reward near-perfect fills.
    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 8 {
        score -= 15.0;
    } else if pr <= 15 {
        score -= 6.5;
    } else if pr <= 25 {
        score -= 1.0;
    } else if pr <= 40 {
        score += 4.0;
    } else if pr <= 60 {
        score += 8.0;
    } else {
        score += 12.0;
    }

    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size > pr {
            score += pr as f64 * 0.5;
        } else {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 45.0 {
                score += (slack - 45.0) * 0.05;
            }
        }
        // Two-item lookahead: exact pair fit.
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        // Triple/quad lookahead for near-exact multi-fit.
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        if pr > 0 && pr % next_item_size == 0 {
            score -= 1.5;
        }
        // Fragment just barely too small for next item is very bad.
        if frag > 0.0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        // Fragment slightly larger than next item is good.
        if frag > 0.0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        // Mid-range gap after next item fits: waste penalty.
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 {
                score += (gap as f64 - 25.0) * 0.08;
            }
        }
        // Fragment in awkward zone between one and two next-items.
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
            if mean_residual < 16.0 && remaining > 100 {
                score += (frag - next_item_size as f64) * 0.08;
            }
        }
        // Large fragments relative to mean residual waste space.
        if frag > mean_residual && frag > 12.0 {
            score += (frag - mean_residual) * 0.06;
        }
        if frag > 40.0 && remaining > 60 {
            score += (frag - 40.0) * 0.05;
        }
        if frag > 0.0 && frag > mean_residual * 1.6 && remaining > 30 {
            score += (frag - mean_residual * 1.6) * 0.04;
        }
        // Small items: penalize burning a big bin on a tiny item.
        if frag > 0.0 && fill_ratio < 0.42 && remaining > 40 {
            score += (0.42 - fill_ratio) * 16.0 * (1.0 - progress * 0.5);
        }
        // Small items can fill mean-sized gaps: keep bins that can host them.
        if next_item_size <= 10 && mean_residual >= next_item_size as f64 {
            score += 3.0;
        }
    }

    // Mean-residual deviation shaping.
    if pr > 0 && mean_residual > 1.0 {
        let dev = ((pr as f64 - mean_residual) / mean_residual).abs();
        if dev < 0.3 {
            score -= 2.0 * (1.0 - dev / 0.3);
        } else if dev > 1.5 && pr as f64 > mean_residual * 2.0 {
            score += 2.5;
        }
    }

    // Open-bin pressure: prefer tighter packing when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Late-stream tightening.
    score += pr as f64 * (0.1 + 0.2 * progress);

    // ===== New-bin candidate handling =====
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        if item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        if fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 4.0;
        }
        if remaining < 8 && fitting_bins_count > 0 {
            score += 5.0;
        }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 {
            score += 3.0;
        }
        if mean_residual > 30.0 && remaining > 100 {
            score -= 2.0;
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 {
            score += 2.0;
        }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 {
            score -= 3.0;
        }
        if item_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 4.0;
        }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size
            && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size
            && remaining > 30 && open_bins_count > 0 && mean_residual >= next_item_size as f64 {
            score += 6.0;
        }
        // Fresh-bin leftover capacity vs mean residual: penalize if it wastes space.
        let fresh_left = (bin_capacity.saturating_sub(item_size)) as f64;
        if remaining > 60 && fresh_left > 0.0 && fresh_left < mean_residual * 1.25 && open_bins_count > 0 {
            score += (mean_residual * 1.25 - fresh_left) * 0.38;
        }
        if fresh_left <= 6.0 && remaining > 30 {
            score -= 4.0;
        }
        if fitting_bins_count > 0 && fresh_left <= 3.0 && item_ratio > 0.9 {
            score -= 5.0;
        }
    } else {
        // Existing bin: small residual after placement near end of stream is valuable.
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let is_new_bin = bin_residual == bin_capacity;
    let mut score = post_residual as f64;

    // Reward bins that become tightly packed (quadratic in fill fraction)
    let used_frac = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 30.0 * used_frac * used_frac;

    // Harmonic class of post_residual: residuals divisible by 10 are
    // more likely reusable by future items -> reward them
    let harmonic_class = post_residual % 10;
    match harmonic_class {
        0 => score -= 6.0,
        5 => score -= 2.0,
        _ => score += 1.0,
    }

    // Lookahead (k=2): if the next item fits into the post_residual,
    // reward especially tight two-item chains
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_slack = post_residual - next_item_size;
        score -= 10.0 * (1.0 - chain_slack as f64 / bin_capacity as f64);
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item cannot use this residual -> dead space penalty grows
        // with how "wasted" the residual is relative to next item size
        score += 2.0 + 4.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: the only open bin that fits -> strongly prefer it
    // over opening a new bin
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 15.0;
    }

    // New-bin candidate: penalize so it only wins when all fits are bad.
    // Penalty grows slightly over the stream (consolidate early, spread late).
    if is_new_bin {
        score += 12.0 + 6.0 * progress;
    }

    // Coupling with mean residual: prefer bins whose residual is below the
    // mean (concentrate filling into emptier-relative bins)
    score += 0.15 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small gaps (10..25) are only marginally useful; penalize softly.
    if post_residual >= 10 && post_residual < 25 {
        score += 12.0;
    }
    // Perfect fit is the ideal outcome.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 25.0;

    // Open-bin pressure: discourage scattering across many bins unless the fit is good.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly, this placement chains well.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        if post_residual - next_item_size < 10 {
            score -= 10.0;
        }
    }
    // If next item cannot use the leftover, the dead space is more costly.
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // New-bin candidate: attractive early, or when mean residual of open bins is too fragmented,
    // or when this bin's fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 18.0 + progress * 10.0;
        if mean_residual > 40.0 {
            nb -= 15.0; // open bins have plenty of room; opening a new bin is wasteful
        }
        if item_size <= 40 {
            nb += 20.0; // small items should go into existing bins
        }
        if fitting_bins_count > 0 {
            nb += 10.0; // only open new bin if open bins are truly bad
        }
        score += nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
