pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // chain placement, ideal
        } else if next_item_size <= post_residual {
            // next item fits here too: reward proportionally to how snugly
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit in the leftover: penalize large dead space
            let over = (next_item_size - post_residual) as f64;
            score += 0.35 * over;
        }
    }

    // Reward tight fits of the current item (small post_residual).
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 20.0 * tightness * tightness;

    // Compare residual against the mean residual across open bins.
    // A residual below mean means this bin is more filled than average: prefer it.
    score -= 0.25 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a future
    // perfect match or few bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_score = 35.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            new_bin_score -= 30.0; // fresh bin can host both items cleanly
        }
        if open_bins_count == 0 {
            new_bin_score -= 60.0; // no alternative
        }
        if progress < 0.2 {
            new_bin_score += 10.0 * (1.0 - progress); // early stream: consolidate
        }
        score += new_bin_score;
    }

    // Mild penalty for leaving residuals that are hard to fill later
    // (small odd residuals between 1 and 9).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
