    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Fine-grained residual tiers (from best heuristic).
    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 8 {
        score -= 15.0;
    } else if pr <= 15 {
        score -= 6.5;
    } else if pr <= 25 {
        score -= 1.0;
    } else if pr <= 40 {
        score += 4.0;
    } else if pr <= 60 {
        score += 8.0;
    } else {
        score += 12.0;
    }

    // Exact-fit lookahead.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size > pr {
            score += (pr as f64) * 0.5;
        } else {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 {
                score -= 5.0;
            }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 45.0 {
                score += (slack - 45.0) * 0.05;
            }
        }
        // Two-item lookahead: item + next exactly fills the bin.
        if item_size as u64 + next_item_size as u64 == pr as u64 {
            score -= 6.0;
        }
        // Double/triple/quad next-item fits.
        let triple = item_size as u64 + next_item_size as u64 * 2;
        if pr as u64 >= triple && (pr as u64 - triple) <= 10 {
            score -= 2.5 * (1.0 - (pr as u64 - triple) as f64 / 10.0);
        }
        let quad = item_size as u64 + next_item_size as u64 * 3;
        if pr as u64 >= quad && (pr as u64 - quad) <= 6 {
            score -= 1.8 * (1.0 - (pr as u64 - quad) as f64 / 6.0);
        }
        if pr > 0 && pr % next_item_size == 0 {
            score -= 1.5;
        }
        // Frag just below next item size: nearly unusable gap.
        if frag > 0.0 && frag < next_item_size as f64 && next_item_size as f64 - frag <= 4.0 {
            score += (next_item_size as f64 - frag) * 0.9;
        }
        // Frag just above next item size: good host.
        if frag > 0.0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        // Dead space if next can't fit the frag and alternatives exist.
        if frag > 0.0 && frag < next_item_size as f64 {
            let dead = next_item_size as f64 - frag;
            if dead > 6.0 && fitting_bins_count > 1 {
