pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 2.5 * fit_ratio * (item_size as f64);

    // Penalize wasted residual relative to capacity (dead space).
    let waste = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste * waste;

    // Lookahead: reward leaving post_residual that the next item can use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 1.5 * next_item_size as f64 * next_fit;
        } else {
            // Post-residual too small for next item: penalize proportional to uselessness.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bin gets worse appeal when many bins are open (prefer consolidation).
        score += 8.0 + open_bins_count as f64 * 0.5;
        // Early in stream, opening bins is cheap; later, avoid fragmentation.
        score += 20.0 * (1.0 - progress);
        // If mean residual across open bins is large, prefer existing bins.
        score += 0.3 * mean_residual;
    } else {
        // Mild bonus for using an existing bin to keep bin count low.
        score -= 5.0;
        // Prefer bins whose residual deviates from mean? Favor below-mean-residual bins
        // (tighter bins) to keep loose bins for future awkward items.
        score += 0.15 * (mean_residual - bin_residual as f64);
    }

    // Small time-dependent exploration term.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * (progress * std::f64::consts::PI).sin();

    score
}

