    // Penalize dead space that no plausible next item can use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post < nxt {
            score += (nxt - post) * (1.0 + progress);
        } else {
            // reward leaving room for the lookahead item
            score -= 4.0 * (1.0 - (post - nxt) / cap).abs();
        }
    }

    // Reward tight fits: small post_residual relative to item
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness * tightness;

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Mild penalty for spreading across many bins vs mean residual
    score += 0.15 * (mean_residual - post).abs();

    // Prefer filling existing bins as stream progresses
    score += progress * 5.0 * (norm_post - 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;
    let frag = pr as f64 - item_size as f64;

    // Dead-space avoidance: small unusable gaps are heavily penalized.
    if pr > 0 && pr < 10 {
        score += 52.0;
    } else if pr > 0 && pr < 20 {
        score += 24.0;
    } else if pr < 25 {
        score += 22.0 * (1.0 - pr as f64 / 25.0);
    }

    // Reward near-perfect fills.
    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 38.0;
    } else if pr <= 8 {
        score -= 15.0;
    } else if pr <= 12 {
        score -= 10.0;
    } else if pr <= 15 {
        score -= 6.0;
    } else if pr <= 40 {
        score += 4.0;
    } else {
        score += 10.0;
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 58.0; // perfect next fit
        } else if next_item_size > pr {
            score += pr as f64 * 0.45; // dead space for next item
        } else {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 45.0 {
                score += (slack - 45.0) * 0.05;
            }
            // NEW: penalize small dead space after next item lands.
            if slack > 0.0 && slack < 14.0 && fitting_bins_count > 1 {
                score += slack * 0.10 * (1.0 - slack / 14.0);
            }
        }
        // Two/three-item lookahead.
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        // Fragment just barely too small for next item: dead space.
        if frag > 0.0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        // Fragment just barely fits next item: good.
        if frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.5 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        // Gap in awkward zone (25-45) wastes space.
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 {
                score += (gap as f64 - 25.0) * 0.08;
            }
        }
        // Dead space scaled by next item's waste of the residual.
        if pr > next_item_size {
            let dead2 = (pr - next_item_size) as f64;
            if dead2 > 6.0 && fitting_bins_count > 1 {
                score += dead2 * 0.12;
            }
        }
        // Near-perfect two-item closure.
        if pr >= next_item_size && pr - next_item_size <= 1 {
            score -= 3.0;
        }
    }

    // Open-bin pressure: prefer tighter packing when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Slight bias toward bins with larger residuals (better long-term hosts).
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Residual close to mean residual: good future host.
    if pr > 0 && mean_residual > 1.0 {
        let dev = ((pr as f64 - mean_residual) / mean_residual).abs();
        if dev < 0.3 {
            score -= 2.0 * (1.0 - dev / 0.3);
        } else if dev > 1.5 && pr as f64 > mean_residual * 2.0 {
            score += 2.5;
        }
    }

    // Fragments larger than mean residual waste capacity going forward.
    if frag > mean_residual && frag > 12.0 {
        score += (frag - mean_residual) * 0.06;
        if mean_residual < 16.0 && remaining > 100 {
            score += (frag - mean_residual) * 0.08;
        }
    }
    if frag > 40.0 && remaining > 60 {
        score += (frag - 40.0) * 0.05;
    }

    // Small items into large residuals: avoid wasting big gaps.
    let fill_ratio = item_size as f64 / bin_capacity.max(1) as f64;
    if frag > 0.0 && fill_ratio < 0.42 && remaining > 40 {
        score += (0.42 - fill_ratio) * 16.0 * (1.0 - progress * 0.5);
    }

    // Late in the stream, tighten packing further.
    score += pr as f64 * (0.1 + 0.25 * progress);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        // Large items: better to start a fresh bin than fragment a good one.
        if item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        if item_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        // Fresh bin leaves a large usable residual matching mean need.
        let fresh_left = bin_capacity.saturating_sub(item_size) as f64;
        if remaining > 60 && fresh_left > 0.0 && fresh_left < mean_residual * 1.25 && open_bins_count > 0 {
            score += (mean_residual * 1.25 - fresh_left) * 0.38;
        }
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        if mean_residual > 30.0 && remaining > 100 {
            score -= 2.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 4.0;
        }
        if fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 {
            score += 2.0;
        }
        if remaining < 8 && fitting_bins_count > 0 {
            score += 5.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 4.0;
        }
        // Prefer fresh bin when its leftover closely matches mean residual.
        if fresh_left > 0.0 && mean_residual > 1.0 && remaining > 40 {
            let d = (fresh_left - mean_residual).abs();
            if d < 4.0 {
                score -= 2.0 * (1.0 - d / 4.0);
            }
        }
        if fresh_left <= 6.0 && remaining > 30 {
            score -= 4.0;
        }
        if fresh_left > 0.0 && next_item_size > 0 && fresh_left < next_item_size as f64 && remaining > 80 && mean_residual < fresh_left {
            score += (next_item_size as f64 - fresh_left) * 0.15;
        }
    } else {
        score += 60.0;
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 6 && fitting_bins_count > 2 {
            score -= 1.5;
        }
        // Endgame: tighten residual matching in existing bins.
        if remaining < 20 && pr > 0 && mean_residual > 1.0 && (pr as f64 - mean_residual).abs() < 3.0 {
            score -= 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic class of the post-residual: residuals that form "useful" classes
    // (multiples of common item sizes / near-capacity fractions) are rewarded.
    let class = |r: u32| -> f64 {
        let mut bonus = 0.0;
        if r == 0 {
            bonus += 30.0; // perfect closure
        } else if r % 10 == 0 {
            bonus += 8.0; // round class residual
        } else if r % 5 == 0 {
            bonus += 4.0;
        }
        // integer-division thresholds: small residuals are dead space
        if r <= 10 {
            bonus += 12.0 * (11.0 - r as f64) / 10.0;
        } else if r <= 20 {
            bonus += 4.0;
        }
        bonus
    };
    score -= class(post_residual);

    // Fractional capacity coupling: penalize leaving a residual that is a large
    // fraction of capacity but awkwardly sized (between 21 and 50).
    if post_residual > 20 && post_residual < 50 {
        score += (50 - post_residual) as f64 * 0.15;
    }

    // Lookahead harmony: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 * (1.0 - slack as f64 / cap);
            if slack % 10 == 0 { score -= 5.0; }
        } else {
            score += 6.0; // next item cannot follow here
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive if it enables a near-full packing
    // (item nearly fills it) or many bins are open with wasted mean residual.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / cap;
        let mut new_bin_score = 100.0 - 60.0 * fill_ratio;
        if fitting_bins_count == 0 { new_bin_score -= 100.0; }
        // if open bins are fragmented, opening fresh can help
        if mean_residual / cap < 0.25 && open_bins_count > 3 {
            new_bin_score -= 20.0;
        }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            new_bin_score -= 25.0;
        }
        score = new_bin_score;
    }

    // Mild progression term: late in the stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (cap - pr) * 0.05;
    score += open_bins_count as f64 * 0.3;

    score
}

