        }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size && remaining > 30 && open_bins_count > 0 && mean_residual >= next_item_size as f64 {
