}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a plausible future item (below the minimum item size of 1-10)
    // are pure waste. Penalize hard when post_residual is in the "dead zone".
    let dead_threshold = 10.0_f64.min(item_size as f64);
    if (post_residual as f64) < dead_threshold {
        score += 60.0; // unusable sliver -> strongly discourage
    } else if post_residual == 0 {
        score -= 120.0; // perfect fit: best possible outcome
    }

    // Tightness reward: fraction of the bin's space consumed by this item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Penalize leaving a gap that is large enough to be useful but awkward:
    // a post_residual just barely above the next item is fragile.
    if next_item_size > 0 && post_residual > 0 {
        let gap_ratio = next_item_size as f64 / post_residual as f64;
        if gap_ratio > 0.9 && gap_ratio <= 1.0 {
            score -= 15.0; // next item fits almost exactly: reserve this bin
        } else if gap_ratio < 0.25 && post_residual < 40 {
            score += 12.0; // small awkward remainder, next item much smaller
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; with few bins, be lenient.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when
    // no existing bin offers a decent fit. Give the empty bin a baseline
    // cost that grows with how many bins are already open, and make it
    // unattractive when the current item fits snugly somewhere.
    if bin_residual == bin_capacity {
        score = 55.0 + 2.5 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // a fresh bin also accommodates the lookahead item
        }
    }

    // Late in the stream, avoid leaving many scattered small residuals:
    // consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: if the next item exactly fills the post residual,
    // strongly reward this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 1000.0;
        } else if next_item_size <= post_residual {
            // Next item fits here too: reward closeness of the final leftover to zero.
            let final_leftover = post_residual - next_item_size;
            score -= 50.0 + (final_leftover as f64).min(40.0);
        } else {
            // Next item won't fit after placing: penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 10.0 + gap * 0.3;
        }
    }

    // Penalize tiny unusable dead space (waste), reward leaving a useful-sized gap.
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        score += (10.0 - pr) * 4.0;
    }

    // Compare post_residual against mean residual across open bins:
    // placing into a bin whose residual is far below mean helps balance.
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.5;
    } else {
        score += (pr - mean_residual) * 0.2;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate (empty bin): only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        score += 120.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Opening a new bin is fine if item + next item nearly fill it together.
            let combined = item_size + next_item_size;
            if combined >= bin_capacity * 9 / 10 {
                score -= 150.0;
            }
        }
    }

    // Early in the stream, encourage consolidation into few bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: tiny residuals are excellent.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        score -= 30.0 / post_residual as f64;
    }

    // Lookahead: reward when the next item fits exactly into the resulting space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 40.0 - 0.3 * (post_residual - next_item_size) as f64;
        } else {
            // Penalize creating a gap the next item can't use, scaled by dead space.
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // New-bin candidate handling: opening a new bin wastes residual capacity
    // of existing bins; only attractive when existing fits are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for abandoning open capacity.
        score += 60.0;
        // If many bins fit, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 80.0 * (fitting_bins_count as f64).min(5.0);
        }
        // If this item would leave a large awkward gap elsewhere, new bin gains appeal.
        let gap_elsewhere = (bin_capacity - item_size) as f64;
        score -= 0.4 * gap_elsewhere;
        // Late in the stream, prefer closing out bins tightly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * (1.0 - progress);
    } else if fitting_bins_count == 1 {
        // Last chance bin: strongly favor using it to avoid a new bin.
        score -= 120.0;
    }

    // Global state: many open bins with high mean residual -> prefer tightening.
    let mean_res_gap = (mean_residual - post_residual as f64).abs();
    score += 0.1 * mean_res_gap;
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Mild preference for bins whose residual is close to item size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 25.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = pr as f64 - item_size as f64;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Exact-fit lookahead: leaving room exactly equal to the next item is ideal.
    if next_item_size > 0 && pr == next_item_size {
        score -= 70.0;
    } else if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 8 {
        score -= 15.0;
    } else if pr <= 15 {
        score -= 6.5;
    } else if pr <= 25 {
        score -= 1.0;
    } else if pr <= 40 {
        score += 4.0;
    } else if pr <= 60 {
        score += 8.0;
    } else {
        score += 12.0;
    }

    // Dead-space avoidance tiers.
    if pr > 0 && pr < 10 {
        score += 55.0;
    } else if pr > 0 && pr < 20 {
        score += 25.0;
    } else if pr > 0 && pr < 30 {
        score += 8.0;
    }

    if next_item_size > 0 {
        if next_item_size > pr {
            // Next item can't use leftover: penalty grows with wasted gap.
            score += (pr as f64) * 0.45;
        } else {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 {
                score -= 5.0;
            }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 45.0 {
                score += (slack - 45.0) * 0.05;
            }
        }
        // Two-item lookahead: item + next exactly fills the bin.
        if item_size as u64 + next_item_size as u64 == pr as u64 {
            score -= 6.0;
        }
        // Double/triple next-item fits.
        let triple = item_size as u64 + next_item_size as u64 * 2;
        if pr as u64 >= triple && (pr as u64 - triple) <= 10 {
            score -= 2.5 * (1.0 - (pr as u64 - triple) as f64 / 10.0);
        }
        let quad = item_size as u64 + next_item_size as u64 * 3;
        if pr as u64 >= quad && (pr as u64 - quad) <= 6 {
            score -= 1.8 * (1.0 - (pr as u64 - quad) as f64 / 6.0);
        }
        // Frag just below next item size: nearly unusable gap.
        if frag > 0.0 && frag < next_item_size as f64 && (next_item_size as f64 - frag) <= 5.0 {
            score += (next_item_size as f64 - frag) * 1.2;
        }
        // Frag comfortably above next item size: good host.
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score -= 2.0;
            if mean_residual < 16.0 && remaining > 100 {
                score += (frag - next_item_size as f64) * 0.08;
            }
        }
        // Dead-space penalty scaled by how much of the residual the next item wastes.
        if pr > next_item_size {
            let dead2 = (pr - next_item_size) as f64;
            if dead2 > 0.0 && dead2 < 14.0 && fitting_bins_count > 1 {
                score += dead2 * 0.10 * (1.0 - dead2 / 14.0);
            }
        }
        // Reward near-perfect two-item closure.
        if pr >= next_item_size && pr - next_item_size <= 1 {
            score -= 3.0;
        }
        if pr > 0 && pr % next_item_size == 0 {
            score -= 1.5;
        }
    }

    // Frag relative to mean residual: big leftover space is costly.
    if frag > mean_residual && frag > 12.0 {
        score += (frag - mean_residual) * 0.06;
    }
    if frag > 40.0 && remaining > 60 {
        score += (frag - 40.0) * 0.05;
    }
    if frag > 0.0 && frag > mean_residual * 1.6 && remaining > 30 {
        score += (frag - mean_residual * 1.6) * 0.04;
    }
    if next_item_size > 0 && frag > 0.0 && frag < next_item_size as f64 {
        let dead = next_item_size as f64 - frag;
        if dead > 6.0 && fitting_bins_count > 1 {
            score += dead * 0.12;
        }
    }

    // Small items early: prefer spreading into residual space.
    let fill_ratio = item_size as f64 / bin_capacity.max(1) as f64;
    if frag > 0.0 && fill_ratio < 0.42 && remaining > 40 {
        score += (0.42 - fill_ratio) * 16.0 * (1.0 - progress * 0.5);
    }

    // Residual close to mean: keep bins homogeneous.
    if pr > 0 && mean_residual > 1.0 {
        let dev = ((pr as f64 - mean_residual) / mean_residual).abs();
        if dev < 0.3 {
            score -= 2.0 * (1.0 - dev / 0.3);
        } else if dev > 1.5 && pr as f64 > mean_residual * 2.0 {
            score += 2.5;
        }
    }

    // Progress-weighted leftover penalty.
    score += pr as f64 * (0.1 + 0.2 * progress);

    // ---- NEW-BIN CANDIDATE HANDLING ----
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure
            + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        if fill_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * fill_ratio;
        }
        if fill_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        if fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        if next_item_size > 0 && item_size as u64 + next_item_size as u64 > bin_capacity as u64 {
            score -= 4.0;
        }
        if remaining < 8 && fitting_bins_count > 0 {
            score += 5.0;
        }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 {
            score += 3.0;
        }
        if mean_residual > 30.0 && remaining > 100 {
            score -= 2.0;
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 {
            score += 2.0;
        }
        if fill_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 {
            score -= 3.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 4.0;
        }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size
            && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size && remaining > 30
            && open_bins_count > 0 && mean_residual >= next_item_size as f64 {
            score += 6.0;
        }
        // Fresh bin leftover close to mean residual: opening may be fine.
        let fresh_left = bin_capacity.saturating_sub(item_size) as f64;
        if remaining > 60 && fresh_left > 0.0 && fresh_left < mean_residual * 1.25 && open_bins_count > 0 {
            score += (mean_residual * 1.25 - fresh_left) * 0.38;
        }
        if fresh_left <= 6.0 && remaining > 30 {
            score -= 4.0;
        }
        if fitting_bins_count > 0 && fresh_left <= 3.0 && fill_ratio > 0.9 {
            score -= 5.0;
        }
        if fresh_left > 0.0 && fresh_left < next_item_size as f64 && remaining > 80 && mean_residual < fresh_left {
            score += (next_item_size as f64 - fresh_left) * 0.15;
        }
        // Prefer opening a fresh bin when its leftover closely matches mean residual.
        if fresh_left > 0.0 && mean_residual > 1.0 && remaining > 40 {
            let d = (fresh_left - mean_residual).abs();
            if d < 4.0 {
                score -= 2.0 * (1.0 - d / 4.0);
            }
        }
    } else {
        // Existing-bin bonus: prefer open bins over new ones.
        score += 60.0;
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        // Last-chance bin: strong preference.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        if next_item_size > 0 && pr >= next_item_size && (pr - next_item_size) <= 6 && fitting_bins_count > 2 {
            score -= 1.5;
        }
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        // Endgame: tighten residual matching in existing bins.
        if remaining < 20 && pr > 0 && mean_residual > 1.0 && ((pr as f64) - mean_residual).abs() < 3.0 {
            score -= 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_post = post / cap;

    // base: prefer small post residual (tight fit)
    let mut score = post;

    // non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (1.0 - progress) + norm_post * progress * progress;
    score += 40.0 * poly;

    // reward tight fits more strongly late in the stream
    score -= (item_size as f64 / cap) * 20.0 * (0.5 + progress);

    // penalize when the leftover can't fit the lookahead item
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0 * (1.0 - progress);
    } else if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    // last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // many open bins: mild penalty on large residuals to consolidate
    score += (open_bins_count as f64).ln() * norm_post * 8.0;

    // deviation from mean residual: prefer bins below/above mean adaptively
    let dev = (post - mean_residual) / cap;
    score += 10.0 * dev * dev * (1.0 - progress);

    // new-bin candidate: penalize so it's only chosen when fits are terrible
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;
    let frag = pr as f64 - item_size as f64;

    // Dead-space avoidance: heavily penalize tiny unusable residuals.
    if pr > 0 && pr < 10 {
        score += 52.0;
    } else if pr < 25 {
        score += 22.0 * (1.0 - pr as f64 / 25.0);
    }

    // Reward near-perfect fills.
    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 8 {
        score -= 15.0;
    } else if pr <= 15 {
        score -= 8.0;
    } else if pr <= 25 {
        score -= 1.0;
    } else if pr <= 40 {
        score += 4.0;
    } else if pr <= 60 {
        score += 8.0;
    } else {
        score += 12.0;
    }

    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0; // perfect next fit
        } else if next_item_size > pr {
            score += pr as f64 * 0.5;
        } else {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 {
                score -= 5.0;
            }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 45.0 {
                score += (slack - 45.0) * 0.05;
            }
            // near-perfect two-item closure
            if slack <= 1.0 {
                score -= 3.0;
            }
            // penalize small dead waste after next item when alternatives exist
            if slack > 0.0 && slack < 14.0 && fitting_bins_count > 1 {
                score += slack * 0.10 * (1.0 - slack / 14.0);
            }
        }
        // Two-item lookahead.
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        // Triple-item lookahead.
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        // Fragment just below next item: dead space warning.
        if frag > 0.0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        // Fragment just above next item: nearly reusable.
        if frag > 0.0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        // Wide dead gap for next item with alternatives available.
        if frag > 0.0 && frag < next_item_size as f64 {
            let dead = next_item_size as f64 - frag;
            if dead > 6.0 && fitting_bins_count > 1 {
                score += dead * 0.12;
            }
        }
        // Fragment in awkward zone between next item and double next.
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
            if mean_residual < 16.0 && remaining > 100 {
                score += (frag - next_item_size as f64) * 0.08;
            }
        }
        // Residual divisible by next item: chain-friendly.
        if pr > 0 && pr % next_item_size == 0 {
            score -= 1.5;
            if pr / next_item_size >= 2 && remaining > 50 {
                score -= 2.0 * ((pr / next_item_size) as f64).min(3.0);
            }
        }
        // Gap just over next item but less than half residual — mild reward.
        if pr > next_item_size && (pr - next_item_size) * 2 <= pr {
            score -= 1.2;
        }
        // Penalize leaving residual just below mean residual (dead space).
        if pr > 0 && mean_residual > 2.0 && (pr as f64) < mean_residual && (mean_residual - pr as f64) < 6.0 {
            score += (mean_residual - pr as f64) * 0.35;
        }
    }

    // Open-bin pressure.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Bias toward bins with larger residuals.
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Large fragments waste future capacity.
    if frag > mean_residual && frag > 12.0 && remaining > 30 {
        score += (frag - mean_residual) * 0.06;
    }
    if frag > 40.0 && remaining > 60 {
        score += (frag - 40.0) * 0.05;
    }
    if frag > 0.0 && frag > mean_residual * 1.6 && remaining > 30 {
        score += (frag - mean_residual * 1.6) * 0.04;
    }
    // Small-item fragments penalized more late in stream.
    let fill_ratio = item_size as f64 / bin_capacity.max(1) as f64;
    if frag > 0.0 && fill_ratio < 0.42 && remaining > 40 {
        score += (0.42 - fill_ratio) * 16.0 * (1.0 - progress * 0.5);
    }

    // Residual close to mean residual: easy to reuse later.
    if pr > 0 && mean_residual > 1.0 {
        let dev = ((pr as f64 - mean_residual) / mean_residual).abs();
        if dev < 0.3 {
            score -= 2.0 * (1.0 - dev / 0.3);
        } else if dev > 1.5 && pr as f64 > mean_residual * 2.0 {
            score += 2.5;
        }
    }

    // Late in the stream, tighten packing further.
    score += pr as f64 * (0.1 + 0.22 * progress);

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        if item_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        let fresh_left = bin_capacity.saturating_sub(item_size) as f64;
        if remaining > 60 && fresh_left > 0.0 && fresh_left < mean_residual * 1.25 && open_bins_count > 0 {
            score += (mean_residual * 1.25 - fresh_left) * 0.38;
        }
        if fresh_left <= 6.0 && remaining > 30 {
            score -= 4.0;
        }
        if item_ratio > 0.9 && fresh_left <= 3.0 && fitting_bins_count > 0 {
            score -= 5.0;
        }
        // Fresh bin leftover closely matching mean residual is a good future host.
        if fresh_left > 0.0 && mean_residual > 1.0 && remaining > 40 {
            let d = (fresh_left - mean_residual).abs();
            if d < 4.0 {
                score -= 2.0 * (1.0 - d / 4.0);
            }
        }
        // Chain-friendly fresh leftover: exact multiple of next item.
        if next_item_size > 2 && fresh_left > 0.0 && fresh_left % next_item_size as f64 == 0.0 && fresh_left / next_item_size as f64 >= 2.0 && remaining > 60 {
            score -= 2.5;
        }
        // Discourage fresh bin when leftover sits just under the next item.
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && (next_item_size as f64 - fresh_left) <= 8.0 && remaining > 40 {
            score += (next_item_size as f64 - fresh_left) * 0.5;
        }
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity && mean_residual >= next_item_size as f64 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 {
            score += 3.0;
        }
        if fitting_bins_count > 0 {
            score += 4.0;
        }
        if remaining < 8 && fitting_bins_count > 0 {
            score += 5.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 4.0;
        }
        if remaining < 15 && fitting_bins_count > 0 {
            score += 3.0;
        }
    } else {
        score += 60.0;
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 6 && fitting_bins_count > 2 {
            score -= 1.5;
        }
        // Endgame — favor residuals matching mean residual.
        if remaining < 20 && pr > 0 && mean_residual > 1.0 && ((pr as f64) - mean_residual).abs() < 3.0 {
            score -= 1.5;
        }
        // Endgame — strong bonus for exact-closure residuals.
        if remaining < 35 && next_item_size > 0 && pr == next_item_size {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let r = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = r;

    // --- Harmonic ideal: perfect fill (residual class "infinity") ---
    if post_residual == 0 {
        score -= 1000.0;
    }

    // --- Harmonic dead-space penalty ---
    // Residual class k = floor(cap / r): the larger k, the smaller (less useful) the leftover.
    // Leftovers below ~cap/8 fall into increasingly "dead" harmonic bands.
    if post_residual > 0 {
        let r_class = (cap / r).floor();
        let dead = (r_class - 8.0).max(0.0);
        let time_scale = 1.2 - 0.6 * progress; // late in the stream, dead space matters less
        score += dead * (2.0 + 0.1 * dead) * time_scale;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= r {
            // chain fit: this bin can also absorb the next item
            score -= 12.0 + 0.25 * nxt;
        } else {
            let miss = nxt - r;
            if miss <= 12.0 {
                // near miss: leftover just barely fails the next item
                score += miss * 1.5;
            }
        }
    }

    // --- Harmonic same-class repetition ---
    // Another item of the same harmonic class still fits the leftover.
    if item_size > 0 && post_residual >= item_size {
        score -= 6.0;
        // modulo test: leftover tiles perfectly by same-class items
        if post_residual % item_size == 0 {
            score -= 4.0;
        }
    }

    // --- Last-chance bin: only open bin that can take this item ---
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // --- Consolidation bias: prefer bins already fuller than the mean residual ---
    let consol = (bin_residual as f64 - mean_residual) * 0.15;
    score += consol.max(-20.0).min(20.0);

    // --- New-bin candidate penalty ---
    if bin_residual == bin_capacity {
        score += 55.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            // nothing open fits: opening a new bin is mandatory
            score -= 1000.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;
    let frag = pr as f64 - item_size as f64;

    // Dead-space avoidance: small unusable gaps are heavily penalized.
    if pr > 0 && pr < 10 {
        score += 55.0;
    } else if pr < 25 {
        score += 22.0 * (1.0 - pr as f64 / 25.0);
    }

    // Reward near-perfect fills.
    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 35.0;
    } else if pr <= 12 {
        score -= 10.0;
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0; // perfect next fit
        } else if next_item_size > pr {
            score += pr as f64 * 0.4; // dead space for next item
        } else {
            let slack = (pr - next_item_size) as f64;
            score -= 6.0 + 9.0 / (1.0 + slack);
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 45.0 {
                score += (slack - 45.0) * 0.05;
            }
        }
        // Two-item lookahead: next item fits twice more.
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        // Quad-chain lookahead (borrowed idea): residual hosts current + 3 next items.
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        // Residual-divisibility chain lookahead.
        if pr > 0 && pr % next_item_size == 0 && pr / next_item_size >= 2 && remaining > 50 {
            score -= 2.0 * ((pr / next_item_size) as f64).min(3.0);
        }
        // Penalize residual just below mean residual (future dead space).
        if pr > 0 && mean_residual > 2.0 && (pr as f64) < mean_residual && (mean_residual - pr as f64) < 6.0 {
            score += (mean_residual - pr as f64) * 0.35;
        }
        // Dead-space penalty scaled by next-item waste, when alternatives exist.
        if pr > next_item_size {
            let dead2 = (pr - next_item_size) as f64;
            if dead2 > 0.0 && dead2 < 14.0 && fitting_bins_count > 1 {
                score += dead2 * 0.10 * (1.0 - dead2 / 14.0);
            }
        }
    }

    // Open-bin pressure: prefer tighter packing when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Slight bias toward bins with larger residuals (better long-term hosts).
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Fragments larger than mean residual waste capacity going forward.
    if frag > mean_residual && frag > 12.0 && remaining > 30 {
        score += (frag - mean_residual) * 0.06;
    }

    // Late in the stream, tighten packing further.
    score += pr as f64 * (0.1 + 0.25 * progress);

