            score -= 3.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        if fitting_bins_count > 0 {
            score += 4.0;
        }
        if remaining < 8 && fitting_bins_count > 0 {
            score += 5.0;
        }
        // NEW: chain-friendly fresh bin — leftover exact multiple of next item.
        if next_item_size > 2 && fresh_left > 0.0 && fresh_left % next_item_size as f64 == 0.0 && fresh_left / next_item_size as f64 >= 2.0 && remaining > 60 {
            score -= 2.5;
        }
        // NEW: discourage fresh bin whose leftover sits just under next item.
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && (next_item_size as f64 - fresh_left) <= 8.0 && remaining > 40 {
            score += (next_item_size as f64 - fresh_left) * 0.5;
        }
        // NEW: fresh bin leftover close to mean residual is a good long-term host.
        if fresh_left > 0.0 && mean_residual > 1.0 && remaining > 40 {
            let d = (fresh_left - mean_residual).abs();
            if d < 4.0 {
                score -= 2.0 * (1.0 - d / 4.0);
            }
        }
        // NEW: tiny leftover fresh bin is wasteful when alternatives exist.
        if fresh_left <= 6.0 && remaining > 30 && fitting_bins_count > 0 {
            score -= 4.0;
        }
    } else {
        score += 60.0;
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        // NEW: endgame exact-closure bonus.
        if remaining < 35 && next_item_size > 0 && pr == next_item_size {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Perfect fits are gold: zero residual means zero waste.
    if post_residual == 0 {
        score -= 60.0;
    }
    // Tiny nonzero gaps (hard to fill later) are heavily penalized.
    else if post_residual < 8 {
        score += 25.0 + (8 - post_residual) as f64 * 4.0;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if next_item_size == post_residual {
            // Sets up a perfect follow-up fit: strong reward.
            score -= 30.0;
        } else if next_item_size < post_residual {
            // Next item fits here; reward closeness to an exact fit.
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / 100.0);
        } else {
            // Next item cannot use this residual: mild penalty.
            score += 3.0;
        }
    }

    // --- Last-chance pressure ---
    // If this is the ONLY open bin that fits, use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // --- Open-bins pressure on the new-bin candidate ---
    if bin_residual == bin_capacity {
        let pressure = 10.0
            + 1.5 * open_bins_count as f64
            + 0.5 * (fitting_bins_count as f64).max(1.0);
        score += pressure;
    }

    // --- Favor bins that are already well-filled (below mean residual) ---
    let progress = (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
    score -= 10.0 * progress;

    // Mild compaction tie-break: prefer bins with less remaining space.
    score += 0.05 * bin_residual as f64;

    score
}

