        // Gap just over next item but less than half residual: mild reward.
        if pr > next_item_size && (pr - next_item_size) * 2 <= pr {
            score -= 1.2;
        }
        // Reward near-perfect two-item closure.
        if pr >= next_item_size && pr - next_item_size <= 1 {
            score -= 3.0;
        }
        // Penalize leaving residual just below mean residual (unusable dead space).
        if pr > 0 && mean_residual > 2.0 && (pr as f64) < mean_residual && (mean_residual - pr as f64) < 6.0 {
