    if post_residual > 0 {
        let dead = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { post_residual as f64 };
        score += dead * 0.6;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Encourage packing into fuller bins when many bins are open
    // (reduce fragmentation across the fleet).
    if open_bins_count > 1 {
        let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= fullness * 5.0;
    }

    // Time-horizon modulation: early in the stream, be more willing to
    // open new bins (penalize existing bins slightly less aggressively);
    // late in the stream, consolidate hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 4.0;

    // Compare against fleet mean residual: bins far below mean residual
    // (i.e. unusually full) are extra valuable.
    score -= (mean_residual - bin_residual as f64) * 0.1;

    // Mild penalty for opening a brand-new bin when other bins fit.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 15.0 - progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let phase = progress * std::f64::consts::PI;
    let coupling = pr_norm * pr_norm * (1.0 - progress) * (1.0 - progress) * cap;
    score += 0.35 * coupling;

    // Penalize residuals that neither fit next item nor are tiny (dead space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (pr - nxt) / cap;
        } else {
            let waste = (nxt - pr) / cap;
            score += 10.0 * waste * waste;
        }
    }

    // Last-chance bin: reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 * (1.0 - progress);
    }

    // Smooth penalty for spreading across many bins
    score += 0.5 * open_bins_count as f64 * (pr_norm);

    // Favor tight fits via cubic term on wasted fraction
    let tight = 1.0 - pr_norm;
    score -= 4.0 * tight * tight * tight * (0.5 + 0.5 * (1.0 - progress));

    // Mild alignment with mean residual state
    score += 0.15 * (pr - mean_residual);

    score
}

