pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (harmonic class 0 of capacity quantum 10)
    let quantum = 10u32;
    let post_mod = post_residual % quantum;
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_mod == 0 {
        score -= 25.0; // dead space aligned to quantum -> reusable by future items
    } else if post_mod <= 2 {
        score -= 8.0;
    } else if post_mod >= quantum - 2 {
        score += 6.0; // nearly aligned but wasteful sliver
    } else {
        score += 4.0; // mid-class fragmentation
    }

    // Integer-division threshold on post_residual: small leftovers are good
    let post_class = post_residual / quantum;
    score += match post_class {
        0 => -15.0,           // <= 9 left
        1 => -6.0,            // 10..19
        2 => 0.0,             // 20..29
        3 => 4.0,             // 30..39
        _ => 8.0,             // large leftover
    } as f64;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            let nm = next_post % quantum;
            if nm == 0 { score -= 18.0; } else { score -= 4.0; }
        } else {
            // next item cannot use this bin's leftover; penalize proportionally
            score += (next_item_size.min(post_residual.max(next_item_size) ) as f64) * 0.05;
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Prefer bins with lower residual relative to mean (denser bins first)
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Slight penalty for spreading across many open bins when residual is large
    if open_bins_count > 4 && post_residual > bin_capacity / 2 {
        score += 3.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        let best_possible = if next_item_size > 0 { (bin_capacity - item_size - next_item_size.min(bin_capacity - item_size)) as f64 } else { (bin_capacity - item_size) as f64 };
        // Neutral baseline; opening a new bin is fine early, penalized when many bins already open
        score = (bin_capacity - item_size) as f64 * 0.9 + (open_bins_count as f64) * 2.0 - best_possible * 0.1;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Mild stream-progression term: tighten packing as stream advances
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 {
        if post_residual < 10 {
            // Absolute dead space: smallest item can never use it.
            score += 500.0;
        } else if post_residual <= 20 {
            score += 150.0;
        } else if post_residual <= 35 {
            score += 40.0;
        } else {
            // Larger gaps are reusable; mild quadratic penalty.
            let r = post_residual as f64;
            score += 0.02 * (100.0 - r) * (100.0 - r) / 10.0;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 300.0;
    }

    // Reward tight fits relative to residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 80.0 * fit_ratio * fit_ratio;

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += 6.0 * open_bins_count as f64;

    // If this bin is the last chance to fit, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: prefer it only if it avoids creating dead space
    // (i.e., when current item is large and mean residual is small).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_bonus = 120.0
            - 0.8 * mean_residual
            - 60.0 * (item_size as f64 / 100.0)
            - 50.0 * progress;
        score += new_bin_bonus;
        // Opening a new bin is bad if the item would leave a small gap.
        if post_residual > 0 && post_residual < 20 {
            score += 100.0;
        }
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 70.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 60.0;
    }

    // Slight preference for bins with below-average residual (keep fat bins fat).
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.3 * diff;
    }

    score
}

