    }

    // New-bin candidate: penalize opening a new bin unless existing bins are hopeless
    if bin_residual == bin_capacity {
        score += 20.0;
        // but if next item is large and current item is small, opening fresh bin can be good
        if next_item_size > item_size + 20 {
            score -= 25.0;
        }
    }

    // Late in stream: be more conservative, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

