pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = pr as f64 - item_size as f64;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Dead-space avoidance ladder
    if pr == 0 {
        score -= 300.0;
    } else if pr < 10 {
        score += 500.0;
    } else if pr <= 20 {
        score += 150.0;
    } else if pr <= 35 {
        score += 40.0;
    } else {
        let r = pr as f64;
        score += 0.02 * (100.0 - r) * (100.0 - r) / 10.0;
    }

    // Tight-fit reward
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 80.0 * fit_ratio * fit_ratio;

    // Bin-count pressure
    score += 6.0 * open_bins_count as f64;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Lookahead: next item fits in post residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 90.0; // exact closure lookahead
        } else if pr >= next_item_size {
            score -= 70.0;
            let slack = (pr - next_item_size) as f64;
            if slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 45.0 {
                score += (slack - 45.0) * 0.05;
            }
        } else if pr > 0 && pr < next_item_size {
            let dead = (next_item_size - pr) as f64;
            if dead <= 8.0 {
                score += dead * 0.5; // guaranteed dead space
            } else {
                score += 60.0;
            }
        }
        // two- and three-item closure lookahead
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        // divisibility chain reward
        if pr > 0 && pr >= next_item_size && pr % next_item_size == 0 && pr / next_item_size >= 2 && remaining > 50 {
            score -= 2.0 * ((pr / next_item_size) as f64).min(3.0);
        }
    }

    // Penalize residual just below mean residual (unusable gap)
    if pr > 0 && mean_residual > 2.0 && (pr as f64) < mean_residual && (mean_residual - pr as f64) < 6.0 {
        score += (mean_residual - pr as f64) * 0.35;
    }

    // Keep fat bins fat
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.3 * diff;
    }

    // Frag-based dead-space pressure
    if frag > 0.0 && frag > 12.0 && frag > mean_residual {
        score += (frag - mean_residual) * 0.06;
    }
    if frag > 40.0 && remaining > 60 {
        score += (frag - 40.0) * 0.05;
    }

    // New-bin candidate logic
    if bin_residual == bin_capacity {
        let new_bin_bonus = 120.0
            - 0.8 * mean_residual
            - 60.0 * (item_size as f64 / 100.0)
            - 50.0 * progress;
        score += new_bin_bonus;
        if pr > 0 && pr < 20 {
            score += 100.0;
        }
        // fresh-bin leftover analysis
        let fresh_left = bin_capacity.saturating_sub(item_size) as f64;
        if remaining > 60 && fresh_left > 0.0 && fresh_left < mean_residual * 1.25 && open_bins_count > 0 {
            score += (mean_residual * 1.25 - fresh_left) * 0.38;
        }
        if fresh_left <= 6.0 && remaining > 30 {
            score -= 4.0;
        }
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && (next_item_size as f64 - fresh_left) <= 8.0 && remaining > 40 {
            score += (next_item_size as f64 - fresh_left) * 0.5;
        }
        if next_item_size > 2 && fresh_left > 0.0 && fresh_left % next_item_size as f64 == 0.0 && fresh_left / next_item_size as f64 >= 2.0 && remaining > 60 {
            score -= 2.5;
        }
        // large item late in stream: open a bin rather than fragment
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 {
            score -= 3.0;
        }
        if item_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 4.0;
        }
    } else {
        score += 60.0; // bias toward existing bins by default
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        if remaining < 35 && next_item_size > 0 && pr == next_item_size {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Perfect or near-perfect fit gets a strong bonus
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 {
        // Dead space relative to the upcoming item
        score += 0.25 * (next_item_size as f64 - post_residual as f64).min(60.0);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer consolidation into existing bins
    if open_bins_count > 3 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    // Global mean residual coupling: prefer bins near the mean residual (balanced packing)
    score += 0.10 * (bin_residual as f64 - mean_residual).abs();

    // Time horizon: early in the stream, be more conservative (favor new bins less);
    // late in the stream, squeeze everything in
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: neutral baseline, slightly penalized so it's chosen
    // only when existing bins would create large dead space
    if bin_residual == bin_capacity {
        score = 0.45 * bin_capacity as f64
            - 0.5 * item_size as f64
            + if next_item_size > 0 && next_item_size <= bin_capacity { 8.0 } else { 0.0 }
            + (fitting_bins_count as f64).recip() * 5.0;
    }

    score
}

