#[inline]
fn item_ratio_check(item_size: u32, bin_capacity: u32) -> f64 {
    item_size as f64 / bin_capacity.max(1) as f64
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: strongly reward (post_residual == 0).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Harmonic class of post_residual: dead space in small "unusable" classes
        // is penalized more because only tiny items (1..=10) can fill it.
        let dead_zone = if post_residual < 10 { 3.0 } else if post_residual < 20 { 1.5 } else { 0.0 };
        score += dead_zone * (post_residual as f64);

        // Modulo-10 harmonic classes: post_residual in the class 1..10 (mod 10)
        // is harder to fill than multiples of 10.
        let class = post_residual % 10;
        if class != 0 {
            score += (10 - class) as f64 * 0.5;
        } else {
            score -= 5.0; // divisible by 10: reusable chunk
        }

        // Reward if the NEXT item fits exactly into post_residual (lookahead chaining).
        if next_item_size > 0 && next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual && next_item_size > 0 {
            // next item won't fit here; residual becomes dead space
            score += (post_residual as f64) * 0.3;
        }

        // Last-chance bin: if this is the only bin that fits, strongly favor using it.
        if fitting_bins_count == 1 {
            score -= 150.0;
        }

        // Prefer bins with low residual relative to mean (tight packing).
        score -= (mean_residual - post_residual as f64).max(0.0) * 0.2;

        // Early in stream: be pickier about creating tiny residuals.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if post_residual < 15 {
            score += (1.0 - progress) * 40.0;
        }
    }

    // New-bin candidate: penalize opening a new bin unless open bins are poor fits.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are only chosen when clearly better.
        score += 120.0;
        // If many bins already open and mean residual is large, discourage new bin more.
        if open_bins_count > 0 {
            score += mean_residual * 0.8;
        }
        // If next item is large, a fresh bin is more attractive (room to co-pack).
        if next_item_size >= 50 {
            score -= 30.0;
        }
    }

    score
}

