pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Medium gaps (10..20) mildly penalized since few item sizes fit them.
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Reward perfect / near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Reward bins that can also fit the lookahead item in the leftover space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: prefer denser bins when many are open.
    score += 0.05 * open_bins_count as f64;

    // Align with mean residual: bins tighter than average are preferred.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: prefer it only when it enables a big lookahead fit
    // or when existing bins would leave very tight dead space.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 12.0;
        }
        // Slight bias against opening new bins early in the stream.
        score += 5.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    score
}

