pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / (total_items - 1) as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr;

    // Smooth non-linear polynomial coupling: penalize residuals near unusable dead-space zones
    // dead-space term grows as post_residual becomes small but nonzero
    let dead = (norm_pr * (1.0 - norm_pr)).max(0.0); // peaks at 0.25 residual
    score += 18.0 * dead * (1.0 - norm_pr).powi(2);

    // Perfect fit reward (post_residual near 0)
    score -= 12.0 * (-pr / 6.0).exp();

    // Favor tighter bins more strongly later in the stream
    score -= progress * (item_size as f64 / cap) * 8.0;

    // Last-chance bonus: only one bin can fit the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (0.5 + progress);
    }

    // New-bin candidate: penalize mildly early, more if it wastes space vs mean residual
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * (1.0 - progress);
        // encourage opening new bin if open bins are fragmented
        if mean_residual < item_size as f64 {
            score -= 8.0;
        }
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 10.0 * (1.0 - (next_item_size as f64 / pr.max(1.0)) * 0.5);
        } else {
            score += 4.0 * (1.0 - progress);
        }
    }

    // Fragmentation pressure: more open bins -> prefer filling existing ones
    score += (open_bins_count as f64).ln().max(0.0) * 1.5 * norm_pr;

    score
}

