    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "nice"
    // divisors / multiples of common item sizes (harmonic packing classes).
    let post = post_residual;
    let classes = [100u32, 50, 25, 20, 10, 40, 60, 80, 30, 70];
    let mut harmonic_bonus = 0.0f64;
    for &c in &classes {
        if post == c {
            harmonic_bonus -= 30.0;
        } else if post % c == 0 && post > 0 {
            harmonic_bonus -= 8.0;
        }
    }
    score += harmonic_bonus;

    // Dead-space penalty: residuals in awkward ranges (1..9, 11..19, 21..29)
    // are hard to fill given min item size ~10; penalize small awkward leftovers.
    if post > 0 && post < 10 {
        score += 45.0; // nearly unusable dead space
    } else if post > 10 && post < 20 {
        score += 18.0;
    } else if post > 20 && post < 25 {
        score += 9.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if next item can't ever fit post, penalize mildly.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 55.0;
        } else if next_item_size <= post {
            score -= 12.0;
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post < bin_capacity {
        score -= 20.0;
        if post < 10 {
            score -= 15.0;
        }
    }

    // New-bin candidate handling: empty bin has high post_residual; only prefer
    // it when all open bins would leave very awkward leftovers.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 35.0;
        // cheaper to open new bin late in stream (less waste horizon)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * progress;
        // cheaper when many bins already open (parallelism exists)
        score -= (open_bins_count.min(10) as f64) * 1.5;
        // if next item is large, a fresh bin is valuable
        if next_item_size >= 50 {
            score -= 20.0;
        }
    }

    // Mean-residual coupling: when mean residual is high, prefer bins that
    // consume a lot (reduce post_residual harder).
    score -= 0.15 * (mean_residual - post as f64).max(0.0);

    // Exact fill is perfect.
    if post == 0 {
        score -= 100.0;
    }

    score
}

