pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = pr as f64 - item_size as f64;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Dead-space avoidance ladder (fine-grained near zero)
    if pr == 0 {
        score -= 300.0;
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr < 10 {
        score += 450.0;
    } else if pr <= 20 {
        score += 150.0;
    } else if pr <= 35 {
        score += 40.0;
    } else {
        let r = pr as f64;
        score += 0.02 * (100.0 - r) * (100.0 - r) / 10.0;
    }

    // Tight-fit reward
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 80.0 * fit_ratio * fit_ratio;

    // Bin-count pressure
    score += 6.0 * open_bins_count as f64;

    // Last-chance bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Lookahead: next item fits in post residual
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 90.0;
            if fitting_bins_count <= 2 { score -= 4.0; }
        } else if pr >= next_item_size {
            score -= 70.0;
            let slack = (pr - next_item_size) as f64;
            if slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 45.0 {
                score += (slack - 45.0) * 0.05;
            }
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 {
                score += (gap as f64 - 25.0) * 0.08;
            }
        } else if pr > 0 && pr < next_item_size {
            let dead = (next_item_size - pr) as f64;
            let density = remaining as f64 / total_items.max(1) as f64;
            if dead <= 8.0 {
                score += dead * (0.5 + 0.55 * density);
            } else {
                score += 60.0 + dead * 0.25 * density;
            }
        }
        // two- and three-item closure lookahead
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        if next_item_size > 0 && pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
