pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;
    let frag = pr as f64 - item_size as f64;

    // Dead-space avoidance: heavily penalize tiny unusable residuals.
    if pr > 0 && pr < 10 {
        score += 52.0;
    } else if pr < 25 {
        score += 22.0 * (1.0 - pr as f64 / 25.0);
    }

    // Reward near-perfect fills.
    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 8 {
        score -= 15.0;
    } else if pr <= 12 {
        score -= 10.0;
    } else if pr <= 25 {
        score -= 1.0;
    } else if pr <= 40 {
        score += 4.0;
    } else if pr <= 60 {
        score += 8.0;
    } else {
        score += 12.0;
    }

    // Dead-space ratio term: residual next item cannot use, scaled by density and scarcity.
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        let dead = (next_item_size - pr) as f64;
        let density = remaining as f64 / total_items.max(1) as f64;
        let scarcity = if fitting_bins_count <= 2 { 1.25 } else { 1.0 };
        score += dead * (0.25 + 0.55 * density) * scarcity;
    }

    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size > pr {
            score += pr as f64 * 0.5;
        } else {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 45.0 {
                score += (slack - 45.0) * 0.05;
            }
            if slack <= 1.0 {
                score -= 3.0;
            }
            if slack > 0.0 && slack < 14.0 && fitting_bins_count > 1 {
                score += slack * 0.10 * (1.0 - slack / 14.0);
            }
        }
        // Two-item lookahead.
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        // Triple-item lookahead.
        let quad = item_size + next_item_size * 3;
