    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next item
    if next_item_size > 0 {
        let diff = (pr as i64 - next_item_size as i64).abs() as f64;
        if pr == next_item_size {
            score -= 1000.0;
        } else {
            score -= 200.0 / (1.0 + diff / 10.0);
        }
        if pr < next_item_size {
            score += (next_item_size - pr) as f64 * 1.5;
        }
        // Multi-fit lookahead: residual that can hold 2+ copies of next item is valuable
        if pr > 0 && pr >= next_item_size * 2 && (pr % next_item_size) <= 2 {
            score -= 1.5 * ((pr / next_item_size) as f64).min(4.0);
        }
        // Exact two-item closure: item + next fills the bin perfectly
        if item_size + next_item_size == pr {
            score -= 8.0;
        }
    }

    // Compare post_residual relative to mean residual: favor bins that will end near mean
    let mean_gap = (pr as f64 - mean_residual).abs();
    score += mean_gap * 0.3;

    // Penalize tight fits that create small unusable slivers (unless next item matches)
    if pr > 0 && pr < 10 && pr != next_item_size {
        score += 50.0;
    } else if pr > 0 && pr < 20 && pr != next_item_size {
        score += 15.0;
    }

    // Dead-space: residual below next item strands space; scale by stream density
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        let dead = (next_item_size - pr) as f64;
        let density = remaining as f64 / total_items.max(1) as f64;
        let scarcity = if fitting_bins_count <= 2 { 1.25 } else { 1.0 };
        score += dead * (0.25 + 0.55 * density) * scarcity;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin when open bins can fit,
    // unless the fresh bin's leftover after placement is a clean multi-fit chunk
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 500.0;
            let fresh_left = bin_capacity.saturating_sub(item_size) as f64;
            if next_item_size > 1 && fresh_left >= next_item_size as f64 * 3.0 && remaining > 50 {
                score -= 60.0;
            }
        } else {
            score -= 100.0;
        }
        // Crowding-aware new-bin penalty
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        score += crowding * 6.0;
    } else {
        score += 60.0;
    }

    // Slight preference to consolidate into fewer bins as stream progresses
    score += open_bins_count as f64 * 0.5;

    // Mild tie-breaker: prefer fuller bins
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    // MUTATION: endgame exact-closure bonus — late stream, prefer fits that zero a residual
    if remaining < 50 && pr > 0 && pr == item_size {
        score -= 2.0 * (1.0 - remaining as f64 / 50.0);
    }

    // MUTATION: near-mean residual alignment reward
    if pr > 0 && mean_residual > 1.0 {
        let dev = ((pr as f64 - mean_residual) / mean_residual).abs();
        if dev < 0.3 {
            score -= 2.0 * (1.0 - dev / 0.3);
        }
    }

    score
}

