        }
        if next_item_size > 2 && fresh_left > 0.0 && fresh_left % next_item_size as f64 == 0.0 && fresh_left / next_item_size as f64 >= 2.0 && remaining > 60 {
            score -= 2.5;
        }
        // Fresh-bin multi-fit lookahead: bin will hold item plus >=2 next-items.
        if next_item_size > 1 && fresh_left >= next_item_size * 3 && remaining > 50 {
            score -= 2.0;
        }
        // MUTATION: fresh-bin lookahead trade-off — opening a new bin whose leftover cannot host
        // the next item while existing bins can is wasteful; strengthen the penalty when many
        // fitting bins exist and mean residual is healthy.
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && fitting_bins_count > 0 && mean_residual >= next_item_size as f64 && remaining > 60 {
            score += (next_item_size as f64 - fresh_left) * 0.35;
