    let mut score = pr;

    // Non-linear polynomial coupling of post residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += 40.0 * norm_pr * norm_pr * (0.5 + 0.5 * p2);
    score -= 25.0 * norm_pr * p3;

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (ns - pr).max(0.0) / cap;
        score += 60.0 * gap * gap * (1.0 - progress);
