    score -= 8.0 * (mean_residual / cap - norm_pr).clamp(0.0, 1.0);

    // New-bin candidate: penalize opening a fresh bin unless item is large
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        score += 15.0 * (1.0 - fill) * (1.0 - fill);
        score += 10.0 * progress;
    }

    score
}

