        let fresh_left = bin_capacity.saturating_sub(item_size) as f64;
        if remaining > 60 && fresh_left > 0.0 && fresh_left < mean_residual * 1.25 && open_bins_count > 0 {
            score += (mean_residual * 1.25 - fresh_left) * 0.38;
        }
        if fresh_left <= 6.0 && remaining > 30 {
            score -= 4.0;
        }
        if fitting_bins_count > 0 && fresh_left <= 3.0 && item_ratio > 0.9 {
            score -= 5.0;
        }
        if fresh_left > 0.0 && mean_residual > 1.0 && remaining > 40 {
            let d = (fresh_left - mean_residual).abs();
            if d < 4.0 {
                score -= 2.0 * (1.0 - d / 4.0);
            }
        }
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && (next_item_size as f64 - fresh_left) <= 8.0 && remaining > 40 {
            score += (next_item_size as f64 - fresh_left) * 0.5;
        }
        if next_item_size > 2 && fresh_left > 0.0 && fresh_left % next_item_size as f64 == 0.0 && fresh_left / next_item_size as f64 >= 2.0 && remaining > 60 {
            score -= 2.5;
        }
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 4.0;
        }
        if fitting_bins_count > 0 {
            score += 4.0;
        }
        if remaining < 8 && fitting_bins_count > 0 {
            score += 5.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 4.0;
        }
        // MUTATION: fresh-bin multi-fit lookahead discount.
        if next_item_size > 1 && fresh_left >= next_item_size as f64 * 3.0 && remaining > 50 {
            score -= 2.0;
        }
    } else {
        score += 60.0;
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        if remaining < 35 && next_item_size > 0 && pr == next_item_size {
            score -= 3.0;
        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 6 && fitting_bins_count > 2 {
            score -= 1.5;
        }
        // MUTATION: endgame exact-closure bonus.
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "small"
    // residue classes (dead space) are penalized; classes that pair well with
    // typical items are rewarded.
    let pr = post_residual;
    let class = pr % 10; // decade residue class
    match class {
        0 => score -= 6.0,           // perfectly divisible residual, reusable
        1 | 2 => score += 4.0,       // awkward slivers
        3 | 4 => score += 1.5,
        5 => score -= 2.0,           // half-decade, flexible
        6 | 7 | 8 => score -= 1.0,
        9 => score += 2.5,
        _ => {}
    }

    // Integer-division thresholds on post_residual: large leftover is good
    // (bin stays usable), tiny leftover wastes capacity but "closes" a bin.
    let q = pr / 25; // 0..=4 coarse fill level after placement
    score -= q as f64 * 8.0;

    // Dead-space penalty: leftover too small for the smallest plausible item.
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

    // Lookahead coupling: reward if the next item fits exactly into post_residual,
    // penalize if next item cannot fit (forcing another bin).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0; // perfect harmonic pair
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.4;
        } else {
            score += 5.0;
        }
        // modulo harmony between next item and post residual
        if pr > 0 && (next_item_size % pr.max(1)) == 0 && pr <= 50 {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when existing bins are crowded
    // or the fit is poor (large post_residual means poor fill of an open bin).
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let poor_fit = post_residual as f64; // empty bin: post_residual = cap - item
        score = cap - item_size as f64;      // baseline: fill efficiency of new bin
        score += crowd * 1.5;                // prefer existing bins mildly
        score -= (mean_residual / cap) * 20.0; // if open bins are roomy, avoid new bin
        if poor_fit < 20.0 { score -= 15.0; } // big item -> new bin is fine
        // late in stream, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Tight-fit reward: item nearly fills the bin exactly.
    if pr == 0 {
        score -= 50.0;
    } else if pr <= 5 {
        score -= 20.0;
    }

    // Mean-residual alignment: placing into bins below average residual
    // (tighter bins) balances the fleet.
    if (bin_residual as f64) < mean_residual && bin_residual < bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
