pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Base: prefer tight fits (small post_residual) but with a dead-space penalty
    // that is non-linear: gaps that are too small for any plausible future item
    // (<= 9) are "dead space" and heavily penalized.
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable slivers are penalized hard.
    if post_residual > 0 && post_residual <= 9 {
        score += (10.0 - post_residual as f64) * 25.0;
    }
    // Moderate gaps (10..=20) are mildly penalized: only large items fit there.
    else if post_residual > 9 && post_residual <= 20 {
        score += (20.0 - post_residual as f64) * 2.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward filling bins that are already substantially consumed (low residual
    // relative to capacity) to close bins out early.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 12.0;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Mean residual coupling: if the fleet average residual is high, tightening
    // this bin (small post_residual) is extra valuable.
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.15;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward;
    // if the next item would be stranded by a small gap, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            score -= 6.0;
        } else if post_residual > 0 && next_item_size > post_residual && post_residual <= 9 {
            score += 15.0; // gap becomes dead space given the known next item
        }
    }

    // New-bin candidate (empty bin): make it attractive only when the current
    // item is large relative to typical residuals, otherwise keep it expensive.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Large items benefit from a fresh bin since they leave little choice.
        if item_size >= 60 {
            score -= 10.0;
        }
        // Early in the stream, opening bins is cheap and useful.
        if progress < 0.15 {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
