}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual >= 10 && next_item_size > 0 && (post_residual as f64) < next_item_size as f64 {
        score += 12.0; // dead space relative to lookahead
    }

    // Lookahead: bonus if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 8.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or this is a large item with poor fit elsewhere.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowded = (open_bins_count as f64) / (1.0 + mean_residual / 10.0);
        let big_item = item_size as f64 / bin_capacity as f64;
