        score += 30.0;
        // But relax penalty over time and when many bins are nearly full.
        score -= 20.0 * progress * (crowded / (crowded + 5.0));
        score -= 15.0 * big_item * fit_ratio;
    }

    // Mild global pressure: when mean residual is low, prefer filling existing bins.
    score -= 5.0 * (mean_residual / bin_capacity as f64).tanh();

    // Slight preference for bins with smaller current residual (denser bins first).
    score += 0.05 * bin_residual as f64;

    score
}

