pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, large post_residual is fine (room for future items);
    // late in the stream, dead space is costly, so inflate it super-linearly.
    let dead_weight = 1.0 + 3.0 * progress * progress + 6.0 * progress.powi(4);
    score += post * post / cap * dead_weight * 0.05;

    // Perfect-fit reward, stronger as stream progresses.
    let fit_ratio = 1.0 - post / cap;
    score -= fit_ratio * fit_ratio * (8.0 + 24.0 * progress);

    // Penalize bins with residual far from mean (fragmentation pressure).
    score += (post - mean_residual).abs() * (0.3 + 0.7 * progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 30.0 + 40.0 * progress;
    }

    // Lookahead: reward leaving post_residual that still fits the next item.
    if next_item_size > 0 && (post_residual as u64) >= (next_item_size as u64) {
        score -= 6.0 + 10.0 * progress;
    } else if next_item_size > 0 {
        // post_residual too small for next item: dead-space penalty grows late.
        score += 4.0 + 12.0 * progress * (1.0 - post / cap);
    }

    // New-bin candidate: only attractive when item is large relative to capacity
    // (a fresh bin would leave a useful residual) and stream is early.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let large_item = item_size as f64 / cap;
        score += 25.0 + 30.0 * progress - 20.0 * large_item * large_item;
    }

    // Mild penalty for proliferating bins.
    score += (open_bins_count as f64).sqrt() * 0.4;

    score
}

