    // integer division into capacity-fraction buckets (dead-space bands).
    let c = bin_capacity as f64;
    let post = post_residual as f64;
    let band = (post_residual / (bin_capacity / 8).max(1)) as f64; // 8 harmonic classes

    // Non-linear penalty on dead space: unusable slivers cost extra.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0; // near-dead residual, almost nothing fits later
    }

    // Reward tight fits (small post_residual) super-linearly.
    score -= 60.0 * (-post / (c * 0.25)).exp();

