            score += 6.0 * (next_item_size as f64 - post) / c;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the
    // item is large relative to capacity or all open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = (mean_residual / c) < 0.25;
        if item_size as f64 > 0.6 * c || (crowded && post_residual >= 20) {
            score -= 30.0;
        } else {
            score += 35.0 + 20.0 * progress; // discourage needless bin proliferation
