    if (bin_residual as f64) > mean_residual && post_residual > 15 {
        score += 4.0;
    }

    // Band-based harmonic adjustment: odd bands are awkward shapes.
    if band as u64 % 2 == 1 {
        score += 2.0;
    }

    score
}

