        if remaining < 90 && pr == 0 && open_bins_count > 3 {
            score -= 1.5 * (1.0 - remaining as f64 / 90.0);
        }
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    // Threshold scales with the smallest conceivable item (1..100 stream).
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < 10.0 {
        score += 100.0; // unusable sliver
    } else if post_residual > 0 && (post_residual as f64) < 30.0 {
        score += 25.0; // likely dead space for many item sizes
    }

    // Reward tight fits (near-zero post residual is excellent).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Exact-fit anticipation: if the next item can exactly consume post_residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use this bin's leftover anyway; leftover is dead space.
        score += (post_residual as f64) * 0.5;
    }

    // Open-bin pressure: discourage spreading across many bins; encourage
    // filling existing bins when few bins are open.
    let pressure = open_bins_count as f64;
    score -= pressure * 1.5;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin: penalize so it only wins when open bins
        // have large dead-space penalties.
        score += 30.0 + mean_residual * 0.3;
    } else {
        // Mild reward for using a bin whose residual is below the mean
        // (concentrate waste into fewer bins).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        }
    }

    // Stream progression: later in the stream, closing out bins tightly matters
    // more (fewer chances to fix fragmentation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    // Prefer bins whose post-residual can still host the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }

    score
}

