        }
        // Penalize leaving residual that neither fits next item nor is small.
        if (post_residual as u32) < next_item_size && post_residual > 0 && post_residual < 10 {
            score += 25.0;
        }
    } else {
        // Last item: prefer tightest fit.
        score += 5.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins)
    // so loose bins stay available for larger future items.
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's early in the stream
    // or the current bin would leave lots of dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let dead = (bin_residual - item_size) as f64;
        score += 55.0 - 25.0 * progress;
        if dead < 8.0 {
            score -= 20.0; // current placement would be near-perfect anyway
        }
    }

    // Mild penalty for very small unusable leftovers.
    if post_residual > 0 && post_residual < 5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;
    let frag = pr as f64 - item_size as f64;
    let density = remaining as f64 / total_items.max(1) as f64;

    if pr > 0 && pr < 10 {
        score += 50.0;
    } else if pr > 0 && pr < 20 {
        score += 25.0;
    } else if pr < 25 {
        score += 22.0 * (1.0 - pr as f64 / 25.0);
    }

    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 8 {
        score -= 15.0;
    } else if pr <= 15 {
        score -= 6.5;
    } else if pr <= 25 {
        score -= 1.0;
    } else if pr <= 40 {
        score += 4.0;
    } else if pr <= 60 {
        score += 8.0;
    } else {
        score += 12.0;
    }

    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        let dead = (next_item_size - pr) as f64;
        let scarcity = if fitting_bins_count <= 2 { 1.25 } else { 1.0 };
        score += dead * (0.25 + 0.55 * density) * scarcity;
    }

    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
            if fitting_bins_count <= 2 {
                score -= 4.0;
            }
            if remaining < 35 {
                score -= 3.0;
            }
        } else if next_item_size > pr {
            score += pr as f64 * 0.5;
        } else {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 {
                score -= 5.0;
            }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack <= 1.0 {
                score -= 3.0;
            }
            if slack > 0.0 && slack < 14.0 && fitting_bins_count > 1 {
                score += slack * 0.10 * (1.0 - slack / 14.0);
            }
            if slack > 45.0 {
                score += (slack - 45.0) * 0.05;
            }
        }
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        if pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        if frag > 0.0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        if pr > 0 && pr < next_item_size && next_item_size - pr <= 3 && remaining > 80 {
            score += (next_item_size - pr) as f64 * 0.6;
        }
        if frag > 0.0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        if frag > 0.0 && frag < next_item_size as f64 {
            let dead = next_item_size as f64 - frag;
            if dead > 6.0 && fitting_bins_count > 1 {
                score += dead * 0.12;
            }
        }
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
            if mean_residual < 16.0 && remaining > 100 {
                score += (frag - next_item_size as f64) * 0.08;
            }
        }
        if pr > 0 && pr % next_item_size == 0 {
            score -= 1.5;
            if pr / next_item_size >= 2 && remaining > 50 {
                score -= 2.0 * ((pr / next_item_size) as f64).min(3.0);
            }
        }
        if next_item_size > 1 && pr > 0 && pr >= next_item_size && (pr / next_item_size) >= 2 && (pr % next_item_size) <= 2 && remaining > 30 {
            score -= 1.6 * ((pr / next_item_size) as f64).min(4.0);
        }
        if pr > next_item_size && (pr - next_item_size) * 2 <= pr {
            score -= 1.2;
        }
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 {
                score += (gap as f64 - 25.0) * 0.08;
            }
        }
        // MUTATION: penalize residuals that are too small to host the mean-sized future item,
        // but also too large to be closed by a small item — dead-space coupling
        if pr > 0 && mean_residual > 3.0 && (pr as f64) < mean_residual * 0.85 && remaining > 60 {
            score += (mean_residual * 0.85 - pr as f64) * 0.22;
        }
        // MUTATION: reward residuals that can host next item plus still leave >= mean_residual
        if next_item_size > 0 && pr >= next_item_size {
            let after = pr - next_item_size;
            if after as f64 >= mean_residual * 0.9 && remaining > 40 {
                score -= 1.2 * (1.0 - progress * 0.4);
            }
        }
    }

    score += open_bins_count as f64 * 0.3;

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    score -= (bin_residual as f64 - mean_residual) * 0.2;

    if frag > mean_residual && frag > 12.0 && remaining > 30 {
        score += (frag - mean_residual) * 0.06;
    }
    if frag > 40.0 && remaining > 60 {
        score += (frag - 40.0) * 0.05;
    }
    if frag > 0.0 && frag > mean_residual * 1.6 && remaining > 30 {
        score += (frag - mean_residual * 1.6) * 0.04;
    }
    let fill_ratio = item_size as f64 / bin_capacity.max(1) as f64;
    if frag > 0.0 && fill_ratio < 0.42 && remaining > 40 {
        score += (0.42 - fill_ratio) * 16.0 * (1.0 - progress * 0.5);
    }

    if pr > 0 && mean_residual > 1.0 {
        let dev = ((pr as f64 - mean_residual) / mean_residual).abs();
        if dev < 0.3 {
            score -= 2.0 * (1.0 - dev / 0.3);
        } else if dev > 1.5 && pr as f64 > mean_residual * 2.0 {
            score += 2.5;
        }
    }
    if pr > 0 && mean_residual > 3.0 && (pr as f64) < mean_residual * 0.85 && remaining > 60 {
        score += (mean_residual * 0.85 - pr as f64) * 0.22;
    }
    if pr > 0 && mean_residual > 2.0 && (pr as f64) < mean_residual && (mean_residual - pr as f64) < 6.0 {
        score += (mean_residual - pr as f64) * 0.35;
    }

    score += pr as f64 * (0.1 + 0.25 * progress);

    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        if item_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        let fresh_left = bin_capacity.saturating_sub(item_size) as f64;
        if remaining > 60 && fresh_left > 0.0 && fresh_left < mean_residual * 1.25 && open_bins_count > 0 {
            score += (mean_residual * 1.25 - fresh_left) * 0.38;
        }
        if fresh_left <= 6.0 && remaining > 30 {
            score -= 4.0;
        }
        if fitting_bins_count > 0 && fresh_left <= 3.0 && item_ratio > 0.9 {
            score -= 5.0;
        }
        if fresh_left > 0.0 && mean_residual > 1.0 && remaining > 40 {
            let d = (fresh_left - mean_residual).abs();
            if d < 4.0 {
                score -= 2.0 * (1.0 - d / 4.0);
            }
        }
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        if mean_residual > 30.0 && remaining > 100 {
            score -= 2.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            if mean_residual >= next_item_size as f64 && fitting_bins_count > 0 {
                score += 4.0;
            } else {
                score -= 4.0;
            }
        }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 {
            score += 3.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 2 && mean_residual >= next_item_size as f64 {
            score += 2.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size && remaining > 30 && open_bins_count > 0 && mean_residual >= next_item_size as f64 {
            score += 6.0;
        }
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && (next_item_size as f64 - fresh_left) <= 8.0 && remaining > 40 {
            score += (next_item_size as f64 - fresh_left) * 0.5;
        }
        if next_item_size > 2 && fresh_left > 0.0 && fresh_left % next_item_size as f64 == 0.0 && fresh_left / next_item_size as f64 >= 2.0 && remaining > 60 {
            score -= 2.5;
        }
        if next_item_size > 1 && fresh_left >= next_item_size * 3 && remaining > 50 {
            score -= 2.0;
        }
        if fresh_left > 0.0 && mean_residual > 2.0 && fresh_left < mean_residual * 0.7 && remaining > 60 {
            score += (mean_residual * 0.7 - fresh_left) * 0.30;
        }
        if next_item_size > 0 && fresh_left == next_item_size as f64 && remaining > 15 {
            score -= 4.0;
        }
        // MUTATION: fresh-bin dead-space — if the leftover after this item is far below mean_residual
        // and no open bin has similar residual, opening is wasteful; penalize harder mid-stream
        if fresh_left > 0.0 && remaining > 80 && open_bins_count > 2
            && fresh_left < next_item_size as f64 && (next_item_size as f64 - fresh_left) > 4.0 {
            score += (next_item_size as f64 - fresh_left) * 0.22;
        }
        if fitting_bins_count > 0 {
            score += 4.0;
        }
        if remaining < 8 && fitting_bins_count > 0 {
            score += 5.0;
        }
        if remaining < 12 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 4.0;
        }
        if remaining < 15 && fitting_bins_count > 0 {
            score += 3.0;
        }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
    } else {
        score += 60.0;
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 6 && fitting_bins_count > 2 {
            score -= 1.5;
        }
        if remaining >= 35 && remaining < 120 && next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 5 {
            score -= 1.0;
        }
        if remaining < 20 && pr > 0 && mean_residual > 1.0 && ((pr as f64) - mean_residual).abs() < 3.0 {
            score -= 1.5;
        }
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        if remaining < 15 && pr == 0 {
            score -= 4.0;
        }
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
        // MUTATION: mid-stream exact-fill bonus — a fit that leaves pr == 0 frees the bin entirely
        if remaining >= 15 && pr == 0 && fitting_bins_count > 1 {
            score -= 1.5 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: shrink score as post_residual shrinks.
    score -= (bin_capacity as f64 - post_residual as f64).max(0.0) * 0.35;

    // Penalize small dead space that is hard to reuse (waste factor).
    if post_residual > 0 {
        let waste = post_residual as f64 / bin_capacity as f64;
        score += waste * waste * 40.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: penalize if the next item cannot use the post residual.
    if next_item_size > 0 {
        if (next_item_size as u64) > (post_residual as u64) {
            score += 12.0;
        } else {
            // Reward residual that leaves a good slot for next item.
            let slack = post_residual as f64 - next_item_size as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64).max(0.0);
        }
    } else {
        // Last item: strongly prefer minimal post residual.
        score += post_residual as f64 * 2.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: neutral-ish baseline; open new bin only when
    // all fits would leave large waste or the stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_waste = mean_residual / open_bins_count.max(1) as f64;
        // If open bins are crowded (low mean residual), opening a new bin is fine.
        score += 30.0 - avg_waste * 0.4 - (1.0 - progress) * 10.0;
        // Never open a new bin for a perfect fit elsewhere.
        if post_residual == 0 && fitting_bins_count >= 1 {
            score += 200.0;
        }
    }

    // Mild penalty for spreading across many bins.
    score += open_bins_count as f64 * 0.05;

    // Prefer bins whose residual deviates favorably from mean (consolidate).
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;
    let frag = pr as f64 - item_size as f64;

    // Dead-space avoidance: small unusable gaps are heavily penalized.
    if pr > 0 && pr < 10 {
        score += 52.0;
    } else if pr < 25 {
        score += 22.0 * (1.0 - pr as f64 / 25.0);
    }

    // Reward near-perfect fills.
    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 38.0;
    } else if pr <= 12 {
        score -= 10.0;
    } else if pr <= 25 {
        score -= 1.0;
    } else if pr <= 40 {
        score += 3.0;
    } else if pr <= 60 {
        score += 7.0;
    } else {
        score += 11.0;
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 58.0;
            if fitting_bins_count <= 2 { score -= 4.0; }
        } else if next_item_size > pr {
            let dead = (next_item_size - pr) as f64;
            let density = remaining as f64 / total_items.max(1) as f64;
            let scarcity = if fitting_bins_count <= 2 { 1.25 } else { 1.0 };
            score += pr as f64 * 0.4 + dead * (0.25 + 0.5 * density) * scarcity;
        } else {
            let slack = (pr - next_item_size) as f64;
            score -= 6.0 + 9.0 / (1.0 + slack);
            if slack == 0.0 {
                score -= 5.0;
            }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 45.0 {
                score += (slack - 45.0) * 0.05;
            }
        }
        // Two-item lookahead: next item fits twice more.
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        // Three-item lookahead.
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        // Chain-friendliness: residual divisible by next size.
        if pr > 0 && pr >= next_item_size && pr % next_item_size == 0 && pr / next_item_size >= 2 && remaining > 50 {
            score -= 2.0 * ((pr / next_item_size) as f64).min(3.0);
        }
        // Multi-fit lookahead: residual holds >=2 next items with tiny remainder.
        if next_item_size > 1 && pr >= next_item_size && (pr / next_item_size) >= 2 && (pr % next_item_size) <= 2 && remaining > 30 {
            score -= 1.6 * ((pr / next_item_size) as f64).min(4.0);
        }
        // Near-closure: leftover within 1-2 of next item size.
        if pr >= next_item_size && pr - next_item_size <= 1 {
            score -= 3.0;
        }
        // Penalize residual just below next item (guaranteed dead space).
        if frag > 0.0 && frag < next_item_size as f64 && next_item_size as f64 - frag <= 4.0 {
            score += (next_item_size as f64 - frag) * 0.9;
        }
        // Small bonus when frag is just above next size (next item still fits).
        if frag > 0.0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        // Dead-space-to-mean coupling: residual below 85% of mean strands future packing.
        if pr > 0 && mean_residual > 3.0 && (pr as f64) < mean_residual * 0.85 && remaining > 60 {
            score += (mean_residual * 0.85 - pr as f64) * 0.22;
        }
        // Small item in a big bin leaves a wide frag that wastes capacity.
        let fill_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if frag > 0.0 && fill_ratio < 0.42 && remaining > 40 {
            score += (0.42 - fill_ratio) * 16.0 * (1.0 - progress * 0.5);
        }
        // Dead-space ratio coupling — frag that next item cannot use, scaled by density.
        if frag > 0.0 && frag < next_item_size as f64 {
            let dead = next_item_size as f64 - frag;
            if dead > 6.0 && fitting_bins_count > 1 {
                score += dead * 0.12;
            }
        }
        // Mid-gap residual band — gaps between items create stranded space.
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 {
                score += (gap as f64 - 25.0) * 0.08;
            }
        }
        // Tight two-stage closure — item + next item nearly closes the bin.
        if pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        // MUTATION: frag between one and two next-items wastes a slot; worse under low mean residual.
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
            if mean_residual < 16.0 && remaining > 100 {
                score += (frag - next_item_size as f64) * 0.08;
            }
        }
        // MUTATION: half-split residual — leftover that can host two more next items is chain-friendly.
        if pr > next_item_size && (pr - next_item_size) * 2 <= pr {
            score -= 1.2;
        }
        // MUTATION: dead2 band — small unusable remainder after next item fits.
        if pr > next_item_size {
            let dead2 = (pr - next_item_size) as f64;
            if dead2 > 0.0 && dead2 < 14.0 && fitting_bins_count > 1 {
                score += dead2 * 0.10 * (1.0 - dead2 / 14.0);
            }
        }
        // MUTATION: exact match under scarcity gets an extra nudge.
        if pr == next_item_size && fitting_bins_count <= 2 {
            score -= 4.0;
        }
    }

    // Open-bin pressure: prefer tighter packing when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Slight bias toward bins with larger residuals (better long-term hosts).
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Fragments larger than mean residual waste capacity going forward.
    if frag > mean_residual && frag > 12.0 && remaining > 30 {
        score += (frag - mean_residual) * 0.06;
    }
    // Very large fragments waste even more.
    if frag > 40.0 && remaining > 60 {
        score += (frag - 40.0) * 0.05;
    }
    // MUTATION: very large frag beyond 1.6x mean strands capacity.
    if frag > mean_residual * 1.6 && remaining > 30 {
        score += (frag - mean_residual * 1.6) * 0.04;
    }

    // Late in the stream, tighten packing further.
    score += pr as f64 * (0.1 + 0.22 * progress);

    // Residual close to mean residual is a good host for future items.
    if pr > 0 && mean_residual > 1.0 {
        let dev = ((pr as f64 - mean_residual) / mean_residual).abs();
        if dev < 0.3 {
            score -= 2.0 * (1.0 - dev / 0.3);
        } else if dev > 1.5 && pr as f64 > mean_residual * 2.0 {
            score += 2.5;
        }
        if mean_residual > 2.0 && (pr as f64) < mean_residual && (mean_residual - pr as f64) < 6.0 {
            score += (mean_residual - pr as f64) * 0.35;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        // Large items: better to start a fresh bin than fragment a good one.
        if item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        if item_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 {
            score -= 3.0;
        }
        // Fresh bin leaves a large usable residual matching mean need.
        let fresh_left = bin_capacity.saturating_sub(item_size) as f64;
        if remaining > 60 && fresh_left > 0.0 && fresh_left < mean_residual * 1.25 && open_bins_count > 0 {
            score += (mean_residual * 1.25 - fresh_left) * 0.38;
        }
        if fresh_left <= 6.0 && remaining > 30 {
            score -= 4.0;
        }
        if fitting_bins_count > 0 && fresh_left <= 3.0 && item_ratio > 0.9 {
            score -= 5.0;
        }
        // Fresh leftover near mean residual is chain-friendly.
        if fresh_left > 0.0 && mean_residual > 1.0 && remaining > 40 {
            let d = (fresh_left - mean_residual).abs();
            if d < 4.0 {
                score -= 2.0 * (1.0 - d / 4.0);
            }
        }
        // Discourage fresh bin when leftover sits just under next item (dead space).
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && (next_item_size as f64 - fresh_left) <= 8.0 && remaining > 40 {
            score += (next_item_size as f64 - fresh_left) * 0.5;
        }
        // Reward fresh bin when leftover is an exact multiple of next size.
        if next_item_size > 2 && fresh_left > 0.0 && fresh_left % next_item_size as f64 == 0.0 && fresh_left / next_item_size as f64 >= 2.0 && remaining > 60 {
            score -= 2.5;
        }
        // Fresh-bin multi-fit lookahead: bin will hold item plus >=2 next items.
        if next_item_size > 1 && fresh_left >= next_item_size as f64 * 3.0 && remaining > 50 {
            score -= 2.0;
        }
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 4.0;
        }
        if fitting_bins_count > 0 {
            score += 4.0;
        }
        // Fresh bin whose leftover can host the next item exactly — avoid stranding mean space.
        if next_item_size > 0 && fitting_bins_count > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && next_item_size as f64 - fresh_left <= 6.0 && remaining > 60 {
            score -= 2.0;
        }
        // Next item fits fresh leftover alongside mean residual need.
        if next_item_size > 0 && fresh_left >= next_item_size as f64 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 {
            score += 2.0;
        }
        // MUTATION: fresh leftover far above mean need with many bins open — cheap to open.
        if fresh_left > 0.0 && mean_residual > 2.0 && fresh_left > mean_residual * 1.8 && remaining > 100 && open_bins_count > 3 {
            score -= 1.5;
        }
        // MUTATION: fresh leftover below next item late in stream — penalize proportionally.
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && remaining > 120 {
            score += (next_item_size as f64 - fresh_left) * 0.35;
        }
        if remaining < 8 && fitting_bins_count > 0 {
            score += 5.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 4.0;
        }
        if remaining < 12 && fitting_bins_count > 0 {
            score += 3.0;
        }
        // MUTATION: mean residual close to next item size — fresh bin less useful.
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
        // MUTATION: next item won't fit fresh leftover but fits elsewhere — push toward open bins.
        if next_item_size > 0 && next_item_size > bin_capacity - item_size && remaining > 30 && open_bins_count > 0 && mean_residual >= next_item_size as f64 {
            score += 6.0;
        }
    } else {
        score += 60.0;
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        // Endgame: strong bonus for exact-closure residuals.
        if remaining < 35 && next_item_size > 0 && pr == next_item_size {
            score -= 3.0;
        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 6 && fitting_bins_count > 2 {
            score -= 1.5;
        }
        // Endgame exact-closure bonus: late stream, prefer the fit that zeroes a residual.
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        // Mid-stream near-closure bonus scaled by progress.
        if remaining >= 35 && remaining < 120 && next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 5 {
            score -= 1.0;
        }
        // MUTATION: endgame — prefer residual matching mean need.
        if remaining < 20 && pr > 0 && mean_residual > 1.0 && ((pr as f64) - mean_residual).abs() < 3.0 {
            score -= 1.5;
        }
        // MUTATION: many fitting bins and residual larger than mean — mild penalty.
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 20.0 * poly;
    // penalize small post-residuals that waste space, more so late in stream
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);
    // reward near-perfect fits
    if pr == 0 { score -= 50.0; }
    // last-chance bonus
    if fitting_bins_count == 1 { score -= 15.0; }
    // lookahead: favor bins whose post_residual fits next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 10.0 * (1.0 - progress);
    } else if next_item_size > 0 {
        score += 5.0 * progress;
    }
    // mild pressure toward consolidating open bins
    score += 0.5 * open_bins_count as f64 * (norm_pr - mean_residual / cap).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues modulo 10 create
    // "usable" (large, divisible) vs "dead" (small) leftover classes.
    let pr = post_residual;
    let class = pr % 10;
    let dead = class > 0 && (pr < 10 || class > 5 && pr < 20);
    if dead {
        score += 25.0 + 2.0 * (10 - class) as f64;
    }

    // Perfect fit reward: post_residual exactly divisible by common item sizes.
    if pr == 0 {
        score -= 40.0;
    } else if pr % 10 == 0 {
        score -= 12.0;
    } else if pr % 5 == 0 {
        score -= 5.0;
    }

    // Lookahead coupling: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Harmonic match: next item's class aligns with leftover.
            let nxt_class = next_item_size % 10;
            let bonus = if pr % next_item_size == 0 {
                18.0
            } else if nxt_class == 0 {
                10.0
            } else {
                4.0
            };
            score -= bonus + (next_item_size as f64) * 0.15;
        } else {
            // Next item cannot use this bin's leftover: penalize dead space.
            score += (next_item_size - pr) as f64 * 0.4;
        }
    }

    // Integer-division threshold on post_residual vs capacity fraction.
    let half = bin_capacity / 2;
    if pr < half / 4 {
        // Very small leftover is nearly dead space.
        score += 15.0;
    } else if pr > half {
        // Large leftover means bin was barely used; prefer filling it more.
        score -= 6.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // or the stream is early and mean residual is high.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let early = (step_index as f64) / (total_items.max(1) as f64);
        score = 60.0 - 45.0 * pressure - 20.0 * (1.0 - early) - mean_residual * 0.1;
    }

    // Mild preference for bins below mean residual (balance utilization).
    score += ((mean_residual - bin_residual as f64) * 0.05).clamp(-5.0, 5.0);

    score
}

