        }
        if remaining < 12 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if remaining < 15 && fitting_bins_count > 0 {
            score += 3.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 4.0;
        }
        // Fresh leftover just under next item late in stream is stranded.
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && remaining > 120 {
            score += (next_item_size - fresh_left as u32) as f64 * 0.35;
        }
        // Fresh leftover far above mean residual with many open bins: keep open bins tight.
        if fresh_left > 0.0 && mean_residual > 2.0 && fresh_left > mean_residual * 1.8 && remaining > 100 && open_bins_count > 3 {
            score -= 1.5;
        }
        // COMBINED: fresh-bin two-step fit check — leftover should host next item AND leave usable space.
        if next_item_size > 0 && fresh_left >= next_item_size as f64 {
            let slack2 = fresh_left - next_item_size as f64;
            if slack2 == 0.0 {
                score -= 2.5;
            } else if slack2 < next_item_size as f64 {
                score += slack2 * 0.08;
            }
        }
    } else {
        score += 60.0;
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        // Endgame: strong bonus for exact-closure residuals.
        if remaining < 35 && next_item_size > 0 && pr == next_item_size {
            score -= 3.0;
        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 6 && fitting_bins_count > 2 {
            score -= 1.5;
        }
        // Mid-stream near-closure bonus.
        if remaining >= 35 && remaining < 120 && next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 5 {
            score -= 1.0;
        }
        // Endgame exact-closure bonus — late stream, prefer the fit that zeroes a residual.
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        // Crowded bins with slack above mean residual are poor hosts.
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
        // Endgame: residual near mean residual is a reliable host.
        if remaining < 20 && pr > 0 && mean_residual > 1.0 && ((pr as f64) - mean_residual).abs() < 3.0 {
            score -= 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (0 < post_residual < 10)
    // are heavily penalized; zero residual is rewarded.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual < 10 {
        score += 45.0; // dead space trap
    } else if post_residual < 20 {
        score += 12.0; // marginal gap
    } else {
        // Larger residuals are fine, mild decay so tight-but-usable wins
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidation into existing bins
    let open_pressure = open_bins_count as f64 * 0.8;
    if bin_residual < bin_capacity {
        score -= open_pressure;
    } else {
        // New-bin candidate: apply pressure so it's only chosen for poor fits
        score += open_pressure * 0.5;
    }

    // Lookahead: if next item fits exactly into the post residual, reward strongly
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack < 10.0 {
                score -= 30.0; // next item seals this bin
            } else {
                score -= 8.0;
            }
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 15.0; // residual too small for lookahead item
        }
    }

    // Deviation from mean residual: prefer bins below mean (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight late-stream conservatism: keep bins open as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let frag = pr as f64 - item_size as f64;
