        }
        // frag exactly equals next item: perfect chain
        if frag > 0.0 && frag as u32 == next_item_size {
            score -= 4.5;
        }
        // frag leaves room for next + tiny remainder
        if frag > 0.0 && frag as u32 > next_item_size && frag as u32 - next_item_size <= 2 {
            let rem = (frag as u32 - next_item_size) as f64;
            score -= 2.2 - rem * 0.6;
        }
        // large frag vs mean residual coupling
        if frag > mean_residual && frag > 12.0 {
