pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual >= next_item_size {
            // Next item fits; reward proportional to how snugly.
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack * 0.4;
        } else {
            // Next item won't fit: penalize small dead space left behind.
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Penalize creating tiny unusable residuals (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual stays near the mean.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: make it attractive only when item is large relative to
    // typical residuals or existing fits are poor.
    if bin_residual == bin_capacity {
        // Base penalty keeps open-bin usage preferred.
        score += 50.0;
        // But reward opening a fresh bin for large items or when few fitting bins.
        if item_size > 60 || (fitting_bins_count <= 1 && open_bins_count > 0) {
            score -= 90.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) super-linearly.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) * 0.05;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin unless current item leaves
    // room for the lookahead item or fits are scarce.
    if bin_residual == bin_capacity {
        let mut newbin_penalty = 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            newbin_penalty -= 12.0; // room for next item in fresh bin
        }
        if fitting_bins_count == 0 {
            newbin_penalty -= 40.0; // no alternative
        }
        // Early in stream, opening bins is cheaper; late, consolidate.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        newbin_penalty *= 0.5 + progress;
        score += newbin_penalty;
    }

    // Lookahead coupling: if this placement leaves room for the next item, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Prefer bins below mean residual (consolidate emptier bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Slight preference for bins with more siblings when many bins open.
    if open_bins_count > 4 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    // Base: post residual, with non-linear polynomial shaping over stream progress.
    // Early on, prefer tight fills (low post_residual); late in the stream,
    // dead space matters slightly less than preserving flexibility.
    let mut score = pr * (1.0 + 0.35 * progress * progress);

    // Smooth convex penalty on small-but-nonzero post_residual (dead space),
    // strongest mid-stream: penalize residuals that are too small to be useful.
    let dead_zone = (1.0 - pr_norm).powi(3) - (1.0 - 2.0 * pr_norm).abs().powi(3);
    score -= 18.0 * dead_zone * (0.5 + 0.5 * (1.0 - progress));

    // Reward near-perfect fits with a smooth quadratic bonus.
    let perfect = 1.0 - (pr_norm / (1.0 - item_norm + 1e-9)).abs();
    score -= 25.0 * perfect * perfect * (1.0 - progress * 0.5);

    // Lookahead coupling: if the next item fits smoothly into the post-residual,
    // reward it with a smooth interaction term; penalize near-miss conflicts.
    if next_item_size > 0 {
        let gap = (pr - next_norm * cap) / cap;
        let fits_next = (gap.max(0.0)).powi(2);
        let near_miss = (1.0 - (gap / 0.1).abs().min(1.0)).max(0.0);
        score -= 12.0 * fits_next * (1.0 - progress);
        score += 10.0 * near_miss * near_miss * (0.3 + 0.7 * progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // (avoid opening a new bin) via smooth sigmoid-like coupling with open bins.
    if fitting_bins_count == 1 {
        let crowding = 1.0 - (-(open_bins_count as f64) / 8.0).exp();
        score -= 20.0 * crowding;
    } else {
        // Mild penalty when many bins compete, favor consolidation.
        score += (fitting_bins_count as f64).ln().max(0.0) * 1.5;
    }

    // Mean-residual coupling: prefer bins whose residual deviates smoothly
    // from the mean (keeps the bin profile balanced polynomially).
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * (0.5 + 0.5 * progress);

    // New-bin candidate adjustment: an empty bin has high post_residual;
    // make it attractive only when the item is large relative to capacity
    // and stream is late (smooth interaction).
    if bin_residual == bin_capacity {
        let large_item = item_norm * item_norm;
        score -= 8.0 * large_item * (0.2 + 0.8 * progress);
    }

    score
