        }
        // stranded fresh leftover below mean residual
        if fresh_left > 0.0 && mean_residual > 2.0 && fresh_left < mean_residual * 0.7 && remaining > 60 {
            score += (mean_residual * 0.7 - fresh_left) * 0.30;
        }
        // exact next-item leftover bonus
        if next_item_size > 0 && fresh_left == next_item_size as f64 && remaining > 15 {
            score -= 4.0;
        }
        // MUTATION: fresh-bin waste-ratio guard — opening a bin that leaves a large unfillable chunk while open bins hold smaller residuals
        if fresh_left > 0.0 && next_item_size > 0 && fresh_left < next_item_size as f64 && remaining > 40 && open_bins_count > 2 && mean_residual > fresh_left * 1.5 {
            score += (next_item_size as f64 - fresh_left) * 0.30;
        }
        // MUTATION: prefer fresh bins whose leftover can chain two next-items with small remainder
        if next_item_size > 1 && fresh_left >= next_item_size as f64 * 2.0 && (fresh_left - next_item_size as f64 * 2.0) <= 3.0 && remaining > 60 {
