        }
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
        // MUTATION: endgame — prefer fits leaving residual equal to a small multiple of next item
        if remaining < 40 && next_item_size > 1 && pr > 0 && pr % next_item_size == 0 && pr / next_item_size <= 2 {
            score -= 1.5 * (1.0 - remaining as f64 / 40.0);
        }
    }

