        score -= 100.0;
    } else if pr <= 5 {
        score -= 38.0;
    } else if pr <= 12 {
        score -= 10.0;
    } else if pr <= 25 {
        score -= 1.0;
    } else if pr <= 40 {
        score += 3.0;
    } else if pr <= 60 {
        score += 7.0;
    } else {
        score += 11.0;
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 58.0;
            if fitting_bins_count <= 2 { score -= 4.0; }
