            score -= 4.0;
        }
        if fitting_bins_count > 0 {
            score += 4.0;
        }
        // Next item fits fresh leftover alongside mean residual need.
        if next_item_size > 0 && fresh_left >= next_item_size as f64 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 {
            score += 2.0;
        }
        // Fresh leftover far above mean need with many bins open — cheap to open.
        if fresh_left > 0.0 && mean_residual > 2.0 && fresh_left > mean_residual * 1.8 && remaining > 100 && open_bins_count > 3 {
            score -= 1.5;
        }
        // Fresh leftover below next item late in stream — penalize proportionally.
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && remaining > 120 {
            score += (next_item_size as f64 - fresh_left) * 0.35;
        }
        if remaining < 8 && fitting_bins_count > 0 {
            score += 5.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 4.0;
        }
        if remaining < 12 && fitting_bins_count > 0 {
            score += 3.0;
        }
        // Mean residual close to next item size — fresh bin less useful.
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
        // Next item won't fit fresh leftover but fits elsewhere — push toward open bins.
        if next_item_size > 0 && next_item_size > bin_capacity - item_size && remaining > 30 && open_bins_count > 0 && mean_residual >= next_item_size as f64 {
            score += 6.0;
        }
        // MUTATION: small next item with mean residual large enough — fresh bin unlikely to be reused well.
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 {
            score += 3.0;
        }
        // MUTATION: very large mean residual and long stream — fresh bins are cheap hosts.
        if mean_residual > 30.0 && remaining > 100 {
            score -= 2.0;
        }
        // MUTATION: many open bins and next item fits mean residual late — avoid opening.
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
    } else {
        score += 60.0;
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        // Endgame: strong bonus for exact-closure residuals.
        if remaining < 35 && next_item_size > 0 && pr == next_item_size {
            score -= 3.0;
        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 6 && fitting_bins_count > 2 {
            score -= 1.5;
        }
        // Endgame exact-closure bonus: late stream, prefer the fit that zeroes a residual.
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        // Endgame exact-closure widened.
        if remaining < 50 && next_item_size > 0 && pr > 0 && pr == next_item_size {
            score -= 2.5 * (1.0 - remaining as f64 / 50.0);
        }
        // Mid-stream near-closure bonus scaled by progress.
        if remaining >= 35 && remaining < 120 && next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 5 {
            score -= 1.0;
        }
        // Endgame — prefer residual matching mean need.
        if remaining < 20 && pr > 0 && mean_residual > 1.0 && ((pr as f64) - mean_residual).abs() < 3.0 {
            score -= 1.5;
        }
        // Many fitting bins and residual larger than mean — mild penalty.
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
        // MUTATION: endgame two-item closure — late stream, residuals that fit next item plus a small margin close out soon.
        if remaining < 30 && next_item_size > 0 && pr > 0 && pr >= next_item_size && pr - next_item_size <= 3 {
            score -= 2.0 * (1.0 - remaining as f64 / 30.0) * (1.0 - (pr - next_item_size) as f64 / 3.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
