pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: which "slot" of capacity it falls into
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post_class = (post_residual / eighth) as f64;
    score += 8.0 * post_class * post_class; // penalize large residuals non-linearly

    // Perfect fit bonus: post_residual near zero
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= eighth {
        score -= 60.0;
    }

    // Dead-space penalty: residual too small for smallest plausible item (<= 10)
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Modulo logic: residuals that are multiples of quarter are "reusable" classes
    let mod_q = post_residual % quarter.max(1);
    if mod_q == 0 && post_residual > 0 {
        score -= 25.0;
    }

    // Lookahead coupling: does next item fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly or with small slack -> strong reward
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 120.0;
            } else {
                score -= 40.0 * (1.0 - slack as f64 / cap);
            }
        } else {
            // next item won't fit here: penalize proportionally to overshoot
            score += 20.0 + (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
