        if remaining < 30 && next_item_size > 0 && pr > 0 && pr >= next_item_size && pr - next_item_size <= 3 {
            score -= 2.0 * (1.0 - remaining as f64 / 30.0) * (1.0 - (pr - next_item_size) as f64 / 3.0);
        }
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * tightness * tightness;

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 5 {
        score -= 15.0;
    }

    // Penalize dead space that no plausible item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0; // tiny unusable sliver
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Lookahead: if the next item fits the post residual, bonus.
    if next_item_size > 0 {
        if (post_residual as i64) >= (next_item_size as i64) {
            score -= 10.0;
            // extra reward if next item exactly fills the remainder
            if post_residual == next_item_size {
                score -= 15.0;
            }
        } else {
            // next item won't fit here; penalize leaving a large awkward remainder
            let waste = post_residual as f64;
            score += 0.15 * waste;
        }
    }

    // New-bin candidate handling: opening a bin should only win when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decreases if current bin fits are poor.
        let mut new_bin_cost = 30.0;
        if fitting_bins_count == 0 {
            new_bin_cost -= 40.0; // forced: no open bin fits
        } else if fitting_bins_count == 1 {
            new_bin_cost += 20.0; // there is a last-chance bin; prefer using it
        }
        // Late in the stream, avoid proliferating bins with tiny residuals left.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_cost += 10.0 * progress;
        // If mean residual across open bins is large, prefer reusing existing bins.
        if mean_residual > item_size as f64 + 20.0 {
            new_bin_cost += 12.0;
        }
        score += new_bin_cost;
    }

    // Mild preference for bins whose residual is below the mean (consolidate fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Slight penalty when many bins are open (encourage closing out bins).
    score += 0.05 * open_bins_count as f64;

    score
}

