            score -= 2.0 * (1.0 - remaining as f64 / 30.0) * (1.0 - (pr - next_item_size) as f64 / 3.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues divisible by common item
    // sizes (10, 20, 25, 50) are more reusable than awkward remainders.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else {
        let reusable = (pr % 10 == 0) as f64 * 6.0
            + (pr % 25 == 0) as f64 * 4.0
            + (pr % 50 == 0) as f64 * 3.0;
        score -= reusable;
        // Dead space penalty: residual too small for the smallest plausible item
        if pr < 10 {
            score += 25.0;
        }
    }

    // Next-item coupling: reward residuals that can still host the lookahead item
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0 + (pr - next_item_size) as f64 * 0.15;
            // harmonic bonus: post residual leaves a reusable class for item after next
            if (pr - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            score += 8.0; // kills lookahead usability
        }
    }

    // Last-chance bin: strongly prefer filling the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (fitting_bins_count == 0) as f64;
        // penalize opening a new bin, unless it is unavoidable (no fitting bins)
        score += 30.0 - pressure * 60.0 - progress * 5.0;
        // still reward it slightly if mean residual of open bins is fragmented
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    // Mild preference for tighter bins relative to the fleet average
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Integer-division threshold: bins whose residual class (div 10) matches
    // the item's class pair nicely (harmonic size classes).
    let item_class = item_size / 10;
    let res_class = bin_residual / 10;
    if res_class >= item_class && (res_class - item_class) <= 2 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
