    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: penalize using crowded bin sets slightly,
    // but penalize opening new bins more when few bins are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize, scaled by how well existing bins could do.
        score += 18.0 + 12.0 * (1.0 - progress);
    }
    score += open_bins_count as f64 * 0.15;

