    if next_item_size > post_residual && next_item_size > 0 && post_residual > 0 {
        score += 3.0;
    }

    // Mean residual coupling: prefer bins deviating below mean (tighter bins).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.2;

    score
}

