        // MUTATION: fresh-bin mean-alignment — leftover close to mean residual
        // promises reuse; reward mildly when alternatives exist.
        if fresh_left > 0.0 && mean_residual > 4.0 && (fresh_left - mean_residual).abs() <= 3.0 && remaining > 40 && open_bins_count > 2 {
