        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        if remaining < 35 && next_item_size > 0 && pr == next_item_size {
            score -= 3.0;
        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 6 && fitting_bins_count > 2 {
            score -= 1.5;
        }
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        if remaining >= 35 && remaining < 120 && next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 5 {
            score -= 1.0;
        }
        if remaining < 20 && pr > 0 && mean_residual > 1.0 && ((pr as f64) - mean_residual).abs() < 3.0 {
            score -= 1.5;
        }
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
        if remaining < 50 && next_item_size > 0 && pr > 0 && pr == next_item_size {
            score -= 2.5 * (1.0 - remaining as f64 / 50.0);
        }
        // MUTATION: endgame two-item closure — late stream, residuals that fit the
        // next item plus a small margin close out soon.
        if remaining < 30 && next_item_size > 0 && pr > 0 && pr >= next_item_size && pr - next_item_size <= 3 {
            score -= 2.0 * (1.0 - remaining as f64 / 30.0) * (1.0 - (pr - next_item_size) as f64 / 3.0);
        }
        // MUTATION: combined fine-grained + lookahead — exact two-item closure with
        // multiple fitting bins gets a mid-stream bonus.
        if next_item_size > 0 && remaining >= 30 && item_size + next_item_size == pr && fitting_bins_count > 1 {
            score -= 2.0 * (1.0 - progress * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact matches with next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 45.0 * (1.0 - diff / bin_capacity as f64).max(0.0);
        // Perfect two-item fill: huge bonus
        if post_residual == next_item_size {
            score -= 60.0;
        }
        // If next item cannot fit here, penalize leaving awkward space
        if post_residual > 0 && post_residual < next_item_size {
            score += 12.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: strongly prefer tightest fit
        score += 30.0;
    }

    // Penalize dead space relative to mean residual
    let dead = post_residual as f64 - mean_residual;
    if dead > 0.0 {
        score += 0.35 * dead;
    } else {
        score += 0.15 * dead;
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin fits poorly
    if bin_residual == bin_capacity {
        let slack = (bin_residual - item_size) as f64;
        let poor_fit = if next_item_size > 0 && slack >= next_item_size as f64 { 0.0 } else { 1.0 };
        score += 55.0 - 40.0 * poor_fit - 0.1 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Slight preference for fuller bins as stream progresses
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 8.0 * fill * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
