}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale down score when post_residual is small relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 25.0;

    // Dead-space penalty: residuals too small for the minimum item size are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }
    if post_residual == 0 {
        score -= 15.0; // perfect fill
    }

    // Lookahead: strongly favor bins whose post_residual exactly fits the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= (next_item_size as f64 / (post_residual as f64 + 1.0)) * 20.0;
        } else {
            score += 12.0; // next item cannot use this bin's remainder
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // residuals are poor (large mean_residual means open bins are mostly empty).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let emptiness = mean_residual / bin_capacity as f64;
        // Penalize new bins when open bins are already fairly full (small mean residual),
        // and slightly discourage proliferation early in the stream.
        score += 30.0 + emptiness * -20.0 + (1.0 - progress) * 10.0 + open_bins_count as f64 * 0.5;
        // A new bin is good if the item is huge and would leave a very tight fit nowhere.
        if item_size > bin_capacity * 3 / 4 && fitting_bins_count <= 1 {
            score -= 45.0;
        }
    }

    // Mild global pressure: with many open bins, prefer consolidating into existing ones.
    score += open_bins_count as f64 * 0.3;

    // Time horizon: later in the stream, waste matters more, so push toward fuller fills.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0 * (1.0 - tightness);

    // Mean-residual coupling: when mean residual is small (bins nearly full), a bin
    // that still fits the item is precious; reward it.
    if bin_residual != bin_capacity && (bin_residual as f64) >= mean_residual {
        score -= 6.0;
    }

    score
}

