pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_post = post / cap;
    let poly = norm_post * norm_post * (0.5 + 2.0 * progress) + norm_post * (1.0 - progress);
    score += 12.0 * poly;

    // Reward tight fits (small post_residual) more strongly later in the stream.
    let tightness = 1.0 - norm_post;
    score -= (4.0 + 10.0 * progress) * tightness * tightness;

    // Last-chance bonus: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0 + 30.0 * progress;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Lookahead: penalize if post_residual can't fit next item but could if slightly larger.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post as u32 >= next_item_size {
            score -= 6.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 4.0 * (nxt / cap) * (1.0 + progress);
        }
    }

    // Penalize bins deviating from mean residual (prefer balanced residual usage).
    let dev = (post - mean_residual).abs() / cap;
    score += 3.0 * dev * dev;

    // Mild penalty for opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * (open_bins_count as f64).ln() * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
