}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into residue classes mod 10.
    // Small post-residuals that fall into "usable" classes (0..=10 multiples) are rewarded.
    let class = post_residual % 10;
    let class_reward: f64 = match class {
        0 => -12.0,                       // perfectly harmonic leftover (e.g. 10,20,...)
        1 | 9 => -4.0,
        2 | 8 => -1.0,
        _ => 2.0,                          // awkward slivers get penalized
    };
    score += class_reward;

    // Integer-division threshold: how many items of the *next* size could fit in post_residual.
    if next_item_size > 0 && next_item_size <= bin_capacity {
        let fits_next = post_residual / next_item_size.max(1);
        if fits_next >= 1 {
            score -= 8.0 + 3.0 * fits_next.min(4) as f64;
        } else {
            // next item cannot follow here -> dead-end penalty scaled by sliver size
            score += 6.0 + (post_residual as f64) * 0.05;
        }
    } else if next_item_size == 0 {
        // last item: just minimize waste
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer filling the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when the current best option
    // would strand a large, non-harmonic residual.
    if bin_residual == bin_capacity {
        let stranded = (bin_residual as f64) - (item_size as f64);
        let bad_fit = stranded > 40.0 && (stranded as u32) % 10 != 0;
        if bad_fit {
            score -= 14.0; // opening fresh bin beats stranding big odd residual
        } else {
            score += 10.0; // prefer reusing open bins otherwise
        }
    }

    // Stream progression: early on, be conservative about opening bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0;

    // Coupling with mean residual: bins far from the mean residual are slightly
    // deprioritized to keep the pool homogeneous.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.08;

    // Reward tight fits explicitly (post_residual close to a harmonic class boundary).
    if post_residual <= 10 {
        score -= (10 - post_residual) as f64 * 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: heavily reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small nonzero gaps are unusable
    // for typical items (min size 1..100 unknown, but small gaps < 10
    // are almost always dead). Penalize them sharply.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Reward leaving a gap that can fit the lookahead item exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }
    // Penalize if the leftover cannot fit the next item but is large
    // enough to look tempting (wasted potential).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // prefer filling existing bins tighter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * 0.8;

    // New-bin candidate: empty bin must be penalized so it only wins
    // when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 90.0 + mean_residual * 0.5;
    }

    // Mild bonus for bins tighter than average (good consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;
    let frag = pr as f64 - item_size as f64;
    let density = remaining as f64 / total_items.max(1) as f64;

    if pr > 0 && pr < 10 {
        score += 50.0;
    } else if pr > 0 && pr < 20 {
        score += 25.0;
    } else if pr < 25 {
        score += 22.0 * (1.0 - pr as f64 / 25.0);
    }

    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 40.0;
    } else if pr <= 8 {
        score -= 15.0;
    } else if pr <= 15 {
        score -= 6.5;
    } else if pr <= 25 {
        score -= 1.0;
    } else if pr <= 40 {
        score += 4.0;
    } else if pr <= 60 {
        score += 8.0;
    } else {
        score += 12.0;
    }

    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        let dead = (next_item_size - pr) as f64;
        let scarcity = if fitting_bins_count <= 2 { 1.25 } else { 1.0 };
        score += dead * (0.25 + 0.55 * density) * scarcity;
    }

    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
            if fitting_bins_count <= 2 {
                score -= 4.0;
            }
            if remaining < 35 {
                score -= 3.0;
            }
        } else if next_item_size > pr {
            score += pr as f64 * 0.5;
        } else {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 0.0 && slack < 14.0 && fitting_bins_count > 1 {
                score += slack * 0.10 * (1.0 - slack / 14.0);
            }
            if slack > 45.0 {
                score += (slack - 45.0) * 0.05;
            }
        }
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        if pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        if frag > 0.0 && frag < next_item_size as f64 && next_item_size - frag as u32 <= 4 {
            score += (next_item_size - frag as u32) as f64 * 0.9;
        }
        if pr > 0 && pr < next_item_size && next_item_size - pr <= 3 && remaining > 80 {
            score += (next_item_size - pr) as f64 * 0.6;
        }
        if frag > 0.0 && frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        if frag > 0.0 && frag < next_item_size as f64 {
            let dead = next_item_size as f64 - frag;
            if dead > 6.0 && fitting_bins_count > 1 {
                score += dead * 0.12;
            }
        }
        if frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
            score += (frag - next_item_size as f64) * 0.10;
            if mean_residual < 16.0 && remaining > 100 {
                score += (frag - next_item_size as f64) * 0.08;
            }
        }
        if pr > 0 && pr % next_item_size == 0 {
            score -= 1.5;
            if pr / next_item_size >= 2 && remaining > 50 {
                score -= 2.0 * ((pr / next_item_size) as f64).min(3.0);
            }
        }
        if next_item_size > 1 && pr > 0 && pr >= next_item_size && (pr / next_item_size) >= 2 && (pr % next_item_size) <= 2 && remaining > 30 {
            score -= 1.6 * ((pr / next_item_size) as f64).min(4.0);
        }
        if pr > next_item_size && (pr - next_item_size) * 2 <= pr {
            score -= 1.2;
        }
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 {
                score += (gap as f64 - 25.0) * 0.08;
            }
        }
        // two-step lookahead — residual that holds next item then a second one exactly
        if next_item_size > 1 && pr >= item_size + next_item_size {
            let rest = pr - item_size - next_item_size;
            if rest >= next_item_size && rest - next_item_size <= 4 && remaining > 25 {
                score -= 2.2 * (1.0 - (rest - next_item_size) as f64 / 4.0);
            }
        }
        // near-miss dead space below next item, mid-stream
        if next_item_size > 0 && pr > 0 && pr < next_item_size && next_item_size - pr <= 6 && remaining > 30 && fitting_bins_count > 2 {
            score += (next_item_size - pr) as f64 * 0.45 * (1.0 - (next_item_size - pr) as f64 / 6.0);
        }
        // MUTATION A: dead-space budget term — reward residuals that leave exactly one next-item slot whose remainder matches the mean residual band
        if next_item_size > 0 && pr > 0 && pr >= next_item_size {
            let rem_after = pr - next_item_size;
            if rem_after > 0 && (rem_after as f64 - mean_residual).abs() <= 2.0 && remaining > 20 {
                score -= 1.8 * (1.0 - (rem_after as f64 - mean_residual).abs() / 2.0);
            }
            // MUTATION B: chained divisibility — post-residual divisible by next item across multiple slots, stronger when bins are scarce
            if rem_after > 0 && rem_after % next_item_size == 0 && rem_after / next_item_size >= 2 && fitting_bins_count <= 3 && remaining > 60 {
                score -= 1.4 * ((rem_after / next_item_size) as f64).min(4.0);
            }
            // MUTATION C: large-dead-space avoidance — strand more than half of next-item size unusable with many alternatives
            if pr < next_item_size && next_item_size - pr > next_item_size / 2 && fitting_bins_count > 3 && remaining > 50 {
                score += (next_item_size - pr) as f64 * 0.30;
            }
        }
    }

    score += open_bins_count as f64 * 0.3;

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    score -= (bin_residual as f64 - mean_residual) * 0.2;

    if frag > mean_residual && frag > 12.0 && remaining > 30 {
        score += (frag - mean_residual) * 0.06;
    }
    if frag > 40.0 && remaining > 60 {
        score += (frag - 40.0) * 0.05;
    }
    if frag > 0.0 && frag > mean_residual * 1.6 && remaining > 30 {
        score += (frag - mean_residual * 1.6) * 0.04;
    }
    let fill_ratio = item_size as f64 / bin_capacity.max(1) as f64;
    if frag > 0.0 && fill_ratio < 0.42 && remaining > 40 {
        score += (0.42 - fill_ratio) * 16.0 * (1.0 - progress * 0.5);
    }

    if pr > 0 && mean_residual > 1.0 {
        let dev = ((pr as f64 - mean_residual) / mean_residual).abs();
        if dev < 0.3 {
            score -= 2.0 * (1.0 - dev / 0.3);
        } else if dev > 1.5 && pr as f64 > mean_residual * 2.0 {
            score += 2.5;
        }
    }
    // progress-aware stranding risk coupling
    if pr > 0 && mean_residual > 3.0 && (pr as f64) < mean_residual * 0.80 && remaining > 60 {
        score += (mean_residual * 0.80 - pr as f64) * (0.18 + 0.14 * progress);
    }
    if pr > 0 && mean_residual > 2.0 && (pr as f64) < mean_residual && (mean_residual - pr as f64) < 6.0 {
        score += (mean_residual - pr as f64) * 0.35;
    }

    score += pr as f64 * (0.1 + 0.25 * progress);

    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        if item_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        let fresh_left = bin_capacity.saturating_sub(item_size) as f64;
        if remaining > 60 && fresh_left > 0.0 && fresh_left < mean_residual * 1.25 && open_bins_count > 0 {
            score += (mean_residual * 1.25 - fresh_left) * 0.38;
        }
        if fresh_left <= 6.0 && remaining > 30 {
            score -= 4.0;
        }
        if fitting_bins_count > 0 && fresh_left <= 3.0 && item_ratio > 0.9 {
            score -= 5.0;
        }
        if fresh_left > 0.0 && mean_residual > 1.0 && remaining > 40 {
            let d = (fresh_left - mean_residual).abs();
            if d < 4.0 {
                score -= 2.0 * (1.0 - d / 4.0);
            }
        }
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        if mean_residual > 30.0 && remaining > 100 {
            score -= 2.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            if mean_residual >= next_item_size as f64 && fitting_bins_count > 0 {
                score += 4.0;
            } else {
                score -= 4.0;
            }
        }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 {
            score += 3.0;
        }
        if next_item_size > 0 && fitting_bins_count >= 2 && mean_residual >= next_item_size as f64 {
            score += 2.0;
        }
        if next_item_size > 0 && next_item_size > bin_capacity - item_size && remaining > 30 && open_bins_count > 0 && mean_residual >= next_item_size as f64 {
            score += 6.0;
        }
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && (next_item_size as f64 - fresh_left) <= 8.0 && remaining > 40 {
            score += (next_item_size as f64 - fresh_left) * 0.5;
        }
        if next_item_size > 2 && fresh_left > 0.0 && fresh_left % next_item_size as f64 == 0.0 && fresh_left / next_item_size as f64 >= 2.0 && remaining > 60 {
            score -= 2.5;
        }
        if next_item_size > 1 && fresh_left >= next_item_size * 3 && remaining > 50 {
            score -= 2.0;
        }
        // near-miss fresh-bin guard
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && (next_item_size as f64 - fresh_left) <= 5.0 && remaining > 60 && fitting_bins_count > 1 {
            score += (next_item_size as f64 - fresh_left) * 0.8;
        }
        // chained divisibility — fresh leftover splits into next-item multiples
        if next_item_size > 1 && fresh_left > next_item_size as f64 && ((fresh_left - next_item_size as f64) as u32) % next_item_size == 0 && remaining > 80 {
            score -= 1.2;
        }
        // stranded fresh leftover below mean residual
        if fresh_left > 0.0 && mean_residual > 2.0 && fresh_left < mean_residual * 0.7 && remaining > 60 {
            score += (mean_residual * 0.7 - fresh_left) * 0.30;
        }
        // exact next-item leftover bonus
        if next_item_size > 0 && fresh_left == next_item_size as f64 && remaining > 15 {
            score -= 4.0;
        }
        // MUTATION D: fresh-bin mean-alignment — new bin whose leftover matches mean residual promises reuse
        if fresh_left > 0.0 && mean_residual > 4.0 && (fresh_left - mean_residual).abs() <= 3.0 && remaining > 40 && open_bins_count > 2 {
            score -= 1.5 * (1.0 - (fresh_left - mean_residual).abs() / 3.0);
        }
        // MUTATION E: fresh-bin multi-fit lookahead — leftover that holds three next-items is valuable
        if next_item_size > 1 && fresh_left >= (next_item_size * 3) as f64 && fresh_left < (next_item_size * 4) as f64 && remaining > 50 {
            score -= 1.0;
        }
        if fitting_bins_count > 0 {
            score += 4.0;
        }
        if remaining < 8 && fitting_bins_count > 0 {
            score += 5.0;
        }
        if remaining < 12 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 4.0;
        }
        if remaining < 15 && fitting_bins_count > 0 {
            score += 3.0;
        }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
    } else {
        score += 60.0;
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 6 && fitting_bins_count > 2 {
            score -= 1.5;
        }
        if remaining >= 35 && remaining < 120 && next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 5 {
            score -= 1.0;
        }
        if remaining < 20 && pr > 0 && mean_residual > 1.0 && ((pr as f64) - mean_residual).abs() < 3.0 {
            score -= 1.5;
        }
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        // endgame exact-closure widened
        if remaining < 50 && next_item_size > 0 && pr > 0 && pr == next_item_size {
            score -= 2.5 * (1.0 - remaining as f64 / 50.0);
        }
        // endgame — strongly prefer fits that leave zero post-residual
        if remaining < 15 && pr == 0 {
            score -= 4.0;
        }
        // MUTATION F: endgame two-item closure — late stream, residuals that fit next item plus small margin close out soon
        if remaining < 30 && next_item_size > 0 && pr > 0 && pr >= next_item_size && pr - next_item_size <= 3 {
            score -= 2.0 * (1.0 - remaining as f64 / 30.0) * (1.0 - (pr - next_item_size) as f64 / 3.0);
        }
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio;

    // Aggressive 2-step lookahead: reward exact chaining of next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect two-item fill
        } else if post_residual >= next_item_size {
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * next_fit; // tighter next fit is better
        } else {
            // next item cannot follow here; penalize wasted residual relative to mean
            score += 10.0 + (post_residual as f64 - mean_residual).abs();
        }
    } else {
        // last item: prefer any bin that closes completely
        if post_residual == 0 {
            score -= 50.0;
        }
    }

    // Penalize leaving dead space below the smallest plausible item (1..100 range: use small threshold)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalize opening a new bin mildly; escalate with number of open bins
        score += 35.0 + 3.0 * open_bins_count as f64;
        // but if next item is huge and current item small, new bin may be better
        if next_item_size > 0 && next_item_size > bin_capacity - item_size.min(bin_capacity) {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Prefer filling bins whose residual is far below mean (consolidate fragmentation)
    if !is_new_bin {
        score -= 5.0 * (mean_residual - bin_residual as f64).max(0.0) / bin_capacity as f64;
    }

    // Late in stream: be greedier about closing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual == 0 {
        score -= 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 40.0;

    // Reward perfect fit strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 5 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits in the post residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if next_item_size <= bin_residual {
            // next item would need another bin; slight penalty if we waste big residual here
            score += post_residual as f64 * 0.1;
        }
        // If next item is large, keep big residuals free for it.
        if next_item_size > 50 && post_residual < next_item_size && post_residual > 0 {
            score += 5.0;
        }
    }

    // Time horizon: early in stream, prefer compacting into fewer bins (favor open bins);
    // late in stream, tighter packing matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    // Penalize bins with residual far below mean (fragmented bins) mildly.
    let diff = mean_residual - bin_residual as f64;
    score += diff * 0.15;

    // Many open bins: discourage opening new ones unless fit is excellent.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64; // == capacity - item_size
        let new_bin_bonus = 60.0 - waste * 0.9;
        score -= new_bin_bonus * (1.0 - progress * 0.5);
        if open_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Prefer bins whose residual is just above item size (best-fit character).
    let gap = bin_residual as f64 - item_size as f64;
    score += gap * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
