    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear penalty on small residuals
    let mut score = pr as f64 - 12.0 * (1.0 - norm_pr).powi(3) * cap * 0.25;

    // Smooth polynomial coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - norm_pr) * (0.5 + progress);
    score += 30.0 * coupling;

    // Late stream: penalize leaving moderate residuals (hard to fill later)
    score += progress * 8.0 * (norm_pr - 0.5).powi(2);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 10.0 * (1.0 - ((pr - ns) / cap).abs().min(1.0));
        } else {
            score += 6.0;
        }
    }

    // Prefer bins below mean residual (fill emptier bins first, smoothly)
    score += 0.05 * (pr - mean_residual);

    // Mild penalty for many open bins
    score += 0.5 * open_bins_count as f64 * (0.5 + progress);

    score
}

