pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Reward near-match: next item fits snugly into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 / (1.0 + slack / 10.0);
    }
    // Penalize leaving space too small for the next item (dead space).
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += dead * 0.8;
    }

    // Compare post residual against mean residual: prefer tightening loose bins.
    if (post_residual as f64) < mean_residual {
        score -= (mean_residual - post_residual as f64) * 0.3;
    } else {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    // Last-chance bonus: only one fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let tight = if next_item_size > 0 && (bin_capacity as f64 - item_size as f64).abs() < 1e9 && item_size + next_item_size <= bin_capacity { 1.0 } else { 0.0 };
        // Fresh bin: baseline cost, discounted when stream is early or many items remain.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 120.0 - 30.0 * pressure - 20.0 * tight - 20.0 * (1.0 - progress);
    }

    // Slight preference for bins with small residual overall (best-fit flavor).
    score += post_residual as f64 * 0.05;

    score
}

