pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize large wasted residual quadratically (dead space)
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Reward tight fits
    if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead coupling: bonus if next item fits in the post-residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            // Penalize leaving residual that next item can't use but is too small to be useful
            if post_residual < 10 {
                score += 8.0;
            }
        }
    }

    // Perfect fit with lookahead: chain bonus
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Time horizon: early in stream, prefer opening new bins over fragmenting
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline penalty modulated by progress and open bins
        score = (bin_capacity as f64) * 0.9 + 25.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // If item is large and few fitting bins, new bin less attractive
        if item_size as f64 > 0.7 * bin_capacity as f64 {
            score += 10.0;
        }
        // Late in stream, avoid opening bins unless really needed
        if progress > 0.8 {
            score += 15.0;
        }
    } else {
        // Prefer bins with residual close to item size (best-fit flavor)
        score += (bin_residual - item_size) as f64 * 0.05;
        // Encourage using bins far below mean residual (balance)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
