pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let mut score = pr;
    // smooth non-linear coupling: post-residual weighted by stream progress
    score *= 1.0 + 0.8 * progress * pr_norm;
    // penalize large wasted residual quadratically
    score += 40.0 * pr_norm * pr_norm * (1.0 + progress);
    // reward tight fits (small post residual) especially late in the stream
    score -= 25.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (0.5 + progress) * item_norm;
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }
    // lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as f64 >= nxt {
            score -= 12.0 * (1.0 - (pr - nxt) / cap) * (1.0 - pr_norm);
        } else {
            score += 8.0 * (nxt - pr) / cap;
        }
    }
    // mildly prefer bins with residuals near the mean (balanced packing)
    score += 0.05 * (pr - mean_residual).abs();
    // new-bin candidate: penalize opening unless residuals are tight
    if bin_residual == bin_capacity {
        score += 30.0 + 60.0 * (1.0 - progress) + 5.0 * open_bins_count as f64;
        if pr as f64 >= next_item_size as f64 && next_item_size > 0 {
            score -= 20.0;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
