pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // fraction of capacity remaining

    // Dead-space penalty: leftover that no future item (min size 1) can use is worst.
    // Harmonic classes: post_residual in [0..10] is near-perfect packing (reward),
    // mid-range leftovers are "harmonic traps" (penalize).
    if post_residual <= 5 {
        score -= 30.0; // excellent fit
    } else if post_residual <= 15 {
        score -= 12.0;
    } else if post_residual <= 30 {
        score += 5.0; // moderate leftover
    } else if post_residual <= 50 {
        score += 14.0; // harmonic trap zone
    } else {
        score += 20.0;
    }

    // Modulo arithmetic on post_residual: multiples of 10 are "harmonic" leftovers
    // that pair well with common item sizes; slight reward.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Leftovers in [1..9] modulo classes: small residue is fine.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0;
    }

    // Integer-division threshold: post_residual / 20 gives coarse class.
    let class = post_residual / 20;
    score += class as f64 * 3.0;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = post_residual - next_item_size;
        if diff == 0 {
            score -= 25.0; // perfect chain
        } else if diff <= 10 {
            score -= 10.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here regardless; leftover is dead for the lookahead.
        score += 6.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad
    // and the item is large (large items deserve fresh space).
    if bin_residual == bin_capacity {
        let bad_fit = post_residual > 40 && fitting_bins_count > 0;
        if bad_fit {
            score -= 10.0; // fresh bin beats a wasteful fit
        } else {
            score += 25.0; // prefer existing bins for decent fits
        }
    }

    // Stream progression: early on, be frugal with bins; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 4.0 * (open_bins_count as f64).sqrt();

    // Prefer bins below mean residual (tighter bins first).
    score += (mean_residual - post) * 0.15;

    score
}

