        if remaining < 30 && next_item_size > 0 && pr > 0 && pr >= next_item_size && pr - next_item_size <= 3 {
            score -= 2.0 * (1.0 - remaining as f64 / 30.0) * (1.0 - (pr - next_item_size) as f64 / 3.0);
        }
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable dead space penalty
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tightness: reward filling a large fraction of the bin
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Penalize bins whose residual deviates far from mean residual (fragmentation control)
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Open bins pressure: with many open bins, discourage opening new ones;
    // with few open bins, new bins are cheaper.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * open_bins_count as f64 * (0.5 + progress);
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 6.0; // creates a gap blocking the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fit (dead-space penalty is quadratic).
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // 2-step lookahead: reward if the next item exactly fills the post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // perfect chain: this bin becomes exactly full
        } else if next_item_size <= post_residual {
            // reward proportional to how tightly the next item fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here: penalize leaving a large awkward gap
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and would leave a bad gap elsewhere; empty bin starts at full residual so
    // add an offset to make it lose against decent fits.
    if bin_residual == bin_capacity {
        score += 15.0;
        // allow new bin late in stream when many bins are open and fit is tight
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if item_size > bin_capacity / 2 && progress > 0.5 {
            score -= 10.0;
        }
    }

    // Slight preference for bins with residuals below mean (consolidate small gaps).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
