pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * tightness * tightness;

    // Penalize large dead space after placement, especially when it cannot fit
    // typical future items (small residuals are more useful than mid ones).
    if post_residual > 0 {
        let waste = post_residual as f64;
        if waste < 10.0 {
            score -= 15.0; // tiny dead space is fine
        } else {
            score += 0.8 * (waste - 10.0).sqrt() * (waste / bin_capacity as f64);
        }
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        // post residual too small for next item: mild penalty scaled by waste
        score += 0.25 * post_residual as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.3 * item_size as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are fragmented or the item is huge.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Penalize new bins by default; discount when open bins are crowded/fragmented
        let mut new_bin_penalty = 45.0;
        if mean_residual < item_size as f64 * 1.2 {
            new_bin_penalty -= 25.0;
        }
        if item_size > 60 {
            new_bin_penalty -= 10.0;
        }
        if fragmentation > 40.0 {
            new_bin_penalty -= 8.0;
        }
        // late in the stream, slightly prefer consolidating
        new_bin_penalty += 10.0 * progress;
        score += new_bin_penalty;
    }

    // Mild penalty for spreading across many open bins: prefer filling few bins deeply.
    score += 0.4 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual deviates from the mean toward being fuller.
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

