            let slack2 = (pr - next_item_size) as f64;
            if slack2 > 7.0 && slack2 < 15.0 {
                score += slack2 * (0.06 + 0.10 * progress);
            }
        }
        // Dead-space ratio vs mean coupling — stranding risk mid-stream.
        if pr > 0 && pr < next_item_size && mean_residual > 4.0 && (pr as f64) < mean_residual && remaining > 50 {
            score += (next_item_size - pr) as f64 * 0.30 * (1.0 - progress * 0.4);
        }
        // Lookahead anticipation — residual fitting next item twice with zero slack is a perfect chain host.
        if next_item_size > 1 && pr >= next_item_size * 2 && pr - next_item_size * 2 <= 1 && fitting_bins_count > 1 {
            score -= 2.0 + 1.5 * (1.0 - progress);
        }
        // COMBINED FEATURE: dead-space budget term — reward residuals that leave exactly one
        // next-item slot AND whose remainder matches the mean residual band (predictable reuse).
        if pr > 0 && pr >= next_item_size {
            let rem_after = pr - next_item_size;
            if rem_after > 0 && (rem_after as f64 - mean_residual).abs() <= 2.0 && remaining > 20 {
                score -= 1.8 * (1.0 - (rem_after as f64 - mean_residual).abs() / 2.0);
            }
            // Chained-divisibility bonus — residual divisible by next item across multiple
            // slots, stronger late when bins are scarce.
            if rem_after > 0 && rem_after % next_item_size == 0 && rem_after / next_item_size >= 2 && fitting_bins_count <= 3 && remaining > 60 {
                score -= 1.4 * ((rem_after / next_item_size) as f64).min(4.0);
            }
            // Large-dead-space avoidance — strand more than half of next-item size unusable
            // with many alternatives is heavily penalized.
            if pr < next_item_size && next_item_size - pr > next_item_size / 2 && fitting_bins_count > 3 && remaining > 50 {
                score += (next_item_size - pr) as f64 * 0.30;
            }
        }
    }

    // Open-bin pressure: prefer tighter packing when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Slight bias toward bins with larger residuals (better long-term hosts).
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Fragments larger than mean residual waste capacity going forward.
    if frag > mean_residual && frag > 12.0 && remaining > 30 {
        score += (frag - mean_residual) * 0.06;
    }
    // Very large fragments waste even more.
    if frag > 40.0 && remaining > 60 {
        score += (frag - 40.0) * 0.05;
    }
    // Very large frag beyond 1.6x mean strands capacity.
    if frag > mean_residual * 1.6 && remaining > 30 {
        score += (frag - mean_residual * 1.6) * 0.04;
    }

    // Late in the stream, tighten packing further.
    score += pr as f64 * (0.1 + 0.22 * progress);

    // Residual close to mean residual is a good host for future items.
    if pr > 0 && mean_residual > 1.0 {
        let dev = ((pr as f64 - mean_residual) / mean_residual).abs();
        if dev < 0.3 {
            score -= 2.0 * (1.0 - dev / 0.3);
        } else if dev > 1.5 && pr as f64 > mean_residual * 2.0 {
            score += 2.5;
        }
        if mean_residual > 2.0 && (pr as f64) < mean_residual && (mean_residual - pr as f64) < 6.0 {
            score += (mean_residual - pr as f64) * 0.35;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        if item_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 {
            score -= 3.0;
        }
        let fresh_left = bin_capacity.saturating_sub(item_size) as f64;
        if remaining > 60 && fresh_left > 0.0 && fresh_left < mean_residual * 1.25 && open_bins_count > 0 {
            score += (mean_residual * 1.25 - fresh_left) * 0.38;
        }
        if fresh_left <= 6.0 && remaining > 30 {
            score -= 4.0;
        }
        if fitting_bins_count > 0 && fresh_left <= 3.0 && item_ratio > 0.9 {
            score -= 5.0;
        }
        if fresh_left > 0.0 && mean_residual > 1.0 && remaining > 40 {
            let d = (fresh_left - mean_residual).abs();
            if d < 4.0 {
                score -= 2.0 * (1.0 - d / 4.0);
            }
        }
        // Discourage fresh bin when leftover sits just under next item (dead space).
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && (next_item_size as f64 - fresh_left) <= 8.0 && remaining > 40 {
            score += (next_item_size as f64 - fresh_left) * 0.5;
        }
        // Reward fresh bin when leftover is an exact multiple of next size.
        if next_item_size > 2 && fresh_left > 0.0 && fresh_left % next_item_size as f64 == 0.0 && fresh_left / next_item_size as f64 >= 2.0 && remaining > 60 {
            score -= 2.5;
        }
        // Fresh-bin multi-fit lookahead.
        if next_item_size > 1 && fresh_left >= next_item_size as f64 * 3.0 && remaining > 50 {
            score -= 2.0;
        }
        // Fresh-bin divisibility refinement (chained fits).
        if next_item_size > 1 && fresh_left > next_item_size as f64 && ((fresh_left - next_item_size as f64) as u32) % next_item_size == 0 && remaining > 80 {
            score -= 1.2;
        }
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 4.0;
        }
        if fitting_bins_count > 0 {
            score += 4.0;
        }
        // Fresh leftover near next item with mean residual need.
        if next_item_size > 0 && fitting_bins_count > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && next_item_size as f64 - fresh_left <= 6.0 && remaining > 60 {
            score -= 2.0;
        }
        if next_item_size > 0 && fresh_left >= next_item_size as f64 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 {
            score += 2.0;
        }
        // Fresh leftover far above mean need with many bins open — cheap to open.
        if fresh_left > 0.0 && mean_residual > 2.0 && fresh_left > mean_residual * 1.8 && remaining > 100 && open_bins_count > 3 {
            score -= 1.5;
        }
        // Fresh leftover below next item late in stream — penalize proportionally.
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && remaining > 120 {
            score += (next_item_size as f64 - fresh_left) * 0.35;
        }
        // Fresh-bin near-miss guard.
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && (next_item_size as f64 - fresh_left) <= 5.0 && remaining > 60 && fitting_bins_count > 1 {
            score += (next_item_size as f64 - fresh_left) * 0.8;
        }
        if remaining < 8 && fitting_bins_count > 0 {
            score += 5.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 4.0;
        }
        if remaining < 12 && fitting_bins_count > 0 {
            score += 3.0;
        }
        // Mean residual close to next item size — fresh bin less useful.
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
        // Next item won't fit fresh leftover but fits elsewhere — push toward open bins.
        if next_item_size > 0 && next_item_size > bin_capacity - item_size && remaining > 30 && open_bins_count > 0 && mean_residual >= next_item_size as f64 {
            score += 6.0;
        }
        // Next item is small and mean residual can host it — fresh bin less useful.
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 {
            score += 3.0;
        }
        // High mean residual late — fresh bin cheaper than stranding.
        if mean_residual > 30.0 && remaining > 100 {
            score -= 2.0;
        }
        // Many open bins with mean residual able to host next item, late stream.
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
        // Fresh-bin lookahead anticipation — exact host for next item under scarce capacity.
        if next_item_size > 0 && fresh_left == next_item_size as f64 && mean_residual < 10.0 && remaining > 40 {
            score -= 3.0;
        }
        // Fresh-bin fine-grained dead-space guard.
        if fresh_left > 0.0 && fresh_left < bin_capacity as f64 * 0.45 && open_bins_count > 4 && remaining > 60 {
            score += (bin_capacity as f64 * 0.45 - fresh_left) * 0.12;
        }
        // COMBINED FEATURE: fresh-bin mean-alignment — a new bin whose leftover closely
        // matches the stream's mean residual promises reuse; reward mildly.
        if fresh_left > 0.0 && mean_residual > 4.0 && (fresh_left - mean_residual).abs() <= 3.0 && remaining > 40 && open_bins_count > 2 {
            score -= 1.5 * (1.0 - (fresh_left - mean_residual).abs() / 3.0);
        }
        // COMBINED FEATURE: fresh-bin lookahead anticipation — fresh leftover that hosts the
        // next item plus leaves a remainder matching mean residual is a predictable host.
        if next_item_size > 0 && fresh_left > next_item_size as f64 {
            let rem2 = fresh_left - next_item_size as f64;
            if rem2 > 0.0 && (rem2 - mean_residual).abs() <= 2.0 && remaining > 60 {
                score -= 1.6 * (1.0 - (rem2 - mean_residual).abs() / 2.0);
            }
        }
    } else {
        score += 60.0;
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        if remaining < 35 && next_item_size > 0 && pr == next_item_size {
            score -= 3.0;
        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 6 && fitting_bins_count > 2 {
            score -= 1.5;
        }
        // Endgame exact-closure bonus.
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        // Mid-stream near-closure bonus scaled by progress.
        if remaining >= 35 && remaining < 120 && next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 5 {
            score -= 1.0;
        }
        // Endgame — prefer residual matching mean need.
        if remaining < 20 && pr > 0 && mean_residual > 1.0 && ((pr as f64) - mean_residual).abs() < 3.0 {
            score -= 1.5;
        }
        // Many fitting bins and residual larger than mean — mild penalty.
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
        // Endgame exact-closure widened.
        if remaining < 50 && next_item_size > 0 && pr > 0 && pr == next_item_size {
            score -= 2.5 * (1.0 - remaining as f64 / 50.0);
        }
        // Combined fine-grained + lookahead — residual that closes exactly after the next
        // two items with zero slack gets a mid-stream bonus.
        if next_item_size > 0 && remaining >= 30 && item_size + next_item_size == pr && fitting_bins_count > 1 {
            score -= 2.0 * (1.0 - progress * 0.5);
        }
        // Fine-grained closure band — residual within 3 of (next + next) mid-stream
        // anticipates two-step zeroing; stronger when bins are crowded.
        if next_item_size > 1 && remaining > 40 && pr >= next_item_size * 2 && pr - next_item_size * 2 <= 3 {
            score -= (1.2 + open_bins_count.min(10) as f64 * 0.1) * (1.0 - (pr - next_item_size * 2) as f64 / 3.0);
        }
        // COMBINED FEATURE: endgame two-item closure — late stream, residuals that fit the
        // next item plus a small margin close out soon.
        if remaining < 30 && next_item_size > 0 && pr > 0 && pr >= next_item_size && pr - next_item_size <= 3 {
            score -= 2.0 * (1.0 - remaining as f64 / 30.0) * (1.0 - (pr - next_item_size) as f64 / 3.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Smooth polynomial coupling of post residual with stream progress
    let poly = x * x * (1.0 - x) * (1.0 + progress);
    score -= 8.0 * poly * cap / 25.0;

    // Penalize dead space more as stream progresses (less time to recover)
    score += progress * (x * x) * 4.0;

    // Last-chance bonus: only fitting bin
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Lookahead fit reward: next item fits into post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let tight = 1.0 - (pr - next_item_size as f64) / cap;
        score -= 3.0 * tight;
    } else if next_item_size > 0 {
        score += 1.5 * progress;
    }

    // Slight penalty for wasting a nearly-full bin residual mismatch vs mean residual
    let dev = (mean_residual - pr).abs() / cap;
    score += 0.5 * dev * (1.0 - progress);

    // New-bin candidate handling: neutral-ish, mildly discouraged early
    if bin_residual == bin_capacity {
        score += 2.0 * (1.0 - progress) - 1.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;
    let frag = pr as f64 - item_size as f64;

    // Dead-space avoidance: small unusable gaps are heavily penalized.
    if pr > 0 && pr < 10 {
        score += 55.0;
    } else if pr < 25 {
        score += 22.0 * (1.0 - pr as f64 / 25.0);
    }

    // Reward near-perfect fills (widened exact-closure band).
    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 42.0;
    } else if pr <= 8 {
        score -= 16.0;
    } else if pr <= 12 {
        score -= 10.0;
    } else if pr <= 15 {
        score -= 4.0;
    } else if pr <= 25 {
        score -= 1.0;
    } else if pr <= 40 {
        score += 4.0;
    } else if pr <= 60 {
        score += 8.0;
    } else {
        score += 12.0;
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size > pr {
            let dead = (next_item_size - pr) as f64;
            let density = remaining as f64 / total_items.max(1) as f64;
            let scarcity = if fitting_bins_count <= 2 { 1.25 } else { 1.0 };
            score += pr as f64 * 0.5 + dead * (0.25 + 0.55 * density) * scarcity;
        } else {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 {
                score -= 5.0;
            }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 45.0 {
                score += (slack - 45.0) * 0.05;
            }
        }
        // Two-item lookahead: next item fits twice more.
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        // Chain-friendliness: residual divisible by next size.
        if pr > 0 && pr >= next_item_size && pr % next_item_size == 0 && pr / next_item_size >= 2 && remaining > 50 {
            score -= 2.0 * ((pr / next_item_size) as f64).min(3.0);
