    } else if pr <= 8 {
        score -= 16.0;
    } else if pr <= 12 {
        score -= 10.0;
    } else if pr <= 15 {
        score -= 4.0;
    } else if pr <= 25 {
        score -= 1.0;
    } else if pr <= 40 {
        score += 4.0;
    } else if pr <= 60 {
        score += 8.0;
    } else {
        score += 12.0;
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
