pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // 2-step lookahead: reward if next item fits into post_residual exactly-ish
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item fill
        } else if next_item_size < post_residual {
            let next_post = post_residual - next_item_size;
            score -= 40.0 * (1.0 - next_post as f64 / bin_capacity as f64);
            // penalize leaving awkward residual for the item after
            score += (next_post as f64).powi(2) / 200.0;
        } else {
            // next item won't fit here: dead space penalty grows with gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.5;
        }
    }

    // Relative to mean residual: prefer bins already tighter than average
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so we only open when fits are bad,
    // but keep it viable late in the stream or when mean residual is low
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 - 10.0 * progress;
        if mean_residual < item_size as f64 {
            score -= 15.0; // no good home elsewhere -> new bin is fine
        }
    }

    // Discourage leaving residuals in the awkward 1..10 dead zone
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
