pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item leaves little waste.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small for the smallest plausible item (<=5).
    if post_residual <= 5 {
        score -= 8.0; // perfect fill, excellent
    } else if post_residual < 15 {
        score -= 3.0; // likely unusable sliver
    } else {
        // Residual still usable: mild penalty scaled by how much remains
        score += 0.03 * (post_residual as f64 - 15.0);
    }

    // Lookahead: if next item can pair into the post-residual, reward this bin.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if next_item_size > post_residual && post_residual < 15 {
            // post-residual too small for next item anyway; keeping this bin tight is fine
            score -= 2.0;
        } else {
            // next item won't fit here: slight penalty so we don't waste a big residual
            score += 1.5;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when no
    // open bin fits well (large post-residual waste) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Cost of a fresh bin grows with progress (fewer chances to fill it).
        score += 25.0 + 30.0 * progress;
        // If many bins are open with slack, discourage opening another.
        score += 0.5 * open_bins_count as f64;
        // If mean residual is large, open bins likely suffice.
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    } else {
        // Slight preference for reusing existing bins over opening new ones.
        score -= 2.0;
        // Prefer bins whose residual is below mean (consolidate waste).
        if (bin_residual as f64) < mean_residual {
            score -= 1.0;
        }
    }

    // Early stream: be slightly more tolerant of slack residuals since many
    // items remain to fill them; late stream: penalize leftover slack harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
