pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: penalize leftover space, with non-linear (quadratic) growth in waste.
    let mut score = pr + 0.9 * (pr / cap) * (pr / cap) * cap;

    // Reward tight fits: small post_residual relative to item size.
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness * (it / cap);

    // Stream-progress coupling: early on, tolerate loose fits (favor consolidation);
    // later, demand tighter fits by scaling the waste penalty up.
    let progress_coupling = 1.0 + 1.5 * progress * progress;
    score *= progress_coupling;

    // Lookahead coupling: if the next item fits into the post-residual, reward this bin.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let nx = next_item_size as f64;
        let compat = 1.0 - ((pr - nx) / cap);
        score -= 10.0 * compat * (nx / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here: mild penalty proportional to how badly it misses.
        let miss = (next_item_size as f64 - pr) / cap;
        score += 6.0 * miss * miss * cap;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless the waste is egregious).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 20.0 * (1.0 - pr / cap);
    }

    // Penalize spreading across too many open bins (encourage consolidation),
    // scaled by mean residual imbalance.
    let imbalance = (mean_residual - pr).abs() / cap;
    score += 3.0 * imbalance * (open_bins_count as f64).ln();

    // New-bin candidate handling: it should only win when the fit in any open bin
    // would be very poor. Give the fresh bin a smooth baseline derived from its
    // own post-residual (already in base score) plus a mild opening cost that
    // shrinks as the stream progresses.
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
