        if pr > 0 && pr >= next_item_size {
            let rem_after = pr - next_item_size;
            if rem_after > 0 && (rem_after as f64 - mean_residual).abs() <= 2.0 && remaining > 20 {
                score -= 1.8 * (1.0 - (rem_after as f64 - mean_residual).abs() / 2.0);
            }
        }
        // Stranding risk coupling: residual well below mean residual mid-stream.
        if pr > 0 && mean_residual > 3.0 && (pr as f64) < mean_residual * 0.80 && remaining > 60 {
            score += (mean_residual * 0.80 - pr as f64) * (0.18 + 0.14 * progress);
        }
        // Residual barely above next item with many alternatives: mild waste signal.
        if pr > next_item_size && (pr - next_item_size) > 0 && (pr - next_item_size) < 14 && fitting_bins_count > 1 {
            let dead2 = (pr - next_item_size) as f64;
            score += dead2 * 0.10 * (1.0 - dead2 / 14.0);
        }
        // Next item fits and leaves room at least twice its size: good host.
        if pr > next_item_size && (pr - next_item_size) * 2 <= pr {
            score -= 1.2;
        }
        // Gap-band penalty — residuals leaving a mid-range unusable gap (25-45) are poor hosts.
        if pr >= next_item_size {
            let gap = pr - next_item_size;
