            }
        }
        // dead-space ratio term — residual the next item cannot use, scaled by stream density.
        if pr > 0 && pr < next_item_size {
            let dead = (next_item_size - pr) as f64;
            let density = remaining as f64 / total_items.max(1) as f64;
            score += dead * (0.20 + 0.40 * density);
        }
        // harvest window — residuals within 2 of the next item close to zero; reward strongly mid/late stream.
        if pr >= next_item_size && pr - next_item_size <= 2 && remaining > 20 {
            score -= 2.5 * (1.0 - (pr - next_item_size) as f64 / 2.0) * (0.6 + 0.8 * progress);
        }
        // wide-gap penalty — residuals leaving 15-30 of dead space after next item, worse with many alternatives.
        if pr > next_item_size {
            let gap = (pr - next_item_size) as f64;
            if gap > 15.0 && gap < 30.0 && fitting_bins_count > 2 {
