    score -= (bin_residual as f64 - mean_residual) * 0.2;

    if frag > mean_residual && frag > 12.0 && remaining > 30 {
        score += (frag - mean_residual) * 0.06;
    }
    if frag > 40.0 && remaining > 60 {
        score += (frag - 40.0) * 0.05;
    }
    if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
        score += (frag - next_item_size as f64) * 0.10;
        if mean_residual < 16.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
    }
    let fill_ratio = item_size as f64 / bin_capacity.max(1) as f64;
    if frag > 0.0 && fill_ratio < 0.42 && remaining > 40 {
        score += (0.42 - fill_ratio) * 16.0 * (1.0 - progress * 0.5);
    }
    if frag > 0.0 && frag > mean_residual * 1.6 && remaining > 30 {
        score += (frag - mean_residual * 1.6) * 0.04;
    }

    score += pr as f64 * (0.1 + 0.22 * progress);

    if pr > 0 && mean_residual > 1.0 {
        let dev = ((pr as f64 - mean_residual) / mean_residual).abs();
        if dev < 0.3 {
            score -= 2.0 * (1.0 - dev / 0.3);
        } else if dev > 1.5 && pr as f64 > mean_residual * 2.0 {
            score += 2.5;
        }
    }
    if pr > 0 && mean_residual > 2.0 && (pr as f64) < mean_residual && (mean_residual - pr as f64) < 6.0 {
        score += (mean_residual - pr as f64) * 0.35;
    }

    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 3.0 } else { 0.0 };
        score += 9.0 + crowding * 6.0 + waste_pressure + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        if item_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        let fresh_left = bin_capacity.saturating_sub(item_size) as f64;
        if remaining > 60 && fresh_left > 0.0 && fresh_left < mean_residual * 1.25 && open_bins_count > 0 {
            score += (mean_residual * 1.25 - fresh_left) * 0.38;
        }
        if fresh_left <= 6.0 && remaining > 30 {
            score -= 4.0;
        }
        if fresh_left > 0.0 && mean_residual > 1.0 && remaining > 40 {
            let d = (fresh_left - mean_residual).abs();
            if d < 4.0 {
                score -= 2.0 * (1.0 - d / 4.0);
            }
        }
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && (next_item_size as f64 - fresh_left) <= 8.0 && remaining > 40 {
            score += (next_item_size as f64 - fresh_left) * 0.5;
        }
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && (next_item_size as f64 - fresh_left) <= 5.0 && remaining > 60 && fitting_bins_count > 1 {
            score += (next_item_size as f64 - fresh_left) * 0.8;
        }
        if next_item_size > 2 && fresh_left > 0.0 && fresh_left % next_item_size as f64 == 0.0 && fresh_left / next_item_size as f64 >= 2.0 && remaining > 60 {
            score -= 2.5;
        }
        if next_item_size > 1 && fresh_left > next_item_size as f64 && ((fresh_left - next_item_size as f64) as u32) % next_item_size == 0 && remaining > 80 {
            score -= 1.2;
        }
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        if fitting_bins_count > 0 {
            score += 4.0;
        }
        if remaining < 8 && fitting_bins_count > 0 {
            score += 5.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 4.0;
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity && remaining > 30 && open_bins_count > 0 && mean_residual >= next_item_size as f64 {
            score += 6.0;
        }
        if next_item_size > 1 && fresh_left >= (next_item_size * 3) as f64 && remaining > 50 {
            score -= 2.0;
        }
        if fresh_left > 0.0 && mean_residual > 4.0 && (fresh_left - mean_residual).abs() <= 3.0 && remaining > 40 && open_bins_count > 2 {
            score -= 1.5 * (1.0 - (fresh_left - mean_residual).abs() / 3.0);
        }
        if fresh_left > 0.0 && mean_residual > 2.0 && fresh_left > mean_residual * 1.8 && remaining > 100 && open_bins_count > 3 {
            score -= 1.5;
        }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 {
            score += 3.0;
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 {
            score += 2.0;
        }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 {
            score -= 3.0;
        }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
        if remaining < 12 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
        if fitting_bins_count > 0 && fresh_left <= 3.0 && item_ratio > 0.9 {
            score -= 5.0;
        }
        // fresh bin whose leftover cannot hold next item while open bins can — discourage opening.
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && mean_residual >= next_item_size as f64 && fitting_bins_count > 0 {
            score += 4.0;
        }
        // fresh leftover far above mean residual mid-stream — likely stranded space, stronger penalty.
        if fresh_left > 0.0 && mean_residual > 2.0 && fresh_left > mean_residual * 2.2 && remaining > 80 && fitting_bins_count > 0 {
            score += (fresh_left - mean_residual * 2.2) * 0.10;
        }
        // MUTATION: fresh-bin exact two-item fit — opening a bin that will hold item + next item exactly is excellent; reward.
        if next_item_size > 0 && fresh_left == next_item_size as f64 && remaining > 20 {
            score -= 5.0;
        }
        // MUTATION: fresh-bin divisibility harvest — leftover divisible by next item into >= 2 slots promises full reuse.
        if next_item_size > 1 && fresh_left > 0.0 && (fresh_left as u32) % next_item_size == 0 && fresh_left / next_item_size as f64 >= 2.0 && remaining > 40 && fitting_bins_count > 0 {
            score -= 3.0;
        }
    } else {
        score += 60.0;
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        if remaining < 35 && next_item_size > 0 && pr == next_item_size {
            score -= 3.0;
        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 6 && fitting_bins_count > 2 {
            score -= 1.5;
        }
        if remaining < 30 && next_item_size > 0 && pr > 0 && pr >= next_item_size && pr - next_item_size <= 3 {
            score -= 2.0 * (1.0 - remaining as f64 / 30.0) * (1.0 - (pr - next_item_size) as f64 / 3.0);
        }
        if next_item_size > 0 && pr > 0 && pr < next_item_size && fitting_bins_count <= 2 && remaining > 40 {
            score += (next_item_size - pr) as f64 * 0.20;
        }
        if remaining >= 35 && remaining < 120 && next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 5 {
            score -= 1.0;
        }
        if remaining < 20 && pr > 0 && mean_residual > 1.0 && ((pr as f64) - mean_residual).abs() < 3.0 {
            score -= 1.5;
        }
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
        if remaining < 50 && next_item_size > 0 && pr > 0 && pr == next_item_size {
            score -= 2.5 * (1.0 - remaining as f64 / 50.0);
        }
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        if next_item_size > 0 && pr > 0 && pr < next_item_size && next_item_size - pr <= 3 && remaining > 80 {
            score += (next_item_size - pr) as f64 * 0.6;
        }
        if next_item_size > 0 && pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        // near-closure harvest — residual within 4 of next item late in stream, reward scaled by closeness.
        if remaining < 70 && next_item_size > 0 && pr > next_item_size && pr - next_item_size <= 4 {
            score -= 1.6 * (1.0 - (pr - next_item_size) as f64 / 4.0) * (1.0 - remaining as f64 / 70.0);
        }
        // MUTATION: many-alternatives exactness — with several fitting bins, strongly prefer the one that zeroes the residual.
        if fitting_bins_count > 2 && pr == 0 && remaining > 10 {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residuals in the "unusable" band
    // (small gaps that few future items can fill) are heavily penalized.
    let dead_low = 1.0f64;
    let dead_high = 10.0f64;
    let pr = post_residual as f64;
    if pr > dead_low && pr < dead_high {
        // Quadratic penalty peaking mid-band
        let t = (pr - dead_low) / (dead_high - dead_low);
        score += 60.0 * (1.0 - (2.0 * t - 1.0).powi(2));
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward tight fits relative to residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the next item would be blocked by a poor leftover.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = (open_bins_count as f64 / 8.0).min(1.5);
        // Penalize opening new bins mildly; escalate with open bin count
        score += 30.0 + 10.0 * pressure;
        // If next item is large, opening a fresh bin now is useful
        if next_item_size >= 50 {
            score -= 15.0;
        }
        // Early stream: prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * (1.0 - progress);
    }

    // Open-bins pressure: with many open bins, favor filling existing ones harder
    score -= 2.0 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Lookahead: penalize leaving a residual that can't host the next item
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward residuals that exactly host the next item
    if next_item_size > 0 && post_residual == next_item_size as u32 {
        score -= 15.0;
    }

    // Mean residual coupling: if this bin's residual deviates favorably (smaller
    // than mean), it's a good consolidation target
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.82;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect match with the NEXT item (2-step lookahead).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Exact match: next item exactly fills this bin afterwards.
        if post_residual == next_item_size {
            score -= 500.0;
        } else if diff <= 10.0 {
            score -= 120.0 - 8.0 * diff;
        } else {
            // Penalize leaving residual that is too small for the next item (dead space),
            // scaled by how "wasted" the leftover is.
            if post_residual < next_item_size {
                score += (next_item_size - post_residual) as f64 * 1.5;
            } else {
                // Residual bigger than next item: partial reward, decaying with gap.
                score -= (60.0 / (1.0 + (diff - 10.0) * 0.15)).max(0.0);
            }
        }
        // Bonus if the bin can also fit the next item now (chaining potential).
        if post_residual >= next_item_size && post_residual > 0 {
            score -= 15.0;
        }
    } else {
        // Last item: strongly prefer minimal leftover.
        score += (post_residual as f64).powi(2) * 0.05;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
        // Extra reward for tight fits in last-chance situations.
        let tightness = (item_size as f64) / (bin_residual as f64);
        score -= 40.0 * tightness;
    }

    // Penalize creating very small unusable residuals (dead space < typical min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Prefer bins whose residual is below the mean (tighter bins first),
    // keeping looser bins available for larger future items.
    if bin_residual < bin_capacity {
        let rel = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
        score += rel * 30.0;
    }

    // New-bin candidate handling: make opening a new bin mildly unattractive by default,
    // so it is chosen only when no open bin offers a decent fit (e.g., all residuals small).
    if bin_residual == bin_capacity {
        // Base penalty grows with number of open bins (encourage consolidation).
        score += 25.0 + 2.0 * open_bins_count as f64;
        // But if the item is large relative to typical residual and no good fits exist,
        // the lookahead rewards above (absent here) make open bins win; if mean residual
        // cannot accommodate the next item well, allow new bin more readily.
        if next_item_size > 0 && mean_residual < next_item_size as f64 && post_residual >= next_item_size {
            score -= 70.0;
        }
    }

    // Mild progression term: early in the stream, be slightly more conservative about
    // fragmenting bins; later, prioritize closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
