pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize small post_residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize large dead space unless it can host the next item (lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Bin remains usable by the lookahead item: reward.
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space that the next item cannot use: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.35 * waste;
        }
    } else {
        // Last item: strongly prefer filling existing space.
        score -= 10.0 * tightness;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is large relative to residual or open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowd = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let pressure = item_size as f64 / bin_capacity as f64;
        // New bins attractive for big items late in the stream or when bins are full-ish.
        let attract = 12.0 * pressure * (0.4 + 0.6 * progress) + 0.05 * crowd;
        score += 25.0 - attract;
    }

    // Mild preference for bins whose residual deviates from the mean (consolidate similar bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Slight time-decay: early on, be a bit greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (1.0 - progress) * 3.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
