pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Smooth non-linear coupling: weight on post_residual grows with progress
    let coupling = 1.0 + 2.0 * progress * progress + 1.5 * progress * (1.0 - progress);
    score *= coupling;

    // Penalize dead space quadratically, scaled by capacity
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 20.0 * dead * dead * (1.0 + progress);

    // Reward tight fits (small post_residual) with smooth exponential bonus
    score -= 15.0 * (-dead * 6.0).exp() * (1.0 + progress);

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits in post_residual
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        let slack = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 10.0 * (1.0 - slack) * (0.5 + progress);
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * (0.25 + 0.5 * progress);

    // Deviation from mean residual: prefer bins near the mean (balanced usage)
    let dev = (bin_residual as f64 - mean_residual).abs() / bin_capacity as f64;
    score += 8.0 * dev * dev * (1.0 - progress);

    score
