        // Widened endgame exact-closure — late stream, prefer fits that zero the residual.
        if remaining < 50 && next_item_size > 0 && pr > 0 && pr == next_item_size {
            score -= 2.5 * (1.0 - remaining as f64 / 50.0);
        }
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        // Two-step exact closure — residual fits item then next item exactly.
        if next_item_size > 0 && pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        // Mid-stream residual that holds next item twice exactly — strong host.
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.0;
        }
        // MUTATION: endgame waste-closure — late stream, prefer residuals that close within a small margin of mean residual.
        if remaining < 45 && pr > 0 && mean_residual > 1.0 && (pr as f64) > mean_residual && (pr as f64) - mean_residual <= 4.0 {
            score -= 1.2 * (1.0 - remaining as f64 / 45.0) * (1.0 - ((pr as f64) - mean_residual) / 4.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but reward perfect closure strongly.
    if post_residual == 0 {
        score -= 500.0; // perfect fit, close the bin
    } else if post_residual < 10 {
        score -= 200.0; // near-perfect: dead space below min item size
    } else {
        // Harmonic class penalty: dead space classified by modulo classes of capacity.
        let r = post_residual % 10;
        // Residuals in "awkward" classes (1..9 mod 10) are harder to fill.
        let class_penalty = match r {
            0 => -20.0,          // multiple of 10: many item sizes can pair with it
            1 | 9 => 30.0,
            2 | 8 => 25.0,
            3 | 7 => 20.0,
            4 | 6 => 15.0,
            _ => 10.0,           // r == 5
        };
        score += class_penalty as f64;
    }

    // Integer-division threshold: residuals that can hold the lookahead item are valuable.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 40.0; // keeps a home for the next item: strong reward
            // Extra reward if lookahead exactly fills the post-residual (harmonic closure k=2).
            if post_residual == next_item_size {
                score -= 120.0;
            } else if (post_residual - next_item_size) < 10 {
                score -= 60.0; // two-item cascade nearly closes the bin
            }
        } else {
            score += 25.0; // lookahead won't fit here: dead space risk
        }
    } else {
        // Last item of stream: any bin is fine, prefer smallest post-residual.
        score -= 100.0;
    }

    // Last-chance bin: if this is the only fitting bin, opening a new bin wastes it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin has full residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly.
        // Penalize moderately so tight existing fits win, but keep it competitive
        // when open bins are fragmented (high mean residual spread).
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 60.0 - 0.3 * open_bins_count as f64 + 0.2 * fragmentation;
        // Early in stream, fresh bins are cheaper to open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
    }

    // Mild preference to spread load when many bins are open and this bin is above-average residual.
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
