pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (<10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Medium dead space (10..=25) is moderately penalized since few future items fit.
    if post_residual >= 10 && post_residual <= 25 {
        score += 8.0;
    }

    // Reward exact / very tight fits.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bins pressure: discourage spreading across many bins; mild term.
    score += 0.15 * open_bins_count as f64;

    // Prefer bins below the mean residual (tighter bins) to keep large residuals intact.
    score += 0.1 * (mean_residual - bin_residual as f64);

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 3.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // would leave a large residual in an existing bin or few bins can fit it.
    if bin_residual == bin_capacity {
        let pressure = (post_residual as f64 / bin_capacity as f64) * 10.0;
        score = 20.0 + pressure
            - 10.0 * (fitting_bins_count as f64).recip().min(1.0)
            + 0.2 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
