        }
        // Scarcity-aware waste — near-miss residuals with few alternatives are costly late.
        if next_item_size > 0 && pr > 0 && pr < next_item_size && fitting_bins_count <= 2 && remaining > 40 {
            score += (next_item_size - pr) as f64 * 0.20;
        }
        // Mid-stream near-closure window.
        if remaining >= 35 && remaining < 120 && next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 5 {
            score -= 1.0;
        }
        // Endgame mean-residual alignment.
        if remaining < 20 && pr > 0 && mean_residual > 1.0 && ((pr as f64) - mean_residual).abs() < 3.0 {
            score -= 1.5;
        }
        // Many alternatives and residual leaves more dead space than mean: deprioritize.
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
        // Widened endgame exact-closure — late stream, prefer fits that zero the residual.
        if remaining < 50 && next_item_size > 0 && pr > 0 && pr == next_item_size {
            score -= 2.5 * (1.0 - remaining as f64 / 50.0);
        }
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        // Two-step exact closure — residual fits item then next item exactly.
        if next_item_size > 0 && pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        // mid-stream residual that holds next item twice exactly — strong host.
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but weight by stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score = post_residual as f64 * (1.0 + 0.5 * progress);

    // Two-step lookahead: perfect match of post_residual with next item is gold.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if post_residual as f64 == nxt {
            score -= 40.0; // exact 2-chain fit
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - diff / cap); // next item still fits here
        } else {
            // next item won't fit: dead space unless post_residual is tiny
            score += 0.3 * post_residual as f64;
            if post_residual < 10 {
                score -= 5.0; // negligible sliver, fine to strand
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more when many bins fit the item.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        score += 30.0 + 5.0 * open_f.min(10.0);
        if fitting_bins_count > 0 {
            score += 20.0; // existing bins can take it; don't open
        }
        // Opening is OK if mean residual is large (existing bins are fragmented)
        if mean_residual > 0.4 * cap {
            score -= 15.0;
        }
    }

    // Favor bins whose residual is already below mean (consolidate fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    score
}

