pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tightness reward: strongly favor small post-residual (non-linear).
    let tightness = post / cap;
    score += tightness * tightness * 40.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Last chance bin: strong bonus to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as u64 == next_item_size as u64 {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (nx / cap);
        } else {
            // next item won't fit here; penalize large dead space slightly more
            score += 8.0 * tightness;
        }
    }

    // Relative-to-mean residual: prefer bins tighter than average.
    if mean_residual > 0.0 {
        let rel = (bin_residual as f64) / mean_residual;
        score += (rel - 1.0) * 10.0;
    }

    // Time horizon: early in stream, be more willing to use new bins / spread load.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost, reduced early, increased late.
        let mut new_bin = 45.0 - 25.0 * (1.0 - progress);
        // discourage new bin if many open bins already and item fits elsewhere
        new_bin += open_bins_count as f64 * 2.0;
        // if item is large, opening fresh bin is attractive
        new_bin -= (item_size as f64 / cap) * 20.0;
        // if next item is huge and this bin would be nearly emptied, prefer new bin
        if next_item_size > 0 && (next_item_size as u32) > post_residual {
            new_bin -= 10.0;
        }
        score = new_bin;
    }

    // Many open bins: mild pressure to consolidate into existing bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
