        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.0;
        }
        // MUTATION (combined feature): fine-grained fit — residual that exactly fits item+next with scarcity boost.
        if next_item_size > 0 && pr == item_size + next_item_size && fitting_bins_count <= 3 {
            score -= 2.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 3.0 * progress) - norm_pr * (1.0 - progress);

    // Reward tight fits (small post residual), more strongly later in the stream
    let mut score = pr * (1.0 + 0.8 * progress) + 12.0 * poly * cap * 0.01;

    // Penalize bins that are much worse than the mean residual
    score += 0.15 * (pr - mean_residual).max(0.0);

    // Reward last-chance bins (avoid opening a new bin when only one fits)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 + 10.0 * progress;
    }

    // Lookahead: favor bins whose post residual can still host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 4.0 * (post_residual - next_item_size) as f64 / cap;
        } else {
            score += 2.0;
        }
    }

    // Mild penalty for opening a new bin when other bins fit
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 6.0 - 4.0 * progress;
    }

    score
}

