        if pr > 0 && pr < next_item_size && next_item_size - pr > next_item_size / 2 && fitting_bins_count > 3 && remaining > 50 {
            score += (next_item_size - pr) as f64 * 0.30;
        }
        if next_item_size > 1 && pr >= item_size + next_item_size {
            let rest = pr - item_size - next_item_size;
            if rest >= next_item_size && rest - next_item_size <= 4 && remaining > 25 {
                score -= 2.2 * (1.0 - (rest - next_item_size) as f64 / 4.0);
            }
        }
        if pr > 0 && pr >= next_item_size {
            let rem_after = pr - next_item_size;
            if rem_after > 0 && (rem_after as f64 - mean_residual).abs() <= 2.0 && remaining > 20 {
                score -= 1.8 * (1.0 - (rem_after as f64 - mean_residual).abs() / 2.0);
            }
        }
        if pr > 0 && mean_residual > 3.0 && (pr as f64) < mean_residual * 0.80 && remaining > 60 {
            score += (mean_residual * 0.80 - pr as f64) * (0.18 + 0.14 * progress);
        }
        if pr > next_item_size && (pr - next_item_size) > 0 && (pr - next_item_size) < 14 && fitting_bins_count > 1 {
            let dead2 = (pr - next_item_size) as f64;
            score += dead2 * 0.10 * (1.0 - dead2 / 14.0);
        }
        if pr > next_item_size && (pr - next_item_size) * 2 <= pr {
            score -= 1.2;
        }
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 {
                score += (gap as f64 - 25.0) * 0.08;
            }
        }
        if pr == next_item_size && fitting_bins_count <= 2 {
            score -= 4.0;
        }
        if frag > 0.0 && frag < next_item_size as f64 {
            let dead = next_item_size as f64 - frag;
            if dead > 6.0 && fitting_bins_count > 1 {
                score += dead * 0.12;
            }
        }
        // dead-space ratio term — residual the next item cannot use, scaled by stream density.
        if pr > 0 && pr < next_item_size {
            let dead = (next_item_size - pr) as f64;
            let density = remaining as f64 / total_items.max(1) as f64;
            score += dead * (0.20 + 0.40 * density);
        }
        // harvest window — residuals within 2 of the next item close to zero; reward strongly mid/late stream.
        if pr >= next_item_size && pr - next_item_size <= 2 && remaining > 20 {
            score -= 2.5 * (1.0 - (pr - next_item_size) as f64 / 2.0) * (0.6 + 0.8 * progress);
        }
        // wide-gap penalty — residuals leaving 15-30 of dead space after next item, worse with many alternatives.
        if pr > next_item_size {
            let gap = (pr - next_item_size) as f64;
            if gap > 15.0 && gap < 30.0 && fitting_bins_count > 2 {
                score += (gap - 15.0) * 0.10;
            }
        }
        // MUTATION: exact-fill lookahead — residual exactly fits item + next item chains, strong reward.
        if next_item_size > 1 && pr > 0 && pr >= item_size + next_item_size && pr % next_item_size == 0 {
            score -= 2.0;
        }
        // MUTATION: near-miss stranding penalty scaled by stream density — residual just below next item strands space.
        if pr > 0 && pr < next_item_size && next_item_size - pr <= 4 {
            let density = remaining as f64 / total_items.max(1) as f64;
            score += (next_item_size - pr) as f64 * (0.30 + 0.35 * density);
        }
    }

    score += open_bins_count as f64 * 0.3;

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    score -= (bin_residual as f64 - mean_residual) * 0.2;

    if frag > mean_residual && frag > 12.0 && remaining > 30 {
        score += (frag - mean_residual) * 0.06;
    }
    if frag > 40.0 && remaining > 60 {
        score += (frag - 40.0) * 0.05;
    }
    if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
        score += (frag - next_item_size as f64) * 0.10;
        if mean_residual < 16.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
    }
    let fill_ratio = item_size as f64 / bin_capacity.max(1) as f64;
    if frag > 0.0 && fill_ratio < 0.42 && remaining > 40 {
        score += (0.42 - fill_ratio) * 16.0 * (1.0 - progress * 0.5);
    }
    if frag > 0.0 && frag > mean_residual * 1.6 && remaining > 30 {
        score += (frag - mean_residual * 1.6) * 0.04;
    }

    score += pr as f64 * (0.1 + 0.22 * progress);

    if pr > 0 && mean_residual > 1.0 {
        let dev = ((pr as f64 - mean_residual) / mean_residual).abs();
        if dev < 0.3 {
            score -= 2.0 * (1.0 - dev / 0.3);
        } else if dev > 1.5 && pr as f64 > mean_residual * 2.0 {
            score += 2.5;
        }
    }
    if pr > 0 && mean_residual > 2.0 && (pr as f64) < mean_residual && (mean_residual - pr as f64) < 6.0 {
        score += (mean_residual - pr as f64) * 0.35;
    }

    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 10.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 - waste_pressure + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        if item_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        let fresh_left = bin_capacity.saturating_sub(item_size) as f64;
        if remaining > 60 && fresh_left > 0.0 && fresh_left < mean_residual * 1.25 && open_bins_count > 0 {
            score += (mean_residual * 1.25 - fresh_left) * 0.38;
        }
        if fresh_left <= 6.0 && remaining > 30 {
            score -= 4.0;
        }
        if fresh_left > 0.0 && mean_residual > 1.0 && remaining > 40 {
            let d = (fresh_left - mean_residual).abs();
            if d < 4.0 {
                score -= 2.0 * (1.0 - d / 4.0);
            }
        }
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && (next_item_size as f64 - fresh_left) <= 8.0 && remaining > 40 {
            score += (next_item_size as f64 - fresh_left) * 0.5;
        }
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && (next_item_size as f64 - fresh_left) <= 5.0 && remaining > 60 && fitting_bins_count > 1 {
            score += (next_item_size as f64 - fresh_left) * 0.8;
        }
        if next_item_size > 2 && fresh_left > 0.0 && fresh_left % next_item_size as f64 == 0.0 && fresh_left / next_item_size as f64 >= 2.0 && remaining > 60 {
            score -= 2.5;
        }
        if next_item_size > 1 && fresh_left > next_item_size as f64 && ((fresh_left - next_item_size as f64) as u32) % next_item_size == 0 && remaining > 80 {
            score -= 1.2;
        }
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        if fitting_bins_count > 0 {
            score += 4.0;
        }
        if remaining < 8 && fitting_bins_count > 0 {
            score += 5.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 4.0;
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity && remaining > 30 && open_bins_count > 0 && mean_residual >= next_item_size as f64 {
            score += 6.0;
        }
        if next_item_size > 1 && fresh_left >= (next_item_size * 3) as f64 && remaining > 50 {
            score -= 2.0;
        }
        if fresh_left > 0.0 && mean_residual > 4.0 && (fresh_left - mean_residual).abs() <= 3.0 && remaining > 40 && open_bins_count > 2 {
            score -= 1.5 * (1.0 - (fresh_left - mean_residual).abs() / 3.0);
        }
        if fresh_left > 0.0 && mean_residual > 2.0 && fresh_left > mean_residual * 1.8 && remaining > 100 && open_bins_count > 3 {
            score -= 1.5;
        }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 {
            score += 3.0;
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 {
            score += 2.0;
        }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 {
            score -= 3.0;
        }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
        if remaining < 12 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
        if fitting_bins_count > 0 && fresh_left <= 3.0 && item_ratio > 0.9 {
            score -= 5.0;
        }
        // fresh bin whose leftover cannot hold next item while open bins can — discourage opening.
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && mean_residual >= next_item_size as f64 && fitting_bins_count > 0 {
            score += 4.0;
        }
        // fresh leftover far above mean residual mid-stream — likely stranded space, stronger penalty.
        if fresh_left > 0.0 && mean_residual > 2.0 && fresh_left > mean_residual * 2.2 && remaining > 80 && fitting_bins_count > 0 {
            score += (fresh_left - mean_residual * 2.2) * 0.10;
        }
        // MUTATION: fresh-bin mean-alignment — leftover matching stream mean residual promises reuse; reward mildly.
        if fresh_left > 0.0 && mean_residual > 4.0 && (fresh_left - mean_residual).abs() <= 3.0 && remaining > 40 && open_bins_count > 2 {
            score -= 1.0 * (1.0 - (fresh_left - mean_residual).abs() / 3.0);
        }
    } else {
        score += 60.0;
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        if remaining < 35 && next_item_size > 0 && pr == next_item_size {
            score -= 3.0;
        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 6 && fitting_bins_count > 2 {
            score -= 1.5;
        }
        if remaining < 30 && next_item_size > 0 && pr > 0 && pr >= next_item_size && pr - next_item_size <= 3 {
            score -= 2.0 * (1.0 - remaining as f64 / 30.0) * (1.0 - (pr - next_item_size) as f64 / 3.0);
        }
        if next_item_size > 0 && pr > 0 && pr < next_item_size && fitting_bins_count <= 2 && remaining > 40 {
            score += (next_item_size - pr) as f64 * 0.20;
        }
        if remaining >= 35 && remaining < 120 && next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 5 {
            score -= 1.0;
        }
        if remaining < 20 && pr > 0 && mean_residual > 1.0 && ((pr as f64) - mean_residual).abs() < 3.0 {
            score -= 1.5;
        }
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
        if remaining < 50 && next_item_size > 0 && pr > 0 && pr == next_item_size {
            score -= 2.5 * (1.0 - remaining as f64 / 50.0);
        }
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        if next_item_size > 0 && pr > 0 && pr < next_item_size && next_item_size - pr <= 3 && remaining > 80 {
            score += (next_item_size - pr) as f64 * 0.6;
        }
        if next_item_size > 0 && pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        // near-closure harvest — residual within 4 of next item late in stream, reward scaled by closeness.
        if remaining < 70 && next_item_size > 0 && pr > next_item_size && pr - next_item_size <= 4 {
            score -= 1.6 * (1.0 - (pr - next_item_size) as f64 / 4.0) * (1.0 - remaining as f64 / 70.0);
        }
        // MUTATION: endgame two-item closure — late stream, residuals fitting next item plus small margin close out soon.
        if remaining < 30 && next_item_size > 0 && pr > 0 && pr >= next_item_size && pr - next_item_size <= 4 {
            score -= 1.2 * (1.0 - remaining as f64 / 30.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: which quarter of capacity it occupies
    let item_class = item_size / 25; // 0..3
    let next_class = (next_item_size as u32) / 25;

    // Perfect-fit harmonic residue classes: post_residual in {0, 10, 20, 25, 50}
    // are reusable "harmonic slots" for common item sizes.
    let harmonic_slot = match post_residual {
        0 => 3.0,
        10 | 20 => 2.0,
        25 | 50 => 1.5,
        _ => 0.0,
    };
    score -= harmonic_slot * 6.0;

    // Penalize dead space: post_residual too small for the smallest item (1)
    // but too awkward for typical classes (1..10 dead zone).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Reward coupling: if next item fits harmonically into post_residual,
    // strongly favor this bin (chained packing).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = post_residual as f64 - next_item_size as f64;
        score -= (10.0 - (chain % 10.0)) * 1.5 + 8.0;
        // bonus if next item lands in same harmonic class slot
        if next_item_size % 10 == 0 {
            score -= 5.0;
        }
    } else if next_item_size > 0 {
        score += 4.0;
    }

    // Last-chance bin: strongly reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New empty bin candidate: penalize mildly so it's chosen only for
    // poor fits into open bins, but reward it for large items (class 3)
    // where fresh capacity is valuable.
    if bin_residual == bin_capacity {
        score += 8.0;
        if item_class == 3 {
            score -= 10.0;
        }
    }

    // Tight fit reward: item fills most of the residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 5.0;

    // Small modulo harmonic: prefer post_residual divisible by common sizes
    if post_residual % 20 == 0 {
        score -= 2.0;
    }

    // Stream progression: early on, be greedy with tight fits; late,
    // consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * progress * 0.5;
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0 * (20.0 - post_residual as f64) / 10.0;
    } else if post_residual == 0 {
        // perfect fit: strong reward
        score -= 80.0;
    } else if post_residual >= 90 {
        // large residual means item was small; mildly penalize wasting big bins
        score += 5.0;
    }

    // Reward filling bins tightly relative to capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill_ratio;

    // Lookahead: if next item fits in the post residual, reward leaving that gap
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
        // even better if next item exactly consumes it
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else if next_item_size > 0 && post_residual > 0 {
        // gap too small for next item: penalize proportionally
        score += 10.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: discourage proliferation of open bins unless needed
    score += 2.0 * open_bins_count as f64;

    // Prefer bins with residual below mean (use up the emptier bins first)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: opening a fresh bin is reasonable when the
    // item is large and no open bin fits well, but penalize it mildly so it
    // only wins when open-bin placements are bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size >= 50 {
            score -= 20.0;
        }
        // late in stream, opening new bins is fine
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), but scale by fill ratio
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score *= 1.0 + 0.5 * fill_ratio;

    // Aggressive 2-step lookahead: exact match of post_residual with next item is gold
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // perfect chain: next item exactly fills this bin
        } else if post_residual > next_item_size {
            // next item still fits after this one: mild reward proportional to closeness
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot use the leftover: penalize dead space
            let dead = post_residual as f64;
            score += 0.3 * dead;
            // extra penalty if next item would have fit in residual before placement
            if bin_residual >= next_item_size && post_residual < next_item_size {
                score += 8.0;
            }
        }
    } else {
        // last item: just minimize post_residual hard
        score -= 20.0;
    }

    // Compare against mean residual: placing into a below-average-residual bin
    // (tighter bin) preserves loose bins for future awkward items
    if (post_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current item is large
    // (small waste risk) or no good fit exists; otherwise discourage opening bins
    if bin_residual == bin_capacity {
        if item_size >= 50 || fitting_bins_count == 0 {
            score -= 10.0 + 20.0 * fill_ratio;
        } else {
            score += 30.0;
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.02 * open_bins_count as f64;

    // Slight stream-position adaptation: early on, be a bit more liberal with new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;
    let frag = pr as f64 - item_size as f64;

    // Dead-space avoidance: small unusable gaps are heavily penalized.
    if pr > 0 && pr < 10 {
        score += 55.0;
    } else if pr < 25 {
        score += 22.0 * (1.0 - pr as f64 / 25.0);
    }

    // Reward near-perfect fills (widened exact-closure band).
    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 42.0;
    } else if pr <= 8 {
        score -= 16.0;
    } else if pr <= 12 {
        score -= 10.0;
    } else if pr <= 15 {
        score -= 4.0;
    } else if pr <= 25 {
        score -= 1.0;
    } else if pr <= 40 {
        score += 4.0;
    } else if pr <= 60 {
        score += 8.0;
    } else {
        score += 12.0;
    }

    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size > pr {
            let dead = (next_item_size - pr) as f64;
            let density = remaining as f64 / total_items.max(1) as f64;
            let scarcity = if fitting_bins_count <= 2 { 1.25 } else { 1.0 };
            score += pr as f64 * 0.5 + dead * (0.25 + 0.55 * density) * scarcity;
            // MUTATION: variance-aware near-miss — residual just below next item wastes a nearly full slot; escalate late.
            if pr > 0 && mean_residual > 2.0 && (next_item_size as f64 - pr as f64) <= mean_residual * 0.7 && remaining > 50 {
                score += (next_item_size as f64 - pr as f64) * (0.35 + 0.25 * progress);
            }
        } else {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 {
                score -= 5.0;
            }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 45.0 {
                score += (slack - 45.0) * 0.05;
            }
        }
        // Two-item lookahead: next item fits twice more.
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        // Chain-friendliness: residual divisible by next size.
