        }
        // Fresh bin with mean residual well below its leftover: likely stranded space.
        if fresh_left > 0.0 && mean_residual > 2.0 && fresh_left > mean_residual * 1.8 && remaining > 100 && open_bins_count > 3 {
            score -= 1.5;
        }
        // Small next item with open bins able to host it — discourage opening a fresh bin.
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 {
