        }
        // MUTATION v141: fresh-bin near-miss with long horizon — leftover just under next item
        // strands space for a long time; escalate mildly.
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && remaining > 120 {
