        // Fresh-bin double-slot divisibility — leftover holds exactly two next-items with zero slack.
        if next_item_size > 1 && fresh_left == (next_item_size * 2) as f64 && remaining > 40 {
            score -= 2.2 * (1.0 - remaining as f64 / total_items.max(1) as f64);
        }
        // Fresh-bin waste-pressure coupling — low mean residual makes opening cheaper; resist otherwise.
        if mean_residual < 18.0 && remaining > 60 && open_bins_count > 0 && fitting_bins_count > 0 {
            score += 2.0;
        }
        // MUTATION (gen141): fresh-bin leftover that misses next item by a large margin while mean residual is small — strong stranding signal.
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && (next_item_size as f64 - fresh_left) > 8.0 && mean_residual < 10.0 && remaining > 60 && fitting_bins_count > 0 {
            score += (next_item_size as f64 - fresh_left) * 0.30;
