        // MUTATION (gen141): fresh-bin leftover exceeding two next-items plus mean band — likely reusable multi-slot host.
        if next_item_size > 1 && fresh_left >= (next_item_size * 2) as f64 && (fresh_left - (next_item_size * 2) as f64) <= mean_residual * 0.5 && remaining > 50 {
