        if next_item_size > 0 && pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        // Mid-stream residual that holds next item twice exactly — strong host.
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.0;
        }
        // Endgame waste-closure — late stream, prefer residuals closing within a small margin of mean residual.
        if remaining < 45 && pr > 0 && mean_residual > 1.0 && (pr as f64) > mean_residual && (pr as f64) - mean_residual <= 4.0 {
            score -= 1.2 * (1.0 - remaining as f64 / 45.0) * (1.0 - ((pr as f64) - mean_residual) / 4.0);
        }
        // MUTATION (gen141): endgame near-closure widened — residual that fits next item plus a remainder within the mean band, scaled by scarcity.
        if remaining < 60 && next_item_size > 0 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 <= mean_residual * 0.6 && fitting_bins_count <= 3 {
            score -= 1.0 * (1.0 - remaining as f64 / 60.0) * (1.0 - (pr - next_item_size) as f64 / (mean_residual * 0.6 + 1.0));
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
