        if next_item_size > 0 && fresh_left == next_item_size as f64 && remaining > 30 {
            score -= 3.0;
        }
        // MUTATION v141: fresh-bin double-slot divisibility — leftover holds exactly two next-items
        // with zero slack is a near-perfect opening; reward scaled by stream progress.
        if next_item_size > 1 && fresh_left == (next_item_size * 2) as f64 && remaining > 40 {
