        }
        // MUTATION v141: mean residual high with long horizon — fresh bin more likely to be reused.
        if mean_residual > 30.0 && remaining > 100 {
            score -= 2.0;
        }
        // MUTATION v142: fresh-bin exact-triple opening — leftover holds exactly three next-items
        // with zero slack is an excellent long-horizon opening.
        if next_item_size > 1 && fresh_left == (next_item_size * 3) as f64 && remaining > 60 {
            score -= 1.8;
        }
    } else {
        score += 60.0;
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        // Endgame: strong bonus for exact-closure residuals.
        if remaining < 35 && next_item_size > 0 && pr == next_item_size {
            score -= 3.0;
        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 6 && fitting_bins_count > 2 {
