            score -= 1.5;
        }
        // Many alternatives and residual leaves more dead space than mean: deprioritize.
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
        // Widened endgame exact-closure — late stream, prefer fits that zero the residual.
        if remaining < 50 && next_item_size > 0 && pr > 0 && pr == next_item_size {
            score -= 2.5 * (1.0 - remaining as f64 / 50.0);
        }
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        // Two-step exact closure — residual fits item then next item exactly.
        if next_item_size > 0 && pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        // MUTATION: mid-stream residual that holds next item twice exactly — strong host.
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.0;
        }
        // MUTATION v142: scarcity-aware triple closure — residual that holds next item three times
        // exactly with few alternatives is a near-perfect multi-fit host.
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 3 && fitting_bins_count <= 3 && remaining > 40 {
            score -= 1.8;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = item_size as f64 / cap;

    // Base: prefer minimal post residual (tight packing)
    let mut score = post;

    // Reward tight fits more strongly as stream progresses (smooth polynomial coupling)
    let tightness = 1.0 - (post / cap);
    let progress_coupling = progress * (1.0 + progress);
    score -= 18.0 * tightness * tightness * progress_coupling;

    // Penalize large dead space, weighted by mean residual context
    if post > 0.0 {
        let dead = (post / cap) * (post / cap);
        score += 12.0 * dead * (1.0 - progress);
    }

    // Lookahead: if next item fits exactly into post_residual, reward this bin
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual as u32 {
            let nxt = next_item_size as f64 / cap;
            score -= 10.0 * nxt * (1.0 + progress);
        } else {
            // penalize leaving residual that likely becomes dead space
            let gap = (next_item_size as f64 - post) / cap;
            score += 6.0 * gap * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + progress);
    }

    // Mild penalty for spreading across many open bins early
    score += 0.5 * (open_bins_count as f64).sqrt() * (1.0 - progress);

    // New-bin candidate handling: slightly discourage opening new bins unless residuals are poor
    if bin_residual == bin_capacity {
        score += 8.0 + 5.0 * (1.0 - progress) - 10.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via squared post-residual normalized by capacity.
    let frac = post_residual as f64 / bin_capacity as f64;
    score = 40.0 * frac * frac + 0.35 * post_residual as f64;

    // Harmonic class of post_residual: dead space in low classes is worse.
    let class = post_residual / 10; // integer division: 0..10
    match class {
        0 => score -= 18.0,                       // perfect/near-perfect fit
        1 => score -= 9.0,                        // leaves room for tiny items
        2 => score += 4.0,                        // awkward dead zone
        3 => score += 8.0,                        // very awkward (30-39 dead)
        4 => score -= 2.0,                        // fits a mid item
        5 => score -= 3.0,                        // half bin: flexible
        _ => {}                                   // large residual: generally fine
    }

    // Modulo-5 harmony: residual divisible by 5 pairs better with typical sizes.
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: reward residuals that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 6.0 - 0.06 * slack as f64;
            if post_residual == next_item_size {
                score -= 10.0; // next item closes this bin perfectly
            }
        } else {
            // Next item cannot fit here anyway; slight penalty for stranding.
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early in stream, new bins are cheaper; late, prefer consolidation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * (1.0 - progress);
        // If many open bins have big mean residual, prefer reusing them.
        score += 0.15 * mean_residual;
    }

    // Slight preference for filling fuller bins when many bins are open.
    score += 0.02 * open_bins_count as f64 * frac;

    score
}

