        // Two-item lookahead: next item fits twice more.
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        // Chain-friendliness: residual divisible by next size.
        if pr > 0 && pr >= next_item_size && pr % next_item_size == 0 && pr / next_item_size >= 2 && remaining > 50 {
            score -= 2.0 * ((pr / next_item_size) as f64).min(3.0);
        }
        // Near-closure: leftover within 1-2 of next item size.
        if pr >= next_item_size && pr - next_item_size <= 1 {
            score -= 3.0;
        }
        // Penalize residual just below next item (guaranteed dead space).
        if frag > 0.0 && frag < next_item_size as f64 && next_item_size as f64 - frag <= 4.0 {
            score += (next_item_size as f64 - frag) * 0.9;
        }
        // Reward frag just above next item size (near-closure after next fit).
        if frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        // Multi-fit lookahead: repeated next-items with tiny remainder.
        if next_item_size > 1 && pr > 0 && pr >= next_item_size && pr / next_item_size >= 2 && pr % next_item_size <= 2 && remaining > 30 {
            score -= 1.6 * ((pr / next_item_size) as f64).min(4.0);
        }
        // Chained-divisibility bonus, stronger when bins are scarce.
        if next_item_size > 1 && pr > 0 && pr >= next_item_size {
            let rem_after = pr - next_item_size;
            if rem_after > 0 && rem_after % next_item_size == 0 && rem_after / next_item_size >= 2 && fitting_bins_count <= 3 && remaining > 60 {
                score -= 1.4 * ((rem_after / next_item_size) as f64).min(4.0);
