        }
        // MUTATION v145: dead-space ratio lookahead — residual that cannot hold next item twice within its own size wastes a slot; penalize proportionally to horizon.
        if next_item_size > 1 && pr > 0 && pr < next_item_size && (next_item_size as f64) > pr as f64 && remaining > 30 {
            let waste_ratio = (next_item_size - pr) as f64 / next_item_size as f64;
            if waste_ratio > 0.5 {
