        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer exact / near-exact fits (low dead space).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * tightness * tightness;

    // 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        // Perfect chain: next item fills this bin exactly.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving residual too small for the next item (dead space trap).
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Relative to mean residual: prefer bins already below average residual
    // (tighter bins get filled first, keeping loose bins flexible).
    score -= 10.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 35.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Late in the stream, avoid opening bins that waste capacity.
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 10.0;
        }
    }

    score
}

