        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 6 && fitting_bins_count > 2 {
            score -= 1.5;
        }
        if remaining < 30 && next_item_size > 0 && pr > 0 && pr >= next_item_size && pr - next_item_size <= 3 {
            score -= 2.0 * (1.0 - remaining as f64 / 30.0) * (1.0 - (pr - next_item_size) as f64 / 3.0);
        }
        if next_item_size > 0 && pr > 0 && pr < next_item_size && fitting_bins_count <= 2 && remaining > 40 {
            score += (next_item_size - pr) as f64 * 0.20;
        }
        if remaining >= 35 && remaining < 120 && next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 5 {
            score -= 1.0;
        }
        if remaining < 20 && pr > 0 && mean_residual > 1.0 && ((pr as f64) - mean_residual).abs() < 3.0 {
            score -= 1.5;
        }
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
        if remaining < 50 && next_item_size > 0 && pr > 0 && pr == next_item_size {
            score -= 2.5 * (1.0 - remaining as f64 / 50.0);
        }
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        if next_item_size > 0 && pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linear).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize very small dead space (waste of capacity that nothing small may use).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 3.0;
        }
        // Perfect chain: this fit plus next fit nearly fills bin.
        if post_residual >= next_item_size && post_residual as i64 - next_item_size as i64 <= 5 {
            score -= 6.0;
        }
    } else {
        // Last item: prefer fullest packing.
        score -= 10.0 * fit_ratio;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing bins.
    score += 0.4 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins tighter than average.
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: only attractive when nothing fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = fit_ratio < 0.5;
        if poor_fit && fitting_bins_count <= 2 {
            score -= 4.0 + 6.0 * progress;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress and residual ratios
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let res_ratio = post_residual as f64 / cap;           // 0..1 after placement
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64; // tightness of fit

    // Reward tight fits: small post_residual relative to bin size, amplified smoothly
    score -= (1.0 - res_ratio).powi(2) * cap * 0.6;

    // Non-linear progress coupling: as stream advances, prefer tighter packing more strongly
    score -= progress * (1.0 - res_ratio).powi(3) * cap * 0.8;

    // Penalize very large leftover dead space (hard to reuse), smooth cubic penalty
    score += res_ratio.powi(3) * cap * 0.35;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= cap * 1.5;
    } else if fitting_bins_count > 0 {
        score -= (fitting_bins_count as f64).recip() * cap * 0.2;
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let snug = 1.0 - ((post_residual as f64 - next_item_size as f64) / cap);
        score -= snug * cap * (0.3 + 0.4 * progress);
    } else if next_item_size > 0 {
        // post_residual cannot host next item: mild penalty scaled by how close it was
        score += 0.25 * cap * (1.0 - (next_item_size as f64 - post_residual as f64) / cap).max(0.0);
    }

    // Mean-residual coupling: if this bin's residual deviates favorably from the mean,
    // prefer it (reduces fragmentation spread); smooth quadratic term
    let dev = post_residual as f64 - mean_residual;
    score += (dev / cap).powi(2) * cap * 0.15;

    // Many open bins: slight pressure to consolidate into existing bins vs opening new ones
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // New-bin candidate: make an empty bin attractive only when the fit is poor elsewhere
    if bin_residual == bin_capacity {
        score += cap * 0.9 + 0.5 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
