        // Scarcity-aware waste — near-miss residuals with few alternatives are costly late.
        if next_item_size > 0 && pr > 0 && pr < next_item_size && fitting_bins_count <= 2 && remaining > 40 {
            score += (next_item_size - pr) as f64 * 0.20;
        }
        // Mid-stream near-closure window.
        if remaining >= 35 && remaining < 120 && next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 5 {
            score -= 1.0;
        }
        // Endgame mean-residual alignment.
        if remaining < 20 && pr > 0 && mean_residual > 1.0 && ((pr as f64) - mean_residual).abs() < 3.0 {
            score -= 1.5;
        }
        // Many alternatives and residual leaves more dead space than mean: deprioritize.
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
        // Widened endgame exact-closure — late stream, prefer fits that zero the residual.
        if remaining < 50 && next_item_size > 0 && pr > 0 && pr == next_item_size {
            score -= 2.5 * (1.0 - remaining as f64 / 50.0);
        }
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        // Two-step exact closure — residual fits item then next item exactly.
        if next_item_size > 0 && pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        // Mid-stream residual that holds next item twice exactly — strong host.
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.0;
        }
        // Endgame waste-closure.
        if remaining < 45 && pr > 0 && mean_residual > 1.0 && (pr as f64) > mean_residual && (pr as f64) - mean_residual <= 4.0 {
            score -= 1.2 * (1.0 - remaining as f64 / 45.0) * (1.0 - ((pr as f64) - mean_residual) / 4.0);
        }
        // MUTATION (gen147): density-weighted host preference — when many bins fit the item,
        // prefer the one whose remainder after this item best matches the mean residual band,
        // reducing variance of leftover space across the fleet.
        if fitting_bins_count > 3 && pr > 0 && mean_residual > 1.0 && remaining > 30 {
            let dev = ((pr as f64 - mean_residual) / (mean_residual + 2.0)).abs();
            score += dev * 1.2 * (1.0 - progress * 0.5);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of post_residual: partition dead space into capacity fractions ---
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap; // 0..1

    // Class boundaries: perfect fit (<=10), small remainder (<=25), medium (<=50), large (>50)
    if post_residual == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 25 {
        score -= 15.0;
    } else if post_residual <= 50 {
        score += 10.0;
    } else {
        score += 25.0; // wasteful, leaves room for a new bin to be preferred
    }

    // --- Modulo / integer-division harmonic classes ---
    // Residuals divisible by small harmonics (4, 5, 10) tend to admit future items
    // drawn from typical size lattices; reward them slightly.
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    } else if post_residual % 4 == 0 {
        score -= 1.5;
    }

    // Integer-division tier: post_residual / 10 gives coarse harmonic band (0..10)
    let tier = post_residual / 10;
    score += (tier as f64) * 1.2;

    // --- Lookahead coupling: harmonic class of next_item_size vs post_residual ---
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if next_item_size <= post_residual {
            // next item could fit here too: reward tight chains
            let ratio = n / post;
            score -= 12.0 * (1.0 - ratio); // prefer chains where next item nearly fills remainder
            if next_item_size % 10 == 0 {
                score -= 4.0; // round-size next item chains well
            }
        } else {
            // next item cannot use this remainder: penalize proportionally to its size class
            let n_tier = next_item_size / 20; // 0..5 harmonic class
            score += 3.0 + (n_tier as f64) * 2.0;
        }
        // If next item is large and this bin would be nearly empty after, defer to new bin
        if next_item_size >= 60 && frac > 0.4 {
            score += 8.0;
        }
    } else {
        // last item: minimize residual strictly
        score = post;
    }

    // --- Last-chance bonus: only this bin fits, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // --- Stream progression: early on, be conservative about dead space; late, pack greedily ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - frac); // late stream: favor filling open bins well

    // --- New-bin candidate calibration: empty bin gets a moderate default ---
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive only if the best existing residual would be badly fragmented
        score = 55.0 + frac * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative, must open
        }
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 10.0; // next item is big relative to mean residual; fresh bin helps
        }
    }

    // --- Mean residual coupling: keep residuals balanced across open bins ---
    let dev = (post - mean_residual).abs();
    score += 0.05 * dev;

    score
}

