        }
        // MUTATION: fresh-bin lookahead — opening is worse when next item cannot share the fresh residual AND open bins could host it later.
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && remaining > 80 && mean_residual < fresh_left {
