        }
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
        if remaining < 50 && next_item_size > 0 && pr > 0 && pr == next_item_size {
            score -= 2.5 * (1.0 - remaining as f64 / 50.0);
        }
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        if next_item_size > 0 && pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.0;
        }
        if remaining < 45 && pr > 0 && mean_residual > 1.0 && (pr as f64) > mean_residual && (pr as f64) - mean_residual <= 4.0 {
            score -= 1.2 * (1.0 - remaining as f64 / 45.0) * (1.0 - ((pr as f64) - mean_residual) / 4.0);
        }
        // MUTATION: endgame fine-grained closure — residual within one unit of next item is nearly exact.
        if remaining < 60 && next_item_size > 0 && pr > 0 && pr >= next_item_size && pr - next_item_size == 1 {
            score -= 1.6 * (1.0 - remaining as f64 / 60.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 200.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 40.0;

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // (make the empty-bin candidate expensive) and encourage consolidation.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 + open_bins_count as f64 * 15.0 + progress * 60.0;
    } else {
        score += open_bins_count as f64 * 2.0;
    }

    // Lookahead: if the next item fits the post-residual exactly, reward it.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 120.0;
        } else if next_item_size > post_residual && post_residual > 0 {
            // post-residual too small for next item: penalize if it's dead space.
            if post_residual < 10 {
                score += 30.0;
            }
        } else {
            // next item fits, but leaves another gap
            let next_gap = post_residual - next_item_size;
            if next_gap > 0 && next_gap < 10 {
                score += next_gap as f64 * 10.0;
            } else {
                score -= 20.0;
            }
        }
    }

    // Mild alignment with mean residual state: prefer bins near the mean
    // to keep residual distribution balanced.
    score += ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
