pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual matches the next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item can also fit here afterwards
            score -= 120.0 - diff * 0.8;
        } else {
            // next item would not fit; penalize tight leftovers that waste capacity
            score += diff * 0.6;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average when many bins are open
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mean_gap = mean_residual - post_residual as f64;
    score -= mean_gap * (0.3 + 0.5 * progress);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the current item is large
    // and no open bin gives a good fit (post_residual small dead space elsewhere).
    if bin_residual == bin_capacity {
        score += 80.0
            + 0.5 * (bin_capacity as f64 - item_size as f64)
            - 60.0 * (fitting_bins_count as f64).min(3.0);
    }

    // Mild preference for filling fuller bins
    score += 0.1 * (bin_residual as f64 - post_residual as f64).max(0.0).signum() * 0.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that can't be filled by typical future items
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 18.0 * dead * dead;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to gap
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Time horizon: early in stream, encourage consolidation into few bins;
    // late in stream, allow opening new bins for tight fits
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate handling: penalize opening new bin unless current fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > (bin_capacity as f64 * 0.5);
        if poor_fit {
            score += 30.0;
        } else {
            score += 12.0 * (1.0 - progress);
        }
    }

    // Global residual pressure: if mean residual is large, prefer filling bins with big residuals
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 6.0 * (bin_residual as f64 / mean_residual.max(1.0)).ln().abs();

    // Slight preference for bins with larger residual (best-fit vs worst-fit blend)
    score -= 10.0 * (bin_residual as f64 / bin_capacity as f64);

    // Open bins count pressure: many open bins -> prefer existing bins
    score += 2.0 * open_bins_count as f64 * (1.0 - tightness);

    // Small noise-free deterministic tie-breaker based on residual parity structure
    score += (post_residual % 7) as f64 * 0.1;

    score
}

