        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 {
            score += 2.0;
        }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 {
            score -= 3.0;
        }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
        if remaining < 12 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
        if fitting_bins_count > 0 && fresh_left <= 3.0 && item_ratio > 0.9 {
            score -= 5.0;
        }
        if next_item_size > 0 && fresh_left == next_item_size as f64 && remaining > 30 {
            score -= 3.0;
        }
        if next_item_size > 1 && fresh_left == (next_item_size * 2) as f64 && remaining > 40 {
            score -= 2.2 * (1.0 - remaining as f64 / total_items.max(1) as f64);
        }
        if mean_residual > 30.0 && remaining > 100 {
            score -= 2.0;
        }
        if next_item_size > 1 && fresh_left == (next_item_size * 3) as f64 && remaining > 60 {
            score -= 1.8;
        }
        // MUTATION v149: fresh-bin dead-space guard — opening a bin whose leftover sits just below
        // the mean residual band strands that space; penalize when many bins are already open.
        if fresh_left > 0.0 && mean_residual > 4.0 && fresh_left < mean_residual * 0.85 && open_bins_count > 2 && remaining > 60 {
            score += (mean_residual * 0.85 - fresh_left) * 0.25;
        }
    } else {
        score += 60.0;
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        if remaining < 35 && next_item_size > 0 && pr == next_item_size {
            score -= 3.0;
        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 6 && fitting_bins_count > 2 {
            score -= 1.5;
        }
        if remaining < 30 && next_item_size > 0 && pr > 0 && pr >= next_item_size && pr - next_item_size <= 3 {
            score -= 2.0 * (1.0 - remaining as f64 / 30.0) * (1.0 - (pr - next_item_size) as f64 / 3.0);
        }
        if next_item_size > 0 && pr > 0 && pr < next_item_size && fitting_bins_count <= 2 && remaining > 40 {
            score += (next_item_size - pr) as f64 * 0.20;
        }
        if remaining >= 35 && remaining < 120 && next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 5 {
            score -= 1.0;
        }
        if remaining < 20 && pr > 0 && mean_residual > 1.0 && ((pr as f64) - mean_residual).abs() < 3.0 {
            score -= 1.5;
        }
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
        if remaining < 50 && next_item_size > 0 && pr > 0 && pr == next_item_size {
            score -= 2.5 * (1.0 - remaining as f64 / 50.0);
        }
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        if next_item_size > 0 && pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.0;
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 3 && fitting_bins_count <= 3 && remaining > 40 {
            score -= 1.8;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: post residual, with smooth non-linear polynomial coupling to stream progress.
    // Early on, prefer tight fits (minimize post_residual strongly); later, allow larger residuals.
    let base = pr * (1.0 + 0.6 * progress * progress);

    // Smooth convex penalty on wasted fraction of capacity (dead space), amplified by progress.
    let waste = 0.9 * fit_norm * fit_norm * cap * (0.5 + 0.5 * progress);

    // Perfect-ish fit reward (smooth kernel around small residuals).
    let tight_reward = -18.0 * (-fit_norm * 12.0).exp();

    // Lookahead: reward if next item fits into post residual (smooth coupling).
    let nis = next_item_size as f64;
    if nis > 0.0 {
        let fits_next = ((pr - nis).max(0.0)) as f64;
        let next_fit_bonus = -6.0 * (1.0 - fits_next / cap) * (1.0 - (pr - nis).abs() as f64 / cap).max(0.0);
        // penalize if next item barely doesn't fit (near miss)
        let near_miss = if pr < nis { 8.0 * (1.0 - (nis - pr) / cap) } else { 0.0 };
        base + waste + tight_reward + next_fit_bonus + near_miss
    } else {
        base + waste + tight_reward
    }
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;
    let frag = pr as f64 - item_size as f64;

    // Dead-space avoidance: small gaps are heavily penalized.
    if pr > 0 && pr < 10 {
        score += 55.0;
    } else if pr < 25 {
        score += 22.0 * (1.0 - pr as f64 / 25.0);
    }

    // Reward near-perfect fills (widened exact-closure band).
    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 42.0;
    } else if pr <= 8 {
        score -= 16.0;
    } else if pr <= 12 {
        score -= 10.0;
    } else if pr <= 15 {
        score -= 4.0;
    } else if pr <= 25 {
        score -= 1.0;
    } else if pr <= 40 {
        score += 4.0;
    } else if pr <= 60 {
        score += 8.0;
    } else {
        score += 12.0;
    }

    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size > pr {
            let dead = (next_item_size - pr) as f64;
            let density = remaining as f64 / total_items.max(1) as f64;
            let scarcity = if fitting_bins_count <= 2 { 1.25 } else { 1.0 };
            score += pr as f64 * 0.5 + dead * (0.25 + 0.55 * density) * scarcity;
        } else {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 {
                score -= 5.0;
            }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 45.0 {
                score += (slack - 45.0) * 0.05;
            }
        }
        // Two-item lookahead: next item fits twice more.
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        // Chain-friendliness: residual divisible by next size.
        if pr > 0 && pr >= next_item_size && pr % next_item_size == 0 && pr / next_item_size >= 2 && remaining > 50 {
            score -= 2.0 * ((pr / next_item_size) as f64).min(3.0);
        }
        // Near-closure: leftover within 1-2 of next item size.
        if pr >= next_item_size && pr - next_item_size <= 1 {
            score -= 3.0;
        }
        // Penalize residual just below next item (guaranteed dead space).
        if frag > 0.0 && frag < next_item_size as f64 && next_item_size as f64 - frag <= 4.0 {
            score += (next_item_size as f64 - frag) * 0.9;
        }
        // Reward frag just above next item size (near-closure after next fit).
        if frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        // Multi-fit lookahead: repeated next-items with tiny remainder.
        if next_item_size > 1 && pr > 0 && pr >= next_item_size && pr / next_item_size >= 2 && pr % next_item_size <= 2 && remaining > 30 {
            score -= 1.6 * ((pr / next_item_size) as f64).min(4.0);
        }
        // Chained-divisibility bonus, stronger when bins are scarce.
        if next_item_size > 1 && pr > 0 && pr >= next_item_size {
            let rem_after = pr - next_item_size;
            if rem_after > 0 && rem_after % next_item_size == 0 && rem_after / next_item_size >= 2 && fitting_bins_count <= 3 && remaining > 60 {
                score -= 1.4 * ((rem_after / next_item_size) as f64).min(4.0);
            }
        }
        // Residual just below next item, mid-stream, with many alternatives — near-miss waste.
        if pr > 0 && pr < next_item_size && next_item_size - pr <= 6 && remaining > 30 && fitting_bins_count > 2 {
            score += (next_item_size - pr) as f64 * 0.45 * (1.0 - (next_item_size - pr) as f64 / 6.0);
        }
        // Large-dead-space avoidance when many alternatives exist.
        if pr > 0 && pr < next_item_size && next_item_size - pr > next_item_size / 2 && fitting_bins_count > 3 && remaining > 50 {
            score += (next_item_size - pr) as f64 * 0.30;
        }
        // Two-step closure — residual fits next item then a second one almost exactly.
        if next_item_size > 1 && pr >= item_size + next_item_size {
            let rest = pr - item_size - next_item_size;
            if rest >= next_item_size && rest - next_item_size <= 4 && remaining > 25 {
                score -= 2.2 * (1.0 - (rest - next_item_size) as f64 / 4.0);
            }
        }
        // Dead-space budget — remainder after one next-item slot matching the mean residual band.
        if pr > 0 && pr >= next_item_size {
            let rem_after = pr - next_item_size;
            if rem_after > 0 && (rem_after as f64 - mean_residual).abs() <= 2.0 && remaining > 20 {
                score -= 1.8 * (1.0 - (rem_after as f64 - mean_residual).abs() / 2.0);
            }
        }
        // Stranding risk coupling: residual well below mean residual mid-stream.
        if pr > 0 && mean_residual > 3.0 && (pr as f64) < mean_residual * 0.80 && remaining > 60 {
            score += (mean_residual * 0.80 - pr as f64) * (0.18 + 0.14 * progress);
        }
        // Residual barely above next item with many alternatives: mild waste signal.
        if pr > next_item_size && (pr - next_item_size) > 0 && (pr - next_item_size) < 14 && fitting_bins_count > 1 {
            let dead2 = (pr - next_item_size) as f64;
            score += dead2 * 0.10 * (1.0 - dead2 / 14.0);
        }
        // Next item fits and leaves room at least twice its size: good host.
        if pr > next_item_size && (pr - next_item_size) * 2 <= pr {
            score -= 1.2;
        }
        // MUTATION: gap-band penalty — residuals leaving a mid-range unusable gap (25-45) are poor hosts.
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 {
                score += (gap as f64 - 25.0) * 0.08;
            }
        }
        // MUTATION: exact-match with few alternatives — strong preference for the unique host.
        if pr == next_item_size && fitting_bins_count <= 2 {
            score -= 4.0;
        }
        // MUTATION: frag dead-space window with alternatives — small unusable remainder after next item.
        if frag > 0.0 && frag < next_item_size as f64 {
            let dead = next_item_size as f64 - frag;
            if dead > 6.0 && fitting_bins_count > 1 {
                score += dead * 0.12;
            }
        }
        // MUTATION: near-miss residual just below next item, long horizon — waste signal.
        if pr > 0 && pr < next_item_size && next_item_size - pr <= 3 && remaining > 80 {
            score += (next_item_size - pr) as f64 * 0.6;
        }
        // MUTATION v141: variance-aware near-miss — tight residual clusters make a post-residual
        // just below next_item waste a nearly full slot; escalate late.
        if pr > 0 && pr < next_item_size && mean_residual > 2.0 && (next_item_size as f64 - pr as f64) <= mean_residual * 0.7 && remaining > 50 {
            score += (next_item_size as f64 - pr as f64) * (0.35 + 0.25 * progress);
        }
        // MUTATION v141: half-capacity pairing — residual that holds next item plus a remainder
        // sized to the mean-residual band promises a second clean fit.
        if next_item_size > 1 && pr >= next_item_size * 2 {
            let rem_after = pr - next_item_size;
            if rem_after >= next_item_size && (rem_after - next_item_size) as f64 <= mean_residual * 0.5 && remaining > 40 {
                score -= 1.1 * (1.0 - (rem_after - next_item_size) as f64 / (mean_residual * 0.5 + 1.0)) * (0.6 + 0.6 * progress);
            }
        }
        // MUTATION v142: exact double-slot host — residual holding exactly two next-items with
        // zero slack is a perfect chain; reward scaled by remaining stream length.
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.4 * (1.0 - remaining as f64 / total_items.max(1) as f64);
        }
        // MUTATION v142: scarcity-escalated near-miss — residual just below next item with very
        // few fitting alternatives strands a nearly-full slot; penalize harder when scarce.
        if pr > 0 && pr < next_item_size && fitting_bins_count <= 2 && remaining > 40 {
            score += (next_item_size - pr) as f64 * 0.20;
        }
        // MUTATION v146: dead-space ratio coupling — penalize residuals whose unusable fraction
        // of next-item space exceeds half, scaled by stream density; reward exact multi-slot hosts.
        if pr > 0 && pr < next_item_size {
            let dead = (next_item_size - pr) as f64;
            if dead * 2 > next_item_size as f64 && remaining > 25 {
                score += dead * (0.10 + 0.20 * progress);
            }
        }
        // MUTATION v146: exact triple-slot host with long horizon — perfect chain of three.
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 3 && remaining > 60 {
            score -= 1.6;
        }
        // MUTATION v146: remainder-after-next near-mean — leftover after one next-item close to
        // the mean residual promises reuse by an average item; reward mildly, progress-scaled.
        if next_item_size > 1 && pr > next_item_size {
            let rem_after = (pr - next_item_size) as f64;
            if mean_residual > 2.0 && (rem_after - mean_residual).abs() <= 1.5 && remaining > 35 {
                score -= 1.3 * (1.0 - (rem_after - mean_residual).abs() / 1.5) * (0.5 + 0.5 * progress);
            }
        }
        // MUTATION v149: waste-fraction term — residual that next item cannot use at all, scaled
        // by stream density; direct dead-space ratio coupling to reduce stranded capacity.
        if pr > 0 && pr < next_item_size {
            let dead = (next_item_size - pr) as f64;
            let density = remaining as f64 / total_items.max(1) as f64;
            score += dead * (0.15 + 0.35 * density);
        }
        // MUTATION v149: zero-slack multi-slot host — post-residual holding exactly two next-items
        // with few alternatives is a guaranteed chain; stronger than the generic bonus.
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && fitting_bins_count <= 3 && remaining > 30 {
            score -= 1.5;
        }
    }

    // Open-bin pressure: prefer tighter packing when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Slight bias toward bins with larger residuals (better long-term hosts).
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Fragments larger than mean residual waste capacity going forward.
    if frag > mean_residual && frag > 12.0 && remaining > 30 {
        score += (frag - mean_residual) * 0.06;
    }
    // Very large fragments waste even more.
    if frag > 40.0 && remaining > 60 {
        score += (frag - 40.0) * 0.05;
    }
    // MUTATION: frag trapped between one and two next-items — dead space signal.
    if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
        score += (frag - next_item_size as f64) * 0.10;
        if mean_residual < 16.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
    }
    // Small-item fragmentation guard: small items in big holes waste future capacity.
    let fill_ratio = item_size as f64 / bin_capacity.max(1) as f64;
    if frag > 0.0 && fill_ratio < 0.42 && remaining > 40 {
        score += (0.42 - fill_ratio) * 16.0 * (1.0 - progress * 0.5);
    }
    // MUTATION: extra waste term for fragments far above mean residual.
    if frag > 0.0 && frag > mean_residual * 1.6 && remaining > 30 {
        score += (frag - mean_residual * 1.6) * 0.04;
    }

    // Late in the stream, tighten packing further.
    score += pr as f64 * (0.1 + 0.22 * progress);

    // Residual close to mean residual is a good host for future items.
    if pr > 0 && mean_residual > 1.0 {
        let dev = ((pr as f64 - mean_residual) / mean_residual).abs();
        if dev < 0.3 {
            score -= 2.0 * (1.0 - dev / 0.3);
        } else if dev > 1.5 && pr as f64 > mean_residual * 2.0 {
            score += 2.5;
        }
    }
    // MUTATION: residual just under mean residual — stranding risk when mean need is close.
    if pr > 0 && mean_residual > 2.0 && (pr as f64) < mean_residual && (mean_residual - pr as f64) < 6.0 {
        score += (mean_residual - pr as f64) * 0.35;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 4.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 + waste_pressure + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        // Large items: better to start a fresh bin than fragment a good one.
        if item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        if item_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        // Fresh bin leaves a large usable residual matching mean need.
        let fresh_left = bin_capacity.saturating_sub(item_size) as f64;
        if remaining > 60 && fresh_left > 0.0 && fresh_left < mean_residual * 1.25 && open_bins_count > 0 {
            score += (mean_residual * 1.25 - fresh_left) * 0.38;
        }
        if fresh_left <= 6.0 && remaining > 30 {
            score -= 4.0;
        }
        // Fresh leftover near mean residual is chain-friendly.
        if fresh_left > 0.0 && mean_residual > 1.0 && remaining > 40 {
            let d = (fresh_left - mean_residual).abs();
            if d < 4.0 {
                score -= 2.0 * (1.0 - d / 4.0);
            }
        }
        // Discourage fresh bin when leftover sits just under next item (dead space).
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && (next_item_size as f64 - fresh_left) <= 8.0 && remaining > 40 {
            score += (next_item_size as f64 - fresh_left) * 0.5;
        }
        // Fresh-bin near-miss guard, stronger with alternatives available.
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && (next_item_size as f64 - fresh_left) <= 5.0 && remaining > 60 && fitting_bins_count > 1 {
            score += (next_item_size as f64 - fresh_left) * 0.8;
        }
        // Reward fresh bin when leftover is an exact multiple of next size.
        if next_item_size > 2 && fresh_left > 0.0 && fresh_left % next_item_size as f64 == 0.0 && fresh_left / next_item_size as f64 >= 2.0 && remaining > 60 {
            score -= 2.5;
        }
        // Chained-divisibility refinement for fresh bins.
        if next_item_size > 1 && fresh_left > next_item_size as f64 && ((fresh_left - next_item_size as f64) as u32) % next_item_size == 0 && remaining > 80 {
            score -= 1.2;
        }
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        if fitting_bins_count > 0 {
            score += 4.0;
        }
        if remaining < 8 && fitting_bins_count > 0 {
            score += 5.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 4.0;
        }
        // Next item won't fit alongside this item in a fresh bin — penalty for opening.
        if next_item_size > 0 && item_size + next_item_size > bin_capacity && remaining > 30 && open_bins_count > 0 && mean_residual >= next_item_size as f64 {
            score += 6.0;
        }
        // Fresh-bin multi-fit lookahead.
        if next_item_size > 1 && fresh_left >= (next_item_size * 3) as f64 && remaining > 50 {
            score -= 2.0;
        }
        // Fresh-bin mean-alignment bonus.
        if fresh_left > 0.0 && mean_residual > 4.0 && (fresh_left - mean_residual).abs() <= 3.0 && remaining > 40 && open_bins_count > 2 {
            score -= 1.5 * (1.0 - (fresh_left - mean_residual).abs() / 3.0);
        }
        // Fresh bin with mean residual well below its leftover: likely stranded space.
        if fresh_left > 0.0 && mean_residual > 2.0 && fresh_left > mean_residual * 1.8 && remaining > 100 && open_bins_count > 3 {
            score -= 1.5;
        }
        // Small next item with open bins able to host it — discourage opening a fresh bin.
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 {
            score += 3.0;
        }
        // Mean residual near next item with alternatives — reuse beats opening.
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 {
            score += 2.0;
        }
        // Large item, mean residual too small for it — fresh bin may be the only sane host.
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 {
            score -= 3.0;
        }
        // Mean residual just above next item size — fresh leftover will be reused soon.
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
        // Endgame — strong bias against opening bins when alternatives exist.
        if remaining < 12 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
        if fitting_bins_count > 0 && fresh_left <= 3.0 && item_ratio > 0.9 {
            score -= 5.0;
        }
        // MUTATION: fresh bin whose leftover exactly matches next item is a good opening.
        if next_item_size > 0 && fresh_left == next_item_size as f64 && remaining > 30 {
            score -= 3.0;
        }
