pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;
    let class = pr % 10; // decade harmonic class

    // Reward residuals that are "harmonically useful": multiples matching
    // common item sizes (10..80 in decades) leave clean slots.
    if class == 0 {
        score -= 25.0; // exact decade fit -> very reusable
    } else if class <= 2 {
        score -= 8.0;  // near-decade, small dead space
    } else if class >= 8 {
        score += 12.0; // awkward sliver, penalize
    }

    // Integer-division threshold: how many "typical" items still fit
    let slots = pr / 20; // coarse slot count
    score -= slots as f64 * 6.0;

    // Capacity-fraction coupling: residual as fraction of capacity
    let frac = post_residual as f64 / cap;
    score += (frac - 0.5) * 20.0; // prefer leaving ~half or less

    // Lookahead harmonic: does next_item_size divide cleanly into post_residual?
    if next_item_size > 0 && next_item_size <= pr {
        let rem = pr % next_item_size;
        if rem == 0 {
            score -= 30.0; // perfect pair packing
        } else if rem < 5 {
            score -= 12.0;
        }
    } else if next_item_size > pr {
        score += 15.0; // next item can't use this bin's leftover
    }

    // Last-chance bin: strongly favor using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64;
        // penalize new bins mildly; less penalty late in stream / crowded
        score += 45.0 - 15.0 * progress - 2.0 * crowd.min(20.0);
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing else fits -> new bin is right
        }
    }

    // Mean-residual alignment: bins far from mean residual get a nudge
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Prefer tighter fits overall
    score += (item_size as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // minimum item (1..=10) are unusable "dead space" -> heavy penalty.
    if post_residual >= 1 && post_residual <= 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }
    // Small-but-marginal gaps (11..=20): only usable by tiny items, mildly risky.
    else if post_residual > 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Reward very tight fits (post_residual near zero but still usable).
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    } else if post_residual <= 5 {
        score -= 6.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // this placement chains nicely -> reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual > next_item_size {
            score -= 3.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // next item cannot use the leftover: dead space confirmed
            score += 6.0 + (post_residual as f64).min(10.0);
        }
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly favor
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins; penalize opening new bins when pressure is high.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 / (1.0 + 10.0 * (1.0 - progress + 0.05));
    if bin_residual == bin_capacity {
        // New-bin candidate: acceptable early or when open bins are mostly full,
        // otherwise penalized under pressure.
        score += 10.0 + 25.0 * pressure;
        // A new bin is attractive if no open bin fits well (large mean residual
        // spread means fragmentation).
        if (mean_residual - post_residual as f64).abs() < 1.0 {
            score -= 5.0;
        }
    } else {
        score -= 2.0 * pressure.min(8.0);
    }

    // Prefer bins whose residual is below average (fill the emptier-than-mean
    // bins less; favor bins tighter than average to consolidate).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    score
}

