        if remaining >= 35 && remaining < 120 && next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 5 {
            score -= 1.0;
        }
        // Endgame mean-residual alignment.
        if remaining < 20 && pr > 0 && mean_residual > 1.0 && ((pr as f64) - mean_residual).abs() < 3.0 {
            score -= 1.5;
        }
        // Many alternatives and residual leaves more dead space than mean: deprioritize.
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
        // Widened endgame exact-closure — late stream, prefer fits that zero the residual.
        if remaining < 50 && next_item_size > 0 && pr > 0 && pr == next_item_size {
            score -= 2.5 * (1.0 - remaining as f64 / 50.0);
        }
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        // Two-step exact closure — residual fits item then next item exactly.
        if next_item_size > 0 && pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        // Mid-stream residual that holds next item twice exactly — strong host.
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.0;
        }
        // Scarcity-aware triple closure — residual that holds next item three times
        // exactly with few alternatives is a near-perfect multi-fit host.
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 3 && fitting_bins_count <= 3 && remaining > 40 {
            score -= 1.8;
        }
        // Mid-stream zero-slack exact closure — any post-residual that exactly
        // equals next item size is a guaranteed clean fit; reward scaled by horizon.
        if next_item_size > 0 && pr > 0 && pr == next_item_size && remaining >= 50 {
            score -= 1.2;
        }
        // Near-closure escalation — residual within 2 of next item size mid-stream
        // with many alternatives is a near-perfect host; reward scaled by alternatives.
        if remaining >= 50 && next_item_size > 0 && pr > next_item_size && pr - next_item_size <= 2 && fitting_bins_count > 3 {
            score -= 1.0 + 0.5 * progress;
        }
        // MUTATION v150: density-escalated near-closure — residual within 3 of next item
        // with dense remaining stream is a high-value host; reward scaled by density.
        if remaining > 120 && next_item_size > 0 && pr > next_item_size && pr - next_item_size <= 3 && fitting_bins_count > 2 {
            score -= 0.8 * density;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 * (1.0 - diff / bin_capacity as f64);
        // Perfect lookahead fit: strong reward
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving a post_residual that nothing small can use later
        if post_residual > 0 && post_residual < 10 {
            score += 30.0;
        }
    } else {
        // Last item: just minimize waste
        score += 0.0;
    }

    // Prefer bins tighter than the mean (good fills), penalize loose bins
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current residuals are all poor fits
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * mean_residual;
        // But if lookahead would perfectly fill a fresh bin, allow opening
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 30.0;
        }
    }

    // Slight preference for compacting many items into fewer bins over time
    score += 0.05 * open_bins_count as f64;

    // Penalize dead space quadratically
    score += 0.05 * (post_residual as f64).powi(2) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on wasted space.
    score += (post_residual as f64 / cap).powi(3) * 30.0;

    // Exact fit is heavily favored.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead-space penalty: residuals too small to hold even the smallest item are useless.
    if post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward this bin;
    // if the post-residual cannot hold the next item, penalize leaving that gap.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            score -= 40.0;
        } else if (post_residual as f64) < nxt && post_residual > 0 {
            score += 10.0;
        }
        // Reward leaving room for a large next item.
        score += (nxt / cap) * (post_residual as f64 - nxt).max(0.0) * 0.5;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
        let mean_tightness = 1.0 - (mean_residual / cap);
        let poor_fit = if post_residual < 15 { 1.0 } else { 0.0 };
        score += 20.0 * (1.0 - crowding) + 15.0 * (1.0 - mean_tightness) - 35.0 * poor_fit;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    }

    // Mild preference for fuller bins among open candidates.
    score -= (bin_residual as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
