        }
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
        if remaining < 50 && next_item_size > 0 && pr > 0 && pr == next_item_size {
            score -= 2.5 * (1.0 - remaining as f64 / 50.0);
        }
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        if next_item_size > 0 && pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.0;
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 3 && fitting_bins_count <= 3 && remaining > 40 {
            score -= 1.8;
        }
        // MUTATION v150: endgame combined closure — late stream, reward residuals that hold
        // next item plus a remainder within the mean-residual band (one more clean fit).
        if remaining < 45 && next_item_size > 0 && pr > next_item_size {
            let rem_after = pr - next_item_size;
            if rem_after > 0 && (rem_after as f64) <= mean_residual.max(1.0) {
                score -= 1.6 * (1.0 - remaining as f64 / 45.0);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let nx = next_item_size as f64;

    // Base: penalize wasted residual, quadratically scaled.
    let mut score = pr / cap;

    // Tightness reward: fraction of residual consumed by this item.
    let fill_ratio = if br > 0.0 { it / br } else { 0.0 };
    score -= 1.5 * fill_ratio * fill_ratio;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, moderate leftovers are fine; late in the stream, demand tighter packing.
    let late_pressure = progress * progress;
    score += late_pressure * (pr / cap) * (pr / cap) * 4.0;

    // Dead-space penalty: residuals too small for the smallest plausible item (<= ~10)
    // are worthless; smooth bump around the small-residual region.
    let dead = ((10.0 - pr) / 10.0).max(0.0);
    score += 0.8 * dead * dead;

    // Lookahead synergy: if next item fits in the post-residual, reward strongly.
    if nx > 0.0 && nx <= pr {
        let snug = 1.0 - (pr - nx) / cap;
        score -= 1.2 * snug;
    } else if nx > 0.0 {
        // Next item won't fit here: mild penalty proportional to how far off it is.
        score += 0.4 * ((nx - pr) / cap);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 2.0;
    }

    // Crowding: with many open bins, prefer consolidating into existing ones.
    score -= 0.15 * (open_bins_count as f64).ln().max(0.0);

    // Mean-residual coupling: if this bin's post-residual deviates high above the
    // mean residual, it's leaving scattered capacity; penalize smoothly.
    let dev = (pr - mean_residual) / cap;
    score += 0.3 * dev * dev;

    // New-bin candidate: it always has maximal post-residual, so the quadratic
    // residual terms already penalize it; add a small extra hysteresis that
    // weakens late in the stream (when closing out bins matters more).
    if bin_residual == bin_capacity {
        score += 0.5 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
