        if remaining < 50 && next_item_size > 0 && pr > 0 && pr == next_item_size {
            score -= 2.5 * (1.0 - remaining as f64 / 50.0);
        }
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        if next_item_size > 0 && pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.0;
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 3 && fitting_bins_count <= 3 && remaining > 40 {
            score -= 1.8;
        }
        // Endgame combined closure — late stream, reward residuals that hold the next item
        // plus a remainder within the mean-residual band (one more clean fit).
        if remaining < 45 && next_item_size > 0 && pr > next_item_size {
            let rem_after = pr - next_item_size;
            if rem_after > 0 && (rem_after as f64) <= mean_residual.max(1.0) {
                score -= 1.6 * (1.0 - remaining as f64 / 45.0);
            }
        }
        // MUTATION v151: endgame mean-band closure — very late stream, residuals within a
        // tight band of the mean residual are the most likely to be exactly closed by an
        // upcoming item; reward escalating as the stream drains.
        if remaining < 25 && pr > 0 && mean_residual > 1.0 {
            let d = ((pr as f64) - mean_residual).abs();
            if d <= 2.0 {
                score -= 2.2 * (1.0 - remaining as f64 / 25.0) * (1.0 - d / 2.0);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;
    let frag = pr as f64 - item_size as f64;

    // Dead-space ratio core: fraction of post-residual unusable by next item.
    if next_item_size > 0 && pr > 0 {
        if pr < next_item_size {
            let dead_ratio = (next_item_size - pr) as f64 / next_item_size as f64;
            let density = remaining as f64 / total_items.max(1) as f64;
            let scarcity = if fitting_bins_count <= 2 { 1.3 } else { 1.0 };
            score += dead_ratio * (next_item_size as f64) * (0.22 + 0.5 * density) * scarcity;
        } else {
            let usable_ratio = (pr - next_item_size) as f64 / pr as f64;
            // Reward hosts whose remainder is a large fraction of the residual (low dead ratio).
            if usable_ratio > 0.5 {
                score -= 1.5 * (usable_ratio - 0.5) * (1.0 + progress);
            }
