pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: capacity fractions
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Reward near-perfect fits strongly (waste classes: 0, tiny, quarter, half)
    if post_residual == 0 {
        score -= 1000.0; // perfect closure
    } else if post_residual <= 3 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    } else if post_residual == bin_capacity / 2 {
        score -= 60.0; // half-capacity residual is reusable
    } else if post_residual == bin_capacity / 4 {
        score -= 40.0;
    } else {
        // penalize dead-space classes: post_residual too small for typical items (min size 10)
        if post_residual < 10 {
            score += 150.0;
        }
        // modulo arithmetic: residuals divisible by small harmonics are more reusable
        if post_residual % 10 == 0 {
            score -= 25.0;
        }
        if post_residual % 5 == 0 {
            score -= 10.0;
        }
        // fractional penalty grows quadratically for mid-range residuals
        score += 60.0 * frac * (1.0 - frac);
    }

    // Lookahead coupling: does next item fit the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 + 30.0 * (1.0 - slack / cap); // tight future fit is great
        } else {
            score += 20.0; // next item won't reuse this space
        }
    }

    // Last-chance bin: strongly favor to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Many open bins: prefer consolidation, penalize spreading
    if open_bins_count > 4 {
        score += 3.0 * (open_bins_count as f64).sqrt();
    }

    // Prefer bins below mean residual (filling emptier bins less wastefully)
    score -= 0.3 * (mean_residual - pr);

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count <= 1 { 0.0 } else { 1.0 };
        score = cap - 50.0 * pressure + 0.5 * (next_item_size as f64);
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // opening fresh bin is good if next item can pair with current one later
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
