        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 10.0 * (1.0 - nx / cap) * (1.0 + progress);
        } else {
            score += 5.0 * (nx - pr) / cap;
        }
    }

    // Mild penalty for many open bins to discourage fragmentation
    score += open_bins_count as f64 * 0.5 * progress;

    // New-bin candidate: keep it neutral-ish, slightly favored when residuals are poor
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * norm_pr + 4.0 * progress;
    }

    score
}

