pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify by integer division into
    // capacity-fraction bands (0-24, 25-49, 50-74, 75-100).
    let band = post_residual / (bin_capacity / 4 + 1);
    let band_penalty: f64 = match band {
        0 => 40.0,  // tiny dead space: nearly full bin, good placement
        1 => 10.0,  // quarter leftover
        2 => 0.0,   // half leftover: neutral
        _ => -8.0,  // large leftover: reward keeping big residual flexible
    };
    score -= band_penalty;

    // Modulo-10 harmony: residuals divisible by 10 pair cleanly with the
    // item-size grid; small non-zero remainders are prime dead space.
    let r10 = post_residual % 10;
    if r10 == 0 {
        score -= 6.0;
    } else if r10 <= 3 {
        score += 5.0 * (1.0 - r10 as f64 / 4.0);
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if it barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 4.0 * (miss / bin_capacity as f64);
        }
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when open bins are congested
    // (high mean residual relative to capacity) or late in the stream.
    if bin_residual == bin_capacity {
        let congestion = mean_residual / bin_capacity as f64;
        score = 55.0 - 30.0 * congestion
            - 5.0 * (open_bins_count as f64).ln().max(0.0)
            - 10.0 * (step_index as f64 / total_items.max(1) as f64);
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 12.0; // next item needs a fresh bin anyway
        }
    }

    // Progress tie-breaker: prefer filling older bins slightly as stream ends.
    score += 3.0 * (step_index as f64 / total_items.max(1) as f64) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Reward tight fits (small relative leftover).
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= tightness * 15.0;
    }

    // Reward if the leftover gap can host the next item (lookahead chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + (post_residual - next_item_size) as f64 * 0.3;
    }
    // Penalize leaving a gap just below the next item size (near-miss dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a bin when pressure is low,
    // but relax penalty when many bins exist or residual is fragmented.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64).max(0.5);
        score += 25.0 + pressure * 5.0;
        if fitting_bins_count == 0 {
            score -= 70.0; // no alternative: new bin is fine
        }
    }

    // Mild open-bin pressure: consolidate into fewer bins early on.
    score += open_bins_count as f64 * 0.8;

    // Slight preference for using bins with residuals close to the mean (balance).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 8.0;

    // Late in stream: be greedier with tight fits.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 60.0 + next_item_size as f64 * 0.5;
            // exact match of post_residual to next item is ideal
            let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
            score -= 40.0 / (1.0 + gap * 0.2);
        } else {
            // post_residual too small for next item: penalize dead space
            score += 25.0;
        }
    }

    // Penalize residuals far below the mean residual (wasting a big residual bin on a small item)
    score += (mean_residual - post_residual as f64).max(0.0) * 0.3;

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: penalize slightly so we only open when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    // Late in the stream, prefer tighter fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0;

    score
}

