        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        if remaining < 35 && next_item_size > 0 && pr == next_item_size {
            score -= 3.0;
        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 6 && fitting_bins_count > 2 {
            score -= 1.5;
        }
        if remaining < 30 && next_item_size > 0 && pr > 0 && pr >= next_item_size && pr - next_item_size <= 3 {
            score -= 2.0 * (1.0 - remaining as f64 / 30.0) * (1.0 - (pr - next_item_size) as f64 / 3.0);
        }
        if next_item_size > 0 && pr > 0 && pr < next_item_size && fitting_bins_count <= 2 && remaining > 40 {
            score += (next_item_size - pr) as f64 * 0.20;
        }
        if remaining >= 35 && remaining < 120 && next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 5 {
            score -= 1.0;
        }
        if remaining < 20 && pr > 0 && mean_residual > 1.0 && ((pr as f64) - mean_residual).abs() < 3.0 {
            score -= 1.5;
        }
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
        if remaining < 50 && next_item_size > 0 && pr > 0 && pr == next_item_size {
            score -= 2.5 * (1.0 - remaining as f64 / 50.0);
        }
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        if next_item_size > 0 && pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.0;
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 3 && fitting_bins_count <= 3 && remaining > 40 {
            score -= 1.8;
        }
        if next_item_size > 0 && pr > 0 && pr == next_item_size && remaining >= 50 {
            score -= 1.2;
        }
        // MUTATION v153: endgame absorbable-remainder bonus — late stream, residuals whose
        // leftover after the next item falls under the mean residual close cleanly.
        if remaining < 60 && next_item_size > 1 && pr > next_item_size && mean_residual > 1.0 {
            let rem_after = (pr - next_item_size) as f64;
            if rem_after > 0.0 && rem_after <= mean_residual {
                score -= 1.5 * (1.0 - remaining as f64 / 60.0);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: the smaller the post residual relative to item size, the better.
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 12.0 * fit_ratio * fit_ratio;

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space for the next item: penalize proportionally.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.15 * gap;
        }
    }

    // Perfect closure bonus: bin completely filled.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is expensive; only attractive when
    // no open bin fits well or the stream is early with many items remaining.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_alternatives = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        // Cost of a new bin grows as the stream progresses (less time to amortize).
        score += 40.0 + 30.0 * progress;
        // But allow opening when nothing fits or mean residual is fragmented.
        score -= 45.0 * poor_alternatives;
        if mean_residual < item_size as f64 * 0.5 {
            score -= 15.0;
        }
    } else {
        // Mild preference for reusing bins with lower residual (better packing).
        score += 0.05 * (bin_residual as f64 - mean_residual);
    }

    // Global state: with many open bins, encourage consolidation into existing bins.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;
    let frag = pr as f64 - item_size as f64;

    // Dead-space avoidance: small gaps are heavily penalized.
    if pr > 0 && pr < 10 {
        score += 55.0;
    } else if pr < 25 {
        score += 22.0 * (1.0 - pr as f64 / 25.0);
    }

    // Reward near-perfect fills.
    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 42.0;
    } else if pr <= 8 {
        score -= 16.0;
    } else if pr <= 12 {
        score -= 10.0;
    } else if pr <= 15 {
        score -= 4.0;
    } else if pr <= 25 {
        score -= 1.0;
    } else if pr <= 40 {
        score += 4.0;
    } else if pr <= 60 {
        score += 8.0;
    } else {
        score += 12.0;
    }

    // MUTATION v153: dead-space ratio coupling — combine fine-grained residual fitting with
    // lookahead anticipation. A post-residual that the next item cannot use at all is dead
    // space for one full stream step; weight it by stream density and bin scarcity.
    if next_item_size > 0 && pr > 0 && pr < next_item_size {
        let dead = (next_item_size - pr) as f64;
        let density = remaining as f64 / total_items.max(1) as f64;
