        // Lookahead: does the next item fit into the post-residual?
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size > pr {
            let dead = (next_item_size - pr) as f64;
            score += pr as f64 * 0.5 + dead * (0.25 + 0.55 * density) * (if fitting_bins_count <= 2 { 1.25 } else { 1.0 });
        } else {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
