        }
        // MUTATION v154 (new): endgame near-zero closure — very late stream, any residual
        // within a couple of units of zero is nearly closed; reward escalating with urgency.
        if remaining < 25 && pr > 0 && pr <= 4 {
            score -= 2.5 * (1.0 - remaining as f64 / 25.0) * (1.0 - pr as f64 / 4.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, prefer tight fits (low post_residual) strongly; later, tolerate slack.
    let tightness = (pr / cap).powi(2) + (pr / cap).powi(4);
    score += tightness * (1.0 - progress) * 30.0;

    // Reward near-perfect fits smoothly: subtract a gaussian-like bump around pr=0.
    let fit_bump = (-(pr * pr) / (2.0 * 8.0 * 8.0)).exp();
    score -= fit_bump * 40.0 * (0.5 + 0.5 * progress);

    // Penalize dead space that can't fit the next item (smooth coupling).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0);
        score += (gap / cap).powi(3) * 20.0;
        // Reward leaving exactly enough room for next item.
        let match_bump = (-(pr - next_item_size as f64).powi(2) / (2.0 * 6.0 * 6.0)).exp();
        score -= match_bump * 15.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Mild penalty when many bins are open and this bin is far below mean residual
    // (encourages consolidation toward average fill).
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 10.0 / (1.0 + open_bins_count as f64 * 0.1);

    // New-bin candidate: make empty bin mildly attractive only when item is large
    // relative to residuals, otherwise favor existing bins.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 / cap;
        score -= 10.0 * big_item * big_item;
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;
    let pr = post_residual;

    // --- Tight-fit rewards (harmonic classes of post_residual) ---
    if pr == 0 {
        score -= 60.0; // perfect fit: ideal
    } else if pr < 5 {
        score -= 25.0;
    } else if pr < 10 {
        score -= 12.0;
    }

    // Integer-division class: coarser residual buckets, larger class = more waste
    let class = pr / 10;
    score += class as f64 * 1.5;

    // Mid-range dead space is the worst: hard to fill later
    if pr >= 30 && pr <= 70 {
        score += 10.0;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 30.0; // next item exactly fills remainder: chain fit
        } else if pr >= next_item_size {
            score -= 10.0 + 0.3 * next_item_size as f64;
        } else {
            // next item cannot use remainder: remainder likely wasted
            score += (next_item_size - pr) as f64 * 0.15;
            if pr < 10 {
                score -= 8.0; // tiny remainder still fine
            }
        }
    }

    // --- Last-chance bin before opening a new one ---
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 35.0;
    }

    // --- New-bin candidate logic ---
    if is_new_bin {
        score += 45.0; // base reluctance to open new bin
        if next_item_size >= 50 {
            score -= 25.0; // big item coming: fresh capacity valuable
        }
        if fitting_bins_count <= 1 {
            score -= 40.0; // no (or one) alternatives
        }
        if open_bins_count > 6 {
            score += 12.0; // too many open bins already
        }
        let t = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - t) * 6.0; // early stream: more willing to open
        if next_item_size > 0 && next_item_size >= item_size && item_size >= 60 {
            score -= 15.0; // large-item regime
        }
    }

    // --- Dispersion coupling: prefer residuals near the mean state ---
    score += (mean_residual - pr as f64).abs() * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;
    let frag = pr as f64 - item_size as f64;

    // Dead-space guard: tiny residuals are poor hosts.
    if pr > 0 && pr < 10 {
        score += 55.0;
    } else if pr < 25 {
        score += 22.0 * (1.0 - pr as f64 / 25.0);
    }

    // Reward near-perfect fills.
    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 42.0;
    } else if pr <= 8 {
        score -= 16.0;
    } else if pr <= 12 {
        score -= 10.0;
    } else if pr <= 15 {
        score -= 4.0;
    } else if pr <= 25 {
        score -= 1.0;
    } else if pr <= 40 {
        score += 4.0;
    } else if pr <= 60 {
        score += 8.0;
    } else {
        score += 12.0;
    }

    if next_item_size > 0 {
        // Lookahead: does the next item fit into the post-residual?
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size > pr {
            let dead = (next_item_size - pr) as f64;
            let density = remaining as f64 / total_items.max(1) as f64;
            let scarcity = if fitting_bins_count <= 2 { 1.25 } else { 1.0 };
            score += pr as f64 * 0.5 + dead * (0.25 + 0.55 * density) * scarcity;
        } else {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 {
                score -= 5.0;
            }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 45.0 {
                score += (slack - 45.0) * 0.05;
            }
        }
        // Two-item lookahead.
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        // Chain-friendliness: residual divisible by next size.
        if pr > 0 && pr >= next_item_size && pr % next_item_size == 0 && pr / next_item_size >= 2 && remaining > 50 {
            score -= 2.0 * ((pr / next_item_size) as f64).min(3.0);
        }
        if pr >= next_item_size && pr - next_item_size <= 1 {
            score -= 3.0;
        }
        // Penalize residual just below next item (guaranteed dead space).
        if frag > 0.0 && frag < next_item_size as f64 && next_item_size as f64 - frag <= 4.0 {
            score += (next_item_size as f64 - frag) * 0.9;
        }
        if frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        // Multi-fit lookahead: repeated next-items with tiny remainder.
        if next_item_size > 1 && pr > 0 && pr >= next_item_size && pr / next_item_size >= 2 && pr % next_item_size <= 2 && remaining > 30 {
            score -= 1.6 * ((pr / next_item_size) as f64).min(4.0);
        }
        // Chained-divisibility bonus, stronger when bins are scarce.
        if next_item_size > 1 && pr > 0 && pr >= next_item_size {
            let rem_after = pr - next_item_size;
            if rem_after > 0 && rem_after % next_item_size == 0 && rem_after / next_item_size >= 2 && fitting_bins_count <= 3 && remaining > 60 {
                score -= 1.4 * ((rem_after / next_item_size) as f64).min(4.0);
            }
        }
        // Near-miss waste.
        if pr > 0 && pr < next_item_size && next_item_size - pr <= 6 && remaining > 30 && fitting_bins_count > 2 {
            score += (next_item_size - pr) as f64 * 0.45 * (1.0 - (next_item_size - pr) as f64 / 6.0);
        }
        if pr > 0 && pr < next_item_size && next_item_size - pr > next_item_size / 2 && fitting_bins_count > 3 && remaining > 50 {
            score += (next_item_size - pr) as f64 * 0.30;
        }
        // Two-step closure.
        if next_item_size > 1 && pr >= item_size + next_item_size {
            let rest = pr - item_size - next_item_size;
            if rest >= next_item_size && rest - next_item_size <= 4 && remaining > 25 {
                score -= 2.2 * (1.0 - (rest - next_item_size) as f64 / 4.0);
            }
        }
        // Dead-space budget matching mean residual band.
        if pr > 0 && pr >= next_item_size {
            let rem_after = pr - next_item_size;
            if rem_after > 0 && (rem_after as f64 - mean_residual).abs() <= 2.0 && remaining > 20 {
                score -= 1.8 * (1.0 - (rem_after as f64 - mean_residual).abs() / 2.0);
            }
        }
        // Stranding risk coupling.
        if pr > 0 && mean_residual > 3.0 && (pr as f64) < mean_residual * 0.80 && remaining > 60 {
            score += (mean_residual * 0.80 - pr as f64) * (0.18 + 0.14 * progress);
        }
        if pr > next_item_size && (pr - next_item_size) < 14 && fitting_bins_count > 1 {
            let dead2 = (pr - next_item_size) as f64;
            score += dead2 * 0.10 * (1.0 - dead2 / 14.0);
        }
        if pr > next_item_size && (pr - next_item_size) * 2 <= pr {
            score -= 1.2;
        }
        // Mid-range unusable gap penalty.
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 {
                score += (gap as f64 - 25.0) * 0.08;
            }
        }
        if pr == next_item_size && fitting_bins_count <= 2 {
