pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base penalty on residual: prefer tight fits.
    score = score * 1.5 + (post_residual as f64).powi(2) / bin_capacity as f64 * 0.5;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item size.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Next item fits perfectly: big reward.
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item would not fit here: mild penalty proportional to overshoot.
            score += 5.0 + gap * 0.1;
        }
    }

    // Relative to mean residual: penalize bins far below/above mean waste.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Late in stream: consolidate, prefer filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // But if this bin is the only fitting one and it's a poor fit, allow opening.
        if fitting_bins_count == 1 && post_residual as f64 > mean_residual {
            score -= 35.0;
        }
        // Early stream: opening bins is cheaper.
        score -= (1.0 - progress) * 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally to how much of the bin the item consumes.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 45.0 * fill_ratio * fill_ratio;

    // Strongly penalize small dead space (unusable leftovers), reward exact/near-exact fits.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item, favor it heavily.
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        // With multiple candidates, mildly prefer bins with less residual (best-fit flavor)
        score += 0.15 * (bin_residual as f64 - mean_residual);
    }

    // Lookahead: if the next item can also fit in the post-residual, reward this bin;
    // otherwise penalize if this placement leaves space too small for the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            score += 8.0;
        }
        // If next item is large, prefer conserving big-residual bins for it
        if nxt > item_size as f64 && bin_residual as f64 >= nxt {
            score += 6.0;
        }
    }

    // New-bin candidate logic: opening a new bin is only attractive when no open bin
    // fits well or when open bins are nearly full.
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize opening new bins when open bins are well utilized
        score += 15.0 * avg_fill;
        // Early in the stream, opening bins is cheap; later, avoid fragmentation
        score += 20.0 * (1.0 - progress);
        // If many bins fit the item, a new bin is unattractive
        if fitting_bins_count > 0 {
            score += 10.0 + 5.0 * fitting_bins_count.min(5) as f64;
        }
    }

    // Mild global pressure: with many open bins, prefer packing into existing ones.
    score += 0.02 * open_bins_count as f64;

    score
}

