    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open bins pressure: when many bins are open, prefer filling existing ones
    // (penalize the new-bin candidate implicitly via residual, but also add pressure).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * 0.6 * (0.5 + 0.5 * progress);

    // Penalize leaving large residuals when mean residual across bins is already high
    // (indicates fragmentation; prefer bins that consolidate space).
    if post_residual as f64 > mean_residual {
        score += 0.25 * (post_residual as f64 - mean_residual);
    }

    // New-bin candidate handling: empty bin gets a mild penalty unless current bin
    // would waste a lot of space.
    if bin_residual == bin_capacity {
        score += 5.0;
        if post_residual >= 50 {
            score -= 10.0; // opening a fresh bin for big items is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

