    // deviating bins are penalized slightly to keep the pool homogeneous.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // Time horizon: early in the stream, be more willing to open new bins (keep options);
    // later, pack tightly.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * t * (item_size as f64 / bin_capacity as f64);
    score += 5.0 * (1.0 - t) * (post_residual as f64 / bin_capacity as f64);

