        1 => score -= 2.0,                           // 25..49: usable for small items
        2 => score -= 6.0,                           // 50..74: sweet spot
        3 => score -= 3.0,                           // 75..99: roomy but wasteful
        _ => {}                                      // 100: exact fit handled below
    }

    // Exact fit: perfect closure.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: does the leftover exactly or comfortably host the next item?
    if next_item_size > 0 {
        if post_residual == next_item_size {
