pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins whose residual is nearly consumed.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize large dead space after placement, especially if it can't host the next item.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 0.6 * (next_item_size - post_residual) as f64;
        } else {
            // leftover can host next item: mild reward
            score -= 0.25 * (post_residual as f64).min(50.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is expensive; make it costly
    // unless it's clearly better (post_residual will be large and no good fits exist).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut penalty = 55.0 + 25.0 * (1.0 - progress);
        // If many bins are open with slack, prefer reusing them.
        penalty += 0.8 * mean_residual.min(80.0);
        // If the item is large and few fitting bins exist, new bin is more acceptable.
        if fitting_bins_count <= 1 {
            penalty -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= item_size && next_item_size > post_residual.max(1) {
            penalty -= 10.0;
        }
        score += penalty;
    }

    // Prefer bins with residual close to item size (perfect nesting).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * gap;

    // Mild preference to consolidate into fewer bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (open_bins_count as f64 / 20.0).min(1.0);

    // Encourage leaving room for the mean demand of future items.
    if next_item_size > 0 {
        let target = (mean_residual * 0.5).min(bin_capacity as f64);
        score += 0.1 * (post_residual as f64 - target).abs();
    }

    score
}

