pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: exact-fill classes are golden.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 0: perfect fit -> huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Fraction-of-capacity harmonic classes for post_residual.
    let frac = pr / c;
    if frac <= 0.05 {
        score -= 60.0; // near-perfect fit
    } else if frac <= 0.15 {
        score -= 25.0;
    } else if frac <= 0.30 {
        score -= 8.0;
    } else {
        // Large dead space: penalize superlinearly.
        score += (frac - 0.30) * 120.0;
    }

    // Integer-division thresholds: residual classes by 20-wide buckets.
    let class = post_residual / 20;
    match class {
        0 => score -= 15.0,           // 0..19: tight
        1 => score -= 5.0,            // 20..39
        2 => score += 3.0,            // 40..59
        3 => score += 10.0,           // 60..79
        _ => score += 18.0,           // 80..99: wasteful
    }

    // Lookahead coupling: next item fits the post residual -> strong reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let fill_ratio = nxt / pr.max(1.0);
            score -= 30.0 * fill_ratio; // reward leaving space usable by next item
        } else {
            // Next item cannot fit here; penalize small leftovers that waste capacity.
            score += 8.0 * (1.0 - frac);
        }
        // Harmonic pairing: next item exactly matches post residual.
        if next_item_size == post_residual {
            score -= 45.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0 + (item_size as f64 / c) * 20.0;
    }

    // New-bin candidate: penalize opening a new bin, more so early in the stream
    // and when many bins are open (aggregation opportunity exists).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = c * 0.55 + 30.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64).sqrt();
        // But if the item is huge and no open bin fits well, allow new bin.
        if item_size as f64 > 0.7 * c && fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Mild preference for bins below mean residual (balances residuals).
    score += 0.05 * (pr - mean_residual);

    // Stream-phase modulation: late in stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && post_residual <= 10 {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small leftover gaps (< 10) are unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Medium dead space is mildly bad if below typical item sizes.
    if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Prefer tighter fits generally (relative fill).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // If the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }
    // Penalize if post residual is too small for the next item (dead space for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading onto new bins
    // and favor consolidating into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or stream is late.
        score += 25.0 + 10.0 * pressure + 20.0 * progress;
    } else {
        // Existing bin: slight reward when bin pressure is high.
        score -= 2.0 * pressure;
    }

    // Favor bins with residuals below the mean (consolidating small gaps).
    let dev = mean_residual - bin_residual as f64;
    score += 0.1 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
