        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
        if fitting_bins_count > 0 && fresh_left <= 3.0 && item_ratio > 0.9 {
            score -= 5.0;
        }
        if next_item_size > 0 && fresh_left == next_item_size as f64 && remaining > 30 {
            score -= 3.0;
        }
        if next_item_size > 1 && fresh_left == (next_item_size * 2) as f64 && remaining > 40 {
            score -= 2.2 * (1.0 - remaining as f64 / total_items.max(1) as f64);
        }
        if mean_residual > 30.0 && remaining > 100 {
            score -= 2.0;
        }
        if next_item_size > 1 && fresh_left == (next_item_size * 3) as f64 && remaining > 60 {
            score -= 1.8;
        }
        // MUTATION v158: fresh-bin dead-space guard — opening a bin whose leftover just misses
        // the next item by a wide margin strands capacity; scale with horizon.
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && remaining > 100 {
            score += (next_item_size as f64 - fresh_left) * 0.25;
        }
        // MUTATION v159: fresh-bin exact-multiple slot bonus — a new bin whose leftover holds
        // an exact number of next-items promises a fully packed lifecycle; reward scaled by
        // slots and horizon.
        if next_item_size > 1 && fresh_left > 0.0 && (fresh_left as u32) % next_item_size == 0 && (fresh_left as u32) / next_item_size >= 2 && remaining > 80 {
            score -= 1.5 * ((fresh_left as u32 / next_item_size) as f64).min(4.0);
        }
        // MUTATION v159: fresh-bin near-miss scarcity guard — when several bins already fit,
        // opening a fresh bin that immediately strands dead space below the next item is wasteful.
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && fitting_bins_count >= 3 && remaining > 50 {
            score += (next_item_size as f64 - fresh_left) * 0.45;
        }
    } else {
        score += 60.0;
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        if remaining < 35 && next_item_size > 0 && pr == next_item_size {
            score -= 3.0;
        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 6 && fitting_bins_count > 2 {
            score -= 1.5;
        }
        if remaining < 30 && next_item_size > 0 && pr > 0 && pr >= next_item_size && pr - next_item_size <= 3 {
            score -= 2.0 * (1.0 - remaining as f64 / 30.0) * (1.0 - (pr - next_item_size) as f64 / 3.0);
        }
        if next_item_size > 0 && pr > 0 && pr < next_item_size && fitting_bins_count <= 2 && remaining > 40 {
            score += (next_item_size - pr) as f64 * 0.20;
        }
        if remaining >= 35 && remaining < 120 && next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 5 {
            score -= 1.0;
        }
        if remaining < 20 && pr > 0 && mean_residual > 1.0 && ((pr as f64) - mean_residual).abs() < 3.0 {
            score -= 1.5;
        }
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
        if remaining < 50 && next_item_size > 0 && pr > 0 && pr == next_item_size {
            score -= 2.5 * (1.0 - remaining as f64 / 50.0);
        }
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        if next_item_size > 0 && pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.0;
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 3 && fitting_bins_count <= 3 && remaining > 40 {
            score -= 1.8;
        }
        // MUTATION v158: endgame exact-closure widening — late stream, residuals that close
        // within one small step of the next item are nearly as good as exact closure.
        if remaining < 45 && next_item_size > 0 && pr > 0 && pr > next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 * (1.0 - remaining as f64 / 45.0) * (1.0 - (pr - next_item_size) as f64 / 2.0);
        }
        // MUTATION v159: endgame multi-slot closure — late stream, residuals holding two or
        // more exact next-items close out several items without opening bins.
        if remaining < 60 && next_item_size > 1 && pr > 0 && pr % next_item_size == 0 && pr / next_item_size >= 2 {
            score -= 2.0 * (1.0 - remaining as f64 / 60.0) * ((pr / next_item_size) as f64).min(3.0) * 0.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: prefer bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // 2-step lookahead: reward when next item exactly matches post-residual
    // (perfect follow-up), penalize post_residual that is useless for next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect chain
        } else if next_item_size <= post_residual {
            // next item fits here: mild reward proportional to how snugly
            let nxt_fill = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 12.0 * nxt_fill;
        } else {
            // next item cannot use the leftover space -> dead-space penalty
            let waste = (post_residual as f64 - (next_item_size as f64 - post_residual as f64)).max(0.0);
            score += 0.15 * waste.min(40.0);
        }
    }

    // Relative to mean residual: bins with small residual are precious,
    // avoid dumping large items into them unless it's a great fit.
    let dev = post_residual as f64 - mean_residual;
    score += 0.10 * dev;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when existing bins fit decently,
    // unless the item is huge relative to capacity.
    if bin_residual == bin_capacity {
        let big_item_bonus = if item_size >= bin_capacity / 2 { 8.0 } else { 0.0 };
        score += 15.0 - big_item_bonus;
    }

    // Slight preference to fill older (smaller-residual) bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared post-residual grows penalty for large leftovers.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: penalize leaving a residual that cannot fit the next item
    // (dead space), reward residuals that can still host it.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 12.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        } else if post_residual >= next_item_size {
            score -= 4.0;
            // Extra reward if next item fills this bin almost perfectly afterwards.
            let two_step = post_residual as i64 - next_item_size as i64;
            if two_step >= 0 && two_step <= 5 {
                score -= 8.0;
            }
        }
    } else {
        // Last item: minimize waste directly.
        score += post_residual as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Prefer bins with less residual among comparable fits (best-fit flavor).
    score += (bin_residual as f64) * 0.1;

    // Penalize opening a new bin when decent open bins exist, but allow it
    // when residuals are fragmented (mean residual low relative to item).
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of a fresh bin.
        score = bin_capacity as f64 * 0.55;
        if fitting_bins_count > 0 {
            let avg_fit_waste = mean_residual - item_size as f64;
            if avg_fit_waste < 10.0 {
                // Existing bins are nearly full: opening new bin is fine.
                score -= 15.0;
            } else {
                // Existing bins have room: discourage new bin.
                score += 10.0 + avg_fit_waste * 0.3;
            }
        }
        // Early in the stream, be more willing to open bins (build diversity).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
        // Few open bins: new bin cheap; many open bins: new bin expensive.
        score += (open_bins_count as f64) * 0.8;
        // If next item is large, a fresh bin is valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Global pressure: many open bins -> prefer consolidating into existing ones.
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
        // Prefer bins whose residual is close to mean (balance residuals).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Small noise-free tie-breaker scaled by item size.
    score -= item_size as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;
    let frag = pr as f64 - item_size as f64;

    // Small-residual dead-space bands.
    if pr > 0 && pr < 10 {
        score += 55.0;
    } else if pr < 25 {
        score += 22.0 * (1.0 - pr as f64 / 25.0);
    }

    // Near-perfect fill rewards (widened exact-closure band).
    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 42.0;
    } else if pr <= 8 {
        score -= 16.0;
    } else if pr <= 12 {
        score -= 10.0;
    } else if pr <= 15 {
        score -= 4.0;
    } else if pr <= 25 {
        score -= 1.0;
    } else if pr <= 40 {
        score += 4.0;
    } else if pr <= 60 {
        score += 8.0;
    } else {
        score += 12.0;
    }

    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size > pr {
            let dead = (next_item_size - pr) as f64;
            let density = remaining as f64 / total_items.max(1) as f64;
            let scarcity = if fitting_bins_count <= 2 { 1.25 } else { 1.0 };
            score += pr as f64 * 0.5 + dead * (0.25 + 0.55 * density) * scarcity;
        } else {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 {
                score -= 5.0;
            }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 45.0 {
                score += (slack - 45.0) * 0.05;
