        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.4 * (1.0 - remaining as f64 / total_items.max(1) as f64);
        }
        // Scarcity-escalated near-miss.
        if pr > 0 && pr < next_item_size && fitting_bins_count <= 2 && remaining > 40 {
            score += (next_item_size - pr) as f64 * 0.20;
        }
        // Dead-space-ratio coupling across the whole near-miss band.
        if pr > 0 && pr < next_item_size {
            let dead = (next_item_size - pr) as f64;
            let density = remaining as f64 / total_items.max(1) as f64;
            let scarcity = if fitting_bins_count <= 2 { 1.2 } else { 1.0 };
            score += dead * (0.10 + 0.30 * density) * scarcity;
        }
        // Triple-slot exact host with scarcity.
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 3 && remaining > 40 {
            let scarcity_bonus = if fitting_bins_count <= 3 { 0.8 } else { 0.0 };
            score -= 1.8 + scarcity_bonus;
        }
        // Slack-band tightening: 3..10 slack wastes a slot's worth of future capacity.
        if pr > next_item_size {
            let slack = pr - next_item_size;
            if slack >= 3 && slack <= 10 && remaining > 25 {
                score += slack as f64 * 0.10 * (1.0 - slack as f64 / 10.0);
            }
        }
        // MUTATION v160: divisibility reward for pr itself (borrowed from best) — residuals that
        // are exact multiples of the next item chain cleanly; reward scaled by chain length.
        if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 && remaining > 40 {
            score -= 1.5 * ((pr / next_item_size) as f64).min(3.0);
        }
        // MUTATION v160: endgame near-closure tightening — late stream, prefer fits that close
        // the residual within a small margin of the next item, scaled by urgency.
        if remaining < 45 && next_item_size > 0 && pr > 0 && pr > next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 * (1.0 - remaining as f64 / 45.0) * (1.0 - (pr - next_item_size) as f64 / 2.0);
