pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: penalize leftover space, with a non-linear (quartic-ish) waste curve.
    let x = pr / cap;
    let mut score = x * x * (2.0 - x) * cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tight residuals matter more (less time to fill them).
    let t = progress;
    let coupling = pr * (0.5 + 1.5 * t * t * (3.0 - 2.0 * t)) / cap;
    score += coupling * 10.0;

    // Perfect fit reward (smooth via residual proximity to zero).
    score -= (1.0 - x).powi(6) * 15.0;

    // Penalize residuals that cannot fit the lookahead item (dead space),
    // smoothly weighted by how close the next item is to fitting.
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = (pr - next_item_size as f64) / cap;
        if gap < 0.0 {
            score += (-gap).powi(2) * 8.0 * (1.0 - nx);
        } else {
            // residual comfortably fits next item: mild reward
            score -= gap.min(0.5) * 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 * (1.0 - t * 0.5);
    }

    // New-bin candidate: prefer it early when open bins are already fragmented,
    // discourage it late in the stream.
    if bin_residual == bin_capacity {
        score += 12.0 * t + 2.0 * (open_bins_count as f64).ln();
    } else {
        // favor fuller bins among open ones
        score += (bin_residual as f64 / cap) * 4.0;
    }

    // Mild preference toward bins with residuals near the mean (balance).
    score += ((pr - mean_residual) / cap).powi(2) * 3.0;

    score
}

