    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let r_mod = (post_residual % bin_capacity) as f64;

    // Penalize residual classes that are "dead" (too small for typical items 10..80)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 10.0; // barely usable
    }

    // Integer division threshold: post_residual / 10 class
    let class = post_residual / 10;
    score -= (class as f64) * 2.0;

    // Reward tight fits (small post_residual but still usable)
    let tightness = 1.0 - post / cap;
    score -= 15.0 * tightness * tightness;

    // Harmonic coupling with next item: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let waste = post_residual - next_item_size;
            score += (waste as f64) * 0.3;
            // modulo harmony: next item leaves a residual in a good class
            let next_post = post_residual - next_item_size;
            if next_post == 0 || next_post >= 10 {
                score -= 8.0;
            }
        } else {
            score += 12.0; // next item cannot use this residual
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly unless open bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        score += 8.0 + (open_bins_count as f64) * 0.5;
        if post_residual >= 20 {
