        }
        // early in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (more filled)
    score += (mean_residual - post).clamp(-30.0, 30.0) * 0.4;

    // Modulo arithmetic flavor: reward residuals divisible by common item classes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
