pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to host any
    // realistic future item are "dead". Penalize them super-linearly.
    let dead_threshold = 9.0; // smallest useful gap
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Medium dead zones: gaps 10..=19 often waste capacity too.
    if post_residual >= 10 && post_residual < 20 {
        score += 3.0;
    }

    // Perfect or near-perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }
    if next_item_size > 0 && post_residual > next_item_size && (post_residual - next_item_size) < 10 {
        score += 4.0; // leaves a small dead sliver after next item
    }

    // Open-bins pressure: with many open bins, prefer consolidation
    // (penalize opening/spreading); when few bins are open, be lenient.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (2.0 + 3.0 * progress);

    // Last-chance bin: strongly favor using it before a new bin is opened.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin would leave a
    // large dead gap and many bins already exist.
    if bin_residual == bin_capacity {
        score -= 5.0;
        if post_residual > 20 && open_bins_count > 3 {
            score -= 8.0;
        }
        if post_residual <= 20 && open_bins_count > 0 {
            score += 10.0; // don't open new bin for a good fit elsewhere
        }
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean
    // (keeps bin population balanced).
    score += ((bin_residual as f64) - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // New-bin candidate handling: neutral baseline, opened only if no good fit exists.
    if bin_residual == bin_capacity {
        return 100.0 + mean_residual * 0.5;
    }

    // 2-step lookahead: strongly reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;

        if post_residual == next_item_size {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            // next fits: prefer small leftover after the second placement
            score -= 30.0 * (1.0 - (post - nxt) / 100.0);
        } else {
            // next won't fit here: penalize dead space relative to next size
            score += 0.25 * (nxt - post).min(60.0);
        }
    }

    // Last-chance bin: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than average residual (best-fit flavor).
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Mild preference for filling bins well as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * (item_size as f64) * 0.1;

    score
}

