pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Base: post residual, scaled by stream progress (dead space matters more later)
    let mut score = pr * (0.6 + 0.8 * progress);

    // Smooth non-linear penalty for awkward residuals: penalize small-but-nonzero
    // residuals (wasted slivers) with a quartic coupling to progress
    let sliver = norm_pr * (1.0 - norm_pr);
    score += 30.0 * sliver * sliver * (0.5 + progress);

    // Reward tight fits: strongly subtract when post_residual is small
    let tightness = (-norm_pr * 6.0).exp();
    score -= 12.0 * tightness * (1.0 + 0.5 * progress);

    // Lookahead coupling: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let fit_next = (norm_pr - norm_next).max(0.0);
        let coupling = fit_next * (1.0 - fit_next) * 4.0; // smooth bump peaking at perfect next-fit
        score -= 10.0 * coupling;
        // Penalize if next item barely misses this residual
        let miss = (norm_next - norm_pr).max(0.0);
        score += 8.0 * (miss * miss) * (1.0 - norm_item);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild pressure toward consolidating into fewer bins
    score += 0.4 * open_bins_count as f64 * norm_pr;

    // Prefer bins below mean residual (filling emptier bins first) with smooth term
    score += 0.5 * (pr - mean_residual) * (0.5 + 0.5 * progress);

    // New-bin candidate: penalize opening a new bin unless item is large relative
    // to typical residuals (smooth logistic gate)
    if bin_residual == bin_capacity {
        let gate = 1.0 / (1.0 + (-(norm_item * 8.0 - 4.0)));
        score += 25.0 * (1.0 - gate) * (1.0 - progress) + 5.0 * gate;
    }

    score
}

