        let mut reusable = 0.0;
        if post_residual % 10 == 0 { reusable += 8.0; }
        if post_residual % 20 == 0 { reusable += 4.0; }
        if post_residual % 25 == 0 { reusable += 4.0; }
        if post_residual % 50 == 0 { reusable += 6.0; }
        score -= reusable;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let next_left = post_residual - next_item_size;
            // Prefer chains that keep residuals in coarse classes.
            if next_left % 10 == 0 { score -= 15.0; }
            score += next_left as f64 * 0.3;
        } else {
