        }
        if next_item_size > 0 && pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.0;
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 3 && fitting_bins_count <= 3 && remaining > 40 {
            score -= 1.8;
        }
        // MUTATION v163: mid-stream tight-fit bonus — residuals that hold the next item
        // with slack within the mean-residual band are strong hosts.
        if remaining >= 120 && next_item_size > 1 && pr > next_item_size && (pr - next_item_size) as f64 <= mean_residual * 0.6 {
            score -= 1.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual) already handled by init.
    // Normalize dead space a bit relative to capacity.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // --- 2-step lookahead: reward bins whose post_residual exactly matches next item ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - nxt).abs();
        if diff == 0.0 {
            // Perfect chain fit: strongly reward.
            score -= 45.0;
        } else if post >= nxt {
            // Next item can still fit here: mild reward proportional to closeness.
            score -= 18.0 * (1.0 - diff / 100.0);
        } else {
            // Next item cannot follow into this bin: penalize leftover dead space,
            // scaled by how much of the bin is wasted relative to next item.
            score += 12.0 * (nxt - post) / 100.0;
        }
        // If post_residual is tiny but nonzero, it's near-unusable dead space.
        if post > 0.0 && post < 10.0 {
            score += 8.0;
        }
    } else {
        // Last item: purely minimize waste.
        score -= 5.0;
    }

    // --- Mean residual coupling: prefer bins with below-average residual
    // (concentrate waste into few bins) ---
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        let rel = (post_f - mean_residual) / mean_residual;
        score += 6.0 * rel;
    }

    // --- Last-chance bin: if this is the only bin that fits, strongly favor using it ---
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // --- New-bin candidate handling (bin_residual == bin_capacity) ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing fits are poor
        // (large post_residual elsewhere) or no open bin fits well.
        // Add a moderate opening cost so we only open when placements are bad.
        let open_cost = 25.0
            + 0.25 * (open_bins_count as f64)
            + 10.0 * (step_index as f64 / total_items.max(1) as f64);
        // If the next item would perfectly fill the fresh bin after this one,
        // opening is more attractive.
        let lookahead_bonus = if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64 - item_size as f64).abs() < 1.0 {
            -20.0
        } else if next_item_size > 0 && next_item_size as f64 <= bin_capacity as f64 - item_size as f64 {
            -8.0
        } else {
            0.0
        };
        score = post_f + open_cost + lookahead_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
