pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: reward near-perfect fills strongly.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score += tight * tight * 20.0;

    // Reward small absolute leftover (wasted space) relative to capacity.
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    } else if post_residual < 10 {
        score -= 10.0; // near-perfect fill, unusable dead space anyway
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Creating dead space smaller than next item: penalize.
        score += 8.0;
    }

    // Global state coupling: when many bins are open with high mean residual,
    // prefer filling existing bins rather than spreading.
    if open_bins_count > 1 {
        let mean_bonus = (mean_residual / bin_capacity as f64) * 6.0;
        score -= mean_bonus;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity and existing residuals are poor.
    if bin_residual == bin_capacity {
        let base_cost = 15.0;
        let pressure = (mean_residual / bin_capacity as f64).max(0.0);
        let large_item = (item_size as f64 / bin_capacity as f64) * 10.0;
        score += base_cost + pressure * 10.0 - large_item - 5.0 * progress;
        // If no open bin fits at all, opening is necessary: soften penalty.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Early stream: slight preference for consolidation to build useful residuals.
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

