        // MUTATION v164: fresh-bin dead-space guard — penalize openings whose leftover misses
        // the next item, scaled by horizon and scarcity of alternatives.
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && remaining > 100 {
            let scarcity = if fitting_bins_count <= 2 { 1.3 } else { 1.0 };
            score += (next_item_size as f64 - fresh_left) * 0.28 * scarcity;
