            score -= 2.5 * (1.0 - remaining as f64 / 50.0);
        }
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        if next_item_size > 0 && pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.0;
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 3 && fitting_bins_count <= 3 && remaining > 40 {
            score -= 1.8;
        }
        // MUTATION v165: endgame mean-band closure — late stream, residual within the
        // mean-residual band promises reuse by the many remaining small items.
        if remaining < 45 && pr > 0 && mean_residual > 2.0 && (pr as f64 - mean_residual).abs() <= 1.5 {
            score -= 2.2 * (1.0 - remaining as f64 / 45.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powi(2) * 100.0;

    // 2-step lookahead: reward exact/near match between post_residual and next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item fits perfectly -> big reward
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // dead space relative to next item -> penalize
            score += 0.4 * gap;
        }
        // perfect match bonus
        if post_residual == next_item_size {
            score -= 40.0;
        }
    }

    // Relative to mean residual: prefer bins with residual above mean (avoid fragmenting tight bins)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly unless current fit is very poor
    if bin_residual == bin_capacity {
        score += 45.0;
        // allow new bin if the item would leave huge dead space everywhere
        if post_residual > bin_capacity / 2 {
            score -= 55.0;
        }
    }

    // Progress-based tightening: later in stream, be more conservative with dead space
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.2;

    score
}

