        // Mild waste signal for residual barely above next item.
        if pr > next_item_size && (pr - next_item_size) > 0 && (pr - next_item_size) < 14 && fitting_bins_count > 1 {
            let dead2 = (pr - next_item_size) as f64;
            score += dead2 * 0.10 * (1.0 - dead2 / 14.0);
        }
        // Good host: residual holds next item plus at least its size again.
        if pr > next_item_size && (pr - next_item_size) * 2 <= pr {
            score -= 1.2;
        }
        // Gap-band penalty: mid-range unusable gaps are poor hosts.
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 {
                score += (gap as f64 - 25.0) * 0.08;
            }
        }
        // Exact-match with few alternatives.
        if pr == next_item_size && fitting_bins_count <= 2 {
            score -= 4.0;
        }
        // Frag dead-space window with alternatives.
        if frag > 0.0 && frag < next_item_size as f64 {
            let dead = next_item_size as f64 - frag;
            if dead > 6.0 && fitting_bins_count > 1 {
                score += dead * 0.12;
            }
        }
        // Long-horizon near-miss.
        if pr > 0 && pr < next_item_size && next_item_size - pr <= 3 && remaining > 80 {
            score += (next_item_size - pr) as f64 * 0.6;
        }
        // Variance-aware near-miss escalation.
        if pr > 0 && pr < next_item_size && mean_residual > 2.0 && (next_item_size as f64 - pr as f64) <= mean_residual * 0.7 && remaining > 50 {
            score += (next_item_size as f64 - pr as f64) * (0.35 + 0.25 * progress);
        }
        // Half-capacity pairing.
        if next_item_size > 1 && pr >= next_item_size * 2 {
            let rem_after = pr - next_item_size;
            if rem_after >= next_item_size && (rem_after - next_item_size) as f64 <= mean_residual * 0.5 && remaining > 40 {
                score -= 1.1 * (1.0 - (rem_after - next_item_size) as f64 / (mean_residual * 0.5 + 1.0)) * (0.6 + 0.6 * progress);
            }
        }
        // Exact double-slot host.
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.4 * (1.0 - remaining as f64 / total_items.max(1) as f64);
        }
        // Scarcity-escalated near-miss.
        if pr > 0 && pr < next_item_size && fitting_bins_count <= 2 && remaining > 40 {
            score += (next_item_size - pr) as f64 * 0.20;
        }
        // MUTATION v158: dead-space-ratio coupling — residual that next item cannot use at all,
        // scaled by stream density and scarcity, combined across the whole near-miss band.
        if pr > 0 && pr < next_item_size {
            let dead = (next_item_size - pr) as f64;
            let density = remaining as f64 / total_items.max(1) as f64;
            let scarcity = if fitting_bins_count <= 2 { 1.2 } else { 1.0 };
            score += dead * (0.10 + 0.30 * density) * scarcity;
        }
        // MUTATION v158: triple-slot exact host with scarcity — residual holding exactly three
        // next-items with zero slack is a near-perfect chain; reward more when bins are scarce.
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 3 && remaining > 40 {
            let scarcity_bonus = if fitting_bins_count <= 3 { 0.8 } else { 0.0 };
            score -= 1.8 + scarcity_bonus;
        }
        // MUTATION v158: slack-band tightening — residual whose slack over next item falls in
        // 3..10 wastes a slot's worth of future capacity; penalize proportionally.
        if pr > next_item_size {
            let slack = pr - next_item_size;
            if slack >= 3 && slack <= 10 && remaining > 25 {
                score += slack as f64 * 0.10 * (1.0 - slack as f64 / 10.0);
            }
        }
        // MUTATION v159: exact-closure divisors — residuals that are exact multiples of the
        // next item (beyond the single-fit case) promise repeated clean fits; reward scaled
        // by the number of slots and stream density.
        if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 && pr / next_item_size >= 2 {
            let slots = (pr / next_item_size) as f64;
            let density = remaining as f64 / total_items.max(1) as f64;
            score -= 0.8 * slots.min(4.0) * (0.5 + 0.5 * density);
        }
        // MUTATION v159: post-residual mean-band alignment — leftover after this fit that sits
        // within a tight band around the mean residual is likely reusable by upcoming items.
        if pr > 0 && mean_residual > 4.0 && pr > next_item_size {
            let rem_after = pr - next_item_size;
            let d = ((rem_after as f64 - mean_residual) / mean_residual).abs();
            if d < 0.15 && remaining > 40 {
                score -= 1.6 * (1.0 - d / 0.15);
            }
        }
        // MUTATION v159: near-miss density escalation — when many bins can fit the item, a
        // residual just below next item size strands capacity that another bin could use.
        if pr > 0 && pr < next_item_size && fitting_bins_count >= 4 && remaining > 60 {
            score += (next_item_size - pr) as f64 * 0.22;
        }
        // MUTATION v160: exact single-fit closure with lookahead — residual exactly equal to
        // next item closes the bin cleanly next step; escalate reward with remaining horizon.
        if pr > 0 && pr == next_item_size && remaining > 15 {
            score -= 2.5 * (1.0 - remaining as f64 / total_items.max(1) as f64);
        }
        // MUTATION v160: combined two-item exact closure — residual that holds exactly the
        // next item plus a small extra that the mean residual suggests will be absorbed.
        if next_item_size > 1 && pr > next_item_size && pr - next_item_size <= mean_residual as u32 && remaining > 30 {
            let extra = (pr - next_item_size) as f64;
            score -= 1.0 * (1.0 - extra / (mean_residual + 1.0));
        }
        // MUTATION v160: waste-floor coupling — residual that leaves both a near-miss below
        // next item AND exceeds the mean residual wastes two ways at once.
        if pr > 0 && pr < next_item_size && pr as f64 > mean_residual * 1.3 && remaining > 40 {
            score += (next_item_size - pr) as f64 * 0.35;
        }
    }

    // Open-bin pressure.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Bias toward bins with larger residuals.
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Fragments larger than mean residual waste capacity.
    if frag > mean_residual && frag > 12.0 && remaining > 30 {
        score += (frag - mean_residual) * 0.06;
    }
    if frag > 40.0 && remaining > 60 {
        score += (frag - 40.0) * 0.05;
    }
    // Frag trapped between one and two next-items.
    if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
        score += (frag - next_item_size as f64) * 0.10;
        if mean_residual < 16.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
    }
    // Small-item fragmentation guard.
    let fill_ratio = item_size as f64 / bin_capacity.max(1) as f64;
    if frag > 0.0 && fill_ratio < 0.42 && remaining > 40 {
        score += (0.42 - fill_ratio) * 16.0 * (1.0 - progress * 0.5);
    }
    if frag > 0.0 && frag > mean_residual * 1.6 && remaining > 30 {
        score += (frag - mean_residual * 1.6) * 0.04;
    }

    // Late-stream tightening.
    score += pr as f64 * (0.1 + 0.22 * progress);

    // Residual close to mean residual is a good host.
    if pr > 0 && mean_residual > 1.0 {
        let dev = ((pr as f64 - mean_residual) / mean_residual).abs();
        if dev < 0.3 {
            score -= 2.0 * (1.0 - dev / 0.3);
        } else if dev > 1.5 && pr as f64 > mean_residual * 2.0 {
            score += 2.5;
        }
    }
    if pr > 0 && mean_residual > 2.0 && (pr as f64) < mean_residual && (mean_residual - pr as f64) < 6.0 {
        score += (mean_residual - pr as f64) * 0.35;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 4.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 + waste_pressure + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        if item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        if item_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        let fresh_left = bin_capacity.saturating_sub(item_size) as f64;
        if remaining > 60 && fresh_left > 0.0 && fresh_left < mean_residual * 1.25 && open_bins_count > 0 {
            score += (mean_residual * 1.25 - fresh_left) * 0.38;
        }
        if fresh_left <= 6.0 && remaining > 30 {
            score -= 4.0;
        }
        if fresh_left > 0.0 && mean_residual > 1.0 && remaining > 40 {
            let d = (fresh_left - mean_residual).abs();
            if d < 4.0 {
                score -= 2.0 * (1.0 - d / 4.0);
            }
        }
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && (next_item_size as f64 - fresh_left) <= 8.0 && remaining > 40 {
            score += (next_item_size as f64 - fresh_left) * 0.5;
        }
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && (next_item_size as f64 - fresh_left) <= 5.0 && remaining > 60 && fitting_bins_count > 1 {
            score += (next_item_size as f64 - fresh_left) * 0.8;
        }
        if next_item_size > 2 && fresh_left > 0.0 && fresh_left % next_item_size as f64 == 0.0 && fresh_left / next_item_size as f64 >= 2.0 && remaining > 60 {
            score -= 2.5;
        }
        if next_item_size > 1 && fresh_left > next_item_size as f64 && ((fresh_left - next_item_size as f64) as u32) % next_item_size == 0 && remaining > 80 {
            score -= 1.2;
        }
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        if fitting_bins_count > 0 {
            score += 4.0;
        }
        if remaining < 8 && fitting_bins_count > 0 {
            score += 5.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 4.0;
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity && remaining > 30 && open_bins_count > 0 && mean_residual >= next_item_size as f64 {
            score += 6.0;
        }
        if next_item_size > 1 && fresh_left >= (next_item_size * 3) as f64 && remaining > 50 {
            score -= 2.0;
        }
        if fresh_left > 0.0 && mean_residual > 4.0 && (fresh_left - mean_residual).abs() <= 3.0 && remaining > 40 && open_bins_count > 2 {
            score -= 1.5 * (1.0 - (fresh_left - mean_residual).abs() / 3.0);
        }
        if fresh_left > 0.0 && mean_residual > 2.0 && fresh_left > mean_residual * 1.8 && remaining > 100 && open_bins_count > 3 {
            score -= 1.5;
        }
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 {
            score += 3.0;
        }
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 {
            score += 2.0;
        }
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 {
            score -= 3.0;
        }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
        if remaining < 12 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
        if fitting_bins_count > 0 && fresh_left <= 3.0 && item_ratio > 0.9 {
            score -= 5.0;
        }
        if next_item_size > 0 && fresh_left == next_item_size as f64 && remaining > 30 {
            score -= 3.0;
        }
        if next_item_size > 1 && fresh_left == (next_item_size * 2) as f64 && remaining > 40 {
            score -= 2.2 * (1.0 - remaining as f64 / total_items.max(1) as f64);
        }
        if mean_residual > 30.0 && remaining > 100 {
            score -= 2.0;
        }
        if next_item_size > 1 && fresh_left == (next_item_size * 3) as f64 && remaining > 60 {
            score -= 1.8;
        }
        // MUTATION v158: fresh-bin dead-space guard — opening a bin whose leftover just misses
        // the next item by a wide margin strands capacity; scale with horizon.
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && remaining > 100 {
            score += (next_item_size as f64 - fresh_left) * 0.25;
        }
        // MUTATION v159: fresh-bin exact-multiple slot bonus — a new bin whose leftover holds
        // an exact number of next-items promises a fully packed lifecycle; reward scaled by
        // slots and horizon.
        if next_item_size > 1 && fresh_left > 0.0 && (fresh_left as u32) % next_item_size == 0 && (fresh_left as u32) / next_item_size >= 2 && remaining > 80 {
            score -= 1.5 * ((fresh_left as u32 / next_item_size) as f64).min(4.0);
        }
        // MUTATION v159: fresh-bin near-miss scarcity guard — when several bins already fit,
        // opening a fresh bin that immediately strands dead space below the next item is wasteful.
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && fitting_bins_count >= 3 && remaining > 50 {
            score += (next_item_size as f64 - fresh_left) * 0.45;
        }
        // MUTATION v160: fresh-bin near-miss horizon guard — leftover that just misses the next
        // item by 1-3 wastes a nearly full slot for a long horizon.
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && (next_item_size as f64 - fresh_left) <= 3.0 && remaining > 70 {
            score += (next_item_size as f64 - fresh_left) * 0.6;
        }
        // MUTATION v160: fresh-bin exact-closure pair — leftover equal to next item means the
        // fresh bin will close perfectly after one more item; strong reward.
        if next_item_size > 0 && fresh_left == next_item_size as f64 && remaining > 50 {
            score -= 3.5;
        }
    } else {
        score += 60.0;
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        if remaining < 35 && next_item_size > 0 && pr == next_item_size {
            score -= 3.0;
        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 6 && fitting_bins_count > 2 {
            score -= 1.5;
        }
        if remaining < 30 && next_item_size > 0 && pr > 0 && pr >= next_item_size && pr - next_item_size <= 3 {
            score -= 2.0 * (1.0 - remaining as f64 / 30.0) * (1.0 - (pr - next_item_size) as f64 / 3.0);
        }
        if next_item_size > 0 && pr > 0 && pr < next_item_size && fitting_bins_count <= 2 && remaining > 40 {
            score += (next_item_size - pr) as f64 * 0.20;
        }
        if remaining >= 35 && remaining < 120 && next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 5 {
            score -= 1.0;
        }
        if remaining < 20 && pr > 0 && mean_residual > 1.0 && ((pr as f64) - mean_residual).abs() < 3.0 {
            score -= 1.5;
        }
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
        if remaining < 50 && next_item_size > 0 && pr > 0 && pr == next_item_size {
            score -= 2.5 * (1.0 - remaining as f64 / 50.0);
        }
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        if next_item_size > 0 && pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.0;
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 3 && fitting_bins_count <= 3 && remaining > 40 {
            score -= 1.8;
        }
        // MUTATION v158: endgame exact-closure widening — late stream, residuals that close
        // within one small step of the next item are nearly as good as exact closure.
        if remaining < 45 && next_item_size > 0 && pr > 0 && pr > next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 * (1.0 - remaining as f64 / 45.0) * (1.0 - (pr - next_item_size) as f64 / 2.0);
        }
        // MUTATION v159: endgame multi-slot closure — late stream, residuals holding two or
        // more exact next-items close out several items without opening bins.
        if remaining < 60 && next_item_size > 1 && pr > 0 && pr % next_item_size == 0 && pr / next_item_size >= 2 {
            score -= 2.0 * (1.0 - remaining as f64 / 60.0) * ((pr / next_item_size) as f64).min(3.0) * 0.5;
        }
        // MUTATION v160: endgame mean-residual sweep — late stream, residuals within the mean
        // residual band are likely to be consumed by remaining items; reward mildly.
        if remaining < 25 && pr > 0 && mean_residual > 1.0 && (pr as f64) <= mean_residual * 1.2 {
            score -= 1.2 * (1.0 - remaining as f64 / 25.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward
    if post_residual == 0 {
        score -= 500.0;
    }

    // Harmonic class of the post-residual: residuals that are "nice" fractions
    // of capacity (0, 25, 50, 75) are reusable dead-space classes.
    let cap = bin_capacity as f64;
    let quarter = (bin_capacity / 4) as u32;
    let half = (bin_capacity / 2) as u32;
    let three_quarter = (3 * bin_capacity / 4) as u32;
    let harmonic_bonus: f64 = if post_residual == half {
        -60.0
    } else if post_residual == quarter || post_residual == three_quarter {
        -40.0
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Integer-division class: post_residual modulo 10 — small moduli are easier to fill later
    let mod10 = (post_residual % 10) as f64;
    score += mod10 * 2.0; // penalize awkward residuals

    // Lookahead: if next item fits exactly into post_residual, strongly favor this bin
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= 80.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // next item cannot fit here: penalize proportionally to wasted potential
            score += 30.0 + (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are bad
    if bin_residual == bin_capacity {
        // neutral base; add penalty that shrinks as stream progresses
        score += 40.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
        // but if no open bin fits well, new bin becomes attractive
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Penalize leaving residuals far below mean (fragmentation)
    let dev = post_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += dev.abs() * 0.15;
    }

    // Coupling: prefer filling bins with large residual when many bins are open
    score -= (bin_residual as f64 / cap) * open_bins_count as f64 * 2.0;

    // Small tie-breaker on tightness
    score += (item_size as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for typical future items
    // (but nonzero) are the worst outcome. Treat gaps < 10 as near-wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 - (post_residual as f64) * 2.0; // small gap => big penalty
    } else if post_residual == 0 {
        // Perfect fit is gold: strong reward.
        score -= 25.0;
    }

    // Prefer filling larger residuals first (best-fit core), scaled by tightness.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 15.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another;
    // the new-bin candidate has bin_residual == bin_capacity so it gets penalized.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 30.0 + 20.0 * progress + (open_bins_count as f64).sqrt() * 5.0;
        // But if next item is large and this item leaves a big gap, opening fresh
        // can be fine: soften when post_residual large relative to next item.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    // Lookahead: reward placements that leave room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 {
            score += 5.0; // creates a gap next item can't use
        }
    }

    // Coupling with mean residual: placing into a bin below the mean residual
    // (larger-than-average hole) balances the fleet.
    if (bin_residual as f64) > mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chaining of two items
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize wasted space relative to capacity
            let wasted = post_residual as f64 / bin_capacity as f64;
            score += 15.0 * wasted;
        }
    }

    // Compare post_residual against mean residual: keep residual diversity low
    score += 0.5 * (post_residual as f64 - mean_residual).abs();

    // Penalize creating tiny unusable residuals (dead space below min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when item fits poorly everywhere
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        score += 20.0 * (1.0 - fit_quality); // large items make new bins attractive
        if fitting_bins_count == 1 {
            score -= 35.0; // but avoid abandoning the last fitting bin
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;
    let frag = pr as f64 - item_size as f64;

    // Dead-space avoidance: small gaps are heavily penalized.
    if pr > 0 && pr < 10 {
        score += 55.0;
    } else if pr < 25 {
        score += 22.0 * (1.0 - pr as f64 / 25.0);
    }

    // Reward near-perfect fills (widened exact-closure band).
    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 42.0;
    } else if pr <= 8 {
        score -= 16.0;
    } else if pr <= 12 {
        score -= 10.0;
    } else if pr <= 15 {
        score -= 4.0;
    } else if pr <= 25 {
        score -= 1.0;
    } else if pr <= 40 {
        score += 4.0;
    } else if pr <= 60 {
        score += 8.0;
    } else {
        score += 12.0;
    }

    // Lookahead: does the next item fit into the post-residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size > pr {
            let dead = (next_item_size - pr) as f64;
            let density = remaining as f64 / total_items.max(1) as f64;
            let scarcity = if fitting_bins_count <= 2 { 1.25 } else { 1.0 };
            score += pr as f64 * 0.5 + dead * (0.25 + 0.55 * density) * scarcity;
        } else {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 {
                score -= 5.0;
            }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 45.0 {
                score += (slack - 45.0) * 0.05;
            }
        }
        // Two-item lookahead: next item fits twice more.
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        // Chain-friendliness: residual divisible by next size.
        if pr > 0 && pr >= next_item_size && pr % next_item_size == 0 && pr / next_item_size >= 2 && remaining > 50 {
            score -= 2.0 * ((pr / next_item_size) as f64).min(3.0);
        }
        // Near-closure: leftover within 1-2 of next item size.
        if pr >= next_item_size && pr - next_item_size <= 1 {
            score -= 3.0;
        }
        // Penalize residual just below next item (guaranteed dead space).
        if frag > 0.0 && frag < next_item_size as f64 && next_item_size as f64 - frag <= 4.0 {
            score += (next_item_size as f64 - frag) * 0.9;
        }
        // Reward frag just above next item size (near-closure after next fit).
        if frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        // Multi-fit lookahead: repeated next-items with tiny remainder.
        if next_item_size > 1 && pr > 0 && pr >= next_item_size && pr / next_item_size >= 2 && pr % next_item_size <= 2 && remaining > 30 {
            score -= 1.6 * ((pr / next_item_size) as f64).min(4.0);
        }
        // Chained-divisibility bonus, stronger when bins are scarce.
        if next_item_size > 1 && pr > 0 && pr >= next_item_size {
            let rem_after = pr - next_item_size;
            if rem_after > 0 && rem_after % next_item_size == 0 && rem_after / next_item_size >= 2 && fitting_bins_count <= 3 && remaining > 60 {
                score -= 1.4 * ((rem_after / next_item_size) as f64).min(4.0);
            }
        }
        // Residual just below next item, mid-stream, with many alternatives — near-miss waste.
        if pr > 0 && pr < next_item_size && next_item_size - pr <= 6 && remaining > 30 && fitting_bins_count > 2 {
            score += (next_item_size - pr) as f64 * 0.45 * (1.0 - (next_item_size - pr) as f64 / 6.0);
        }
        // Large-dead-space avoidance when many alternatives exist.
        if pr > 0 && pr < next_item_size && next_item_size - pr > next_item_size / 2 && fitting_bins_count > 3 && remaining > 50 {
            score += (next_item_size - pr) as f64 * 0.30;
        }
        // Two-step closure — residual fits next item then a second one almost exactly.
        if next_item_size > 1 && pr >= item_size + next_item_size {
            let rest = pr - item_size - next_item_size;
            if rest >= next_item_size && rest - next_item_size <= 4 && remaining > 25 {
                score -= 2.2 * (1.0 - (rest - next_item_size) as f64 / 4.0);
            }
        }
        // Dead-space budget — remainder after one next-item slot matching the mean residual band.
        if pr > 0 && pr >= next_item_size {
            let rem_after = pr - next_item_size;
            if rem_after > 0 && (rem_after as f64 - mean_residual).abs() <= 2.0 && remaining > 20 {
                score -= 1.8 * (1.0 - (rem_after as f64 - mean_residual).abs() / 2.0);
            }
        }
        // Stranding risk coupling: residual well below mean residual mid-stream.
        if pr > 0 && mean_residual > 3.0 && (pr as f64) < mean_residual * 0.80 && remaining > 60 {
            score += (mean_residual * 0.80 - pr as f64) * (0.18 + 0.14 * progress);
        }
        // Residual barely above next item with many alternatives: mild waste signal.
        if pr > next_item_size && (pr - next_item_size) > 0 && (pr - next_item_size) < 14 && fitting_bins_count > 1 {
            let dead2 = (pr - next_item_size) as f64;
            score += dead2 * 0.10 * (1.0 - dead2 / 14.0);
        }
        // Next item fits and leaves room at least twice its size: good host.
        if pr > next_item_size && (pr - next_item_size) * 2 <= pr {
            score -= 1.2;
        }
        // MUTATION: gap-band penalty — residuals leaving a mid-range unusable gap (25-45) are poor hosts.
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 {
                score += (gap as f64 - 25.0) * 0.08;
            }
        }
        // MUTATION: exact-match with few alternatives — strong preference for the unique host.
        if pr == next_item_size && fitting_bins_count <= 2 {
            score -= 4.0;
        }
        // MUTATION: frag dead-space window with alternatives — small unusable remainder after next item.
        if frag > 0.0 && frag < next_item_size as f64 {
            let dead = next_item_size as f64 - frag;
            if dead > 6.0 && fitting_bins_count > 1 {
                score += dead * 0.12;
            }
        }
        // MUTATION: near-miss residual just below next item, long horizon — waste signal.
        if pr > 0 && pr < next_item_size && next_item_size - pr <= 3 && remaining > 80 {
            score += (next_item_size - pr) as f64 * 0.6;
        }
        // MUTATION v141: variance-aware near-miss — tight residual clusters make a post-residual
        // just below next_item waste a nearly full slot; escalate late.
        if pr > 0 && pr < next_item_size && mean_residual > 2.0 && (next_item_size as f64 - pr as f64) <= mean_residual * 0.7 && remaining > 50 {
            score += (next_item_size as f64 - pr as f64) * (0.35 + 0.25 * progress);
        }
        // MUTATION v141: half-capacity pairing — residual that holds next item plus a remainder
        // sized to the mean-residual band promises a second clean fit.
        if next_item_size > 1 && pr >= next_item_size * 2 {
            let rem_after = pr - next_item_size;
            if rem_after >= next_item_size && (rem_after - next_item_size) as f64 <= mean_residual * 0.5 && remaining > 40 {
                score -= 1.1 * (1.0 - (rem_after - next_item_size) as f64 / (mean_residual * 0.5 + 1.0)) * (0.6 + 0.6 * progress);
            }
        }
        // MUTATION v142: exact double-slot host — residual holding exactly two next-items with
        // zero slack is a perfect chain; reward scaled by remaining stream length.
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.4 * (1.0 - remaining as f64 / total_items.max(1) as f64);
        }
        // MUTATION v142: scarcity-escalated near-miss — residual just below next item with very
        // few fitting alternatives strands a nearly-full slot; penalize harder when scarce.
        if pr > 0 && pr < next_item_size && fitting_bins_count <= 2 && remaining > 40 {
            score += (next_item_size - pr) as f64 * 0.20;
        }
        // MUTATION v166: fine-grained residual fitting — combine slack-band reward with lookahead:
        // residuals that host next item and leave a remainder in the 1..=6 sweet band are prime
        // hosts for the small-item tail of the stream; reward scales with remaining horizon.
        if pr > next_item_size {
            let rem_after = pr - next_item_size;
            if rem_after >= 1 && rem_after <= 6 && remaining > 25 {
                score -= 2.6 * (1.0 - rem_after as f64 / 7.0) * (0.5 + 0.5 * progress);
            }
        }
        // MUTATION v166: combined fit+lookahead — residual that holds next item twice AND whose
        // final remainder is either zero or exactly the mean residual is a dual-purpose host.
        if next_item_size > 1 && pr >= next_item_size * 2 {
            let rem2 = pr - next_item_size * 2;
            if rem2 == 0 {
                score -= 1.5;
            } else if mean_residual > 1.0 && (rem2 as f64 - mean_residual).abs() <= 1.5 && remaining > 30 {
                score -= 1.3 * (1.0 - (rem2 as f64 - mean_residual).abs() / 1.5);
            }
        }
        // MUTATION v166: mid-gap trap — post-residual that cannot hold the next item twice but
        // leaves a stranded 7..=18 remainder with many alternatives; penalize mildly.
        if next_item_size > 1 && pr > next_item_size {
            let rem_after = pr - next_item_size;
            if rem_after >= 7 && rem_after < next_item_size && rem_after <= 18 && fitting_bins_count > 2 && remaining > 40 {
                score += rem_after as f64 * 0.09;
            }
        }
        // MUTATION v166: scarcity-protected large residual — when almost nothing else fits the
        // item, a roomy residual is valuable regardless of waste; soften waste penalties.
        if fitting_bins_count <= 1 && pr >= next_item_size {
            score -= 1.5;
        }
    }

    // Open-bin pressure: prefer tighter packing when many bins are open.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Slight bias toward bins with larger residuals (better long-term hosts).
    score -= (bin_residual as f64 - mean_residual) * 0.2;

    // Fragments larger than mean residual waste capacity going forward.
    if frag > mean_residual && frag > 12.0 && remaining > 30 {
        score += (frag - mean_residual) * 0.06;
    }
    // Very large fragments waste even more.
    if frag > 40.0 && remaining > 60 {
        score += (frag - 40.0) * 0.05;
    }
    // MUTATION: frag trapped between one and two next-items — dead space signal.
    if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
        score += (frag - next_item_size as f64) * 0.10;
        if mean_residual < 16.0 && remaining > 100 {
            score += (frag - next_item_size as f64) * 0.08;
        }
    }
    // Small-item fragmentation guard: small items in big holes waste future capacity.
    let fill_ratio = item_size as f64 / bin_capacity.max(1) as f64;
    if frag > 0.0 && fill_ratio < 0.42 && remaining > 40 {
        score += (0.42 - fill_ratio) * 16.0 * (1.0 - progress * 0.5);
    }
    // MUTATION: extra waste term for fragments far above mean residual.
    if frag > 0.0 && frag > mean_residual * 1.6 && remaining > 30 {
        score += (frag - mean_residual * 1.6) * 0.04;
    }

    // Late in the stream, tighten packing further.
    score += pr as f64 * (0.1 + 0.22 * progress);

    // Residual close to mean residual is a good host for future items.
    if pr > 0 && mean_residual > 1.0 {
        let dev = ((pr as f64 - mean_residual) / mean_residual).abs();
        if dev < 0.3 {
            score -= 2.0 * (1.0 - dev / 0.3);
        } else if dev > 1.5 && pr as f64 > mean_residual * 2.0 {
            score += 2.5;
        }
    }
    // MUTATION: residual just under mean residual — stranding risk when mean need is close.
    if pr > 0 && mean_residual > 2.0 && (pr as f64) < mean_residual && (mean_residual - pr as f64) < 6.0 {
        score += (mean_residual - pr as f64) * 0.35;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let crowding = (open_bins_count as f64 / (total_items.max(1) as f64 / 4.0)).min(1.0);
        let waste_pressure = if mean_residual < 18.0 { 4.0 } else { 0.0 };
        score += 8.0 + crowding * 6.0 + waste_pressure + (fitting_bins_count == 0) as i32 as f64 * 40.0;
        let item_ratio = item_size as f64 / bin_capacity.max(1) as f64;
        // Large items: better to start a fresh bin than fragment a good one.
        if item_ratio > 0.6 && remaining > 20 {
            score -= 2.5 * item_ratio;
        }
        if item_ratio > 0.85 && remaining > 150 {
            score -= 2.0;
        }
        // Fresh bin leaves a large usable residual matching mean need.
        let fresh_left = bin_capacity.saturating_sub(item_size) as f64;
        if remaining > 60 && fresh_left > 0.0 && fresh_left < mean_residual * 1.25 && open_bins_count > 0 {
            score += (mean_residual * 1.25 - fresh_left) * 0.38;
        }
        if fresh_left <= 6.0 && remaining > 30 {
            score -= 4.0;
        }
        // Fresh leftover near mean residual is chain-friendly.
        if fresh_left > 0.0 && mean_residual > 1.0 && remaining > 40 {
            let d = (fresh_left - mean_residual).abs();
            if d < 4.0 {
                score -= 2.0 * (1.0 - d / 4.0);
            }
        }
        // Discourage fresh bin when leftover sits just under next item (dead space).
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && (next_item_size as f64 - fresh_left) <= 8.0 && remaining > 40 {
            score += (next_item_size as f64 - fresh_left) * 0.5;
        }
        // Fresh-bin near-miss guard, stronger with alternatives available.
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && (next_item_size as f64 - fresh_left) <= 5.0 && remaining > 60 && fitting_bins_count > 1 {
            score += (next_item_size as f64 - fresh_left) * 0.8;
        }
        // Reward fresh bin when leftover is an exact multiple of next size.
        if next_item_size > 2 && fresh_left > 0.0 && fresh_left % next_item_size as f64 == 0.0 && fresh_left / next_item_size as f64 >= 2.0 && remaining > 60 {
            score -= 2.5;
        }
        // Chained-divisibility refinement for fresh bins.
        if next_item_size > 1 && fresh_left > next_item_size as f64 && ((fresh_left - next_item_size as f64) as u32) % next_item_size == 0 && remaining > 80 {
            score -= 1.2;
        }
        if mean_residual < 12.0 && remaining > 50 {
            score -= 3.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity * 3 / 4 {
            score -= 5.0;
        }
        if fitting_bins_count > 0 {
            score += 4.0;
        }
        if remaining < 8 && fitting_bins_count > 0 {
            score += 5.0;
        }
        if remaining < 25 && fitting_bins_count > 0 && mean_residual < item_size as f64 {
            score += 4.0;
        }
        // Next item won't fit alongside this item in a fresh bin — penalty for opening.
        if next_item_size > 0 && item_size + next_item_size > bin_capacity && remaining > 30 && open_bins_count > 0 && mean_residual >= next_item_size as f64 {
            score += 6.0;
        }
        // Fresh-bin multi-fit lookahead.
        if next_item_size > 1 && fresh_left >= (next_item_size * 3) as f64 && remaining > 50 {
            score -= 2.0;
        }
        // Fresh-bin mean-alignment bonus.
        if fresh_left > 0.0 && mean_residual > 4.0 && (fresh_left - mean_residual).abs() <= 3.0 && remaining > 40 && open_bins_count > 2 {
            score -= 1.5 * (1.0 - (fresh_left - mean_residual).abs() / 3.0);
        }
        // Fresh bin with mean residual well below its leftover: likely stranded space.
        if fresh_left > 0.0 && mean_residual > 2.0 && fresh_left > mean_residual * 1.8 && remaining > 100 && open_bins_count > 3 {
            score -= 1.5;
        }
        // Small next item with open bins able to host it — discourage opening a fresh bin.
        if next_item_size > 0 && next_item_size <= 10 && mean_residual >= next_item_size as f64 {
            score += 3.0;
        }
        // Mean residual near next item with alternatives — reuse beats opening.
        if next_item_size > 0 && mean_residual >= next_item_size as f64 && fitting_bins_count >= 2 {
            score += 2.0;
        }
        // Large item, mean residual too small for it — fresh bin may be the only sane host.
        if item_ratio > 0.75 && mean_residual > 20.0 && mean_residual < item_size as f64 {
            score -= 3.0;
        }
        // Mean residual just above next item size — fresh leftover will be reused soon.
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
        // Endgame — strong bias against opening bins when alternatives exist.
        if remaining < 12 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
        if fitting_bins_count > 0 && fresh_left <= 3.0 && item_ratio > 0.9 {
            score -= 5.0;
        }
        // MUTATION: fresh bin whose leftover exactly matches next item is a good opening.
        if next_item_size > 0 && fresh_left == next_item_size as f64 && remaining > 30 {
            score -= 3.0;
        }
        // MUTATION v141: fresh-bin double-slot divisibility — leftover holds exactly two next-items
        // with zero slack is a near-perfect opening; reward scaled by stream progress.
        if next_item_size > 1 && fresh_left == (next_item_size * 2) as f64 && remaining > 40 {
            score -= 2.2 * (1.0 - remaining as f64 / total_items.max(1) as f64);
        }
        // MUTATION v141: mean residual high with long horizon — fresh bin more likely to be reused.
        if mean_residual > 30.0 && remaining > 100 {
            score -= 2.0;
        }
        // MUTATION v142: fresh-bin exact-triple opening — leftover holds exactly three next-items
        // with zero slack is an excellent long-horizon opening.
        if next_item_size > 1 && fresh_left == (next_item_size * 3) as f64 && remaining > 60 {
            score -= 1.8;
        }
        // MUTATION v166: fresh-bin sweet-band opening — leftover that hosts next item and leaves
        // a 1..=6 remainder promises a near-closed chain; reward with horizon scaling.
        if next_item_size > 0 && fresh_left > next_item_size as f64 {
            let rem_after = fresh_left - next_item_size as f64;
            if rem_after >= 1.0 && rem_after <= 6.0 && remaining > 40 {
                score -= 2.0 * (1.0 - rem_after / 7.0);
            }
        }
        // MUTATION v166: fresh-bin dead remainder — leftover that leaves a stranded 7..=18 gap
        // after hosting next item, with alternatives available, is a poor opening.
        if next_item_size > 1 && fresh_left > next_item_size as f64 {
            let rem_after = fresh_left - next_item_size as f64;
            if rem_after >= 7.0 && rem_after < next_item_size as f64 && rem_after <= 18.0 && fitting_bins_count > 2 && remaining > 40 {
                score += rem_after * 0.12;
            }
        }
    } else {
        score += 60.0;
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        // Endgame: strong bonus for exact-closure residuals.
        if remaining < 35 && next_item_size > 0 && pr == next_item_size {
            score -= 3.0;
        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 6 && fitting_bins_count > 2 {
            score -= 1.5;
        }
        // Endgame two-item closure.
        if remaining < 30 && next_item_size > 0 && pr > 0 && pr >= next_item_size && pr - next_item_size <= 3 {
            score -= 2.0 * (1.0 - remaining as f64 / 30.0) * (1.0 - (pr - next_item_size) as f64 / 3.0);
        }
        // Scarcity-aware waste — near-miss residuals with few alternatives are costly late.
        if next_item_size > 0 && pr > 0 && pr < next_item_size && fitting_bins_count <= 2 && remaining > 40 {
            score += (next_item_size - pr) as f64 * 0.20;
        }
        // Mid-stream near-closure window.
        if remaining >= 35 && remaining < 120 && next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 5 {
            score -= 1.0;
        }
        // Endgame mean-residual alignment.
        if remaining < 20 && pr > 0 && mean_residual > 1.0 && ((pr as f64) - mean_residual).abs() < 3.0 {
            score -= 1.5;
        }
        // Many alternatives and residual leaves more dead space than mean: deprioritize.
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
        // Widened endgame exact-closure — late stream, prefer fits that zero the residual.
        if remaining < 50 && next_item_size > 0 && pr > 0 && pr == next_item_size {
            score -= 2.5 * (1.0 - remaining as f64 / 50.0);
        }
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        // Two-step exact closure — residual fits item then next item exactly.
        if next_item_size > 0 && pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        // MUTATION: mid-stream residual that holds next item twice exactly — strong host.
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.0;
        }
        // MUTATION v142: scarcity-aware triple closure — residual that holds next item three times
        // exactly with few alternatives is a near-perfect multi-fit host.
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 3 && fitting_bins_count <= 3 && remaining > 40 {
            score -= 1.8;
        }
        // MUTATION v166: endgame sweet-band closure — residuals leaving a 1..=6 remainder after
        // hosting next item close out cleanly late; reward scaled by urgency.
        if next_item_size > 0 && pr > next_item_size && remaining < 60 {
            let rem_after = pr - next_item_size;
            if rem_after >= 1 && rem_after <= 6 {
                score -= 1.6 * (1.0 - remaining as f64 / 60.0) * (1.0 - rem_after as f64 / 7.0);
            }
        }
    }

    score
}

