pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fits.
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space relative to smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score -= 25.0; // nearly perfect fill
    } else if post_residual >= 10 {
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in post_residual, reward; else penalize.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else {
            let waste_gap = next_item_size as f64 - post_residual as f64;
            score += 0.4 * waste_gap;
        }
    }

    // New-bin candidate logic: only attractive when open bins are crowded
    // or mean residual is too small for typical future items.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
        let pressure = (mean_residual < item_size as f64) as i32 as f64 * 20.0;
        let new_bin_bonus = 8.0 + 20.0 * progress + 0.05 * crowded + pressure;
        // New bin has residual = capacity - item_size; compare fairly.
        score -= new_bin_bonus;
        // Discard new-bin option if an open bin fits well (high fit_ratio elsewhere is cheap anyway).
        if fit_ratio > 0.85 && !fitting_bins_count.eq(&0) {
            score += 25.0;
        }
    } else {
        // Favor bins whose residual is small (consolidation).
        score += 0.1 * (mean_residual - bin_residual as f64).abs();

        // Reward spreading load when many bins are open and mean residual is high.
        if bin_residual as f64 > mean_residual && open_bins_count > 2 {
            score -= 3.0;
        }
    }

    // Mild time-horizon modulation: early on, be conservative (avoid fragmentation);
    // late, prefer filling existing bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 0.1 * post_residual as f64;
    score -= progress * 5.0;

    score
}

