            score -= 1.2 * (1.0 - (pr as f64 - mean_residual).abs() / 2.0) * (0.5 + 0.5 * density_proxy(remaining, total_items));
        }
        // MUTATION v167: exact triple-slot host with scarcity — near-perfect multi-fit host.
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 3 && fitting_bins_count <= 3 && remaining > 40 {
            score -= 1.8;
        }
    }

    // Open-bin pressure.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Bias toward bins with larger residuals.
