        }
        if remaining < 20 && pr > 0 && mean_residual > 1.0 && ((pr as f64) - mean_residual).abs() < 3.0 {
            score -= 1.5;
        }
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
        if remaining < 50 && next_item_size > 0 && pr > 0 && pr == next_item_size {
            score -= 2.5 * (1.0 - remaining as f64 / 50.0);
        }
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        if next_item_size > 0 && pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.0;
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 3 && fitting_bins_count <= 3 && remaining > 40 {
            score -= 1.8;
        }
        // MUTATION v167: density-weighted near-closure — mid-stream residuals leaving 1-5
        // slack above the next item are strong hosts; reward more when many items remain.
        if next_item_size > 0 && pr > 0 && pr > next_item_size && pr - next_item_size <= 5 && remaining > 120 {
            score -= (5 - (pr - next_item_size)) as f64 * 0.35;
        }
    }

    score
}

fn density_proxy(remaining: usize, total_items: usize) -> f64 {
    remaining as f64 / total_items.max(1) as f64
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let base = pr;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    // Smooth non-linear coupling of post_residual with stream progress
    let progress_term = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    let mut score = base * (1.0 + 0.15 * progress_term * (pr / cap));
    // Reward tight fits (small post_residual), smoothly
    score -= (1.0 - pr / cap).powi(3) * 12.0;
    // Penalize dead space that can't fit a typical next item, smooth ramp
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += gap * gap * 20.0;
        // Reward residual that exactly accommodates the lookahead item
        let fit_lookahead = ((pr - next_item_size as f64) / cap).abs();
        score -= (-fit_lookahead * 8.0).exp() * 6.0;
    }
    // Last-chance bonus: smooth decay as fitting bins increase
    if fitting_bins_count > 0 {
        score -= 1.0 / (fitting_bins_count as f64).powi(2);
    }
    // Slight preference for balancing residuals across open bins
    score += ((pr - mean_residual) / cap).abs() * 2.0;
    // New-bin candidate: penalize mildly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 8.0 + 6.0 * progress;
    }
    score
}

