        }
        // MUTATION v159: endgame multi-slot closure.
        if remaining < 60 && next_item_size > 1 && pr > 0 && pr % next_item_size == 0 && pr / next_item_size >= 2 {
            score -= 2.0 * (1.0 - remaining as f64 / 60.0) * ((pr / next_item_size) as f64).min(3.0) * 0.5;
        }
        // MUTATION v167: endgame mean-band closure — late stream, residuals whose leftover after
        // the next item sits within the mean residual band are likely to close cleanly soon.
        if remaining < 50 && next_item_size > 1 && pr > next_item_size {
            let rem_after = pr - next_item_size;
            if rem_after > 0 && mean_residual > 1.0 && (rem_after as f64 - mean_residual).abs() <= 2.0 {
                score -= 1.4 * (1.0 - remaining as f64 / 50.0) * (1.0 - (rem_after as f64 - mean_residual).abs() / 2.0);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual lands on coarse
    // capacity fractions (>= half, quarter) are more reusable.
    let pr = post_residual;
    let prf = pr as f64;
    if pr == 0 {
        score -= 60.0; // perfect fill
    } else {
        // class by integer division thresholds
        if pr >= bin_capacity / 2 {
            score -= 25.0;
        } else if pr >= bin_capacity / 4 {
            score -= 10.0;
        } else if pr >= bin_capacity / 8 {
            score -= 3.0;
        } else {
            score += 15.0; // tiny dead space class
        }
        // modulo structure: residuals divisible by common item granularities
        if pr % 10 == 0 {
            score -= 8.0;
        } else if pr % 5 == 0 {
            score -= 4.0;
        }
        // odd/prime-ish residuals are harder to fill
        if pr % 2 == 1 {
            score += 2.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / cap);
            if slack as u32 <= bin_capacity / 10 {
                score -= 6.0; // near-exact chained fit
            }
        } else {
            score += 10.0; // next item won't fit here: residual likely dead
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current bin would be
    // badly fragmented or no good fit exists.
    if bin_residual == bin_capacity {
        let tight = (post_residual as f64) / cap;
        score = 55.0 + 40.0 * (1.0 - tight) - 8.0 * (open_bins_count as f64).ln().max(0.0);
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a bin
        }
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 15.0; // big next item: fresh bin useful
        }
    }

    // Wasted-fraction penalty (non-linear in fill ratio).
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= 20.0 * fill * fill;

    // Late in the stream: consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - prf / cap);

    // Prefer bins below mean residual (keeps residuals balanced).
    score += 0.3 * (prf - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
