    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale post_residual by how full the bin becomes.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * (bin_capacity as f64 * 0.5);

    // Penalize dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else if post_residual == next_item_size {
            // Perfect handoff to next item: strong reward.
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + item_size as f64 * 0.2;
    }

    // Penalize opening a new bin when plenty of open bins exist and item is small.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = mean_residual / bin_capacity as f64;
        score += 40.0 * (1.0 - progress) + open_bins_count as f64 * 3.0 - pressure * 20.0;
        if item_size > bin_capacity / 2 {
            score -= 15.0; // big items justify fresh bins
        }
    } else {
        // Mild reward for placing into already-open bins when mean residual is high.
        score -= (mean_residual - post_residual as f64).abs() * 0.05;
    }

    // Slight preference for bins with residual closest to item (best-fit flavor).
    score += (bin_residual as f64 - item_size as f64) * 0.1;

    score
}

