            score -= 1.0 + 0.5 * progress;
        }
        // MUTATION v172: divisibility ladder — post-residuals one or two units above an
        // exact multiple of next_item are nearly as chainable; decayed reward.
        if next_item_size > 1 && pr > 0 && pr >= next_item_size && remaining > 25 {
            let k = pr / next_item_size;
            let rem = pr % next_item_size;
            if k >= 2 && rem > 0 && rem <= 2 {
                score -= (1.4 - 0.45 * rem as f64) * (0.4 + 0.5 * (1.0 - progress));
            }
        }
        // MUTATION v172: mean-band tightening after a fit — leftover after placing next_item
        // just above mean residual is most likely reused by the typical item.
        if next_item_size > 1 && pr > 0 && pr >= next_item_size && mean_residual > 3.0 && remaining > 40 {
            let rem_after = (pr - next_item_size) as f64;
            if rem_after > mean_residual && rem_after - mean_residual <= 3.0 {
                score -= (3.0 - (rem_after - mean_residual)) * 0.35 * (0.6 + 0.4 * progress);
            }
        }
        // MUTATION v172: dead-space ratio suppression — post-fit leftovers too small to
        // host a typical item, extended smoothly into the mean*0.5..mean*0.75 band.
        if pr > 0 && mean_residual > 4.0 && (pr as f64) < mean_residual * 0.5 && remaining > 80 {
            score += (mean_residual * 0.5 - pr as f64) * 0.22 * (1.0 - progress * 0.4);
        }
        if pr > 0 && mean_residual > 4.0 && (pr as f64) >= mean_residual * 0.5 && (pr as f64) < mean_residual * 0.75 && remaining > 60 {
            score += (mean_residual * 0.75 - pr as f64) * 0.09 * (1.0 - progress * 0.3);
        }
        // MUTATION v172: near-closure bonus — post-residual within 2 of zero is a near-perfect fill.
