        }
        // Exact-closure divisors.
        if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 && pr / next_item_size >= 2 {
            let slots = (pr / next_item_size) as f64;
            let density = remaining as f64 / total_items.max(1) as f64;
            score -= 0.8 * slots.min(4.0) * (0.5 + 0.5 * density);
