        if next_item_size > 1 && pr > 0 && pr >= next_item_size && mean_residual > 3.0 && remaining > 40 {
            let rem_after = (pr - next_item_size) as f64;
            if rem_after > mean_residual && rem_after - mean_residual <= 3.0 {
