        }
        // MUTATION v174: near-closure bonus — post-residual within 2 of zero is a near-perfect
        // fill, reward more strongly mid-stream.
        if pr > 0 && pr <= 2 && remaining > 30 {
            score -= 3.0 * (1.0 - progress * 0.5);
        }
        // MUTATION v174: dead-space ratio suppression — penalize post-fit leftovers too small
        // to host a typical item, with a smooth extension into the mean*0.5..mean*0.75 band.
        if pr > 0 && mean_residual > 4.0 && (pr as f64) < mean_residual * 0.5 && remaining > 80 {
            score += (mean_residual * 0.5 - pr as f64) * 0.22 * (1.0 - progress * 0.4);
        }
        if pr > 0 && mean_residual > 4.0 && (pr as f64) >= mean_residual * 0.5 && (pr as f64) < mean_residual * 0.75 && remaining > 60 {
            score += (mean_residual * 0.75 - pr as f64) * 0.09 * (1.0 - progress * 0.3);
