        }
        if next_item_size > 0 && fresh_left == next_item_size as f64 && remaining > 30 {
            score -= 3.0;
        }
        if next_item_size > 1 && fresh_left == (next_item_size * 2) as f64 && remaining > 40 {
            score -= 2.2 * (1.0 - remaining as f64 / total_items.max(1) as f64);
        }
        if mean_residual > 30.0 && remaining > 100 {
            score -= 2.0;
        }
        if next_item_size > 1 && fresh_left == (next_item_size * 3) as f64 && remaining > 60 {
            score -= 1.8;
        }
        // Fresh-bin dead-space guard.
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && remaining > 100 {
            score += (next_item_size as f64 - fresh_left) * 0.25;
        }
        // Fresh-bin exact-multiple slot bonus.
        if next_item_size > 1 && fresh_left > 0.0 && (fresh_left as u32) % next_item_size == 0 && (fresh_left as u32) / next_item_size >= 2 && remaining > 80 {
            score -= 1.5 * ((fresh_left as u32 / next_item_size) as f64).min(4.0);
        }
        // Fresh-bin near-miss scarcity guard.
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && fitting_bins_count >= 3 && remaining > 50 {
            score += (next_item_size as f64 - fresh_left) * 0.45;
        }
        // fresh-bin exact-quadruple opening — long-horizon multi-fit opening.
        if next_item_size > 1 && fresh_left == (next_item_size * 4) as f64 && remaining > 80 {
            score -= 1.5;
        }
        // fresh-bin mean-band alignment with lookahead.
        if fresh_left > 0.0 && mean_residual > 3.0 && (fresh_left - mean_residual).abs() <= mean_residual * 0.25 && remaining > 50 && open_bins_count > 0 {
            score -= 1.0 * (1.0 - (fresh_left - mean_residual).abs() / (mean_residual * 0.25 + 1.0)) * (0.5 + 0.5 * progress);
        }
        // MUTATION v174: fresh-bin dead-space guard smoothing — extend into the
        // mean*0.55..mean*0.75 band with a mild slope for continuous ranking.
        if fresh_left > 0.0 && mean_residual > 5.0 && fresh_left >= mean_residual * 0.55 && fresh_left < mean_residual * 0.75 && fitting_bins_count >= 2 && remaining > 60 {
            score += (mean_residual * 0.75 - fresh_left) * 0.10;
        }
        // MUTATION v174: fresh-bin near-multiple ladder — openings one or two units above an
        // exact multiple of next_item are almost as chainable; decayed reward.
        if next_item_size > 1 && fresh_left > 0.0 && fresh_left >= (next_item_size * 2) as f64 && remaining > 70 {
            let rem = (fresh_left as u32) % next_item_size;
            if rem > 0 && rem <= 2 {
                score -= 0.7 - 0.2 * rem as f64;
            }
        }
        // MUTATION v174: fresh-bin wedge guard — a new bin whose leftover falls in the
        // stranded dead-zone is a poor opening when alternatives exist.
        if fresh_left > 0.0 && next_item_size > 1 && mean_residual > 3.0 && fresh_left < next_item_size as f64 && fresh_left > mean_residual * 0.6 && fitting_bins_count >= 1 && remaining > 60 {
            score += (next_item_size as f64 - fresh_left) * 0.22;
        }
        // MUTATION v174: crowding-aware large-item opening — when crowded and the item is
        // large, opening a fresh bin is usually cheaper than fragmenting an open bin.
        if item_ratio > 0.7 && open_bins_count > 3 && remaining > 40 && mean_residual < item_size as f64 {
            score -= 1.6 * (item_ratio - 0.7) * 3.0;
        }
    } else {
        score += 60.0;
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        if remaining < 35 && next_item_size > 0 && pr == next_item_size {
            score -= 3.0;
        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 6 && fitting_bins_count > 2 {
            score -= 1.5;
        }
        if remaining < 30 && next_item_size > 0 && pr > 0 && pr >= next_item_size && pr - next_item_size <= 3 {
            score -= 2.0 * (1.0 - remaining as f64 / 30.0) * (1.0 - (pr - next_item_size) as f64 / 3.0);
        }
        if next_item_size > 0 && pr > 0 && pr < next_item_size && fitting_bins_count <= 2 && remaining > 40 {
            score += (next_item_size - pr) as f64 * 0.20;
        }
        if remaining >= 35 && remaining < 120 && next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 5 {
            score -= 1.0;
        }
        if remaining < 20 && pr > 0 && mean_residual > 1.0 && ((pr as f64) - mean_residual).abs() < 3.0 {
            score -= 1.5;
        }
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
        if remaining < 50 && next_item_size > 0 && pr > 0 && pr == next_item_size {
            score -= 2.5 * (1.0 - remaining as f64 / 50.0);
        }
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        if next_item_size > 0 && pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.0;
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 3 && fitting_bins_count <= 3 && remaining > 40 {
            score -= 1.8;
        }
        // Endgame exact-closure widening.
        if remaining < 45 && next_item_size > 0 && pr > 0 && pr > next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 * (1.0 - remaining as f64 / 45.0) * (1.0 - (pr - next_item_size) as f64 / 2.0);
        }
        // Endgame multi-slot closure.
        if remaining < 60 && next_item_size > 1 && pr > 0 && pr % next_item_size == 0 && pr / next_item_size >= 2 {
            score -= 2.0 * (1.0 - remaining as f64 / 60.0) * ((pr / next_item_size) as f64).min(3.0) * 0.5;
        }
        // mean-band two-slot closure — remainder after one next-item slot
        // within a tight band around the mean residual promises tight compaction.
        if next_item_size > 1 && pr > 0 && pr > next_item_size {
            let rem_after = pr - next_item_size;
            if rem_after > 0 && mean_residual > 2.0 && (rem_after as f64 - mean_residual).abs() <= mean_residual * 0.2 && remaining > 30 {
                score -= 1.2 * (1.0 - (rem_after as f64 - mean_residual).abs() / (mean_residual * 0.2 + 1.0)) * (0.4 + 0.6 * progress);
            }
        }
        // MUTATION v174: non-fresh divisibility closure — exact multiples of next_item in
        // open bins are reliable chained fits; reward deeper multiples with mild decay.
        if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 && pr / next_item_size >= 2 && remaining > 30 {
            let k = (pr / next_item_size) as f64;
            score -= 0.9 + 0.25 * (k - 2.0).min(4.0);
        }
        // MUTATION v174: non-fresh near-multiple closure — leftovers one or two units above a
        // multiple of next_item still chain well; mild decayed reward.
        if next_item_size > 1 && pr > 0 && pr >= next_item_size * 2 && remaining > 30 {
            let rem = pr % next_item_size;
            if rem > 0 && rem <= 2 {
                score -= 0.6 - 0.2 * rem as f64;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.86;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;
    let frag = pr as f64 - item_size as f64;

    // Small-residual dead-space bands.
    if pr > 0 && pr < 10 {
        score += 55.0;
    } else if pr < 25 {
        score += 22.0 * (1.0 - pr as f64 / 25.0);
    }

    // Near-perfect fill rewards (widened exact-closure band).
    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 42.0;
    } else if pr <= 8 {
        score -= 16.0;
    } else if pr <= 12 {
        score -= 10.0;
    } else if pr <= 15 {
        score -= 4.0;
    } else if pr <= 25 {
        score -= 1.0;
    } else if pr <= 40 {
        score += 4.0;
    } else if pr <= 60 {
        score += 8.0;
    } else {
        score += 12.0;
    }

    // MUTATION v176: near-closure bonus — post-residual within 2 of zero is a near-perfect fill.
    if pr > 0 && pr <= 2 && remaining > 30 {
        score -= 3.0 * (1.0 - progress * 0.5);
    }

    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size > pr {
            let dead = (next_item_size - pr) as f64;
            let density = remaining as f64 / total_items.max(1) as f64;
            let scarcity = if fitting_bins_count <= 2 { 1.25 } else { 1.0 };
            score += pr as f64 * 0.5 + dead * (0.25 + 0.55 * density) * scarcity;
        } else {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 {
                score -= 5.0;
            }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 45.0 {
                score += (slack - 45.0) * 0.05;
