        }
        if next_item_size > 0 && (mean_residual as u32) >= next_item_size && (mean_residual as u32) - next_item_size <= 3 && remaining > 40 {
            score += 3.5;
        }
        if remaining < 12 && fitting_bins_count > 0 {
            score += 4.0;
        }
        if next_item_size > 0 && open_bins_count > 5 && mean_residual >= next_item_size as f64 && remaining < 40 {
            score += 3.0;
        }
        if fitting_bins_count > 0 && fresh_left <= 3.0 && item_ratio > 0.9 {
            score -= 5.0;
        }
        if next_item_size > 0 && fresh_left == next_item_size as f64 && remaining > 30 {
            score -= 3.0;
        }
        if next_item_size > 1 && fresh_left == (next_item_size * 2) as f64 && remaining > 40 {
            score -= 2.2 * (1.0 - remaining as f64 / total_items.max(1) as f64);
        }
        if mean_residual > 30.0 && remaining > 100 {
            score -= 2.0;
        }
        if next_item_size > 1 && fresh_left == (next_item_size * 3) as f64 && remaining > 60 {
            score -= 1.8;
        }
        // Fresh-bin dead-space guard.
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && remaining > 100 {
            score += (next_item_size as f64 - fresh_left) * 0.25;
        }
        // Fresh-bin exact-multiple slot bonus.
        if next_item_size > 1 && fresh_left > 0.0 && (fresh_left as u32) % next_item_size == 0 && (fresh_left as u32) / next_item_size >= 2 && remaining > 80 {
            score -= 1.5 * ((fresh_left as u32 / next_item_size) as f64).min(4.0);
        }
        // Fresh-bin near-miss scarcity guard.
        if next_item_size > 0 && fresh_left > 0.0 && fresh_left < next_item_size as f64 && fitting_bins_count >= 3 && remaining > 50 {
            score += (next_item_size as f64 - fresh_left) * 0.45;
        }
        // Fresh-bin exact-quadruple opening.
        if next_item_size > 1 && fresh_left == (next_item_size * 4) as f64 && remaining > 80 {
            score -= 1.5;
        }
        // Fresh-bin mean-band alignment with lookahead.
        if fresh_left > 0.0 && mean_residual > 3.0 && (fresh_left - mean_residual).abs() <= mean_residual * 0.25 && remaining > 50 && open_bins_count > 0 {
            score -= 1.0 * (1.0 - (fresh_left - mean_residual).abs() / (mean_residual * 0.25 + 1.0)) * (0.5 + 0.5 * progress);
        }
        // scarcity-weighted fresh-bin dead-space guard — bite harder when many open bins can host the item.
        if fresh_left > 0.0 && mean_residual > 5.0 && fresh_left < mean_residual * 0.75 && fitting_bins_count >= 2 && remaining > 70 {
            let scarcity = 1.0 / (1.0 + (fitting_bins_count as f64 - 2.0).max(0.0) * 0.35);
            score += (mean_residual * 0.75 - fresh_left).max(0.0) * 0.12 * scarcity;
        }
        // waste-pressure adaptive base — scale fresh-bin penalty by mean-residual band.
        score += if mean_residual < 6.0 { 3.0 } else if mean_residual < 14.0 { 0.0 } else { -(mean_residual - 14.0).min(12.0) * 0.25 };
        // crowding-aware large-item fresh opening.
        if item_ratio > 0.7 && open_bins_count > 3 && remaining > 40 && mean_residual < item_size as f64 {
            score -= 1.6 * (item_ratio - 0.7) * 3.0;
        }
        // MUTATION v178: fresh-bin scarcity relief — when the fresh bin is the only viable host for a large item deep in the stream, release opening pressure so big items get clean bins instead of shattering a tight residual.
        if fitting_bins_count == 0 && item_ratio > 0.55 && remaining > 50 {
            score -= (item_ratio - 0.55) * 10.0 * (1.0 - progress * 0.4);
        }
        // MUTATION v178: tail-stream fresh-bin throttle — near the end of the stream, a fresh bin's leftover will almost never be reused; lift the base penalty when alternatives exist.
        if remaining < 20 && fresh_left > 0.0 && fitting_bins_count > 0 {
            score += (20.0 - remaining as f64) * 0.30;
        }
        // MUTATION v178: fresh-bin near-multiple ladder — openings whose leftover sits one or two units above an exact multiple of next_item are nearly as chainable; reward with a decayed slope.
        if next_item_size > 1 && fresh_left > 0.0 && fresh_left >= (next_item_size * 2) as f64 && remaining > 70 {
            let rem = (fresh_left as u32) % next_item_size;
            if rem > 0 && rem <= 2 {
                score -= 0.7 - 0.2 * rem as f64;
            }
        }
    } else {
        score += 60.0;
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        if remaining < 35 && next_item_size > 0 && pr == next_item_size {
            score -= 3.0;
        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 6 && fitting_bins_count > 2 {
            score -= 1.5;
        }
        if remaining < 30 && next_item_size > 0 && pr > 0 && pr >= next_item_size && pr - next_item_size <= 3 {
            score -= 2.0 * (1.0 - remaining as f64 / 30.0) * (1.0 - (pr - next_item_size) as f64 / 3.0);
        }
        if next_item_size > 0 && pr > 0 && pr < next_item_size && fitting_bins_count <= 2 && remaining > 40 {
            score += (next_item_size - pr) as f64 * 0.20;
        }
        if remaining >= 35 && remaining < 120 && next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 5 {
            score -= 1.0;
        }
        if remaining < 20 && pr > 0 && mean_residual > 1.0 && ((pr as f64) - mean_residual).abs() < 3.0 {
            score -= 1.5;
        }
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
        if remaining < 50 && next_item_size > 0 && pr > 0 && pr == next_item_size {
            score -= 2.5 * (1.0 - remaining as f64 / 50.0);
        }
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        if next_item_size > 0 && pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.0;
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 3 && fitting_bins_count <= 3 && remaining > 40 {
            score -= 1.8;
        }
        // Endgame exact-closure widening.
        if remaining < 45 && next_item_size > 0 && pr > 0 && pr > next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 * (1.0 - remaining as f64 / 45.0) * (1.0 - (pr - next_item_size) as f64 / 2.0);
        }
        // Endgame multi-slot closure.
        if remaining < 60 && next_item_size > 1 && pr > 0 && pr % next_item_size == 0 && pr / next_item_size >= 2 {
            score -= 2.0 * (1.0 - remaining as f64 / 60.0) * ((pr / next_item_size) as f64).min(3.0) * 0.5;
        }
        // mean-band two-slot closure.
        if next_item_size > 1 && pr > 0 && pr > next_item_size {
            let rem_after = pr - next_item_size;
            if rem_after > 0 && mean_residual > 2.0 && (rem_after as f64 - mean_residual).abs() <= mean_residual * 0.2 && remaining > 30 {
                score -= 1.2 * (1.0 - (rem_after as f64 - mean_residual).abs() / (mean_residual * 0.2 + 1.0)) * (0.4 + 0.6 * progress);
            }
        }
        // sole-fitter closure bonus — only bin that fits and still covers next_item.
        if fitting_bins_count == 1 && next_item_size > 0 && pr >= next_item_size && remaining > 30 {
            score -= 1.4 * (0.5 + 0.5 * progress);
        }
        // MUTATION v178: sub-mean*0.3 dead-space tail relief in non-fresh bins — very small nonzero leftovers are nearly closed bins; reward near-closure continuously down to zero instead of a single pr<=2 cliff.
        if pr > 0 && mean_residual > 4.0 && (pr as f64) <= mean_residual * 0.3 && remaining > 30 {
            score -= (mean_residual * 0.3 - pr as f64) * 0.20 * (0.6 + 0.4 * progress);
        }
        // MUTATION v178: non-fresh divisibility closure — exact multiples of next_item in open bins are reliable chained fits.
        if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 && pr / next_item_size >= 2 && remaining > 30 {
            let k = (pr / next_item_size) as f64;
            score -= 0.9 + 0.25 * (k - 2.0).min(4.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;
    let remaining = total_items.saturating_sub(step_index);
    let progress = step_index as f64 / total_items.max(1) as f64;
    let frag = pr as f64 - item_size as f64;

    if pr > 0 && pr < 10 {
        score += 55.0;
    } else if pr < 25 {
        score += 22.0 * (1.0 - pr as f64 / 25.0);
    }

    if pr == 0 {
        score -= 100.0;
    } else if pr <= 5 {
        score -= 42.0;
    } else if pr <= 8 {
        score -= 16.0;
    } else if pr <= 12 {
        score -= 10.0;
    } else if pr <= 15 {
        score -= 4.0;
    } else if pr <= 25 {
        score -= 1.0;
    } else if pr <= 40 {
        score += 4.0;
    } else if pr <= 60 {
        score += 8.0;
    } else {
        score += 12.0;
    }

    if pr > 0 && pr <= 2 && remaining > 30 {
        score -= 3.0 * (1.0 - progress * 0.5);
    }

    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size > pr {
            let dead = (next_item_size - pr) as f64;
            let density = remaining as f64 / total_items.max(1) as f64;
            let scarcity = if fitting_bins_count <= 2 { 1.25 } else { 1.0 };
            score += pr as f64 * 0.5 + dead * (0.25 + 0.55 * density) * scarcity;
        } else {
            let slack = (pr - next_item_size) as f64;
            score -= 7.0 + 10.0 / (1.0 + slack);
            if slack == 0.0 {
                score -= 5.0;
            }
            if slack >= 1.0 && slack <= 12.0 {
                score -= 3.0 * (1.0 - slack / 12.0);
            }
            if slack > 45.0 {
                score += (slack - 45.0) * 0.05;
            }
        }
        let triple = item_size + next_item_size * 2;
        if pr >= triple && pr - triple <= 10 {
            score -= 2.5 * (1.0 - (pr - triple) as f64 / 10.0);
        }
        let quad = item_size + next_item_size * 3;
        if pr >= quad && pr - quad <= 6 {
            score -= 1.8 * (1.0 - (pr - quad) as f64 / 6.0);
        }
        if item_size + next_item_size == pr {
            score -= 6.0;
        }
        if pr > 0 && pr >= next_item_size && pr % next_item_size == 0 && pr / next_item_size >= 2 && remaining > 50 {
            score -= 2.0 * ((pr / next_item_size) as f64).min(3.0);
        }
        if pr >= next_item_size && pr - next_item_size <= 1 {
            score -= 3.0;
        }
        if frag > 0.0 && frag < next_item_size as f64 && next_item_size as f64 - frag <= 4.0 {
            score += (next_item_size as f64 - frag) * 0.9;
        }
        if frag >= next_item_size as f64 && frag - next_item_size as f64 <= 3.0 {
            score -= 1.0 * (1.0 - (frag - next_item_size as f64) / 3.0);
        }
        if next_item_size > 1 && pr > 0 && pr >= next_item_size && pr / next_item_size >= 2 && pr % next_item_size <= 2 && remaining > 30 {
            score -= 1.6 * ((pr / next_item_size) as f64).min(4.0);
        }
        if next_item_size > 1 && pr > 0 && pr >= next_item_size {
            let rem_after = pr - next_item_size;
            if rem_after > 0 && rem_after % next_item_size == 0 && rem_after / next_item_size >= 2 && fitting_bins_count <= 3 && remaining > 60 {
                score -= 1.4 * ((rem_after / next_item_size) as f64).min(4.0);
            }
        }
        if pr > 0 && pr < next_item_size && next_item_size - pr <= 6 && remaining > 30 && fitting_bins_count > 2 {
            score += (next_item_size - pr) as f64 * 0.45 * (1.0 - (next_item_size - pr) as f64 / 6.0);
        }
        if pr > 0 && pr < next_item_size && next_item_size - pr > next_item_size / 2 && fitting_bins_count > 3 && remaining > 50 {
            score += (next_item_size - pr) as f64 * 0.30;
        }
        if next_item_size > 1 && pr >= item_size + next_item_size {
            let rest = pr - item_size - next_item_size;
            if rest >= next_item_size && rest - next_item_size <= 4 && remaining > 25 {
                score -= 2.2 * (1.0 - (rest - next_item_size) as f64 / 4.0);
            }
        }
        if pr > 0 && pr >= next_item_size {
            let rem_after = pr - next_item_size;
            if rem_after > 0 && (rem_after as f64 - mean_residual).abs() <= 2.0 && remaining > 20 {
                score -= 1.8 * (1.0 - (rem_after as f64 - mean_residual).abs() / 2.0);
            }
        }
        if pr > 0 && mean_residual > 3.0 && (pr as f64) < mean_residual * 0.80 && remaining > 60 {
            score += (mean_residual * 0.80 - pr as f64) * (0.18 + 0.14 * progress);
        }
        if pr > next_item_size && (pr - next_item_size) > 0 && (pr - next_item_size) < 14 && fitting_bins_count > 1 {
            let dead2 = (pr - next_item_size) as f64;
            score += dead2 * 0.10 * (1.0 - dead2 / 14.0);
        }
        if pr > next_item_size && (pr - next_item_size) * 2 <= pr {
            score -= 1.2;
        }
        if pr >= next_item_size {
            let gap = pr - next_item_size;
            if gap > 25 && gap < 45 {
                score += (gap as f64 - 25.0) * 0.08;
            }
        }
        if pr == next_item_size && fitting_bins_count <= 2 {
            score -= 4.0;
        }
        if frag > 0.0 && frag < next_item_size as f64 {
            let dead = next_item_size as f64 - frag;
            if dead > 6.0 && fitting_bins_count > 1 {
                score += dead * 0.12;
            }
        }
        if pr > 0 && pr < next_item_size && next_item_size - pr <= 3 && remaining > 80 {
            score += (next_item_size - pr) as f64 * 0.6;
        }
        if pr > 0 && pr < next_item_size && mean_residual > 2.0 && (next_item_size as f64 - pr as f64) <= mean_residual * 0.7 && remaining > 50 {
            score += (next_item_size as f64 - pr as f64) * (0.35 + 0.25 * progress);
        }
        if next_item_size > 1 && pr >= next_item_size * 2 {
            let rem_after = pr - next_item_size;
            if rem_after >= next_item_size && (rem_after - next_item_size) as f64 <= mean_residual * 0.5 && remaining > 40 {
                score -= 1.1 * (1.0 - (rem_after - next_item_size) as f64 / (mean_residual * 0.5 + 1.0)) * (0.6 + 0.6 * progress);
            }
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.4 * (1.0 - remaining as f64 / total_items.max(1) as f64);
        }
        if pr > next_item_size {
            let slack = pr - next_item_size;
            if slack >= 3 && slack <= 10 && remaining > 25 {
                score += slack as f64 * 0.10 * (1.0 - slack as f64 / 10.0);
            }
        }
        if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 && pr / next_item_size >= 2 {
            let slots = (pr / next_item_size) as f64;
            let density = remaining as f64 / total_items.max(1) as f64;
            score -= 0.8 * slots.min(4.0) * (0.5 + 0.5 * density);
        }
        if pr > 0 && mean_residual > 4.0 && pr > next_item_size {
            let rem_after = pr - next_item_size;
            let d = ((rem_after as f64 - mean_residual) / mean_residual).abs();
            if d < 0.15 && remaining > 40 {
                score -= 1.6 * (1.0 - d / 0.15);
            }
        }
        if pr > 0 && pr < next_item_size && fitting_bins_count >= 4 && remaining > 60 {
            score += (next_item_size - pr) as f64 * 0.22;
        }
        if pr > 0 && mean_residual > 4.0 && (pr as f64) < mean_residual * 0.5 && remaining > 80 {
            score += (mean_residual * 0.5 - pr as f64) * 0.22 * (1.0 - progress * 0.4);
        }
        if pr > 0 && mean_residual > 4.0 && (pr as f64) >= mean_residual * 0.5 && (pr as f64) < mean_residual * 0.75 && remaining > 60 {
            score += (mean_residual * 0.75 - pr as f64) * 0.09 * (1.0 - progress * 0.3);
        }
        if next_item_size > 1 && pr > 0 && pr >= next_item_size * 2 && remaining > 25 {
            let rem = pr % next_item_size;
            if rem > 0 && rem <= 2 {
                score -= (1.4 - 0.45 * rem as f64) * (0.4 + 0.5 * (1.0 - progress));
            }
        }
        if next_item_size > 1 && pr > 0 && pr >= next_item_size && remaining > 40 {
            let surplus = pr - next_item_size;
            if (surplus as f64) > 0.0 && (surplus as f64) < mean_residual * 0.8 {
                score -= (mean_residual * 0.8 - surplus as f64) * 0.12 * (0.5 + 0.5 * progress);
            }
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 4 && remaining > 60 {
            score -= 1.6 + 1.0 * (1.0 - remaining as f64 / total_items.max(1) as f64);
        }
        if next_item_size > 1 && pr > 0 && pr >= next_item_size {
            let rem_after = pr - next_item_size;
            if rem_after >= next_item_size && (rem_after as f64) <= mean_residual * 1.3 && (rem_after as f64) >= mean_residual * 0.7 && remaining > 35 {
                score -= 1.3 * (1.0 - ((rem_after as f64 - mean_residual).abs() / (mean_residual * 0.3 + 1.0)).min(1.0)) * (0.5 + 0.7 * progress);
            }
        }
        if pr > 0 && pr < next_item_size && next_item_size - pr <= 4 && mean_residual < 8.0 && fitting_bins_count > 2 && remaining > 25 {
            score += (next_item_size - pr) as f64 * 0.28;
        }
        if pr > 0 && next_item_size > 1 && mean_residual > 3.0 && (pr as f64) > mean_residual * 0.6 && (pr as u32) < next_item_size && remaining > 45 {
            let depth = next_item_size as f64 - pr as f64;
            score += depth * (0.16 + 0.10 * progress) * (1.0 - ((pr as f64 - mean_residual * 0.6) / (next_item_size as f64 - mean_residual * 0.6 + 1.0)).min(1.0));
        }
        if next_item_size > 1 && pr > 0 && pr >= next_item_size && mean_residual > 3.0 && remaining > 40 {
            let rem_after = (pr - next_item_size) as f64;
            if rem_after > mean_residual && rem_after - mean_residual <= 3.0 {
                score -= (3.0 - (rem_after - mean_residual)) * 0.35 * (0.6 + 0.4 * progress);
            }
        }
        if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 && pr / next_item_size >= 2 {
            let k = (pr / next_item_size) as f64;
            score -= (1.0 + 0.4 * (k - 2.0).min(3.0)) * (0.4 + 0.6 * (1.0 - progress));
        }
        // MUTATION v178: combined fine-grained residual fit + lookahead anticipation — reward bins whose post-residual after placing the item equals the mean residual exactly (tightest predictable reuse), weighted by stream density.
        if next_item_size > 1 && pr > 0 && pr >= next_item_size && mean_residual > 2.0 && remaining > 25 {
            let rem_after = (pr - next_item_size) as f64;
            let d = (rem_after - mean_residual).abs();
            if d < 1.5 {
                score -= (1.5 - d) * (0.5 + 0.5 * (remaining as f64 / total_items.max(1) as f64)) * 0.9;
            }
        }
        // MUTATION v178: scarcity-weighted sole-fitter reinforcement — when only one open bin fits and its leftover after the item still chains, lock it in harder late-stream.
        if fitting_bins_count == 1 && next_item_size > 0 && pr >= next_item_size && remaining > 25 {
            score -= 1.0 * (0.5 + 0.7 * progress);
        }
        // MUTATION v179: reuse-window ladder — post-fit leftovers slightly above mean_residual within a sliding window are the most reusable; reward continuously across the mean..mean*1.4 band so ranking near the band edge is smooth rather than cliffed.
        if next_item_size > 1 && pr > 0 && pr > next_item_size && mean_residual > 3.0 && remaining > 40 {
            let rem_after = (pr - next_item_size) as f64;
            if rem_after > mean_residual && rem_after < mean_residual * 1.4 {
                score -= (mean_residual * 1.4 - rem_after) * 0.10 * (0.5 + 0.5 * progress);
            }
        }
        // MUTATION v179: scarcity-graded dead-space suppression — soften the sub-mean leftover penalty when few fitting bins remain, so slightly sub-mean leftovers are still kept rather than fragmenting.
        if pr > 0 && mean_residual > 4.0 && (pr as f64) < mean_residual * 0.75 && remaining > 60 {
            let scarcity = 1.0 / (1.0 + (fitting_bins_count as f64).max(1.0) * 0.30);
            score += (mean_residual * 0.75 - pr as f64).max(0.0) * 0.06 * scarcity * (1.0 - progress * 0.3);
        }
        // MUTATION v179: crowding-coupled wedge relief — with many open fitting bins, stranded wedges are truly dead; penalize harder. With scarce bins, relax.
        if pr > 0 && next_item_size > 1 && mean_residual > 3.0 && (pr as u32) < next_item_size && (pr as f64) > mean_residual * 0.6 && remaining > 45 && open_bins_count > 3 && fitting_bins_count > 2 {
            score += (next_item_size - pr) as f64 * 0.08 * (1.0 - progress);
        }
        // MUTATION v180: near-closure ladder extension — extend the tiny-residual reward smoothly through the 3..8 band, progress-weighted, so bins closing to near-zero beat bins leaving mid-range wedges even when the exact pr<=2 cliff misses them.
        if pr > 2 && pr <= 8 && remaining > 30 {
            score -= (9.0 - pr as f64) * 0.30 * (0.5 + 0.5 * progress);
        }
        // MUTATION v180: dead-space wedge tail — extend the open-bin wedge penalty smoothly into the sub-mean*0.6 band with a slope proportional to how far below the typical residual the leftover sits, scarcity-relaxed.
        if pr > 0 && next_item_size > 1 && mean_residual > 4.0 && (pr as f64) <= mean_residual * 0.6 && (pr as f64) > mean_residual * 0.3 && remaining > 50 && fitting_bins_count > 1 {
            let relief = 1.0 / (1.0 + (fitting_bins_count as f64 - 1.0) * 0.25);
            score += (mean_residual * 0.6 - pr as f64) * (0.14 - 0.10 * relief) * (1.0 - progress * 0.35);
        }
    }

    score += open_bins_count as f64 * 0.3;

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    score -= (bin_residual as f64 - mean_residual) * 0.2;

    if frag > mean_residual && frag > 12.0 && remaining > 30 {
        score += (frag - mean_residual) * 0.06;
    }
    if frag > 40.0 && remaining > 60 {
        score += (frag - 40.0) * 0.05;
    }
    if next_item_size > 0 && frag > next_item_size as f64 && frag < next_item_size as f64 * 2.0 && frag > 8.0 {
        score += (frag - next_item_size as f64) * 0.10;
