        score += if mean_residual < 6.0 { 3.0 } else if mean_residual < 14.0 { 0.0 } else { -(mean_residual - 14.0).min(12.0) * 0.25 };
        if item_ratio > 0.7 && open_bins_count > 3 && remaining > 40 && mean_residual < item_size as f64 {
