        if fresh_left > 0.0 && next_item_size > 1 && mean_residual > 3.0 && fresh_left < next_item_size as f64 && fresh_left > mean_residual * 0.6 && fitting_bins_count >= 1 && remaining > 60 {
            score += (next_item_size as f64 - fresh_left) * 0.22;
        }
        if next_item_size > 1 && fresh_left > 0.0 && fresh_left >= (next_item_size * 2) as f64 && remaining > 70 {
            let rem = (fresh_left as u32) % next_item_size;
            if rem > 0 && rem <= 2 {
                score -= 0.7 - 0.2 * rem as f64;
            }
        }
        if next_item_size > 1 && fresh_left > 0.0 && fresh_left % next_item_size as f64 == 0.0 && (fresh_left / next_item_size as f64) >= 2.0 && remaining > 70 {
            score -= 0.8 + 0.3 * ((fresh_left / next_item_size as f64) - 2.0).min(3.0);
        }
        // MUTATION v178: fresh-bin mean-tightness coupling — when the fresh bin's leftover after placing the item matches the stream's typical residual exactly, the opening is predictable; reward it when alternatives are plentiful.
        if fresh_left > 0.0 && mean_residual > 3.0 && (fresh_left - mean_residual).abs() < 1.5 && fitting_bins_count >= 2 && remaining > 50 {
            score -= 1.2 * (1.0 - (fresh_left - mean_residual).abs() / 1.5) * (0.5 + 0.5 * progress);
        }
        // MUTATION v179: fresh-bin scarcity-graded guard — dead-space guard on fresh openings should bite harder when many open bins can already host the item; relax when the item barely fits anywhere.
        if fresh_left > 0.0 && mean_residual > 5.0 && fresh_left < mean_residual * 0.55 && fitting_bins_count >= 2 && remaining > 70 {
            let scarcity = 1.0 / (1.0 + (fitting_bins_count as f64).max(1.0) * 0.25);
            score += (mean_residual * 0.55 - fresh_left) * 0.30 * scarcity;
        }
        // MUTATION v179: fresh-bin crowding-coupled large-item relief — when the stream is crowded and the item is large, opening a fresh bin is usually cheaper than fragmenting an open bin.
        if item_ratio > 0.7 && open_bins_count > 3 && remaining > 40 && mean_residual < item_size as f64 {
            score -= 1.6 * (item_ratio - 0.7) * 3.0;
        }
        // MUTATION v180: fresh-bin scarcity relief — when the fresh bin is the ONLY viable host for a large item and the stream is deep, the fixed opening penalty over-fragments; release pressure proportional to item size and remaining stream so big items get clean bins instead of shattering a tight residual.
        if fitting_bins_count == 0 && item_ratio > 0.55 && remaining > 50 {
            score -= (item_ratio - 0.55) * 10.0 * (1.0 - progress * 0.4);
        }
        // MUTATION v180: tail-stream fresh-bin throttle — near the end of the stream, a fresh bin's leftover will almost never be reused, so its opening should be judged only on closing this item; suppress reuse-oriented fresh-bin rewards by lifting the base penalty.
        if remaining < 20 && fresh_left > 0.0 && fitting_bins_count > 0 {
            score += (20.0 - remaining as f64) * 0.30;
        }
        // MUTATION v180: fresh-bin tail-closure preference — near the stream end, a fresh bin whose leftover is an exact multiple of next_item can still absorb late repeats; reward exact multi-slot openings when remaining is small but nonzero.
        if next_item_size > 1 && fresh_left > 0.0 && (fresh_left as u32) % next_item_size == 0 && fresh_left / next_item_size as f64 >= 2.0 && remaining >= 8 && remaining <= 30 {
            score -= 1.0 * (1.0 - (remaining as f64 - 8.0) / 22.0);
