    if pr > 0 && pr <= 2 && remaining > 30 {
        score -= 3.0 * (1.0 - progress * 0.5);
    }

    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size > pr {
            let dead = (next_item_size - pr) as f64;
            let density = remaining as f64 / total_items.max(1) as f64;
