            score -= 0.8 + 0.3 * ((fresh_left / next_item_size as f64) - 2.0).min(3.0);
        }
        if fresh_left > 0.0 && mean_residual > 3.0 && (fresh_left - mean_residual).abs() < 1.5 && fitting_bins_count >= 2 && remaining > 50 {
            score -= 1.2 * (1.0 - (fresh_left - mean_residual).abs() / 1.5) * (0.5 + 0.5 * progress);
        }
        if fresh_left > 0.0 && mean_residual > 5.0 && fresh_left < mean_residual * 0.55 && fitting_bins_count >= 2 && remaining > 70 {
            let scarcity = 1.0 / (1.0 + (fitting_bins_count as f64).max(1.0) * 0.25);
            score += (mean_residual * 0.55 - fresh_left) * 0.30 * scarcity;
        }
        // MUTATION v180: scarcity relief for fresh bins — when the fresh bin is the ONLY viable host for a large item and the stream is deep, release opening pressure proportional to item size so big items get clean bins instead of shattering a tight residual.
        if fitting_bins_count == 0 && item_ratio > 0.55 && remaining > 50 {
            score -= (item_ratio - 0.55) * 10.0 * (1.0 - progress * 0.4);
        }
        // MUTATION v180: tail-stream fresh-bin throttle — near the stream end, a fresh bin's leftover will almost never be reused; judge the opening only on closing this item.
        if remaining < 20 && fresh_left > 0.0 && fitting_bins_count > 0 {
            score += (20.0 - remaining as f64) * 0.30;
        }
        // MUTATION v180: fresh-bin tail-closure preference — near the stream end, a fresh bin whose leftover is an exact multi-slot multiple of next_item can still absorb late repeats; reward it when remaining is small but nonzero.
        if next_item_size > 1 && fresh_left > 0.0 && (fresh_left as u32) % next_item_size == 0 && fresh_left / next_item_size as f64 >= 2.0 && remaining >= 8 && remaining <= 30 {
            score -= 1.0 * (1.0 - (remaining as f64 - 8.0) / 22.0);
        }
    } else {
        score += 60.0;
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 + 2.0 * progress;
        }
        if remaining < 30 && pr > 0 && pr <= 12 {
            score -= (13.0 - pr as f64) * 0.4;
        }
        if remaining < 35 && next_item_size > 0 && pr == next_item_size {
            score -= 3.0;
        }
        if next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 6 && fitting_bins_count > 2 {
            score -= 1.5;
        }
        if remaining < 30 && next_item_size > 0 && pr > 0 && pr >= next_item_size && pr - next_item_size <= 3 {
            score -= 2.0 * (1.0 - remaining as f64 / 30.0) * (1.0 - (pr - next_item_size) as f64 / 3.0);
        }
        if next_item_size > 0 && pr > 0 && pr < next_item_size && fitting_bins_count <= 2 && remaining > 40 {
            score += (next_item_size - pr) as f64 * 0.20;
        }
        if remaining >= 35 && remaining < 120 && next_item_size > 0 && pr >= next_item_size && pr - next_item_size <= 5 {
            score -= 1.0;
        }
        if remaining < 20 && pr > 0 && mean_residual > 1.0 && ((pr as f64) - mean_residual).abs() < 3.0 {
            score -= 1.5;
        }
        if fitting_bins_count > 4 && pr > 0 && pr > next_item_size && (pr - next_item_size) as f64 > mean_residual {
            score += 0.8;
        }
        if remaining < 50 && next_item_size > 0 && pr > 0 && pr == next_item_size {
            score -= 2.5 * (1.0 - remaining as f64 / 50.0);
        }
        if remaining < 50 && pr > 0 && pr == item_size {
            score -= 2.0 * (1.0 - remaining as f64 / 50.0);
        }
        if next_item_size > 0 && pr >= item_size + next_item_size && pr - (item_size + next_item_size) <= 2 {
            score -= 2.0 * (1.0 - (pr - item_size - next_item_size) as f64 / 2.0);
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 2 && remaining > 20 {
            score -= 2.0;
        }
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 3 && fitting_bins_count <= 3 && remaining > 40 {
            score -= 1.8;
        }
        if remaining < 45 && next_item_size > 0 && pr > 0 && pr > next_item_size && pr - next_item_size <= 2 {
            score -= 2.0 * (1.0 - remaining as f64 / 45.0) * (1.0 - (pr - next_item_size) as f64 / 2.0);
        }
        if remaining < 60 && next_item_size > 1 && pr > 0 && pr % next_item_size == 0 && pr / next_item_size >= 2 {
            score -= 2.0 * (1.0 - remaining as f64 / 60.0) * ((pr / next_item_size) as f64).min(3.0) * 0.5;
        }
        if next_item_size > 1 && pr > 0 && pr > next_item_size {
            let rem_after = pr - next_item_size;
            if rem_after > 0 && mean_residual > 2.0 && (rem_after as f64 - mean_residual).abs() <= mean_residual * 0.2 && remaining > 30 {
                score -= 1.2 * (1.0 - (rem_after as f64 - mean_residual).abs() / (mean_residual * 0.2 + 1.0)) * (0.4 + 0.6 * progress);
            }
        }
        if fitting_bins_count == 1 && next_item_size > 0 && pr >= next_item_size && remaining > 30 {
            score -= 1.4 * (0.5 + 0.5 * progress);
        }
        if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 && pr / next_item_size >= 2 && remaining > 30 {
            let k = (pr / next_item_size) as f64;
            score -= 0.9 + 0.25 * (k - 2.0).min(4.0);
        }
        if next_item_size > 1 && pr > 0 && pr >= next_item_size * 2 && remaining > 30 {
            let rem = pr % next_item_size;
            if rem > 0 && rem <= 2 {
                score -= 0.6 - 0.2 * rem as f64;
            }
        }
        if remaining < 40 && pr > 0 && mean_residual > 2.0 && pr > next_item_size {
            let rem_after = (pr - next_item_size) as f64;
            let d = (rem_after - mean_residual).abs();
            if d < 2.0 {
                score -= (2.0 - d) * 0.5 * (1.0 - remaining as f64 / 40.0);
            }
        }
        if fitting_bins_count == 1 && pr > 0 && next_item_size > 1 && (pr as u32) < next_item_size && remaining > 30 {
            score -= (next_item_size - pr) as f64 * 0.35 * (0.5 + 0.5 * progress);
        }
        // MUTATION v180: sub-mean*0.3 dead-space tail relief in non-fresh bins — a very small but nonzero leftover is nearly a closed bin; reward near-closure continuously down to zero instead of a single pr<=2 cliff.
        if pr > 0 && mean_residual > 4.0 && (pr as f64) <= mean_residual * 0.3 && remaining > 30 {
            score -= (mean_residual * 0.3 - pr as f64) * 0.20 * (0.6 + 0.4 * progress);
        }
        // MUTATION v180: non-fresh near-closure ladder — extend the tiny-residual reward smoothly through the 3..8 band, progress-weighted, so bins closing to near-zero beat bins leaving mid-range wedges.
        if pr > 2 && pr <= 8 && remaining > 30 {
            score -= (9.0 - pr as f64) * 0.30 * (0.5 + 0.5 * progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
