        }
        if next_item_size > 1 && pr > 0 && pr >= next_item_size && mean_residual > 2.0 && remaining > 25 {
            let rem_after = (pr - next_item_size) as f64;
            let d = (rem_after - mean_residual).abs();
            if d < 1.5 {
                score -= (1.5 - d) * (0.5 + 0.5 * (remaining as f64 / total_items.max(1) as f64)) * 0.9;
