        // MUTATION v181: near-closure ladder — extend the tiny-residual reward smoothly through the 3..8 band, progress-weighted, so bins closing to near-zero beat bins leaving mid-range wedges even when the pr<=2 cliff misses them.
        if pr > 2 && pr <= 8 && remaining > 30 {
            score -= (9.0 - pr as f64) * 0.30 * (0.5 + 0.5 * progress);
        }
        // MUTATION v181: exact-slot lookahead — a post-residual that holds an exact multiple of the NEXT item AND the item itself closed the gap tightly is a perfect chain; reward deeper multiples with a progress-weighted slope so late-stream chains count most.
        if next_item_size > 1 && pr > 0 && pr % next_item_size == 0 && item_size + next_item_size <= bin_residual {
            let k = (pr / next_item_size) as f64;
            score -= 0.9 * k.min(3.0) * (0.5 + 0.5 * progress);
