                score -= (1.4 - 0.45 * rem as f64) * (0.4 + 0.5 * (1.0 - progress));
            }
        }
        // reusable-residual alignment — surplus after next_item fits within mean band promises reuse.
        if next_item_size > 1 && pr > 0 && pr >= next_item_size && remaining > 40 {
            let surplus = pr - next_item_size;
            if (surplus as f64) > 0.0 && (surplus as f64) < mean_residual * 0.8 {
                score -= (mean_residual * 0.8 - surplus as f64) * 0.12 * (0.5 + 0.5 * progress);
            }
        }
        // exact quadruple-slot host — long-horizon multi-fit reward.
        if next_item_size > 1 && pr > 0 && pr == next_item_size * 4 && remaining > 60 {
            score -= 1.6 + 1.0 * (1.0 - remaining as f64 / total_items.max(1) as f64);
        }
        // combined fine-grained residual fit + lookahead anticipation.
        if next_item_size > 1 && pr > 0 && pr >= next_item_size {
            let rem_after = pr - next_item_size;
            if rem_after >= next_item_size && (rem_after as f64) <= mean_residual * 1.3 && (rem_after as f64) >= mean_residual * 0.7 && remaining > 35 {
                score -= 1.3 * (1.0 - ((rem_after as f64 - mean_residual).abs() / (mean_residual * 0.3 + 1.0)).min(1.0)) * (0.5 + 0.7 * progress);
            }
        }
        // near-miss escalation in tight clusters.
        if pr > 0 && pr < next_item_size && next_item_size - pr <= 4 && mean_residual < 8.0 && fitting_bins_count > 2 && remaining > 25 {
            score += (next_item_size - pr) as f64 * 0.28;
        }
        // v178: reuse-window ladder — post-fit leftovers slightly above mean_residual are the most reusable by the stream's typical item.
        if next_item_size > 1 && pr > 0 && pr > next_item_size && mean_residual > 3.0 && remaining > 40 {
            let rem_after = (pr - next_item_size) as f64;
            if rem_after > mean_residual && rem_after < mean_residual * 1.4 {
                score -= (mean_residual * 1.4 - rem_after) * 0.10 * (0.5 + 0.5 * progress);
            }
        }
        // v178: scarcity-graded dead-space suppression.
        if pr > 0 && mean_residual > 4.0 && (pr as f64) < mean_residual * 0.75 && remaining > 60 {
            let scarcity = 1.0 / (1.0 + (fitting_bins_count as f64).max(1.0) * 0.30);
            score += (mean_residual * 0.75 - pr as f64).max(0.0) * 0.06 * scarcity * (1.0 - progress * 0.3);
        }
        // v178: sole-fitter wedge relief.
        if fitting_bins_count == 1 && pr > 0 && next_item_size > 1 && (pr as u32) < next_item_size && remaining > 30 {
            score -= (next_item_size - pr) as f64 * 0.35 * (0.5 + 0.5 * progress);
        }
        // v179: dead-space wedge tail — extend the open-bin wedge penalty smoothly into the sub-mean*0.6 band.
        if pr > 0 && next_item_size > 1 && mean_residual > 4.0 && (pr as f64) <= mean_residual * 0.6 && (pr as f64) > mean_residual * 0.3 && remaining > 50 && fitting_bins_count > 1 {
            score += (mean_residual * 0.6 - pr as f64) * 0.14 * (1.0 - progress * 0.35);
        }
        // v179: scarcity-refined wedge tail — relax when fitting options are scarce, concentrate where alternatives abound.
        if pr > 0 && next_item_size > 1 && mean_residual > 4.0 && (pr as f64) <= mean_residual * 0.6 && (pr as f64) > mean_residual * 0.3 && remaining > 50 && fitting_bins_count > 1 {
            let relief = 1.0 / (1.0 + (fitting_bins_count as f64 - 1.0) * 0.25);
            score += (mean_residual * 0.6 - pr as f64) * 0.10 * relief * progress;
        }
        // v179: post-fit surplus just above mean residual — the tightest reusable window after a fit.
        if next_item_size > 1 && pr > 0 && pr >= next_item_size && mean_residual > 3.0 && remaining > 40 {
            let rem_after = (pr - next_item_size) as f64;
            if rem_after > mean_residual && rem_after - mean_residual <= 3.0 {
                score -= (3.0 - (rem_after - mean_residual)) * 0.35 * (0.6 + 0.4 * progress);
