        }
        if fresh_left > 0.0 && next_item_size > 1 && mean_residual > 3.0 && fresh_left < next_item_size as f64 && fresh_left > mean_residual * 0.6 && fitting_bins_count >= 1 && remaining > 60 {
            score += (next_item_size as f64 - fresh_left) * 0.22;
        }
        if next_item_size > 1 && fresh_left > 0.0 && fresh_left >= (next_item_size * 2) as f64 && remaining > 70 {
            let rem = (fresh_left as u32) % next_item_size;
            if rem > 0 && rem <= 2 {
