        }
        if fresh_left > 0.0 && mean_residual > 5.0 && fresh_left < mean_residual * 0.55 && fitting_bins_count >= 2 && remaining > 70 {
            let scarcity = 1.0 / (1.0 + (fitting_bins_count as f64).max(1.0) * 0.25);
            score += (mean_residual * 0.55 - fresh_left) * 0.30 * scarcity;
        }
        // MUTATION v180: scarcity relief for fresh bins — big items get clean bins when they fit nowhere else.
        if fitting_bins_count == 0 && item_ratio > 0.55 && remaining > 50 {
            score -= (item_ratio - 0.55) * 10.0 * (1.0 - progress * 0.4);
        }
        // MUTATION v180: tail-stream fresh-bin throttle — near the stream end, judge the opening only on closing this item.
        if remaining < 20 && fresh_left > 0.0 && fitting_bins_count > 0 {
            score += (20.0 - remaining as f64) * 0.30;
        }
        // MUTATION v180: fresh-bin tail-closure preference — exact multi-slot openings absorb late repeats.
        if next_item_size > 1 && fresh_left > 0.0 && (fresh_left as u32) % next_item_size == 0 && fresh_left / next_item_size as f64 >= 2.0 && remaining >= 8 && remaining <= 30 {
            score -= 1.0 * (1.0 - (remaining as f64 - 8.0) / 22.0);
        }
        // MUTATION v181: fresh-bin two-slot lookahead — leftover hosting next item plus a near-mean remainder is compaction-friendly.
        if next_item_size > 1 && fresh_left > next_item_size as f64 && mean_residual > 2.0 && remaining > 60 {
            let rem2 = fresh_left - next_item_size as f64;
            if rem2 > mean_residual * 0.5 && rem2 < mean_residual * 1.2 {
                score -= 1.0 * (1.0 - (rem2 - mean_residual * 0.5).abs() / (mean_residual * 0.7)) * (0.4 + 0.4 * progress);
            }
        }
        // MUTATION v183: fresh-bin scarcity relief extension — when the fresh bin is the ONLY host and the item is very large, release even more pressure late in the stream so the final big items don't shatter tight residuals.
        if fitting_bins_count == 0 && item_ratio > 0.7 && remaining > 25 && remaining <= 50 {
            score -= (item_ratio - 0.7) * 14.0 * (1.0 - progress * 0.5);
        }
        // MUTATION v184 (new): fresh-bin mean-tight guard — when the residual pool is very tight (small mean_residual) and the fresh-bin leftover is far above the pool's typical leftover, opening wastes reusable space; penalize proportionally when alternatives exist.
        if fresh_left > 0.0 && mean_residual > 1.0 && mean_residual < 7.0 && fresh_left > mean_residual * 1.6 && fitting_bins_count >= 2 && remaining > 45 {
            score += (fresh_left - mean_residual * 1.6) * 0.10 * (0.5 + 0.5 * progress);
