    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;

    // base: prefer small post-residual, with non-linear (quadratic) shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // smooth coupling of post-residual with stream progress:
    // later in the stream, dead space matters more (convex penalty)
    score += 30.0 * norm_pr * norm_pr * (progress * progress);

    // reward tight fits, smoothly scaled by progress
    score -= 15.0 * fit * fit * (1.0 - fit) * (1.0 + progress);

    // lookahead: reward bins whose post-residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64 / cap;
        score -= 12.0 * (1.0 - slack) * (1.0 + progress);
    } else if next_item_size > 0 {
        // penalize when next item cannot follow, more so later in stream
        score += 8.0 * (1.0 - progress);
    }

    // last-chance bin: strong smooth reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - norm_pr) * (1.0 + progress);
    }

    // many open bins: gently discourage spreading, scaled by mean residual
    score += 0.5 * open_bins_count as f64 * (mean_residual / cap) * (0.5 + 0.5 * progress);

    // new-bin candidate: make it attractive only when this bin would be a bad fit
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new_bin {
        // smooth penalty unless post-residual would be small
        score += 25.0 * (norm_pr * norm_pr) * (1.0 + 2.0 * progress);
    }

    score
}

