    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Best-fit emphasis: tighter fits strongly preferred.
    score *= 1.0 + (item_size as f64 / cap) * 0.5;

    // Dead-space penalty grows for awkward post-residuals (harmonic classes).
    let pr = post_residual;
    if pr > 0 {
        // class of post_residual relative to capacity: exact quarters/eighths are reusable
        let reusable = (cap / pr as f64).fract() < 1e-9
            || (cap / 2.0 / pr as f64).fract() < 1e-9;
        if !reusable {
            score += (pr as f64) * 0.35;
        }
        // small unusable slivers
        if pr < 10 {
            score += 25.0;
        }
    } else {
        score -= 40.0; // perfect closure
    }

    // Lookahead: reward if next item fits exactly in post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size < pr {
            score -= 15.0 * (1.0 - (pr - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here; penalize more if this residual becomes dead
            if pr < next_item_size && pr < 10 {
                score += 20.0;
            }
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only fit.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer reusing open bins early; allow new bins late or when mean residual is tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 - 25.0 * progress;
        if mean_residual > item_size as f64 * 1.5 && open_bins_count > 0 {
            score += 30.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0;
        }
    }

    // Spread-out residuals: discourage creating bins far from mean residual (fragmentation control).
    score += 0.15 * ((post_residual as f64 - mean_residual).abs());

    score
}

