pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item (<= ~10)
    // are unusable; treat them as fully wasted.
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Penalize leaving a gap that is awkwardly large but not reusable by the
    // next item (lookahead-aware dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    }
    // Reward when post_residual exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few
    // open bins, encourage filling existing bins rather than opening new ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= 3.0 + pressure * 2.0;
    } else {
        // New-bin candidate: only attractive when existing residuals are poor
        // or no bin fits well.
        score += 10.0 + mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // penalize extreme outliers.
    score += ((bin_residual as f64) - mean_residual).abs() * 0.15;

    // Late in the stream, be greedier: tighter fits matter more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 2.0 + progress * 6.0 * (1.0 - (post_residual as f64) / bin_capacity as f64);

    score
