        }
        // MUTATION v183: non-fresh compaction closure
        if next_item_size > 1 && pr > 0 {
            let two = item_size as f64 + next_item_size as f64;
            if (bin_residual as f64) >= two {
                let rem2 = bin_residual as f64 - two;
                if rem2 > 4.0 && rem2 <= 10.0 && remaining > 40 && fitting_bins_count <= 3 {
                    score += rem2 * 0.22 * (0.5 + 0.5 * progress);
                }
            }
        }
        // MUTATION v184 (borrowed from best): exact-slot reinforcement in non-fresh bins.
        if next_item_size > 1 && pr > 0 && pr == next_item_size && remaining > 12 {
            score -= 1.8 * (0.5 + 0.5 * progress);
        }
        // MUTATION v184 (borrowed from best): triple-slot near-exact chain in non-fresh bins.
        if next_item_size > 1 && pr > 0 && pr >= next_item_size * 3 && remaining > 35 {
            let rem3 = pr % next_item_size;
            if rem3 <= 1 {
                score -= (1.0 + 0.35 * (pr / next_item_size).min(6) as f64) * (0.4 + 0.6 * progress);
            }
        }
        // MUTATION v184: post-next near-zero remainder guard in non-fresh bins.
        if next_item_size > 1 && pr > 0 && pr > next_item_size {
            let rem_after = pr - next_item_size;
            if rem_after > 0 && rem_after < 4 && fitting_bins_count > 1 && remaining > 20 {
                score += (4.0 - rem_after as f64) * 0.9 * (0.5 + 0.5 * progress);
            }
        }
    }

    if frag > 0.0 && frag < 6.0 && next_item_size > 0 && (next_item_size as f64) > frag && remaining > 40 && fitting_bins_count > 1 {
        score += (next_item_size as f64 - frag) * 0.20 * (0.6 + 0.4 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
