        }
        if next_item_size > 1 && pr > 0 {
            let two = item_size as f64 + next_item_size as f64;
            if (bin_residual as f64) >= two {
                let rem2 = bin_residual as f64 - two;
                if rem2 <= 3.0 && remaining > 25 {
