pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.10;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual already does this).

    // Aggressive 2-step lookahead: reward when the leftover space matches the next item.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if nxt <= post {
            // Next item can be placed here afterwards: strong reward proportional to match quality.
            let gap = (post - nxt) as f64;
            score -= 18.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's leftover: penalize proportional to overshoot.
            let over = nxt - post;
            score += 0.6 * over as f64;
        }
    }

    // Compare post_residual against mean residual: avoid creating outliers of dead space.
    let post = post_residual as f64;
    if post > mean_residual {
        score += 0.35 * (post - mean_residual);
    } else {
        score -= 0.20 * (mean_residual - post);
    }

    // Last chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize wasting a nearly-full bin's residual on a poor fit (dead space).
    let waste_ratio = post / bin_capacity as f64;
    if waste_ratio > 0.0 && waste_ratio < 0.10 {
        score += 12.0 * (1.0 - waste_ratio / 0.10);
    }

    // Early in the stream, be slightly more willing to open/use fresh bins flexibly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 3.0 * (1.0 - progress);

    // Slight penalty when many bins are open already: encourage consolidation.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = 1.0 - (post_residual as f64 / cap);
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect lookahead match: residual left equals next item exactly -> big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize residual that is slightly larger than next item (dead space for lookahead).
    if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size + 10 {
        score += 8.0;
    }
    // Penalize residuals too small for the minimum item size (unusable dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Fragmentation pressure: when many bins are open with scattered residuals,
    // prefer consolidating into existing bins rather than opening new ones.
    if bin_residual < bin_capacity {
        let spread = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * spread;
        score -= 0.3 * open_bins_count as f64;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive early in
    // the stream or when the current item is large and would leave a very tight fit
    // elsewhere anyway. Penalize new bins as open bins accumulate.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 25.0 * (1.0 - progress) * 0.0 + 0.5 * open_bins_count as f64;
        // Allow a new bin if item is huge relative to capacity (poor fit anywhere).
        if item_size as f64 > 0.7 * cap {
            score -= 18.0;
        }
        // If nothing else fits well (mean residual very low), a new bin is fine.
        if mean_residual < item_size as f64 {
            score -= 15.0;
        }
    }

    // Mild time-horizon shaping: late in the stream, squeeze bins harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * fit_ratio;

    score
}

