                    score -= (4.0 - rem2) * 0.6 * (0.5 + 0.5 * progress);
                }
            }
        }
        // MUTATION: tiny dead remainder after next item with alternatives — waste signal.
        if next_item_size > 1 && pr > 0 && pr > next_item_size {
            let rem_after = pr - next_item_size;
            if rem_after > 0 && rem_after < 4 && fitting_bins_count > 1 && remaining > 20 {
                score += (4.0 - rem_after as f64) * 0.9 * (0.5 + 0.5 * progress);
            }
        }
        // MUTATION: combined fine-grained fit + lookahead — ideal host with scarce alternatives.
        if next_item_size > 0 && pr > 0 && pr >= next_item_size && fitting_bins_count <= 3 && remaining > 25 {
            let rem_after = pr - next_item_size;
            if rem_after as f64 <= mean_residual + 2.0 {
                score -= 1.4 * (1.0 - rem_after as f64 / (mean_residual + 3.0)) * (1.0 - progress * 0.4);
            }
        }
    }

    // MUTATION: small frag below next item with alternatives — waste signal.
    if frag > 0.0 && frag < 6.0 && next_item_size > 0 && (next_item_size as f64) > frag && remaining > 40 && fitting_bins_count > 1 {
        score += (next_item_size as f64 - frag) * 0.20 * (0.6 + 0.4 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit), with non-linear sharpening
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * norm_pr);

    // Smooth polynomial coupling of tightness with stream progress:
    // later in the stream, tight fits matter more (waste compounds)
    let tightness = 1.0 - norm_pr;
    score -= 0.8 * progress * tightness * tightness * tightness;

    // Penalize large post residual more aggressively as stream progresses
    score += 0.6 * progress * norm_pr * norm_pr * norm_pr;

    // Interaction with mean residual: if bin is far below mean residual,
    // it's a laggard bin — favor using it to consolidate
    let dev = (pr - mean_residual) / cap;
    score += 0.4 * dev * dev - 0.5 * dev * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    if fitting_bins_count == 1 {
        score -= 1.5 + 0.5 * progress;
    }

    // Lookahead: reward if next item fits into post residual (smooth kernel)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit_gap = (pr - ns) / cap;
        let k = (-12.0 * fit_gap * fit_gap).max(-60.0);
        score -= 0.9 * k.exp() * (1.0 - 0.3 * progress);
    }

    // Mild penalty for opening new bins when many bins already open
    if bin_residual == bin_capacity {
        score += 0.35 + 0.25 * (open_bins_count as f64).ln().max(0.0) + 0.3 * progress;
    }

    // Small preference for using fuller bins (smooth in residual)
    score += 0.15 * (bin_residual as f64 / cap) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by 10 are
    // "harmonious" (future items 10..80 in steps of 10 can re-fill them well).
    let class = post_residual % 10;
    score += (class as f64) * 1.5; // penalize off-class dead space

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small residual that is hard to reuse: penalize proportionally to waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: does the next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic chain: next item can follow into this bin.
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 + slack * 0.05;
            // Extra reward if next item exactly fills the bin afterwards.
            if next_item_size == post_residual {
                score -= 20.0;
            }
        } else {
            // Next item won't fit here; mildly penalize tight-ish leftovers
            // that are too small for typical items.
            if post_residual < 20 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and current open bins are crowded.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size >= 50 {
            score -= 20.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
        // If many open bins exist with slack, prefer them over a new bin.
        if mean_residual > item_size as f64 {
            score += 10.0;
        }
    }

    // Prefer tighter fits among equal residuals: reward small item/bins gap.
    let gap = (bin_residual - item_size) as f64;
    score += gap * 0.15;

    // Late in the stream, consolidate: discourage spreading across many bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64) * 0.3 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: when average residual is large, tighter fits matter.
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Reward very tight fits.
    if post_residual == 0 {
        score -= 45.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Lookahead: if next item fits perfectly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - gap / bin_capacity as f64);
    }

    // New-bin candidate: baseline competitive score, penalize opening bins early.
    if bin_residual == bin_capacity {
        score += 30.0 + 8.0 * open_bins_count as f64;
    }

    // Mild alignment with mean residual: prefer bins close to the mean (balanced packing).
    score += ((post_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
