pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Penalize residuals that fall into "dead" classes (small, hard-to-fill slivers)
    let class = post_residual % 10; // fine harmonic class
    score += (10 - class) as f64 * 0.35;

    // Coarse class: which quarter of capacity does the residual land in
    let quarter = post_residual / 25;
    match quarter {
        0 => score += 12.0,          // 0..24: nearly dead space
        1 => score += 4.0,           // 25..49: poor
        2 => score -= 2.0,           // 50..74: decent
        _ => score -= 6.0,           // 75..100: excellent
    }

    // Integer-division threshold: residual divisible by common item sizes is valuable
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 3.0; }
        if post_residual % 20 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 2.0; }
    }

    // Lookahead coupling: harmonic class of next item vs post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly-ish: reward tight modulo match
            let gap = post_residual - next_item_size;
            if gap % 10 == 0 { score -= 8.0; } else { score -= (gap as f64) * 0.05; }
        } else {
            // next item won't fit here; penalize more if residual is small
            score += ((next_item_size - post_residual) as f64) * 0.08;
        }
    }

    // Last-chance bonus: only fitting bin -> strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets moderate default score
    if bin_residual == bin_capacity {
        // prefer new bin only when existing residuals are all poor (mean residual low)
        let progress = step_index as f64 / total_items as f64;
        score = cap * 0.55 - mean_residual * 0.4 + progress * 5.0;
        if fitting_bins_count == 1 { score += 20.0; } // keep last-chance bin alive
    }

    // Mild pressure to consolidate when many bins are open
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.05;
    score
}
